#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_SPI_CS_GPIO 8
#define MCP3008_MOSI_GPIO 10
#define MCP3008_MISO_GPIO 9
#define MCP3008_SCLK_GPIO 11
#define MCP3008_CH0 0

static const int spi_pins[] = {MCP3008_SPI_CS_GPIO, MCP3008_MOSI_GPIO, MCP3008_MISO_GPIO, MCP3008_SCLK_GPIO};
static const int spi_mode = SPI_MODE_0;
static const int adc_channel = MCP3008_CH0;
static const int adc_bits = 10;

static gpio pigpio = 0;
static int spi_fd = -1;

void spi_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(spi_pins[MCP3008_SPI_CS_GPIO], PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CE0 as output.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(spi_pins[MCP3008_MOSI_GPIO], PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MOSI as output.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(spi_pins[MCP3008_MISO_GPIO], PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set MISO as input.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(spi_pins[MCP3008_SCLK_GPIO], PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCLK as output.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    spi_fd = gpioOpen(3, spi_mode);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void spi_cleanup() {
    gpioClose(spi_fd, 0);
    spi_fd = -1;
    gpioTerminate();
}

uint16_t read_adc(void) {
    uint8_t cmd[2] = {0x01, (adc_channel & 0x0F) | 0x80};
    uint8_t data[2];

    if (gpioSPITransmit(spi_fd, cmd, 2) < 0) {
        fprintf(stderr, "SPI transmission error.\n");
        return 0;
    }

    if (gpioSPIReceive(spi_fd, data, 2) < 0) {
        fprintf(stderr, "SPI reception error.\n");
        return 0;
    }

    return (data[1] << 8) | data[0];
}

int main(void) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    spi_init();

    while (1) {
        uint16_t adc_value = read_adc();
        time_t now = time(NULL);

        printf("Moisture level: %d (raw), %f (V), %d %s\n", adc_value, (double)adc_value / 1024.0 * 5.0, now, ctime(&now));

        sleep(1);
    }

    cleanup();
    return 0;
}

static void cleanup(int signum) {
    spi_cleanup();
    exit(signum == SIGINT || signum == SIGTERM ? 0 : 1);
}

