#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigio.h>
#include <unistd.h>
#include <stdint.h>

#define ADS1115_ADDR 0x48
#define MLX91219_AIN 0
#define PGA_4_096V 0b000
#define MUX_AIN0 0b100
#define DR_128SPS 0b00

#define SENSORS_SUPPLY 3.3
#define MLX91219_SENSITIVITY 40e-3

static int i2c_fd;
static gpio pigpio;

void sigint_handler(int signum) {
    gpioTerminate(pigpio);
    close(i2c_fd);
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "pigpioInitialise failed\n");
        return 1;
    }

    i2c_fd = i2cOpen(1, ADS1115_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "i2cOpen failed\n");
        pigpioTerminate();
        return 1;
    }

    if (i2cWriteI2CBlockData(i2c_fd, 0x20, (uint8_t[]){0x00, 0x00, 0x00, 0x00, 0x00}) < 0) {
        fprintf(stderr, "ADS1115 configuration write failed\n");
        close(i2c_fd);
        pigpioTerminate();
        return 1;
    }

    uint16_t adc_value;
    while (1) {
        if (i2cReadI2CBlockData(i2c_fd, 0x00, (uint8_t*)&adc_value, 2) < 0) {
            fprintf(stderr, "ADS1115 read failed\n");
            break;
        }

        double voltage = (double)adc_value * (SENSORS_SUPPLY / 65535);
        double current = voltage / MLX91219_SENSITIVITY;

        printf("Current: %.6f A\n", current);
        usleep(500000);
    }

    close(i2c_fd);
    pigpioTerminate();
    return 0;
}

