#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define FLAME_SENSOR_GPIO 4
#define MCP3008_CE0_GPIO 8
#define MCP3008_CHANNEL 0
#define ADC_BITS 10
#define TEMP_MIN 10
#define TEMP_MAX 40

static pigio *gpio;
static int spi_fd;
FILE *log_file = NULL;

void init_pigpio(void) {
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpio = pigpio_get();
}

void init_spi(void) {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_transfer transf;
    transf.bits_per_word = 8;
    transf.speed_hz = 1000000;
    transf.delay_usecs = 0;
    transf.bits_per_frame = transf.bits_per_word;
    transf.frame_format = SPI_FRAME_MSB_FIRST;
    transf.ignore_cs_change = 1;

    if (ioctl(spi_fd, SPI_IOC_WR_FRAMES, &transf) < 0) {
        perror("Failed to set SPI transfer parameters");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_gpio(void) {
    gpio_set_mode(FLAME_SENSOR_GPIO, PI_OUTPUT);
    gpio_set_function(FLAME_SENSOR_GPIO, PI_OUTPUT);
    gpio_set_pullup(FLAME_SENSOR_GPIO, 1);

    gpio_set_mode(MCP3008_CE0_GPIO, PI_OUTPUT);
    gpio_set_function(MCP3008_CE0_GPIO, PI_OUTPUT);
    gpio_write(MCP3008_CE0_GPIO, 0);
}

uint16_t read_analog(void) {
    gpio_set_function(FLAME_SENSOR_GPIO, PI_INPUT);
    gpio_set_pullup(FLAME_SENSOR_GPIO, 0);

    gpio_set(MCP3008_CE0_GPIO, 0);
    spi_transfer_byte(spi_fd, 0x01); // Start conversion

    uint8_t data[3];
    spi_transfer_byte(spi_fd, 0x00);
    spi_transfer_byte(spi_fd, 0x00);
    spi_transfer_byte(spi_fd, 0xFF); // Read 10-bit result

    data[0] = spi_transfer_byte(spi_fd, 0x00);
    data[1] = spi_transfer_byte(spi_fd, 0x00);
    data[2] = spi_transfer_byte(spi_fd, 0x00);

    gpio_set(MCP3008_CE0_GPIO, 1);

    uint16_t adc_value = (data[1] << 8) | data[0];
    return adc_value;
}

void cleanup(void) {
    gpio_stop();
    pigpio_terminate();
    close(spi_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    init_pigpio();
    init_spi();
    setup_gpio();

    log_file = fopen("flame_data.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,FlameDetected,Temperature\n");

    while (1) {
        uint16_t adc_value = read_analog();
        double temperature = (adc_value / (double)pow(2, ADC_BITS)) * (TEMP_MAX - TEMP_MIN) + TEMP_MIN;

        int flame_detected = gpio_read(FLAME_SENSOR_GPIO);

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

