        return 1;
    }

    if ((ret = ads1x15_open(I2C_ADDR)) < 0) {
        fprintf(stderr, "I2C open failed: %s\n", ads1x15_errorString(ret));
        pigpio_terminate();
        return 1;
    }

    if ((ret = ads1x15_config_single(I2C_ADDR, ADS1115_AIN0, ADS1115_GAIN_PLUS_4_096, ADS1115_RES_12_BIT, ADS1115_MODE_SINGLE)) < 0) {
        fprintf(stderr, "ADC configuration failed: %s\n", ads1x15_errorString(ret));
        ads1x15_close(I2C_ADDR);
        pigpio_terminate();
        return 1;
    }

    gpioSetMode(FLAME_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(FLAME_GPIO, PI_PUD_OFF);
    gpioWrite(FLAME_GPIO, 1);

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    pigpio_set_callback(FLAME_GPIO, PI_FALLING_EDGE, flame_isr);

    while (running) {
        if (last_flame_event && ads1x15_read_single(I2C_ADDR) > TEMP_THRESHOLD) {
            buzzer_on = 1;
            gpioWrite(BUZZER_GPIO, 1);
            time_t now = time(NULL);
            fprintf(log_file, "%ld: Fire and heat detected\n", now);
        } else if (last_flame_event) {
            fprintf(log_file, "Flame detected!\n");
        }

        if (ads1x15_read_single(I2C_ADDR) > TEMP_THRESHOLD) {
            buzzer_on = 1;
            gpioWrite(BUZZER_GPIO, 1);
            time_t now = time(NULL);
            fprintf(log_file, "%ld: Heat detected\n", now);
            fprintf(log_file, "Temperature: %.2f°C\n", ads1x15_read_single(I2C_ADDR) * 1.25); // Convert raw ADC value to temperature
        }

        if (buzzer_on) {
            if (!buzzer_callback(BUZZER_GPIO, 1)) {
                fprintf(stderr, "Buzzer callback failed\n");
                break;
            }
            sleep(2);
            buzzer_on = 0;
            gpioWrite(BUZZER_GPIO, 0);
        }

        gpioProcess(POLL_INTERVAL);
    }

cleanup:
    if (buzzer_on) {
        gpioWrite(BUZZER_GPIO, 0);
    }
    pigpio_stopCallback(FLAME_GPIO, PI_FALLING_EDGE);
    ads1x15_close(I2C_ADDR);
    if (log_file) {
        fclose(log_file);
    }
    pigpio_terminate();
    return 0;
}

void sigint_handler(int signo) {
    running = 0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    return _main(argc, argv);
}
