#include <string.h>
#include <stdbool.h>
#include <time.h>
#include <libgpiod.h>
#include <spidev.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>

#define SENSOR_SENSITIVITY 100e-3 // Default 100 mV/A
#define CURRENT_THRESHOLD 5.0 // Default 5.0 A
#define GPIO_FAN 18

struct spi_device dev;
int spi_fd;
int gpio_chip = 4; // Try gpiochip4 for Pi 5, fallback to 0
int gpio_fan = -1;

void usage(char *progname) {
    fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", progname);
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                SENSOR_SENSITIVITY = atof(optarg) * 1000.0; // Convert to mV/A
                break;
            case 't':
                CURRENT_THRESHOLD = atof(optarg);
                break;
            default:
                usage(argv[0]);
        }
    }

    struct gpiod_chip *chip;
    int ret = gpiod_chip_open(&chip, "gpiochip%d", gpio_chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return ret;
    }
    gpio_fan = gpiod_chip_get_line(chip, "P%d.18", 0);
    if (gpio_fan < 0) {
        fprintf(stderr, "Failed to get GPIO fan line\n");
        gpiod_chip_close(chip);
        return -EINVAL;
    }

    struct spidev *spi = spidev_open("/dev/spidev0.0", spi_fd);
    if (spi == NULL) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -ENODEV;
    }

    if (spidev_open(spi, &dev) < 0) {
        fprintf(stderr, "Failed to initialize SPI device\n");
        spidev_close(spi);
        gpiod_chip_close(chip);
        return -EINVAL;
    }

    if (gpiod_chip_request_lines(chip, &gpio_fan, NULL) < 0) {
        fprintf(stderr, "Failed to request GPIO fan line\n");
        spidev_close(spi);
        gpiod_chip_close(chip);
        return -EBUSY;
    }

    gpiod_chip_set_owner(chip, gpio_fan, GET_CURRENT_OWNER_PID);

    char timestamp[32];
    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto close_spi;
    }

    while (1) {
        uint8_t tx[3] = {0x01, 0x80, 0x00};
        uint8_t rx[3];
        int bytes_transferred = spidev_transfer(spi, tx, rx);
        if (bytes_transferred < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            break;
        }

        if (rx[0] != 0x01 || rx[1] != 0x80 || rx[2] != 0x00) {
            fprintf(stderr, "Invalid SPI response\n");
            break;
        }

        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        double voltage = adc_value * (3.3 / 1024.0);
        double current = voltage / SENSOR_SENSITIVITY;

        time_t now_sec = time(NULL);
        struct tm *now_tm = localtime(&now_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

        fprintf(log_file, "%s, Current: %.3f A\n", timestamp, current);

        if (current > CURRENT_THRESHOLD) {
            gpiod_trigger(chip, gpio_fan, true);
        } else {
            gpiod_trigger(chip, gpio_fan, false);
        }

        usleep(1000000); // Sample once per second
    }

close_spi:
    gpiod_chip_close(chip);
    spidev_close(spi);
    fclose(log_file);

    return 0;
}

