#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <wiringPiI2C.h>

#define DEVICE_ADDR 0x28
#define I2C_BUS 1
#define ADC_ADDR 0x48

// Calibration curve coefficients (example values)
#define CO_LOG_A 0.000022
#define CO_LOG_B -0.00000001

static const char *log_file = "co_log.txt";
static FILE *log_fp = NULL;

void init_pigpio();
void cleanup_pigpio();
uint16_t read_adc(int channel);
double convert_to_ppm(uint16_t raw_value);
void log_ppm(double ppm);

int main() {
    int ret;
    signal(SIGINT, cleanup_pigpio);
    signal(SIGTERM, cleanup_pigpio);

    init_pigpio();

    ret = wiringPiI2CSetup(I2C_BUS);
    if (ret) {
        fprintf(stderr, "Failed to initialize I2C bus %d\n", I2C_BUS);
        goto cleanup;
    }

    log_fp = fopen(log_file, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s\n", log_file);
        goto cleanup;
    }

    while (1) {
        gpioInitialise();
        gpioSetMode(I2C_BUS, PI_OUTPUT);
        gpioWrite(I2C_BUS, 0);
        delay(100);
        gpioWrite(I2C_BUS, 1);

        uint16_t raw_value = read_adc(0);
        if (raw_value == 0xFFFF) {
            fprintf(stderr, "Sensor absent or I2C error\n");
            continue;
        }

        double ppm = convert_to_ppm(raw_value);
        log_ppm(ppm);

        sleep(5);
    }

cleanup:
    cleanup_pigpio();
    if (log_fp) fclose(log_fp);
    return ret;
}

void init_pigpio() {
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup_pigpio() {
    pigpio_terminate();
}

uint16_t read_adc(int channel) {
    uint8_t addr = ADC_ADDR;
    uint8_t reg = channel * 2;

    gpioSetMode(I2C_BUS, PI_INPUT);
    if (wiringPiI2CReadReg16(I2C_BUS, addr) != 0x55) {
        return 0xFFFF; // Sensor absent or I2C error
    }

    gpioWrite(I2C_BUS, 0);
    reg |= 0x01;
    delay(1);
    uint16_t raw_value = wiringPiI2CReadReg16(I2C_BUS, addr) & 0x00FF;

    gpioWrite(I2C_BUS, 1);
    return raw_value;
}

double convert_to_ppm(uint16_t raw_value) {
    return CO_LOG_A * (double)raw_value + CO_LOG_B;
}

void log_ppm(double ppm) {
    time_t now = time(NULL);
    struct tm tm_struct;
    localtime_r(&now, &tm_struct);

    fprintf(log_fp, "%02d:%02d:%02d, %f PPM\n",
            tm_struct.tm_hour, tm_struct.tm_min, tm_struct.tm_sec, ppm);
    fflush(log_fp);
}

