#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define KY026_D0_PIN 4
#define MCP3008_CE0_PIN 8
#define MCP3008_SCLK_PIN 11
#define MCP3008_MOSI_PIN 10
#define MCP3008_MISO_PIN 9
#define MCP3008_CH 0

#define SPI_CLOCK 1000000

int main() {
    int spi_fd;
    gpioInitialise();
    if (gpioFailed()) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    spi_fd = spiOpen(MCP3008_SCLK_PIN, MCP3008_MISO_PIN, MCP3008_MOSI_PIN, SPI_CLOCK);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus.\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(KY026_D0_PIN, PI_OUTPUT);
    gpioSetMode(MCP3008_CE0_PIN, PI_OUTPUT);

    while (1) {
        gpioWrite(KY026_D0_PIN, 0); // Pull CE0 low to select MCP3008
        gpioWrite(MCP3008_CE0_PIN, 0);

        uint8_t spi_tx[2] = {MCP3008_CH << 4 | 0b00000100}; // Convert channel 0 to SPI command
        uint8_t spi_rx[3];
        int bytes_read = spiTransfer(spi_fd, spi_tx, spi_rx);
        if (bytes_read != 3) {
            fprintf(stderr, "SPI transfer failed.\n");
            break;
        }

        int adc_value = (spi_rx[1] << 8) | spi_rx[2];
        double temperature = (adc_value / 1023.0) * 30 + 10; // Linear scaling to 10.0-40.0°C

        gpioWrite(KY026_D0_PIN, 1); // Pull CE0 high to deselect MCP3008
        gpioWrite(MCP3008_CE0_PIN, 1);

        int flame_present = gpioRead(KY026_D0_PIN);

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

        FILE *file = fopen("flame_data.csv", "a");
        if (file) {
            fprintf(file, "%s,%d,%.1f\n", timestamp, flame_present, temperature);
            fclose(file);
        } else {
            fprintf(stderr, "Failed to open flame_data.csv for writing.\n");
            break;
        }
    }

    gpioTerminate();
    return 0;
}

