#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigio.h>

#define SENSOR_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define ALERT_THRESHOLD 25

float co_ppm;
FILE *co_log = NULL;
FILE *alert_log = NULL;

void sigint_handler(int signum) {
    if (co_log) fclose(co_log);
    if (alert_log) fclose(alert_log);
    pigio_terminate();
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

void init_logs() {
    co_log = fopen(LOG_FILE, "w");
    alert_log = fopen(ALERT_FILE, "w");
    if (!co_log || !alert_log) {
        perror("Error opening log files");
        pigio_terminate();
        exit(1);
    }
}

void cleanup_logs() {
    if (co_log) fclose(co_log);
    if (alert_log) fclose(alert_log);
}

void read_sensor_data() {
    uint8_t data[4];
    int ret = pigio_i2c_rd(gpioPin(SENSOR_ADDR), data, 4);
    if (ret < 0) {
        fprintf(stderr, "I2C read failed: %s\n", pigio_last_error());
        return;
    }

    uint16_t ox = (data[1] << 8) | data[0];
    uint16_t red = (data[3] << 8) | data[2];

    co_ppm = (float)ox / 65535 * 1000; // Assuming 1000 PPM/V
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    init_logs();

    if (pigio_initialise() < 0) {
        fprintf(stderr, "pigio_initialise failed: %s\n", pigio_last_error());
        cleanup_logs();
        return 1;
    }

