#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigio.h>

#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define LED_GPIO 27
#define SAMPLE_INTERVAL_US 1000
#define SAMPLE_WINDOW_MS 100
#define RMS_THRESHOLD 0.7
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / SAMPLE_INTERVAL_US)

float adc_values[NUM_SAMPLES][2];
float rms_values[NUM_SAMPLES];
char filename[] = "audio_events.csv";
FILE *fp = NULL;

void init_spi() {
    gpioInitialise();
    gpioSetMode(SPI0_MOSI, PI_OUTPUT);
    gpioSetMode(SPI0_MISO, PI_INPUT);
    gpioSetMode(SPI0_SCLK, PI_OUTPUT);
    gpioSetMode(SPI0_CE0, PI_OUTPUT);
    gpioSetMode(SPI0_CE1, PI_OUTPUT);

    if (gpioSPIOpen(SPI0_MOSI, SPI0_MISO, SPI0_SCLK, SPI0_CE0, SPI0_CE1, SAMPLE_INTERVAL_US) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_adc(int channel) {
    uint8_t msg[4];
    msg[0] = (channel << 4) | 0x30; // Start bit, channel selection
    gpioWrite(SPI0_CE0, 1);
    gpioWrite(SPI0_SCLK, 1);
    delayMicroseconds(1);
    gpioWrite(SPI0_SCLK, 0);
    delayMicroseconds(1);

    for (int i = 0; i < 8; i++) {
        if (i == 4) {
            msg[1] |= gpioRead(SPI0_MISO) << i & 0x80;
            delayMicroseconds(1);
            gpioWrite(SPI0_SCLK, 1);
            delayMicroseconds(1);
            gpioWrite(SPI0_SCLK, 0);
        } else {
            delayMicroseconds(1);
        }
    }

    gpioWrite(SPI0_CE0, 0);
    return (msg[1] << 8) | msg[2];
}

void cleanup() {
    gpioTerminate();
    if (fp != NULL) {
        fclose(fp);
    }
}

void sigint_handler(int signum) {
    gpioWrite(LED_GPIO, 0);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    init_spi();
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    if (fp == NULL) {
        fp = fopen(filename, "w");
        if (!fp) {
            fprintf(stderr, "Failed to open file %s\n", filename);
            cleanup();
            exit(EXIT_FAILURE);
        }
        fprintf(fp, "Timestamp,Mic1 RMS,Mic2 RMS\n");
    }

    while (1) {
        for (int i = 0; i < NUM_SAMPLES; i++) {
            adc_values[i][0] = read_adc(MCP3008_CHANNEL_0) / 1023.0;
            adc_values[i][1] = read_adc(MCP3008_CHANNEL_1) / 1023.0;
        }

        float mic1_sum = 0, mic2_sum = 0;
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_sum += adc_values[i][0];
            mic2_sum += adc_values[i][1];
        }

        float mic1_rms = sqrt(mic1_sum / NUM_SAMPLES);
        float mic2_rms = sqrt(mic2_sum / NUM_SAMPLES);

        rms_values[0] = mic1_rms;
        rms_values[1] = mic2_rms;

        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            delayMicroseconds(500000);
            gpioWrite(LED_GPIO, 0);
        }

        time_t t = time(NULL);
        fprintf(fp, "%ld,%f,%f\n", (long)t, rms_values[0], rms_values[1]);
        delayMicroseconds(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

