#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define BUFFER_SIZE 100
#define SAMPLING_INTERVAL 1000000 / 10 // 10Hz
#define OVERCURRENT_THRESHOLD 50.0
#define LED_PIN 17
#define I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x00
#define ADS1115_REG_CHANNEL_CONFIG 0x01
#define ADS1115_REG_SINGLE_ENDED_GAIN 0x02
#define ADS1115_REG_CONFIG_MUX 0x03
#define ADS1115_REG_RESULT_LOW 0x04
#define ADS1115_REG_RESULT_HIGH 0x05

float current_buffer[BUFFER_SIZE];
int buffer_index = 0;
float total_current = 0;

void overcurrent_warning() {
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 1);
}

void normal_operation() {
    gpioWrite(LED_PIN, 0);
}

void sigint_handler(int signum) {
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);
    pigpio_stop();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    if (i2cWriteDevice(I2C_ADDR, ADS1115_REG_CONFIG, 0x06) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        pigpio_terminate();
        gpioTerminate();
        return 1;
    }

    if (i2cWriteDevice(I2C_ADDR, ADS1115_REG_CHANNEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set channel configuration\n");
        pigpio_terminate();
        gpioTerminate();
        return 1;
    }

    if (i2cWriteDevice(I2C_ADDR, ADS1115_REG_SINGLE_ENDED_GAIN, 0x00) < 0) {
        fprintf(stderr, "Failed to set gain\n");
        pigpio_terminate();
        gpioTerminate();
        return 1;
    }

    if (i2cWriteDevice(I2C_ADDR, ADS1115_REG_CONFIG_MUX, 0x00) < 0) {
        fprintf(stderr, "Failed to set mux\n");
        pigpio_terminate();
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint16_t result_low, result_high;

        if (i2cReadDevice(I2C_ADDR, ADS1115_REG_RESULT_LOW, &result_low, 2) < 0) {
            fprintf(stderr, "Failed to read low bytes from ADS1115\n");
            break;
        }

        if (i2cReadDevice(I2C_ADDR, ADS1115_REG_RESULT_HIGH, &result_high, 2) < 0) {
            fprintf(stderr, "Failed to read high bytes from ADS1115\n");
            break;
        }

        float voltage = (result_high << 8 | result_low) * 0.0048828125; // Convert to Volts
        float current = voltage * OVERCURRENT_THRESHOLD / 4.5; // Assuming 100A full-scale

        current_buffer[buffer_index] = current;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        total_current += current;

        if (buffer_index > 0 && buffer_index % (BUFFER_SIZE / 10) == 0) {
            total_current /= buffer_index;
            if (total_current > OVERCURRENT_THRESHOLD) {
                overcurrent_warning();
            } else {
                normal_operation();
            }
        }

        usleep(SAMPLING_INTERVAL);
    }

    pigpio_terminate();
    gpioTerminate();
    return 0;
}

