#define TCS34725_ADDR 0x29
#define ATIME 0xFF
#define GAIN 0x01
#define ENABLE (0x01 | 0x02)
#define ID_CHECK 0x44

static FILE *csv_file = NULL;
static int i2c_failures = 0;

void sigint_handler(int signum) {
    gpioTerminate();
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }
    exit(0);
}

int main() {
    int ret;
    gpioInitialise();
    if ((ret = gpioSetMode(0, PI_OUTPUT)) != 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", ret);
        return 1;
    }
    if ((ret = gpioSetMode(1, PI_I2C_AD)) != 0) {
        fprintf(stderr, "Failed to set I2C mode: %d\n", ret);
        return 1;
    }
    if ((ret = gpioI2COpen(1, TCS34725_ADDR)) != 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", ret);
        return 1;
    }

    if (gpioRead(1, 0x12) != 0x44) {
        fprintf(stderr, "Invalid TCS34725 ID\n");
        return 1;
    }

    gpioWrite(1, 0x00);
    gpioWrite(1, ENABLE);
    usleep(3000);

    gpioWrite(1, TCS34725_ADDR | 0x01); // Set ATIME
    gpioWrite(1, ATIME);
    gpioWrite(1, TCS34725_ADDR | 0x0F); // Set GAIN
    gpioWrite(1, GAIN);
    gpioWrite(1, TCS34725_ADDR | 0x00); // Power on and enable ADC

    csv_file = fopen("color_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open color_log.csv\n");
        return 1;
    }
    fprintf(csv_file, "Year,Month,Day,Hour,Minute,Second,Clear,Red,Green,Blue\n");

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        static struct tm tm;
