#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <gpiod.h>

#define CHANNELS 2
#define SAMPLES_PER_SECOND 2
#define SPI_DEVICE "/dev/spidev0.0"
#define CE0_GPIO 8
#define MOISTURE_LOG "moisture_log.csv"

struct moisture_reading {
    time_t timestamp;
    uint16_t channel0;
    uint16_t channel1;
};

int main() {
    int spi_fd;
    int ret;
    struct moisture_reading readings[CHANNELS];
    struct gpiod_chip mcp3008_chip;
    struct gpiod_line *ce0;
    FILE *fp;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_FRAMES, &SAMPLES_PER_SECOND);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        return 1;
    }

    ce0 = gpiod_chip_get_line(&mcp3008_chip, CE0_GPIO);
    if (!ce0) {
        fprintf(stderr, "Failed to get CE0 line\n");
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_export(ce0, NULL) < 0) {
        fprintf(stderr, "Failed to export CE0 line\n");
        gpiod_line_free(ce0);
        close(spi_fd);
        return 1;
    }

    gpiod_line_set_direction(ce0, GPIO_DIR_OUT);

    fp = fopen(MOISTURE_LOG, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open moisture_log.csv\n");
        gpiod_line_free(ce0);
        close(spi_fd);
        return 1;
    }

    fprintf(fp, "Timestamp,Moisture1,Moisture2\n");

    while (1) {
        for (int i = 0; i < CHANNELS; i++) {
            readings[i].timestamp = time(NULL);

            // Read from MCP3008
            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &readings[i].channel0);
            if (ret < 0) {
                fprintf(stderr, "Failed to read from MCP3008 channel %d\n", i);
                gpiod_line_free(ce0);
                close(spi_fd);
                fclose(fp);
                return 1;
            }

            // Map raw value to 0-100% scale
            readings[i].channel0 = map(readings[i].channel0, 0, 1023, 0, 100);

            // Activate chip-select
            gpiod_line_trigger(ce0, GPIO_FALLING_EDGE);
            usleep(1000); // Short delay to allow settling
            gpiod_line_trigger(ce0, GPIO_NONE);

            // Read from MCP3008 again for the second channel
            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &readings[i].channel1);
            if (ret < 0) {
                fprintf(stderr, "Failed to read from MCP3008 channel %d\n", i);
                gpiod_line_free(ce0);
                close(spi_fd);
                fclose(fp);
                return 1;
            }

            // Map raw value to 0-100% scale
            readings[i].channel1 = map(readings[i].channel1, 0, 1023, 0, 100);

            fprintf(fp, "%ld,%d,%d\n", readings[i].timestamp, readings[i].channel0, readings[i].channel1);
        }

        sleep(5);
    }

    gpiod_line_free(ce0);
    close(spi_fd);
    fclose(fp);

    return 0;
}

uint16_t map(uint16_t x, uint16_t x_min, uint16_t x_max, uint16_t y_min, uint16_t y_max) {
    return (uint16_t)(((double)(x - x_min) * (y_max - y_min) / (x_max - x_min)) + y_min);
}

