#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <spidev.h>
#include <signal.h>

#define SENSOR_CHANNEL 0
#define SAMPLING_INTERVAL 1
#define OVERCURRENT_THRESHOLD 10.0
#define MAX_SPI_RETRIES 3

float sensitivity = 0.1;
float offset = 0.05;

int spi_fd;
int shutdown_gpio = 17;
int sensor_gpio = 8; // CE0
int clk_gpio = 11;   // SCLK
int mosi_gpio = 10; // MOSI
int miso_gpio = 9;  // MISO

FILE *log_file = NULL;

void log_current(float current) {
    if (log_file == NULL) {
        log_file = fopen("current_log.csv", "w");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        fprintf(log_file, "timestamp,current_in_Amperes\n");
    }
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s,%f\n", timestamp, current);
    fclose(log_file);
    log_file = fopen("current_log.csv", "a");
}

float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024;
}

float adc_to_current(int adc_value) {
    return sensitivity * (adc_to_voltage(adc_value) - offset);
}

void shutdown_motor() {
    gpiod_trigger_disable(shutdown_gpio);
}

void enable_motor() {
    gpiod_trigger_enable(shutdown_gpio);
}

void spi_read(int retries) {
    if (retries > MAX_SPI_RETRIES) {
        fprintf(stderr, "SPI communication error, giving up.\n");
        return;
    }

    int fd_mosi = open("/dev/spidev0.0", O_RDWR);
    if (fd_mosi < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    int fd_miso = open("/dev/spidev0.0", O_RDWR);
    if (fd_miso < 0) {
        perror("Failed to open SPI device");
        close(fd_mosi);
        exit(EXIT_FAILURE);
    }

    struct spi_transfer transf;
    transf.tx_buf = NULL;
    transf.rx_buf = NULL;
    transf.len = 1;

    if (ioctl(fd_mosi, SPI_WRITE, &transf) < 0) {
        fprintf(stderr, "SPI write failed, retrying...\n");
        spi_read(retries + 1);
        close(fd_mosi);
        close(fd_miso);
        return;
    }

    if (ioctl(fd_miso, SPI_READ, &transf) < 0) {
        fprintf(stderr, "SPI read failed, retrying...\n");
        spi_read(retries + 1);
        close(fd_mosi);
        close(fd_miso);
        return;
    }

    close(fd_mosi);
    close(fd_miso);
}

int main() {
    struct gpiod_chip chip;
    gpiod_chip_init(&chip);

    int ret = gpiod_chip_add_lines(&chip, "gpiochip0",
                                     &shutdown_gpio, GPIO_DIR_OUT, "Shutdown GPIO");
    if (ret < 0) {
        fprintf(stderr, "Failed to add shutdown GPIO\n");
        return ret;
    }

    ret = gpiod_chip_add_lines(&chip, "gpiochip0",
                                 &sensor_gpio, GPIO_DIR_IN, "Sensor CE0");
    if (ret < 0) {
        fprintf(stderr, "Failed to add sensor CE0 GPIO\n");
        gpiod_chip_remove_lines(&chip, &shutdown_gpio);
        return ret;
    }

    ret = gpiod_chip_add_lines(&chip, "gpiochip0",
                                 &clk_gpio, GPIO_DIR_OUT, "SPI SCLK");
    if (ret < 0) {
        fprintf(stderr, "Failed to add SPI SCLK GPIO\n");
        gpiod_chip_remove_lines(&chip, &shutdown_gpio);
        return ret;
    }

    ret = gpiod_chip_add_lines(&chip, "gpiochip0",
                                 &mosi_gpio, GPIO_DIR_OUT, "SPI MOSI");
    if (ret < 0) {
        fprintf(stderr, "Failed to add SPI MOSI GPIO\n");
        gpiod_chip_remove_lines(&chip, &shutdown_gpio);
        return ret;
    }

    ret = gpiod_chip_add_lines(&chip, "gpiochip0",
                                 &miso_gpio, GPIO_DIR_IN, "SPI MISO");
    if (ret < 0) {
        fprintf(stderr, "Failed to add SPI MISO GPIO\n");
        gpiod_chip_remove_lines(&chip, &shutdown_gpio);
        return ret;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        spi_read(0);
        int adc_value = *(int *)((char *)&transf.rx_buf[0]);

        float current = adc_to_current(adc_value);
        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            shutdown_motor();
            fprintf(stderr, "Overcurrent detected! Motor shutting down...\n");
            log_current(current);
            sleep(1);
            enable_motor();
            fprintf(stderr, "Motor re-enabled.\n");
        }

        sleep(SAMPLING_INTERVAL);
    }

    gpiod_chip_remove_lines(&chip, &shutdown_gpio);
    gpiod_chip_remove_lines(&chip, &sensor_gpio);
    gpiod_chip_remove_lines(&chip, &clk_gpio);
    gpiod_chip_remove_lines(&chip, &miso_gpio);
    gpiod_chip_release(&chip);

    close(spi_fd);
    return 0;
}

void exit_handler(int signum) {
    printf("Exiting...\n");
    gpiod_chip_remove_lines(&chip, &shutdown_gpio);
    gpiod_chip_remove_lines(&chip, &sensor_gpio);
    gpiod_chip_remove_lines(&chip, &clk_gpio);
    gpiod_chip_remove_lines(&chip, &miso_gpio);
    gpiod_chip_release(&chip);
    fclose(log_file);
    return;
}

