        fprintf(stderr, "Failed to add SPI MOSI GPIO\n");
        gpiod_chip_remove_lines(&chip, &shutdown_gpio);
        return ret;
    }

    ret = gpiod_chip_add_lines(&chip, "gpiochip0",
                                 &miso_gpio, GPIO_DIR_IN, "SPI MISO");
    if (ret < 0) {
        fprintf(stderr, "Failed to add SPI MISO GPIO\n");
        gpiod_chip_remove_lines(&chip, &shutdown_gpio);
        return ret;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        spi_read(0);
        int adc_value = *(int *)((char *)&transf.rx_buf[0]);

        float current = adc_to_current(adc_value);
        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            shutdown_motor();
            fprintf(stderr, "Overcurrent detected! Motor shutting down...\n");
            log_current(current);
            sleep(1);
            enable_motor();
            fprintf(stderr, "Motor re-enabled.\n");
        }

        sleep(SAMPLING_INTERVAL);
    }

    gpiod_chip_remove_lines(&chip, &shutdown_gpio);
    gpiod_chip_remove_lines(&chip, &sensor_gpio);
    gpiod_chip_remove_lines(&chip, &clk_gpio);
    gpiod_chip_remove_lines(&chip, &miso_gpio);
    gpiod_chip_release(&chip);

    close(spi_fd);
    return 0;
}

void exit_handler(int signum) {
    printf("Exiting...\n");
    gpiod_chip_remove_lines(&chip, &shutdown_gpio);
    gpiod_chip_remove_lines(&chip, &sensor_gpio);
    gpiod_chip_remove_lines(&chip, &clk_gpio);
    gpiod_chip_remove_lines(&chip, &miso_gpio);
    gpiod_chip_release(&chip);
    fclose(log_file);
    return;
}
