#include <time.h>

#define LED_PIN 17
#define SAMPLES 1
#define MAX_RETRIES 3
#define WARNING_THRESHOLD 105.0

float adc_to_pressure(float adc_value) {
    return (adc_value * 6.144) / 5.0;
}

float adc_to_temperature(float adc_value) {
    return (adc_value * 100.0) / 2.0;
}

int main() {
    pigpio_init();
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetWarningOnHighOutput(LED_PIN);

    int ads_addr = 0x48;
    int retry_count = 0;
    int ads_data[2];

    while (1) {
        for (int i = 0; i < MAX_RETRIES; i++) {
            int ret = pigpio_i2c_rd(ads_addr, 2, ads_data, sizeof(ads_data));
            if (ret >= 0) {
                break;
            }
            retry_count++;
            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Error: Failed to read from ADS1115 after %d retries.\n", MAX_RETRIES);
                goto cleanup;
            }
        }

        float pressure = adc_to_pressure((ads_data[0] << 8 | ads_data[1]) / 32768.0 * 6.144);
        float temperature = adc_to_temperature((ads_data[0] << 8 | ads_data[1]) / 32768.0 * 2.0);

        gpioWrite(LED_PIN, pressure > WARNING_THRESHOLD);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
        time.h_sleep(1);
    }

cleanup:
    pigpio_terminate();
    return 0;
}

