#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define SPI_MODE 0
#define MCP3008_CE0_GPIO 8
#define MCP3008_SCLK_GPIO 11
#define MCP3008_MOSI_GPIO 10
#define MCP3008_MISO_GPIO 9
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100
#define OVERCURRENT_THRESHOLD 1000 // 10A in ADC steps

int spi_fd = -1;
gpio_init();

void spi_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    spi_fd = gpioSPIOpen(MCP3008_MOSI_GPIO, MCP3008_MISO_GPIO, MCP3008_SCLK_GPIO, MCP3008_CE0_GPIO, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

uint16_t read_adc(uint8_t channel) {
    uint8_t transfer[3] = {0x01, channel | 0x80, 0x00};
    uint16_t result = 0;

    if (gpioSPITransfer(spi_fd, transfer, &result, 3) != 3) {
        fprintf(stderr, "SPI transfer error.\n");
        exit(EXIT_FAILURE);
    }

    return result;
}

float adc_to_voltage(uint16_t adc_value) {
    return (float)adc_value * (3.3 / 1024);
}

float adc_to_current(float voltage) {
    return (voltage - 1.65) * 66; // 1.65V is Vcc/2
}

void log_current(float current) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    if (fputs(timestamp, log_file) == EOF || fputs(" Current: ", log_file) == EOF ||
        fprintf(log_file, "%.2f A\n", current) == EOF) {
        fprintf(stderr, "Error writing to log file.\n");
    }

    fclose(log_file);
}

int main() {
    spi_init();
    gpioSetMode(MCP3008_CE0_GPIO, PI_OUTPUT);

    while (1) {
        uint16_t adc_value = read_adc(MCP3008_CHANNEL);
        float voltage = adc_to_voltage(adc_value);
        float current = adc_to_current(voltage);

        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            gpioSetMode(27, PI_OUTPUT);
            gpioWrite(27, 1);
            log_current(current) = "OVERCURRENT";
            break;
        }

        delay_ms(SAMPLE_INTERVAL_MS);
    }

    gpioClose(spi_fd, 0);
    gpioTerminate();
    gpioSetMode(27, PI_OUTPUT);
    gpioWrite(27, 0);

    return 0;
}

