#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define MCP3008_CHANNEL 0
#define REFERENCE_VOLTAGE 3.3
#define ALARM_THRESHOLD (REFERENCE_VOLTAGE * 2.5 / 1024.0)

static FILE *log_file = NULL;

void log_reading(double voltage) {
    if (log_file != NULL) {
        time_t now;
        struct tm *time_struct;
        time(&now);
        time_struct = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,Voltage: %.2f V\n",
                1900 + time_struct->tm_year, time_struct->tm_mon + 1,
                time_struct->tm_mday, time_struct->tm_hour,
                time_struct->tm_min, time_struct->tm_sec, voltage);
    }
}

int main() {
    int spi_fd;
    int ret;
    gpioInitialise();
    spi_fd = spiOpen(0, 1000000);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        return 1;
    }

    if (gpioSetMode(4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO4 as output\n");
        spiClose(spi_fd);
        return 1;
    }

    log_file = fopen("co_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        gpioWrite(4, 0); // Turn off alarm

        ret = spiTransfer(spi_fd, 0x01);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed, logging error and retrying\n");
            log_error("SPI transfer failed");
            sleep(1);
            continue;
        }

        uint16_t adc_value = (ret >> 8) & 0xFF;
        double voltage = (adc_value * REFERENCE_VOLTAGE) / 1024.0;
        log_reading(voltage);

        if (voltage > ALARM_THRESHOLD) {
            gpioWrite(4, 1); // Turn on alarm
        } else {
            gpioWrite(4, 0); // Turn off alarm
        }

        sleep(1);
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

void log_error(const char *error_message) {
    if (log_file != NULL) {
        fprintf(log_file, "ERROR: %s\n", error_message);
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (spi_fd >= 0) {
            spiClose(spi_fd);
        }

        if (log_file != NULL) {
            fclose(log_file);
        }

        gpioTerminate();
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return main();
}

