#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <fcntl.h>
#include <unistd.h>

#define MCP3008_SPI_BUS 0
#define MCP3008_CHANNEL 0
#define START_BYTE 0x01
#define CONFIG_BYTE 0x80
#define DUMMY_BYTE 0x00
#define MAX_PPM 5000

int spi_fd;
int spi_handle;
FILE *log_file;

void spi_transfer(uint8_t tx[], uint8_t rx[], int len) {
    int ret;
    ret = spiTransfer(spi_fd, tx, rx, len);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
    }
}

int main() {
    int ret;
    struct timespec timestamp;
    uint8_t tx[3] = {START_BYTE, CONFIG_BYTE, DUMMY_BYTE};
    uint8_t rx[3];

    // Initialize pigpio
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", ret);
        return 1;
    }
    gpioSetMode(8, PI_OUTPUT); // Set GPIO8 as output (CS/SHDN)

    // Open SPI bus
    spi_fd = spiOpen(MCP3008_SPI_BUS, 1000000);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        return 1;
    }

    // Set CS/SHDN low
    gpioWrite(8, 0);

    // Initialize file for logging
    log_file = fopen("methane_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &timestamp);
        char time_str[32];
        strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%SZ", localtime_r(&timestamp.tv_sec, &tm));

        spi_transfer(tx, rx, 3);
        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        double methane_ppm = adc_value * (MAX_PPM / 1023.0);

        fprintf(log_file, "%s: %f PPM\n", time_str, methane_ppm);
