        fprintf(stderr, "Failed to initialize I2C bus %d\n", i2c_bus);
        goto exit_cleanup;
    }

    if (!init_ads1115(ads_bus_num)) {
        fprintf(stderr, "Failed to initialize ADS1115 on I2C bus %d\n", ads_bus_num);
        goto exit_i2c_cleanup;
    }

    while (1) {
        uint16_t adc_value = read_ads1115(ads_bus_num, AIN_CHANNEL);
        if (adc_value == 0xFFFF) {
            fprintf(stderr, "ADS1115 read error\n");
            continue;
        }

        float voltage = adc_value_to_voltage(adc_value);
        float pressure = voltage_to_pressure(voltage);

        if (pressure < 0 || pressure > 100) {
            fprintf(stderr, "Pressure out of range: %f kPa\n", pressure);
            continue;
        }

        char timestamp[24];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&time(NULL)));
        log_pressure(pressure, timestamp);

        gpioTerminate();
        sleep(SAMPLING_INTERVAL);
    }

exit_cleanup:
    gpioTerminate();

exit_i2c_cleanup:
    if (ads_bus_num == i2c_bus)
        init_ads1115(ads_bus_num);

return 0;
}

