    if (gpioI2CInit(bus_num) < 0) {
        return 0;
    }
    return 1;
}

int init_ads1115(int bus_num) {
    if (pigpio_initialise() < 0) {
        return 0;
    }
    return 1;
}

uint16_t read_ads1115(int bus_num, int channel) {
    uint16_t result;
    if (pigpio_write(0, 0) < 0 || pigpio_i2c_rdwr(bus_num, 0x40, &result, 2, 0, NULL) < 0) {
        return 0xFFFF; // Error or no response
    }
    return result;
}

float adc_value_to_voltage(uint16_t adc_value) {
    return (float)adc_value * (5.0 / 65535.0);
}

float voltage_to_pressure(float voltage) {
    float pressure = (voltage - 0.5) * 0.1;
    return pressure;
}

void log_pressure(float pressure, char *timestamp) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open pressure_log.txt\n");
        return;
    }
    fprintf(fp, "%s, %f kPa\n", timestamp, pressure);
    fclose(fp);
}

