#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <spidev.h>
#include <signal.h>

#define MCP3208_CHANNEL 0
#define VREF 3.3
#define TMP36_SENSITIVITY 0.01
#define TMP36_MIN_VOLTAGE -0.5
#define TMP32_MAX_VOLTAGE 1.7
#define TMP36_MIN_TEMP -40.0
#define TMP36_MAX_TEMP 125.0

struct spi_data {
    spidev_fd fd;
    int channel;
};

struct temp_data {
    FILE *log_file;
    char header[50];
};

static struct gpiod_chip gpiochip4;
static struct gpiod_line *cs_line;
static struct spi_data spi_dev;
static struct temp_data temp_data;

static void spi_close(struct spi_data *dev) {
    spidev_close(dev->fd);
}

static int spi_transfer(struct spi_data *dev, uint8_t *tx_buf, uint8_t *rx_buf, uint16_t len) {
    return spidev_transfer(dev->fd, tx_buf, rx_buf, len);
}

static void init_gpio(void) {
    int ret;

    ret = gpiod_chip_open(&gpiochip4, "gpiochip4");
    if (ret) {
        fprintf(stderr, "Failed to open gpiochip4\n");
        exit(EXIT_FAILURE);
    }

    cs_line = gpiod_chip_get_line(&gpiochip4, "gpio8");
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS line\n");
        gpiod_chip_close(&gpiochip4);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_export(cs_line, true);
    if (ret) {
        fprintf(stderr, "Failed to export CS line\n");
        gpiod_chip_close(&gpiochip4);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_add(cs_line, GPIO_DIR_OUT);
    if (ret) {
        fprintf(stderr, "Failed to request CS line\n");
        gpiod_chip_close(&gpiochip4);
        exit(EXIT_FAILURE);
    }
}

static void cleanup_gpio(void) {
    gpiod_line_release(cs_line);
    gpiod_chip_close(&gpiochip4);
}

static void init_spi(void) {
    int ret;

    spi_dev.fd = spidev_open("/dev/spidev0.0", 0);
    if (spi_dev.fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }

    ret = spidev_ioctl(spi_dev.fd, SPI_RCSR, &spi_dev.channel);
    if (ret) {
        fprintf(stderr, "Failed to set SPI mode\n");
        spidev_close(spi_dev.fd);
        exit(EXIT_FAILURE);
    }

    spi_dev.channel |= SPI_CS_HIGH; // Set CS high initially
}

static void cleanup_spi(void) {
    spi_close(&spi_dev);
}

static void read_temp(void) {
    uint8_t tx_buf[2] = {MCP3208_CHANNEL | 0x60, 0x00};
    uint8_t rx_buf[3];
    int16_t adc_value;
    float voltage, celsius;

    if (spi_transfer(&spi_dev, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed\n");
        return;
    }

    adc_value = (rx_buf[1] << 8) | rx_buf[2];

    if (adc_value < 0 || adc_value > 4095) {
        fprintf(stderr, "Invalid ADC reading\n");
        return;
    }

    voltage = (adc_value / 4095.0) * VREF;

    if (voltage < TMP36_MIN_VOLTAGE || voltage > TMP32_MAX_VOLTAGE) {
        fprintf(stderr, "Voltage out of range\n");
        return;
    }

    celsius = (voltage - TMP36_SENSITIVITY) / TMP36_SENSITIVITY;

    if (celsius < TMP36_MIN_TEMP || celsius > TMP36_MAX_TEMP) {
        fprintf(stderr, "Temperature out of range\n");
        return;
    }

    fprintf(temp_data.log_file, "%lu,%.2f\n", time(NULL), celsius);
}

static void sigint_handler(int signum) {
    cleanup_spi();
    cleanup_gpio();
    fclose(temp_data.log_file);
    exit(EXIT_SUCCESS);
}

int main(void) {
    int ret;
    struct sigaction sa;

    temp_data.log_file = fopen("temperature_log.csv", "a");

    if (!temp_data.log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (fgetc(temp_data.log_file) != ',') {
        fprintf(temp_data.log_file, "timestamp,temperature_celsius\n");
    }

    init_gpio();
    init_spi();

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        read_temp();
        sleep(1);
    }

    cleanup_spi();
    cleanup_gpio();
    fclose(temp_data.log_file);

    return EXIT_SUCCESS;
}

