static void read_temp(void) {
    uint8_t tx_buf[2] = {MCP3208_CHANNEL | 0x60, 0x00};
    uint8_t rx_buf[3];
    int16_t adc_value;
    float voltage, celsius;

    if (spi_transfer(&spi_dev, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed\n");
        return;
    }

    adc_value = (rx_buf[1] << 8) | rx_buf[2];

    if (adc_value < 0 || adc_value > 4095) {
        fprintf(stderr, "Invalid ADC reading\n");
        return;
    }

    voltage = (adc_value / 4095.0) * VREF;

    if (voltage < TMP36_MIN_VOLTAGE || voltage > TMP32_MAX_VOLTAGE) {
        fprintf(stderr, "Voltage out of range\n");
        return;
    }

    celsius = (voltage - TMP36_SENSITIVITY) / TMP36_SENSITIVITY;

    if (celsius < TMP36_MIN_TEMP || celsius > TMP36_MAX_TEMP) {
        fprintf(stderr, "Temperature out of range\n");
        return;
    }

    fprintf(temp_data.log_file, "%lu,%.2f\n", time(NULL), celsius);
}

static void sigint_handler(int signum) {
    cleanup_spi();
    cleanup_gpio();
    fclose(temp_data.log_file);
    exit(EXIT_SUCCESS);
}

int main(void) {
    int ret;
    struct sigaction sa;

    temp_data.log_file = fopen("temperature_log.csv", "a");

    if (!temp_data.log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (fgetc(temp_data.log_file) != ',') {
        fprintf(temp_data.log_file, "timestamp,temperature_celsius\n");
    }

    init_gpio();
    init_spi();

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        read_temp();
        sleep(1);
    }

    cleanup_spi();
    cleanup_gpio();
    fclose(temp_data.log_file);

    return EXIT_SUCCESS;
}
