#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define SI1172_I2C_BUS 1
#define SI1172_I2C_ADDR 0x49
#define FIFO_REG_START 0xC1
#define FIFO_REG_END 0xC4
#define IR_ADC_REG 0xC1
#define RED_ADC_REG 0xC3

#define LOG_FILE "biometric_log.csv"

enum {
    ERROR_NONE = 0,
    ERROR_READ = 1,
    ERROR_SENSOR_ABSENT = 2,
};

typedef struct {
    time_t timestamp;
    int hr;
    int spo2;
    int error_flag;
} BiometricData;

int i2c_read(int bus, int addr, uint8_t reg, uint16_t *value) {
    int fd = i2c_open(bus, 1000);
    if (fd < 0) {
        return ERROR_SENSOR_ABSENT;
    }

    int res = pigpio_i2c_rdwr(fd, addr, 0, NULL, 0, reg, value, 2);
    i2c_close(fd);

    if (res < 0) {
        return ERROR_READ;
    }

    return ERROR_NONE;
}

int main() {
    gpioInitialise();
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,HR(bpm),SpO2(%),Error_Flag\n");

    while (1) {
        BiometricData data;
        data.timestamp = time(NULL);

        uint16_t ir_adc, red_adc;
        int error = i2c_read(SI1172_I2C_BUS, SI1172_I2C_ADDR, IR_ADC_REG, &ir_adc);
        if (error != ERROR_NONE) {
            data.error_flag = error;
        } else {
            error = i2c_read(SI1172_I2C_BUS, SI1172_I2C_ADDR, RED_ADC_REG, &red_adc);
            if (error != ERROR_NONE) {
                data.error_flag = error;
            } else {
                data.hr = ir_adc;
                data.spo2 = red_adc;
                data.error_flag = ERROR_NONE;
            }
        }

        fprintf(log_file, "%ld,%d,%d,%d\n",
                (long)data.timestamp, data.hr, data.spo2, data.error_flag);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    pigpio_terminate();
    gpioTerminate();

    return EXIT_SUCCESS;
}

// Handle SIGINT for graceful shutdown
void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT, shutting down...\n");
    // Close I2C handle, terminate pigpio, and close log file here
}

int main() {
    signal(SIGINT, sigint_handler);
    // ... rest of the main function ...
}

