#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define SENSOR_SPI_CHANNEL 0
#define SENSOR_SPI_BAUD 1000000
#define ADC_RES 1024
#define VCC 3.3
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0

float adc_to_voltage(int adc_value) {
    return (float)adc_value * VCC / ADC_RES;
}

float voltage_to_flow(float voltage) {
    return (voltage / 3.3) * (FLOW_MAX - FLOW_MIN) + FLOW_MIN;
}

int main() {
    int spi_fd;
    gpioInitialise();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_fd = spiOpen(SENSOR_SPI_CHANNEL, SENSOR_SPI_BAUD);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    char timestamp[25];
    FILE *log_file = fopen("flow_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        gpioSetMode(8, PI_OUTPUT);
        gpioWrite(8, 1);
        usleep(100000);
        gpioWrite(8, 0);

        int adc_value;
        if (spiTransfer(spi_fd, 0x00, &adc_value, 1) != 1) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        float voltage = adc_to_voltage(adc_value);
        float flow_rate = voltage_to_flow(voltage);

        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Invalid flow rate: %f\n", flow_rate);
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s,%f\n", timestamp, flow_rate);
        fflush(log_file);

        usleep(1000000); // 1 second
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

