#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "0"
#define I2C_ADDR 0x67
#define MEASUREMENT_CMD 0x6845
#define SAMPLE_INTERVAL 5

#define TEMP_CAL_A -0.00002025
#define TEMP_CAL_B 0.00010018
#define PRESS_CAL_A 0.00002412
#define PRESS_CAL_B -0.00000011

int i2c_fd = -1;
FILE *csv_log = NULL;

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (csv_log != NULL) {
        fclose(csv_log);
        csv_log = NULL;
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int i2c_init() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open i2c-1\n");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to acquire bus access and/or talk to slave\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int i2c_read_calibration(uint8_t *data, int len) {
    if (write(i2c_fd, &MEASUREMENT_CMD, 2) != 2) {
        log_error("Failed to send measurement command\n");
        return -1;
    }

    // Wait for conversion to finish (implementation depends on the sensor)
    // ...

    if (read(i2c_fd, data, len) != len) {
        log_error("Failed to read from sensor\n");
        return -1;
    }

    return 0;
}

double convert_temp(uint16_t temp_msb, uint16_t temp_lsb) {
    return (temp_msb * TEMP_CAL_A) + (temp_lsb * TEMP_CAL_B);
}

double convert_pressure(uint16_t press_msb, uint16_t press_lsb) {
    return (press_msb * PRESS_CAL_A) + (press_lsb * PRESS_CAL_B);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    csv_log = fopen("environmental_data.csv", "a");
    if (!csv_log) {
        log_error("Failed to open CSV log file\n");
        return -1;
    }

    if (i2c_init() < 0) {
        return -1;
    }

    while (1) {
        uint8_t pressure_msb, pressure_lsb, temp_msb, temp_lsb, crc_high, crc_low;
        i2c_read_calibration(&pressure_msb, &pressure_lsb, &temp_msb, &temp_lsb, &crc_high, &crc_low);

        double pressure = convert_pressure(pressure_msb, pressure_lsb);
        double temp = convert_temp(temp_msb, temp_lsb);

        time_t now = time(NULL);
        fprintf(csv_log, "%ld,%f,%f\n", now, temp, pressure);
        printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temp, pressure);

        fflush(csv_log);
        fflush(stdout);

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

