#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define MCP3008_SPI_CHANNEL 0
#define SAMPLE_INTERVAL 60000000 // 60 seconds in nanoseconds
#define FILE_PATH "moisture_log.txt"

int main() {
    int spi_fd;
    int adc_value;
    char timestamp[25];
    FILE *file;

    // Initialize pigpio library
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    // Initialize SPI0 with CE0
    spi_fd = pigpio_open(0, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI0 (CE0).\n");
        pigpio_terminate();
        return 1;
    }

    // Configure GPIO pins for MCP3008
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        pigpio_close(spi_fd, 0);
        pigpio_terminate();
        return 1;
    }

    // Set CS, SCLK, MISO, MOSI pins for MCP3008
    gpioSetMode(VEGETRONIX_CS_PIN, PI_OUTPUT);
    gpioSetMode(MCP3008_SPI_CHANNEL, PI_OUTPUT);
    gpioSetMode(MCP3008_SCLK_PIN, PI_OUTPUT);
    gpioSetMode(MCP3008_MISO_PIN, PI_INPUT);
    gpioSetMode(MCP3008_MOSI_PIN, PI_OUTPUT);

    // Start SPI transfer
    if (pigpio_spiTransfer(spi_fd, &MCP3008_SPI_CHANNEL, &adc_value, 1) != 1) {
        fprintf(stderr, "SPI transfer failed.\n");
        gpioClose(spi_fd, 0);
        pigpio_terminate();
        return 1;
    }

    // Validate ADC range
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        gpioClose(spi_fd, 0);
        pigpio_terminate();
        return 1;
    }

    // Open log file
    file = fopen(FILE_PATH, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", FILE_PATH);
        gpioClose(spi_fd, 0);
        pigpio_close(spi_fd);
        pigpio_terminate();
        return 1;
    }

    // Infinite loop for continuous sampling
    while (1) {
        // Get current UTC timestamp
        time_t rawtime;
        struct tm * timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Write moisture reading to file
        if (fprintf(file, "%s,%d\n", timestamp, adc_value) < 0) {
            fprintf(stderr, "Failed to write to log file.\n");
            break;
        }

        // Sleep for the specified interval
        struct timespec req = {0};
        req.tv_sec = SAMPLE_INTERVAL / 1000000000;
        nanosleep(&req, NULL);
    }

    // Close file and release resources
    fclose(file);
    gpioClose(spi_fd, 0);
    pigpio_close(spi_fd);
    gpioTerminate();
    pigpio_terminate();

    return 0;
}

