#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <spidev.h>

#define CH0 0
#define GPIO_BUZZER 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRY 3

int spi_fd;
int chip_select;
struct gpiod_chip gpiod_chip;
struct gpiod_line buzzer_line;
FILE *log_file;
double ambient_temp = 25.0;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(stderr, format, args);
    va_end(args);
    fflush(stderr);

    fprintf(log_file, "%s, ", asctime(localtime(&now)), format, args);
    fputc('\n', log_file);
}

int read_adc(uint8_t *adc_data) {
    int ret;
    struct spi_transfer spi_txfx[1];

    spi_txfx[0].tx_buf = (void *)"0x00";
    spi_txfx[0].len = 3;
    spi_txfx[0].flags = SPI_TRANSFER_MSBFIRST;

    ret = spi_xfer(spi_fd, spi_txfx, 1);
    if (ret < 0) {
        log_message("SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    memcpy(adc_data, spi_txfx[0].tx_buf, 3);
    return 0;
}

double get_ambient_temp() {
    double temp;
    int fd = fopen("ambient_temp.txt", "r");
    if (fd == NULL) {
        log_message("Failed to open ambient_temp.txt\n");
        return 25.0;
    }
    fscanf(fd, "%lf", &temp);
    fclose(fd);
    return temp;
}

int main() {
    int ret;
    struct timespec sample_delay;
    clock_gettime(CLOCK_MONOTONIC, &sample_delay);

    spi_fd = spi_open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_message("Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    chip_select = gpiod_chip_register_acquire(&gpiod_chip, "SPI_CS");
    if (!chip_select) {
        log_message("Failed to acquire SPI chip select\n");
        spi_close(spi_fd);
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(gpiod_chip.id, "buzzer");
    if (!buzzer_line) {
        log_message("Failed to acquire buzzer line\n");
        spi_close(spi_fd);
        gpiod_chip_release(gpiod_chip);
        return 1;
    }

    log_file = fopen("flame_log.txt", "w");
    if (!log_file) {
        log_message("Failed to open log file\n");
        spi_close(spi_fd);
        gpiod_chip_release(gpiod_chip);
        return 1;
    }

    ambient_temp = get_ambient_temp();

    sample_delay.tv_sec = sample_interval_ms / 1000;
    sample_delay.tv_nsec = (sample_interval_ms % 1000) * 1000000;

    while (1) {
        uint8_t adc_data[3];
        int adc_value;

        ret = read_adc(adc_data);
        if (ret < 0) {
            continue;
        }

        adc_value = (adc_data[1] << 8) | adc_data[2];
        if (adc_value > 1023 || adc_value < 0) {
            for (int i = 0; i < MAX_RETRY; ++i) {
                ret = read_adc(adc_data);
                if (ret < 0) {
                    break;
                }
                adc_value = (adc_data[1] << 8) | adc_data[2];
                if (adc_value >= 0 && adc_value <= 1023) {
                    break;
                }
            }
            if (adc_value < 0 || adc_value > 1023) {
                continue;
            }
        }

        double voltage = (double)adc_value * (5.0 / 1023.0);
        double compensated_voltage = voltage + (ambient_temp - 25.0) * 0.001;

        if (compensated_voltage > 1.0) {
            gpiod_trigger_enable(buzzer_line, NULL);
            log_message("Flame detected: %f\n", compensated_voltage);
        } else {
            gpiod_trigger_disable(buzzer_line, NULL);
            log_message("No flame detected: %f\n", compensated_voltage);
        }

        fprintf(log_file, "%s, %d, %f, %f, %f, %d\n",
                asctime(localtime(&now)), adc_value,
                voltage, compensated_voltage, ambient_temp,
                compensated_voltage > 1.0);

        nanosleep(&sample_delay, NULL);
    }

    fclose(log_file);
    gpiod_chip_release(gpiod_chip);
    spi_close(spi_fd);

    return 0;
}

