#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define LED_PIN 17
#define CE0 8
#define MISO 9
#define MOSI 10
#define SCLK 11
#define MCP3008_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_MODE 0
#define LED_THRESHOLD_HIGH 75
#define LED_THRESHOLD_LOW 70
#define JSON_FILE "water_levels.json"

struct water_level_data {
    char timestamp[20];
    int water_level;
};

void log_reading(struct water_level_data data) {
    FILE *file = fopen(JSON_FILE, "a");
    if (file) {
        fprintf(file, "[");
        fputs(data.timestamp, file);
        fprintf(file, ",");
        fprintf(file, "%d", data.water_level);
        fprintf(file, "]\n");
        fclose(file);
    }
}

int main() {
    int spi_channel;
    int rc;

    // Initialize pigpio library
    if ((rc = pigpio_initialise()) < 0) {
        pigpio_error("pigpio_initialise() failed");
        return 1;
    }

    // Set GPIO pins
    pinMode(CE0, PI_OUTPUT);
    pinMode(LED_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_channel = spiOpen(SPI_BUS_SPI0, SPI_DEVICE_MCP3008, SPI_BAUD, SPI_MODE);
    if (spi_channel < 0) {
        pigpio_error("spiOpen() failed");
        pigpio_terminate();
        return 1;
    }

    // Set CE0 low to select MCP3008
    gpioSetMode(CE0, PI_OUTPUT);
    gpioWrite(CE0, 0);

    struct water_level_data data;
    char timestamp[20];

    while (1) {
        // Get current timestamp
        time_t rawtime;
        struct tm * timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(data.timestamp, sizeof(data.timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Perform SPI transfer
        uint8_t tx[3] = {0x01, 0x80 | (MCP3008_CHANNEL << 4), 0x00};
        uint8_t rx[3];
        int bytes_read = spiTransfer(spi_channel, tx, rx);

        if (bytes_read < 0) {
            pigpio_error("spiTransfer() failed");
            gpioWrite(CE0, 1); // Deselect MCP3008
            sleep(100); // Sleep for 100ms
            continue;
        }

        // Parse ADC value
        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

        // Convert to percentage
        int water_level = (adc_value * 100) / 1023;

        // Print to stdout
        printf("Water Level: %.2f%%\n", water_level);

        // Log to JSON file
        data.water_level = water_level;
        log_reading(data);

        // Control LED based on water level
        if (water_level > LED_THRESHOLD_HIGH) {
            gpioWrite(LED_PIN, 1);
        } else if (water_level < LED_THRESHOLD_LOW) {
            gpioWrite(LED_PIN, 0);
        } else {
            gpioWrite(LED_PIN, 1);
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Handle SIGINT and SIGTERM
    signal(SIGINT, [](int) {
