    gpio_set_mode(MCP3008_SPI_CLK_PIN, PI_OUTPUT);
    gpio_set_mode(MCP3008_SPI_DOUT_PIN, PI_OUTPUT);
    gpio_set_mode(MCP3008_SPI_DIN_PIN, PI_INPUT);
