void cleanup_spi() {
    gpio_set_mode(MCP3008_SPI_CS_PIN, PI_INPUT);
    gpio_set_mode(MCP3008_SPI_CLK_PIN, PI_INPUT);
    gpio_set_mode(MCP3008_SPI_DOUT_PIN, PI_INPUT);
    gpio_set_mode(MCP3008_SPI_DIN_PIN, PI_INPUT);
}

uint16_t read_mcp3008(uint8_t channel) {
    gpio_set_level(MCP3008_SPI_CS_PIN, 0);
    gpio_write(MCP3008_SPI_CLK_PIN, 0);

    // Send out clock low
    gpio_write(MCP3008_SPI_CLK_PIN, 0);
    // Set chip select low
    gpio_write(MCP3008_SPI_CS_PIN, 0);
    // Shift out sample command
    gpio_write(MCP3008_SPI_DOUT_PIN, 1);
    gpio_write(MCP3008_SPI_CLK_PIN, 1);
    gpio_write(MCP3008_SPI_CLK_PIN, 0);

    // Shift out channel bits
    gpio_write(MCP3008_SPI_DOUT_PIN, (channel & 0x03) >> 0);
    gpio_write(MCP3008_SPI_CLK_PIN, 1);
    gpio_write(MCP3008_SPI_CLK_PIN, 0);

    gpio_write(MCP3008_SPI_DOUT_PIN, (channel & 0x03) >> 2);
    gpio_write(MCP3008_SPI_CLK_PIN, 1);
    gpio_write(MCP3008_SPI_CLK_PIN, 0);

