    uint8_t data_byte;
    gpio_read(MCP3008_SPI_DIN_PIN);
    gpio_read(MCP3008_SPI_DIN_PIN);
    data_byte = gpio_read(MCP3008_SPI_DIN_PIN);

    // Set chip select high
    gpio_write(MCP3008_SPI_CS_PIN, 1);

    return (data_byte << 8) | (gpio_read(MCP3008_SPI_DIN_PIN));
}

float convert_adc_to_lpm(uint16_t adc_value) {
    // AWM7300V datasheet provides conversion formula: LPM = (ADC_Value * 0.00492) - 0.127
    return (float)(adc_value * 0.00492) - 0.127;
}

