    strftime(data.timestamp, sizeof(data.timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

    fprintf(log_file, "%s,%.2f\n", data.timestamp, data.lpm);
    fflush(log_file);
}

int main() {
    init_pigpio();
    init_spi();

    log_data_flag = 0;
    struct sensor_data data;

    while (1) {
        if (gpio_event(MCP3008_SPI_CS_PIN, PI_FALLING, 0) && !log_data_flag) {
            log_data_flag = 1;
            data.lpm = convert_adc_to_lpm(read_mcp3008(MCP3008_CHANNEL));
            log_data(data);
            log_data_flag = 0;
        }

        pigpio_delay(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup_spi();
    cleanup_pigpio();
    fclose(log_file);

    return 0;
}

