#include <msmtp.h>

#define SPI_BUS 0
#define SPI_CS 0
#define ADC_CHANNEL 0
#define MIN_RAW_VALUE 300
#define MAX_RAW_VALUE 700
#define MOISTURE_THRESHOLD 30
#define LOGGING_FREQUENCY 60

int spi_fd;
int adc_channel;
int min_raw;
int max_raw;
int moisture_threshold;
int logging_frequency;
char *email_recipient;
char *msmtp_config;

void spi_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    spi_fd = gpioSPIOpen(SPI_BUS, SPI_CS, 50000000);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

uint16_t read_adc(void) {
    uint8_t cmd[3] = {0x01, 0x00, ADC_CHANNEL};
    uint8_t data[2];

    if (gpioSPITransmit(spi_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        fprintf(stderr, "SPI transmission error.\n");
        return -1;
    }

    if (gpioSPIReceive(spi_fd, data, sizeof(data)) != sizeof(data)) {
        fprintf(stderr, "SPI reception error.\n");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

float calculate_moisture(uint16_t raw_value) {
    return (float)(raw_value - min_raw) / (max_raw - min_raw) * 100;
}

void log_moisture(const char *timestamp) {
    FILE *log_file = fopen("plant_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    fprintf(log_file, "%s, %d\n", timestamp, (int)(calculate_moisture(read_adc())));
    fclose(log_file);
}

void send_email_alert(const char *moisture_percent) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Moisture level is low: %s%%\" | msmtp -t %s", moisture_percent, msmtp_config);
    FILE *pipe = popen(command, "w");
    if (!pipe) {
        fprintf(stderr, "Failed to execute email command.\n");
    } else {
        pclose(pipe);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    // ...

    spi_init();

    while (1) {
        uint16_t raw_value = read_adc();
        if (raw_value != -1) {
            float moisture_percent = calculate_moisture(raw_value);
            log_moisture(get_current_time_string());

            if (moisture_percent < moisture_threshold) {
                send_email_alert(moisture_percent);
            }
        }

        gpioWaitEvent(spi_fd, GPIO_EVENT_WRITE, -1);
        usleep(100000); // Delay to avoid overloading the SPI bus
    }

    // Handle SIGINT and SIGTERM for graceful shutdown
    // ...

    gpioTerminate();
    return 0;
}

