#include <signal.h>
#include <libgpiod.h>

#define DRY_ADC_VALUE 700
#define WET_ADC_VALUE 300
#define SPI_DEVICE "/dev/spidev0.0"
#define CHANNEL 0
#define MOISTURE_PERCENTAGE_MAX 100
#define MOISTURE_PERCENTAGE_MIN 0

int spi_fd;

void spi_cleanup(int signum) {
    gpiod_device_release(spi_fd);
    close(spi_fd);
    exit(signum);
}

int main() {
    struct gpiod_chip chip;
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    ret = gpiod_chip_open(&chip, "/dev/spidev0.0");
    if (ret < 0) {
        perror("Failed to open SPI chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    spi_fd = ret;

    ret = gpiod_chip_set_owner(&chip);
    if (ret < 0) {
        perror("Failed to set SPI chip owner");
        gpiod_chip_close(&chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    register_cleanup(spi_cleanup, &chip);

    while (1) {
        uint8_t cmd[3] = {MCP3008_SINGLE_ENDED, CHANNEL, 0};
        uint8_t data[3];

        ret = ioctl(spi_fd, SPI_IO, cmd);
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            break;
        }

        ret = read(spi_fd, data, 3);
        if (ret != 3) {
            perror("Failed to read from SPI device");
            break;
        }

        uint16_t adc_raw = (data[1] << 8) | data[2];
        float moisture_percentage = (adc_raw - DRY_ADC_VALUE) * (MOISTURE_PERCENTAGE_MAX - MOISTAGE_PERCENTAGE_MIN) / (512 - DRY_ADC_VALUE - WET_ADC_VALUE) + MOISTURE_PERCENTAGE_MIN;

        moisture_percentage = fmin(fmax(moisture_percentage, MOISTURE_PERCENTAGE_MIN), MOISTURE_PERCENTAGE_MAX);

        printf("Raw ADC: %d, Moisture (%): %.2f\n", adc_raw, moisture_percentage);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

