struct spi_config {
    int spi_fd;
    int chip_select;
    int speed_hz;
};

int spi_open(struct spi_config *cfg) {
    char path[256];
    snprintf(path, sizeof(path), "/dev/spidev%d.0", cfg->chip_select);
    cfg->spi_fd = open(path, O_RDWR);
    if (cfg->spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    return 0;
}

void spi_close(struct spi_config *cfg) {
    close(cfg->spi_fd);
}

int spi_transfer(struct spi_config *cfg, uint8_t tx_buf[], uint8_t rx_buf[], size_t len) {
    if (cfg->spi_fd < 0) {
        return -1;
    }
    if (write(cfg->spi_fd, tx_buf, len) != len) {
        perror("Failed to write to SPI device");
        return -1;
    }
    if (read(cfg->spi_fd, rx_buf, len) != len) {
        perror("Failed to read from SPI device");
        return -1;
    }
    return 0;
}

uint16_t read_adc(struct spi_config *cfg) {
    uint8_t tx_buf[2] = {0x01, SEN0193_CHANNEL};
    uint8_t rx_buf[3];
    int ret;

    ret = spi_transfer(cfg, tx_buf, rx_buf, sizeof(tx_buf));
    if (ret < 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    return (rx_buf[1] << 8) | rx_buf[2];
}

float adc_to_moisture(uint16_t adc_value) {
    return (float)adc_value * (800.0 / 1023) + 0;
}

int main() {
    struct spi_config cfg = {0};
    int ret;

    // Initialize GPIO for CE0
    ret = gpiod_in_init(&cfg.chip_select, 8);
    if (ret) {
        fprintf(stderr, "Failed to initialize CE0 GPIO\n");
        return -1;
    }
    gpiod_in_export(&cfg.chip_select, NULL);

    // Initialize SPI
    ret = spi_open(&cfg);
    if (ret) {
        fprintf(stderr, "Failed to open SPI device\n");
        return -1;
    }

    // Main loop
    while (1) {
        uint16_t adc_value = read_adc(&cfg);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        float moisture = adc_to_moisture(adc_value);
        time_t now = time(NULL);
        printf("Timestamp: %s, Moisture: %.2f%%\n", ctime(&now), moisture);

        sleep(5);
    }

    // Clean up
    spi_close(&cfg);
    gpiod_in_unexport(&cfg.chip_select);
    gpiod_in_free(&cfg.chip_select);

    return 0;
}

