#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define MCP3008_CHANNEL 0
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_CLOCK_HZ 1000000
#define MOISTURE_READ_INTERVAL 5

int spi_fd;

uint16_t read_mcp3008_channel(int fd, int channel) {
    uint8_t cmd[3] = {0x01, (SPI_MODE << 5) | 0, channel & 0x07};
    uint8_t result[2];

    if (write(fd, cmd, 3) != 3) {
        perror("SPI write");
        return -1;
    }

    if (read(fd, result, 2) != 2) {
        perror("SPI read");
        return -1;
    }

    return ((uint16_t)(result[1] << 8) | result[0]);
}

int main() {
    spi_fd = spidev_open("/dev/spidev0.0", SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    if (spidev_lrcw(spi_fd, SPI_BITS_PER_WORD) != SPI_BITS_PER_WORD) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        return 1;
    }

    if (spidev_xfer(spi_fd, NULL, NULL, 0, 1000000) != 0) {
        fprintf(stderr, "Failed to configure SPI clock\n");
        close(spi_fd);
        return 1;
    }

    while (1) {
        uint16_t adc_value = read_mcp3008_channel(spi_fd, MCP3008_CHANNEL);
        if (adc_value == -1) {
            break;
        }

        double moisture_percentage = (double)adc_value * 50 / 1023;
        moisture_percentage = fmin(100.0, fmax(0.0, moisture_percentage));
        printf("Soil moisture: %.2f%%\n", moisture_percentage);

        sleep(MOISTURE_READ_INTERVAL);
    }

    spidev_close(spi_fd);
    return 0;
}

void sigint_handler(int signum) {
    spidev_close(spi_fd);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Rest of the main function remains the same
}

