    }

    if (i2c_get_device(&i2c_dev) < 0) {
        fprintf(stderr, "Failed to get I2C device information\n");
        i2c_close(i2c_handle);
        return 1;
    }

    if (i2c_xfer(i2c_handle, &i2c_dev, NULL, NULL, 0, SPI_REG_PART_ID, NULL, 1, 0) != 1) {
        fprintf(stderr, "Failed to read Part ID register\n");
        i2c_close(i2c_handle);
        return 1;
    }

    if (i2c_xfer(i2c_handle, &i2c_dev, NULL, NULL, 0, SPI_REG_MODE_CONFIG, &ret, 1, 0) != 1) {
        fprintf(stderr, "Failed to read MODE_CONFIG register\n");
        i2c_close(i2c_handle);
        return 1;
    }
    ret |= 0x40;
    if (i2c_xfer(i2c_handle, &i2c_dev, NULL, &ret, 1, SPI_REG_MODE_CONFIG, NULL, 0, 0) != 1) {
        fprintf(stderr, "Failed to write to MODE_CONFIG register\n");
        i2c_close(i2c_handle);
        return 1;
    }

    if (i2c_xfer(i2c_handle, &i2c_dev, NULL, NULL, 0, SPI_REG_SPO2_CONFIG, &ret, 1, 0) != 1) {
        fprintf(stderr, "Failed to read SPO2_CONFIG register\n");
        i2c_close(i2c_handle);
        return 1;
    }
    ret = 0x27;
    if (i2c_xfer(i2c_handle, &i2c_dev, NULL, &ret, 1, SPI_REG_SPO2_CONFIG, NULL, 0, 0) != 1) {
        fprintf(stderr, "Failed to write to SPO2_CONFIG register\n");
        i2c_close(i2c_handle);
        return 1;
    }

    if (i2c_xfer(i2c_handle, &i2c_dev, NULL, NULL, 0, SPI_REG_LED1_PA, &ret, 1, 0) != 1) {
        fprintf(stderr, "Failed to read LED1_PA register\n");
        i2c_close(i2c_handle);
        return 1;
    }
    ret = 0x24;
    if (i2c_xfer(i2c_handle, &i2c_dev, NULL, &ret, 1, SPI_REG_LED1_PA, NULL, 0, 0) != 1) {
        fprintf(stderr, "Failed to write to LED1_PA register\n");
        i2c_close(i2c_handle);
        return 1;
    }

    if (i2c_xfer(i2c_handle, &i2c_dev, NULL, NULL, 0, SPI_REG_LED2_PA, &ret, 1, 0) != 1) {
        fprintf(stderr, "Failed to read LED2_PA register\n");
        i2c_close(i2c_handle);
        return 1;
    }
    ret = 0x24;
    if (i2c_xfer(i2c_handle, &i2c_dev, NULL, &ret, 1, SPI_REG_LED2_PA, NULL, 0, 0) != 1) {
        fprintf(stderr, "Failed to write to LED2_PA register\n");
        i2c_close(i2c_handle);
        return 1;
    }

    pigpio_initialise();
    pigpio_initialized = 1;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    now = time(NULL);

    while (1) {
        gpio defaultOut = 0;
        int bytes_read = 0;

        if (i2c_xfer(i2c_handle, &i2c_dev, NULL, buffer, MAX_BUFFER_SIZE, SPI_REG_FIFO_DATA, &bytes_read, MAX_BUFFER_SIZE, 0) != bytes_read) {
            fprintf(stderr, "Failed to read FIFO data register\n");
            break;
        }

        // Process the FIFO data to get red_ratio and ir_ratio
        // ...

        heart_rate = peak_detection_on_ir_signal(buffer);

        if (red_ratio < 0.95 * 512 || heart_rate > 100) {
            FILE *log_file = fopen("health_log.txt", "a");
            if (log_file != NULL) {
                now = time(NULL);
                fprintf(log_file, "%ld\n", now);
                fclose(log_file);
            }
        }

        gpioSetMode(0, PI_OUTPUT);
        gpioOutput(0, 0);
        delay(1000);
    }

    pigpio_stop();
    i2c_close(i2c_handle);

    return 0;
}

