#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_SPI_MODE 0
#define MCP3008_CLK_DIV 1
#define MCP3008_VREF 3.3
#define SPI_DEVICE 0
#define CE0_GPIO 13
#define CHANNELS 3

static const int spi_mode = MCP3008_SPI_MODE;
static const int clk_div = MCP3008_CLK_DIV;
static const float vref = MCP3008_VREF;

static FILE *csv_file = NULL;

void init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(CE0_GPIO, PI_OUTPUT);
}

void cleanup_pigpio(void) {
    gpioTerminate();
}

uint16_t read_mcp3008(int channel) {
    uint8_t tx_buf[3] = {0x01, (channel << 4) | 0x00, 0x00};
    uint8_t rx_buf[3];
    int ret;

    ret = spiTransfer(SPI_DEVICE, tx_buf, 3, rx_buf, 3, 1000);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint16_t result = (rx_buf[1] << 8) | rx_buf[2];
    return result;
}

void log_to_csv(int channel, float voltage) {
    static int header_written = 0;

    if (!header_written) {
        csv_file = fopen("analog_log.csv", "w");
        if (!csv_file) {
            fprintf(stderr, "Failed to open CSV file\n");
            exit(EXIT_FAILURE);
        }
        fprintf(csv_file, "Timestamp,Channel,Voltage\n");
        header_written = 1;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%FT%T%z", gmtime(&now));

    fprintf(csv_file, "%s,%d,%f\n", timestamp, channel, voltage);
    fflush(csv_file);
}

int main(void) {
    init_pigpio();
    gpioSetMode(CE0_GPIO, PI_OUTPUT);
    gpioWrite(CE0_GPIO, 0);

    spiOpen(SPI_DEVICE, 1000000);

    while (1) {
        for (int i = 0; i < CHANNELS; ++i) {
            uint16_t reading = read_mcp3008(i);
            if (reading >= 0) {
                float voltage = (reading * vref) / 1023.0;
                log_to_csv(i, voltage);
            }
        }
        sleep(0.5);
    }

    cleanup_pigpio();
    spiClose(SPI_DEVICE);
    fclose(csv_file);

    return 0;
}

