#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GAS_SENSOR_CHANNEL 0
#define BUZZER_GPIO 24
#define CE0_GPIO 8
#define THRESHOLD 500

static volatile int running = 1;
static gpio spiBus = -1;
static gpio ce0 = -1;
static gpio buzzer = -1;

void sigint_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    spiBus = gpioInitialiseSPI(32000);
    if (spiBus < 0) {
        fprintf(stderr, "Failed to initialize SPI bus.\n");
        gpioTerminate();
        return 1;
    }

    ce0 = gpioInitialise(CE0_GPIO);
    if (ce0 < 0) {
        fprintf(stderr, "Failed to initialize CE0 GPIO.\n");
        gpioTerminateSPI(spiBus);
        gpioTerminate();
        return 1;
    }

    buzzer = gpioInitialise(BUZZER_GPIO);
    if (buzzer < 0) {
        fprintf(stderr, "Failed to initialize buzzer GPIO.\n");
        gpioTerminateSPI(spiBus);
        gpioTerminate(ce0);
        return 1;
    }

    gpioSetMode(ce0, PI_OUTPUT);
    gpioSetMode(buzzer, PI_OUTPUT);

    while (running) {
        int adcValue = readADC(GAS_SENSOR_CHANNEL);

        if (adcValue < THRESHOLD) {
            gpioWrite(buzzer, 0);
        } else {
            gpioWrite(buzzer, 1);
        }

        usleep(500000);
    }

    gpioTerminateSPI(spiBus);
    gpioTerminate(ce0);
    gpioTerminate(buzzer);
    gpioTerminate();

    return 0;
}

int readADC(int channel) {
    int spiData = 0;
    int spiBuffer[3];

    if (gpioSPIRX(spiBus, spiBuffer, 3) != 3) {
