#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>
#include <spidev.h>

#define MCP3008_SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "soil_moisture_log.csv"
#define SENSOR_COUNT 3
#define CHANNEL 0
#define LOG_INTERVAL 5

struct sensor_data {
    int adc_value;
} sensors[SENSOR_COUNT];

int spi_open(const char *dev) {
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_FRAMES, 1) < 0) {
        close(fd);
        perror("Failed to set SPI frame size");
        return -1;
    }
    if (ioctl(fd, SPI_IOC_RD_FRAMES, &fd) < 0) {
        close(fd);
        perror("Failed to get SPI frame size");
        return -1;
    }
    return fd;
}

void spi_close(int fd) {
    close(fd);
}

int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    if (write(fd, tx_buf, len) != len) {
        perror("Failed to write to SPI device");
        return -1;
    }
    if (read(fd, rx_buf, len) != len) {
        perror("Failed to read from SPI device");
        return -1;
    }
    return 0;
}

int gpiod_init(int chip_cs[], int pin_num[], int count) {
    struct gpiod_chip *chip;
    struct gpiod_chip_line *lines[count];

    chip = gpiod_chip_open(0, "rpi");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    for (int i = 0; i < count; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_num[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", pin_num[i]);
            gpiod_chip_close(chip);
            return -1;
        }
        gpiod_line_export(lines[i], "rpi/cs%d", i);
    }

    gpiod_chip_close(chip);
    return 0;
}

void gpiod_cleanup(int chip_cs[], int pin_num[], int count) {
    for (int i = 0; i < count; i++) {
        gpiod_line_unset(chip_cs[i]);
    }
}

int main() {
    int spi_fd = spi_open(MCP3008_SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    int chip_cs[] = {8, 7, 25};
    int pin_num[] = {chip_cs, chip_cs + 1, chip_cs + 2};
    if (gpiod_init(chip_cs, pin_num, SENSOR_COUNT) < 0) {
        spi_close(spi_fd);
        return EXIT_FAILURE;
    }

    struct spidev_xfer xfer;
    uint8_t tx_buf[3] = {0x01, (0x08 | CHANNEL) << 4, 0x00};
    uint8_t rx_buf[3];

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spi_close(spi_fd);
        gpiod_cleanup(chip_cs, pin_num, SENSOR_COUNT);
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Failed to seek to beginning of log file\n");
        fclose(log_file);
        spi_close(spi_fd);
        gpiod_cleanup(chip_cs, pin_num, SENSOR_COUNT);
        return EXIT_FAILURE;
    }

    if (feof(log_file)) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
        fflush(log_file);
    }

    while (1) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            xfer.tx_buf = tx_buf;
            xfer.rx_buf = rx_buf;
            xfer.len = sizeof(rx_buf);

            if (spi_transfer(spi_fd, tx_buf, rx_buf, xfer.len) < 0) {
                fprintf(stderr, "Failed to perform SPI transfer\n");
                fclose(log_file);
                spi_close(spi_fd);
                gpiod_cleanup(chip_cs, pin_num, SENSOR_COUNT);
                return EXIT_FAILURE;
            }

            sensors[i].adc_value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];

            if (sensors[i].adc_value == -1) {
                fprintf(stderr, "Failed to read sensor %d\n", i + 1);
                sensors[i].adc_value = -1;
            }
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%d,%d,%d\n", (long)now, sensors[0].adc_value, sensors[1].adc_value, sensors[2].adc_value);
        fflush(log_file);

        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    gpiod_cleanup(chip_cs, pin_num, SENSOR_COUNT);
    spi_close(spi_fd);

    return EXIT_SUCCESS;
}

