#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

int threshold = DEFAULT_THRESHOLD;
int duration = DEFAULT_DURATION;
int sleep_interval = DEFAULT_SLEEP_INTERVAL;
int retry_count = 0;
int pump_state = 0;

void sigint_handler(int signum) {
    pump_state = 0;
    spiClose(SPI_DEVICE);
    pigpio_terminate(NULL);
    exit(0);
}

uint16_t read_soil_moisture(mcp3008_context *ctx) {
    uint16_t value = 0;
    for (int i = 0; i < 3; ++i) {
        if (mcp_read(ctx, SOIL_MOISTURE_CH, &value) == MCP_SUCCESS) {
            return value;
        }
        if (++retry_count >= 3) {
            fprintf(stderr, "Error reading soil moisture sensor, skipping irrigation cycle.\n");
            retry_count = 0;
            return 0;
        }
        _delay_ms(50);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    pigpio_init();
    spi_open(SPI_DEVICE, CE0_GPIO, SPI_CLK_DIV);

    if (argc > 1) {
        if (sscanf(argv[1], "%d", &threshold) != 1) {
            fprintf(stderr, "Invalid threshold value.\n");
            return 1;
        }
    }
    if (argc > 2) {
        if (sscanf(argv[2], "%d", &duration) != 1) {
            fprintf(stderr, "Invalid duration value.\n");
            return 1;
        }
    }
    if (argc > 3) {
        if (sscanf(argv[3], "%d", &sleep_interval) != 1) {
            fprintf(stderr, "Invalid sleep interval value.\n");
            return 1;
        }
    }

    mcp3008_context ctx;
    mcp3008_init(&ctx, SPI_DEVICE);

    while (1) {
        uint16_t moisture_value = read_soil_moisture(&ctx);
        double moisture_percent = map(moisture_value, 0, 1023, 0, 100);

        if (moisture_percent < threshold) {
            pump_state = 1;
            gpioSetMode(PUMP_GPIO, PI_OUTPUT);
            gpioWrite(PUMP_GPIO, 1);
            _delay_ms(duration * 1000);
            gpioWrite(PUMP_GPIO, 0);
            pump_state = 0;
        }

        FILE *log_file = fopen("irrigation.log", "a");
        if (!log_file) {
            perror("Error opening log file");
            continue;
        }
        fprintf(log_file, "%lu: Moisture %d%%, Pump %s\n", time(NULL), (int)moisture_percent, pump_state ? "ON" : "OFF");
        fclose(log_file);

        _delay_ms(sleep_interval * 1000);
    }

    spiClose(SPI_DEVICE);
    pigpio_terminate(NULL);
    return 0;
}

double map(int x, int x_min, int x_max, int y_min, int y_max) {
    return (double)(y_max - y_min) * (x - x_min) / (x_max - x_min) + y_min;
}

