#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define MCP3008_SPI_DEVICE 0
#define CE0_GPIO 8
#define CLK_GPIO 11
#define MOSI_GPIO 10
#define MISO_GPIO 9
#define SAMPLE_INTERVAL_MS 10
#define PEAK_THRESHOLD_MARGIN 0.2

int spi_fd;
int gpio_init_status = 0;
int spi_init_status = 0;

void spi_init() {
    spi_fd = spiOpen(MCP3008_SPI_DEVICE, 1000000);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device\n");
        exit(EXIT_FAILURE);
    }
    spi_init_status = 1;
}

void gpio_init() {
    gpioInitialise();
    gpioSetMode(CE0_GPIO, PI_OUTPUT);
    gpioSetMode(CLK_GPIO, PI_OUTPUT);
    gpioSetMode(MOSI_GPIO, PI_OUTPUT);
    gpioSetMode(MISO_GPIO, PI_INPUT);
    gpio_init_status = 1;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_init();
    spi_init();

    if (!gpio_init_status || !spi_init_status) {
        fprintf(stderr, "Failed to initialize GPIO or SPI\n");
        return EXIT_FAILURE;
    }

    double ema = 0.0;
    double peak_threshold = 0.0;
    FILE *log_file = fopen("/var/log/sound_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        gpioSetOutput(CE0_GPIO, 1);
        spiTransfer(spi_fd, 0x01); // Start conversion
        spiTransfer(spi_fd, 0x00); // Read data

        uint16_t adc_value = (spiGetBits(spi_fd, 16) << 8) | spiGetBits(spi_fd, 8);
        double raw_value = (double)adc_value / 1024.0 * 3.3;

        if (raw_value > peak_threshold) {
            double timestamp = time(NULL);
            struct tm *now = localtime(&timestamp);
            char timestamp_str[20];
            strftime(timestamp_str, sizeof(timestamp_str), "%FT%T", now);

            fprintf(log_file, "%s, Peak value: %.2f\n", timestamp_str, raw_value);
        }

        ema = raw_value * PEAK_THRESHOLD_MARGIN + ema * (1 - PEAK_THRESHOLD_MARGIN);
        peak_threshold = ema;

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpioClose(CE0_GPIO);
    spiClose(spi_fd);
    fclose(log_file);

    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Shutting down...\n");
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

