#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define PCF8591_ADDR 0x48
#define SAMPLE_DELAY_MS 100000 // 100 ms in microseconds

int main() {
    int file;
    int r;
    struct i2c_rdwr_ioctl_data rdwr_data;
    struct i2c_msg messages[2];
    gpiod_chip chip;
    gpiod_chip_register_error_handler(NULL);

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus\n");
        close(file);
        return 1;
    }

    messages[0].addr = PCF8591_ADDR;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &rdwr_data.data[0];

    messages[1].addr = PCF8591_ADDR;
    messages[1].flags = 0;
    messages[1].len = 1;
    messages[1].buf = &rdwr_data.data[1];

    rdwr_data.msgs = messages;
    rdwr_data.nmsgs = 2;

    // Dummy read to ensure ADC is ready
    if (ioctl(file, I2C_RDWR, &rdwr_data) < 0) {
        fprintf(stderr, "Failed to perform dummy read\n");
        close(file);
        return 1;
    }

    // Configure control byte for single-ended mode on channel 0
    rdwr_data.data[0] = 0x40 | (0 << 5) | (0 << 4); // 00100000b, single-ended mode, AIN0, analog output disabled
    if (ioctl(file, I2C_RDWR, &rdwr_data) < 0) {
        fprintf(stderr, "Failed to configure control byte\n");
        close(file);
        return 1;
    }

    // Initialize GPIO (not used in this example, but required for libgpiod)
    r = gpiod_chip_new(&chip, "gpio");
    if (!r) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        close(file);
        return 1;
    }

    // Register signal callback (not used in this example, but required for libgpiod)
    // gpiod_chip_register_signal(&chip, ...);

    while (1) {
        // Perform a read
        rdwr_data.data[0] = 0xE0 | (0 << 5) | (0 << 4); // 111000000b, read data from AIN0
        if (ioctl(file, I2C_RDWR, &rdwr_data) < 0) {
            fprintf(stderr, "Failed to read from PCF8591\n");
            break;
        }

        uint8_t sample = rdwr_data.data[1];
        printf("Sample value: %d\n", sample);

        usleep(SAMPLE_DELAY_MS);
    }

    gpiod_chip_put(chip);
    close(file);
    return 0;
}

