#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pigpio.h>
#include <syslog.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>

#define BUFFER_SIZE 10
#define THRESHOLD 500
#define SAMPLE_RATE 1
#define I2C_ADDR 0x48
#define AIN0 0

int16_t buffer[BUFFER_SIZE];
int buffer_index = 0;
float rolling_average = 0;
bool shutdown_signal = false;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_INFO, format, args);
    va_end(args);
}

int init_pigpio() {
    if (pigpio_initialise() < 0) {
        log_message("Failed to initialize pigpio library. Exiting.\n");
        return -1;
    }
    return 0;
}

int init_i2c() {
    if (gpioInitialise() < 0) {
        log_message("Failed to initialize GPIO. Exiting.\n");
        return -1;
    }

    if (pigpio_i2c_open(0, I2C_ADDR) < 0) {
        log_message("Failed to open I2C bus. Continuing...\n");
        return -1;
    }

    return 0;
}

int read_adc(uint8_t *data) {
    if (pigpio_i2c_write(0, I2C_ADDR, (uint8_t *)"START", 4) < 0) {
        log_message("Failed to send start bit on I2C. Skipping sample...\n");
        return -1;
    }

    if (pigpio_i2c_read(0, I2C_ADDR, (uint8_t *)data, 2) < 0) {
        log_message("Failed to read from I2C. Skipping sample...\n");
        return -1;
    }

    return 0;
}

float voltage_to_gauss(int16_t raw_voltage) {
    return (float)raw_voltage * 3.3 / 1000 * 1.4;
}

void update_buffer(int16_t raw_voltage) {
    if (raw_voltage < 0 || raw_voltage > 65535) {
        log_message("Invalid voltage reading. Skipping sample...\n");
        return;
    }

    buffer[buffer_index] = raw_voltage;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    rolling_average += voltage_to_gauss(raw_voltage);

    if (buffer_index > 0) {
        rolling_average -= voltage_to_gauss(buffer[buffer_index - 1]);
    }

    if (rolling_average / BUFFER_SIZE > THRESHOLD) {
        shutdown_signal = true;
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, [](int) {
        log_message("Received SIGINT. Stopping...\n");
        pigpio_stop();
        closelog();
        exit(0);
    });

    signal(SIGTERM, [](int) {
        log_message("Received SIGTERM. Stopping...\n");
        pigpio_stop();
