            gpioWrite(PUMP_GPIO, 1); // Pump on

            sleep(PUMP_ON_TIME / 1000); // Run pump for 10 seconds
            gpioWrite(PUMP_GPIO, 0); // Pump off

            fprintf(log_file, "%ld: Moisture level %d, pump deactivated\n", time(NULL), adc_value);
        }

        fprintf(log_file, "%ld: Moisture level %d\n", time(NULL), adc_value);
        sleep(WATERING_INTERVAL / 1000); // Read every 60 seconds
    }

    gpioFree();
    fclose(log_file);
    return EXIT_SUCCESS;
}

