#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>

#define MCP3008_CH 0
#define ADC_FS 1023
#define RAIN_INTENSITY_SCALE 10

void rain_intensity_to_level(uint16_t adc_value, int *level) {
    *level = (int) ((adc_value / (double) ADC_FS) * RAIN_INTENSITY_SCALE);
}

int main() {
    struct timespec ts;
    gpioInitialise();
    if (piGetMode() != GPIO_CAREFUL) {
        fprintf(stderr, "Error: Careful mode not enabled.\n");
        return 1;
    }

    spiMode = 0;
    spiClockDiv = 1;
    spiChipSelect = 0;
    spiDevice = 0;
    spiBus = 0;

    if (spiOpen(SPI_PORT_A, 1000000, spiMode, spiClockDiv, spiChipSelect, spiDevice, spiBus) < 0) {
        fprintf(stderr, "Error: Failed to open SPI.\n");
        gpioTerminate();
        return 1;
    }

    int spi_fd = spiGetFd();
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint16_t adc_value;

        if (spiXfer(spi_fd, &adc_value, 2) < 0) {
            fprintf(stderr, "Error: SPI transfer failed. Retrying...\n");
            continue;
        }

        int level;
        rain_intensity_to_level(adc_value, &level);

        char timestamp[24];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        printf("%s: ADC value = %d, Rainfall intensity level = %d\n", timestamp, adc_value, level);

        if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
            fprintf(stderr, "Error: Failed to set SIGINT handler.\n");
            break;
        }
    }

    spiClose(spi_fd);
    gpioTerminate();
    return 0;
}

