#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define CE_PIN 8
#define PWM_PIN 18

volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

int main() {
    struct spi_device spi;
    int spi_fd;
    int adc_value;
    gpioInitialise();

    if (init_pigpio() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_fd = spiOpen(SPI_CHANNEL, 1000000);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    spi_config(spi_fd, SPI_MODE0);
    spi_open(spi_fd, CE_PIN, SPI_MODE0);

    if (set_pwm_dutycycle(PWM_PIN, 1000) < 0) {
        fprintf(stderr, "PWM initialization failed\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        spi_transfer(spi_fd, (uint8_t[]){0x01}, (uint8_t[]){0x00}, 1);
        if (spi_transfer_result(spi_fd) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        adc_value = (spi_data[0] << 8) | spi_data[1];
        set_pwm_dutycycle(PWM_PIN, adc_value);

        printf("ADC Value: %d, PWM Duty Cycle: %d\n", adc_value, get_pwm_dutycycle(PWM_PIN));
        usleep(100000);
    }

    spiClose(spi_fd);
    gpioTerminate();
    return 0;
}

