#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <pigio.h>
#include <ads1x15.h>

#define LED_GPIO 17
#define I2C_ADDR 0x48
#define AIN_CHANNEL 0
#define GAIN 4.096
#define THRESHOLD_DEFAULT 100.0
#define READ_INTERVAL_MS 100
#define LED_ON_MS 50
#define LED_OFF_MS 50
#define LED_DURATION_MS 1000

int threshold = THRESHOLD_DEFAULT;
int led_state = 0;
int led_timer = 0;

void blink_led(int gpio, int state) {
    if (state) {
        gpioSetMode(gpio, PI_OUTPUT);
        gpioWrite(gpio, 1);
        usleep(LED_ON_MS * 1000);
        gpioWrite(gpio, 0);
        usleep(LED_OFF_MS * 1000);
    }
}

double read_adc(int fd) {
    struct ads1x15_config config;
    struct ads1x15_channel channel;
    int ret;

    memset(&config, 0, sizeof(config));
    config.i2c_addr = I2C_ADDR;
    config.bus_num = 1;
    config.res = ADS1115_RES_12BIT;
    config.pga = (uint8_t)GAIN;
    config.mode = ADS1115_MODE_SINGLE_SHOT;

    memset(&channel, 0, sizeof(channel));
    channel.channel = AIN_CHANNEL;

    ret = ads1x15_configure(fd, &config);
    if (ret < 0) {
        fprintf(stderr, "Error configuring ADS1115: %d\n", ret);
        return -1;
    }

    ret = ads1x15_read(fd, &channel, NULL);
    if (ret < 0) {
        fprintf(stderr, "Error reading from ADS1115: %d\n", ret);
        return -1;
    }

    return (double)channel.x * (5.0 / 32768.0);
}

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd;
    int ret;

    gpio_fd = pigpio(0);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", gpio_init_error());
        return 1;
    }

    i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus 1: %d\n", i2c_open_error());
        gpio_stop();
        return 1;
    }

    if (i2c_write(i2c_fd, 0x2C, NULL, 1) < 0) {
        fprintf(stderr, "Error writing to ADS1115 register: %d\n", i2c_error());
        i2c_close(i2c_fd);
        gpio_stop();
        return 1;
    }

    if (i2c_read(i2c_fd, 0x00, NULL, 6) < 0) {
        fprintf(stderr, "Error reading from ADS1115 register: %d\n", i2c_error());
        i2c_close(i2c_fd);
        gpio_stop();
        return 1;
    }

    while (1) {
        double adc_value = read_adc(i2c_fd);
        if (adc_value > -1) {
            int gauss = (int)(adc_value / 0.001);
            printf("Magnetic field strength: %.0f Gauss\n", gauss);

            if (gauss > threshold) {
                blink_led(LED_GPIO, 1);
                led_timer = LED_DURATION_MS;
            } else {
                blink_led(LED_GPIO, 0);
                led_timer -= 1;
                if (led_timer <= 0) {
                    led_timer = 0;
                }
            }
        }

        usleep(READ_INTERVAL_MS * 1000);
    }

    i2c_close(i2c_fd);
    gpio_stop();
    return 0;
}

