#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <pigio.h>
#include <mqtt.h>

#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MOISTURE_HYSTERESIS 5
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define SPI_CLOCK 1000000
#define CHECK_INTERVAL 60

static pigio *gpio;
static spi_device *spi;
mqtt_client_handle_t client;

void sigint_handler(int signum) {
    (void)signum;
    cleanup_resources();
    exit(0);
}

void cleanup_resources() {
    mqtt_disconnect(client);
    pigpio_terminate(gpio);
    syslog(LOG_INFO, "Pigpio and MQTT clients terminated.");
    exit(0);
}

void sensor_read(uint16_t *moisture) {
    gpio_set_function(8, PI_OUTPUT);
    gpio_write(8, 0); // Pull CE0 low to select MCP3008
    spi_transfer(spi, 0x01); // Start conversion
    spi_transfer(spi, 0x00); // Read 10-bit result
    *moisture = (spi_transfer(spi, 0x00) << 8) | spi_transfer(spi, 0x00);
    gpio_write(8, 1); // Pull CE0 high to deselect
    if (*moisture < 1 || *moisture > 1023) {
        syslog(LOG_ERR, "Invalid moisture reading, likely sensor absent.");
    }
}

void control_pump(uint16_t moisture) {
    if (moisture < MOISTURE_THRESHOLD_LOW && moisture > MOISTURE_THRESHOLD_LOW - MOISTURE_HYSTERESIS) {
        gpio_write(17, 1); // Activate relay
    } else if (moisture > MOISTURE_THRESHOLD_HIGH + MOISTURE_HYSTERESIS) {
        gpio_write(17, 0); // Deactivate relay
    }
}

void mqtt_callback(mqtt_message_t *msg, void *arg) {
    if (strcmp(msg->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
        if (strcmp(msg->payload, "pump_on") == 0) {
            gpio_write(17, 1);
        } else if (strcmp(msg->payload, "pump_off") == 0) {
            gpio_write(17, 0);
        }
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    gpio = pigio_init();
    if (!gpio) {
        syslog(LOG_ERR, "Failed to initialize pigpio.");
        return 1;
    }

    spi = spi_open(0, SPI_MODE0, SPI_BITS_8, SPI_CLOCK_HZ(SPI_CLOCK));
    if (!spi) {
        pigpio_terminate(gpio);
        syslog(LOG_ERR, "Failed to open SPI device.");
        return 1;
    }

    client = mqtt_client_init();
    if (!client) {
        spi_close(spi);
        pigpio_terminate(gpio);
        syslog(LOG_ERR, "Failed to initialize MQTT client.");
        return 1;
    }

    mqtt_client_set_callback(client, mqtt_callback, NULL);
    mqtt_client_connect(client, "mqtt_broker_address", "mqtt_broker_port", "client_id");
    mqtt_client_subscribe(client, MQTT_TOPIC_SOIL_MOISTURE, 0);

    while (1) {
        uint16_t moisture;
        sensor_read(&moisture);
        control_pump(moisture);
        mqtt_client_publish(client, MQTT_TOPIC_SOIL_MOISTURE, NULL, &moisture, strlen("0") + 1, 0);
        usleep(CHECK_INTERVAL * 1000000);
    }

    mqtt_client_disconnect(client);
    spi_close(spi);
    pigpio_terminate(gpio);

    return 0;
}

