#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <signal.h>

#define MCP3008_CMD 0x01
#define MCP3008_CONFIG 0x02
#define MCP3008_CHANNEL 0x00
#define VREF 3.3

static int spi_fd = -1;

void sigint_handler(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    exit(0);
}

int init_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_xfer xfer;
    xfer.tx_buf = (unsigned char[]){MCP3008_CMD, MCP3008_CONFIG | (0 << 4), MCP3008_CHANNEL};
    xfer.rx_buf = (unsigned char[]){0};
    xfer.len = 3;
    xfer.delay_usecs = 0;
    xfer.speed_hz = 1000000;
    xfer.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_XFER, &xfer) == -1) {
        perror("Failed to perform SPI transfer");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    if (init_spi() != 0) {
        return 1;
    }

    while (1) {
        struct spi_xfer xfer;
        xfer.tx_buf = (unsigned char[]){MCP3008_CMD, MCP3008_CONFIG | (0 << 4), MCP3008_CHANNEL};
        xfer.rx_buf = (unsigned char[]){0};
        xfer.len = 3;
        xfer.delay_usecs = 0;
        xfer.speed_hz = 1000000;
        xfer.bits_per_word = 8;

        if (ioctl(spi_fd, SPI_XFER, &xfer) == -1) {
            perror("Failed to perform SPI transfer");
            break;
        }

        uint16_t raw_value = ((xfer.rx_buf[0] & 0x03) << 8) | xfer.rx_buf[1];
        double voltage = raw_value * VREF / 1024.0;

        printf("Raw value: %d, Voltage: %.3f V\n", raw_value, voltage);
        usleep(500000);
    }

    close(spi_fd);
    return 0;
}

