#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define VREF 3.3
#define RESOLUTION 1024
#define SPI_PORT 0
#define CE0 25
#define CHANNELS 3

float adc_to_voltage(int adc_value) {
    return (adc_value * VREF) / RESOLUTION;
}

void sigint_handler(int signum) {
    gpioTerminate();
    printf("\nReceived SIGINT, cleaning up...\n");
    exit(0);
}

void sigterm_handler(int signum) {
    gpioTerminate();
    printf("\nReceived SIGTERM, cleaning up...\n");
    exit(0);
}

int main() {
    struct sigaction sa;
    gpioInitialise();
    if (-1 == gpioInitialise()) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    spiMode = 0;
    spiSpeedMode = spi_mode_full;
    gpioSetMode(CE0, PI_OUTPUT);
    gpioWrite(CE0, 0);

    spiDevice = spiOpen(SPI_PORT, 1000000);
    if (!spiDevice) {
        fprintf(stderr, "Failed to open SPI device.\n");
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen("sensor_data.csv", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open file for writing.\n");
        spiClose(spiDevice);
        gpioTerminate();
        return 1;
    }

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        for (int i = 0; i < CHANNELS; i++) {
            int channel = i;
            gpioWrite(CE0, 1);
            spiTransfer(spiDevice, &channel, 1);
            spiTransfer(spiDevice, NULL, 1);

            int adc_value = spiRead(spiDevice, NULL, 2);
            gpioWrite(CE0, 0);

            if (adc_value < 0) {
                fprintf(stderr, "SPI transfer failed.\n");
                spiClose(spiDevice);
                fclose(fp);
                gpioTerminate();
                return 1;
            }

            float voltage = adc_to_voltage(adc_value);
            time_t t = time(NULL);
            fprintf(fp, "%ld,%f\n", t, voltage);
        }
        sleep(5);
    }

    spiClose(spiDevice);
    fclose(fp);
    gpioTerminate();

    return 0;
}

