#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>
#include <pigio.h>
#include <spidev.h>

#define MOTOR_PINS {17, 27}
#define ADC_CHANNEL 0
#define NOISE_THRESHOLD 500
#define PWM_FREQ 100
#define SAMPLE_INTERVAL 10000 // 10 ms

int main() {
    int fd_spidev = -1;
    struct spi_device spidev;
    int fd_gpio = -1;
    int ret;
    double pwm_duty_cycle;
    int adc_value;
    time_t now;

    // Initialize pigpio library
    if ((ret = piGpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", strerror(ret));
        return 1;
    }

    // Initialize SPI device
    spidev.fd = open("/dev/spidev0.0", O_RDWR);
    if (spidev.fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        piGpioTerminate();
        return 1;
    }
    spidev.cs_change = 0;
    spidev.bits_per_word = 10;
    spidev.speed_hz = 1000000;
    if (ioctl(spidev.fd, SPI_WRITE_THEN_READ, NULL) < 0) {
        fprintf(stderr, "SPI configuration failed: %s\n", strerror(errno));
        close(spidev.fd);
        piGpioTerminate();
        return 1;
    }
    fd_spidev = spidev.fd;

    // Initialize GPIO pins for motors
    fd_gpio = piGpioOpen(NULL);
    for (int i = 0; i < 2; ++i) {
        if (piGpioSetMode(fd_gpio, MOTOR_PINS[i], piGPIO_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode for motor %d\n", i + 1);
            close(fd_spidev);
            piGpioClose(fd_gpio);
            piGpioTerminate();
            return 1;
        }
        piGpioSetPWMfrequency(fd_gpio, MOTOR_PINS[i], PWM_FREQ);
        piGpioSetPWMdutycycle(fd_gpio, MOTOR_PINS[i], 0);
    }

    // Open log file
    FILE *log_file = fopen("vibration_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(fd_spidev);
        piGpioClose(fd_gpio);
        piGpioTerminate();
        return 1;
    }

    while (1) {
        now = time(NULL);
        pwm_duty_cycle = (double)adc_value / NOISE_THRESHOLD * 100;

        if ((ret = spi_transfer(fd_spidev, &ADC_CHANNEL)) < 0) {
            fprintf(stderr, "ADC read failed: %s\n", strerror(errno));
            continue;
        }
        adc_value = (int)(ret[0] & 0xFF);

        if (adc_value > NOISE_THRESHOLD) {
            for (int i = 0; i < 2; ++i) {
                piGpioSetPWMdutycycle(fd_gpio, MOTOR_PINS[i], (int)(pwm_duty_cycle * 255));
            }
            fprintf(log_file, "%ld: Noise level %d, PWM duty cycle %d%%\n", time(NULL), adc_value, (int)pwm_duty_cycle);
        } else {
            for (int i = 0; i < 2; ++i) {
                piGpioSetPWMdutycycle(fd_gpio, MOTOR_PINS[i], 0);
            }
        }

        usleep(SAMPLE_INTERVAL);
    }

    // Graceful shutdown
    piGpioTerminate();
    fclose(log_file);
    close(fd_spidev);
    piGpioClose(fd_gpio);

    return 0;
}

