#include <gpiod.h>

#define MAX_BUFFER_SIZE 1024
#define I2C_ADDR_BH1750 0x23
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define CSV_FILE "tamper_log.csv"
#define READ_DELAY_MS 180

struct sensor_data {
    double timestamp;
    int sound_level_db;
    int light_level_lux;
    int error_code;
};

int main() {
    int adc_fd, i2c_fd;
    struct sensor_data data;
    FILE *csv_file = fopen("tamper_log.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return 1;
    }

    fprintf(csv_file, "timestamp,sound_level_db,light_level_lux,error_code\n");

    // Initialize GPIO
    gpiod_context ctx = gpiod_new();
    if (!ctx) {
        perror("Failed to create GPIO context");
        return 1;
    }

    int chip = gpiod_chip_open(ctx, "spidev0.0");
    if (chip < 0) {
        perror("Failed to open SPI chip");
        gpiod_context_destroy(ctx);
        return 1;
    }

    int line = gpiod_chip_get_line(chip, "ce0");
    if (line < 0) {
        perror("Failed to get SPI CE0 line");
        gpiod_chip_close(chip);
        gpiod_context_destroy(ctx);
        return 1;
    }

    gpiod_line_request_set_config(line, GPIO_DIR_OUT, GPIO_PUD_OFF, "MAX9814_CS");

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_context_destroy(ctx);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR_BH1750) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_context_destroy(ctx);
        return 1;
    }

    // Read sound level from MAX9814 via MCP3008
    while (1) {
        data.timestamp = time(NULL);

        // Activate MAX9814 CS
        gpiod_line_trigger(line, 0);
        usleep(READ_DELAY_MS * 1000);
        gpiod_line_trigger(line, 1);

        // Read ADC value
        unsigned int adc_value;
        if (pread(adc_fd, &adc_value, sizeof(adc_value), 0) != sizeof(adc_value)) {
            data.error_code = -1;
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            data.sound_level_db = (adc_value * 2.5) - 2500; // Convert to dB
            data.error_code = 0;
        }

        // Read light level from BH1750
        unsigned char msb, lsb;
        if (ioctl(i2c_fd, I2C_MASTER_TRANSMIT, &I2C_ADDR_BH1750) < 0) {
            data.error_code = -2;
            fprintf(stderr, "Failed to transmit to BH1750\n");
        } else if (ioctl(i2c_fd, I2C_MASTER_RECEIVE, &msb) < 0) {
            data.error_code = -3;
            fprintf(stderr, "Failed to receive from BH1750\n");
        } else {
            lsb = ioctl(i2c_fd, I2C_MASTER_RECEIVE, &msb);
            data.light_level_lux = (msb << 8) | lsb;
            data.error_code = 0;
        }

        fprintf(csv_file, "%f,%d,%d,%d\n", data.timestamp, data.sound_level_db, data.light_level_lux, data.error_code);
        fflush(csv_file);

        sleep(5);
    }

    // Cleanup
    fclose(csv_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpiod_context_destroy(ctx);
    close(i2c_fd);
    return 0;
}

