#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigio.h>
#include <stdbool.h>

#define VH400_MIN_MOISTURE 30
#define SPI_CHANNEL 0
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MAX_RETRIES 3

static volatile bool running = true;
static pig_client *pi = NULL;

void sigint_handler(int signum) {
    running = false;
}

uint16_t read_analog(uint8_t channel) {
    uint16_t adc_value = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (pigio_spi_transfer(pi, SPI_CHANNEL, &channel, 1, NULL, 1) == 1) {
            adc_value = (uint16_t)(pigio_spi_receive(pi, SPI_CHANNEL, NULL, 2) >> 8);
            adc_value |= (uint16_t)pigio_spi_receive(pi, SPI_CHANNEL, NULL, 1) << 8;

            if (adc_value > 0) {
                return adc_value;
            }
        }
        retries++;
        sleep(1);
    }

    return 0; // Failed to read ADC value
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (pigio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    if (spidev_open(SPI_CHANNEL) < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        pigio_terminate();
        return EXIT_FAILURE;
    }

    pi = pig_client_init("pi");
    if (!pi) {
        fprintf(stderr, "Failed to initialize pigpio client.\n");
        spidev_close(SPI_CHANNEL);
        pigio_terminate();
        return EXIT_FAILURE;
    }

    pig_set_mode(pi, PUMP_GPIO, PI_OUTPUT);
    pinAssign(PUMP_GPIO, PI_OPEN_DRAIN, PI_NO_PULL);
    pig_output(pi, PUMP_GPIO, 0); // Turn off the pump

    while (running) {
        uint16_t adc_value = read_analog(MCP3008_CHANNEL);
        float voltage = (float)adc_value * (5.0 / 1023.0);
        float moisture = voltage * (VH400_MAX_MOISTURE / 3.0) - VH400_MIN_MOISTURE;

        if (moisture < VH400_MIN_MOISTURE) {
            pig_output(pi, PUMP_GPIO, 1); // Turn on the pump
        } else {
            pig_output(pi, PUMP_GPIO, 0); // Turn off the pump
        }

        time_t now = time(NULL);
        printf("Timestamp: %ld, Moisture: %.2f%%, Pump: %s\n", now, moisture, moisture < VH400_MIN_MOISTURE ? "ON" : "OFF");
        sleep(60);
    }

    pigio_terminate();
    spidev_close(SPI_CHANNEL);
    return EXIT_SUCCESS;
}

