#define MCP3008_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000
#define FAN_GPIO 18
#define CHECK_INTERVAL_MS 5000
#define CO2_THRESHOLD 700
#define SLEEP_INTERVAL_MS 100

float calibration_slope = 0.5;
float calibration_intercept = -50;

void log_reading(const char *filename, long timestamp, float co2_ppm, int fan_state) {
    FILE *fp = fopen(filename, "a");
    if (fp) {
        fprintf(fp, "%ld,%.2f,%d\n", (long)time(NULL), co2_ppm, fan_state);
        fclose(fp);
    }
}

int main() {
    pigpio *gpio;
    int adc_value;
    float co2_ppm;
    int fan_state = 0;
    long timestamp;

    gpio = pigpio(0, 0);
    if (!gpio) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (spiOpen(0, SPI_MODE, SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        pigpio_terminate(gpio);
        return 1;
    }

    spiCsbMode(0);
    spiChipSelect0(0);

    while (1) {
        spiTransferBlock(0, (uint8_t[]){MCP3008_CHANNEL}, 1);
        spiReadBlocks(0, (uint8_t*)&adc_value, 2);
        spiChipSelect0(1);

        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        co2_ppm = (float)adc_value * calibration_slope + calibration_intercept;
        timestamp = time(NULL);

        log_reading("air_quality.log", timestamp, co2_ppm, fan_state);

        if (co2_ppm > CO2_THRESHOLD) {
            if (!fan_state) {
                gpioSetMode(FAN_GPIO, PI_OUTPUT);
                gpioWrite(FAN_GPIO, 1);
                fan_state = 1;
            }
        } else {
            if (fan_state) {
                gpioSetMode(FAN_GPIO, PI_OUTPUT);
                gpioWrite(FAN_GPIO, 0);
                fan_state = 0;
            }
        }

        usleep(SLEEP_INTERVAL_MS * 1000);
    }

    pigpio_terminate(gpio);
    spiClose(0);

    return 0;
}

