#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <stdbool.h>
#include <libgpiod.h>

#define RELAY_PIN 17
#define IR_SENSOR_PIN 27
#define DEBOUNCE_DELAY 1000000 // 1 second in microseconds
#define POLLING_INTERVAL 100000 // 100 milliseconds in microseconds
#define MIN_DISTANCE 20

static gpiod_chip *chip;
static gpiod_line *relay_line;
static gpiod_line *ir_sensor_line;
static spi_device *spidev;

void log_event(const char *event) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen("door_events.log", "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fclose(log_file);
    }
}

int main() {
    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, "SPI0.CE0");
    if (!relay_line) {
        fprintf(stderr, "Failed to get SPI0.CE0 line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    ir_sensor_line = gpiod_chip_get_line(chip, "GPIO27");
    if (!ir_sensor_line) {
        fprintf(stderr, "Failed to get GPIO27 line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_export(relay_line, "Relay") < 0 || gpiod_line_export(ir_sensor_line, "IR_Sensor") < 0) {
        fprintf(stderr, "Failed to export lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_set_direction(relay_line, GPIO_OUTPUT);
    gpiod_line_set_value(relay_line, 0);

    spidev = spi_open("/dev/spidev0.0", O_RDWR);
    if (!spidev) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (spi_xfer(spidev, NULL) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        spi_close(spidev);
        gpiod_chip_close(chip);
        return 1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 1,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .bits = SPI_CPOL_LOW | SPI_MSBFIRST,
    };

    bool ir_detected = false;
    bool debouncing = false;
    unsigned long last_event_time = 0;

    while (1) {
        if (gpiod_line_read(ir_sensor_line) == 1) {
            if (!debouncing) {
                debouncing = true;
                last_event_time = get_timestamp_us();
            }
        } else {
            debouncing = false;
        }

        if (debouncing && (get_timestamp_us() - last_event_time) > DEBOUNCE_DELAY) {
            ir_detected = true;
            log_event("Proximity detected, energizing relay");
            gpiod_line_set_value(relay_line, 1);
            usleep(POLLING_INTERVAL);
        }

        if (ir_detected && get_distance_cm() < MIN_DISTANCE) {
            gpiod_line_set_value(relay_line, 1);
            usleep(POLLING_INTERVAL);
            ir_detected = false;
        }

        sleep(1);
    }

    gpiod_line_release(relay_line);
    gpiod_line_release(ir_sensor_line);
    gpiod_chip_close(chip);
    spi_close(spidev);

    return 0;
}

unsigned long get_timestamp_us() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (unsigned long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
