    if (!chip) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, "SPI0.CE0");
    if (!relay_line) {
        fprintf(stderr, "Failed to get SPI0.CE0 line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    ir_sensor_line = gpiod_chip_get_line(chip, "GPIO27");
    if (!ir_sensor_line) {
        fprintf(stderr, "Failed to get GPIO27 line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_export(relay_line, "Relay") < 0 || gpiod_line_export(ir_sensor_line, "IR_Sensor") < 0) {
        fprintf(stderr, "Failed to export lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_set_direction(relay_line, GPIO_OUTPUT);
    gpiod_line_set_value(relay_line, 0);

    spidev = spi_open("/dev/spidev0.0", O_RDWR);
    if (!spidev) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (spi_xfer(spidev, NULL) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        spi_close(spidev);
        gpiod_chip_close(chip);
        return 1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 1,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .bits = SPI_CPOL_LOW | SPI_MSBFIRST,
    };

