            if (!debouncing) {
                debouncing = true;
                last_event_time = get_timestamp_us();
            }
        } else {
            debouncing = false;
        }

        if (debouncing && (get_timestamp_us() - last_event_time) > DEBOUNCE_DELAY) {
            ir_detected = true;
            log_event("Proximity detected, energizing relay");
            gpiod_line_set_value(relay_line, 1);
