#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define VALVE_GPIO 17
#define SENSOR_SPI_CHANNEL 0
#define NUM_SENSORS 3
#define SPI_CLOCK 1000000
#define PWM_FREQ 100
#define PWM_RANGE 100
#define LOG_INTERVAL 5

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void setup_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        exit(EXIT_FAILURE);
    }
    if (spiOpen(SENSOR_SPI_CHANNEL, SPI_MODE0, SPI_CLOCK, 8, 0) < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (pwmTerminalCountSet(VALVE_GPIO, 100) < 0) {
        fprintf(stderr, "PWM terminal count set failed.\n");
        spiClose(SENSOR_SPI_CHANNEL);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (pwmFrequencySet(VALVE_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "PWM frequency set failed.\n");
        spiClose(SENSOR_SPI_CHANNEL);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup_pigpio(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    pwmStop(VALVE_GPIO);
    spiClose(SENSOR_SPI_CHANNEL);
    gpioTerminate();
}

int main(void) {
    setup_pigpio();

    const char *log_filename = "irrigation.log";
    FILE *log_file = fopen(log_filename, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", log_filename);
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    while (running) {
        int adc_values[NUM_SENSORS];
        int total = 0;
        int count = 0;

        for (int i = 0; i < NUM_SENSORS; ++i) {
            int spi_result = spiTransfer(SENSOR_SPI_CHANNEL, &adc_values[i], 2);
            if (spi_result < 0) {
                fprintf(stderr, "SPI transfer failed for sensor %d\n", i);
                continue;
            }
            total += adc_values[i];
            count++;
        }

        if (count > 0) {
            int average = total / count;
            int valve_position = PWM_RANGE - (average * PWM_RANGE / 1023);
            gpioWrite(VALVE_GPIO, valve_position);

            time_t now = time(NULL);
            fprintf(log_file, "%ld ", now);
            for (int i = 0; i < NUM_SENSORS; ++i) {
                fprintf(log_file, "%d ", adc_values[i]);
            }
            fprintf(log_file, "%d %d\n", average, valve_position);
        }

        usleep(LOG_INTERVAL * 1000000);
    }

    cleanup_pigpio();
    fclose(log_file);
    return EXIT_SUCCESS;
}

