#include <time.h>
#include <pigpio.h>

#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define MAX_RETRIES 5
#define INITIAL_BACKOFF_MS 100

int spi_read(int channel, int spi_mode, int *adc_value) {
    int retry_count = 0;
    int backoff_ms = INITIAL_BACKOFF_MS;

    while (retry_count < MAX_RETRIES) {
        *adc_value = pigpio_spi_transfer(gpio, SPI_MODE, (1 << channel));
        if (*adc_value != -1) {
            return 0; // Success
        }

        retry_count++;
        if (retry_count < MAX_RETRIES) {
            piSleep(backoff_ms);
            backoff_ms *= 2; // Exponential backoff
        }
    }

    return -1; // Failed after retries
}

float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return (float)adc_value * (100.0 / 1023.0);
}

void log_reading(const char *timestamp, int adc_value) {
    FILE *fp = fopen("soil_data.txt", "a");
    if (fp) {
        time_t now = time(NULL);
        char *dt = ctime(&now);
        fprintf(fp, "%s: ADC Value = %d, Moisture (%) = %.2f\n", dt, adc_value, adc_to_moisture(adc_value));
        fclose(fp);
    }
}

int main() {
    gpioInitialise();
    gpioSetMode(8, PI_OUTPUT); // CE0

    int spi_channel = 0;
    int adc_value;
    float moisture;

    while (1) {
        if (spi_read(MCP3008_CHANNEL, SPI_MODE, &adc_value) == 0) {
            moisture = adc_to_moisture(adc_value);
            log_reading(ctime(NULL), adc_value);
        } else {
            fprintf(stderr, "SPI communication failed after retries.\n");
        }

        piSleep(5000000); // Sleep for 5 seconds
    }

    gpioTerminate();
    return 0;
}

