#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define MCP3008_SPI_MODE 0
#define MCP3008_CHANNEL 0
#define FAN_GPIO 18
#define MAX_SPI_RETRIES 3
#define SPI_RETRY_DELAY 1000000 // 1 second in microseconds

int spi_read(uint8_t *data) {
    static int retry_count = 0;
    int ret = 0;

    if (retry_count < MAX_SPI_RETRIES) {
        ret = spiSendRecv(gpioChip0(), 0x01 | (MCP3008_SPI_MODE << 6) | (MCP3008_CHANNEL << 3));
        if (ret < 0) {
            retry_count++;
            printf("SPI read failed, retrying...\n");
            delayMicroseconds(SPI_RETRY_DELAY);
        }
    } else {
        printf("SPI read failed after %d retries, re-initializing SPI\n", MAX_SPI_RETRIES);
        spiInit(gpioChip0(), 0, 0, 0, 0, 0, 0, 0, 0);
        retry_count = 0;
    }

    return ret;
}

int main() {
    pigpio *gpio;
    gpio = pigpioInit();
    if (!gpio) {
        fprintf(stderr, "pigpioInit failed\n");
        return 1;
    }

    if (gpioSetMode(gpio, FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        pigpioTerminate(gpio);
        return 1;
    }
    gpioSetMode(gpio, FAN_GPIO, PI_OPEN_DRAIN);
    gpioSetPullUpDown(gpio, FAN_GPIO, 1);

    if (spiInit(gpio, 0, 0, 0, 0, 0, 0, 0, 0) < 0) {
        fprintf(stderr, "SPI init failed\n");
        pigpioTerminate(gpio);
        return 1;
    }

    FILE *log_file = fopen("air_quality.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpioTerminate(gpio);
        return 1;
    }

    while (1) {
        uint8_t adc_value[2];
        int spi_ret = spi_read(adc_value);
        if (spi_ret < 0) {
            continue;
        }

        uint16_t raw_value = (adc_value[1] << 8) | adc_value[0];
        float voltage = raw_value * (5.0 / 1023.0);
        int aqi = (int) (voltage * 500);

        fprintf(log_file, "%ld: AQI = %d\n", time(NULL), aqi);

        if (aqi > 100) {
            gpioSetMode(gpio, FAN_GPIO, PI_OUTPUT);
            gpioWrite(gpio, FAN_GPIO, 1);
        } else {
            gpioSetMode(gpio, FAN_GPIO, PI_OUTPUT);
            gpioWrite(gpio, FAN_GPIO, 0);
        }

        delayMicroseconds(5000000); // 5 seconds
    }

    fclose(log_file);
    pigpioTerminate(gpio);
    return 0;
}

