        fprintf(stderr, "pigpioInit failed\n");
        return 1;
    }

    if (gpioSetMode(gpio, FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        pigpioTerminate(gpio);
        return 1;
    }
    gpioSetMode(gpio, FAN_GPIO, PI_OPEN_DRAIN);
    gpioSetPullUpDown(gpio, FAN_GPIO, 1);

    if (spiInit(gpio, 0, 0, 0, 0, 0, 0, 0, 0) < 0) {
        fprintf(stderr, "SPI init failed\n");
        pigpioTerminate(gpio);
        return 1;
    }

    FILE *log_file = fopen("air_quality.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpioTerminate(gpio);
        return 1;
    }

    while (1) {
        uint8_t adc_value[2];
        int spi_ret = spi_read(adc_value);
        if (spi_ret < 0) {
            continue;
        }

        uint16_t raw_value = (adc_value[1] << 8) | adc_value[0];
        float voltage = raw_value * (5.0 / 1023.0);
        int aqi = (int) (voltage * 500);

        fprintf(log_file, "%ld: AQI = %d\n", time(NULL), aqi);

        if (aqi > 100) {
            gpioSetMode(gpio, FAN_GPIO, PI_OUTPUT);
            gpioWrite(gpio, FAN_GPIO, 1);
        } else {
            gpioSetMode(gpio, FAN_GPIO, PI_OUTPUT);
            gpioWrite(gpio, FAN_GPIO, 0);
        }

        delayMicroseconds(5000000); // 5 seconds
    }

    fclose(log_file);
    pigpioTerminate(gpio);
    return 0;
