int main() {
    struct spi_device spi;
    struct gpiod_chip chip;
    struct gpiod_line *ce0;
    int fd;
    int retries = 0;

    fd = spidev_open("/dev/spidev0.0", SPI_MODE);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    spi.fd = fd;
    spi.cs_change_delay_us = 10;
    spi.speed_hz = SPI_CLK_SPEED;
    spi.bits_per_word = 8;
    spi.chip_select_polarity = 0;
    spi.mode = SPI_MODE;

    if (spidev_transfer(&spi, tx, rx) != rx[0]) {
        fprintf(stderr, "SPI transfer failed\n");
        spidev_close(fd);
        return 1;
    }

    if (gpiod_chip_open(&chip, "GPIO08") < 0) {
        perror("Failed to open GPIO chip");
        spidev_close(fd);
        return 1;
    }

    ce0 = gpiod_chip_get_line(&chip, "GPIO08", "OUT");
    if (!ce0) {
        fprintf(stderr, "Failed to get CE0 line\n");
        spidev_close(fd);
        gpiod_chip_close(&chip);
        return 1;
    }

    gpiod_line_export(ce0, NULL);
    gpiod_line_set_direction(ce0, GPIO_OUT);

    while (1) {
        time_t now;
        struct tm *time_struct;
        char timestamp[64];

        time(&now);
        time_struct = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

        for (retries = 0; retries < MAX_RETRIES; retries++) {
            if (spidev_transfer(&spi, tx, rx) != rx[0]) {
                if (retries == MAX_RETRIES - 1) {
                    fprintf(stderr, "Error: SPI transfer failed after %d retries\n", MAX_RETRIES);
                    break;
                }
                sleep(DELAY_MS / 1000);
                continue;
            }

            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            double ppm = (adc_value * 0.5) - 10.0;

            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "Sensor-absent condition detected\n");
                break;
            }

            gpiod_line_set_value(ce0, 0);
            usleep(SPI_CLK_DIV * 1000000 / SPI_CLK_SPEED);
            gpiod_line_set_value(ce0, 1);
            usleep(SPI_CLK_DIV * 1000000 / SPI_CLK_SPEED);

            if (fp == NULL) {
                fp = fopen(log_file, "w");
                if (!fp) {
                    perror("Failed to open log file");
                    spidev_close(fd);
                    gpiod_chip_close(&chip);
                    return 1;
                }
            }

            fprintf(fp, "%s, PPM: %.2f\n", timestamp, ppm);
            fflush(fp);

            if (ppm > 50.0) {
                printf("Alcohol detected! Limit exceeded.\n");
            } else if (ppm < 20.0) {
                printf("Sobriety confirmed.\n");
            } else {
                printf("Alcohol level within acceptable range.\n");
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Error: Failed to read ADC value after %d retries\n", MAX_RETRIES);
        }
    }

    gpiod_line_unset_value(ce0, 0);
    gpiod_line_unset_value(ce0, 1);
    gpiod_chip_close(&chip);
    spidev_close(fd);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    return 0;
}

