        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(SCLK_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCLK_GPIO as output\n");
        gpioTerminate();
        exit(1);
