    if (gpioSetMode(MOSI_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MOSI_GPIO as output\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(MISO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set MISO_GPIO as input\n");
        gpioTerminate();
        exit(1);
    }

    if (spiOpen(&spi_fd, SPI_MODE_0, MCP3008_SPI_CLOCK, 8, SPI_CE0_GPIO, SCLK_GPIO, MOSI_GPIO, MISO_GPIO) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        exit(1);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open irrigation.log\n");
        gpioTerminate();
        exit(1);
    }
}

