#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <wiringPiSPI.h>

#define MIN_SPEED 50
#define MAX_SPEED 255
#define HOLD_TIME 2000000 // 2 seconds in µs
#define PAUSE_TIME 50000000 // 5 seconds in µs

#define MOTOR1_EN GPIO18
#define MOTOR1_DIR GPIO23
#define MOTOR2_EN GPIO24
#define MOTOR2_DIR GPIO25

#define SPI_CHANNEL 0
#define MOSI_PIN GPIO10
#define MISO_PIN GPIO9
#define SCLK_PIN GPIO11
#define CE0_PIN GPIO8

#define ADC_CHANNEL0 0
#define ADC_CHANNEL1 1

float speed_factor(int value) {
    return (float)MIN_SPEED + (MAX_SPEED - MIN_SPEED) * log(1 + value / 1023.0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    if (wiringPiSPIInit() < 0) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        gpioTermination();
        return 1;
    }

    gpioSetMode(MOTOR1_EN, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_EN, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);

    if (gpioSPIOpen(SPI_CHANNEL, 1000000) < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTermination();
        return 1;
    }

    int pot1, pot2;
    float motor1_speed, motor2_speed;

    while (1) {
        if (gpioSPIGetData(SPI_CHANNEL, (uint8_t *)&pot1, 1) != 1) {
            fprintf(stderr, "Failed to read from SPI.\n");
            break;
        }
        if (gpioSPIGetData(SPI_CHANNEL, (uint8_t *)&pot2, 1) != 1) {
            fprintf(stderr, "Failed to read from SPI.\n");
            break;
        }

        motor1_speed = speed_factor(pot1);
        motor2_speed = speed_factor(pot2);

        gpioPWM(MOTOR1_EN, (int)(motor1_speed * 1000));
        gpioPWM(MOTOR2_EN, (int)(motor2_speed * 1000));

        gpioWrite(MOTOR1_DIR, 1);
        gpioWrite(MOTOR2_DIR, 0);

        // Move forward Motor 1, backward Motor 2
        gpioPulse(MOTOR1_EN, 1, 1000000);
        gpioPulse(MOTOR2_EN, 0, 1000000);

        usleep(HOLD_TIME);

        gpioPulse(MOTOR1_EN, 0, 1000000);
        gpioPulse(MOTOR2_EN, 1, 1000000);

        usleep(HOLD_TIME);

        gpioWrite(MOTOR1_DIR, 0);
        gpioWrite(MOTOR2_DIR, 1);

        // Move backward Motor 1, forward Motor 2
        gpioPulse(MOTOR1_EN, 0, 1000000);
        gpioPulse(MOTOR2_EN, 1, 1000000);

        usleep(HOLD_TIME);

        gpioPulse(MOTOR1_EN, 1, 1000000);
        gpioPulse(MOTOR2_EN, 0, 1000000);

        usleep(HOLD_TIME);

        // Pause
        usleep(PAUSE_TIME);
    }

    gpioTermination();
    return 0;
}

