void log_reading(double voltage) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen("airflow_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s, Voltage: %.2f V\n", timestamp, voltage);
        fclose(log_file);
    } else {
        fprintf(stderr, "ERROR: Failed to open log file.\n");
    }
}

int main() {
    int spi_fd = spiOpen(MCP3008_SPI_CHANNEL, 1000000);
    if (spi_fd < 0) {
        fprintf(stderr, "ERROR: Failed to open SPI channel.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: Failed to initialize pigpio library.\n");
        spiClose(spi_fd);
        return 1;
    }

    gpioSetMode(CE0_GPIO, PI_OUTPUT);

    if ((gpioFileDesc = fopen("/dev/pigpio", "r+")) == NULL) {
        fprintf(stderr, "ERROR: Failed to open pigpio device file.\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetWarningHandler(warning_handler);

    while (1) {
        gpioWrite(CE0_GPIO, 1);
        spiTransfer(spi_fd, 0x01);
        gpioWrite(CE0_GPIO, 0);

        int adc_value = spiRead(spi_fd);
        double voltage = (adc_value * 3.3) / 1023.0;

        if (adc_value < 0) {
            fprintf(stderr, "ERROR: ADC read failed.\n");
            log_reading(-1);
            continue;
        }

        log_reading(voltage);

        struct timespec delay = {0, 100 * 1000 * 1000};
        nanosleep(&delay, NULL);
    }

    gpioTerminate();
    spiClose(spi_fd);
    fclose(gpioFileDesc);

    return 0;
}

static void warning_handler(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    fprintf(stderr, "WARNING: ");
    vfprintf(stderr, fmt, args);
    fprintf(stderr, "\n");
    va_end(args);
}

