#include <spidev.h>

#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define SAMPLE_RATE_HZ 1000
#define SAMPLE_PERIOD_US 1000
#define LOG_FILE "audio_log.txt"

struct spi_dev spi;
int spi_fd = -1;
int chip = -1;
int line = -1;
FILE *log_fp = NULL;

void sigint_handler(int signum) {
    if (log_fp) fclose(log_fp);
    gpiod_request_release(line);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int init_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) != 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) != 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) != 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int init_gpio(int gpio_num) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(&gpiod_chip_default, "gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, gpio_num);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", gpio_num);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_direction(line, GPIO_REQUEST_OUTPUT) != 0) {
        perror("Failed to request GPIO direction");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(line) != 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return line->line.id;
}

int sample_adc() {
    uint8_t tx_buf[3] = {0x01, 0x0800, 0x00};
    uint8_t rx_buf[3];
    int bytes_read;

    if (gpiod_line_set_value(line, 0) != 0) {
        perror("Failed to drive CS low");
        return -1;
    }
    delay_us(5);

    if (write(spi_fd, tx_buf, 3) != 3) {
        perror("Failed to write to SPI");
        gpiod_line_set_value(line, 1);
        return -1;
    }

    if ((bytes_read = read(spi_fd, rx_buf, 3)) != 3) {
        perror("Failed to read from SPI");
        gpiod_line_set_value(line, 1);
        return -1;
    }

    if (gpiod_line_set_value(line, 1) != 0) {
        perror("Failed to drive CS high");
        return -1;
    }

    return ((rx_buf[1] << 8) | rx_buf[2]);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = init_gpio(8);
    if (chip < 0) {
        return -1;
    }

    line = gpiod_line_from_id(chip, 0);
    if (!line) {
        fprintf(stderr, "Failed to get line from id\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (init_spi() < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    if ((log_fp = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return -1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        uint16_t adc_value = sample_adc();

        fprintf(log_fp, "%llu|%d\n", (unsigned long long)ts.tv_sec * 1000000 + ts.tv_nsec, adc_value);
        fflush(log_fp);

        usleep(SAMPLE_PERIOD_US - (uint32_t)(1000000 * (ts.tv_sec - (ts.tv_sec % (SAMPLE_RATE_HZ / 1000000)))) % 1000000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);
    fclose(log_fp);
    return 0;
}

