#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>

#define MCP3008_SPI_MODE 0
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define PPM_FACTOR 1000.0

static volatile int running = 1;
static pigio_context *gpio;

void spi_init() {
    gpio = init_pigpio();
    if (gpio == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_mode(CE0, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CE0 as output\n");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_mode(SPI_MOSI, PI_OUTPUT) < 0 ||
        gpio_set_mode(SPI_MISO, PI_INPUT) < 0 ||
        gpio_set_mode(SPI_CLK, PI_OUTPUT) < 0 ||
        gpio_set_mode(SPI_CS0, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI pins mode\n");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_pull_up_down(CE0, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set CE0 pull-up-down\n");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_clk(SPI_CLK, 1000000) < 0) {
        fprintf(stderr, "Failed to set SPI clock frequency\n");
        exit(EXIT_FAILURE);
    }
}

void spi_cleanup() {
    gpio_terminate(gpio);
}

uint16_t read_adc(void) {
    gpio_write(CE0, 0);
    gpio_write(SPI_CLK, 0);
    gpio_write(SPI_CS0, 0);

    // Start condition
    gpio_write(SPI_CLK, 1);
    gpio_write(SPI_CS0, 1);

    // Clock high
    gpio_write(SPI_CLK, 1);

    // Select channel
    gpio_write(SPI_MOSI, MCP3008_CHANNEL << 3);
    gpio_write(SPI_CLK, 0);
    gpio_write(SPI_CLK, 1);

    // Clock low
    gpio_write(SPI_CLK, 0);

    // Read data
    uint8_t data[3];
    gpio_read(SPI_MISO, &data[0], 1);
    gpio_read(SPI_MISO, &data[1], 1);
    gpio_read(SPI_MISO, &data[2], 1);

    gpio_write(SPI_CS0, 0);
    gpio_write(SPI_CLK, 0);

    uint16_t adc_value = (data[1] << 8) | data[0];
    return adc_value;
}

void log_data(double voltage, double ppm) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen("gas_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open 'gas_log.txt'\n");
        return;
    }

    fprintf(log_file, "%s, Voltage: %.3f V, PPM: %.3f\n", timestamp, voltage, ppm);
    fclose(log_file);
}

int main(void) {
    spi_init();

    signal(SIGINT, (sig_t)cleanup);

    while (running) {
        double voltage;
        uint16_t adc_value;

        for (int i = 0; i < 3; i++) {
            adc_value = read_adc();
            if (adc_value != 0xFFFF) {
                voltage = (adc_value * VREF) / 1023.0;
                break;
            }
            usleep(100 * 1000);
        }

        if (adc_value == 0xFFFF) {
            fprintf(stderr, "Failed to read ADC value after retries\n");
            break;
        }

        double ppm = voltage * PPM_FACTOR;

