#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define MAX_LOG_SIZE 1024
#define LOG_FILE "magnetic_log.txt"

float sensor_values[3];
FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpiod_unrequest(chip, lines);
    exit(0);
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line[3];
    int r;
    int i;

    // Initialize libgpiod
    r = gpiod_chip_open(&chip, "GPIO");
    if (r < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return r;
    }

    // Request GPIO lines for input
    for (i = 0; i < 3; i++) {
        char line_name[32];
        snprintf(line_name, sizeof(line_name), "GPIO%d", 4 + i);
        r = gpiod_line_request_input(chip.id, line_name, &line[i]);
        if (r < 0) {
            fprintf(stderr, "Failed to request input for %s\n", line_name);
            gpiod_chip_close(chip.id);
            return r;
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip.id);
        return -1;
    }

    // Signal handler setup
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read sensor values
        for (i = 0; i < 3; i++) {
            r = gpiod_line_get_value_cb(line[i].id, 0, &sensor_values[i]);
            if (r < 0) {
                fprintf(stderr, "Failed to read sensor %d\n", i + 1);
                continue;
            }
        }

        // Calculate magnetic field strength
        float b[3];
        for (i = 0; i < 3; i++) {
            b[i] = (sensor_values[i] - V_QUIESCENT) * SENSITIVITY;
            if (b[i] > 100.0 || b[i] < -100.0) {
                fprintf(stderr, "Warning: Magnetic field strength out of range for sensor %d\n", i + 1);
            }
        }

        // Log the readings
        char log_entry[MAX_LOG_SIZE];
        snprintf(log_entry, MAX_LOG_SIZE, "%.2f,%.2f,%.2f", b[0], b[1], b[2]);
        fputs(log_entry, log_file);
        fflush(log_file);

        // Sleep for 100 milliseconds
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    gpiod_unrequest(chip.id, line, 3);
    gpiod_chip_close(chip.id);

    return 0;
}

