#define MOISTURE_THRESHOLD 30
#define PUMP_GPIO 17
#define ADC_CHANNEL 0
#define SPI_CE0 10

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct timespec ts;
    gpioInitialise();
    if (piGetMode() != PI_SPIMODE_MODE0) {
        gpioTerminate();
        fprintf(stderr, "Error: Incorrect SPI mode.\n");
        return 1;
    }

    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    if (gpioInitialiseSPI(SPI_CE0) < 0) {
        gpioTerminate();
        fprintf(stderr, "Error: Failed to initialize SPI.\n");
        return 1;
    }

    if (gpioSetADCSampleTime(ADC_CHANNEL, 1000000) < 0) {
        gpioTerminate();
        fprintf(stderr, "Error: Failed to set ADC sample time.\n");
        return 1;
    }

    if (gpioSetADCPin(ADC_CHANNEL) < 0) {
        gpioTerminate();
        fprintf(stderr, "Error: Failed to set ADC pin.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        ts = *localtime(&now);
        fprintf(stderr, "[%02d:%02d:%02d] ", ts.tv_sec / 3600, (ts.tv_sec / 60) % 60, ts.tv_sec % 60);

        int moisture_level;
        if (gpioADCRaw(ADC_CHANNEL, &moisture_level) < 0) {
            fprintf(stderr, "Error reading ADC.\n");
            continue;
        }

        float moisture_percentage = (float)moisture_level / 1023 * 100;
        fprintf(stderr, "Moisture: %.2f%%\n", moisture_percentage);

        if (moisture_percentage < MOISTURE_THRESHOLD) {
            gpioWrite(PUMP_GPIO, 1);
            fprintf(stderr, "Pump ON\n");
        } else {
            gpioWrite(PUMP_GPIO, 0);
            fprintf(stderr, "Pump OFF\n");
        }

        sleep(60);
    }

    gpioTerminate();
    return 0;
}

