#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <libgpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CSV_FILE "sensor_data.csv"
#define CHANNELS 3
#define SAMPLE_INTERVAL 1

struct spi_data {
    int fd;
    gpiod_chip *chip;
};

void log_adc_reading(struct spi_data *spi, int channel) {
    uint8_t command[3] = {0x01, 0x80 | (channel << 4), 0x00};
    int ret;

    ret = write(spi->fd, command, 3);
    if (ret != 3) {
        fprintf(stderr, "Error writing to SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    uint16_t adc_value;
    ret = ioctl(spi->fd, SPI_IOC_MESSAGE(3), &adc_value);
    if (ret < 0) {
        fprintf(stderr, "Error during SPI ioctl: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    adc_value = (adc_value & 0x03) << 8 | spi->data[2];
    fprintf(csv_file, "%d,%d\n", (int)adc_value, channel);
}

int main() {
    struct spi_data spi;
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
