#define LED_GPIO 17
#define BROKER "mqtt.eclipseprojects.io"
#define BROKER_PORT 1883
#define CLIENT_ID "rpi_led_control"
#define MAX_RECONNECT_DELAY 60000000 // 60 seconds

static volatile sig_atomic_t sigint_received = 0;
static volatile sig_atomic_t sigterm_received = 0;

static mosq_cb callback;
static mosquitto *mqtt_handle = NULL;
static gpio *gpio_handle = NULL;

void sigint_handler(int signum) {
    sigint_received = 1;
}

void sigterm_handler(int signum) {
    sigterm_received = 1;
}

void init_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);
}

void cleanup() {
    mosquitto_disconnect(mqtt_handle);
    mosquitto_destroy(mqtt_handle);
    mqtt_handle = NULL;

    gpioTerminate();
    gpio_handle = NULL;
}

void reconnect_delay(int attempt) {
    int delay = 1 << attempt;
    if (delay > MAX_RECONNECT_DELAY) {
        delay = MAX_RECONNECT_DELAY;
    }
    printf("Reconnecting in %d seconds...\n", delay);
    sleep(delay);
}

void mqtt_callback(mosquitto *mqtt, void *obj, const char *topic, const char *payload) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        fprintf(stderr, "Error parsing JSON: %s\n", cJSON_GetErrorPtr());
        return;
    }

    if (cJSON_ObjectGetCaseSensitive(json, "led_state") == NULL) {
        cJSON_Delete(json);
        return;
    }

    bool led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state")->valueint;
    cJSON_Delete(json);

    if (led_state) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(int argc, char *argv[]) {
    init_signal_handlers();
    gpio_handle = gpioInitialise();
    if (gpio_handle == NULL) {
        fprintf(stderr, "Error initialising pigpio\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    mqtt_handle = mosquitto_new(NULL, true);
    if (mqtt_handle == NULL) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        return 1;
    }

    callback = mqtt_callback;
    mosquitto_callback_set(mqtt_handle, callback);

    if (mosquitto_connect(mqtt_handle, BROKER, 1883, 60, NULL, 0, NULL) == MOSQ_ERR_SUCCESS) {
        mosquitto_loop_forever(mqtt_handle, -1, 1);
    } else {
        fprintf(stderr, "Error connecting to MQTT broker\n");
        return 1;
    }

    cleanup();
    return 0;
}

