#include <signal.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18
#define SOUND_LEVEL_DELAY_MS 100
#define ALARM_ON_TIME_MS 1000
#define ALARM_OFF_TIME_MS 1000

static struct gpiod_chip *chip;
static struct gpiod_line *sound_sensor_line;
static struct gpiod_line *alarm_led_line;
static int alarm_state = 0;
static int alarm_state_timeout = 0;

void alarm_led_callback(const struct gpiod_line *line, uint32_t events) {
    if (events & (1 << GPIO_EVENT_FALLING)) {
        alarm_state = 1;
        alarm_state_timeout = ALARM_ON_TIME_MS;
    }
}

void sound_sensor_callback(const struct gpiod_line *line, uint32_t events) {
    if (events & (1 << GPIO_EVENT_FALLING)) {
        printf("Sound detected (level: 1)\n");
        trigger_alarm();
    }
}

void trigger_alarm() {
    if (alarm_state_timeout > 0) {
        alarm_state = 1;
        gpiod_trigger(alarm_led_line, events: GPIO_FALLING_EDGE);
        alarm_state_timeout -= SOUND_LEVEL_DELAY_MS;

        if (alarm_state_timeout == 0) {
            gpiod_trigger(alarm_led_line, events: GPIO_RISING_EDGE);
            alarm_state = 0;
            alarm_state_timeout = ALARM_OFF_TIME_MS;
        }
    }
}

void cleanup(int signum) {
    gpiod_line_release(sound_sensor_line);
    gpiod_line_release(alarm_led_line);
    gpiod_chip_release(chip);
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(0, "GPIO");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    sound_sensor_line = gpiod_chip_get_line(chip, "GPIO17");
    if (!sound_sensor_line) {
        fprintf(stderr, "Failed to get sound sensor line\n");
        gpiod_chip_release(chip);
        return 1;
    }

    alarm_led_line = gpiod_chip_get_line(chip, "GPIO18");
    if (!alarm_led_line) {
        fprintf(stderr, "Failed to get alarm LED line\n");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_release(chip);
        return 1;
    }

    gpiod_line_export(sound_sensor_line, "sound_sensor");
    gpiod_line_export(alarm_led_line, "alarm_led");

    gpiod_line_set_direction(sound_sensor_line, GPIO_OUT);
    gpiod_line_set_direction(alarm_led_line, GPIO_OUT);

    gpiod_line_set_listener(sound_sensor_line, sound_sensor_callback);
    gpiod_line_set_listener(alarm_led_line, alarm_led_callback);

    while (1) {
        gpiod_line_read(sound_sensor_line);
        usleep(SOUND_LEVEL_DELAY_MS * 1000);

        if (alarm_state) {
            trigger_alarm();
        }
    }

    gpiod_line_release(sound_sensor_line);
    gpiod_line_release(alarm_led_line);
    gpiod_chip_release(chip);

    return 0;
}

