#include <stdatomic.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <gpiod.h>

volatile sig_atomic_t sigint_received = 0;
volatile sig_atomic_t sigterm_received = 0;

static int log_file_fd = -1;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static void sigterm_handler(int signum) {
    sigterm_received = 1;
}

static int setup_logging(const char *log_file) {
    log_file_fd = fopen(log_file, "a");
    if (!log_file_fd) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

static void log_vibration_event(const char *message) {
    static struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(log_file_fd, "%ld.%09lu: %s\n", ts.tv_sec, ts.tv_nsec, message);
    fprintf(stdout, "%s\n", message);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    struct gpiod_chipchip *chip;
    struct gpiod_line *line;
    struct gpiod_event event;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, "GPIO17");
    if (!line) {
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_add(line, "vibration-monitor");
    if (ret) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_event_read(line, &event);
    gpiod_line_event_wait_for(line, &event, -1);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    if (setup_logging("/var/log/vibration_shutdown.log")) {
        log_vibration_event("Vibration detected, initiating shutdown");
    } else {
        log_vibration_event("Could not open log file");
    }

    while (!sigint_received || !sigterm_received) {
        gpiod_line_event_read(line, &event);
        if (event.type == GPIO_EVENT_FALLING) {
            if (setup_logging("/var/log/vibration_shutdown.log")) {
                log_vibration_event("Vibration detected, initiating shutdown");
            } else {
                log_vibration_event("Could not open log file");
            }
            system("sudo shutdown -h now");
            break;
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

