#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define MCP3008_SPI_MODE 0
#define MCP3008_CHANNEL 0
#define BUFFER_SIZE 120
#define SPI_CHANNEL 0
#define CE0_GPIO 8

float temp_buffer[BUFFER_SIZE];
int buffer_index = 0;

void spi_transfer(uint8_t tx[], uint8_t rx[], int len) {
    int i;
    for (i = 0; i < len; i++) {
        if (gpioInitialise() < 0) {
            fprintf(stderr, "Error: pigpio initialization failed.\n");
            return;
        }
        if (gpioSetMode(CE0_GPIO, PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: Failed to set CE0_GPIO as output.\n");
            return;
        }
        gpioWrite(CE0_GPIO, 0);
        if (piSend(SPI_CHANNEL, tx, len) < 0) {
            fprintf(stderr, "Error: SPI transfer failed.\n");
            return;
        }
        if (piReceive(SPI_CHANNEL, rx, len) < 0) {
            fprintf(stderr, "Error: SPI transfer failed.\n");
            return;
        }
        gpioWrite(CE0_GPIO, 1);
        delay(1); // Wait for conversion to complete
    }
}

float read_temperature() {
    uint8_t tx[] = {0x01};
    uint8_t rx[3];
    spi_transfer(tx, rx, 1);

    int channel_code = (1 << 7) | MCP3008_CHANNEL;
    tx[0] = 0x01 | channel_code;
    spi_transfer(tx, rx, 1);

    int result = ((rx[1] & 0x03) << 8) | rx[2];
    float voltage = result * (3.3 / 1024.0);
    float temperature = voltage * 100; // LM35: 10mV/°C

    return temperature;
}

void log_to_file(const char *filename) {
    FILE *file = fopen(filename, "ab");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file %s for writing.\n", filename);
        return;
    }
    fwrite(temp_buffer, sizeof(float), BUFFER_SIZE, file);
    fclose(file);
}

void signal_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(CE0_GPIO, PI_OUTPUT);
    gpioWrite(CE0_GPIO, 0);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    while (1) {
        float temperature = read_temperature();
        printf("Temperature: %.2f °C\n", temperature);

        temp_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        if (time(NULL) % 5 == 0) {
            log_to_file("temp_log.dat");
        }

        delay(1000);
    }

    gpioTerminate();
    return 0;
}

