#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <spidev.h>

#define BH1750_ADDR 0x23
#define MCP3008_CHAN 0
#define SAMPLE_INTERVAL 1

int i2c_fd = -1;
int spi_fd = -1;

void log_environmental_data() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    int light_value;
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus\n");
        return;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &light_value) < 0) {
        fprintf(stderr, "Failed to read from BH1750\n");
        close(i2c_fd);
        return;
    }
    close(i2c_fd);

    int sound_value;
    if (ioctl(spi_fd, SPI_RDWR, &sound_value) < 0) {
        fprintf(stderr, "Failed to read from MCP3008\n");
        close(spi_fd);
        return;
    }
    close(spi_fd);

    FILE *log_file = fopen("environmental_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(log_file, "%s, Light: %d, Sound: %d\n", timestamp, light_value, sound_value);
    fclose(log_file);
}

int main() {
    struct i2c_rdwr_ioctl_data rdwr;
    struct spidev_ioc_transfer tr;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open i2c bus\n");
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        close(i2c_fd);
        return 1;
    }

    rdwr.u8 = &light_value;
    rdwr.u8_len = 1;
    rdwr.u8_buf = NULL;

    tr.flags = SPI_TRANSFER_FULL_DUPLEX | SPI_TRANSFER_MSBX;
    tr.tx_buf = (unsigned char[]){MCP3008_CHAN};
    tr.rx_buf = (unsigned char[]){0};
    tr.len = 1;

    while (1) {
        log_environmental_data();
        sleep(SAMPLE_INTERVAL);
    }

    close(i2c_fd);
    close(spi_fd);
    return 0;
}

