#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define FLAME_THRESHOLD 1
#define LOG_FILE "flame_events.log"

static int line_state;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

static void log_event(const char *timestamp, int pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Unable to open log file %s\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "%s, %d, %d\n", timestamp, pin, state);
    fclose(fp);
}

static void print_alarm() {
    printf("ALARM: Flame detected!\n");
}

static int check_flame_detected(int state) {
    return (state == 1) ? 1 : 0;
}

static void cleanup() {
    if (line) {
        gpiod_line_unref(line);
    }
    if (chip) {
        gpiod_chip_unref(chip);
    }
}

int main(int argc, char *argv[]) {
    struct gpiod_chip_list *cl;
    int r;

    chip = gpiod_chip_open(NULL, "gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Unable to open gpiochip0\n");
        return EXIT_FAILURE;
    }

    cl = gpiod_chip_get_lines(chip, NULL);
    if (!cl) {
        fprintf(stderr, "Error: Unable to get lines from gpiochip0\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, "17");
    if (!line) {
        fprintf(stderr, "Error: Unable to get line for GPIO%d\n", FLAME_SENSOR_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    r = gpiod_line_request_add(line, &gpiod_line_request_in, GPIOD_LINE_ACTIVE_LOW, NULL);
    if (r < 0) {
        fprintf(stderr, "Error: Failed to request input line\n");
        cleanup();
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_state = gpiod_line_get_value(line);

    while (1) {
        if (line_state == 1) {
            print_alarm();
            log_event(asctime(localtime(&now)), FLAME_SENSOR_PIN, line_state);
        }

        sleep(1);
        line_state = gpiod_line_get_value(line);

        if (check_flame_detected(line_state)) {
            log_event(asctime(localtime(&now)), FLAME_SENSOR_PIN, line_state);
        }
    }

    cleanup();
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

