#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define DAC_ADDR 0x62
#define SPI_MODE 0
#define SPI_FREQ 500000
#define TEMP_MIN 0
#define TEMP_MAX 50
#define VOLTAGE_MIN 0
#define VOLTAGE_MAX 3.3

int spi_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }
    if (piGiocontrol(PI_SOFT, SPI_MODE, SPI_FREQ) < 0) {
        fprintf(stderr, "Failed to set SPI mode and frequency\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

int spi_transfer(uint8_t tx_byte) {
    uint8_t rx_byte;
    if (gpioSPITransmitReceive(0, &tx_byte, &rx_byte, 1) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return 0;
}

int i2c_write(uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = DAC_ADDR;
    buf[1] = reg;
    buf[2] = (value & 0xFF);
    if (piGiocontrol(PI_HARD, I2C_WRITE, 3) < 0) {
        fprintf(stderr, "Failed to initiate I2C write\n");
        return -1;
    }
    if (gpioI2CWrite(buf, 3) < 0) {
        fprintf(stderr, "Failed to perform I2C write\n");
        return -1;
    }
    return 0;
}

float adc_to_voltage(uint16_t adc_value) {
    return (adc_value * 3.3f) / 1023;
