#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_CHANNELS 3
#define SLEEP_INTERVAL 60000000 // 60 seconds in nanoseconds

void log_reading(int sensor_num, int adc_value) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%F %T", localtime(now));

    FILE *log_file = fopen("soil_data.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s, Sensor %d: %d ADC, %f%% moisture\n", timestamp, sensor_num, adc_value, (float)adc_value / 1023.0 * 100.0);
        fclose(log_file);
    } else {
        perror("Error opening log file");
        exit(1);
    }
}

int main() {
    gpioInitialise();

    int spi_fd = spiOpen(0, 1000000);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(0, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(0, PI_INPUT);

    while (1) {
        int adc_values[MCP3008_CHANNELS];
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            gpioSetMode(i * 2, PI_OUTPUT);
            gpioWrite(i * 2, 0);
            gpioSetMode(i * 2 + 1, PI_INPUT);

            int spi_len = spiXfer(spi_fd, (volatile char*)(&adc_values[i]), 2);
            if (spi_len != 2) {
                fprintf(stderr, "Error transferring SPI data\n");
                break;
            }

            if (adc_values[i] < 0 || adc_values[i] > 1023) {
                fprintf(stderr, "Invalid ADC value from sensor %d\n", i);
                continue;
            }

            double moisture = (1.0 - (double)adc_values[i] / 1023.0) * 100.0;
            log_reading(i + 1, adc_values[i]);
        }

        gpioWrite(0, 0);
        gpioDelay(10);

        if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
            // Ignore SIGINT
        }

        if (kill(getppid(), SIGINT) != 0) {
            fprintf(stderr, "Error sending SIGINT to parent process\n");
            break;
        }

        usleep(SLEEP_INTERVAL);
    }

    gpioTerminate();
    spiClose(spi_fd);
    fclose("soil_data.txt");

    return 0;
}

