#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS {17, 22, 23, 24}
#define RELAY_COUNT (sizeof(RELAY_PINS) / sizeof(RELAY_PINS[0]))

int relay_states[NUM_RELAYS] = {0};

void deactivate_all_relays() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(relay_lines[i], 0);
    }
}

void signal_handler(int signum) {
    deactivate_all_relays();
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(relay_lines[i]);
    }
    exit(signum);
}

int main() {
    struct gpiod_chipchip *chip;
    struct gpiod_line *lines[NUM_RELAYS];

    chip = gpiod_chip_open(0, "GPIO");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for pin %d\n", RELAY_PINS[i]);
            gpiod_chip_close(chip);
            return 1;
        }

        if (gpiod_line_request_output(lines[i], "SRD-05VDC-SL")) {
            fprintf(stderr, "Failed to request output for pin %d\n", RELAY_PINS[i]);
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            return 1;
        }

        gpiod_line_set_value(lines[i], 0); // Initially set all relays off
    }

    gpiod_chip_close(chip);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            relay_states[i] = !relay_states[i];
            gpiod_line_set_value(lines[i], relay_states[i]);
            sleep(1);
        }
    }

    return 0;
}

