#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_CHANNEL 0
#define LED_GPIO 16
#define CH_SELECT_GPIO 8
#define THRESHOLD 500
#define DEBOUNCE_DELAY 50
#define SPI_CLOCK 1000000

static volatile int led_state = 0;
static volatile int sound_level;

static void sigint_handler(int signum) {
    gpioTerminate();
    close(spi_fd);
    exit(0);
}

int main() {
    struct timespec ts;
    static int last_trigger_time = 0;
    int spi_fd;
    gpioInitialise();
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    spi_fd = spiOpen(0, SPI_CLOCK);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(CH_SELECT_GPIO, PI_OUTPUT);
    gpioWrite(CH_SELECT_GPIO, 0);

    if (pigpioRequest(100) < 0) {
        fprintf(stderr, "Failed to request pigpio resources\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);

        if (sound_level > THRESHOLD) {
            if (ts.tv_sec - last_trigger_time > DEBOUNCE_DELAY / 1000000.0) {
                gpioWrite(LED_GPIO, 1);
                last_trigger_time = ts.tv_sec;

                FILE *log_file = fopen("sound_events.log", "a");
                if (!log_file) {
                    fprintf(stderr, "Failed to open log file\n");
                    gpioWrite(LED_GPIO, 0);
                    continue;
                }

                time_t now_time = time(NULL);
                struct tm *tm_info = localtime(&now_time);
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - Sound level exceeded threshold\n",
                        tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                        tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);
                fclose(log_file);
            }
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        if (spiTransfer(spi_fd, &sound_level, sizeof(sound_level)) != 2) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        usleep(10 * 1000);
    }

    gpioTerminate();
    spiClose(spi_fd);
    pigpio_terminate(0);
    return 0;
}

