#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define PWM_SPEED 150
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define POLL_INTERVAL 1

volatile sig_atomic_t shutdown_flag = 0;

int main(int argc, char *argv[]) {
    struct timespec ts;
    gpioInit();
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spiDevice spi = spiOpen(0, SPI_BAUD);
    if (!spi) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("rain_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Log file open failed\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(17, PI_OUTPUT);
    gpioSetMode(18, PI_OUTPUT);
    gpioSetMode(27, PI_OUTPUT);

    gpioSetPWMfrequency(27, SPI_BAUD);
    gpioSetPWMdutycycle(27, PWM_SPEED);

    while (!shutdown_flag) {
        uint16_t adc_value;
        uint8_t tx[3] = {0x01, (0x08 | SPI_CHANNEL) << 4, 0x00};
        uint8_t rx[3];

        if (spiTransfer(spi, tx, rx) != 3) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        int rain_level = 10 - (adc_value / 4096.0 * 10);

        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0;
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(log_file, "%s: Rain level %d\n", timestamp, rain_level);
        fflush(log_file);

        if (rain_level >= RAIN_THRESHOLD) {
            gpioWrite(17, MOTOR_FORWARD);
            gpioWrite(18, MOTOR_REVERSE);
            usleep(3000000);
        } else {
            gpioWrite(17, MOTOR_REVERSE);
            gpioWrite(18, MOTOR_FORWARD);
            usleep(3000000);
        }
    }

    gpioTerminate();
    spiClose(spi);
    fclose(log_file);
    return 0;
}

void sigint_handler(int signum) {
    shutdown_flag = 1;
}

void sigterm_handler(int signum) {
    shutdown_flag = 1;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Rest of the main function remains the same
}

