#define THRESHOLD (700)
#define LED_PIN 16
#define MIC_PIN 26
#define DEBOUNCE_TIME_US (50)
#define DETECTION_ON_TIME_MS (500)

static volatile int led_state = 0;
static uint32_t last_detection_time = 0;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main(void) {
    struct timespec ts;
    int fd;
    int ret;

    // Register SIGINT handler
    if ((fd = signal(SIGINT, sigint_handler)) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler\n");
        return 1;
    }

    // Initialize pigpio library
    if ((ret = pigpio(0, 0)) != 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", pigpio_error(ret));
        return 1;
    }

    // Set GPIO modes
    if (gpioInitialise() != 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        pigpio_terminate(0);
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(MIC_PIN, PI_INPUT);

    // Set up ADC
    if (pigpio_adcSetMode(MIC_PIN, PI_ADC_MODE_BIT) != 0) {
        fprintf(stderr, "pigpio_adcSetMode() failed\n");
        gpioTerminate();
        pigpio_terminate(0);
        return 1;
    }

    // Start continuous sampling
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint10_t adc_value;

        if (pigpio_adcRead(MIC_PIN, &adc_value) != 0) {
            fprintf(stderr, "pigpio_adcRead() failed\n");
            break;
        }

        if (adc_value.value >= THRESHOLD) {
            uint32_t now = ts.tv_sec * 1000 + ts.tv_nsec / 1000;
            if (now - last_detection_time > DEBOUNCE_TIME_US) {
                gpioWrite(LED_PIN, 1);
                last_detection_time = now;
                printf("%lu: Clap detected! LED on\n", (unsigned long)now);

                // Turn on LED for DETECTION_ON_TIME_MS
                gpioWrite(LED_PIN, 1);
                delay(DETECTION_ON_TIME_MS * 1000);
                gpioWrite(LED_PIN, 0);
            }
        } else {
            gpioWrite(LED_PIN, 0);
        }

        delay(10); // Sample at ~100 Hz
    }

    gpioTerminate();
    pigpio_terminate(0);
    return 0;
}

