#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define A 26.0
#define B -6.0

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    int fd;
    char timestamp[20];
    double voltage;
    float distance;

    if (gpiod_chip_open(&chip, "gpiochip0") < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    if (gpiod_chip_get_line(&chip, "17", &line) < 0) {
        fprintf(stderr, "Failed to get line 17\n");
        gpiod_chip_close(&chip);
        return 1;
    }

    fd = gpiod_line_to_fd(line);
    if (fd < 0) {
        fprintf(stderr, "Failed to get file descriptor\n");
        gpiod_chip_close(&chip);
        return 1;
    }

    while (1) {
        time_t now;
        struct tm *timeinfo;
        char buf[80];

        time(&now);
        timeinfo = localtime(&now);
        strftime(buf, sizeof(buf), "%F %T", timeinfo);

        if (gpiod_line_read(fd) < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        voltage = gpiod_line_get_value(fd) ? 3.3 : 0;
        distance = A / voltage + B;

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        FILE *log_file = fopen("distance_log.txt", "a");
        if (log_file != NULL) {
            fprintf(log_file, "%s, Distance: %.2f mm\n", buf, distance);
            fclose(log_file);
        }

        if (signal(SIGINT, sigint_handler) || signal(SIGTERM, sigint_handler)) {
            fprintf(stderr, "Signal handlers installed\n");
        }
    }

    gpiod_line_unexport(line);
    gpiod_chip_close(&chip);
    close(fd);
    return 0;
}

static void sigint_handler(int signum) {
    gpiod_line_unexport(line);
    fprintf(stderr, "Interrupted, exiting...\n");
    exit(0);
}

