#include <signal.h>
#include <libgpio.h>
#include <spidev.h>

#define VH400_DRY 800
#define VH400_WET 300
#define PUMP_GPIO 17
#define SPI_DEV "/dev/spidev0.0"
#define LOG_FILE "soil_moisture.log"

struct gpio_chip *chip;
struct spidev *spi;
FILE *log_file;

void log_moisture_data(double moisture_percentage, int pump_status);
void shutdown(int signum);

int main() {
    int ret;
    struct gpio_line *mosi, *miso, *clk, *ce0;
    struct gpio_chip_config config;
    struct spidev_xfer xfer;

    // Initialize libgpiod
    ret = gpio_open();
    if (ret) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }
    chip = gpio_chip_open("/dev/gpiochip0", NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpio_close();
        return 1;
    }

    // Initialize SPI
    spi = spidev_open(SPI_DEV, 0);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpio_close();
        return 1;
    }

    // Configure GPIO pins
    mosi = gpio_chip_get_line(chip, "GPIO10");
    clk = gpio_chip_get_line(chip, "GPIO11");
    miso = gpio_chip_get_line(chip, "GPIO9");
    ce0 = gpio_chip_get_line(chip, "GPIO12");

    if (!gpio_line_export(mosi, "mosi") || !gpio_line_export(clk, "clk") ||
        !gpio_line_export(miso, "miso") || !gpio_line_export(ce0, "ce0")) {
        fprintf(stderr, "Failed to export GPIO lines\n");
        spidev_close(spi);
        gpio_close();
        return 1;
    }

    // Set initial direction and level for SPI lines
    gpio_line_direction_set(mosi, GPIO_DIRECTION_OUT);
    gpio_line_direction_set(clk, GPIO_DIRECTION_OUT);
    gpio_line_direction_set(miso, GPIO_DIRECTION_IN);
    gpio_line_direction_set(ce0, GPIO_DIRECTION_OUT);
    gpio_line_set_value(ce0, 0);

    // Open log file
    log_file = fopen("soil_moisture.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpio_close();
        spidev_close(spi);
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, shutdown);

    while (1) {
        // Read ADC value from MCP3008
        xfer.tx_buf = (uint8_t[]){0x01}; // Start conversion
        xfer.rx_buf = (uint8_t[]){0};
        xfer.len = 1;
        spi_transfer(spi, &xfer);

        int adc_value = (xfer.rx_buf[0] & 0x03) * 255;

        // Validate ADC value
        if (adc_value < 0 || adc_value > VH400_DRY) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Calculate moisture percentage
        double moisture_percentage = map_value(adc_value, 0, VH400_DRY, 0, 100);

        // Activate pump if moisture level is below 30%
        int pump_status = (moisture_percentage < 30) ? 1 : 0;
        if (pump_status) {
            gpio_line_set_value(ce0, 1);
        } else {
            gpio_line_set_value(ce0, 0);
        }

        // Log data
        log_moisture_data(moisture_percentage, pump_status);

        // Sleep for 60 seconds
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    gpio_close();
    spidev_close(spi);
    return 0;
}

void log_moisture_data(double moisture_percentage, int pump_status) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Moisture: %.2f%% (%s)\n",
            1900 + local_time->tm_year,
            1 + local_time->tm_mon,
            local_time->tm_mday,
            local_time->tm_hour,
            local_time->tm_min,
            local_time->tm_sec,
            moisture_percentage,
            pump_status ? "ON" : "OFF");
}

void shutdown(int signum) {
    gpio_line_set_value(ce0, 0); // Turn off pump
    fclose(log_file);
    gpio_close();
    spidev_close(spi);
    exit(0);
}

double map_value(int x, int in_min, int in_max, int out_min, int out_max) {
    return (double)(x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

