#include <stdbool.h>
#include <stdint.h>
#include <libgpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define CS_GPIO 8
#define SAMPLE_INTERVAL_MS 500
#define LOG_FILE "magnetic_log.txt"

int spi_fd;
int cs_gpio;
FILE *log_file;

void cleanup() {
    gpiod_release(cs_gpio);
    gpiod_close(gpiochip);
    fclose(log_file);
}

void handle_sigint(int signum) {
    fprintf(stderr, "Received SIGINT, cleaning up and exiting...\n");
    cleanup();
    exit(signum);
}

void handle_sigterm(int signum) {
    fprintf(stderr, "Received SIGTERM, cleaning up and exiting...\n");
    cleanup();
    exit(signum);
}

int main() {
    struct gpiod_chip gpiochip;
    struct gpiod_line *cs_line;
    int ret;

    gpiochip_open(&gpiochip, "gpiochip0");
    cs_line = gpiod_chip_get_line(&gpiochip, "GPIO%d", CS_GPIO);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line for CS\n");
        return 1;
    }

    ret = gpiod_line_export(cs_line, true);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO line for CS\n");
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_WRITER_DUART, 0) < 0) {
        fprintf(stderr, "Failed to set SPI mode 0\n");
        return 1;
    }

    ret = fcntl(spi_fd, F_SETFL, O_NONBLOCK);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI file descriptor to non-blocking mode\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    if (signal(SIGTERM, handle_sigterm) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        return 1;
    }

    cs_gpio = gpiod_line_get_gpio(cs_line);
    gpiod_line_set_value(cs_line, 0);

    while (true) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint16_t adc_value;

        gpiod_line_set_value(cs_line, 0);
        if (write(spi_fd, &SAMPLE_INTERVAL_MS, 4) != 4) {
            fprintf(stderr, "Failed to write sample interval to SPI\n");
            break;
        }

        if (read(spi_fd, &adc_value, 2) != 2) {
            fprintf(stderr, "Failed to read ADC value from SPI\n");
            break;
        }

        gpiod_line_set_value(cs_line, 1);

        int vout_mV = (adc_value * 3300) / 1023;
        int B_mt = (vout_mV - 1650) / 100;

        fprintf(log_file, "%ld,%.2f\n", (long)ts.tv_sec, (double)B_mt);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}
