#include <pigpio.h>

#define LED_GPIO 21
#define MCP3008_CH 0
#define SENSITIVITY_MV_PER_MT (1.65 * 3.3 / 5)
#define QUIESCENT_VCC 3.3
#define THRESHOLD_MT 10.0

void cleanup() {
    gpioTerminate();
}

int main() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (spidev_open(0, 1000000) < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetOutputLevel(LED_GPIO, 0);

    while (1) {
        int adc_value;
        if (spidev_transfer(spidev_handle, &MCP3008_CH, NULL, &adc_value, 1) != 1) {
            fprintf(stderr, "SPI read failed\n");
            break;
        }

        float voltage = (float)adc_value * QUIESCENT_VCC / 1023.0;
        float field_mt = (voltage - QUIESCENT_VCC / 2) * 1000.0 / SENSITIVITY_MV_PER_MT;

        FILE *log_file = fopen("magnetic_log.txt", "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            break;
        }

        fprintf(log_file, "%s: %f mT\n", timestamp, field_mt);
        fclose(log_file);

        if (field_mt > THRESHOLD_MT) {
            gpioSetOutputLevel(LED_GPIO, 1);
        } else {
            gpioSetOutputLevel(LED_GPIO, 0);
        }

        usleep(100000);
    }

    cleanup();
    spidev_close(spidev_handle);
    return 0;
}

