#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define CE0 8

static const int spi_freq = 1000000;
static const int spi_mode = 0;
static const int spi_bits_per_word = 8;
static const int spi_cs_active_low = 1;

static int spi_fd;
static gpio_init *gpio;

void log_moisture_reading(int adc_value) {
    time_t now;
    struct tm *time_struct;
    char timestamp[20];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%F %T", time_struct);

    FILE *log_file = fopen("moisture_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s: %d\n", timestamp, adc_value);
        fclose(log_file);
    }
}

void log_error(const char *message) {
    time_t now;
    struct tm *time_struct;
    char timestamp[20];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%F %T", time_struct);

    FILE *log_file = fopen("moisture_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s: ERROR: %s\n", timestamp, message);
        fclose(log_file);
    }
}

int main() {
    int rc;

    gpio = gpioInitialise();
    if (gpio == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    spi_fd = spiOpen(SPI_CHANNEL, spi_freq);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate(gpio);
        return 1;
    }

    pinMode(CE0, output);
    gpioSetMode(CE0, PI_OUTPUT);

    while (1) {
        gpioWrite(CE0, 0); // Select MCP3008 chip
        spiTransfer(spi_fd, 0x01 | (MCP3008_CHANNEL << 3)); // Start bit and channel selection

        uint8_t rx_buf[3];
        uint32_t count = spiRead(spi_fd, rx_buf, 3);
        if (count != 3) {
            log_error("Failed to read from SPI");
            continue;
        }

        int adc_value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
        log_moisture_reading(adc_value);

        gpioWrite(CE0, 1); // Deselect MCP3008 chip

        sleep(60);
    }

    spiClose(spi_fd);
    gpioTerminate(gpio);

    return 0;
}

