#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpio.h>
#include <linux/spi/spidev.h>

#define MLX91209_GPIO_PIN 17
#define MCP3008_CHANNEL 0
#define LOG_FILE "current_log.txt"
#define READ_INTERVAL 1

struct spi_dev spi;
struct gpiod_chip chip;
FILE *log_file;

void signal_handler(int signum) {
    gpiod_chip_unprepare(&chip);
    spidev_close(&spi);
    fclose(log_file);
    exit(signum);
}

int init_gpio() {
    int ret;
    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return ret;
    }

    ret = gpiod_chip_export(&chip, MLX91209_GPIO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", MLX91209_GPIO_PIN, strerror(errno));
        gpiod_chip_free(&chip);
        return ret;
    }

    ret = gpiod_chip_address_create(&chip, MLX91209_GPIO_PIN, GPIO_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", MLX91209_GPIO_PIN, strerror(errno));
        gpiod_chip_free(&chip);
        return ret;
    }

    return 0;
}

int init_spi() {
    spi.fd = open("/dev/spidev0.0", O_RDWR);
    if (spi.fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi.fd, SPI_IOC_WR_FRAMES, &spi.len) < 0) {
        perror("Failed to set SPI frame size");
        close(spi.fd);
        return -1;
    }

    if (ioctl(spi.fd, SPI_IOC_RD_FRAMES, &spi.len) < 0) {
        perror("Failed to get SPI frame size");
        close(spi.fd);
        return -1;
    }

    return 0;
}

int init_log_file() {
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    return 0;
}

int read_current() {
    int msec;
    struct timespec ts;
    double voltage, current;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    msec = ts.tv_nsec / 1000000;

    // Set GPIO high for MLX91209
    gpiod_trigger_output(&chip, MLX91209_GPIO_PIN, 1);
    usleep(1000); // Wait for stable output

    // Read ADC value from MCP3008
    spi.bufs[0] = MCP3008_CHANNEL;
    if (ioctl(spi.fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        fprintf(stderr, "Failed to read from SPI device\n");
        return -1;
    }

    voltage = (double)spi.bufs[0] / 1024 * 5; // Convert to voltage
    current = voltage / 100; // Convert to current (A)

    fprintf(log_file, "%ld,%.6f\n", (long)msec, current);

    // Set GPIO low for MLX91209
    gpiod_trigger_output(&chip, MLX91209_GPIO_PIN, 0);
    usleep(1000); // Wait for stable output

    return 0;
}

int main() {
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    ret = init_gpio();
    if (ret < 0) {
        return ret;
    }

    ret = init_spi();
    if (ret < 0) {
        gpiod_chip_unprepare(&chip);
        return ret;
    }

    ret = init_log_file();
    if (ret < 0) {
        spidev_close(&spi);
        gpiod_chip_unprepare(&chip);
        return ret;
    }

    while (1) {
        read_current();
        sleep(READ_INTERVAL);
    }

    gpiod_chip_unprepare(&chip);
    spidev_close(&spi);
    fclose(log_file);

    return 0;
}

