#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MCP3008_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_MODE 0
#define SPI_CE 0
#define LOG_FILE "current_log.txt"

volatile sig_atomic_t interrupt_flag = 0;

int main() {
    gpioInitialise();
    if (gpioFailed()) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    spiOpen(0, SPI_BAUD, SPI_MODE, 8, 0, spi_ce_callback);
    if (pi_spi_failed()) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, [](int) { interrupt_flag = 1; });

    while (!interrupt_flag) {
        uint8_t tx[3] = {0x01, 0x80 | (MCP3008_CHANNEL << 4), 0x00};
        uint8_t rx[3];
        int rc = spiXfer(0, tx, rx);
        if (rc < 0) {
            fprintf(stderr, "SPI transfer error\n");
            gpioDelay(100000);
            continue;
        }

        uint16_t raw_value = ((rx[1] & 0x03) << 8) | rx[2];
        double voltage = raw_value * (5.0 / 1023.0);

        if (voltage < 0 || voltage > 5) {
            fprintf(stderr, "Voltage out of range: %f V\n", voltage);
            gpioDelay(100000);
            continue;
        }

        double current = (voltage - 2.5) * (50.0 / 2.5);
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %02d.%02d A\t%f\n",
                1900 + tm->tm_year, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                (int)(current + 0.5), (int)((current - (int)current) * 1000000), current);
        fflush(log_file);
        gpioDelay(100000);
    }

    fclose(log_file);
    spiClose(0);
    gpioTerminate();

    return 0;
}

static void spi_ce_callback(int ce, int level) {
    if (ce == SPI_CE) {
        interrupt_flag = 1;
    }
}

