        uint8_t rx[3];
        int rc = spiXfer(0, tx, rx);
        if (rc < 0) {
            fprintf(stderr, "SPI transfer error\n");
            gpioDelay(100000);
            continue;
        }

        uint16_t raw_value = ((rx[1] & 0x03) << 8) | rx[2];
        double voltage = raw_value * (5.0 / 1023.0);

        if (voltage < 0 || voltage > 5) {
            fprintf(stderr, "Voltage out of range: %f V\n", voltage);
            gpioDelay(100000);
            continue;
        }

        double current = (voltage - 2.5) * (50.0 / 2.5);
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %02d.%02d A\t%f\n",
                1900 + tm->tm_year, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                (int)(current + 0.5), (int)((current - (int)current) * 1000000), current);
        fflush(log_file);
        gpioDelay(100000);
    }

    fclose(log_file);
    spiClose(0);
    gpioTerminate();

    return 0;
}

static void spi_ce_callback(int ce, int level) {
    if (ce == SPI_CE) {
        interrupt_flag = 1;
    }
}
