        return -1;
    }

    if (gpiod_line_request_input(line, "input") < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(fd);
        fprintf(stderr, "Failed to request input from GPIO line\n");
        return -1;
    }

    *result = 0;
    for (int i = 0; i < NUM_SAMPLES; ++i) {
        int value = gpiod_line_get_value(line);
        (*result) += value;
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }
    gpiod_line_release(line);
