#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t termination_flag = 0;

int read_mcp3008(int channel) {
    uint8_t tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    uint8_t rx_buf[3];
    int rc;

    rc = spiTransfer(SPI_CHANNEL, tx_buf, rx_buf);
    if (rc < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", rc);
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC)
        return -1;

    return 100.0 - ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

void log_data(double moisture_level) {
    time_t now_time = time(NULL);
    struct tm *time_info = localtime(&now_time);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, moisture_level);
    fclose(log_file);

    printf("%s, %.2f\n", timestamp, moisture_level);
}

void signal_handler(int signal) {
    termination_flag = 1;
}

int spi_setup(spi_config_t config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_BAUD, config) < 0) {
        gpioTerminate();
        return -1;
    }

    signal(SIGINT, signal_handler);

    return 0;
}

int main() {
    spi_config_t config;
    config.bits_per_word = 16;
    config.max_speed_hz = SPI_BAUD;

    if (spi_setup(config) < 0)
        return 1;

    while (!termination_flag) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            double moisture_level = calculate_moisture_level(adc_value);
            if (moisture_level >= 0)
                log_data(moisture_level);
        }

        sleep(READ_DELAY);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

