#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <time.h>
#include <pigio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY (200 * 1000) // 200 ms
#define POLL_INTERVAL (50 * 1000) // 50 ms
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define OUTPUT_DIR "/home/pi/security_cam"
#define LOG_PREFIX "[PIR_CAMERA]"

void log_event(const char *event) {
    openlog(LOG_PREFIX, LOG_PID, LOG_USER);
    syslog(LOG_INFO, "%s: %s", LOG_PREFIX, event);
    closelog();
}

void init_pigpio() {
    if (pigpio_initialise() < 0) {
        log_event("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
    log_event("pigpio initialized");
}

void cleanup_pigpio() {
    pigpio_terminate();
    log_event("pigpio terminated");
}

void setup_gpio() {
    if (gpio_set_mode(GPIO_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO%d as output");
        exit(EXIT_FAILURE);
    }
    if (gpio_set_pull_updn(GPIO_PIN, PI_PUD_OFF) < 0) {
        log_event("Failed to configure pull-down resistor on GPIO%d");
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    struct timespec ts;
    int ret;
    gpio pi = GPIO;
    char filename[256];

    init_pigpio();
    setup_gpio();

    if (mkdir(OUTPUT_DIR, 0755) < 0 && errno != EEXIST) {
        log_event("Failed to create output directory");
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    while (1) {
        ret = gpio_read(GPIO_PIN);
        if (ret == PI_HIGH) {
            if (time(&ts) - last_motion_time > DEBOUNCE_DELAY) {
                snprintf(filename, sizeof(filename), "%s/motion_%d_%04d_%02d_%02d_%02d.jpg",
                         OUTPUT_DIR, getuid(),
                         (int)ts.tv_sec,
                         (int)ts.tv_nsec / 1000000,
                         (int)(ts.tv_nsec / 1000) % 60,
                         (int)(ts.tv_nsec / 100000) % 60);

            log_event("Motion detected, capturing image...");
            if (fork() == 0) {
                // Child process
                close(STDOUT_FILENO);
                close(STDERR_FILENO);

                char cmd[256];
                snprintf(cmd, sizeof(cmd), "libcamera-still --width %d --height %d --format jpeg --filename '%s'",
                         IMAGE_WIDTH, IMAGE_HEIGHT, filename);

                if (execvp(cmd, &cmd[0]) < 0) {
                    log_event("Failed to execute libcamera-still");
                    exit(EXIT_FAILURE);
                }
            } else {
                // Parent process
                waitpid(-1, &ret, 0);
                if (WIFEXITED(ret) && WEXITSTATUS(ret) != 0) {
                    log_event("libcamera-still failed to capture image");
                }
            }

            last_motion_time = time(NULL);
        }

        nanosleep(&ts, NULL);
    }

    cleanup_pigpio();
    closelog();
    return 0;
}

