    if (fd != -1) {
        close(fd);
        fd = -1;
    }
    if (buffer_fd != -1) {
        munmap(buffer, BUFFER_SIZE);
        close(buffer_fd);
        buffer_fd = -1;
    }
    exit(0);
}

int init_camera(const char *device) {
    fd = open(device, O_RDWR);
    if (fd == -1) {
        perror("Failed to open device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query device capabilities");
        close(fd);
        fd = -1;
        return -1;
    }

    if ((cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) == 0) {
        fprintf(stderr, "Device does not support capture\n");
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_fmtdesc fmt;
    fmt.index = 0;
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) == -1) {
        perror("Failed to enumerate formats");
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_frmt vfmt;
    memset(&vfmt, 0, sizeof(vfmt));
    vfmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    vfmt.fmt.pix.width = WIDTH;
    vfmt.fmt.pix.height = HEIGHT;
    vfmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    vfmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &vfmt) == -1) {
        perror("Failed to set format");
        close(fd);
        fd = -1;
        return -1;
    }

    int flags = O_RDWR | O_SYNC;
    if (fcntl(fd, F_SETFL, O_NONBLOCK) == -1) {
        perror("Failed to set non-blocking mode");
        close(fd);
        fd = -1;
        return -1;
    }

    BUFFER_SIZE = WIDTH * HEIGHT;
    buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to mmap buffer");
        close(fd);
        fd = -1;
        return -1;
    }

    buffer_fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (buffer_fd == -1) {
        perror("Failed to open /dev/mem");
        munmap(buffer, BUFFER_SIZE);
        close(fd);
        fd = -1;
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <device>\n", argv[0]);
        return 1;
    }

    const char *device = argv[1];
    if (init_camera(device) == -1) {
        return 1;
    }

    int nfds = fd + 1;
    fd_set rfds;
    FD_ZERO(&rfds);
    FD_SET(fd, &rfds);
    struct timeval tv;
    tv.tv_sec = TIMEOUT_MS / 1000;
    tv.tv_usec = (TIMEOUT_MS % 1000) * 1000;

    int ret;
    int image_count = 0;
    while (1) {
        ret = select(nfds, &rfds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("select");
            break;
        }
        if (FD_ISSET(fd, &rfds)) {
            if (read(fd, buffer, BUFFER_SIZE) != BUFFER_SIZE) {
                perror("read");
                break;
            }

            char filename[12];
            snprintf(filename, sizeof(filename), "image_%04d.pgm", ++image_count);
            FILE *fp = fopen(filename, "wb");
            if (fp == NULL) {
                perror("fopen");
                break;
            }

            fwrite("P5\n%d %d\n255\n", 1, WIDTH, fp);
            fwrite(buffer, 1, BUFFER_SIZE, fp);
            fclose(fp);
        }
    }

    munmap(buffer, BUFFER_SIZE);
    close(buffer_fd);
    close(fd);
    return 0;
}
