    fprintf(frame_log_fp, "%llu.000\n", usecs);
    fflush(frame_log_fp);
}

void *get_video_buffer() {
    if (!video_buffer) {
        if (-1 == mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, 0)) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
    }
    return video_buffer;
}

void release_video_buffer() {
    if (video_buffer && -1 != munmap(video_buffer, BUFFER_SIZE)) {
        video_buffer = NULL;
    }
}

int init_video_capture(const char *device) {
    video_fd = open(device, O_RDWR);
    if (video_fd < 0) {
