    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;

    if (-1 == ioctl(video_fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        close(video_fd);
        video_fd = -1;
        return -1;
    }

    return 0;
}

void cleanup() {
    release_video_buffer();
    if (frame_log_fp) {
        fclose(frame_log_fp);
        frame_log_fp = NULL;
    }
    if (video_fd >= 0) {
        close(video_fd);
        video_fd = -1;
    }
}

void sigint_handler(int signum) {
    signal(signum, sigint_handler);
    cleanup();
    exit(0);
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_fmtvid fmt;
    struct timespec ts;
    fd_set rdfs;
    int max_fd = video_fd;

