            void *buffers[1] = {get_video_buffer()};

            if (-1 == ioctl(video_fd, VIDIOC_DQBUF, &num_buffers > 0 ? &buffers : NULL)) {
                if (errno == EAGAIN || errno == EINTR) {
                    continue;
                }
                perror("VIDIOC_DQBUF");
                cleanup();
                return EXIT_FAILURE;
            }

            if (num_buffers > 0) {
                struct v4l2_buffer *buf = (struct v4l2_buffer *)buffers[0];
                gettimeofday(ts, NULL);
                uint64_t usecs = (ts.tv_sec * 1000000) + ts.tv_nsec / 1000;

                if (buf->type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
                    log_frame_timestamp(&buf->timestamp);
                    memcpy(video_buffer, buf->data, buf->length);

                    if (-1 == ioctl(video_fd, VIDIOC_QBUF, &buf)) {
                        perror("VIDIOC_QBUF");
                        cleanup();
                        return EXIT_FAILURE;
                    }
                }

                release_video_buffer();
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

