#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/udp.h>

#define BUFFER_COUNT 4
#define FRAME_SIZE 65000
#define MAX_FRAG_SIZE (BUFFER_COUNT * FRAME_SIZE)

struct frame_buffer {
    void *addr;
    size_t len;
};

struct frame_fragment {
    uint32_t index;
    uint32_t frag_index;
    uint32_t total_fragments;
    uint32_t payload_size;
    uint8_t data[FRAME_SIZE];
};

static volatile sig_atomic_t running = 1;
static int video_fd = -1;
static struct frame_buffer *buffers;
static struct udpsock sock;

static void signal_handler(int signum) {
    running = 0;
}

static int init_camera(const char *dev_path) {
    int fd = open(dev_path, O_RDWR);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("ioctl VIDIOC_S_FMT");
        close(fd);
        return -1;
    }

    buffers = malloc(BUFFER_COUNT * sizeof(struct frame_buffer));
    if (!buffers) {
        perror("malloc");
        close(fd);
        return -1;
    }

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        buffers[i].len = fmt.fmt.pix.sizeimage;
        buffers[i].addr = mmap(NULL, buffers[i].len, PROT_READ | PROT_WRITE, MAP_SHARED, fd, fmt.fmt.pix.pixeltype);
        if (buffers[i].addr == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return -1;
        }
    }

    return fd;
}

static void cleanup() {
    if (video_fd >= 0) {
        munmap(buffers, BUFFER_COUNT * sizeof(struct frame_buffer));
        close(video_fd);
    }

    if (sock.sock >= 0) {
        close(sock.sock);
    }

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        free(buffers[i].addr);
    }
    free(buffers);
}

static int send_frame_fragments(int fd, const uint8_t *data, size_t len) {
    uint32_t frag_size = len < FRAME_SIZE ? len : FRAME_SIZE;
    struct frame_fragment frag;

    for (size_t i = 0; i < (len + FRAME_SIZE - 1) / FRAME_SIZE; ++i) {
        frag.index = i;
        frag.frag_index = 0;
        frag.total_fragments = (size_t)i + 1;
        frag.payload_size = frag_size;

        memcpy(frag.data, data + i * FRAME_SIZE, frag_size);

        if (sendto(fd, &frag, sizeof(frag), 0, (struct sockaddr *)&sock.addr, sock.addrlen) != frag_size) {
            perror("sendto");
            return -1;
        }
    }

    return 0;
}

int main(int argc, char *argv[]) {
    struct v4l2_capability cap;
    struct v4l2_fmtvid fmt;
    struct sigaction sa;
    struct sockaddr_in sock_addr;

    sigfillset(&sa.sa_mask);
    sa.sa_handler = signal_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    sock_addr.sin_family = AF_INET;
    sock_addr.sin_port = htons(atoi(argv[2]));
    inet_pton(AF_INET, argv[1], &sock_addr.sin_addr);
    sock.sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock.sock < 0) {
        perror("socket");
        return 1;
    }
    sock.addrlen = sizeof(sock_addr);
    if (bind(sock.sock, (struct sockaddr *)&sock_addr, sock.addrlen) < 0) {
        perror("bind");
        return 1;
    }

    memset(&cap, 0, sizeof(cap));
    if (ioctl(open("/dev/video0", O_RDWR), VIDIOC_QUERYCAP, &cap) < 0) {
        perror("ioctl VIDIOC_QUERYCAP");
        cleanup();
        return 1;
    }

    if (cap.cap.caps.cap_driver & V4L2_CAP_VIDEO_CAPTURE) {
        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt.fmt.pix.width = 640;
        fmt.fmt.pix.height = 480;
        fmt.fmt.pix.pixeltype = V4L2_PIX_FMT_YUYV;
        fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

        if (ioctl(open("/dev/video0", O_RDWR), VIDIOC_S_FMT, &fmt) < 0) {
            perror("ioctl VIDIOC_S_FMT");
            cleanup();
            return 1;
        }

        video_fd = init_camera("/dev/video0");
        if (video_fd < 0) {
            cleanup();
            return 1;
        }

        while (running) {
            for (int i = 0; i < BUFFER_COUNT; ++i) {
                if (ioctl(video_fd, VIDIOC_DQBUF, &id) < 0) {
                    perror("ioctl VIDIOC_DQBUF");
                    cleanup();
                    return 1;
                }
                if (buffers[i].addr) {
                    send_frame_fragments(sock.sock, buffers[i].addr, buffers[i].len);
                    munmap(buffers[i].addr, buffers[i].len);
                    buffers[i].addr = NULL;
                }
            }

            usleep(10000); // Adjust frame rate as needed
        }
    } else {
        fprintf(stderr, "This device does not support video capture.\n");
        cleanup();
        return 1;
    }

    cleanup();
    return 0;
}

