#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define PAN_GPIO 4
#define TILT_GPIO 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

#define SERVO_PERIOD 20000  // 50 Hz
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 1500
#define DEFAULT_POSITION 750

int pan_pos = DEFAULT_POSITION;
int tilt_pos = DEFAULT_POSITION;

void sigint_handler(int signum) {
    gpiod_unrequest_all();
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *pan_line;
    struct gpiod_line *tilt_line;
    struct gpiod_line *up_line;
    struct gpiod_line *down_line;
    struct gpiod_line *left_line;
    struct gpiod_line *right_line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    ret = gpiod_chip_request_lines(chip, &pan_line, &tilt_line, &up_line, &down_line, &left_line, &right_line);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    pan_line->request.user_data = &pan_pos;
    tilt_line->request.user_data = &tilt_pos;
    up_line->request.user_data = &tilt_pos;
    down_line->request.user_data = &tilt_pos;
    left_line->request.user_data = &pan_pos;
    right_line->request.user_data = &pan_pos;

    gpiod_line_request_cooked(pan_line, PAN_GPIO);
    gpiod_line_request_cooked(tilt_line, TILT_GPIO);
    gpiod_line_request_cooked(up_line, TILT_UP_BUTTON);
    gpiod_line_request_cooked(down_line, TILT_DOWN_BUTTON);
    gpiod_line_request_cooked(left_line, PAN_LEFT_BUTTON);
    gpiod_line_request_cooked(right_line, PAN_RIGHT_BUTTON);

    signal(SIGINT, sigint_handler);

    while (1) {
        gpiod_handle_event_set(chip, &chip->event_set);

        if (gpiod_line_get_value(up_line))
            tilt_pos = (tilt_pos + 5 > 125) ? 125 : tilt_pos + 5;
        if (gpiod_line_get_value(down_line))
            tilt_pos = (tilt_pos - 5 < 25) ? 25 : tilt_pos - 5;
        if (gpiod_line_get_value(left_line))
            pan_pos = (pan_pos - 5 < 25) ? 25 : pan_pos - 5;
        if (gpiod_line_get_value(right_line))
            pan_pos = (pan_pos + 5 > 125) ? 125 : pan_pos + 5;

        gpiod_line_set_value(tilt_line, tilt_pos / 10);
        gpiod_line_set_value(pan_line, pan_pos / 10);

        usleep(50000);  // 50 ms delay
    }

    gpiod_unrequest_all();
    gpiod_chip_close(chip);
    return 0;
}

