#include <gpiod.h>
#include <jpeglib.h>

#define BUF_COUNT 2
#define WIDTH 640
#define HEIGHT 480
#define KERNEL_RADIUS 2

struct frame_data {
    int fd;
    void *mapped_memory;
    struct v4l2_buffer *buffer;
    struct timespec timestamp;
};

static int v4l2_setup(struct frame_data *fd_data) {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open video device");
        return -1;
    }

    fd_data->fd = fd;

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query video device capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        return -1;
    }

    struct v4l2_fmtdesc fmt;
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) < 0) {
        perror("Failed to enumerate video formats");
        close(fd);
        return -1;
    }

    struct v4l2_frmsizeenum size;
    memset(&size, 0, sizeof(size));
    size.pixel_format = V4L2_PIX_FMT_YUYV;
    size.discrete_size_enable = 1;
    size.selected_size.width = WIDTH;
    size.selected_size.height = HEIGHT;

    if (ioctl(fd, VIDIOC_S_FMT, &size) < 0) {
        fprintf(stderr, "Failed to set video format\n");
        close(fd);
        return -1;
    }

    fd_data->buffer = malloc(BUF_COUNT * sizeof(*fd_data->buffer));
    if (!fd_data->buffer) {
        perror("Failed to allocate memory for buffers");
        close(fd);
        return -1;
    }

    return 0;
}

static void v4l2_capture(struct frame_data *fd_data) {
    fd_data->buffer[0]->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fd_data->buffer[0]->memory = V4L2_MEMORY_MMAP;
    fd_data->buffer[0]->index = 0;
    fd_data->buffer[0]->timestamp.tv_sec = 0;
    fd_data->buffer[0]->timestamp.tv_nsec = 0;

    if (ioctl(fd_data->fd, VIDIOC_DQBUF, fd_data->buffer) < 0) {
        fprintf(stderr, "Failed to dequeue buffer\n");
        exit(-1);
    }

    fd_data->mapped_memory = mmap(NULL, fd_data->buffer[0]->length, PROT_READ | PROT_WRITE, MAP_SHARED, fd_data->fd, fd_data->buffer[0]->m.offset);
    if (mapped_memory == MAP_FAILED) {
        perror("Failed to mmap buffer");
        exit(-1);
    }

    fd_data->buffer[0]->index = -1;
    if (ioctl(fd_data->fd, VIDIOC_QBUF, fd_data->buffer) < 0) {
        fprintf(stderr, "Failed to queue buffer\n");
        exit(-1);
    }

    if (ioctl(fd_data->fd, VIDIOC_STREAMON, NULL) < 0) {
        fprintf(stderr, "Failed to start streaming\n");
        exit(-1);
    }

    fd_data->buffer[0]->timestamp = gettimeofday(NULL, NULL);
}

static void v4l2_capture_complete(struct frame_data *fd_data) {
    if (ioctl(fd_data->fd, VIDIOC_STREAMOFF, NULL) < 0) {
        fprintf(stderr, "Failed to stop streaming\n");
        exit(-1);
    }

    munmap(fd_data->mapped_memory, fd_data->buffer[0]->length);
}

