static int save_jpeg(const unsigned char *data, int width, int height, const char *filename) {
    JSAMPROW row_pointer[height];
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error;
    jpeg_create_compress(&cinfo);
    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_mem_dest(&cinfo, data, width * height * 3);

    jpeg_set_defaults(&cinfo);
    cinfo.jpeg_compress_complete = jpeg_compress_slow_to_memory;
    cinfo.quality = 75;

    if (setjmp(cinfo.jpeg_dest.longjmp_buf)) {
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    for (int y = 0; y < height; ++y) {
        row_pointer[y] = &data[y * width * 3];
    }

    jpeg_start_compress(&cinfo, TRUE);
    while (cinfo.next_scanline < height) {
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }
    jpeg_finish_compress(&cinfo);

    jpeg_destroy_compress(&cinfo);
    return 0;
}

int main() {
    struct frame_data fd_data;

    if (v4l2_setup(&fd_data) < 0) {
        return -1;
    }

    v4l2_capture(&fd_data);

    fd_data.buffer[0]->flags &= ~V4L2_BUF_FLAG_DONE;
    fd_data.buffer[0]->timestamp = gettimeofday(NULL, NULL);

    fd_data.buffer[0]->flags |= V4L2_BUF_FLAG_DONE;
    if (ioctl(fd_data.fd, VIDIOC_DQBUF, fd_data.buffer) < 0) {
        fprintf(stderr, "Failed to dequeue buffer\n");
        exit(-1);
    }

    fd_data.mapped_memory = mmap(NULL, fd_data.buffer[0]->length, PROT_READ | PROT_WRITE, MAP_SHARED, fd_data.fd, fd_data.buffer[0]->m.offset);
    if (mapped_memory == MAP_FAILED) {
        perror("Failed to mmap buffer");
        exit(-1);
    }

    unsigned char *yuyv = (unsigned char *)fd_data.mapped_memory;
    unsigned char *rgb24 = malloc(WIDTH * HEIGHT * 3);
    yuyv_to_rgb24(yuyv, rgb24, WIDTH, HEIGHT);

    unsigned char *blurred = malloc(WIDTH * HEIGHT * 3);
    box_blur(rgb24, blurred, WIDTH, HEIGHT);

    char filename[32];
    strftime(filename, sizeof(filename), "capture_%04d%02d%02d_%02d%02d.jpg",
            1900, 1, 1, 0, 0);

    if (save_jpeg(blurred, WIDTH, HEIGHT, filename) < 0) {
        fprintf(stderr, "Failed to save JPEG\n");
        exit(-1);
    }

    v4l2_capture_complete(&fd_data);
    free(rgb24);
    free(blurred);
    munmap(fd_data.mapped_memory, fd_data.buffer[0]->length);
    close(fd_data.fd);

    return 0;
}

