static int v4l2_query_device(const char *dev_path) {
    int fd = open(dev_path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open device %s\n", dev_path);
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Failed to query device capabilities\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device %s does not support video capture\n", dev_path);
        close(fd);
        return -1;
    }

    struct v4l2_frmsizeenum fs_enum;
    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fs_enum) < 0) {
        fprintf(stderr, "Failed to enumerate frame sizes\n");
        close(fd);
        return -1;
    }

    struct v4l2_frmivalenum fi_enum;
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fi_enum) < 0) {
        fprintf(stderr, "Failed to enumerate frame intervals\n");
        close(fd);
        return -1;
    }

    struct v4l2_control focus_auto;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &focus_auto) < 0) {
        fprintf(stderr, "Failed to query focus auto control\n");
        close(fd);
        return -1;
    }

    if (focus_auto.id == V4L2_CID_FOCUS_AUTO) {
        if (focus_auto.value_type == V4L2_CTRL_TYPE_INTEGER) {
            printf("Autofocus supported: Yes\n");
        } else {
            printf("Autofocus supported: No\n");
        }
    } else {
        printf("Autofocus supported: Unknown\n");
    }

    printf("Supported resolutions:\n");
    for (int i = 0; i < fs_enum.numframes; ++i) {
        printf("  %dx%d\n", fs_enum.frame_width[i], fs_enum.frame_height[i]);
    }

    printf("Supported frame rates:\n");
    for (int i = 0; i < fi_enum.numframes; ++i) {
        printf("  %d fps\n", fi_enum.step[i]);
    }

    close(fd);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <device_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    return v4l2_query_device(argv[1]);
}

