#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define PAN_GPIO 4
#define TILT_GPIO 5
#define UP_BUTTON GPIO6
#define DOWN_BUTTON GPIO7
#define LEFT_BUTTON GPIO8
#define RIGHT_BUTTON GPIO9

int pan_pos = 1500;
int tilt_pos = 1500;

void cleanup(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);
    gpioSetMode(UP_BUTTON, PI_INPUT);
    gpioSetMode(DOWN_BUTTON, PI_INPUT);
    gpioSetMode(LEFT_BUTTON, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON, PI_INPUT);

    gpioSetPullUpDown(UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON, PI_PUD_UP);

    gpioSetServoPulsewidth(PAN_GPIO, 1500);
    gpioSetServoPulsewidth(TILT_GPIO, 1500);

    printf("Pan servo on GPIO%d, Tilt servo on GPIO%d\n", PAN_GPIO, TILT_GPIO);
    printf("Center position: Pan=%d, Tilt=%d\n", pan_pos, tilt_pos);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        static int pan_dir = 0;
        static int tilt_dir = 0;

        if (gpioRead(UP_BUTTON) == 0) {
            pan_dir = 1;
        } else if (gpioRead(DOWN_BUTTON) == 0) {
            pan_dir = -1;
        } else if (gpioRead(LEFT_BUTTON) == 0) {
            tilt_dir = -1;
        } else if (gpioRead(RIGHT_BUTTON) == 0) {
            tilt_dir = 1;
        }

        if (pan_dir != 0) {
            pan_pos += pan_dir;
            if (pan_pos < 1000) {
                pan_pos = 1000;
                pan_dir = 0;
            } else if (pan_pos > 2000) {
                pan_pos = 2000;
                pan_dir = 0;
            }
            gpioSetServoPulsewidth(PAN_GPIO, pan_pos);
        }

        if (tilt_dir != 0) {
            tilt_pos += tilt_dir;
            if (tilt_pos < 1000) {
                tilt_pos = 1000;
                tilt_dir = 0;
            } else if (tilt_pos > 2000) {
                tilt_pos = 2000;
                tilt_dir = 0;
            }
            gpioSetServoPulsewidth(TILT_GPIO, tilt_pos);
        }

        usleep(50000);
    }

    gpioTerminate();
    return 0;
}

