#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 11
#define CAMERA_WIDTH 640
#define CAMERA_HEIGHT 480
#define QUALITY 85
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_MS 2000

static volatile sig_atomic_t sigint_received = 0;

void signal_handler(int signum) {
    sigint_received = 1;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PULLDOWN);
}

void setup_camera_path() {
    char path[1024];
    snprintf(path, sizeof(path), "/home/pi/motion_captures/%s_%ld.jpg", __FUNCTION__, (long)time(NULL));
    mkdir("motion_captures", 0755);
}

void capture_image(const char *path) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "libcamera-still -w %d -h %d -q %d -o %s", CAMERA_WIDTH, CAMERA_HEIGHT, QUALITY, path);
    system(cmd);
}

void poll_motion() {
    while (!sigint_received) {
        int motion_state = gpioRead(GPIO_PIN);

        if (motion_state == 0) {
            gpioWrite(GPIO_PIN, 1);
            gpioSetPulsePair(GPIO_PIN, 0, DEBOUNCE_MS);

            setup_camera_path();
            capture_image(gpioGetFilePath(GPIO_PIN));

            gpioWrite(GPIO_PIN, 0);
        }

        gpioWaitEvent(GPIO_PIN, PI_FALLING, POLL_INTERVAL_MS);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    setup_gpio();
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioTerminate();
    curl_global_init(CURL_GLOBAL_ALL);

    setup_camera_path();

    poll_motion();

    gpioTerminate();
    curl_global_cleanup();

    return 0;
}

