#include <gpiod.hpp>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define DEBOUNCE_TIMEOUT_MS 50
#define CAMERA_WIDTH 640
#define CAMERA_HEIGHT 480
#define JPEG_QUALITY 85
#define CAMERA_TIMEOUT 2000

static gpiod_chip chip;
static gpiod_line line;
static FILE *log_file;

void init_logging() {
    log_file = fopen("/home/pi/motion_capture.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup_logging() {
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    gpiod_chip_unclaim(chip);
    if (line.fd >= 0) {
        close(line.fd);
    }
    cleanup_logging();
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

void setup_gpio() {
    int ret;

    ret = gpiod_chip_open(&chip, "GPIO17");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = chip.request_add(&line, GPIO_PIN);
    if (ret < 0) {
        perror("Failed to claim GPIO pin");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_direction(&line, GPIO_DIR_IN);
    if (ret < 0) {
        perror("Failed to set GPIO direction");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_pull(&line, GPIO_PULL_UP);
    if (ret < 0) {
        perror("Failed to set GPIO pull-up");
        gpiod_chip_close(line.fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_edge_detect(&line, GPIO_EDGE_FALLING);
    if (ret < 0) {
        perror("Failed to set edge detection");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void capture_image(const char *timestamp) {
