#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <signal.h>

#define CROP_X 100
#define CROP_Y 50
#define CROP_W 200
#define CROP_H 150

int video_fd = -1;

void sigint_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        v4l2_stop_streaming();
        exit(EXIT_SUCCESS);
    }
}

void v4l2_stop_streaming() {
    if (video_fd != -1) {
        ioctl(video_fd, VIDIOC_STREAMOFF);
        close(video_fd);
        video_fd = -1;
    }
}

int v4l2_init() {
    struct v4l2_capability cap;
    video_fd = open("/dev/video0", O_RDWR);

    if (video_fd == -1) {
        perror("Failed to open /dev/video0");
        return -1;
    }

    if (ioctl(video_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query V4L2 device capabilities");
        close(video_fd);
        return -1;
    }

    if (cap.cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        struct v4l2_fmtdesc fmt_desc;
        struct v4l2_cropcap crop_cap;
        struct v4l2_crop crop;
        struct v4l2_frmsizeenum size_enum;
        struct v4l2_capability cap_out;

        memset(&fmt_desc, 0, sizeof(fmt_desc));
        fmt_desc.index = 0;
        fmt_desc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

        if (ioctl(video_fd, VIDIOC_ENUM_FMT, &fmt_desc) < 0) {
            perror("Failed to enumerate formats");
            goto err_close;
        }

        fmt_desc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt_desc.format = V4L2_PIX_FMT_YUYV;

        if (ioctl(video_fd, VIDIOC_S_FMT, &fmt_desc) < 0) {
            perror("Failed to set format");
            goto err_close;
        }

        memset(&crop_cap, 0, sizeof(crop_cap));
        crop_cap.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        crop_cap.c.x = CROP_X;
        crop_cap.c.y = CROP_Y;
        crop_cap.c.width = CROP_W;
        crop_cap.c.height = CROP_H;

        if (ioctl(video_fd, VIDIOC_CROP, &crop_cap) < 0) {
            perror("Failed to set crop area");
            goto err_close;
        }

        memset(&size_enum, 0, sizeof(size_enum));
        size_enum.pixel_aspect.numerator = 1;
        size_enum.pixel_aspect.denominator = 1;
        size_enum.discrete_size_enable = 1;
        size_enum.selected_size.width = 640;
        size_enum.selected_size.height = 480;

        if (ioctl(video_fd, VIDIOC_ENUM_FRAMESIZES, &size_enum) < 0) {
            perror("Failed to enumerate frame sizes");
            goto err_close;
        }

        if (size_enum.framesizes[0].width != 640 || size_enum.framesizes[0].height != 480) {
            fprintf(stderr, "Warning: Requested frame size (640x480) not available, using default.\n");
        }

        if (ioctl(video_fd, VIDIOC_S_FRAMESIZES, &size_enum.selected_size) < 0) {
            perror("Failed to set frame size");
            goto err_close;
        }

        if (ioctl(video_fd, VIDIOC_REQBUFS, &num_buffers) < 0) {
            perror("Failed to request buffers");
            goto err_close;
        }

        if (num_buffers < 1) {
            fprintf(stderr, "Error: Not enough buffers requested.\n");
            goto err_close;
        }

        buffers = (v4l2_buffer *)malloc(num_buffers * sizeof(v4l2_buffer));
        if (!buffers) {
            fprintf(stderr, "Memory allocation failed.\n");
            goto err_close;
        }

        for (int i = 0; i < num_buffers; i++) {
            if (ioctl(video_fd, VIDIOC_QUERYBUF, &buf_desc) < 0) {
                perror("Failed to query buffer");
                goto err_close;
            }
            buffers[i].index = buf_desc.index;
            buffers[i].type = buf_desc.type;
            buffers[i].memory] = buf_desc.memory;
            buffers[i].bytesused = buf_desc.bytesused;
        }

        if (ioctl(video_fd, VIDIOC_QBUF, &buf_desc) < 0) {
            perror("Failed to queue buffer");
            goto err_close;
        }

        if (ioctl(video_fd, VIDIOC_STREAMON) < 0) {
            perror("Failed to start streaming");
            goto err_close;
        }

        return 0;
    err_close:
        v4l2_stop_streaming();
    } else {
        fprintf(stderr, "Error: /dev/video0 is not a video capture device.\n");
        return -1;
    }
}

int v4l2_capture_frame(void) {
    int ret;
    struct v4l2_buffer buf;
    struct timeval tv;
    fd_set rdf;

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        FD_ZERO(&rdf);
        FD_SET(video_fd, &rdf);

        ret = select(video_fd + 1, NULL, NULL, NULL, &tv);
        if (ret < 0) {
            perror("select");
            return -1;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for frame.\n");
            return -1;
        }

        if (FD_ISSET(video_fd, &rdf)) {
            if (ioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("Failed to dequeue buffer");
                return -1;
            }

            if (buf.type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
                unsigned char *data = (unsigned char *)mmap(NULL, buf.length, PROT_READ, MAP_SHARED, video_fd, buf.m.offset);
                if (data == MAP_FAILED) {
                    perror("mmap");
                    return -1;
                }

                int width = buf.fields[0].width;
                int height = buf.fields[0].height;
                int bytes_per_pixel = (buf.fmt.pix.num_bytes == 0) ? 2 : 1;
                int y_offset = 0;
                int uv_offset = 1;

                FILE *fp = fopen("cropped.yuv", "wb");
                if (!fp) {
                    perror("fopen");
                    munmap(data, buf.length);
                    return -1;
                }

                for (int y = CROP_Y; y < CROP_Y + CROP_H; y++) {
                    for (int x = CROP_X; x < CROP_X + CROP_W; x++) {
                        unsigned char *y0_ptr = data + y * width * bytes_per_pixel + x * bytes_per_pixel;
                        unsigned char *u_ptr = data + (y * width / 2 + (x / 2)) * bytes_per_pixel;
                        unsigned char *v_ptr = data + (y * width / 2 + (x / 2) + 1) * bytes_per_pixel;

                        fwrite(y0_ptr, 1, 2, fp);
                        fwrite(u_ptr, 1, 1, fp);
                        fwrite(v_ptr, 1, 1, fp);
                    }
                }

                fclose(fp);
                munmap(data, buf.length);
                ioctl(video_fd, VIDIOC_QBUF, &buf);
            }
        }
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int ret;

    ret = v4l2_init();
    if (ret < 0) {
        return EXIT_FAILURE;
    }

    ret = v4l2_capture_frame();
    if (ret < 0) {
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

