#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define PWM_FREQ 50
#define DEGREE_TO_US 10
#define US_TO_DEGREE (57.3) // (180 / 360)

int pan_angle = 90;
int tilt_angle = 90;

void set_servo_angle(int gpio, int angle) {
    int pulse_width = (angle * DEGREE_TO_US) + 500; // 500 us at 0 degrees, 2500 us at 180 degrees
    gpioPulseLength(gpio, gpio, pulse_width);
}

void handle_signal(int signum) {
    if (signum == SIGINT || !strcmp(stdin->c_str(), "q\n")) {
        printf("Setting servos to neutral position...\n");
        pan_angle = 90;
        tilt_angle = 90;
        set_servo_angle(PAN_GPIO, pan_angle);
        set_servo_angle(TILT_GPIO, tilt_angle);
        gpioTerminate();
        exit(0);
    }
}

int main() {
    signal(SIGINT, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQ);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQ);

    while (1) {
        char input;
        scanf(" %c", &input);

        switch (input) {
            case 'w':
                pan_angle = (pan_angle > 0) ? pan_angle - 5 : 0;
                break;
            case 's':
                pan_angle = (pan_angle < 180) ? pan_angle + 5 : 180;
                break;
            case 'a':
                tilt_angle = (tilt_angle > 0) ? tilt_angle - 5 : 0;
                break;
            case 'd':
                tilt_angle = (tilt_angle < 180) ? tilt_angle + 5 : 180;
                break;
            case 'q':
            case '\n':
                goto neutral_position;
            default:
                continue;
        }

        usleep(100 * 1000); // 100 ms delay

        set_servo_angle(PAN_GPIO, pan_angle);
        set_servo_angle(TILT_GPIO, tilt_angle);

    neutral_position:
        if (pan_angle > 180 || pan_angle < 0 || tilt_angle > 180 || tilt_angle < 0) {
            printf("Error: Angle out of range. Please reset the servos and try again.\n");
            pan_angle = 90;
            tilt_angle = 90;
        }
    }

cleanup:
    gpioTerminate();
    return 0;
}

