        switch (input) {
            case 'w':
                pan_angle = (pan_angle > 0) ? pan_angle - 5 : 0;
                break;
            case 's':
                pan_angle = (pan_angle < 180) ? pan_angle + 5 : 180;
                break;
            case 'a':
                tilt_angle = (tilt_angle > 0) ? tilt_angle - 5 : 0;
                break;
            case 'd':
                tilt_angle = (tilt_angle < 180) ? tilt_angle + 5 : 180;
                break;
            case 'q':
            case '\n':
                goto neutral_position;
            default:
                continue;
        }

        usleep(100 * 1000); // 100 ms delay

        set_servo_angle(PAN_GPIO, pan_angle);
        set_servo_angle(TILT_GPIO, tilt_angle);

    neutral_position:
        if (pan_angle > 180 || pan_angle < 0 || tilt_angle > 180 || tilt_angle < 0) {
            printf("Error: Angle out of range. Please reset the servos and try again.\n");
            pan_angle = 90;
            tilt_angle = 90;
        }
    }

cleanup:
    gpioTerminate();
    return 0;
}
