#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define PULSES_PER_LITER 7.5

volatile float flow_rate = 0.0;
int pulse_count = 0;

void sigint_handler(int signum) {
    pigpio_stop();
    wiringPiI2CClose(lcd_fd);
    exit(0);
}

void setup() {
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(1);
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_OFF);
    gpioSetAlert(FLOW_SENSOR_GPIO, PI_RISING_EDGE, 0);

    if (wiringPiI2CInit() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus.\n");
        pigpio_terminate();
        exit(1);
    }

    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd < 0) {
        fprintf(stderr, "Failed to open I2C device for LCD.\n");
        pigpio_terminate();
        wiringPiI2CClose(lcd_fd);
        exit(1);
    }
}

void loop() {
    int pulse_timeout = 1000000; // 1 second
    int pulse_count_timeout = 60000000; // 60 seconds

    while (1) {
        pulse_count = 0;

        // Wait for pulses or timeout
        if (pigpio_wait_for_edge(FLOW_SENSOR_GPIO, PI_RISING_EDGE, pulse_timeout) > 0) {
            pulse_count = pigpio_count_edges(FLOW_SENSOR_GPIO);
        }

        if (pulse_count > 0) {
            flow_rate = (float)pulse_count / PULSES_PER_LITER;
            pulse_count = 0;
        }

        // Update LCD display
        update_lcd();

        // Check for no pulses over extended period
        if (pulse_count < 100000) { // Adjust this value as needed
            usleep(100000);
            continue;
        }

        printf("No pulses detected for extended period. Exiting...\n");
        break;
    }
}

void update_lcd() {
    static int row = 0;
    static int lcd_init = 0;

    if (!lcd_init) {
        lcd_init = 1;
        i2c_write8(lcd_fd, 0x01, 0x02); // Clear display
        i2c_write8(lcd_fd, 0x01, 0x0C); // Return home
        i2c_write8(lcd_fd, 0x01, 0x02); // Entry mode set
        i2c_write8(lcd_fd, 0x01, 0x00); // Display on, cursor off
        i2c_write8(lcd_fd, 0x06, 'F'); // Set cursor to second line
        i2c_write8(lcd_fd, 0x01, 0x0E); // Display on, cursor off
        i2c_write8(lcd_fd, 0x06, ' '); // Move cursor to start of line
    }

    if (row == 0) {
        i2c_write8(lcd_fd, 0x06, 'F'); // Set cursor to first line
        i2c_write8(lcd_fd, 0x01, "Flow Rate:");
    } else {
        char flow_str[10];
        snprintf(flow_str, sizeof(flow_str), "%.2f", flow_rate);
        i2c_write8(lcd_fd, 0x06, ' '); // Move cursor to start of line
        i2c_write8(lcd_fd, 0x01, flow_str);
    }

    row ^= 1;
}

int main(int argc, char **argv) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup();

    loop();

    pigpio_stop();
    wiringPiI2CClose(lcd_fd);

    return 0;
}

