#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define LED_MATRIX_ROWS 8
#define SCAN_DELAY_US 800

// GPIO assignments
const int ledMatrixRows[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int ledMatrixCols[] = {5, 6, 12, 13, 19, 16, 26, 20};

// Wave patterns
const uint8_t *wavePatterns[2] = {
    {0x3F, 0x06, 0x09, 0x51, 0x59, 0x79, 0x7F, 0x01}, // Left-to-right
    {0x01, 0x79, 0x59, 0x09, 0x51, 0x06, 0x3F, 0x00} // Right-to-left
};

int currentPattern = 0;

void scanRow(int row) {
    gpiod_chip_remove_file_events(chip);
    for (int col = 0; col < LED_MATRIX_ROWS; col++) {
        gpiod_trigger_output(line[row][col], 0);
    }
    usleep(SCAN_DELAY_US);
    for (int col = 0; col < LED_MATRIX_ROWS; col++) {
        gpiod_trigger_output(line[row][col], 1);
    }
}

void setupGPIO() {
    struct gpiod_chip *chip;
    struct gpiod_line *line[LED_MATRIX_ROWS][LED_MATRIX_COLS];
    int i, j;

    chip = gpiod_chip_open("/dev/gpiod", NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return;
    }

    for (i = 0; i < LED_MATRIX_ROWS; i++) {
        for (j = 0; j < LED_MATRIX_COLS; j++) {
            line[i][j] = gpiod_chip_get_line(chip, ledMatrixRows[i]);
            if (!line[i][j]) {
                fprintf(stderr, "Failed to get line for row %d, col %d\n", ledMatrixRows[i], ledMatrixCols[j]);
                return;
            }
            gpiod_line_export(line[i][j], NULL);
            gpiod_line_set_direction(line[i][j], GPIO_OUTPUT);
        }
    }
}

void cleanupGPIO() {
    int i, j;
