#define I2C_BUS 1
#define SENSOR_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define SAMPLE_INTERVAL 100000 // 100 milliseconds in microseconds

static FILE *log_file = NULL;

void log_distance(uint16_t distance) {
    if (log_file != NULL) {
        fprintf(log_file, "%lu,%u\n", time(NULL), distance);
        fflush(log_file);
    }
}

int main() {
    int ret;
    gpioInitialise();

    // Open I2C bus
    if ((ret = gpioI2COpen(I2C_BUS, &i2c_handle)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", ret);
        return 1;
    }

    // Open the sensor
    if ((ret = gpioI2CWrite(i2c_handle, SENSOR_ADDR << 1 | 0, 1)) < 0) {
        fprintf(stderr, "Error writing to sensor register\n");
        goto i2c_close;
    }

    uint8_t buf[3];
    if ((ret = gpioI2CRead(i2c_handle, SENSOR_ADDR << 1 | DISTANCE_REG, 2, buf, 2)) < 0) {
        fprintf(stderr, "Error reading from sensor register\n");
        goto i2c_write;
    }

    uint16_t distance = (buf[1] << 8) | buf[0];
    log_distance(distance);

i2c_write:
    gpioI2CClose(i2c_handle);
    i2c_handle = NULL;

i2c_close:
    if (i2c_handle != NULL) {
        gpioI2CClose(i2c_handle);
        i2c_handle = NULL;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    if (ret != 0) {
        return 1;
    }

    // Initialize the log file
    if ((log_file = fopen("depth_log.csv", "a")) == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    if (fputc('\n', log_file) == EOF) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }

    // Start sampling loop
    while (1) {
        sleep_us(SAMPLE_INTERVAL);

        if (i2c_handle == NULL) {
            // Re-open I2C handle on failure
            if ((ret = gpioI2COpen(I2C_BUS, &i2c_handle)) < 0) {
                fprintf(stderr, "Error reopening I2C bus: %d\n", ret);
                break;
            }

            if ((ret = gpioI2CWrite(i2c_handle, SENSOR_ADDR << 1 | 0, 1)) < 0) {
                fprintf(stderr, "Error writing to sensor register\n");
                goto i2c_close_sample;
