            if ((ret = gpioI2CRead(i2c_handle, SENSOR_ADDR << 1 | DISTANCE_REG, 2, buf, 2)) < 0) {
                fprintf(stderr, "Error reading from sensor register\n");
                goto i2c_write_sample;
            }

            distance = (buf[1] << 8) | buf[0];
            log_distance(distance);

i2c_write_sample:
            gpioI2CClose(i2c_handle);
            i2c_handle = NULL;
        }

        log_distance(-1); // Log -1 as error if I2C read fails

i2c_close_sample:
        if (i2c_handle != NULL) {
            gpioI2CClose(i2c_handle);
            i2c_handle = NULL;
        }
    }

    gpioTerminate();
    return 0;
}

