    if (i2cWrite(i2c_fd, COMMAND_REG, &command, 1) != 1) {
        fprintf(stderr, "Failed to write to COMMAND register\n");
        fclose(log_file);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        time_t now_sec = time(NULL);
        struct tm *now_tm = localtime(&now_sec);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

        uint16_t proximity, ambient;
        if (i2cRead(i2c_fd, 0x02, &proximity, 2) != 2) {
            fprintf(stderr, "I2C read failed mid-loop\n");
            continue;
        }

        fprintf(log_file, "%s: Proximity=%d, Ambient=%d\n", timestamp, proximity, ambient);

        usleep(500000);
    }

    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
