            gpiod_line_unexport(sensor_line);
        } else {
            gpiod_line_unexport(sensor_line);
            gpiod_chip_list_free(chip_list);
        }
    } else {
        gpiod_chip_list_free(chip_list);
    }

    fclose(log_file);
    return 0;
}

