#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define SI1145_I2C_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x08
#define MEAS_RATE_PS_REG 0x09
#define MEAS_RATE_ALS_REG 0x0A
#define COMMAND_REG 0x30
#define PS1_REG_LOW 0x18
#define PS1_REG_HIGH 0x19
#define ALS_VIS_REG_LOW 0x22
#define ALS_VIS_REG_HIGH 0x23

#define CHECK_I2C_RC(rc) if ((rc) != GPIO_I2C_OK) { \
    fprintf(stderr, "I2C error: %d\n", (rc)); \
    goto err_exit; }

void err_exit(void) {
    gpioTerminate();
    exit(EXIT_FAILURE);
}

int main(void) {
    int fd;
    gpioInitialise();
    fd = gpioI2cOpen(1, SI1145_I2C_ADDR);
    CHECK_I2C_RC(fd);

    uint8_t part_id;
    CHECK_I2C_RC(gpioI2cWrite(fd, PART_ID_REG, &part_id, 1));
    if (part_id != 0x45) {
        fprintf(stderr, "Invalid part ID: 0x%02X\n", part_id);
        goto err_exit;
    }

    uint8_t hw_key = 0x17;
    CHECK_I2C_RC(gpioI2cWrite(fd, HW_KEY_REG, &hw_key, 1));

    uint8_t ch_list = 0x4F;
    CHECK_I2C_RC(gpioI2cWrite(fd, CH_LIST_REG, &ch_list, 1));

    uint8_t meas_rate_ps = 0x01; // e.g., 1 Hz
    CHECK_I2C_RC(gpioI2cWrite(fd, MEAS_RATE_PS_REG, &meas_rate_ps, 1));

    uint8_t meas_rate_als = 0x01; // e.g., 1 Hz
    CHECK_I2C_RC(gpioI2cWrite(fd, MEAS_RATE_ALS_REG, &meas_rate_als, 1));

    uint8_t command = 0x06 | (1 << 1); // ALS_FORCE
    CHECK_I2C_RC(gpioI2cWrite(fd, COMMAND_REG, &command, 1));

    command = 0x07 | (1 << 0); // PS_FORCE
    CHECK_I2C_RC(gpioI2cWrite(fd, COMMAND_REG, &command, 1));

    uint16_t proximity, ambient_light;
    while (1) {
        CHECK_I2C_RC(gpioI2cRead(fd, PS1_REG_HIGH, &proximity));
        CHECK_I2C_RC(gpioI2cRead(fd, PS1_REG_LOW, &proximity));
        proximity = (proximity << 8) | (uint8_t)proximity;

        CHECK_I2C_RC(gpioI2cRead(fd, ALS_VIS_REG_HIGH, &ambient_light));
        CHECK_I2C_RC(gpioI2cRead(fd, ALS_VIS_REG_LOW, &ambient_light));
        ambient_light = (ambient_light << 8) | (uint8_t)ambient_light;

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        FILE *log_file = fopen("biometric_data.log", "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            goto err_exit;
        }
        fprintf(log_file, "%s, %d, %d\n", timestamp, proximity, ambient_light);
        fclose(log_file);

        sleep(1);
    }

err_exit:
    gpioI2cClose(fd);
    gpioTerminate();
    return 0;
}

void sigint_handler(int signum) {
    gpioTerminate();
    fclose(stdout);
    fclose(stderr);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    return main();
}

