#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <stdbool.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 27
#define VOLTAGE_DIVIDER_RATIO 2.0
#define TRIG_PULSE_US 10
#define TIMEOUT_MS 30000
#define POLLING_INTERVAL_S 60
#define MIN_DISTANCE_CM 15
#define MAX_DISTANCE_CM 400

struct distance_measurement {
    double distance_cm;
    struct timespec timestamp;
};

void log_measurement(const struct distance_measurement *dm) {
    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", localtime(&dm->timestamp.tv_sec));
    fprintf(stderr, "%s: %f cm\n", timestamp_str, dm->distance_cm);
}

int main() {
    struct gpiod_chipchip *chi;
    struct gpiod_chip_line *line;
    struct gpiod_chip_line *trigger_line;
    struct gpiod_chip_line *echo_line;
    struct distance_measurement dm;
    FILE *log_file = fopen("distance_log.txt", "w");
    bool running = true;

    gpiod_chip_init(0);

    chi = gpiod_chip_open(0, "rpi-gpio");
    if (!chi) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chi, "GPIO17");
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chi);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chi, "GPIO27");
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_chip_close(chi);
        return 1;
    }

    if (gpiod_line_export(trigger_line, "user") < 0 || gpiod_line_export(echo_line, "user") < 0) {
        fprintf(stderr, "Failed to export GPIO lines\n");
        gpiod_chip_close(chi);
        return 1;
    }

    gpiod_line_set_config(trigger_line, 0, GPIOD_OUTPUT, 0, 0);
    gpiod_line_set_config(echo_line, 0, GPIOD_INPUT, 0, 0);

    // Voltage divider setup
    gpiod_line_set_pull(echo_line, GPIOD_PULL_DOWN);

    // Register callbacks
    gpiod_line_set_event_handler(trigger_line, 0, &on_trigger_event, NULL);
    gpiod_line_set_event_handler(echo_line, GPIOD_EVENT_RISING | GPIOD_EVENT_FALLING, &on_echo_event, NULL);

    while (running) {
        // Wait for trigger pulse
