#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x39
#define PROX_THRESHOLD 200
#define RGB_REG_START 0x96
#define PROX_REG 0x9C

static FILE *csv_file = NULL;
static gpio pigpio_handle = GPIO_UNINITIALIZED;

void sigint_handler(int signum) {
    gpioTerminate();
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(1);
    }
}

void init_apds9960(int fd) {
    if (i2c_open(fd) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        exit(1);
    }

    if (i2c_rdwr(fd, 0x92, NULL, 0, NULL, 0) != 2) {
        fprintf(stderr, "Failed to read sensor ID register.\n");
        i2c_close(fd);
        gpioTerminate();
        exit(1);
    }

    uint8_t sensor_id = i2c_rdwr(fd, 0x92, &i2c_buf, 1, NULL, 0)[0];
    if (sensor_id != 0xAB) {
        fprintf(stderr, "Invalid sensor ID.\n");
        i2c_close(fd);
        gpioTerminate();
        exit(1);
    }

    // Configure APDS9960
    i2c_rdwr(fd, 0x80, &enable_reg, 1, NULL, 0);
    i2c_rdwr(fd, 0x81, &atime_reg, 1, NULL, 0);
    i2c_rdwr(fd, 0x83, &wtime_reg, 1, NULL, 0);
    i2c_rdwr(fd, 0x8E, &ppulse_reg, 1, NULL, 0);
    i2c_rdwr(fd, 0xF1, &control_reg, 1, NULL, 0);
    i2c_rdwr(fd, 0x90, &config2_reg, 1, NULL, 0);
}

void read_apds9960(int fd) {
    uint16_t red, green, blue;
    uint8_t proximity;

    if (i2c_rdwr(fd, 0x96, &red, 2, NULL, 0) != 3) {
        fprintf(stderr, "Failed to read RGB registers.\n");
        return;
    }

    if (i2c_rdwr(fd, 0x97, &green, 2, NULL, 0) != 3) {
        fprintf(stderr, "Failed to read RGB registers.\n");
        return;
    }

    if (i2c_rdwr(fd, 0x98, &blue, 2, NULL, 0) != 3) {
        fprintf(stderr, "Failed to read RGB registers.\n");
        return;
    }

    if (i2c_rdwr(fd, 0x9C, &proximity, 1, NULL, 0) != 2) {
        fprintf(stderr, "Failed to read proximity register.\n");
        return;
    }

    if (proximity > PROX_THRESHOLD) {
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);

        if (csv_file == NULL) {
            csv_file = fopen("color_proximity_log.csv", "w");
            if (csv_file == NULL) {
                fprintf(stderr, "Failed to open CSV file.\n");
                gpioTerminate();
                exit(1);
            }
            fprintf(csv_file, "Timestamp,Red,Green,Blue,Proximity\n");
        }

        fprintf(csv_file, "%ld,%d,%d,%d,%d\n", (long)lt->tm_hour * 3600 + lt->tm_min * 60 + lt->tm_sec, red, green, blue, proximity);
        fflush(csv_file);
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_pigpio();
    int fd = i2c_open(1);
    init_apds9960(fd);

    while (1) {
        read_apds9960(fd);
        gpioDelay(100000);
    }

    gpioTerminate();
    if (csv_file != NULL) {
        fclose(csv_file);
    }

    return 0;
}

