    gpiod_chip_init(&chip, "GPIO0");
    gpiod_add_override(&chip, 12, GPIOD_LINE_INPUT, "sigint-handler");
    gpiod_export(&chip);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set 7-bit slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t part_id;
    if (i2c_read_byte_data(i2c_fd, PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        close(i2c_fd);
        return 1;
    }

    if (part_id != 0x11) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X\n", part_id);
        close(i2c_fd);
        return 1;
    }

    uint8_t rate_value = 0x01; // Set to 1 Hz
    if (i2c_write_byte_data(i2c_fd, MEAS_RATE0, rate_value) < 0) {
        fprintf(stderr, "Failed to write MEAS_RATE0 register\n");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_byte_data(i2c_fd, COMMAND, 0x01) < 0) {
        fprintf(stderr, "Failed to write COMMAND register\n");
        close(i2c_fd);
        return 1;
    }

    csv_file = fopen("heartrate.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open heartrate.csv\n");
        close(i2c_fd);
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H-%M-%S", localtime(&ts.tv_sec));

    while (running) {
        uint16_t proximity_data = 0;

        if (i2c_read_word_data(i2c_fd, PS_DATA0, &proximity_data) < 0) {
            fprintf(stderr, "Failed to read PS_DATA0 register\n");
            continue;
        }

        if (i2c_read_word_data(i2c_fd, PS_DATA1, &proximity_data) < 0) {
            fprintf(stderr, "Failed to read PS_DATA1 register\n");
            continue;
        }

        proximity_data = (proximity_data << 8) | (uint16_t)proximity_data;

        // Placeholder BPM calculation
        int bpm = proximity_data * 2; // Just an example, replace with actual calculation

        fprintf(csv_file, "%s,%d\n", timestamp, bpm);
        fflush(csv_file);

        usleep(100000);
    }

    fclose(csv_file);
    close(i2c_fd);
    gpiod_unexport(&chip);

    return 0;
}

