#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_ADDR 0x45
#define SAMPLE_INTERVAL 200000 // 200 ms in µs
#define TRIG_PIN 18
#define ECHO_PIN 23
#define BUFFER_SIZE 32

static FILE *log_file = NULL;

void log_distance(int distance) {
    static char timestamp[BUFFER_SIZE];
    time_t now;
    struct tm *time_struct;

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, BUFFER_SIZE, "%F %T", time_struct);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    printf("%s, %d\n", timestamp, distance);
}

int main() {
    int i2c_fd;
    int ret;

    // Initialize pigpio library
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_fd = i2c_open(1, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        piGPIO_terminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(i2c_fd);
        piGPIO_terminate();
        return 1;
    }

    while (1) {
        // Trigger the ultrasonic sensor
        piGPIO_set_mode(TRIG_PIN, PI_OUTPUT);
        piGPIO_write(TRIG_PIN, 1);
        piGPIO_write(TRIG_PIN, 0);

        // Wait for echo pulse
        piGPIO_set_mode(ECHO_PIN, PI_INPUT);
        ret = piGPIO_pulse_setup(ECHO_PIN, 100000, 100000);
        if (ret < 0) {
            fprintf(stderr, "Failed to set up pulse on ECHO_PIN\n");
            break;
        }

        ret = piGPIO_wait_for_pulse(ECHO_PIN);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for pulse on ECHO_PIN\n");
            break;
        }

        // Read distance (in cm) from I2C
        uint16_t distance_cm = i2c_read_word_data(i2c_fd, I2C_ADDR);
        int distance_mm = distance_cm * 10; // Convert to mm

        log_distance(distance_mm);

        // Sleep for the sample interval
        piGPIO_sleep(SAMPLE_INTERVAL);
    }

    // Close the log file
    fclose(log_file);

    // Close I2C handle and terminate pigpio
    i2c_close(i2c_fd);
    piGPIO_terminate();

    return 0;
}

void sigint_handler(int signo) {
    if (signo == SIGINT) {
        fprintf(stderr, "Received SIGINT, cleaning up...\n");
        // Close log file, I2C handle, and terminate pigpio
        fclose(log_file);
        i2c_close(i2c_fd);
        piGPIO_terminate();
        exit(0);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, sigint_handler);

    // Call the main loop
    return main_loop();
}

