#define SENSOR_PINS 17, 18
#define NUM_SENSORS (sizeof SENSOR_PINS / sizeof SENSOR_PINS[0])

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static int read_sensor(int pin) {
    int value;
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO\n");
        return -1;
    }

    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode for sensor pin\n");
        gpioTerminate();
        return -1;
    }

    gpioSetOutput(pin);
    delay(10); // Ensure the pin is set before reading
    if (gpioRead(pin) < 0) {
        fprintf(stderr, "Error: Failed to read sensor value\n");
        return -1;
    }
    value = gpioRead(pin);
    gpioTerminate();
    return value;
}

int main() {
    struct timespec ts;
    gpioInit();

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to set SIGINT handler\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; ++i) {
        if (gpioSetMode(SENSOR_PINS[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO mode for sensor pin %d\n", SENSOR_PINS[i]);
            return 1;
        }
    }

    FILE *log_file = fopen("obstacle_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
    }

    while (!sigint_received) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        for (int i = 0; i < NUM_SENSORS; ++i) {
            int sensor_value = read_sensor(SENSOR_PINS[i]);
            if (sensor_value == -1)
                continue;

            fprintf(log_file, "%s Sensor %d: %d\n", timestamp, SENSOR_PINS[i], sensor_value);
        }

        usleep(100000); // Sleep for 100 milliseconds
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

