#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SI1182_ADDR 0x60
#define REG_PROX 0x18
#define REG_LIGHT 0x16
#define MAX_RETRIES 3
#define LOG_FILE "biometric_log.txt"

static FILE *log_file = NULL;
static gpio i2c_gpio = -1;

void log_reading(uint16_t proximity, uint16_t light) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld: Proximity = 0x%04X, Light = 0x%04X\n", now, proximity, light);
        fflush(log_file);
    }
}

int read_register(int fd, uint8_t reg_addr, uint16_t *data, int retries) {
    int ret;
    *data = 0;

    for (int i = 0; i < retries; ++i) {
        ret = pigpio_i2c_rdwr(fd, SI1182_ADDR, &reg_addr, 1, data, 2, 0);
        if (ret >= 0) {
            return ret;
        }
        printf("Failed to read register, retrying (%d/%d)\n", i + 1, MAX_RETRIES);
        sleep(100); // short delay before retry
    }

    return -1;
}

int main() {
    struct timespec ts;
    int fd;
    uint16_t proximity, light;

    // Initialize pigpio library
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO for I2C bus 1
    i2c_gpio = gpioInitialise();
    if (i2c_gpio < 0) {
        fprintf(stderr, "Failed to initialize GPIO for I2C\n");
        pigpio_terminate();
        return 1;
    }

    fd = pigpio_open(i2c_gpio, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        pigpio_terminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_close(fd, 1);
        pigpio_terminate();
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        proximity = light = 0;

        for (int i = 0; i < MAX_RETRIES; ++i) {
            if (read_register(fd, REG_PROX, &proximity, i + 1) < 0) {
                continue;
            }
            break;
        }

        for (int i = 0; i < MAX_RETRIES; ++i) {
            if (read_register(fd, REG_LIGHT, &light, i + 1) < 0) {
                continue;
            }
            break;
        }

        log_reading(proximity, light);
        usleep(500000); // Sleep for 500 ms
    }

    // Clean up
    fclose(log_file);
    pigpio_close(fd, 1);
    pigpio_terminate();
    gpioTerminate(i2c_gpio);

    return 0;
}

void sigint_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "Received SIGINT, cleaning up and exiting...\n");
        if (log_file != NULL) {
            fclose(log_file);
            log_file = NULL;
        }
        if (fd >= 0) {
            pigpio_close(fd, 1);
            fd = -1;
        }
        pigpio_terminate();
        gpioTerminate(i2c_gpio);
        exit(0);
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    return main_loop();
}

