        fprintf(log_file, "%ld: Proximity = 0x%04X, Light = 0x%04X\n", now, proximity, light);
        fflush(log_file);
    }
}

int read_register(int fd, uint8_t reg_addr, uint16_t *data, int retries) {
    int ret;
    *data = 0;

    for (int i = 0; i < retries; ++i) {
        ret = pigpio_i2c_rdwr(fd, SI1182_ADDR, &reg_addr, 1, data, 2, 0);
        if (ret >= 0) {
            return ret;
        }
        printf("Failed to read register, retrying (%d/%d)\n", i + 1, MAX_RETRIES);
        sleep(100); // short delay before retry
    }

    return -1;
}

int main() {
    struct timespec ts;
    int fd;
    uint16_t proximity, light;

    // Initialize pigpio library
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO for I2C bus 1
    i2c_gpio = gpioInitialise();
    if (i2c_gpio < 0) {
        fprintf(stderr, "Failed to initialize GPIO for I2C\n");
        pigpio_terminate();
        return 1;
    }

    fd = pigpio_open(i2c_gpio, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        pigpio_terminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_close(fd, 1);
        pigpio_terminate();
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        proximity = light = 0;

        for (int i = 0; i < MAX_RETRIES; ++i) {
            if (read_register(fd, REG_PROX, &proximity, i + 1) < 0) {
                continue;
            }
            break;
        }

        for (int i = 0; i < MAX_RETRIES; ++i) {
            if (read_register(fd, REG_LIGHT, &light, i + 1) < 0) {
                continue;
            }
            break;
        }

        log_reading(proximity, light);
        usleep(500000); // Sleep for 500 ms
    }

    // Clean up
    fclose(log_file);
    pigpio_close(fd, 1);
    pigpio_terminate();
    gpioTerminate(i2c_gpio);

    return 0;
}

void sigint_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "Received SIGINT, cleaning up and exiting...\n");
        if (log_file != NULL) {
            fclose(log_file);
            log_file = NULL;
        }
        if (fd >= 0) {
            pigpio_close(fd, 1);
            fd = -1;
        }
        pigpio_terminate();
        gpioTerminate(i2c_gpio);
        exit(0);
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    return main_loop();
}
```

This code initializes the pigpio library, sets up GPIO for I2C communication on bus 1, opens the specified I2C device file descriptor, and opens the log file. It then enters a loop where it reads proximity and ambient light data from the Si1182 sensor every 500 ms, logging the readings with timestamps. The code retries failed I2C read operations up to three times and handles SIGINT (Ctrl+C) gracefully by cleaning up resources and terminating the pigpio library before exiting.

