#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define SENSOR_ADDR 0x50
#define CYCLE_DELAY 100000 // 100 ms in microseconds
#define SAMPLE_COUNT 10
#define MIN_DISTANCE 1000

int i2c_fd = -1;
FILE *log_file = NULL;

void log_event(double timestamp, double avg_distance) {
    if (log_file != NULL) {
        fprintf(log_file, "%f, %f\n", timestamp, avg_distance);
        fflush(log_file);
    }
}

int main() {
    int ret;
    struct i2c_rdwr_ioctl_data rdwr_data;
    unsigned char cmd_frame[] = {0x50, 0x0A, 0x00, 0x01};
    unsigned char response[15];
    int16_t distance_sum = 0;
    double avg_distance;
    time_t timestamp;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        timestamp = time(NULL);
        distance_sum = 0;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            rdwr_data.msgs = &response;
            rdwr_data.nmsgs = 1;
            rdwr_data.flags = 0;

            if (write(i2c_fd, cmd_frame, 4) != 4) {
                fprintf(stderr, "Failed to write to I2C bus\n");
                break;
            }

            if (ioctl(i2c_fd, I2C_RDWR, &rdwr_data) != 0) {
                fprintf(stderr, "Failed to read from I2C bus\n");
                break;
            }

            if (response[0] != 0x50) {
                fprintf(stderr, "Invalid header received\n");
                break;
            }

            distance_sum += (int16_t)(response[11] << 8 | response[12]);
            usleep(CYCLE_DELAY);
        }

        avg_distance = (double)distance_sum / SAMPLE_COUNT;
        if (avg_distance < MIN_DISTANCE) {
            log_event(timestamp, avg_distance);
            printf("Intrusion detected! Average distance: %f mm\n", avg_distance);
        }
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

void sigint_handler(int signo) {
    if (signo == SIGINT) {
        printf("\nCleaning up and exiting...\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    // Rest of the main function remains the same as above
}

