#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define VL53L0X_ADDR 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define MODEL_ID_REG 0xC0

int main() {
    struct timespec ts;
    int fd;
    gpioInitialise();
    if (gpioFailed()) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    if (pigpioRequest(1, &fd) < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (i2c_rdwr_start(fd) < 0) {
        fprintf(stderr, "Failed to start I2C transaction: %s\n", strerror(errno));
        close(fd);
        gpioTerminate();
        return 1;
    }

    uint8_t model_id;
    if (i2c_rdwr(fd, VL53L0X_ADDR, &model_id, 1) != 1) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        close(fd);
        gpioTerminate();
        return 1;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Invalid model ID: 0x%02X (expected 0xEE)\n", model_id);
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        ts.tv_sec = 0;
        ts.tv_nsec = 500 * 1000 * 1000;
        if (i2c_rdwr_wait(fd, &ts) < 0) {
            fprintf(stderr, "I2C timeout while waiting for range data: %s\n", strerror(errno));
            continue;
        }

        if (i2c_rdwr(fd, VL53L0X_ADDR, &model_id, 1) != 1) {
            fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
            continue;
        }

        if (model_id != 0xEE) {
            fprintf(stderr, "Invalid model ID: 0x%02X (expected 0xEE)\n", model_id);
            continue;
        }

        if (i2c_rdwr(fd, VL53L0X_ADDR, NULL, 0) != 0) {
            fprintf(stderr, "Failed to write to SYSRANGE_START: %s\n", strerror(errno));
            continue;
        }

        int range_found = 0;
        while (!range_found) {
            uint8_t ris;
            if (i2c_rdwr(fd, VL53L0X_ADDR, &ris, 1) != 1) {
                fprintf(stderr, "Failed to read RESULT_INTERRUPT_STATUS: %s\n", strerror(errno));
                continue;
            }

            if (ris & 0x01) {
                range_found = 1;
            } else {
                if (i2c_rdwr_wait(fd, &ts) < 0) {
                    fprintf(stderr, "I2C timeout while waiting for range data: %s\n", strerror(errno));
                    range_found = 1;
                    break;
                }
            }
        }

        if (!range_found) {
            fprintf(stderr, "Timeout while waiting for range data\n");
            continue;
        }

        uint16_t distance;
        if (i2c_rdwr(fd, VL53L0X_ADDR, &distance, 2) != 2) {
            fprintf(stderr, "Failed to read RESULT_RANGE_STATUS: %s\n", strerror(errno));
            continue;
        }

        distance = (distance[1] << 8) | distance[0];
        if (i2c_rdwr(fd, VL53L0X_ADDR, &model_id, 1) != 1) {
            fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
            continue;
        }

        if (model_id != 0xEE) {
            fprintf(stderr, "Invalid model ID: 0x%02X (expected 0xEE)\n", model_id);
            continue;
        }

        if (i2c_rdwr(fd, VL53L0X_ADDR, &system_interrupt_clear, 1) != 1) {
            fprintf(stderr, "Failed to write to SYSTEM_INTERRUPT_CLEAR: %s\n", strerror(errno));
            continue;
        }

        printf("Distance: %d mm\n", distance);
    }

    close(fd);
    gpioTerminate();
    return 0;
}

