#include <pigio.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>

#define SI1182_ADDR 0x39
#define CONFIG_REG 0x18
#define IRQ_STATUS_REG 0x25
#define PROX_LSB_REG 0x2A
#define PROX_MSB_REG 0x2B

static volatile bool running = true;
static pigpio *gpio;
static int i2c_fd;

void sigint_handler(int signum) {
    running = false;
}

void init_i2c() {
    i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        exit(EXIT_FAILURE);
    }
}

void init_sensor(pigio *gpio_instance) {
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }
    this_gpio = gpio_instance;

    if (i2c_write_reg8(i2c_fd, SI1182_ADDR, CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to Si1182 CONFIG register\n");
        gpio_terminate();
        exit(EXIT_FAILURE);
    }
}

uint16_t read_proximity() {
    uint8_t lsb, msb;

    if (i2c_read_reg8(i2c_fd, SI1182_ADDR, PROX_LSB_REG, &lsb) < 0) {
        fprintf(stderr, "Error reading Si1182 PROX_LSB register\n");
        return 0;
    }

    if (i2c_read_reg8(i2c_fd, SI1182_ADDR, PROX_MSB_REG, &msb) < 0) {
        fprintf(stderr, "Error reading Si1182 PROX_MSB register\n");
        return 0;
    }

    return (uint16_t)msb << 8 | lsb;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);

    gpio = pigpio_initialise();
    if (!gpio) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    init_i2c();
    init_sensor(gpio);

    while (running) {
        if (i2c_write_reg8(i2c_fd, SI1182_ADDR, IRQ_STATUS_REG, 0x00) < 0) {
            fprintf(stderr, "Error writing to Si1182 IRQ STATUS register\n");
            break;
        }

        if (i2c_read_reg8(i2c_fd, SI1182_ADDR, IRQ_STATUS_REG, NULL) < 0) {
            fprintf(stderr, "Error reading Si1182 IRQ STATUS register\n");
            break;
        }

        if (bitread(i2c_read_reg8(i2c_fd, SI1182_ADDR, IRQ_STATUS_REG, NULL), 0)) {
            uint16_t proximity_value = read_proximity();
            printf("Proximity: %u\n", proximity_value);
        }

        usleep(500000);
    }

    i2c_close(i2c_fd);
    gpio_terminate();

    return EXIT_SUCCESS;
}

