#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>

#define MLX75030_ADDR 0x4C
#define REG_DISTANCE 0x00
#define MM_PER_COUNT 0.125

static int i2c_fd = -1;

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main() {
    struct i2c_rdwr_ioctl_data rdwr_data;
    int i2c_addr = MLX75030_ADDR;
    int ret;

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Verify device response
    rdwr_data.u8 = 0;
    if (ioctl(i2c_fd, I2C_SLAVE, 0) < 0) {
        fprintf(stderr, "Device not responding, exiting...\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        rdwr_data.u8 = REG_DISTANCE;
        rdwr_data.len = 2;
        rdwr_data.addr = i2c_addr << 1;

        if ((ret = ioctl(i2c_fd, I2C_RDWR, &rdwr_data)) < 0) {
            fprintf(stderr, "I2C read failed with error %d\n", errno);
            continue;
        }

        uint16_t distance_raw = (rdwr_data.data[0] << 8) | rdwr_data.data[1];
        double distance_mm = distance_raw * MM_PER_COUNT;

        printf("Distance: %.2f mm\n", distance_mm);

        nanosleep(&sleep_time, NULL);
    }

    close(i2c_fd);
    return 0;
}

