#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3101_ADDR 0x44
#define CHANNEL_0 0x00

static int gpio_init = 0;
static int i2c_init = 0;

void sigint_handler(int signum) {
    gpioTerminate();
    pigpio_stop();
    exit(0);
}

int main() {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library.\n");
        return 1;
    }
    gpio_init = 1;

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        gpioTerminate();
        return 1;
    }

    if (i2c_init_check(1) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus 1.\n");
        pigpio_terminate();
        gpioTerminate();
        return 1;
    }

    while (1) {
        int distance, ambient_light, error_flags;
        if (i2c_read_word(OPT3101_ADDR, CHANNEL_0, &distance, &ambient_light, &error_flags) < 0) {
            fprintf(stderr, "I2C communication error.\n");
            break;
        }

        printf("Distance: %d, Ambient Light: %d, Error Flags: %d\n", distance, ambient_light, error_flags);

        usleep(500000);
    }

    pigpio_terminate();
    gpioTerminate();
    return 0;
}

int i2c_init_check(int bus_num) {
    int fd;
    struct i2c_rdwr_ioctl_data rdwr;
    struct i2c_dev_id dev_id;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    rdwr.flags = 0;
    rdwr.len = 2;
    rdwr.buf = &dev_id;

    if (ioctl(fd, I2C_RDWR, &rdwr) < 0) {
        close(fd);
        return -1;
    }

    if (dev_id.vendor != 0x0B || dev_id.device != 0x31) {
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int i2c_read_word(int addr, int reg, int *distance, int *ambient_light, int *error_flags) {
    int fd;
    struct i2c_rdwr_ioctl_data rdwr;
    uint8_t request[2];

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    request[0] = (addr << 1) | 0x01; // Address | Write bit | Register
    request[1] = (addr << 1) | (reg << 1) | 0x01; // Address | Write bit | Register & Channel

    rdwr.flags = 0;
    rdwr.len = 2;
    rdwr.buf = (void *)request;

    if (ioctl(fd, I2C_RDWR, &rdwr) < 0) {
        close(fd);
        return -1;
    }

    if (pigpio_read(gpioGetModeForPin(PIN_GPIO0), 2, request) < 0) {
        close(fd);
        return -1;
    }

    *distance = (request[1] >> 4) & 0x0F;
    *ambient_light = request[1] & 0x0F;
    *error_flags = gpioGetModeForPin(PIN_GPIO0) & 0x01;

    close(fd);
    return 0;
}

