#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_RANGE 200  // cm
#define TIMEOUT_MS 200
#define TICK_INTERVAL 1000000  // 1 second in microseconds

static volatile int running = 1;
static int pulse_width_us = 0;

void sigint_handler(int signum) {
    running = 0;
}

void setup_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    if (gpioSetPullUpDown(ECHO_PIN) < 0) {
        fprintf(stderr, "Failed to set pull-up/pull-down on ECHO_PIN.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_pigpio();

    gpioSetOutputLevel(TRIG_PIN, 0);

    while (running) {
        gpioTrigger(TRIG_PIN, 0, TICK_INTERVAL);

        int timeout = gpioWaitRisingEdge(ECHO_PIN, TIMEOUT_MS * 1000000);
        if (timeout < 0) {
            fprintf(stderr, "Echo timeout occurred.\n");
            break;
        }

        int falling_edge = gpioWaitFallingEdge(ECHO_PIN, TIMEOUT_MS * 1000000);
        if (falling_edge < 0) {
            fprintf(stderr, "Echo falling-edge timeout occurred.\n");
            break;
        }

        pulse_width_us = gpioGetLevel(ECHO_PIN) ? gpioReadClockCounts(ECHO_PIN) - timeout : 0;

        if (pulse_width_us <= 0 || pulse_width_us > MAX_RANGE) {
            fprintf(stderr, "Invalid pulse duration: %d us\n", pulse_width_us);
            break;
        }

        double distance_cm = (pulse_width_us * 0.0343) / 2;
        time_t now = time(NULL);
        printf("Timestamp: %s, Distance: %.2f cm\n", ctime(&now), distance_cm);

        // Sleep for the remaining time to maintain 1-second interval
        struct timespec rem_time;
        rem_time.tv_sec = 0;
        rem_time.tv_nsec = TICK_INTERVAL - (timespecToMsecs(rem_time).tv_nsec);
        nanosleep(&rem_time, NULL);
    }

    gpioTerminate();
    return 0;
}

