#include <fcntl.h>
#include <time.h>
#include <pigio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define DIST_THRESHOLD 1.0
#define BUF_SIZE 144 // 8 (magic word) + 64 (range bins) * 2 (16-bit integers)

struct timespec ts;
int serial_fd;
int gpio_led;

void init_uart() {
    struct termios term;
    if (tcgetattr(serial_fd, &term) != 0) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    memset(&term, 0, sizeof(term));
    term.c_cflag = B9600 | CS8 | CLOCAL | CREAD;
    if (tcflush(serial_fd, TCIFLUSH) != 0) {
        perror("tcflush");
        exit(EXIT_FAILURE);
    }

    term.c_iflag = IGNPAR;
    term.c_oflag = 0;
    term.c_lflag = 0;

    if (tcsetattr(serial_fd, TCSANOW, &term) != 0) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_range_profile(int fd) {
    uint16_t range_profile[64];
    int i;

    if (read(fd, &range_profile, BUF_SIZE) != BUF_SIZE) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    return range_profile[0];
