#include <signal.h>
#include <string.h>
#include <libgpiod.h>

#define OBSTACLE_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL 100000 // 100 ms in microseconds

static gpiod_chip *chip;
static int obstacle_line;
static int buzzer_line;
static FILE *log_file;

static void sigint_handler(int signum) {
    gpiod_chip_unrequest(chip);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

static void setup_gpio(gpiod_chip *chip) {
    int ret;

    ret = gpiod_chip_request_lines(chip, &obstacle_line, NULL, "Obstacle Sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request obstacle line: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }
    gpiod_line_request_set_value(obstacle_line, 1);

    ret = gpiod_chip_request_lines(chip, &buzzer_line, NULL, "Buzzer");
    if (ret < 0) {
        fprintf(stderr, "Failed to request buzzer line: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }
    gpiod_line_request_set_value(buzzer_line, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void cleanup_gpio() {
    gpiod_line_release(obstacle_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_unrequest(chip);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void poll_obstacle() {
    int value;
    time_t now;
    struct tm *time_info;

    while (true) {
        time(&now);
        time_info = localtime(&now);

        value = gpiod_line_get_value(obstacle_line);
        if (value == 0) {
            fprintf(log_file, "[%04ld-%02d-%02dT%02d:%02d:%02d.%03d] Obstacle detected\n",
                    1900 + time_info->tm_year,
                    1 + time_info->tm_mon,
                    time_info->tm_mday,
                    time_info->tm_hour,
                    time_info->tm_min,
                    time_info->tm_sec,
                    (int)((time_info->tm_isdst ? 0 : 1) + time_info->tm_sec / 2));

            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(POLL_INTERVAL);
    }
}

int main(int argc, char *argv[]) {
    int ret;
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    ret = gpiod_new(&chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(ret));
        return EXIT_FAILURE;
    }

    ret = gpiod_chip_find("GPIO17-E18-D80NK", 0, &chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to find the sensor chip: %s\n", gpiod_strerror(ret));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    setup_gpio(chip);

    ret = gpiod_chip_start(chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to start GPIO chip: %s\n", gpiod_strerror(ret));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    poll_obstacle();

    cleanup_gpio();
    return EXIT_SUCCESS;
}

