#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define CHIP_I2C_ADDR 0x69
#define DISTANCE_REG_HIGH 0x31
#define DISTANCE_REG_LOW 0x32
#define GPIO_ALERT 17
#define SAMPLE_INTERVAL_MS 100

static pigio *pi = NULL;
static gpio chip_i2d = -1;
static gpio alert_gpio = -1;
FILE *log_file = NULL;

void cleanup() {
    if (pi) pigpio_terminate(pi);
    if (chip_i2d != -1) gpio_set_function(chip_i2d, PI_OUTPUT);
    if (alert_gpio != -1) gpio_set_function(alert_gpio, PI_OUTPUT);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void sigint_handler(int signum) {
    cleanup();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pi = g_pi;

    chip_i2d = gpio_initialise(CHIP_I2C_ADDR);
    if (chip_i2d < 0) {
        fprintf(stderr, "I2C chip initialisation failed\n");
        pigpio_terminate(pi);
        return 1;
    }
    gpio_set_mode(chip_i2d, PI_OUTPUT);

    alert_gpio = gpio_initialise(GPIO_ALERT);
    if (alert_gpio < 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        gpio_terminate(chip_i2d);
        pigpio_terminate(pi);
        return 1;
    }
    gpio_set_mode(alert_gpio, PI_OUTPUT);

    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    while (1) {
        if (pigpio_signal_wait(pi, GPIO_ALERT, HIGH, SAMPLE_INTERVAL_MS * 1000) == 0) {
            break;
        }

        uint16_t distance_high = gpio_read(chip_i2d + DISTANCE_REG_HIGH);
        uint16_t distance_low = gpio_read(chip_i2d + DISTANCE_REG_LOW);

        if (distance_high == 0xFF || distance_low == 0xFF) {
            fprintf(stderr, "Sensor absence or I2C error\n");
            continue;
        }

        uint32_t distance = (uint32_t)distance_high << 8 | distance_low;
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", g_localtime);

        fprintf(log_file, "%s, Distance: %u cm\n", timestamp, distance);

        if (distance < 100) { // Assuming distance is in mm
            gpio_write(alert_gpio, 1);
        } else {
            gpio_write(alert_gpio, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    fclose(log_file);
    return 0;
}

