code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define DISTANCE_FILE "distance_log.csv"
#define MAX_DISTANCE 1200
#define POLL_INTERVAL 100
#define SYSTEM_MODE_START 0x007
#define SYSTEM_INTERRUPT_CLEAR 0x014
#define RESULT_INTERRUPT_STATUS 0x013
#define RESULT_RANGE_STATUS 0x078
#define MODEL_ID_REG 0x010F
#define SOFTWARE_RESET 0x0000
#define SYSRANGE_START 0x000

int i2c_fd;
pig_client *pi;
FILE *log_file;

void sigint_handler(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    pig_stop(pi);
    if (log_file) fclose(log_file);
    exit(0);
}

void init_i2c() {
    i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        exit(1);
    }
}

void init_pigpio() {
    pi = pig_init();
    if (!pi) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
    pig_claim_irq(pi, 1); // Claim IRQ 1 for VL53L1X
}

void check_model_id() {
    uint8_t model_id;
    i2c_rdwr_ptr(i2c_fd, 0x29, &model_id, 1);
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID, sensor not detected\n");
        pig_stop(pi);
        exit(1);
    }
}

void software_reset_sensor() {
    i2c_wr_ptr(i2c_fd, 0x29, &SOFTWARE_RESET, 1);
    usleep(2000);
}

void start_continuous_ranging() {
    i2c_wr_ptr(i2c_fd, 0x29, &SYSTEM_MODE_START, 1);
}

int poll_sysrange_start() {
    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = POLL_INTERVAL * 1000000;

    while (1) {
        if (i2c_rdwr_dbg(i2c_fd, 0x29, &SYSRANGE_START, 1, NULL, 0) == 1) {
            return 1;
        }
        if (clock_gettime(CLOCK_MONOTONIC, &timeout) && timeout.tv_sec > 0) {
            fprintf(stderr, "Timeout waiting for SYSRANGE__START\n");
            return 0;
        }
    }
}

uint16_t read_distance() {
    uint16_t distance;
    i2c_rdwr_ptr(i2c_fd, 0x29, &distance, sizeof(distance));
    return distance;
}

void clear_interrupt() {
    i2c_wr_ptr(i2c_fd, 0x29, &SYSTEM_INTERRUPT_CLEAR, 1);
}

void log_distance(uint16_t dist) {
    static int file_created = 0;
    if (!file_created) {
        log_file = fopen(DISTANCE_FILE, "w");
        if (!log_file) {
            fprintf(stderr, "Failed to create distance log file\n");
            exit(1);
        }
        fprintf(log_file, "timestamp,distance_mm\n");
        file_created = 1;
    }
    char timestamp[32];
    time_t t = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));
    fprintf(log_file, "%s,%d\n", timestamp, dist);
    fflush(log_file);
}

void print_parking_guidance(uint16_t dist) {
    switch (dist) {
        case uint16_t{0}:
        case uint16_t{...}: // Add more thresholds as needed
            printf("STOP\n");
            break;
        case uint16_t{300}:
        case uint16_t{...}: // Add more thresholds as needed
            printf("APPROACH\n");
            break;
        case uint16_t{600}:
        case uint16_t{...}: // Add more thresholds as needed
            printf("SLOW\n");
            break;
        default:
            printf("CLEAR\n");
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    init_i2c();
    init_pigpio();
    check_model_id();
    software_reset_sensor();
    start_continuous_ranging();

    if (!poll_sysrange_start()) {
        fprintf(stderr, "Failed to start continuous ranging\n");
        pig_stop(pi);
        i2c_close(i2c_fd);
        exit(1);
    }

    while (1) {
        clear_interrupt();
        if (i2c_rdwr_dbg(i2c_fd, 0x29, &RESULT_INTERRUPT_STATUS, 1, NULL, 0) == 1) {
            uint16_t dist = read_distance();
            log_distance(dist);
            print_parking_guidance(dist);
        }
        pig_sleep(100 * 1000);
    }

    pig_stop(pi);
    i2c_close(i2c_fd);
    if (log_file) fclose(log_file);

    return 0;
}

