#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x45
#define LED_PIN 18
#define MAX_RETRIES 3
#define RETRY_DELAY 10000

volatile int running = 1;
pig_client *client;

void sigint_handler(int signum) {
    running = 0;
}

void setup_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    client = pigpio(0, 0);
    if (!client) {
        fprintf(stderr, "Failed to create pigpio client\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_led() {
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetOutput(LED_PIN, 0);
}

void setup_i2c() {
    if (pigio_i2c_open(client, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

uint16_t read_distance(int retry_count) {
    uint16_t distance = 0;
    for (int i = 0; i <= retry_count; ++i) {
        int res = pigio_i2c_read(client, 2, (uint8_t *)&distance, 1);
        if (res >= 0) {
            return distance;
        }
        if (i < MAX_RETRIES) {
            printf("I2C read failed, retrying in %d ms\n", RETRY_DELAY);
            sleep(RETRY_DELAY / 1000);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
            exit(EXIT_FAILURE);
        }
    }
    return 0;
}

void cleanup() {
    gpioTerminate();
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_pigpio();
    setup_led();
    setup_i2c();

    while (running) {
        uint16_t distance = read_distance(MAX_RETRIES);
        if (distance) {
            double freq = map_distance_to_frequency(distance);
            gpioWrite(LED_PIN, (int)(freq * 50)); // half-cycle
            printf("Distance: %d mm, Frequency: %.2f Hz, Time: %lu\n", distance, freq, time(NULL));
        }
        sleep(0.1);
    }

    cleanup();
    pigio_i2c_close(client);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetOutput(LED_PIN, 0);

    return 0;
}

double map_distance_to_frequency(uint16_t distance) {
    double freq = (distance - 50) * (1 / 450); // 50 mm -> 10 Hz, 500 mm -> 1 Hz
    return clamp(freq, 0, 20); // clamp between 0 and 20 Hz
}

double clamp(double value, double min, double max) {
    return fmax(min, fmin(value, max));
}

