#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MLX75030_ADDR 0x29
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3

static int retry_count = 0;
static const int max_retries = MAX_RETRIES;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

void setup_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(0, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

int write_mlx75030(uint8_t value) {
    int ret;

    for (ret = 0; ret < max_retries; ret++) {
        if (gpioWrite(0, value) < 0) {
            fprintf(stderr, "I2C write failed, retrying...\n");
            delay(10000); // Wait for 10ms before retrying
        } else {
            break;
        }
    }

    if (ret == max_retries) {
        fprintf(stderr, "Max retries reached for I2C write.\n");
        return -1;
    }

    return 0;
}

uint16_t read_mlx75030() {
    uint16_t distance;
    int ret;

    for (ret = 0; ret < max_retries; ret++) {
        if (gpioRead(0) < 0) {
            fprintf(stderr, "I2C read failed, retrying...\n");
            delay(10000); // Wait for 10ms before retrying
        } else {
            distance = (gpioRead(0) << 8) | gpioRead(1);
            break;
        }
    }

    if (ret == max_retries) {
        fprintf(stderr, "Max retries reached for I2C read.\n");
        return -1;
    }

    return distance;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_pigpio();

    FILE *fp = fopen("distance_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open distance_log.csv for writing.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        write_mlx75030(MLX75030_ADDR);
        delay(SAMPLE_INTERVAL_MS * 1000 / 10); // Delay for SAMPLE_INTERVAL_MS ms

        uint16_t distance = read_mlx75030();
        if (distance != -1) {
            time_t now = time(NULL);
            fprintf(fp, "%ld,%d\n", (long)now, distance);
            fflush(fp);
        } else {
            fprintf(stderr, "Error reading distance data, skipping sample.\n");
        }
    }

    gpioTerminate();
    fclose(fp);
    return 0;
}

