#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define DEBOUNCE_TIME_MS 50
#define POLL_INTERVAL_MS 10

enum sensor_id { SENSOR_1, SENSOR_2 };
enum event_type { DETECTED, CLEARED };

void log_event(enum sensor_id sensor, enum event_type event) {
    static FILE *log_file = NULL;
    static int log_file_initialized = 0;

    if (!log_file_initialized) {
        log_file = fopen("proximity_log.txt", "w");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            exit(EXIT_FAILURE);
        }
        log_file_initialized = 1;
    }

    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", local_time);

    fprintf(log_file, "%s %d %s\n", timestamp, (int)sensor, (event == DETECTED) ? "DETECTED" : "CLEARED");
    fflush(log_file);
}

int main() {
    int sensor_states[2] = {0};
    int poll_index = 0;
    int event_type = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_OUTPUT) < 0 || gpioSetMode(SENSOR_2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 || gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetOutputHigh(SENSOR_1_PIN);
    gpioSetOutputHigh(SENSOR_2_PIN);

    while (1) {
        gpioRead(SENSOR_1_PIN, &event_type);
        if (event_type & (1 << SENSOR_1_PIN)) {
            sensor_states[SENSOR_1] = 0;
        } else {
            sensor_states[SENSOR_1] = 1;
        }

        gpioRead(SENSOR_2_PIN, &event_type);
        if (event_type & (1 << SENSOR_2_PIN)) {
            sensor_states[SENSOR_2] = 0;
        } else {
            sensor_states[SENSOR_2] = 1;
        }

        if (poll_index % (DEBOUNCE_TIME_MS + POLL_INTERVAL_MS) == 0) {
            for (int i = 0; i < 2; i++) {
                if (sensor_states[i] != sensor_states[(i + 1) % 2]) {
                    log_event(i, sensor_states[i] ? CLEARED : DETECTED);
                    sensor_states[i] = sensor_states[(i + 1) % 2];
                }
            }
        }

        poll_index++;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    fclose(log_file);

    return 0;
}

