#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define DEVICE "/dev/i2c-1"
#define TDK_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define POLL_TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

int i2c_fd = -1;

int i2c_open() {
    i2c_fd = open(DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

void i2c_close() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int i2c_ioctl(unsigned int fd, unsigned int ioctl_cmd, unsigned long arg) {
    if (ioctl(fd, ioctl_cmd, arg) == -1) {
        perror("Failed to perform I2C ioctl");
        return -1;
    }
    return 0;
}

int i2c_write_then_read(int fd, unsigned char reg_addr, unsigned char reg_val, unsigned char *reg_data, int len) {
    struct i2c_rdwr_ioctl_data rdwr;

    rdwr.addr = TDK_ADDR;
    rdwr.flags = 0;
    rdwr.len = len;
    rdwr.data = reg_data;

    if (i2c_ioctl(fd, I2C_RDWR, &rdwr) == -1)
        return -1;

    rdwr.flags = I2C_M_RD;
    if (i2c_ioctl(fd, I2C_RDWR, &rdwr) == -1)
        return -1;

    return 0;
}

int main() {
    int ret;
    struct timespec ts;
    FILE *fp;

    if (i2c_open() != 0)
        return EXIT_FAILURE;

    ret = i2c_ioctl(i2c_fd, I2C_SLAVE, TDK_ADDR);
    if (ret != 0)
        return EXIT_FAILURE;

    fp = fopen("distance_log.csv", "w");
    if (!fp) {
        perror("Failed to open CSV file");
        i2c_close();
        return EXIT_FAILURE;
    }

    while (1) {
        // Trigger measurement
        if (write(i2c_fd, &MEAS_TRIGGER, 1) != 1) {
            fprintf(stderr, "Failed to write to TDK CH-101 MEAS_TRIGGER register\n");
            continue;
        }

        // Poll MEAS_STATUS until data-ready bit is set
        unsigned char reg_data[2];
        struct timespec start_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        while (1) {
            if (i2c_write_then_read(i2c_fd, MEAS_STATUS, 0, reg_data, 2) != 0) {
                fprintf(stderr, "Failed to read from TDK CH-101 MEAS_STATUS register\n");
                break;
            }

            if ((reg_data[0] & 0x01) != 0) {
                break;
            }

