#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define MLX75030_ADDR 0x4C
#define RETRY_COUNT 3
#define RETRY_DELAY 10000 // 10 ms

static const uint8_t reg_distance_ms = 0x00;

static int i2c_read(uint8_t reg, uint8_t *data, int len) {
    int ret;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        ret = pi_i2c_read_reg_byte(gpio, MLX75030_ADDR, reg);
        if (ret >= 0) {
            *data = ret;
            return 1;
        }
        if (i < RETRY_COUNT - 1) {
            pi_sleep(RETRY_DELAY);
        }
    }
    return -1;
}

int main() {
    gpioInitialise();

    int fd = pi_i2c_open(gpio, 1);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        goto exit_cleanup;
    }

    if (pi_i2c_address(fd, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        pi_i2c_close(fd);
        goto exit_cleanup;
    }

    uint16_t distance_ms;
    while (1) {
        if (i2c_read(reg_distance_ms, &distance_ms, sizeof(distance_ms)) < 0) {
            fprintf(stderr, "Failed to read distance after retries\n");
            break;
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t timestamp = (uint64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000;

        printf("Distance: %u ms at %llu ms\n", distance_ms, timestamp);

        pi_sleep(100000); // Sleep for 100 ms
    }

exit_cleanup:
    if (fd >= 0) {
        pi_i2c_close(fd);
    }
    gpioTerminate();

    return 0;
}

