#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define VL53L4CX_ADDR 0x29
#define SOFT_RESET_REG 0x7FFF
#define START_RANGE_REG 0x0009
#define INT_STATUS_REG 0x0046
#define DIST_HIGH_REG 0x0096
#define DIST_LOW_REG 0x0097
#define POLL_INTERVAL 500000

static pigpio *gpio;
static int i2c_fd;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    const char *dev = "/dev/i2c-1";
    int ret;

    // Initialize pigpio
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", gpioError());
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open I2C bus
    if ((i2c_fd = open(dev, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open %s\n", dev);
        gpioTerminate();
        return 1;
    }

    // Set up pigpio I2C
    if ((ret = gpioSetMode(i2c_fd, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set I2C mode: %s\n", gpioError());
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Perform startup sequence
    if (gpioI2CWrite(i2c_fd, VL53L4CX_ADDR, SOFT_RESET_REG, &soft_reset_val, 1) < 0) {
        fprintf(stderr, "Failed to write soft reset\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    usleep(10000);

    if (gpioI2CWrite(i2c_fd, VL53L4CX_ADDR, START_RANGE_REG, &start_range_val, 1) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Poll interrupt status
        if (gpioI2CRead(i2c_fd, VL53L4CX_ADDR, INT_STATUS_REG, &int_status_val, 1) < 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            continue;
        }

        if (int_status_val & 0x01) {
            // Read distance
            if (gpioI2CRead(i2c_fd, VL53L4CX_ADDR, DIST_HIGH_REG, &dist_high_val, 1) < 0) {
                fprintf(stderr, "Failed to read high distance byte\n");
                continue;
            }

            if (gpioI2CRead(i2c_fd, VL53L4CX_ADDR, DIST_LOW_REG, &dist_low_val, 1) < 0) {
                fprintf(stderr, "Failed to read low distance byte\n");
                continue;
            }

            uint32_t distance = (dist_high_val << 8) | dist_low_val;
            char timestamp[32];
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            printf("%s.%06llu, Distance: %u mm\n", timestamp, ts.tv_nsec, distance);
        }

        usleep(POLL_INTERVAL);
    }

    // Clean up
    gpioTerminate();
    close(i2c_fd);
    return 0;
}

