static void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO as output for buzzer
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioSetOutputLevel(BUZZER_GPIO, 0); // Buzzer off initially
}

// Release pigpio resources
static void release_pigpio() {
    gpioTerminate();
}

// Configure VL53L1X sensor
static void configure_sensor() {
    uint8_t buf[] = {0x0001, 0x0001, 0x0007, 0x0096};

    if (pi_i2cWrite(VL53L1X_I2C_ADDR, buf, 4) < 0) {
        fprintf(stderr, "Error writing to VL53L1X sensor.\n");
        return;
    }

    // Set continuous ranging mode
    if (pi_i2cWrite(VL53L1X_I2C_ADDR, (uint8_t[]){0x0001}, 1) < 0) {
        fprintf(stderr, "Error setting continuous ranging mode.\n");
        return;
    }
}

// Read distance from VL53L1X sensor
static uint16_t read_distance() {
    uint8_t buf[3];
    if (pi_i2cRead(VL53L1X_I2C_ADDR, buf, 3) < 0) {
        fprintf(stderr, "Error reading from VL53L1X sensor.\n");
        return 0;
    }

    return (buf[1] << 8) | buf[2];
}

int main() {
    struct sigaction sa;

    // Initialize signal handling for graceful shutdown
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    init_pigpio();
    configure_sensor();

    while (running) {
        uint16_t distance = read_distance();

        if (distance < DISTANCE_THRESHOLD) {
            if (!buzzer_on) {
                gpioSetOutputLevel(BUZZER_GPIO, 1); // Buzzer on
                buzzer_on = 1;
            }
        } else {
            if (buzzer_on) {
                gpioSetOutputLevel(BUZZER_GPIO, 0); // Buzzer off
                buzzer_on = 0;
            }
        }

        usleep(READING_INTERVAL);
    }

    release_pigpio();
    return 0;
}
