#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 17
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define SPEED_OF_SOUND 343
#define TIMEOUT_MS 50
#define READING_INTERVAL_MS 200

float map_distance_to_angle(float distance) {
    return ((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 90;
