        fprintf(stderr, "Failed to set trigger GPIO as output: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    if ((ret = gpioSetMode(ECHO_GPIO, PI_INPUT)) != 0) {
        fprintf(stderr, "Failed to set echo GPIO as input: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    gpioSetWDOne(TRIG_GPIO);
    delayMicroseconds(10);
    gpioSetWDOne(TRIG_GPIO);

    if ((ret = gpioSetServoPulseWidthRange(SERVO_GPIO, 500, 2500)) != 0) {
        fprintf(stderr, "Failed to set servo pulse width range: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    gpioSetServoPosition(SERVO_GPIO, 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0;

        gpioRead(ECHO_GPIO);
        delayMicroseconds(10);
        gpioWrite(TRIG_GPIO, 1);
        delayMicroseconds(10);
        gpioWrite(TRIG_GPIO, 0);

        unsigned int echo_start_time = gpioRead(ECHO_GPIO);
        unsigned int echo_end_time;
        unsigned int timeout_counter = 0;

        while ((echo_end_time = gpioRead(ECHO_GPIO)) == 0 && timeout_counter < TIMEOUT_MS / READING_INTERVAL_MS) {
            delayMicroseconds(READING_INTERVAL_MS);
            timeout_counter++;
        }

        if (timeout_counter >= TIMEOUT_MS / READING_INTERVAL_MS) {
            fprintf(stderr, "Timeout error: echo stuck low or high.\n");
            continue;
        }

        unsigned int pulse_width = echo_end_time - echo_start_time;
        float distance = (pulse_width / 2) * SPEED_OF_SOUND;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range: %f cm\n", distance);
            continue;
        }

        float servo_angle = map_distance_to_angle(distance);
        gpioSetServoPosition(SERVO_GPIO, servo_angle);

        FILE *log_file = fopen("sensor_data.log", "a");
        if (log_file != NULL) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld.%03ld: Distance: %f cm, Servo Angle: %f degrees\n", ts.tv_sec, ts.tv_nsec, distance, servo_angle);
            fclose(log_file);
        }

        delayMicroseconds(READING_INTERVAL_MS);
    }

    gpioTerminate();
    return 0;
}

void signal_handler(int signum) {
    gpioTerminate();
    printf("Exiting gracefully...\n");
    exit(0);
}

