#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/msg.h>
#include <pigpio.h>

#define I2C_ADDR 0x29
#define TIMING_BUDGET 50
#define MIN_DISTANCE 100
#define BUZZER_PIN 23
#define MESSAGE_QUEUE_KEY 1234

struct msgbuf {
    long mtype;
    int distance;
};

int main() {
    int fd, i2c_fd, gpio_fd;
    gpio i2c_gpio;
    pigpio p;
    struct msgbuf msg;
    int mq_id;

    fd = pigpio_initialise();
    if (fd < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    p = (pigpio *) fd;

    i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C bus 1 open failed\n");
        pigpio_terminate((pigpio) fd);
        return 1;
    }
    i2c_gpio = i2c_get_gpio(i2c_fd);

    if (i2c_rdwr_setup(i2c_fd, &i2c_gpio) < 0) {
        fprintf(stderr, "I2C rdwr setup failed\n");
        i2c_close(i2c_fd);
        pigpio_terminate((pigpio) fd);
        return 1;
    }

    if (i2c_rd(i2c_fd, I2C_ADDR, 0x0F, (unsigned char *) &msg, 1) != 1) {
        fprintf(stderr, "Failed to read model ID\n");
        i2c_close(i2c_fd);
        pigpio_terminate((pigpio) fd);
        return 1;
    }

    if (msg[0] != 0xEA) {
        fprintf(stderr, "Invalid model ID\n");
        i2c_close(i2c_fd);
        pigpio_terminate((pigpio) fd);
        return 1;
    }

    if (i2c_wr(i2c_fd, I2C_ADDR, (unsigned char *) &i2c_reset, 2) != 2) {
        fprintf(stderr, "Failed to perform software reset\n");
        i2c_close(i2c_fd);
        pigpio_terminate((pigpio) fd);
        return 1;
    }

    if (i2c_wr(i2c_fd, I2C_ADDR, (unsigned char *) &timing_budget, 1) != 1) {
        fprintf(stderr, "Failed to set timing budget\n");
        i2c_close(i2c_fd);
        pigpio_terminate((pigpio) fd);
        return 1;
    }

    if (i2c_wr(i2c_fd, I2C_ADDR, (unsigned char *) &start_ranging, 1) != 1) {
        fprintf(stderr, "Failed to start ranging\n");
        i2c_close(i2c_fd);
        pigpio_terminate((pigpio) fd);
        return 1;
    }

    mq_id = msgget(MESSAGE_QUEUE_KEY, 0666 | IPC_CREAT);
    if (mq_id < 0) {
        fprintf(stderr, "Message queue creation failed\n");
        i2c_close(i2c_fd);
        pigpio_terminate((pigpio) fd);
        return 1;
    }

    while (1) {
        if (msq_receive(mq_id, &msg, sizeof(struct msgbuf)) < 0) {
            fprintf(stderr, "Message queue receive failed\n");
            break;
        }

        if (i2c_rd(i2c_fd, I2C_ADDR, 0x09, (unsigned char *) &data_ready, 1) != 1) {
            fprintf(stderr, "Failed to read data-ready bit\n");
            continue;
        }

        if (data_ready & 0x01) {
            if (i2c_rd(i2c_fd, I2C_ADDR, 0x96, (unsigned char *) &distance_msb, 1) != 1) {
                fprintf(stderr, "Failed to read distance MSB\n");
                continue;
            }
            if (i2c_rd(i2c_fd, I2C_ADDR, 0x97, (unsigned char *) &distance_lsb, 1) != 1) {
                fprintf(stderr, "Failed to read distance LSB\n");
                continue;
            }
            msg.distance = (distance_msb << 8) | distance_lsb;

            if (msg.distance < MIN_DISTANCE) {
                gpio_set_output(gpio_fd, BUZZER_PIN);
                pigpio_delay(100);
                gpio_clear_output(gpio_fd, BUZZER_PIN);
                pigpio_delay(100);
            }

            msq_send(mq_id, &msg, sizeof(struct msgbuf), 0);
        }

        pigpio_delay(TIMING_BUDGET * 1000);
    }

    i2c_close(i2c_fd);
    pigpio_terminate((pigpio) fd);
    munmsg();
    return 0;
}

