#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <stdbool.h>
#include <unistd.h>

#define TRIG_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define SOUND_SPEED 34300
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define READ_INTERVAL 100000 // 100 ms

static volatile int distance = MAX_DISTANCE;
static bool buzzer_on = false;

static void buzzer_callback(int pin, int level, void *userdata) {
    if (level) {
        gpioSetMode(BUZZER_PIN, PI_OUTPUT);
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioSetMode(BUZZER_PIN, PI_OUTPUT);
        gpioWrite(BUZZER_PIN, 0);
    }
}

static void trigger_pulse(int pin) {
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 1);
    usleep(10000);
    gpioWrite(pin, 0);
}

static int get_distance(int echo_pin) {
    int timeout = 1000000;
    int echo_time = 0;
    int echo_level;

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    trigger_pulse(TRIG_PIN);
    while (timeout > 0) {
        if (gpioRead(ECHO_PIN) == 1) {
            echo_time = 0;
            while (gpioRead(ECHO_PIN) == 1) {
                echo_time += 5;
                if (echo_time > timeout) {
                    return -1; // Timeout
                }
            }
            break;
        }
        timeout -= READ_INTERVAL;
    }

    if (echo_time == 0) {
        return -1; // No echo
    }

    int distance_cm = (echo_time * SOUND_SPEED) / (2 * echo_time);

    if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
        return -1; // Invalid reading
    }

    return distance_cm;
}

int main(int argc, char **argv) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    if (gpioSetAlertFuncEx(ECHO_PIN, READ_INTERVAL, buzzer_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function for echo pin.\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        int distance_cm = get_distance(ECHO_PIN);

        if (distance_cm != -1) {
            distance = distance_cm;
            if (buzzer_on && distance >= 30) {
                gpioSetMode(BUZZER_PIN, PI_OUTPUT);
                gpioWrite(BUZZER_PIN, 0);
                buzzer_on = false;
            }
        }

        if (distance < 30) {
            if (!buzzer_on) {
                gpioSetMode(BUZZER_PIN, PI_OUTPUT);
                gpioWrite(BUZZER_PIN, 1);
                buzzer_on = true;
            }
        } else {
            buzzer_on = false;
        }

        printf("Distance: %d cm\n", distance);
        usleep(READ_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

