#include <pigio.h>
#include <wiringPiI2C.h>
#include <paho-mqtt/mqtt.h>

#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define MAX_RETRIES 3
#define CLOSE 0
#define OPEN 1
#define DIST_THRESHOLD 20

static int i2c_fd = -1;
static int gpio_init = -1;
static int servo_angle = CLOSE;
static int mqtt_connected = 0;

void gate_event_callback(const char *topic, const unsigned char *payload, void *context) {
    if (strcmp(topic, "gate/force_open") == 0)
        servo_angle = OPEN;
    else if (strcmp(topic, "gate/force_close") == 0)
        servo_angle = CLOSE;
    else if (strcmp(topic, "gate/status") == 0)
        printf("Gate status: %s\n", payload ? "open" : "closed");
}

void i2c_init() {
    if (wiringPiI2CInit() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        exit(EXIT_FAILURE);
    }
    i2c_fd = wiringPiI2CSetup(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_distance(uint8_t *data, size_t len) {
    uint16_t distance;
    int ret;

    for (int i = 0; i < MAX_RETRIES; ++i) {
        ret = i2c_rdwr(i2c_fd, &wiringPiI2C_wr, sizeof(wiringPiI2C_wr), VL53L1X_ADDR, 0x80, data, 1);
        if (ret == 1) {
            distance = (data[0] << 8) | data[1];
            return distance;
        }
        if (i == MAX_RETRIES - 1) {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
            exit(EXIT_FAILURE);
        }
        _delay_ms(100);
    }
}

void servo_control(int angle) {
    if (gpio_init < 0) {
        gpioInitialize();
        gpio_init = 1;
    }

    pigpio_set_mode(gpio, SERVO_PIN, PI_OUTPUT);
    pigpio_write(gpio, SERVO_PIN, angle);
}

void log_gate_event(const char *event) {
    FILE *log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), event);
    fclose(log_file);
}

int main() {
    i2c_init();
    gpio_init = pigpio_initialise();
    if (gpio_init < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    mqtt_connect("mqtt_broker_address", "mqtt_port", "client_id");
    mqtt_subscribe("gate/#");

    while (1) {
        uint16_t distance = read_distance((uint8_t *) &distance, sizeof(distance));
        if (distance < DIST_THRESHOLD) {
            servo_control(OPEN);
            log_gate_event("Gate opened");
            mqtt_publish("gate/status", "open", 0);
        } else {
            servo_control(CLOSE);
            log_gate_event("Gate closed");
            mqtt_publish("gate/status", "closed", 0);
        }

        mqtt_loop_forever();

        pigpio_terminate();
        fclose(stdout);
        fclose(stderr);
        return 0;
    }
}

