#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define MAX_DISTANCE 30000 // cm
#define MIN_DISTANCE 100 // cm
#define MEASUREMENT_INTERVAL 200000 // us
#define TIMEOUT_INTERVAL 6000000 // us

static const float SPEED_OF_SOUND = 0.0343; // cm/us

static FILE *log_file = NULL;

void echo_callback(int pin, uint tick, void *data) {
    static uint rising_edge_tick = 0;
    static uint falling_edge_tick = 0;

    if (piGetMode() != PI_INPUT) {
        fprintf(stderr, "ECHO pin is not in input mode\n");
        return;
    }

    if (piGetLevel(ECHO_PIN)) {
        if (!rising_edge_tick)
            rising_edge_tick = tick;
        falling_edge_tick = tick;
    }
}

int main() {
    int ret;

    // Initialize pigpio with full error checking
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", gpioGetError());
        return ret;
    }

    // Set GPIO pins
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_OFF);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Generate trigger pulse
        gpioWrite(TRIG_PIN, 0);
        delayMicroseconds(10);
    }

    // Register echo callback
    gpioSetCallback(ECHO_PIN, echo_callback);

    while (1) {
        // Wait for rising edge
        while ((uint) (falling_edge_tick - rising_edge_tick) < MIN_DISTANCE * MEASUREMENT_INTERVAL) {
            if (piGetLevel(ECHO_PIN)) {
                rising_edge_tick = falling_edge_tick;
                gpioClearCallback(ECHO_PIN);
            }
            delayMicroseconds(1);
        }

        // Wait for falling edge
        while ((uint) (falling_edge_tick - rising_edge_tick) > MAX_DISTANCE * MEASUREMENT_INTERVAL) {
            if (!piGetLevel(ECHO_PIN)) {
                falling_edge_tick = rising_edge_tick;
                gpioSetCallback(ECHO_PIN, echo_callback);
            }
            delayMicroseconds(1);
        }

        // Calculate distance
        uint pulse_width = falling_edge_tick - rising_edge_tick;
        float distance = pulse_width * SPEED_OF_SOUND / 2 / MEASUREMENT_INTERVAL;

        // Validate and log distance
        if (pulse_width < MIN_DISTANCE * MEASUREMENT_INTERVAL || pulse_width > MAX_DISTANCE * MEASUREMENT_INTERVAL) {
            fprintf(stderr, "Invalid distance reading: %u us\n", pulse_width);
            continue;
        }

        // Log distance with timestamp
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(stdout, "%s: %f cm\n", timestamp, distance);
        fprintf(log_file, "%s: %f cm\n", timestamp, distance);
        fflush(stdout);
        fflush(log_file);

        // Reset for next measurement
        rising_edge_tick = falling_edge_tick;
        gpioClearCallback(ECHO_PIN);

        // Handle SIGINT and SIGTERM for clean shutdown
        if (signal(SIGINT, cleanup) != SIG_ERR && signal(SIGTERM, cleanup) != SIG_ERR) {
            fprintf(stderr, "Signal handlers installed\n");
        }
    }

    cleanup:
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

