#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define VL53L1X_ADDR 0x29
#define MIN_DISTANCE 50
#define MAX_DISTANCE 60
#define HYSTERESIS 5

static const char *log_file = "parking_log.txt";
static FILE *log_fp = NULL;

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(INTERRUPT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void init_sensor() {
    uint8_t model_id[4];
    if (i2c_read_reg_byte(VL53L1X_ADDR, 0x06, model_id) != 4) {
        fprintf(stderr, "Failed to read VL53L1X model ID.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (memcmp(model_id, "VL53L1", 6) != 0) {
        fprintf(stderr, "Invalid VL53L1X sensor detected.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set shutdown pin mode.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

int i2c_read_reg_byte(uint8_t device_address, uint8_t reg_address, uint8_t *data) {
    int ret;
    ret = i2c_write_byte_data(device_address, reg_address, 0);
    if (ret < 0) {
        return ret;
    }

    ret = i2c_read_byte_data(device_address, reg_address);
    if (ret < 0) {
        return ret;
    }

    *data = ret;
    return 1;
}

void setup_logging() {
    log_fp = fopen("parking_log.txt", "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void close_logging() {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

void gate_control_loop() {
    uint16_t distance;
    int gate_state = 0;

    while (1) {
        gpioPulse(SERVO_PIN, 1000); // Open gate
        delay(1000);

        if (i2c_read_distance(VL53L1X_ADDR, &distance) < 0) {
            fprintf(stderr, "Failed to read distance.\n");
            continue;
        }

        if (distance >= MAX_DISTANCE - HYSTERESIS || distance <= MIN_DISTANCE + HYSTERESIS) {
            gate_state = 1;
            gpioWrite(SHUTDOWN_PIN, 1);
        } else {
            gate_state = 0;
            gpioWrite(SHUTDOWN_PIN, 0);
        }

        if (gate_state != previous_gate_state) {
            timestamp_t now = time(NULL);
            strftime(time_str, 20, "%Y-%m-%d %H:%M:%S", localtime(&now));

            fprintf(log_fp, "%s: Gate state changed to %d, distance: %d cm\n", time_str, gate_state, distance);
            previous_gate_state = gate_state;
        }

        delay(500);
    }
}

int main(int argc, char **argv) {
    init_gpio();
    init_sensor();
    setup_logging();

    previous_gate_state = 0;

    gpioSetAlertMode(INTERRUPT_PIN, PI_FALLING);
    gpioSetCallback(INTERRUPT_PIN, trigger_callback);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gate_control_loop();

    gpioTerminate();
    return 0;
}

static int previous_gate_state = 0;
static char time_str[20];

void trigger_callback(int pin, uint timestamp, uint edge, uint level, void *user_data) {
    // Handle interrupt if needed
}

void signal_handler(int signum) {
    close_logging();
    gpioTerminate();
    exit(0);
}

