#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define GPIO24 24
#define GPIO17 17
#define GPIO18 18
#define MAX_RETRIES 5

static int i2c_retry_count = 0;
static const int i2c_retry_delay_ms = 100;

void vl53l1x_read_distance(int fd, uint8_t *distance) {
    int r;
    uint8_t data[1];

    if ((r = pigpio_i2c_write(fd, VL53L1X_ADDR, (uint8_t *)"\x00", 1)) != 1) {
        fprintf(stderr, "Error writing to VL53L1X: %d\n", r);
        return;
    }

    if ((r = pigpio_delay_us(i2c_retry_count * i2c_retry_delay_ms)) != 0) {
        fprintf(stderr, "Error delaying: %d\n", r);
        return;
    }

    if ((r = pigpio_i2c_read(fd, VL53L1X_ADDR, (uint8_t *)data, 1)) != 1) {
        if (i2c_retry_count < MAX_RETRIES) {
            i2c_retry_count++;
            usleep(i2c_retry_delay_ms);
            vl53l1x_read_distance(fd, distance);
            return;
        }
        fprintf(stderr, "Error reading from VL53L1X: %d\n", r);
        return;
    }

    if (data[0] & 0x01) {
        if ((r = pigpio_i2c_read(fd, VL53L1X_ADDR, (uint8_t *)distance, 2)) != 2) {
            fprintf(stderr, "Error reading distance: %d\n", r);
            return;
        }
    } else {
        fprintf(stderr, "Data not ready\n");
        return;
    }
}

void motor_control(int distance) {
    int forward = (distance < 100);
    int backward = (distance > 300);

    if (forward) {
        gpioSetMode(GPIO17, PI_OUTPUT);
        gpioSetMode(GPIO18, PI_OUTPUT);
        gpioWrite(GPIO17, 1);
        gpioWrite(GPIO18, 0);
    } else if (backward) {
        gpioSetMode(GPIO17, PI_OUTPUT);
        gpioSetMode(GPIO18, PI_OUTPUT);
        gpioWrite(GPIO17, 0);
        gpioWrite(GPIO18, 1);
    } else {
        gpioWrite(GPIO17, 0);
        gpioWrite(GPIO18, 0);
    }

    printf("Distance: %d mm, Motor: %s forward, %s backward\n", distance, forward ? "ON" : "OFF", backward ? "ON" : "OFF");
}

int main() {
    int fd;
    gpioInitialise();

    fd = i2c_open(1);
    if (!fd) {
        fprintf(stderr, "Error opening I2C bus 1\n");
        goto cleanup;
    }

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Error initialising pigpio\n");
        i2c_close(fd);
        goto cleanup;
    }

    gpioSetMode(GPIO24, PI_INPUT, PI_PULLUP);
    gpioSetMode(GPIO17, PI_OUTPUT);
    gpioSetMode(GPIO18, PI_OUTPUT);

    pigpio_set_callback(gpio24, PI_RISING_EDGE, &vl53l1x_read_distance_callback);

    while (1) {
        uint16_t distance;
        vl53l1x_read_distance(fd, &distance);
        motor_control(distance);
    }

cleanup:
    pigpio_stop();
    i2c_close(fd);
    gpioTerminate();
    return 0;
}

void vl53l1x_read_distance_callback(int pin, uint timestamp, int edge, void *user_data) {
    uint16_t distance;
    vl53l1x_read_distance(i2c_fd, &distance);
    motor_control(distance);
}

