#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <gpio.h>

#define I2C_ADDR 0x5A
#define POLL_INTERVAL_MS 50
#define GPIO_LED17 17
#define GPIO_LED18 18
#define GPIO_LED27 27
#define GPIO_LED22 22

#define ELECONFIG0 0x00
#define MHDR 0x01
#define NHDR 0x01
#define NCLR 0x0E
#define FDLR 0x00
#define ELECONFIG_RUN 0x0C
#define THRESHOLD_REG0 0x5A
#define THRESHOLD_REG1 0x5D
#define THRESHOLD_REG2 0x5E
#define THRESHOLD_REG3 0x5F

#define SOFT_RESET 0x63

#define LED_PATTERN_OFF 0x00
#define LED_PATTERN_1 0x01
#define LED_PATTERN_2 0x02
#define LED_PATTERN_3 4
#define LED_PATTERN_4 0x08

int gpio_fds[4];
int i2c_fd;
FILE *log_fp;

void init_gpio() {
    int ret;

    for (int i = 0; i < 4; i++) {
        gpio_fds[i] = gpiod_request_single(NULL, "led" + to_string(i + 1), GPIOD_OUT_PP, 0);
        if (gpio_fds[i] < 0) {
            fprintf(stderr, "Failed to request GPIO %d\n", i + 1);
            exit(EXIT_FAILURE);
        }
        ret = gpio_set_value(gpio_fds[i], 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO %d to 0\n", i + 1);
            exit(EXIT_FAILURE);
        }
    }
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }
}

void init_log() {
    log_fp = fopen("/var/log/proximity_events.log", "a");
    if (!log_fp) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void soft_reset_sensor() {
    uint8_t buf[2];
    buf[0] = SOFT_RESET;
    buf[1] = 0;

    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to write soft reset command\n");
        exit(EXIT_FAILURE);
    }
}

void verify_sensor_presence() {
    uint8_t buf[2];
    buf[0] = 0x0F;
    buf[1] = 0;

    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to write to sensor for presence check\n");
        exit(EXIT_FAILURE);
    }

    uint8_t response[2];
    if (read(i2c_fd, response, 2) != 2) {
        fprintf(stderr, "Failed to read from sensor for presence check\n");
        exit(EXIT_FAILURE);
    }

    if (response[0] != 0x0F) {
        fprintf(stderr, "Sensor not present or communication error\n");
        exit(EXIT_FAILURE);
    }
}

void configure_sensor() {
    uint8_t buf[10];

    // Stop mode
    buf[0] = ELECONFIG0;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to set stop mode\n");
        exit(EXIT_FAILURE);
    }

    // Baseline filtering
    buf[0] = MHDR;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to set MHDR\n");
        exit(EXIT_FAILURE);
    }
    buf[0] = NHDR;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to set NHDR\n");
        exit(EXIT_FAILURE);
    }
    buf[0] = NCLR;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to set NCLR\n");
        exit(EXIT_FAILURE);
    }
    buf[0] = FDLR;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to set FDLR\n");
        exit(EXIT_FAILURE);
    }

    // Auto-configuration thresholds
    buf[0] = THRESHOLD_REG0;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to set threshold 0x%02X\n", THRESHOLD_REG0);
        exit(EXIT_FAILURE);
    }
    buf[0] = THRESHOLD_REG1;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to set threshold 0x%02X\n", THRESHOLD_REG1);
        exit(EXIT_FAILURE);
    }
    buf[0] = THRESHOLD_REG2;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to set threshold 0x%02X\n", THRESHOLD_REG2);
        exit(EXIT_FAILURE);
    }
    buf[0] = THRESHOLD_REG3;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to set threshold 0x%02X\n", THRESHOLD_REG3);
        exit(EXIT_FAILURE);
    }

    // Run mode
    buf[0] = ELECONFIG_RUN;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to set run mode\n");
        exit(EXIT_FAILURE);
    }
}

void map_electrode_to_led(uint8_t electrode) {
    switch (electrode) {
        case 0:
            gpio_set_value(gpio_fds[0], 1);
            gpio_set_value(gpio_fds[1], 0);
            gpio_set_value(gpio_fds[2], 0);
            gpio_set_value(gpio_fds[3], 0);
            break;
        case 1:
            gpio_set_value(gpio_fds[0], 0);
            gpio_set_value(gpio_fds[1], 1);
            gpio_set_value(gpio_fds[2], 0);
            gpio_set_value(gpio_fds[3], 0);
            break;
        case 2:
            gpio_set_value(gpio_fds[0], 0);
            gpio_set_value(gpio_fds[1], 0);
            gpio_set_value(gpio_fds[2], 1);
            gpio_set_value(gpio_fds[3], 0);
            break;
        case 3:
            gpio_set_value(gpio_fds[0], 0);
            gpio_set_value(gpio_fds[1], 0);
            gpio_set_value(gpio_fds[2], 0);
            gpio_set_value(gpio_fds[3], 1);
            break;
        // ... Add mappings for other electrodes (4-11)
        default:
            gpio_set_value(gpio_fds[0], 0);
            gpio_set_value(gpio_fds[1], 0);
            gpio_set_value(gpio_fds[2], 0);
            gpio_set_value(gpio_fds[3], 0);
            break;
    }
}

void log_proximity_event(uint8_t electrode) {
    time_t now = time(NULL);
    fprintf(log_fp, "[%ld] Electrode %d active\n", now, electrode);
}

void cleanup() {
    fclose(log_fp);
    for (int i = 0; i < 4; i++) {
        gpio_set_value(gpio_fds[i], 0);
        gpiod_release(gpio_fds[i]);
    }
    close(i2c_fd);
}

void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

void sigterm_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    init_gpio();
    init_i2c();
    init_log();
    soft_reset_sensor();
    verify_sensor_presence();
    configure_sensor();

    while (1) {
        uint8_t status_reg_0[2];
        uint8_t status_reg_1[2];

        if (read(i2c_fd, status_reg_0, 2) != 2) {
            fprintf(stderr, "Failed to read status register 0\n");
            break;
        }
        if (read(i2c_fd, status_reg_1, 2) != 2) {
            fprintf(stderr, "Failed to read status register 1\n");
            break;
        }

        uint8_t electrodes_active = (status_reg_0[0] & 0x0F);

        if (electrodes_active == 0) {
            fprintf(stderr, "No electrodes active\n");
            log_proximity_event(0); // Log no electrode active
        } else {
            map_electrode_to_led(electrodes_active);
            log_proximity_event(electrodes_active);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

