#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define ELECTRODE 0
#define LED_PIN 27
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05

static volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int signum) {
    sigint_received = 1;
}

int main() {
    struct pi_i2c_bus bus;
    gpioInitialise();
    if (piGetI2CBusses(&bus, 1) < 0) {
        fprintf(stderr, "Failed to get I2C bus 1\n");
        return 1;
    }

    if (piI2COpen(bus, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to open MPR121 on I2C bus 1\n");
        return 1;
    }

    if (readRegister16(MPR121_ADDR, MPR121_DEVICE_ID) != 0x5A) {
        fprintf(stderr, "Device ID mismatch, MPR121 not present\n");
        return 1;
    }

    if (writeRegister16(MPR121_ADDR, FFI, 0x00) < 0 ||
        writeRegister16(MPR121_ADDR, SFI, 0x00) < 0 ||
        writeRegister16(MPR121_ADDR, ESI, 0x00) < 0 ||
        writeRegister16(MPR121_ADDR, DEBOUNCE, 0x00) < 0 ||
        writeRegister16(MPR121_ADDR, AFE_CONFIG, 0x00) < 0 ||
        writeRegister16(MPR121_ADDR, BASELINE_FILTER, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize MPR121 registers\n");
        return 1;
    }

    if (writeRegister16(MPR121_ADDR, TOUCH_THRESHOLD_L(ELECTRODE), TOUCH_THRESHOLD & 0xFF) < 0 ||
        writeRegister16(MPR121_ADDR, RELEASE_THRESHOLD_L(ELECTRODE), RELEASE_THRESHOLD & 0xFF) < 0) {
        fprintf(stderr, "Failed to set touch/release thresholds\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    signal(SIGINT, sigint_handler);

    while (!sigint_received) {
        uint8_t touch_state = readRegister8(MPR121_ADDR, TOUCH_STATUS_L(ELECTRODE));

        if (touch_state & (1 << ELECTRODE)) {
            gpioWrite(LED_PIN, 1);
            FILE *log_file = fopen("proximity.log", "a");
            if (log_file != NULL) {
                time_t now = time(NULL);
                fprintf(log_file, "Proximity detected at %ld\n", now);
                fclose(log_file);
            }
            sleep(1);
            gpioWrite(LED_PIN, 0);
        }
        usleep(100000);
    }

    piI2CClose(bus, MPR121_ADDR);
    gpioTerminate();

    return 0;
}

