#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2
#define SPEED_OF_SOUND_MS 0.0343
#define TIMEOUT_MS 30

volatile sig_atomic_t sigint_flag = 0;

static int distance_callback(const struct gpiod_line *line, uint32_t events) {
    if (events & (GPIOD_EVENT_FALL | GPIOD_EVENT_RISING)) {
        if (line->line_id == ECHO_GPIO) {
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            unsigned long echo_pulse_us = (ts.tv_sec * 1000000 + ts.tv_nsec / 1000);

            if (events & GPIOD_EVENT_RISING) {
                unsigned long start_us = echo_pulse_us;
                while (!(gpiod_get_value(line) == 0) && (clock_gettime(CLOCK_MONOTONIC, &ts) - start_us < TIMEOUT_MS / 1000)) {
                    if ((clock_gettime(CLOCK_MONOTONIC, &ts) - start_us) > TIMEOUT_MS / 1000) {
                        printf("Timeout: Echo never rose\n");
                        return 0;
                    }
                }
            }

            unsigned long pulse_us = echo_pulse_us - start_us;
            float distance_cm = (pulse_us * SPEED_OF_SOUND_MS) / 2.0;

            if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
                printf("Error: Distance out of range (%f cm)\n", distance_cm);
                return 0;
            }

            printf("Distance: %f cm\n", distance_cm);
            log_distance(distance_cm);
        }
    }
    return 0;
}

static void log_distance(float distance) {
    FILE *log_file = fopen("distance_log.txt", "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s, %f\n", timestamp, distance);
        fclose(log_file);
        fflout(log_file);
    }
}

static void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main(int argc, char *argv[]) {
    struct gpiod_chipchip *chip;
    struct gpiod_line *trig_line, *echo_line;

    chip = gpiod_chip_open(0, "rpi-gpio");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, "GPIO17");
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(trig_line, "my-trigger") < 0) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, "GPIO18");
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(echo_line) < 0) {
        fprintf(stderr, "Failed to request echo line as input\n");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_add_callback(trig_line, GPIOD_EVENT_FALL | GPIOD_EVENT_RISING, distance_callback) < 0) {
        fprintf(stderr, "Failed to add callback\n");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!sigint_flag) {
        sleep(1);
    }

    gpiod_remove_callback(trig_line, distance_callback);
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

