#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE 4000 // 4 meters
#define MIN_DISTANCE 5   // 1 cm

static FILE *log_file = NULL;
static volatile int running = 1;

static void isr_callback(int pin, int level, void (*user_function)(int, int, void *), void *user_data) {
    static unsigned long last_us = 0;
    static unsigned long pulse_us = 0;

    if (level == 1) { // RISING_EDGE
        last_us = 0;
    } else if (level == 0) { // FALLING_EDGE
        pulse_us = gpio_pulselength(pin, 1);
        if (pulse_us > 0 && pulse_us < 25000000) { // 25 ms
            double distance_m = pulse_us * 343 / (2 * 1000000);
            char timestamp[20];
            time_t t = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));

            if (log_file != NULL) {
                fprintf(log_file, "%s, %lu\n", timestamp, (unsigned long)distance_m);
            }
        }
    }
}

void sigint_handler(int signum) {
    running = 0;
}

int main() {
    gpioInitialise();
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen("distance_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    gpioSetISRFuncEx(ECHO_PIN, PI_RISING_EDGE | PI_FALLING_EDGE, isr_callback, NULL);
    gpioSetISRCallback(ECHO_PIN, isr_callback, NULL);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        gpio_set_function(TRIG_PIN, PI_OUTPUT);
        gpio_write(TRIG_PIN, 1);
        delay(1000000); // 1 second
        gpio_write(TRIG_PIN, 0);
        delay(10000); // Ensure the echo pulse has completed
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

