        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen("distance_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    gpioSetISRFuncEx(ECHO_PIN, PI_RISING_EDGE | PI_FALLING_EDGE, isr_callback, NULL);
    gpioSetISRCallback(ECHO_PIN, isr_callback, NULL);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        gpio_set_function(TRIG_PIN, PI_OUTPUT);
        gpio_write(TRIG_PIN, 1);
        delay(1000000); // 1 second
        gpio_write(TRIG_PIN, 0);
        delay(10000); // Ensure the echo pulse has completed
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
