    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID from VL53L1X\n");
        exit(1);
    }

    if (i2c_wr(i2c_fd, 0x0021, &RANGE_MODE_SHORT) != 1) {
        fprintf(stderr, "Failed to set ranging mode to short\n");
        exit(1);
    }

    if (i2c_wr(i2c_fd, 0x0015, &START_RANGE) != 1) {
        fprintf(stderr, "Failed to start ranging\n");
        exit(1);
    }
}

