    signal(SIGTERM, sigint_handler);

    init_i2c();
    init_gpio();
    init_sensor();

    log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
