        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        update_gate_state();
        fprintf(log_file, "%s: Distance = %d cm, Gate = %s\n", timestamp, MIN_DISTANCE_CM - distance_cm, distance_cm < MIN_DISTANCE_CM ? "Open" : "Closed");

        sleep(1);
    }

    pigpio_stop(gpio);
    fclose(log_file);
    pigpio_terminate();
    return 0;
}

