#include <time.h>
#include <signal.h>
#include <math.h>

#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 18
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define SPEED_OF_SOUND 34300
#define SAMPLE_COUNT 5
#define TRIG_PULSE_US 10
#define TIMEOUT_MS 30
#define SAMPLE_INTERVAL_MS 100
#define SIGINT_FLAG 0

volatile sig_atomic_t sigint_flag = SIGINT_FLAG;

struct sample_t {
    float distance;
    float angle;
};

struct {
    int count;
    float sum;
    struct sample_t samples[SAMPLE_COUNT];
} distance_samples = {0, 0, {0}};

static void alert_cb(uint pulse, uint user, uint edge, uint jitter, uint tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;
    float pulse_width_ms;

    if (current_tick - last_tick > TIMEOUT_MS) {
        gpioTerminate();
        sigint_flag = SIGINT_FLAG;
        return;
    }

    last_tick = current_tick;

    pulse_width_ms = (float)(pulse - user) * (TIMEOUT_MS * 1000) / GPIO_FREQ;
    distance_samples.sum -= distance_samples.samples[distance_samples.count].distance;
    distance_samples.samples[distance_samples.count].distance = pulse_width_ms * SPEED_OF_SOUND / 2;
    distance_samples.sum += distance_samples.samples[distance_samples.count].distance;
    distance_samples.count = (distance_samples.count + 1) % SAMPLE_COUNT;
}

static void servo_angle_to_pulsewidth(float angle, uint32_t *pulsewidth) {
    *pulsewidth = (uint32_t)(angle / M_PI * 1800 + 500);
}

static float log_map(float x, float in_min, float in_max, float out_min, float out_max) {
    return out_min + (out_max - out_min) * (log(x - in_min) - log(in_max - in_min)) / (log(MAX_DISTANCE - MIN_DISTANCE));
}

int main(int argc, char **argv) {
    int fd;
    int ret;
    gpioInitialise();

    if ((fd = fopen("distance_log.csv", "w")) == NULL) {
        perror("Failed to open distance_log.csv");
        return 1;
    }
    fprintf(fd, "Timestamp,Distance (cm),Angle (degrees)\n");
    fflush(fd);

    if ((ret = gpioSetMode(TRIG_GPIO, PI_OUTPUT)) < 0) {
        perror("gpioSetMode(TRIG_GPIO)");
        return 1;
    }
    if ((ret = gpioSetMode(ECHO_GPIO, PI_INPUT)) < 0) {
        perror("gpioSetMode(ECHO_GPIO)");
        return 1;
    }
    if ((ret = gpioSetMode(SERVO_GPIO, PI_OUTPUT)) < 0) {
        perror("gpioSetMode(SERVO_GPIO)");
        return 1;
    }
    if ((ret = gpioSetAlertFunc(ECHO_GPIO, alert_cb, edge_rising)) < 0) {
        perror("gpioSetAlertFunc(ECHO_GPIO)");
        return 1;
    }
    if ((ret = gpioSetAlertFunc(SERVO_GPIO, NULL, edge_none)) < 0) {
        perror("gpioSetAlertFunc(SERVO_GPIO)");
        return 1;
    }

    signal(SIGINT, [](int) { sigint_flag = 1; });

    while (1) {
        if (sigint_flag) {
            break;
        }

        gpioWrite(TRIG_GPIO, 1);
        delayMicroseconds(TRIG_PULSE_US);
        gpioWrite(TRIG_GPIO, 0);

        if (distance_samples.count > 0) {
            distance_samples.sum /= distance_samples.count;
            float angle = log_map(distance_samples.sum, MIN_DISTANCE, MAX_DISTANCE, 0, 180);
            uint32_t pulsewidth;
            servo_angle_to_pulsewidth(angle, &pulsewidth);

            FILE *log_file = fopen("distance_log.csv", "a");
            if (log_file != NULL) {
                time_t now = time(NULL);
                fprintf(log_file, "%ld,%.2f,%.2f\n", (long)now, distance_samples.sum, angle);
                fclose(log_file);
            }
            fflush(stdout);
        }

        gpioWrite(SERVO_GPIO, pulsewidth);
        delay(SAMPLE_INTERVAL_MS);
    }

    gpioTerminate();
    fclose(fd);
    return 0;
}

