#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <stdbool.h>
#include <time.h>

#define BUFFER_SIZE 10
#define I2C_ADDR 0x29
#define GPIO_WARNING 17
#define CHECK_INTERVAL (50 * 1000 / 1000)

typedef struct {
    float buffer[BUFFER_SIZE];
    int head, tail;
} CircularBuffer;

CircularBuffer cb;
pig_address i2c_addr = I2C_ADDR;

void cb_init() {
    cb.head = cb.tail = 0;
}

bool is_full(CircularBuffer *cb) {
    return ((cb->head + 1) % BUFFER_SIZE) == cb->tail;
}

bool is_empty(CircularBuffer *cb) {
    return cb->head == cb->tail;
}

void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
}

float cb_get(CircularBuffer *cb) {
    float value = cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    return value;
}

void sigint_handler(int signum) {
    gpioTerminate();
    pigpio_stop();
    exit(0);
}

int main() {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = CHECK_INTERVAL;

    if (init_pigpio() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
