#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <wiringPiI2C.h>

#define SI1102_ADDR 0x60
#define GPIO_PIN 27
#define DEFAULT_THRESHOLD 1000

int i2c_fd = -1;
int gpio_pin = -1;
uint16_t threshold = DEFAULT_THRESHOLD;
uint16_t proximity;
int log_file = -1;
volatile int interrupt_flag = 0;

void log_proximity(const char *status) {
    if (log_file == -1) return;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%F %T", timeinfo);

    fprintf(log_file, "%s, Proximity: %u, Status: %s\n", timestamp, proximity, status);
}

void interrupt_handler() {
    interrupt_flag = 1;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_fd = wiringPiI2CSetup(atoi(optarg));
                if (i2c_fd < 0) {
                    fprintf(stderr, "Error: Failed to open I2C bus\n");
                    return 1;
                }
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s -a <i2c_address> -t <threshold>\n", argv[0]);
                return 1;
        }
    }

    if (i2c_fd < 0 || threshold == 0) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return 1;
    }

    if (pigpio(0, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialise pigpio\n");
        return 1;
    }

    gpio_pin = gpioInitialise(GPIO_PIN);
    if (gpio_pin < 0) {
        fprintf(stderr, "Error: Failed to initialise GPIO\n");
        pigpioTerminate(0);
        return 1;
    }

    pigpioSetMode(gpio_pin, PI_OUTPUT);
    pigpioSetPullUpDown(gpio_pin, 1);

    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        pigpioTerminate(0);
        return 1;
    }

    if (wiringPiI2CWriteReg16(i2c_fd, 0x0E, 0x0000) < 0) {
        fprintf(stderr, "Error: Failed to write to Si1102 registers\n");
        pigpioTerminate(0);
        return 1;
    }

    log_file = fopen("proximity.log", "w");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        pigpioTerminate(0);
        return 1;
    }

    pigpioSetCallback(gpio_pin, interrupt_handler);
    pigpioSetDrive(gpio_pin, 0);

    while (1) {
        if (interrupt_flag) {
            interrupt_flag = 0;
            uint8_t reg_high[2], reg_low[2];
            if (wiringPiI2CReadReg8(i2c_fd, 0x08, reg_high, 2) != 2 ||
                wiringPiI2CReadReg8(i2c_fd, 0x09, reg_low, 2) != 2) {
                fprintf(stderr, "Error: Failed to read from Si1102 registers\n");
                break;
            }
            proximity = (uint16_t)(reg_high[0] << 8 | reg_low[0]);

            if (proximity > threshold) {
                log_proximity("ALERT");
            } else {
                log_proximity("SAFE");
            }
        }

        pigpioWaitEDGE(gpio_pin, 1);
    }

    pigpioTerminate(0);
    fclose(log_file);
    return 0;
}

void sigint_handler(int signum) {
    pigpioTerminate(0);
    fclose(log_file);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    return main(argc, argv);
}

