#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <math.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define MAX_DISTANCE 200
#define MIN_DISTANCE 2
#define PWM_FREQ 48000

float distance;
float frequency;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

void sigterm_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(1);
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin as output.\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin as input.\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin as output.\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency.\n");
        gpioTerminate();
        exit(1);
    }
}

void trigger_ultrasonic() {
    gpioSetOutputHigh(TRIG_PIN);
    delayMicroseconds(10);
    gpioSetInput(TRIG_PIN);
}

void read_echo() {
    distance = gpioWaveFormLength(ECHO_PIN, PI_HIGH);
    distance = distance * 17150; // cm
    distance /= 29.1; // speed of sound in cm/us
}

void update_frequency() {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return;
    }

    frequency = 200 * exp(distance / 50);
    gpioSetPWMfrequency(PWM_PIN, (int)(PWM_FREQ * frequency / 200));
    gpioSetPWMdutycycle(PWM_PIN, (int)(frequency * 50));
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    setup_gpio();

    while (1) {
        trigger_ultrasonic();
        read_echo();
        update_frequency();
        delay(100);
    }

    gpioTerminate();
    return 0;
}

