#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DIST 5
#define MAX_DIST 50
#define MIN_FREQ 200
#define MAX_FREQ 2000

int distance;
float freq;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(1);
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    if (gpioSetPWMfrequency(BUZZER_PIN, 8000000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d.\n", BUZZER_PIN);
        gpioTerminate();
        exit(1);
    }

    if (gpioSetPWMrange(BUZZER_PIN, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO%d.\n", BUZZER_PIN);
        gpioTerminate();
        exit(1);
    }
}

uint32_t read_distance() {
    gpioSetOutputHigh(TRIG_PIN);
    delayMicroseconds(10);
    gpioSetOutputLow(TRIG_PIN);

    uint32_t start_time = gpioGetTimestamp();
    while (gpioGetLevel(ECHO_PIN) == 0);
    uint32_t stop_time = gpioGetTimestamp();

    uint32_t elapsed_time = stop_time - start_time;
    uint32_t distance_cm = elapsed_time * 17150; // Speed of sound is 34300 cm/s

    if (distance_cm > 400) {
        distance_cm = -1; // Timeout
    }

    distance = distance_cm;
    return distance_cm;
}

int main() {
    signal(SIGINT, sigint_handler);

    setup_gpio();

    while (1) {
        uint32_t distance_cm = read_distance();

        if (distance_cm != -1) {
            freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance_cm) / (MAX_DIST - MIN_DIST);
            freq = fmaxf(MIN_FREQ, fminf(freq, MAX_FREQ));

            gpioSetPWMfrequency(BUZZER_PIN, freq);
            gpioSetPWMdutycycle(BUZZER_PIN, (float)freq);
        }

        printf("Distance: %.2f cm, Frequency: %.0f Hz\n", distance, freq);
        delayMicroseconds(10);
    }

    gpioTerminate();
    return 0;
}

