#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define CLOSE_DISTANCE 10
#define MEASUREMENT_INTERVAL 500
#define TRIG_PULSE_US 10
#define TIMEOUT_MS 50
#define SPEED_OF_SOUND 29.1

volatile sig_atomic_t interrupt_flag = 0;

void signal_handler(int sig) {
    interrupt_flag = 1;
}

int main() {
    gpioInitialise();
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIG_PIN, 0);

    if (gpioSetup(ECHO_PIN, PI_INPUT, PI_PULLUP) < 0) {
        fprintf(stderr, "Failed to set up echo pin.\n");
        gpioTerminate();
        return 1;
    }

    while (!interrupt_flag) {
        if (gpioRead(TRIG_PIN) == 0) {
            gpioWrite(TRIG_PIN, 1);
            delayMicroseconds(TRIG_PULSE_US);
            gpioWrite(TRIG_PIN, 0);

            int echo_pulse_time = 0;
            int timeout = 0;

            gpioSetPulsePairTimeout(ECHO_PIN, TIMEOUT_MS * 1000, 0);
            echo_pulse_time = gpioPulsePair(ECHO_PIN, 1);

            if (echo_pulse_time == -1) {
                fprintf(stderr, "Timeout occurred while measuring echo pulse.\n");
                break;
            }

            float distance_cm = (echo_pulse_time / 2) / SPEED_OF_SOUND;

            if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
                printf("Invalid reading\n");
            } else {
                printf("Distance: %.2f cm", distance_cm);
                if (distance_cm < CLOSE_DISTANCE) {
                    printf(" Too close!\n");
                }
            }
        }

        delayMilliseconds(MEASUREMENT_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

