void sigint_handler(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    gpioInitialise();
    gpioSetMode(CHIP_SELECT, PI_OUTPUT);
    gpioSetMode(SPI_CS_PIN, PI_OUTPUT);

    if (gpioInitialiseSPI(SPI_PORT, SPI_DEVICE, SPI_CLOCK, SPI_MODE, 8, 0) < 0) {
