        return 1;
    }

    if (gpioSetSPIMode(SPI_PORT, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        return 1;
    }

    if (gpioWrite(CHIP_SELECT, 1) < 0) {
        fprintf(stderr, "Failed to assert chip select\n");
        return 1;
    }

    if (spiXfer(SPI_PORT, NULL, 0) < 0) {
        fprintf(stderr, "SPI transfer error\n");
        return 1;
    }

    if (spiXfer(SPI_PORT, (unsigned char*) &register_value, 1) < 0) {
        fprintf(stderr, "Failed to write to register\n");
        return 1;
    }

    register_value = 0x01;
    spiXfer(SPI_PORT, &register_value, 1);

    register_value = 0x00;
    spiXfer(SPI_PORT, &register_value, 1);

    register_value = 0x01;
    spiXfer(SPI_PORT, &register_value, 1);

