    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    atexit(close_log_file);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        if (spiXfer(SPI_PORT, spi_buffer, 2) < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        distance_mm = (spi_buffer[1] << 8) | spi_buffer[0];

