#include <time.h>
#include <errno.h>
#include <stdint.h>

#define SI1175_ADDR 0x60
#define REG_ALS_L 0x22
#define REG_ALS_H 0x23

int i2c_fd = -1;
FILE *log_file = NULL;

void log_reading(uint16_t als_visible) {
    static int header_written = 0;
    char timestamp[32];
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);

    if (!header_written) {
        fprintf(log_file, "timestamp,als_visible\n");
        header_written = 1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_struct);
    fprintf(log_file, "%s,%u\n", timestamp, als_visible);
}

int read_i2c(uint8_t reg, uint16_t *value) {
    uint8_t data[3];

    if (reg == REG_ALS_L) {
        data[0] = 0x00; // Register address for low byte
    } else if (reg == REG_ALS_H) {
        data[0] = 0x01; // Register address for high byte
    } else {
        fprintf(stderr, "Error: Invalid register address\n");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Error: Failed to acquire I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, data + 1) < 0) {
        perror("Error: Failed to read from I2C device");
        return -1;
    }

    *value = (data[1] << 8) | data[2];
    return 0;
}

int main() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Error: Failed to acquire I2C bus");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("proximity_log.csv", "w");
    if (!log_file) {
        perror("Error: Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint16_t als_visible;
    while (1) {
        if (read_i2c(REG_ALS_L, &als_visible) < 0) {
            break;
        }
        if (read_i2c(REG_ALS_H, &als_visible) < 0) {
            break;
        }
        log_reading(als_visible);
        usleep(5000000); // Sleep for 5 seconds
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

