code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define SI1120_ADDR 0x60
#define REG_PART_ID 0x00
#define REG_RESET 0x30
#define REG_ALS_LOW 0x22
#define REG_ALS_HIGH 0x23
#define REG_PROX_LOW 0x18
#define REG_PROX_HIGH 0x19
#define MAX_RETRIES 3
#define DELAY_MS 10

int i2c_read(int fd, uint8_t reg, uint16_t *value) {
    int retries = MAX_RETRIES;
    while (retries--) {
        if (pigpio_i2c_read(fd, reg, value, 2) < 0) {
            if (pigpio_terminal_state() & GPIO_TERMINATE_I2C) {
                fprintf(stderr, "I2C terminal state detected, giving up.\n");
                return -1;
            }
            fprintf(stderr, "I2C read failed, retrying...\n");
            sleep(DELAY_MS / 1000);
        } else {
            return 0;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

int main() {
    int fd;
    uint8_t part_id;
    uint16_t als, prox;
    FILE *log_file = NULL;
    char timestamp[20];

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    fd = i2c_open(1);
    if (fd < 0) {
        fprintf(stderr, "I2C bus 1 open failed.\n");
        pigpio_terminate();
        return 1;
    }

    if (i2c_write(fd, REG_RESET, &part_id, 1) < 0) {
        pigpio_terminate();
        return 1;
    }

    if (part_id != 0x41) {
        fprintf(stderr, "Invalid part ID: 0x%02X, expected 0x41.\n", part_id);
        i2c_close(fd);
        pigpio_terminate();
        return 1;
    }

    time_t t;
    time(&t);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));

    log_file = fopen("si1120_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        i2c_close(fd);
        pigpio_terminate();
        return 1;
    }

    while (1) {
        if (i2c_read(fd, REG_ALS_LOW, &als) < 0) {
            fprintf(stderr, "ALS read failed, exiting.\n");
            break;
        }
        if (i2c_read(fd, REG_ALS_HIGH, &als) < 0) {
            fprintf(stderr, "High ALS byte read failed, exiting.\n");
            break;
        }
        als = (als << 8) | (als & 0xFF);

        if (i2c_read(fd, REG_PROX_LOW, &prox) < 0) {
            fprintf(stderr, "Proximity read failed, exiting.\n");
            break;
        }
        if (i2c_read(fd, REG_PROX_HIGH, &prox) < 0) {
            fprintf(stderr, "High proximity byte read failed, exiting.\n");
            break;
        }
        prox = (prox << 8) | (prox & 0xFF);

        fprintf(log_file, "%s ALS: 0x%04X, Prox: 0x%04X\n", timestamp, als, prox);

        sleep(5);
    }

    fclose(log_file);
    i2c_close(fd);
    pigpio_terminate();
    return 0;
}

