#include <time.h>
#include <signal.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define MIN_DISTANCE_CM 20

static volatile int running = 1;
static int last_distance = -1;
static int buzzer_state = 0;

static void sigint_handler(int signum) {
    running = 0;
}

static void trigger_pulse(void) {
    gpioWrite(TRIG_PIN, 0);
    gpioWrite(TRIG_PIN, 1);
    gpioWrite(TRIG_PIN, 0);
}

static uint64_t get_time_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
}

static int measure_distance(void) {
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetAlertFuncEx(ECHO_PIN, PI_FALLING | PI_RISING, get_time_us, 0);

    trigger_pulse();

    while (1) {
        if (gpioRead(ECHO_PIN) == 0) {
            uint64_t start_time = get_time_us();
            while (gpioRead(ECHO_PIN) == 0);
            uint64_t end_time = get_time_us();

            uint64_t pulse_width_us = (end_time - start_time) / 1000;
            int distance_cm = pulse_width_us * 0.0343 / 2;

            if (distance_cm < MIN_DISTANCE_CM) {
                buzzer_state = 1;
            } else {
                buzzer_state = 0;
            }

            if (distance_cm != last_distance) {
                last_distance = distance_cm;
                printf("Distance: %.2f cm\n", distance_cm);
            }

            break;
        }
    }

    gpioSetAlertFuncEx(ECHO_PIN, 0, 0, 0);
    gpioWrite(TRIG_PIN, 0);

    return 0;
}

int main(int argc, char **argv) {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio_initialise() failed\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        pigpio_terminate();
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIG_PIN) failed\n");
        pigpio_terminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ECHO_PIN) failed\n");
        pigpio_terminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, PI_FALLING | PI_RISING, get_time_us, 0) < 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(ECHO_PIN) failed\n");
        gpioWrite(TRIG_PIN, 0);
        pigpio_terminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BUZZER_PIN) failed\n");
        gpioWrite(TRIG_PIN, 0);
        gpioSetAlertFuncEx(ECHO_PIN, 0, 0, 0);
        pigpio_terminate();
        return 1;
    }

    gpioWrite(BUZZER_PIN, buzzer_state);

    while (running) {
        measure_distance();
        gpioDelay(1000000); // Delay for 1 second
    }

    pigpio_terminate();
    gpioTerminate();

    return 0;
}

