#include <pigpio.h>
#include <unistd.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

int main() {
    int fd;
    gpioInitialise();

    if ((fd = gpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", gpioGetError());
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    int distance = -1.0;
    int servo_angle = 0;

    while (1) {
        gpioWrite(TRIG_PIN, 0);
        gpioWrite(TRIG_PIN, 1);
        gpioWrite(TRIG_PIN, 0);

        int start_time = gpioRead(ECHO_PIN);
        int end_time = 0;
        int duration = 0;

        while (gpioRead(ECHO_PIN) < start_time) {
            duration++;
        }

        end_time = gpioRead(ECHO_PIN);
        while (gpioRead(ECHO_PIN) < end_time) {
            duration++;
        }

        distance = (float)(duration * 17150) / 29; // cm

        if (distance == -1.0) {
            fprintf(stderr, "Echo timeout or error\n");
            break;
        }

        servo_angle = (int)((200 - distance) / 90 * 180);
        if (servo_angle < 0) servo_angle = 0;
        if (servo_angle > 180) servo_angle = 180;

        gpioWrite(SERVO_PIN, servo_angle);

        printf("Distance: %.2f cm, Servo angle: %d degrees\n", distance, servo_angle);
        gpioDelay(100000); // Delay for 100 ms
    }

    gpioTerminate();
    return 0;
}

