        end_time = gpioRead(ECHO_PIN);
        while (gpioRead(ECHO_PIN) < end_time) {
            duration++;
        }

        distance = (float)(duration * 17150) / 29; // cm

        if (distance == -1.0) {
            fprintf(stderr, "Echo timeout or error\n");
            break;
        }

        servo_angle = (int)((200 - distance) / 90 * 180);
        if (servo_angle < 0) servo_angle = 0;
        if (servo_angle > 180) servo_angle = 180;

        gpioWrite(SERVO_PIN, servo_angle);

        printf("Distance: %.2f cm, Servo angle: %d degrees\n", distance, servo_angle);
        gpioDelay(100000); // Delay for 100 ms
    }

    gpioTerminate();
    return 0;
}
