        pigpio_terminate(0);
        return 1;
    }

    if (i2c_write_word(fd, TIMING_BUDGET_REG, 0x00000600) < 0) {
        fprintf(stderr, "Failed to set timing budget.\n");
        i2c_close(fd);
        pigpio_terminate(0);
        return 1;
    }

    if (i2c_write_word(fd, 0x12, 0x0000) < 0) {
        fprintf(stderr, "Failed to start ranging.\n");
        i2c_close(fd);
        pigpio_terminate(0);
        return 1;
    }

    uint16_t distance;
    while (1) {
        if (i2c_read_word(fd, DIST_REG, &distance) < 0) {
