            pigpio_set_mode(gpio, SERVO_PIN, PI_OUTPUT);
            pigpio_write(gpio, SERVO_PIN, 1000);
            pigpio_set_servo_pulsewidth(gpio, SERVO_PIN, 1000);
        } else if (distance > OPEN_THRESHOLD) {
            log_event("Gate closed");
            pigpio_set_mode(gpio, SERVO_PIN, PI_OUTPUT);
            pigpio_write(gpio, SERVO_PIN, 2000);
            pigpio_set_servo_pulsewidth(gpio, SERVO_PIN, 2000);
        } else {
            pigpio_set_mode(gpio, SERVO_PIN, PI_OUTPUT);
            pigpio_write(gpio, SERVO_PIN, (1000 + 2000) / 2);
            pigpio_set_servo_pulsewidth(gpio, SERVO_PIN, (1000 + 2000) / 2);
        }

        usleep(100000); // Poll every 100 ms
    }

    i2c_close(fd);
    pigpio_terminate(0);
    return 0;
