#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 18
#define TIMEOUT 50000
#define TRIG_PULSE 10000
#define SPEED_OF_SOUND 343.0

float distance_to_angle(float distance) {
    if (distance < 0.2)
        return 0.0;
    else if (distance > 0.4)
        return 180.0;
    return distance * 90.0 / 2;
}

int main() {
    struct sigaction sa;

    // Initialize pigpio with error checking
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set up GPIOs
    gpioSetMode(TRIG_GPIO, PI_OUTPUT);
    gpioSetMode(ECHO_GPIO, PI_INPUT);
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Set up servo pulse width
    gpioServoRange(SERVO_GPIO, 500, 2500);

    // Signal handler for SIGINT (Ctrl+C)
    sa.sa_handler = (void (*)(int))cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        // Trigger the sensor
        gpioWrite(TRIG_GPIO, 1);
        delayMicroseconds(TRIG_PULSE);
        gpioWrite(TRIG_GPIO, 0);

        float start_time = gpioRead(ECHO_GPIO);
        float stop_time;
        int timeout_flag = 0;

        for (int i = 0; i < TIMEOUT; i++) {
            if (gpioRead(ECHO_GPIO) != 0) {
                stop_time = gpioRead(ECHO_GPIO);
                timeout_flag = 1;
                break;
            }
            delayMicroseconds(1);
        }

        if (!timeout_flag) {
            fprintf(stderr, "Echo timeout\n");
            break;
        }

        float pulse_width = (stop_time - start_time) * 17.2; // Convert gpioTick() values to microseconds
        float distance = (pulse_width * SPEED_OF_SOUND) / 2;

        float angle = distance_to_angle(distance);
        gpioServo(SERVO_GPIO, (long)(angle * 10));

        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        delayMicroseconds(100);
    }

    cleanup:
    gpioTerminate();
    return 0;
}

