#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMIDITY_REG 0x02

#define READING_INTERVAL 2

static int i2c_handle = -1;
static int config_written = 0;

void sigint_handler(int signum) {
    if (i2c_handle != -1) {
        gpioTerminate();
        close(i2c_handle);
        i2c_handle = -1;
    }
    exit(signum == SIGINT);
}

int main() {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d.\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(I2C_BUS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C bus %d as output.\n", I2C_BUS);
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(I2C_ADDR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set I2C address %x as input.\n", I2C_ADDR);
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(I2C_ADDR, 1) < 0) {
        fprintf(stderr, "Failed to assert I2C address %x.\n", I2C_ADDR);
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioI2CWrite(i2c_handle, &CONFIG_REG, 1, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register.\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }
    config_written = 1;
    usleep(10000);

    while (1) {
        if (gpioI2CWrite(i2c_handle, &TEMP_REG, 1, 0x00) < 0) {
            fprintf(stderr, "Failed to read temperature.\n");
            close(i2c_handle);
            gpioTerminate();
            return 1;
        }
        usleep(10000);

        uint16_t raw_temp = gpioRead(TEMP_REG);
        float temp = (175.72 * raw_temp) / 65536.0 - 46.85;
        printf("Temperature: %.2f C\n", temp);

        if (gpioI2CWrite(i2c_handle, &HUMIDITY_REG, 1, 0x00) < 0) {
            fprintf(stderr, "Failed to read humidity.\n");
            close(i2c_handle);
            gpioTerminate();
            return 1;
        }
        usleep(10000);

        uint16_t raw_humidity = gpioRead(HUMIDITY_REG);
        float humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;
        printf("Humidity: %.2f %%\n", humidity);

        usleep(READING_INTERVAL * 1000000);
    }

    close(i2c_handle);
    gpioTerminate();

    return 0;
}

