#include <stdio.h>
#include <stdlib.h>
#include <signal.d.h>
#include <pigpio.h>
#include <unistd.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define SLEEP 0x80
#define I2C_MST_CTRL 0xFE
#define SMPLRT_DIV 0x00
#define CONFIG 0x00
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define TEMP_OUT_H 0x41
#define TEMP_OUT_L 0x42

static int i2c_fd;
static gpio pigpio;

void sigint_handler(int signum) {
    gpioTerminate(pigpio);
    close(i2c_fd);
    printf("Clean shutdown.\n");
    exit(0);
}

int main() {
    gpioInitialise();
    pigpio = gpioInitialise();
    if (pigpio == 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate(pigpio);
        return 1;
    }

    if (i2c_rdwr_start(i2c_fd) < 0) {
        fprintf(stderr, "Failed to start I2C transaction.\n");
        i2c_close(i2c_fd);
        gpioTerminate(pigpio);
        return 1;
    }

    uint8_t reg_value;
    if (i2c_rdwr(i2c_fd, &reg_value, 1, NULL, 0) != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        i2c_close(i2c_fd);
        gpioTerminate(pigpio);
        return 1;
    }

    if (reg_value != 0x68) {
        fprintf(stderr, "MPU-6050 not found.\n");
        i2c_close(i2c_fd);
        gpioTerminate(pigpio);
        return 1;
    }

    if (i2c_wr(i2c_fd, PWR_MGMT_1) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1 register.\n");
        i2c_close(i2c_fd);
        gpioTerminate(pigpio);
        return 1;
    }

    if (i2c_rdwr(i2c_fd, NULL, 0, &reg_value, 1) != 1) {
        fprintf(stderr, "Failed to read PWR_MGMT_1 register.\n");
        i2c_close(i2c_fd);
        gpioTerminate(pigpio);
        return 1;
    }

    if (reg_value & SLEEP) {
        if (i2c_wr(i2c_fd, ~SLEEP) < 0) {
            fprintf(stderr, "Failed to clear SLEEP bit.\n");
            i2c_close(i2c_fd);
            gpioTerminate(pigpio);
            return 1;
        }
    }

    if (i2c_wr(i2c_fd, SMPLRT_DIV) < 0) {
        fprintf(stderr, "Failed to write sample-rate divider.\n");
        i2c_close(i2c_fd);
        gpioTerminate(pigpio);
        return 1;
    }

    if (i2c_wr(i2c_fd, ACCEL_CONFIG) < 0) {
        fprintf(stderr, "Failed to write accelerometer configuration.\n");
        i2c_close(i2c_fd);
        gpioTerminate(pigpio);
        return 1;
    }

    if (i2c_wr(i2c_fd, GYRO_CONFIG) < 0) {
        fprintf(stderr, "Failed to write gyroscope configuration.\n");
        i2c_close(i2c_fd);
        gpioTerminate(pigpio);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    printf("MPU-6050 initialized. Press Ctrl+C to exit.\n");

    while (1) {
        int16_t accel_x, accel_y, accel_z;
        int16_t gyro_x, gyro_y, gyro_z;
        int temp;

        if (i2c_rdwr(i2c_fd, &ACCEL_XOUT_H, 1, NULL, 0) != 1) {
            fprintf(stderr, "Failed to read accelerometer data.\n");
            continue;
        }

        if (i2c_rdwr(i2c_fd, &ACCEL_XOUT_L, 1, NULL, 0) != 1) {
            fprintf(stderr, "Failed to read accelerometer data.\n");
            continue;
        }

        if (i2c_rdwr(i2c_fd, &ACCEL_YOUT_H, 1, NULL, 0) != 1) {
            fprintf(stderr, "Failed to read accelerometer data.\n");
            continue;
        }

        if (i2c_rdwr(i2c_fd, &ACCEL_YOUT_L, 1, NULL, 0) != 1) {
            fprintf(stderr, "Failed to read accelerometer data.\n");
