#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define SHT40_ADDR 0x44
#define I2C_BUS 1
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

struct sht40_data {
    int i2c_fd;
    int gpio_fd;
    int i2c_handle;
};

static void sighandler(int signum) {
    printf("Exiting on signal %d\n", signum);
    pigpio_stop();
    exit(0);
}

static int read_crc8(const uint8_t *data, size_t len, uint8_t crc) {
    uint8_t crc_calc = crc;
    for (size_t i = 0; i < len; i++) {
        crc_calc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calc & 0x01) {
                crc_calc ^= CRC_POLY;
            }
            crc_calc >>= 1;
        }
    }
    return crc_calc == crc;
}

static int convert_raw_to_temp(uint16_t raw_temp) {
    return -45 + 175 * (float)raw_temp / 65535;
}

static int convert_raw_to_rh(uint16_t raw_rh) {
    return -6 + 125 * (float)raw_rh / 65535;
}

static void init_i2c(struct sht40_data *data) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    data->gpio_fd = gpio;
    if (i2c_open(I2C_BUS) < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    data->i2c_fd = fileno(stdout);
    data->i2c_handle = i2c_get_fd(I2C_BUS);
}

static void cleanup_i2c(struct sht40_data *data) {
    i2c_close(data->i2c_handle);
    i2c_free_fd(data->i2c_handle);
    gpioTerminate();
}

static uint8_t sht40_read(struct sht40_data *data, uint8_t cmd) {
    uint8_t buf[7];
    int ret;

    i2c_write(data->i2c_handle, &cmd, 1);
    usleep(10000);

    ret = i2c_read(data->i2c_handle, buf, 6);
    if (ret < 0) {
        fprintf(stderr, "I2C read error\n");
        i2c_close(data->i2c_handle);
        i2c_free_fd(data->i2c_handle);
        gpioTerminate();
        init_i2c(data);
        return -1;
    }

    if (!read_crc8(buf + 2, 2, buf[0]) || !read_crc8(buf + 4, 2, buf[1])) {
        fprintf(stderr, "CRC error\n");
        i2c_close(data->i2c_handle);
        i2c_free_fd(data->i2c_handle);
        gpioTerminate();
        init_i2c(data);
        return -1;
    }

    return buf[2];
}

int main(int argc, char *argv[]) {
    struct sht40_data data;
    int ret;

    signal(SIGINT, sighandler);
    signal(SIGTERM, sighandler);

    init_i2c(&data);

    while (1) {
        uint16_t raw_temp, raw_rh;
        uint8_t temp, rh;

        temp = sht40_read(&data, 0xFD);
        raw_temp = (temp << 8) | sht40_read(&data, 0xFE);
        rh = sht40_read(&data, 0xFD);
        raw_rh = (rh << 8) | sht40_read(&data, 0xFE);

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", convert_raw_to_temp(raw_temp), convert_raw_to_rh(raw_rh));

        usleep(5000000);
    }

    cleanup_i2c(&data);
    pigpio_stop();
    return 0;
}

