#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define MLX90614_ADDR 0x5A
#define REG_AMBIENT 0x06
#define REG_OBJECT 0x07
#define LOG_FILE "temperature_log.csv"

int i2c_fd = -1;
FILE *log_file = NULL;

void log_temperature(float ambient, float object) {
    if (log_file == NULL)
        return;

    fprintf(log_file, "%lu,%.2f,.%.2f\n", time(NULL), ambient, object);
    fflush(log_file);
}

int i2c_init(const char *dev) {
    i2c_fd = open(dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        perror("Failed to acquire i2c bus");
        return -1;
    }

    return 0;
}

int read_temp(uint8_t reg, float *temp) {
    uint8_t data[2];

    if (reg == REG_AMBIENT) {
        if (read(i2c_fd, data, 2) != 2) {
            fprintf(stderr, "Failed to read from ambient temperature register\n");
            return -1;
        }
    } else if (reg == REG_OBJECT) {
        if (read(i2c_fd, data, 2) != 2) {
            fprintf(stderr, "Failed to read from object temperature register\n");
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid register address\n");
        return -1;
    }

    *temp = (data[1] << 8) | data[0];
    *temp = *temp * 0.02; // Convert to Celsius

    return 0;
}

void cleanup() {
    if (i2c_fd >= 0)
        close(i2c_fd);

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    int ret;
    struct gi10_chip chip;

    ret = i2c_init("/dev/i2c-1");
    if (ret) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return ret;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return -1;
    }

    while (1) {
        float ambient_temp, object_temp;

        if ((ret = read_temp(REG_AMBIENT, &ambient_temp)) != 0) {
            cleanup();
            return ret;
        }

        if ((ret = read_temp(REG_OBJECT, &object_temp)) != 0) {
            cleanup();
            return ret;
        }

        log_temperature(ambient_temp, object_temp);
        usleep(5000000); // Sleep for 5 seconds
    }

    cleanup();
    return 0;
}

