#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define SDP810_ADDR 0x25
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define I2C_BUS 1
#define SAMPLE_INTERVAL 1000000 // 1 second
#define FILE_PATH "pressure_log.csv"

struct sensor_data {
    double pressure;
    double temperature;
};

int crc8(unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_data(struct sensor_data data) {
    FILE *file = fopen(FILE_PATH, "a");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file %s\n", FILE_PATH);
        return;
    }

    if (fgetc(file) == EOF) { // Check if file is empty
        fprintf(file, "timestamp,pressure,temperature\n");
    }
    fprintf(file, "%ld,%.2f,%.2f\n", (long)time(NULL), data.pressure, data.temperature);
    fclose(file);
}

int main() {
    int fd = pigpio_initialise();
    if (fd < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        pigpio_terminate(fd);
        return 1;
    }

    if (i2c_open(I2C_BUS) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d\n", I2C_BUS);
        gpioTermination(fd);
        pigpio_terminate(fd);
        return 1;
    }

    struct sensor_data data;
    while (1) {
        i2c_write_reg8(I2C_BUS, SDP810_ADDR, 0x36);
        i2c_write_reg8(I2C_BUS, SDP810_ADDR, 0x08);
        usleep(1000);

        i2c_read(I2C_BUS, SDP810_ADDR, 9, data.raw_data);

        if (data.raw_data[0] != 0x00 || data.raw_data[1] != 0x00) {
            fprintf(stderr, "Error: Sensor absent or bus error\n");
            break;
        }

        data.pressure = (float)((data.raw_data[2] << 8) | data.raw_data[3]) * 0.01;
        data.temperature = (float)((data.raw_data[4] << 8) | data.raw_data[5]) / 10.0;

        if (crc8(data.raw_data, 9) != data.raw_data[6]) {
            fprintf(stderr, "Error: CRC mismatch\n");
            break;
        }

        log_data(data);

        sleep(SAMPLE_INTERVAL / 1000);
    }

    i2c_close(I2C_BUS);
    gpioTermination(fd);
    pigpio_terminate(fd);

    return 0;
}

