#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define SHT40_ADDR 0x44
#define HIGH_REPEAT_MEASUREMENT 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

int i2c_fd = -1;
FILE *log_file = NULL;

void log_reading(double temp, double hum) {
    time_t now;
    struct tm *time_struct;
    char timestamp[20];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temp, hum);
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int ret;
    struct i2c_rdwr_ioctl_data rdwr;
    uint8_t write_buf[2] = {HIGH_REPEAT_MEASUREMENT, 0x00};
    uint8_t read_buf[7];
    double temp, hum;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("sht40_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        rdwr.frm = (struct i2c_rdwr_desc) {
            .addr = SHT40_ADDR,
            .flags = 0,
            .len = sizeof(read_buf),
            .buf = read_buf,
        };

        rdwr.frms = 1;

        ret = ioctl(i2c_fd, I2C_RDWR(write_buf, read_buf), sizeof(write_buf) + sizeof(read_buf));
        if (ret < 0) {
            perror("Failed to perform I2C transaction");
            continue;
        }

        if (crc8(read_buf, 6) != read_buf[6]) {
            fprintf(stderr, "CRC mismatch, retrying...\n");
            continue;
        }

        temp = -45 + 175 * (read_buf[1] << 8 | read_buf[0]) / 65535;
        hum = 100 * (read_buf[3] << 8 | read_buf[2]) / 65535;

        log_reading(temp, hum);
        sleep(5);
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

