#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <signal.h>

#define SENS_ADDR 0x28
#define TRIG_CMD 0x21
#define TRIG_CMD_HIGH 0x96
#define SAMPLE_INTERVAL 100000 // 100 ms in µs
#define MAX_RETRIES 3

volatile sig_atomic_t sigint_received = 0;
FILE *log_file = NULL;

void sigint_handler(int signum) {
    sigint_received = 1;
}

int i2c_write_retry(int fd, unsigned char *data, int len) {
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = i2cWriteDevice(fd, data, len);
        if (ret >= 0) {
            return ret;
        }
        retries++;
        // Exponential backoff
        usleep(2 << retries);
    }

    return -1;
}

int i2c_read_retry(int fd, unsigned char *data, int len) {
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = i2cReadDevice(fd, data, len);
        if (ret >= 0) {
            return ret;
        }
        retries++;
        // Exponential backoff
        usleep(2 << retries);
    }

    return -1;
}

int main() {
    gpioInitialise();
    i2cOpen(1, &i2c_fd);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    log_file = fopen("airflow.log", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (!sigint_received) {
        unsigned char trig_cmd[2] = {TRIG_CMD, TRIG_CMD_HIGH};

        if (i2c_write_retry(i2c_fd, trig_cmd, sizeof(trig_cmd)) < 0) {
            fprintf(stderr, "I2C write failed, exiting...\n");
            break;
        }

        usleep(SAMPLE_INTERVAL);

        unsigned char data[6];
        if (i2c_read_retry(i2c_fd, data, 6) < 0) {
            fprintf(stderr, "I2C read failed, exiting...\n");
            break;
        }

        int32_t raw_pressure = (int32_t)(data[1] << 8 | data[0]);
        int32_t raw_temperature = (int32_t)(data[3] << 8 | data[2]);

        double pressure_pa = (double)raw_pressure / 60.0;
        double temperature_c = (double)raw_temperature / 200.0;

        time_t now = time(NULL);
        struct tm tm;
        localtime_r(&now, &tm);

        fprintf(log_file, "%ld,%.2f,%.2f\n", (int)(tm.tm_hour * 3600 + tm.tm_min * 60 + tm.tm_sec), pressure_pa, temperature_c);
    }

    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

