#include <string.h>
#include <time.h>
#include <errno.h>
#include <pigio.h>

#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUM_CMD 0xF5
#define MAX_RETRIES 5

void log_reading(double temp, double hum) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *fp = fopen("sensor_data.txt", "a");
    if (!fp) {
        perror("Failed to open 'sensor_data.txt'");
        return;
    }
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temp, hum);
    fclose(fp);

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temp, hum);
}

double read_temperature() {
    int raw_temp;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (pigpio_i2c_write_device(gpio, SI7015_ADDR, (uint8_t *)&TEMP_CMD, 1) < 0) {
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }

        if (pigpio_i2c_read_device(gpio, SI7015_ADDR, (uint8_t *)&raw_temp, 2) < 0) {
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }

        if ((raw_temp >> 7) & 0x1) {
            break;
        }
        retries++;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error: Failed to read temperature after %d retries\n", MAX_RETRIES);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    return (175.72 * raw_temp / 65536.0) - 46.85;
}

double read_humidity() {
    int raw_humidity;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (pigpio_i2c_write_device(gpio, SI7015_ADDR, (uint8_t *)&HUM_CMD, 1) < 0) {
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }

        if (pigpio_i2c_read_device(gpio, SI7015_ADDR, (uint8_t *)&raw_humidity, 2) < 0) {
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }

        if ((raw_humidity >> 7) & 0x1) {
            break;
        }
        retries++;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error: Failed to read humidity after %d retries\n", MAX_RETRIES);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

int main() {
    int gpio = pigpio_initialise();
    if (gpio < 0) {
        perror("pigpio_initialise");
        return EXIT_FAILURE;
    }

    if (i2c_open(gpio, 1) < 0) {
        pigpio_terminate();
        perror("i2c_open");
        return EXIT_FAILURE;
    }

    double temp, hum;
    while (1) {
        temp = read_temperature();
        hum = read_humidity();
        log_reading(temp, hum);
        printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temp, hum);
        sleep(5);
    }

    pigpio_terminate();
    i2c_close(gpio);
    return EXIT_SUCCESS;
}

