#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define SDP800_ADDR 0x25
#define CHECKSUM_POLYNOMIAL 0x07
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "airflow_data.txt"
#define SAMPLE_INTERVAL_MS 100

static FILE *log_file = NULL;

int main() {
    int file_desc;
    char msg[100];
    struct i2c_rdwr_ioctl_data rdwr;
    struct timespec next_sample;
    time_t now;

    file_desc = open(I2C_BUS, O_RDWR);
    if (file_desc < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(file_desc, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file_desc);
        return 1;
    }

    rdwr.u8 = 0x36;
    rdwr.u8len = 1;
    rdwr.u9 = 0x2F;
    rdwr.u9len = 1;

    if (ioctl(file_desc, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to send command to SDP800");
        close(file_desc);
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &next_sample);
    next_sample.tv_sec += SAMPLE_INTERVAL_MS / 1000;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now >= next_sample) {
            rdwr.u8 = 0;
            rdwr.u8len = 9;

            if (ioctl(file_desc, I2C_RDWR, &rdwr) < 0) {
                perror("Failed to read from SDP800");
                continue;
            }

            int pressure_raw = (rdwr.u8[0] << 8) | rdwr.u8[1];
            int temp_raw = (rdwr.u8[3] << 8) | rdwr.u8[4];
            int scale_factor = (rdwr.u8[6] << 8) | rdwr.u8[7];

            if (validate_crc8((uint8_t *)rdwr.u8, rdwr.u8len, CHECKSUM_POLYNOMIAL) != 0) {
                fprintf(stderr, "CRC error\n");
                continue;
            }

            float pressure = (float)pressure_raw / scale_factor;
            float temp = (float)temp_raw / 200 - 45;

            if (log_file == NULL) {
                log_file = fopen(LOG_FILE, "w");
                if (!log_file) {
                    perror("Failed to open log file");
                    close(file_desc);
                    return 1;
                }
                fprintf(log_file, "Timestamp,Pressure(Pa),Temperature(C)\n");
            }

            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            strftime(msg, sizeof(msg), "%Y-%m-%d %H:%M:%S", &tm);

            fprintf(log_file, "%s,%.2f,%.2f\n", msg, pressure, temp);

            next_sample.tv_sec += SAMPLE_INTERVAL_MS / 1000;
        }

        sleep(1);
    }

    fclose(log_file);
    close(file_desc);

    return 0;
}

int validate_crc8(const void *data, size_t len, unsigned char polynomial) {
    unsigned char crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= (unsigned char)data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

