#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigio.h>

#define SENSOR_ADDR 0x4A
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SAMPLE_INTERVAL 5000000 // 5 seconds in µs
#define CONVERSION_DELAY 15000 // 15 ms in µs

int i2c_fd;
gpioReceiveSetup rsetup[];
gpioGeneralSetup gsetup;

void sigint_handler(int signum) {
    gpioTerminate();
    pigpio_stop();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = i2c_open(1, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Error initialising pigpio library\n");
        i2c_close(i2c_fd);
        return 1;
    }

    gsetup = gpioGeneralSetup(0, 0);
    if (gpioReceiveSetup_init(rsetup, 3, 8, 0) < 0) {
        fprintf(stderr, "Error initialising gpioReceiveSetup\n");
        pigpio_terminate();
        i2c_close(i2c_fd);
        return 1;
    }

    while (1) {
        // Issue single-shot measurement command
        const uint8_t cmd[2] = {0x2C, 0x06};
        if (i2c_write(i2c_fd, SENSOR_ADDR, cmd, 2) != 2) {
            fprintf(stderr, "Error writing to sensor\n");
            break;
        }

        // Wait for conversion
        usleep(CONVERSION_DELAY);

        // Read 3 bytes
        uint8_t data[3];
        if (i2c_read(i2c_fd, SENSOR_ADDR, data, 3) != 3) {
            fprintf(stderr, "Error reading from sensor\n");
            break;
        }

        // Validate CRC-8
        uint8_t crc = data[2];
        uint8_t expected_crc = crc_ccitt(data, 2, CRC_INIT, CRC_POLY);
        if (crc != expected_crc) {
            fprintf(stderr, "CRC mismatch\n");
            break;
        }

        // Convert raw value to Celsius
        int16_t raw = (int16_t)(data[0] << 8 | data[1]);
        float temp = -45 + 175 * (raw / 65535);

        // Log temperature reading
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        FILE *log_file = fopen("enclosure_temp_log.txt", "a");
        if (log_file != NULL) {
            fprintf(log_file, "%s, %f\n", timestamp, temp);
        }
        fclose(log_file);

        // Sleep until next sample
        this_micros() = SAMPLE_INTERVAL;
        while (this_micros() < SAMPLE_INTERVAL) {}
    }

    gpioTerminate();
    pigpio_stop();
    i2c_close(i2c_fd);
    return 0;
}

