uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    struct i2c_rdwr_ioctl_data rdwr_data;
    rdwr_data.msgs = NULL;
    rdwr_data.nmsgs = 0;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        log_error("Failed to acquire I2C bus\n");
        close_resources();
        return 1;
    }

    log_file = fopen("sht40_log.txt", "w");
    if (!log_file) {
        log_error("Failed to open log file\n");
        close_resources();
        return 1;
    }

    while (1) {
        rdwr_data.u.rd = (struct i2c_rdwr_regs) {
            .addr = SHT40_ADDR,
            .flags = 0,
            .len = 1,
            .buf = &HIGH_REPEAT_CMD,
        };
        rdwr_data.msgs = &rdwr_data.u.rd;
        rdwr_data.nmsgs = 1;

        if (ioctl(i2c_fd, I2C_RDWR, &rdwr_data) < 0) {
            log_error("Failed to write to I2C device\n");
            continue;
        }

        usleep(8500000); // Wait at least 8.5 ms

        rdwr_data.u.wr = (struct i2c_rdwr_regs) {
            .addr = SHT40_ADDR,
            .flags = 0,
            .len = 6,
            .buf = &rdwr_data.u.rd.len,
        };
        rdwr_data.msgs = &rdwr_data.u.wr;
        rdwr_data.nmsgs = 1;

        if (ioctl(i2c_fd, I2C_RDWR, &rdwr_data) < 0) {
            log_error("Failed to read from I2C device\n");
            continue;
        }

        uint8_t raw_data[6];
        memcpy(raw_data, rdwr_data.u.wr.buf, 6);

        if (crc8(raw_data, 6) != raw_data[5]) {
            log_error("CRC failure\n");
            continue;
        }

        float temp = -45 + 175 * (raw_data[0] << 8 | raw_data[1]) / 65535;
        float rh = 100 * (raw_data[2] << 8 | raw_data[3]) / 65535;

        time_t t = time(NULL);
        fprintf(log_file, "%ld: Temp = %.2f C, RH = %.2f %%\n", t, temp, rh);
    }

    close_resources();
    return 0;
}
