#include <time.h>

#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT 0x362F
#define I2C_DEVICE "/dev/i2c-1"
#define FILE_LOG "airflow_data.txt"
#define CRC_POLYNOMIAL 0x31
#define SCALE_FACTOR 240
#define TEMP_SCALE 200
#define TEMP_OFFSET -45

int i2c_fd = -1;
FILE *log_file = NULL;

void log_data(double pressure, double temperature) {
    if (log_file == NULL) return;
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%.2f,%.2f\n", now, pressure, temperature);
    fflush(log_file);
}

uint8_t crc8(uint8_t *data, size_t length, uint8_t init_val) {
    uint8_t crc = init_val;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

double read_pressure_pa(uint8_t *data) {
    return (data[1] << 8 | data[0]) * SCALE_FACTOR;
}

double read_temperature_c(uint8_t *data) {
    return (data[3] << 8 | data[2]) * TEMP_SCALE / 100 - TEMP_OFFSET;
}

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(FILE_LOG, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t write_buffer[2] = {CONTINUOUS_MEASUREMENT >> 8, CONTINUOUS_MEASUREMENT & 0xFF};
    if (write(i2c_fd, write_buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t read_buffer[6];
    if (nread(i2c_fd, read_buffer, 6) != 6) {
        perror("Failed to read from I2C device");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t crc_read = (read_buffer[1] << 8 | read_buffer[0]) ^ (read_buffer[3] << 8 | read_buffer[2]);
    if (crc8(read_buffer, 4, 0xFF) != crc_read) {
        fprintf(stderr, "CRC mismatch for pressure data\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (crc8(read_buffer + 4, 4, 0xFF) != (read_buffer[5] << 8 | read_buffer[4])) {
        fprintf(stderr, "CRC mismatch for temperature data\n");
        cleanup();
        return EXIT_FAILURE;
    }

    double pressure = read_pressure_pa(read_buffer);
    double temperature = read_temperature_c(read_buffer + 4);

    log_data(pressure, temperature);

    cleanup();
    return EXIT_SUCCESS;
}

ssize_t nread(int fd, void *buf, size_t count) {
    ssize_t n;
    struct i2c_rdwr_ioctl_data rdwr;

    rdwr.addr = SDP800_ADDR;
    rdwr.flags = 0;
    rdwr.len = count;
    rdwr.buf = (unsigned char *)buf;

    n = ioctl(fd, I2C_RDWR(SDP800_ADDR, &rdwr, count));
    if (n < 0) {
        perror("I2C read error");
    }
    return n;
}

