#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigio.h>

#define BUFFER_SIZE 60
#define I2C_ADDR 0x40
#define TEMP_REG 0xF4
#define HUM_REG 0xF6
#define HOLD_MASTER_TEMP 0xE3
#define HOLD_MASTER_HUM 0xE5
#define FAN_GPIO 18
#define TEMP_THRESHOLD 28.0
#define HYSTERESIS 0.1
#define I2C_RETRY_COUNT 3

typedef struct {
    float temp;
    float humidity;
    time_t timestamp;
} Reading;

Reading readings[BUFFER_SIZE];
int read_index = 0;

void sigint_handler(int signum) {
    gpioTerminate();
    pigpio_stop();
    printf("\nExiting...\n");
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio_initialise() failed\n");
        return 1;
    }

    if (gpio_initialise() < 0) {
        fprintf(stderr, "gpio_initialise() failed\n");
        pigpio_terminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(FAN_GPIO, PI_PULLUP);
    gpioWrite(FAN_GPIO, 0);

    int i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "i2c_open() failed\n");
        gpio_terminate();
        pigpio_terminate();
        return 1;
    }

    if (i2c_rdwr_setup(i2c_fd, 0x40, 2) < 0) {
        fprintf(stderr, "i2c_rdwr_setup() failed\n");
        i2c_close(i2c_fd);
        gpio_terminate();
        pigpio_terminate();
        return 1;
    }

    while (1) {
        float temp_raw, hum_raw;
        int retries = 0;

        while (retries < I2C_RETRY_COUNT) {
            if (i2c_write_rd_wr(i2c_fd, &HOLD_MASTER_TEMP, 1) < 0) {
                retries++;
                continue;
            }

            if (i2c_rd_wr(i2c_fd, (void *)&temp_raw, 2) < 0) {
                retries++;
                continue;
            }

            if (i2c_write_rd_wr(i2c_fd, &HOLD_MASTER_HUM, 1) < 0) {
                retries++;
                continue;
            }

            if (i2c_rd_wr(i2c_fd, (void *)&hum_raw, 2) < 0) {
                retries++;
                continue;
            }

            break;
        }

        if (retries == I2C_RETRY_COUNT) {
            fprintf(stderr, "Failed to read from Si7021 after %d retries\n", I2C_RETRY_COUNT);
            continue;
        }

        temp_raw = ntohs(temp_raw);
        hum_raw = ntohs(hum_raw);

        float temp = 175.72 * temp_raw / 65536.0 - 46.85;
        float humidity = 125.0 * hum_raw / 65536.0 - 6.0;

        readings[read_index].temp = temp;
        readings[read_index].humidity = humidity;
        readings[read_index].timestamp = time(NULL);

        read_index = (read_index + 1) % BUFFER_SIZE;

        printf("%ld: Temp=%.2f°C, Humidity=%.2f%%\n", (long)readings[read_index].timestamp, temp, humidity * 100);

        if (temp > TEMP_THRESHOLD - HYSTERESIS) {
            gpioWrite(FAN_GPIO, 1);
        } else if (temp < TEMP_THRESHOLD - HYSTERESIS) {
            gpioWrite(FAN_GPIO, 0);
        }

        sleep(2);
    }

    i2c_close(i2c_fd);
    gpio_terminate();
    pigpio_terminate();

    return 0;
}

