#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigio.h>

#define SCD40_I2C_ADDR 0x62
#define START_MEASUREMENT 0x21B1
#define STOP_MEASUREMENT 0x3F86
#define DATA_READY 0xE4B8
#define READ_DATA 0xEC05
#define CRC_POLYNOMIAL 0x31

#define CRC8_INIT 0xFF

int i2c_fd;
gpio *gpio_handle;

void sigint_handler(int signum) {
    if (gpio_handle) gpio_terminate();
    if (i2c_fd != -1) close(i2c_fd);
    if (log_file != NULL) fclose(log_file);
    exit(0);
}

void log_air_quality(const char *timestamp, float co2_ppm, float temperature, float humidity) {
    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.1f,%.1f\n", timestamp, co2_ppm, temperature, humidity);
        fflush(log_file);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    gpio_init();
    gpio_handle = gpio_init();
    if (!gpio_handle) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    i2c_fd = i2c_open(0, 1000000);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpio_terminate();
        return 1;
    }

    if (i2c_write_byte(i2c_fd, SCD40_I2C_ADDR, START_MEASUREMENT)) {
        fprintf(stderr, "Failed to send Start Periodic Measurement command.\n");
        close(i2c_fd);
        gpio_terminate();
        return 1;
    }

    gpio_set_mode(gpio_handle, 17, PI_OUTPUT);
    gpio_write(gpio_handle, 17, 1);

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        float co2_ppm = 0.0;
        float temperature = 0.0;
        float humidity = 0.0;

        if (i2c_read_byte_timeout(i2c_fd, SCD40_I2C_ADDR, DATA_READY, 1000000)) {
            fprintf(stderr, "Failed to check data-ready flag.\n");
            continue;
        }

        if (i2c_read_bytes_timeout(i2c_fd, SCD40_I2C_ADDR, READ_DATA, 9, 1000000)) {
            fprintf(stderr, "Failed to read data from SCD40.\n");
            continue;
        }

        uint8_t data[9];
        memcpy(data, i2c_buffer, 9);

        uint16_t crc = crc8_calc(data, 9, CRC_POLYNOMIAL, CRC8_INIT);
        if (crc != data[8]) {
            fprintf(stderr, "CRC check failed.\n");
            continue;
        }

        co2_ppm = data[0];
        temperature = -45 + 175 * (data[2] >> 8);
        humidity = 100 * (data[3] >> 8);

        log_air_quality(timestamp, co2_ppm, temperature, humidity);

        sleep(5);
    }

    close(i2c_fd);
    gpio_terminate();
    return 0;
}

uint16_t crc8_calc(const uint8_t *data, size_t len, uint8_t polynomial, uint8_t init_value) {
    uint16_t crc = init_value;
    for (size_t i = 0; i < len; i++) {
        crc ^= (uint16_t)data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x8000) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

