        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        pigpio_stop();
        exit(1);
    }
}

void close_i2c() {
    if (i2cClose(i2c_handle) < 0) {
        fprintf(stderr, "Failed to close I2C bus 1\n");
    }
}

