    uint16_t data[3];
    uint8_t crc_valid;

    if (i2cRead(i2c_handle, I2C_ADDR, (uint8_t*)data, 6) != 6) {
        fprintf(stderr, "Failed to read data from I2C\n");
        return 0;
    }

    crc_valid = (data[4] == (data[5] << 8 | data[6]));

    for (int i = 0; i < 3; i++) {
        if (!crc_valid) {
            fprintf(stderr, "CRC-8 checksum invalid\n");
            return 0;
        }
    }

    return (data[0] << 8 | data[1]);
}

void log_reading(Reading* reading) {
    readings_buffer[read_index++] = *reading;
    if (read_index >= BUFFER_SIZE) {
        read_index = 0;
    }
}

void print_readings() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (readings_buffer[i].crc_valid) {
            printf("CO2: %d ppm, Temp: %.2f °C, Humidity: %.2f %%\n",
                   readings_buffer[i].co2, readings_buffer[i].temp, readings_buffer[i].humidity);
        }
    }
}

int main(int argc, char** argv) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_pigpio();
    init_i2c();
    start_measurement();

    while (1) {
        if (get_data_ready()) {
            uint16_t co2 = read_measurement();
            float temp = (float)co2 / 65535 * 1000; // Assuming linear relationship
            float humidity = (float)co2 / 65535 * 100; // Assuming linear relationship

            Reading reading = {co2, temp, humidity, 1};
            log_reading(&reading);

            if (co2 > 1000) {
                gpioSetOutputLevel(LED_GPIO, 1);
            } else {
                gpioSetOutputLevel(LED_GPIO, 0);
            }

            print_readings();
        }

        gpioWaitEvent(LED_GPIO, PI_FALLING);
        usleep(MEASUREMENT_INTERVAL);
    }

    stop_measurement();
    close_i2c();
    gpioTerminate();
    pigpio_stop();

    return 0;
}

