#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 5000000 // 5 seconds
#define EDGE_TIMEOUT 50000 // 50 ms
#define MIN_TEMP -40
#define MAX_TEMP 150
#define CONSECUTIVE_FAILURE_THRESHOLD 3

int main() {
    int fd;
    gpioInit();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    fd = fopen("temperature_log.txt", "a");
    if (!fd) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    const gpio pin = GPIO_PIN;
    int th, tl, temp;
    int failure_count = 0;
    unsigned long last_sample_time = 0;

    while (1) {
        unsigned long start_time = gpioGetTime();
        int high_wait_count = 0;

        // Wait for rising edge
        if (gpioWaitEdge(pin, 1, EDGE_TIMEOUT) < 0) {
            fprintf(stderr, "Timeout waiting for rising edge on GPIO%d.\n", pin);
            failure_count++;
            continue;
        }

        // Count high pulses until falling edge
        while (gpioRead(pin) == 1) {
            high_wait_count++;
        }

        // Wait for falling edge
        if (gpioWaitEdge(pin, 0, EDGE_TIMEOUT) < 0) {
            fprintf(stderr, "Timeout waiting for falling edge on GPIO%d.\n", pin);
            failure_count++;
            continue;
        }

        unsigned long end_time = gpioGetTime();
        tl = (end_time - start_time);
        th = high_wait_count;

        if (tl == 0) {
            fprintf(stderr, "Division by zero detected.\n");
            failure_count++;
            continue;
        }

        temp = 4215 - (2143 * (float)th / (float)tl);

        if (temp < MIN_TEMP || temp > MAX_TEMP) {
            fprintf(stderr, "Invalid temperature reading: %d °C\n", temp);
            failure_count++;
            continue;
        }

        if (end_time - last_sample_time < SAMPLE_INTERVAL) {
            continue;
        }
        last_sample_time = end_time;

        struct time_t now_time = time(NULL);
        char timestamp[24];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now_time));

        fprintf(fd, "%s, Temperature: %d °C\n", timestamp, temp);

        if (failure_count >= CONSECUTIVE_FAILURE_THRESHOLD) {
            fprintf(fd, "SENSOR MALFUNCTION\n");
            break;
        }

        failure_count = 0;
    }

    gpioTerminate();
    fclose(fd);
    return 0;
}

