#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>

#define SHT35_ADDR 0x44
#define CRC_POLY 0x07
#define MAX_RETRIES 3
#define DELAY_MS 1000
#define FILENAME "environmental_data.txt"

struct sht35_data {
    int16_t temp;
    int16_t hum;
};

void sine_offset(double *val, double amplitude, double frequency, double phase) {
    *val += amplitude * sin(2 * M_PI * frequency * time(NULL) + phase);
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    struct iovec iov = { .iov_base = buf, .iov_len = len };
    ssize_t bytes_read;

    do {
        bytes_read = ioctl(fd, I2C_RDWR, &reg);
        if (bytes_read < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            return -1;
        }
        bytes_read -= reg;
        if (bytes_read < len) {
            return -1;
        }
    } while (bytes_read > 0);

    return bytes_read;
}

int main() {
    int i2c_fd = -1;
    int pigpio_fd = -1;
    struct sht35_data data;
    int retries = 0;
    time_t last_log = 0;

    pigpio_init();
    pigpio_set_mode(0, PI_OUTPUT);
    pigpio_set_mode(1, PI_INPUT);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto finish;
    }

    if (pigpio_request(1, 1000000) < 0) {
        perror("Failed to claim GPIO for I2C");
        goto close_i2c;
    }

    while (1) {
        if (time(NULL) - last_log >= 5) {
            last_log = time(NULL);

            // Read temperature and humidity
            uint8_t buf[6];
            if (i2c_read(i2c_fd, 0x06, buf, 6) != 6) {
                continue;
            }

            data.temp = (buf[1] << 8) | buf[0];
            data.hum = (buf[3] << 8) | buf[2];

            // Validate CRC
            uint8_t crc = (buf[4] << 8) | buf[5];
            uint32_t crc_calc = 0xFFFF;
            for (int i = 0; i < 5; i++) {
                crc_calc ^= buf[i];
                for (int j = 0; j < 8; j++) {
                    if (crc_calc & 0x8000) {
                        crc_calc = (crc_calc << 1) ^ CRC_POLY;
                    } else {
                        crc_calc <<= 1;
                    }
                }
            }

            if (crc != crc_calc) {
                if (retries++ < MAX_RETRIES) {
                    usleep(DELAY_MS * 1000);
                    continue;
                }
                data.temp = NAN;
                data.hum = NAN;
            } else {
                retries = 0;
            }

            // Apply sinusoidal offset
            sine_offset(&data.temp, 2.0, 1 / 3600.0, M_PI / 2);
            sine_offset(&data.hum, 5.0, 1 / 3600.0, M_PI / 4);
        }

        // Log data
        FILE *log_file = fopen("environmental_data.txt", "a");
        if (!log_file) {
            perror("Failed to open log file");
            goto close_i2c;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.000Z %d.%02dC %d.%02d%%RH\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                (int)data.temp, (int)((data.temp - (int)data.temp) * 100),
                (int)data.hum, (int)((data.hum - (int)data.hum) * 100));
        fclose(log_file);
    }

close_i2c:
    close(i2c_fd);
finish:
    pigpio_terminate();

    return 0;
}

void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT, cleaning up...\n");
    pigpio_terminate();
    close(i2c_fd);
    remove(FILENAME);
    exit(signum == SIGINT ? 0 : 1);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return execv("/usr/bin/env", {"/usr/bin/env", NULL});
}

