        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.000Z %d.%02dC %d.%02d%%RH\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                (int)data.temp, (int)((data.temp - (int)data.temp) * 100),
                (int)data.hum, (int)((data.hum - (int)data.hum) * 100));
        fclose(log_file);
    }

close_i2c:
    close(i2c_fd);
finish:
    pigpio_terminate();

    return 0;
}

void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT, cleaning up...\n");
    pigpio_terminate();
    close(i2c_fd);
    remove(FILENAME);
    exit(signum == SIGINT ? 0 : 1);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return execv("/usr/bin/env", {"/usr/bin/env", NULL});
}
```

This code initializes the pigpio library, opens the I2C bus, and sets up GPIO modes. It reads temperature and humidity from the SHT35 sensor, validates CRC, applies sinusoidal offsets, and logs data in ISO-8601 UTC format every 5 seconds. It handles errors during initialization, I2C operations, and file operations, and implements graceful shutdown on SIGINT and SIGTERM.

