#define SDP810_ADDR 0x25
#define CONVERSION_TIME_MS 45
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

struct sdp810_data {
    uint8_t pressure;
    uint8_t temperature;
    uint8_t scale_factor;
};

uint8_t crc8(uint8_t *data, size_t len, uint8_t init_crc) {
    uint8_t crc = init_crc;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

struct sdp810_data read_sdp810(int fd) {
    struct sdp810_data data;
    uint8_t buf[9];

    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_export(&gpio_chip, "i2c-dev") < 0) {
        fprintf(stderr, "Error exporting I2C GPIO\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip_config chip_config = gpiod_chip_config_init("i2c-dev");
    chip_config.direction = GPIO_DIR_OUT;
    chip_config.options = GPIO_OPT_OPEN_DRAIN;
    if (gpiod_chip_set_config(gpio_chip, &chip_config) < 0) {
        fprintf(stderr, "Error configuring I2C GPIO\n");
        gpiod_chip_free(&gpio_chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_set_value(gpio_chip, 0, 1) < 0) {
        fprintf(stderr, "Error setting I2C GPIO high\n");
        gpiod_chip_free(&gpio_chip);
        close(fd);
        exit(EXIT_FAILURE);
    }
    usleep(CONVERSION_TIME_MS * 1000);
    if (gpiod_chip_set_value(gpio_chip, 0, 0) < 0) {
        fprintf(stderr, "Error setting I2C GPIO low\n");
        gpiod_chip_free(&gpio_chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (write(fd, &0x36, 1) != 1) {
        fprintf(stderr, "Error sending command to SDP810\n");
        gpiod_chip_free(&gpio_chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (read(fd, buf, 9) != 9) {
        fprintf(stderr, "Error reading from SDP810\n");
        gpiod_chip_free(&gpio_chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    data.pressure = buf[0];
    data.temperature = (buf[1] << 8) | buf[2];
    data.scale_factor = buf[3];

    data.pressure ^= (uint8_t)crc8((uint8_t *)&data.pressure, 1, CRC_INIT);
    data.temperature ^= (uint8_t)crc8((uint8_t *)&data.temperature, 2, CRC_INIT);
    data.scale_factor ^= (uint8_t)crc8((uint8_t *)&data.scale_factor, 1, CRC_INIT);

    if (data.pressure != buf[4] || data.temperature != (buf[5] << 8) | buf[6] || data.scale_factor != buf[7]) {
        fprintf(stderr, "CRC mismatch\n");
        gpiod_chip_free(&gpio_chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_free(&gpio_chip);
    close(fd);

    return data;
}

float pressure_to_pa(uint16_t pressure_raw) {
    return (float)pressure_raw * 0.02490074;
}

float temperature_to_celsius(uint16_t temperature_raw) {
    return (float)temperature_raw * 0.01;
}

int main() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Error setting SDP810 address\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct sdp810_data data;
    FILE *fp = fopen("airflow.csv", "w");
    if (!fp) {
        fprintf(stderr, "Error opening airflow.csv\n");
        close(fd);
        return EXIT_FAILURE;
    }

    fprintf(fp, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    while (1) {
        data = read_sdp810(fd);
        time_t now = time(NULL);
        fprintf(fp, "%ld,%.6f,%.2f\n", now, pressure_to_pa(data.pressure), temperature_to_celsius(data.temperature));
        fflush(fp);
        sleep(1);
    }

    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

