#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define SHT35_ADDR 0x44
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SAMPLE_INTERVAL 5000000 // 5 seconds
#define MIN_WAIT_US 15000

static FILE *fp = NULL;
static gpio pigpio = GPIO_UNINITIALIZED;

void sigint_handler(int signum) {
    gpioTerminate(pigpio);
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }
    pigpio = gpio;

    if (i2cOpen(pigpio, 1, SHT35_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate(pigpio);
        return 1;
    }

    if (fp == NULL) {
        fp = fopen("environment.csv", "a");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open 'environment.csv' for writing.\n");
            i2cClose(pigpio, SHT35_ADDR);
            gpioTerminate(pigpio);
            return 1;
        }

        if (fgets(NULL, 0, fp) == NULL) { // File is empty or doesn't exist
            fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
        }
    }

    while (1) {
        uint8_t data[6];
        uint16_t crc;

        // Send measurement command
        i2cWriteReg8(pigpio, SHT35_ADDR, 0x24, 1);

        // Wait at least 15 ms
        gpioDelay(MIN_WAIT_US);

        // Read 6 bytes
        i2cReadReg8(pigpio, SHT35_ADDR, 0, 6, data);

        // Validate CRC-8
        crc = data[5];
        for (int i = 0; i < 6; i++) {
            if (i == 5) {
                crc ^= CRC_INIT;
            }
            crc ^= data[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc <<= 1;
                    crc ^= CRC_POLY;
                } else {
                    crc <<= 1;
                }
            }
        }

        if (crc != data[5]) {
            fprintf(stderr, "CRC validation failed.\n");
            continue;
        }

        // Convert raw values
        float temperature = -45 + 175 * (data[0] << 8 | data[1]) / 65535;
        float humidity = 100 * (data[2] << 8 | data[3]) / 65535;

        // Get current timestamp
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

        // Write to CSV
        fprintf(fp, "%s,%.2f,%.0f\n", timestamp, temperature, humidity);

        gpioDelay(SAMPLE_INTERVAL);
    }

    gpioTerminate(pigpio);
    if (fp != NULL) {
        fclose(fp);
    }

    return 0;
}

