#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define SI7021_ADDR 0x40
#define CRC_POLY 0x31
#define CRC_INIT 0x00
#define TIMEOUT_MS 100
#define BUS_SPEED 100000
#define CHECK_INTERVAL_MS 5000

int i2c_fd = -1;

void crc8(unsigned char *data, int len, unsigned char *crc) {
    unsigned char crc_temp;
    for (int i = 0; i < len; i++) {
        crc_temp = data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_temp & 0x01) {
                crc_temp ^= CRC_POLY;
            } else {
                crc_temp >>= 1;
            }
            if (j < 7)
                crc_temp <<= 1;
        }
        *crc = *crc ^ crc_temp;
    }
}

int i2c_read(int fd, unsigned char reg, unsigned char *buf, int len) {
    struct i2c_rdwr_ioctl_data rdwr;
    rdwr.u8 = reg;
    rdwr.u8len = 1;
    rdwr.u8buf = NULL;
    rdwr.u8buf_len = 0;

    struct i2c_msg messages[] = {
        { .addr = SI7021_ADDR, .flags = 0, .len = len - 1, .buf = buf },
        { .addr = 0, .flags = 0, .len = 0, .buf = NULL }
    };

    if (ioctl(fd, I2C_RDWR, &messages) < 0) {
        perror("I2C_RDWR");
        return -1;
    }

    return 0;
}

int main() {
    struct timespec next_check;
    clock_gettime(CLOCK_MONOTONIC, &next_check);

    i2c_fd = i2c_open(BUS_SPEED, 0x40);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &next_check);
        int elapsed_ms = (next_check.tv_sec - last_check.tv_sec) * 1000 + (next_check.tv_nsec - last_check.tv_nsec) / 1000000;

        if (elapsed_ms >= CHECK_INTERVAL_MS) {
            unsigned char hum_raw[3], temp_raw[3], crc;
            int ret = i2c_read(i2c_fd, 0xF5, hum_raw, 3);
            if (ret < 0) {
                fprintf(stderr, "I2C read error\n");
                continue;
            }

            if (hum_raw[2] != crc8(hum_raw, 2, &crc)) {
                fprintf(stderr, "CRC error\n");
                ret = i2c_read(i2c_fd, 0xF5, hum_raw, 3);
                if (ret < 0) {
                    continue;
                }
            }

            float humidity = 125.0 * (hum_raw[1] << 8 | hum_raw[0]) / 65536.0 - 6.0;
            float temperature = 175.72 * (hum_raw[2] << 8 | hum_raw[1]) / 65536.0 - 46.85;

            ret = i2c_read(i2c_fd, 0xE0, temp_raw, 3);
            if (ret < 0) {
                fprintf(stderr, "I2C read error\n");
                continue;
            }

            if (temp_raw[2] != crc8(temp_raw, 2, &crc)) {
                fprintf(stderr, "CRC error\n");
                ret = i2c_read(i2c_fd, 0xE0, temp_raw, 3);
                if (ret < 0) {
                    continue;
                }
            }

            float temp_assoc = 175.72 * (temp_raw[1] << 8 | temp_raw[0]) / 65536.0 - 46.85;

            FILE *fp = fopen("environment.log", "a");
            if (fp == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                continue;
            }
            fprintf(fp, "%ld,%f,%f\n", (long)timespec_to_timeval(next_check).tv_sec, temperature, humidity);
            fclose(fp);

            last_check = next_check;
        }

        struct timespec rem_time;
        rem_time.tv_sec = next_check.tv_sec + TIMEOUT_MS / 1000;
        rem_time.tv_nsec = next_check.tv_nsec + (TIMEOUT_MS % 1000 * 1000000);
        if (rem_time.tv_sec < next_check.tv_sec || rem_time.tv_nsec < next_check.tv_nsec) {
            nanosleep(&rem_time, NULL);
        } else {
            sleep(1);
        }
    }

    i2c_close(i2c_fd);
    return 0;
}

