        clock_gettime(CLOCK_MONOTONIC, &next_check);
        int elapsed_ms = (next_check.tv_sec - last_check.tv_sec) * 1000 + (next_check.tv_nsec - last_check.tv_nsec) / 1000000;

        if (elapsed_ms >= CHECK_INTERVAL_MS) {
            unsigned char hum_raw[3], temp_raw[3], crc;
            int ret = i2c_read(i2c_fd, 0xF5, hum_raw, 3);
            if (ret < 0) {
                fprintf(stderr, "I2C read error\n");
                continue;
            }

            if (hum_raw[2] != crc8(hum_raw, 2, &crc)) {
                fprintf(stderr, "CRC error\n");
                ret = i2c_read(i2c_fd, 0xF5, hum_raw, 3);
                if (ret < 0) {
                    continue;
                }
            }

            float humidity = 125.0 * (hum_raw[1] << 8 | hum_raw[0]) / 65536.0 - 6.0;
            float temperature = 175.72 * (hum_raw[2] << 8 | hum_raw[1]) / 65536.0 - 46.85;

            ret = i2c_read(i2c_fd, 0xE0, temp_raw, 3);
            if (ret < 0) {
                fprintf(stderr, "I2C read error\n");
                continue;
            }

            if (temp_raw[2] != crc8(temp_raw, 2, &crc)) {
                fprintf(stderr, "CRC error\n");
                ret = i2c_read(i2c_fd, 0xE0, temp_raw, 3);
                if (ret < 0) {
                    continue;
                }
            }

            float temp_assoc = 175.72 * (temp_raw[1] << 8 | temp_raw[0]) / 65536.0 - 46.85;

            FILE *fp = fopen("environment.log", "a");
            if (fp == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                continue;
            }
            fprintf(fp, "%ld,%f,%f\n", (long)timespec_to_timeval(next_check).tv_sec, temperature, humidity);
            fclose(fp);

            last_check = next_check;
        }

        struct timespec rem_time;
        rem_time.tv_sec = next_check.tv_sec + TIMEOUT_MS / 1000;
        rem_time.tv_nsec = next_check.tv_nsec + (TIMEOUT_MS % 1000 * 1000000);
        if (rem_time.tv_sec < next_check.tv_sec || rem_time.tv_nsec < next_check.tv_nsec) {
            nanosleep(&rem_time, NULL);
        } else {
            sleep(1);
        }
    }

    i2c_close(i2c_fd);
    return 0;
}
