        fprintf(stderr, "Failed to read CRC from sensor.\n");
        return;
    }

    if (i2cRead(0, 1, &SDP810_ADDR, 9, (uint8_t *)&raw_pressure_msb, 1) < 0) {
        fprintf(stderr, "Failed to read pressure MSB from sensor.\n");
        return;
    }
    if (i2cRead(0, 1, &SDP810_ADDR, 9, (uint8_t *)&raw_pressure_lsb, 1) < 0) {
        fprintf(stderr, "Failed to read pressure LSB from sensor.\n");
        return;
    }
    if (i2cRead(0, 1, &SDP810_ADDR, 9, (uint8_t *)&raw_temp_msb, 1) < 0) {
        fprintf(stderr, "Failed to read temperature MSB from sensor.\n");
        return;
    }
    if (i2cRead(0, 1, &SDP810_ADDR, 9, (uint8_t *)&raw_temp_lsb, 1) < 0) {
        fprintf(stderr, "Failed to read temperature LSB from sensor.\n");
        return;
    }

    if (crc8((uint8_t *)&raw_pressure_msb, 1, &crc) != 0 ||
        crc8((uint8_t *)&raw_pressure_lsb, 1, &crc) != 0 ||
        crc8((uint8_t *)&raw_temp_msb, 1, &crc) != 0 ||
        crc8((uint8_t *)&raw_temp_lsb, 1, &crc) != 0) {
        fprintf(stderr, "CRC validation failed.\n");
        return;
    }

    s.pressure = (float)(raw_pressure_msb << 8 | raw_pressure_lsb) / (scale_factor_bytes[0] << 16 | scale_factor_bytes[1] << 8 | scale_factor_bytes[2] + 1000);
    s.temperature = (float)(raw_temp_msb << 8 | raw_temp_lsb) / 200.0 - 45.0;

    if (pwrite(sample_file, &s, sizeof(struct sample), 0) != sizeof(struct sample)) {
        fprintf(stderr, "Failed to write sample to file.\n");
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup();

    while (1) {
        sample_and_log();
        usleep(SAMPLE_INTERVAL * 1000000);
    }

    cleanup();
    return 0;
}

