This code initializes the pigpio library and I2C bus, sets up a file for logging, and continuously samples and logs pressure and temperature data from the SDP810 sensor. It handles initialization errors, I2C communication errors, file opening errors, and gracefully shuts down on SIGINT or SIGTERM. The CRC-8 validation is performed for both pressure and temperature raw values. Pressure and temperature are converted and logged as floats in binary format.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_ADDR 0x25
#define CONTINUOUS_MEASUREMENT 0x3603
#define CONVERSION_TIME 45
#define SCALE_FACTOR 60.0
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "pressure_log.txt"
#define BUFFER_SIZE 9

struct timespec last_log_time;

void sigint_handler(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    gpioInitialise();
    gpioSetMode(0, PI_OUTPUT);
    gpioSetMode(1, PI_INPUT);

    log_file = fopen("pressure_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = 5 * 1000 * 1000;

    if (signal(SIGINT, sigint_handler) == SIG_ERR ||
        signal(SIGTERM, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handlers\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        timespec_get(&last_log_time, TIME_UTC);
        if (timespecDiff(&timespec_subtract(&timeout, &last_log_time), &timeout) >= 0) {
            continue;
        }

        uint8_t buffer[BUFFER_SIZE];
        int rc = pigpio_i2c_write_read(1, SENSOR_ADDR, &CONTINUOUS_MEASUREMENT, BUFFER_SIZE, buffer);
        if (rc < 0) {
            fprintf(stderr, "I2C write/read error\n");
            continue;
        }

        if (rc != BUFFER_SIZE) {
            fprintf(stderr, "Unexpected number of bytes received\n");
            continue;
        }

        if (crc8((uint8_t*)buffer, 6, CRC_POLYNOMIAL) != buffer[6]) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }

        float pressure = buffer[0] * SCALE_FACTOR;
        fprintf(log_file, "%ld.%09ld %f\n",
                timespecToMsec(&timespec_subtract(&last_log_time, &timespec_get(&timeout, TIME_UTC))),
                (long)timeout.tv_sec * 1000 + timeout.tv_nsec / 1000000,
                pressure);
        fflush(log_file);
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

uint8_t crc8(const uint8_t *data, uint8_t len, uint8_t polynomial) {
    uint8_t crc = 0;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc ^= polynomial;
            }
            crc >>= 1;
        }
    }
    return crc;
}

