#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigio.h>

#define SENSOR_ADDR 0x28
#define SENSOR_REG_DATA 0x00
#define SENSOR_READ_BITS 16
#define SENSOR_STATUS_BITS 2
#define SENSOR_RAW_BITS (SENSOR_READ_BITS - SENSOR_STATUS_BITS)
#define SENSOR_COUNTS_PER_SLPM (14745 - 1638)
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds

int i2c_fd;
gpioInit p;

void sigint_handler(int signum) {
    pigpio_stop();
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

void setup_i2c() {
    i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus 1\n");
        exit(1);
    }

    if (i2c_rdwr_setup(i2c_fd, 0x0000, 0, 0) < 0) {
        i2c_close(i2c_fd);
        i2c_fd = -1;
        fprintf(stderr, "Error setting up I2C transfer\n");
        exit(1);
    }
}

uint16_t read_sensor(void) {
    uint8_t data[2];
    if (i2c_rdwr(i2c_fd, &data[0], 1, &data[1], 1) < 0) {
        fprintf(stderr, "Error reading from sensor\n");
        exit(1);
    }

    return (data[0] << 8) | data[1];
}

double compute_flow_rate(uint16_t raw_reading) {
    return (double)(raw_reading - 1638) * (10 / SENSOR_COUNTS_PER_SLPM);
}

void setup_pwm(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        exit(1);
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        exit(1);
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        exit(1);
    }

    if (gpioPWMset(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Error setting initial PWM duty cycle\n");
        exit(1);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_i2c();
    setup_pwm();

    FILE *log_file = fopen("flow_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        exit(1);
    }

    char timestamp[20];
    while (1) {
        time(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&rawtime));

        uint16_t raw_reading = read_sensor();
        uint16_t masked_reading = raw_reading >> SENSOR_STATUS_BITS;
        double flow_rate = compute_flow_rate(masked_reading);

        int duty_cycle = (int)(flow_rate / 10 * 100);
        gpioPWMset(FAN_GPIO, duty_cycle);

        fprintf(log_file, "%s, %.2f\n", timestamp, flow_rate);

        usleep(SAMPLE_INTERVAL);
    }

    pigpio_stop();
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

