#define BUFFER_SIZE 10
#define LED_GPIO 17
#define TEMP_SENSOR_ADDR 0x48
#define TEMP_REG_ADDR 0x00

int buffer[BUFFER_SIZE];
int index = 0;
float sum = 0;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signum) {
    gpioTerminate();
    exit(0);
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(1);
    }
}

void cleanup_pigpio() {
    gpioTerminate();
}

void read_temp_sensor() {
    int16_t low_byte, high_byte;
    int temp_value;

    if (pigpio_i2c_open(1, TEMP_SENSOR_ADDR) < 0) {
        fprintf(stderr, "I2C bus open failed\n");
        return;
    }

    if (pigpio_i2c_read_word_data(1, TEMP_SENSOR_ADDR, &low_byte, &high_byte) < 0) {
        fprintf(stderr, "I2C read failed\n");
        pigpio_i2c_close(1);
        return;
    }

    if (pigpio_i2c_close(1) < 0) {
        fprintf(stderr, "I2C close failed\n");
        return;
    }

    // Swap bytes and calculate temperature
    temp_value = (high_byte << 8) | low_byte;
    temp_value >>= 7;
    temp_value /= 2;

    buffer[index] = (int)temp_value;
    index = (index + 1) % BUFFER_SIZE;
    sum += temp_value;

    if (index == 0) {
        printf("Average temperature: %.2f °C\n", sum / BUFFER_SIZE);
    }
}

