    init_pigpio();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        read_temp_sensor();
        usleep(1000000); // Sleep for 1 second
    }

    cleanup_pigpio();
    return 0;
