#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <signal.h>

#define SCD30_ADDR 0x61
#define MEAS_INTERVAL 2000000 // 2 seconds
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

#define LOG_FILE "air_quality.log"

struct sensor_data {
    float co2_ppm;
    float temp_c;
    float rh_percent;
};

void sigint_handler(int signum) {
    printf("\nReceived SIGINT, shutting down...\n");
    pigio_stop();
    i2c_close();
    fclose(log_file);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("\nReceived SIGTERM, shutting down...\n");
    pigio_stop();
    i2c_close();
    fclose(log_file);
    exit(0);
}

void crc8(uint8_t *data, int len, uint8_t *crc) {
    uint8_t crc_temp;
    *crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc_temp = (*data++ ^ *crc);
        for (int j = 0; j < 8; j++) {
            if (crc_temp & 0x01) {
                *crc ^= CRC_POLY;
            }
            crc_temp >>= 1;
            if (j < 8) {
                *crc <<= 1;
            }
        }
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return 1;
    }

    if (pigio_init() < 0) {
        fprintf(stderr, "pigio_init() failed\n");
        return 1;
    }

    int i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "i2c_open() failed\n");
        pigio_terminate();
        return 1;
    }

    if (i2c_write(i2c_fd, 0x02, 0x02, 1) != 1) {
        fprintf(stderr, "Failed to write data-ready command\n");
        i2c_close(i2c_fd);
        pigio_terminate();
        return 1;
    }

    struct sensor_data data;
    while (1) {
        uint8_t buffer[10];
        if (i2c_read(i2c_fd, 0x03, buffer, 10) != 10) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        uint8_t crc_read;
        memcpy(&crc_read, buffer + 8, 1);
        uint8_t crc_calc;
        crc8(buffer, 8, &crc_calc);

        if (crc_read != crc_calc) {
            fprintf(stderr, "CRC mismatch, ignoring data\n");
            continue;
        }

        data.co2_ppm = *(float *)(buffer + 0);
        data.temp_c = *(float *)(buffer + 4);
        data.rh_percent = *(float *)(buffer + 8);

        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%.2f,%.1f,%.1f\n", timestamp, data.co2_ppm, data.temp_c, data.rh_percent);
        fflush(log_file);

        if (data.co2_ppm < 800) {
            printf("Ventilation: OFF\n");
        } else if (data.co2_ppm < 1200) {
            printf("Ventilation: LOW\n");
        } else {
            printf("Ventilation: HIGH\n");
        }

        sleep(MEAS_INTERVAL);
    }

    pigio_terminate();
    i2c_close(i2c_fd);
    fclose(log_file);
    return 0;
}

