#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define SDP32_ADDR 0x21
#define SAMPLING_INTERVAL_MS 1000

struct sdp32_data {
    uint16_t raw_pressure;
    uint16_t raw_temperature;
    uint16_t scale_factor;
    float pressure_pa;
};

static int sampling_interval = SAMPLING_INTERVAL_MS;
static struct sdp32_data sensor_data;
static gpio pigpio = -1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Exiting on signal %d\n", signum);
        cleanup();
        exit(0);
    }
}

void cleanup() {
    if (pigpio != -1) {
        gpioTerminate(pigpio);
        pigpio = -1;
    }
}

void init_pigpio() {
    pigpio = gpioInitialise(0);
    if (pigpio == -1) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }
}

uint8_t sdp32_read_byte(int fd) {
    uint8_t data;
    int ret = ioctl(fd, I2C_SLAVE, SDP32_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to communicate with SDP32 sensor\n");
        exit(1);
    }

    ret = read(fd, &data, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to read from SDP32 sensor\n");
        exit(1);
    }

    return data;
}

void sdp32_write_bytes(int fd, const uint8_t *bytes, size_t len) {
    int ret;
    for (size_t i = 0; i < len; i++) {
        ret = write(fd, &bytes[i], 1);
        if (ret != 1) {
            fprintf(stderr, "Failed to write to SDP32 sensor\n");
            exit(1);
        }
    }
}

uint8_t sdp32_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc <<= 1;
            if (crc & 0x80) {
                crc ^= 0x07;
            } else {
                crc++;
            }
        }
    }
    return crc;
}

float sdp32_convert_pressure(uint16_t raw_pressure, uint16_t scale_factor) {
    return (float)raw_pressure / scale_factor;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init_pigpio();

    int fd = ioctl(gpioGetFD(pigpio), I2C_SLAVE, SDP32_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to get file descriptor for I2C bus\n");
        cleanup();
        exit(1);
    }

    sdp32_write_bytes(fd, (uint8_t[]){0x36, 0x2F}, 2);

    while (1) {
        sensor_data.raw_pressure = 0;
        sensor_data.raw_temperature = 0;
        sensor_data.scale_factor = 0;

        sensor_data.raw_pressure = sdp32_read_byte(fd);
        sensor_data.raw_pressure <<= 8;
        sensor_data.raw_pressure |= sdp32_read_byte(fd);

        sensor_data.raw_temperature = sdp32_read_byte(fd);
        sensor_data.raw_temperature <<= 8;
        sensor_data.raw_temperature |= sdp32_read_byte(fd);

        sensor_data.scale_factor = sdp32_read_byte(fd);
        sensor_data.scale_factor <<= 8;
        sensor_data.scale_factor |= sdp32_read_byte(fd);

        if (sdp32_crc8(&sensor_data.raw_pressure, 2) != sensor_data.raw_pressure[1]) {
            fprintf(stderr, "CRC mismatch for pressure data\n");
