#define SDP810_I2C_ADDR 0x25
#define SDP810_CMD_CONTINUOUS 0x3615
#define SDP810_CRC_POLY 0x31
#define SDP810_CRC_INIT 0xFF

struct sdp810_data {
    uint16_t pressure;
    uint16_t temperature;
    uint8_t scale_factor_pressure;
    uint8_t scale_factor_temperature;
};

static int i2c_fd = -1;
static struct sdp810_data data;

static int read_crc8(uint8_t *data, int len) {
    uint8_t crc = SDP810_CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void sdp810_read(int fd) {
    gpioInitialise();
    if (gpioI2COpen(fd, &i2c_fd) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        exit(EXIT_FAILURE);
    }

    if (gpioI2CWrite(i2c_fd, SDP810_CMD_CONTINUOUS, 1) < 0) {
        fprintf(stderr, "Error writing to I2C bus\n");
        exit(EXIT_FAILURE);
    }

    if (gpioI2CRead(i2c_fd, (void *)&data, 9) < 0) {
        fprintf(stderr, "Error reading from I2C bus\n");
        exit(EXIT_FAILURE);
    }

    uint8_t crc = read_crc8((uint8_t *)&data, 9);
    if (crc != data.crc) {
        fprintf(stderr, "CRC mismatch\n");
        exit(EXIT_FAILURE);
    }

    data.pressure = (data.pressure << 4) | (data.pressure >> 4);
    data.temperature = (data.temperature << 4) | (data.temperature >> 4);

    data.pressure /= data.scale_factor_pressure;
    data.temperature /= 200.0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, [](int) { gpioTerminate(); exit(0); });
    signal(SIGTERM, [](int) { gpioTerminate(); exit(0); });

    gpioSetMode(0, PI_OUTPUT);
    gpioSetMode(2, PI_INPUT);
    gpioSetMode(3, PI_INPUT);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initialising pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (i2c_fd < 0) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Error opening I2C bus\n");
            gpioTerminate();
            exit(EXIT_FAILURE);
        }
    }

    while (1) {
        sdp810_read(i2c_fd);
        printf("Pressure: %.2f, Temperature: %.2f\n", data.pressure, data.temperature);
        usleep(45000);
    }

    gpioTerminate();
    close(i2c_fd);
    return 0;
}

