#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>

#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define DELAY_MS 20

int i2c_fd = -1;

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c-1");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

void configure_sensor() {
    struct i2c_rdwr_ioctl_data rdwr;
    struct i2c_msg messages[] = {
        {
            .addr = HDC1000_ADDR,
            .flags = 0,
            .len = 1,
            .buf = &CONFIG_REG,
        },
        {
            .addr = HDC1000_ADDR,
            .flags = I2C_M_RD,
            .len = 0,
            .buf = NULL,
        },
    };

    rdwr.msgs = messages;
    rdwr.nmsgs = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to configure sensor");
    }
}

void read_sensor_data() {
    struct i2c_rdwr_ioctl_data rdwr;
    struct i2c_msg messages[] = {
        {
            .addr = HDC1000_ADDR,
            .flags = 0,
            .len = 1,
            .buf = &TEMP_REG,
        },
        {
            .addr = HDC1000_ADDR,
            .flags = I2C_M_RD,
            .len = 4,
            .buf = NULL,
        },
    };

    rdwr.msgs = messages;
    rdwr.nmsgs = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to read sensor data");
        return;
    }

    uint16_t raw_temp = *(uint16_t *)rdwr.msgs[1].buf;
    uint16_t raw_humidity = *(uint16_t *)(rdwr.msgs[1].buf + 2);

    float temp = (raw_temp / 65536.0) * 165.0 - 40.0;
    float humidity = (raw_humidity / 65536.0) * 100.0;

    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humidity);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (init_i2c() < 0) {
        return 1;
    }

    configure_sensor();

    while (1) {
        read_sensor_data();
        usleep(5000000); // 5 seconds
    }

    close(i2c_fd);
    return 0;
}

