#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI7051_ADDR 0x40
#define SI7051_REG_TEMP_MSB 0xF6
#define SI7051_REG_TEMP_LSB 0xF7

static volatile int running = 1;
static pigio *io;

static void sigint_handler(int signum) {
    running = 0;
}

static int read_temp(int16_t *temp) {
    uint8_t data[2];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return -1;
    }

    io = pigio;
    if (io == NULL) {
        fprintf(stderr, "Failed to get pigpio instance.\n");
        return -1;
    }

    if (gpioSetMode(2, PI_OUTPUT) < 0 || gpioSetMode(3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C bus SDA/SCL pins as output.\n");
        goto cleanup;
    }

    gpioWrite(2, 0);
    gpioWrite(3, 0);

    // Start I2C transfer
    if (piGetFlags(PI_I2C_START) < 0 ||
        piWrite(3, 0x40) < 0 ||
        piGetFlags(PI_I2C_STOP) < 0) {
        fprintf(stderr, "I2C communication error.\n");
        goto cleanup;
    }

    // Wait for I2C bus to be free
    if (piGetFlags(PI_I2C_BUSY) > 0) {
        fprintf(stderr, "I2C bus is busy.\n");
        goto cleanup;
    }

    // Read temperature data
    if (piI2CGet(3, &data, 2, 0) < 0) {
        fprintf(stderr, "Failed to read temperature data from Si7051.\n");
        goto cleanup;
    }

    *temp = (int16_t)((data[0] << 8) | data[1]);

    cleanup:
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio library.\n");
    }

    return 0;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    io = NULL;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    io = pigio;
    if (io == NULL) {
        fprintf(stderr, "Failed to get pigpio instance.\n");
        return 1;
    }

    int16_t temp;
    while (running) {
        if (read_temp(&temp) < 0) {
            continue;
        }

        printf("Temperature: %.2f °C\n", temp * 0.01);
        usleep(5000000); // Sleep for 5 seconds
    }

    cleanup:
    if (io) {
        gpioTerminate();
    }

    return 0;
}

