    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "pigpioInitialise failed\n");
        return 1;
    }
    pigpio = (gpio)pigpioInitialise();

    i2c_fd = i2c_open(I2C_BUS, 0);
    if (i2c_fd < 0) {
