        fprintf(stderr, "i2c_write failed\n");
        i2c_close(i2c_fd);
        gpioTerminate(pigpio);
        return 1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        char timestamp[64];
