        int data_l, data_h;
        if (i2c_read(i2c_fd, MLX90833_ADDR, &data_l, 1) < 0) {
            fprintf(stderr, "i2c_read (low byte) failed\n");
            break;
        }
        if (i2c_read(i2c_fd, MLX90833_ADDR | 0x01, &data_h, 1) < 0) {
            fprintf(stderr, "i2c_read (high byte) failed\n");
            break;
        }

        uint16_t pressure = (data_h << 8) | data_l;
        printf("%s: %d\n", timestamp, pressure);

        gpioDelay(500000);
    }

    i2c_close(i2c_fd);
    gpioTerminate(pigpio);
    return 0;
}

