#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_ADDR 0x63
#define CALIB_CMD 0x50
#define MEAS_CMD 0x40
#define DELAY_MS 7

struct sensor_data {
    float scale_factor_lut;
    float scale_factor_h;
    float scale_factor_p;
    float temp_comp;
    float press_comp;
};

static struct sensor_data sensor_data;
static gpioI2C *i2c;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

void sigterm_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

void read_calibration_coeffs() {
    uint8_t calib_coeffs[8];
    int ret = pigpio_i2c_read_reg_byte(i2c, I2C_ADDR, CALIB_CMD, &calib_coeffs, 8);
    if (ret < 0 || memmem(calib_coeffs, 8, (uint8_t[]){0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF}) != NULL) {
        fprintf(stderr, "Error reading calibration coefficients\n");
        gpioTerminate();
        exit(1);
    }

    sensor_data.scale_factor_lut = (float)((calib_coeffs[0] << 8) | calib_coeffs[1]) / 1000.0;
    sensor_data.scale_factor_h = (float)((calib_coeffs[2] << 8) | calib_coeffs[3]) / 100.0;
    sensor_data.scale_factor_p = (float)((calib_coeffs[4] << 8) | calib_coeffs[5]) / 10.0;
    sensor_data.temp_comp = (float)((calib_coeffs[6] << 8) | calib_coeffs[7]) / 100.0;
    sensor_data.press_comp = 0.000584; // From datasheet
}

void read_high_precision_measurement() {
    uint8_t raw_data[6];
    int ret = pigpio_i2c_read_reg_bytes(i2c, I2C_ADDR, MEAS_CMD, raw_data, 6);
    if (ret < 0 || (memmem(raw_data, 6, (uint8_t[]){0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF}) != NULL)) {
        fprintf(stderr, "Error reading high-precision measurement\n");
        gpioTerminate();
        exit(1);
    }

    int16_t temp_raw = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    int32_t press_raw = ((int32_t)raw_data[2] << 16) | ((int32_t)raw_data[3] << 8) | (int32_t)raw_data[4];

    float temp = (temp_raw * sensor_data.temp_comp) / 100.0;
    float press = (press_raw * sensor_data.scale_factor_p) / (float)(1 << 16);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
           datetime(),
           temp,
           press);
}

int main() {
    const char *dev = "0";
    gpioInitialise(dev);
    gpioSetMode(0, PI_OUTPUT);
    i2c = gpioI2COpen(0, 1);
    if (!i2c) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    read_calibration_coeffs();

    while (1) {
        read_high_precision_measurement();
        sleep(5);
    }

    gpioTerminate();
    return 0;
}

