#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define MLX90819_ADDR 0x60
#define PRESSURE_MSB 0xAA
#define PRESSURE_LSB 0xAB
#define SCALING_FACTOR 0.1

static int i2c_fd = -1;

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct i2c_rdwr_ioctl_data rdwr_data;
    struct i2c_msg messages[2];
    int ret;

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    ioctl(i2c_fd, I2C_SLAVE, MLX90819_ADDR);

    messages[0].len = 1;
    messages[0].addr = PRESSURE_MSB;
    messages[0].flags = 0;
    messages[0].data = NULL;

    messages[1].len = 1;
    messages[1].addr = PRESSURE_LSB;
    messages[1].flags = 0;
    messages[1].data = NULL;

    rdwr_data.msgs = messages;
    rdwr_data.nmsgs = 2;

    while (1) {
        rdwr(i2c_fd, &rdwr_data);

        if (rdwr_data.len != 2 || rdwr_data.flags != 0) {
            fprintf(stderr, "Error reading from sensor\n");
            continue;
        }

        uint16_t raw_pressure = ((uint16_t)rdwr_data.data[0] << 8) | rdwr_data.data[1];
        float pressure_kPa = raw_pressure * SCALING_FACTOR;

        time_t now = time(NULL);
        printf("Timestamp: %ld, Pressure: %.2f kPa\n", now, pressure_kPa);

        sleep(1);
    }

    close(i2c_fd);
    return 0;
}

