#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SDA_GPIO 2
#define SCL_GPIO 3
#define I2C_BUS 1
#define SENSOR_ADDR 0x25
#define COMMAND_CONTINUOUS_MEASUREMENT 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

static int i2c_fd = -1;
static GPIODevice *sda_gpio;
static GPIODevice *scl_gpio;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    sda_gpio = gpiod_in_setup(&res_, SDA_GPIO);
    if (!sda_gpio) {
        perror("Failed to initialize SDA GPIO");
        close(i2c_fd);
        return;
    }

    scl_gpio = gpiod_out_setup(&res_, SCL_GPIO, 0);
    if (!scl_gpio) {
        perror("Failed to initialize SCL GPIO");
        gpiod_rmdev(sda_gpio);
        close(i2c_fd);
        return;
    }
}

void cleanup_i2c() {
    gpiod_rmdev(scl_gpio);
    gpiod_rmdev(sda_gpio);
    close(i2c_fd);
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct gpiod_chip chip;
    res_ = gpiod_new();
    if (!res_) {
        perror("Failed to initialize gpiod");
        return EXIT_FAILURE;
    }

    init_i2c();

    while (1) {
        // Write command
        write(i2c_fd, &COMMAND_CONTINUOUS_MEASUREMENT, 2);
        usleep(45 * 1000);

        // Read 9 bytes
        uint8_t data[9];
        read(i2c_fd, data, 9);

        // Validate CRC
        if (crc8(data, 9) != data[8]) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        // Convert raw values
        float pressure = data[0] / 60.0;
        float temperature = data[1] / 200.0;

        // Log data
        FILE *log_file = fopen("pressure_log.txt", "a");
        if (!log_file) {
            perror("Failed to open log file");
            continue;
        }
        fprintf(log_file, "%lu,%.2f,%.2f\n", time(NULL), pressure, temperature);
        fclose(log_file);
    }

    cleanup_i2c();
    gpiod_free(res_);
    return EXIT_SUCCESS;
}

