#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define REG_PRESSURE 0x00
#define SAFE_RANGE_MIN 200.0
#define SAFE_RANGE_MAX 250.0
#define SCALE_FACTOR 0.01

int main() {
    int fd;
    gpioInitialise();
    if (gpioFail()) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    fd = i2cOpen(I2C_BUS, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("pressure_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    if (fseek(log_file, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Failed to seek to start of log file\n");
        fclose(log_file);
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    char header[] = "timestamp,pressure_kPa\n";
    if (fwrite(header, sizeof(char), strlen(header), log_file) != strlen(header)) {
        fprintf(stderr, "Failed to write header to log file\n");
        fclose(log_file);
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    rewind(log_file);

    while (1) {
        uint16_t pressure_raw;
        int ret = i2cReadI2CBlockData(fd, I2C_ADDR, REG_PRESSURE, &pressure_raw, 2);
        if (ret < 0) {
            if (gpioFail()) {
                fprintf(stderr, "Failed to read from I2C device\n");
                break;
            }
            i2cClose(fd);
            fd = i2cOpen(I2C_BUS, 0);
            if (fd < 0) {
                fprintf(stderr, "Failed to reopen I2C bus %d\n", I2C_BUS);
                gpioTerminate();
                return 1;
            }
            ret = i2cReadI2CBlockData(fd, I2C_ADDR, REG_PRESSURE, &pressure_raw, 2);
        }
        if (ret < 0)
            continue;

        double pressure_kPa = pressure_raw * SCALE_FACTOR;
        if (pressure_kPa < SAFE_RANGE_MIN || pressure_kPa > SAFE_RANGE_MAX)
            fprintf(stderr, "Warning: Pressure %f kPa is out of safe range\n", pressure_kPa);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%f\n", timestamp, pressure_kPa);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2cClose(fd);
    gpioTerminate();

    return 0;
}

