#include <fcntl.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define SAMPLE_INTERVAL 5
#define LOG_FILE "environment_data.log"
#define LOG_SIZE 1048576 // 1 MB

struct sensor_data {
    double temperature;
    double humidity;
};

int main() {
    int fd;
    gpioInitialise();
    pigpio gpio = pigpio_init();
    if (!gpio) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    while (1) {
        struct sensor_data data;
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        // Trigger measurement
        gpioWrite(I2C_BUS, GPIO_OUTPUT);
        gpioSetMode(I2C_BUS, GPIO_OUTPUT);
        gpioWrite(I2C_BUS, 0x00);
        usleep(40000); // Wait 40 ms
        gpioWrite(I2C_BUS, GPIO_INPUT);
        gpioSetMode(I2C_BUS, GPIO_INPUT);

        // Read 4 bytes
        int r = pigpio_i2c_read(gpio, I2C_ADDR, 4, (uint8_t *)&data, NULL);
        if (r < 0) {
            fprintf(stderr, "I2C read error: %d\n", r);
            break;
        }

        // Validate sensor status bits
        if ((data.status & 0x03) != 0x00) {
            fprintf(stderr, "Sensor error: %02x\n", data.status);
            continue;
        }

        // Convert raw values
        data.temperature = data.raw_T * 165.0 / 16383.0 - 40.0;
        data.humidity = data.raw_H * 100.0 / 16383.0;

        // Log data
        FILE *log_file = fdopen(fd, "a");
        if (fseek(log_file, 0, SEEK_END) == -1 || ftruncate(fileno(log_file), LOG_SIZE) == -1) {
            perror("fseek/ftruncate");
            break;
        }
        fprintf(log_file, "%s: Temp=%.2f, Humidity=%.2f\n", timestamp, data.temperature, data.humidity);
        fclose(log_file);

        // Sleep
        usleep(SAMPLE_INTERVAL * 1000000);
    }

    pigpio_terminate(gpio);
    gpioCleanAll();
    close(fd);

    return 0;
}

