#define SENT_PIN 4
#define TICK_TIME 3  // us
#define SYNC_PULSE 56
#define NIBBLE_MIN 12
#define NIBBLE_MAX 271
#define CHECKSUM_MOD 16
#define RAW_BITS 12
#define SCALE 0.0125
#define OFFSET -16384

typedef struct {
    uint16_t sync_pulse;
    uint16_t status;
    uint16_t data[3];
    uint16_t checksum;
} sent_data_t;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    struct timespec ts;
    sent_data_t sent_data;
    float pressure;
    FILE *log_file = fopen("pressure_log.txt", "a");

    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return 1;
    }

    gpioSetMode(SENT_PIN, PI_OUTPUT);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t start_time = ts.tv_sec * 1000000 + ts.tv_nsec;

        gpioSetOutput(SENT_PIN, 0);
        gpioPulse(SENT_PIN, 0, 0);
        gpioSetOutput(SENT_PIN, 1);

        uint64_t end_time;
        do {
            end_time = ts.tv_sec * 1000000 + ts.tv_nsec;
        } while ((end_time - start_time) * 1000 < SYNC_PULSE * TICK_TIME);

        // Read SENT data
        gpioSetOutput(SENT_PIN, 0);
        sent_data.sync_pulse = gpioRead(SENT_PIN);

        // Read status, data, and checksum nibbles
        // ... (Implement nibble reading logic here)

        // Validate checksum
        uint16_t calculated_checksum = (sent_data.status + sent_data.data[0] + sent_data.data[1] + sent_data.data[2]) % 16;
        if (calculated_checksum != sent_data.checksum) {
            fprintf(stderr, "Checksum error\n");
            continue;
        }

        // Validate pulse widths
        if (sent_data.sync_pulse < NIBBLE_MIN || sent_data.sync_pulse > NIBBLE_MAX) {
            fprintf(stderr, "Invalid sync pulse width\n");
            continue;
        }
        // Validate other pulse widths similarly

        // Convert raw value to pressure
        pressure = (sent_data.data[0] * 256 + sent_data.data[1] * 16 + sent_data.data[2]) * SCALE + OFFSET;

        // Log pressure reading
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa\n",
                ts.tv_year + 1900, ts.tv_mon + 1, ts.tv_mday,
                ts.tv_hour, ts.tv_min, ts.tv_sec, pressure);
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

