struct sht40_data {
    uint8_t raw_temp;
    uint8_t raw_humidity;
};

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

float convert_temp(uint8_t raw_temp) {
    return -45 + 175 * (raw_temp / 65535.0);
}

float convert_humidity(uint8_t raw_humidity) {
    return -6 + 125 * (raw_humidity / 65535.0);
}

int main() {
    int i2c_fd;
    struct sht40_data data;
    FILE *log_file;
    char timestamp[20];

    if (init_pigpio() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioI2COpen(I2C_BUS, &i2c_fd) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        pigpio_terminate(NULL);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        pigpio_terminate(NULL);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        gpioI2CWriteReg8(i2c_fd, SHT40_ADDR, 0x2C, HIGH_PREC_CMD);
        sleep(READ_INTERVAL_SEC);

        uint8_t buffer[6];
        if (gpioI2CReadReg8(i2c_fd, SHT40_ADDR, 0xFA, buffer, 6) != 6) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        data.raw_temp = buffer[1];
        data.raw_humidity = buffer[3];

        uint8_t crc_received_temp = buffer[2];
        uint8_t crc_received_humidity = buffer[5];

        if (crc8((uint8_t *)&data.raw_temp, 2) != crc_received_temp ||
            crc8((uint8_t *)&data.raw_humidity, 2) != crc_received_humidity) {
            fprintf(stderr, "CRC validation failed\n");
            break;
        }

        float temp = convert_temp(data.raw_temp);
        float humidity = convert_humidity(data.raw_humidity);

        fprintf(log_file, "%s: Temperature = %.2f °C, Humidity = %.2f %%\n", timestamp, temp, humidity);
        fflush(log_file);
    }

    fclose(log_file);
    gpioI2CClose(i2c_fd);
    pigpio_terminate(NULL);

    return 0;
}

