#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

#define BUFFER_SIZE 100
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define LSB_RESOLUTION 0.0078125

typedef struct {
    uint16_t buffer[BUFFER_SIZE];
    int head, tail;
} CircularBuffer;

void init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup_pigpio(void) {
    gpioTerminate();
}

void init_buffer(CircularBuffer *buf) {
    buf->head = buf->tail = 0;
}

bool is_full(CircularBuffer *buf) {
    return ((buf->head + 1) % BUFFER_SIZE) == buf->tail;
}

bool is_empty(CircularBuffer *buf) {
    return buf->head == buf->tail;
}

void add_sample(CircularBuffer *buf, uint32_t sample) {
    buf->buffer[buf->head] = sample;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
}

uint32_t get_sample(CircularBuffer *buf) {
    if (is_empty(buf))
        return 0;

    uint32_t ret = buf->buffer[buf->tail];
    buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    return ret;
}

void save_buffer_to_file(CircularBuffer *buf, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file %s for writing\n", filename);
        return;
    }

    for (int i = 0; i < buf->head; ++i) {
        uint32_t sample = get_sample(buf);
        fwrite(&sample, sizeof(uint32_t), 1, fp);
    }
    fclose(fp);
}

void sigint_handler(int signum) {
    save_buffer_to_file(&buffer, "temperature_log.dat");
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main(void) {
    CircularBuffer buffer;
    init_buffer(&buffer);

    init_pigpio();

    const int i2c_fd = gpioI2COpen(1, I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    gpioSetMode(i2c_fd, PI_OUTPUT);

    while (1) {
        uint8_t msb, lsb;
        if (gpioI2CReadRegBytes(i2c_fd, TEMP_REG, &msb, 1) != 1) {
            fprintf(stderr, "Failed to read temperature register\n");
            continue;
        }

        if (gpioI2CReadRegBytes(i2c_fd, TEMP_REG + 1, &lsb, 1) != 1) {
            fprintf(stderr, "Failed to read temperature register (LSB)\n");
            continue;
        }

        uint32_t temperature = (msb << 8) | lsb;
        temperature = temperature * LSB_RESOLUTION;

        add_sample(&buffer, temperature);

        usleep(5000000); // 5 seconds
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    save_buffer_to_file(&buffer, "temperature_log.dat");
    cleanup_pigpio();

    return EXIT_SUCCESS;
}

