#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHTC3_ADDR 0x70
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define HUMIDITY_MIN 0.0
#define HUMIDITY_MAX 100.0

struct shtc3_data {
    uint8_t temp_msb;
    uint8_t temp_lsb;
    uint8_t temp_crc;
    uint8_t humidity_msb;
    uint8_t humidity_lsb;
    uint8_t humidity_crc;
};

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

float temp_convert(struct shtc3_data *data) {
    return 175 * ((float)(data->temp_msb << 8 | data->temp_lsb)) / 65535 - 45;
}

float humidity_convert(struct shtc3_data *data) {
    return 100 * ((float)(data->humidity_msb << 8 | data->humidity_lsb)) / 65535;
}

int main() {
    struct shtc3_data data;
    gpioInitialise();
    if (piGiocontrol(GPIO_OUTPUT, 2, 0) || piGiocontrol(GPIO_OUTPUT, 3, 0)) {
        fprintf(stderr, "Error setting GPIO direction\n");
        return 1;
    }

    i2c_handle = piGiocontrol(GPIO_INPUT, 2, 0);
    if (!i2c_handle) {
        fprintf(stderr, "Error getting I2C handle\n");
        return 1;
    }

    if (i2c_open(SHTC3_ADDR, 1) || i2c_write_reg8(i2c_handle, 0x06, 0x7866)) {
        fprintf(stderr, "Error opening or writing to I2C device\n");
        return 1;
    }

    while (1) {
        piGiowait(i2c_handle, 12400); // Wait for conversion

        if (i2c_read_regs_8(i2c_handle, &data, 6)) {
            if (data.temp_crc == crc8(&data, 3) && data.humidity_crc == crc8(&data, 3)) {
                float temp = temp_convert(&data);
                float humidity = humidity_convert(&data);

                if (temp >= TEMP_MIN && temp <= TEMP_MAX && humidity >= HUMIDITY_MIN && humidity <= HUMIDITY_MAX) {
                    time_t now = time(NULL);
                    struct tm *time_info = localtime(&now);

                    FILE *log_file = fopen("shtc3_environment.log", "a");
                    if (!log_file) {
                        fprintf(stderr, "Error opening log file\n");
                        continue;
                    }

                    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
                            1900 + time_info->tm_year,
                            1 + time_info->tm_mon,
                            time_info->tm_mday,
                            time_info->tm_hour,
                            time_info->tm_min,
                            time_info->tm_sec,
                            temp,
                            humidity);

                    fclose(log_file);

                    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temp, humidity);
                }
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Error reading from I2C device\n");
        }
    }

    piGioclose(i2c_handle, 1);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    if (i2c_handle) {
        piGioclose(i2c_handle, 1);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    return 0;
}

