                        continue;
                    }

                    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
                            1900 + time_info->tm_year,
                            1 + time_info->tm_mon,
                            time_info->tm_mday,
                            time_info->tm_hour,
                            time_info->tm_min,
                            time_info->tm_sec,
                            temp,
                            humidity);

                    fclose(log_file);

                    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temp, humidity);
                }
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Error reading from I2C device\n");
        }
    }

    piGioclose(i2c_handle, 1);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    if (i2c_handle) {
        piGioclose(i2c_handle, 1);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    return 0;
}
