#define I2C_ADDR 0x48
#define TMP117_REG 0x00
#define RESOLUTION 0.0078125

static const char *filename = "temperature_log.txt";
static int retry_count = 3;
static int i2c_handle = -1;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    struct timespec ts;
    gpioInitialise();
    gpioSetMode(0, PI_OUTPUT); // Ensure GPIO is in output mode for pigpio

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting SIGINT handler\n");
        return 1;
    }

    i2c_handle = gpioInitialiseRPi();
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        int ret = pigpio_i2c_write(i2c_handle, I2C_ADDR, (uint8_t *) &TMP117_REG, 1, 1000);
        if (ret < 0) {
            if (--retry_count == 0) {
                fprintf(stderr, "I2C bus error, exiting\n");
                gpioTerminate();
                return 1;
            }
            continue;
        }

        uint16_t temp_raw;
        ret = pigpio_i2c_read(i2c_handle, I2C_ADDR, (uint8_t *) &temp_raw, 2, 1000);
        if (ret < 0) {
            if (--retry_count == 0) {
                fprintf(stderr, "I2C bus error, exiting\n");
                gpioTerminate();
                return 1;
            }
            continue;
        }

        double temp_c = temp_raw * RESOLUTION;
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        FILE *log_file = fopen(filename, "a");
        if (!log_file) {
            fprintf(stderr, "Error opening log file\n");
            gpioTerminate();
            return 1;
        }

        fprintf(log_file, "%s, Temperature: %f C\n", timestamp, temp_c);
        fclose(log_file);

        sleep(1);
    }

    gpioTerminate();
    return 0;
}

