#include <pigpio.h>
#include <errno.h>

#define DEVICE_ADDR 0x49
#define I2C_BUS 1
#define SAMPLE_INTERVAL 1

static FILE *log_file = NULL;
static gpio pigpio_instance = -1;

void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    pigpio_instance = gpio;
}

void cleanup_pigpio() {
    if (pigpio_instance >= 0) {
        gpioTerminate();
        pigpio_instance = -1;
    }
}

int read_flow_temp(uint8_t *flow, uint8_t *temp) {
    int ret;
    ret = pi_i2c_read_device(I2C_BUS, DEVICE_ADDR, 4, (uint8_t *)flow, 2, (uint8_t *)temp, 2);
    if (ret < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void convert_raw_to_slpm(uint16_t raw_flow, float *slpm) {
    *slpm = ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
}

void convert_raw_to_celsius(uint16_t raw_temp, float *celsius) {
    *celsius = ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;
}

void log_data(float flow_slpm, float temp_celsius) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f,%.2f\n", now, flow_slpm, temp_celsius);
        fflush(log_file);
    }
}

int main() {
    init_pigpio();
    log_file = fopen("flow_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    uint8_t flow[2], temp[2];
    float flow_slpm, temp_celsius;

    signal(SIGINT, cleanup_pigpio);
    signal(SIGTERM, cleanup_pigpio);

    while (1) {
        if (gpioGetVersion() == PI_VERSION) {
            if (read_flow_temp(flow, temp) == 0) {
                convert_raw_to_slpm(flow[0] | (flow[1] << 8), &flow_slpm);
                convert_raw_to_celsius(temp[0] | (temp[1] << 8), &temp_celsius);
                log_data(flow_slpm, temp_celsius);
            } else {
                fprintf(stderr, "Failed to read sensor data, retrying...\n");
                // Retry logic here
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup_pigpio();
    fclose(log_file);
    return 0;
}

