#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigio.h>

#define DHT11_GPIO 4
#define START_PULSE_LOW 18000
#define BIT_DURATION 50
#define CHECKSUM_TIMEOUT 1000
#define DATA_BITS 40
#define SAMPLE_INTERVAL 2000000

enum dht11_status {
    DHT11_SUCCESS,
    DHT11_TIMEOUT,
    DHT11_CHECKSUM_FAILURE,
    DHT11_SENSOR_NOT_PRESENT,
};

enum dht11_status dht11_read(uint8_t *data) {
    int fd;
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    uint8_t response[6];
    uint8_t checksum;
    uint8_t bit_count = 0;
    uint8_t byte_count = 0;

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioTick(START_PULSE_LOW);
    gpioWrite(DHT11_GPIO, 1);

    // Wait for start signal
    if (gpioRead(DHT11_GPIO) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) < 1000) {
            return DHT11_TIMEOUT;
        }
    } else {
        return DHT11_SENSOR_NOT_PRESENT;
    }

    // Read response
    for (int i = 0; i < 6; i++) {
        if (gpioRead(DHT11_GPIO) == 0) {
            response[i] = 1;
            bit_count += BIT_DURATION;
        } else {
            response[i] = 0;
            bit_count += BIT_DURATION;
            if (bit_count >= 80) {
                bit_count = 0;
                byte_count++;
            }
        }
    }

    // Checksum
    checksum = 0;
    for (int i = 0; i < 4; i++) {
        checksum += response[i];
    }
    if (response[4] != checksum) {
        return DHT11_CHECKSUM_FAILURE;
    }

    // Extract humidity and temperature
    data[0] = response[0];
    data[1] = 0;
    data[2] = response[1];
    data[3] = 0;
    data[4] = response[2];
    data[5] = 0;

    return DHT11_SUCCESS;
}

void log_reading(uint8_t humidity, uint8_t temperature) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_struct);

    FILE *file = fopen("dht11_readings.txt", "a");
    if (file) {
        fprintf(file, "%s: humidity=%u%%, temperature=%uC\n", timestamp, humidity, temperature);
        fclose(file);
    }
}

int main() {
    gpioInitialise();
    uint8_t data[6];

    while (1) {
        enum dht11_status status = dht11_read(data);
        switch (status) {
            case DHT11_SUCCESS:
                log_reading(data[0], data[2]);
                break;
            case DHT11_TIMEOUT:
            case DHT11_CHECKSUM_FAILURE:
            case DHT11_SENSOR_NOT_PRESENT:
                fprintf(stderr, "Error: %s\n", status == DHT11_TIMEOUT ? "Timeout" :
                       status == DHT11_CHECKSUM_FAILURE ? "Checksum failure" :
                       "Sensor not present");
                break;
            default:
                break;
        }

        usleep(SAMPLE_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

