        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(SDA_PIN, PI_OUTPUT);
    gpioSetMode(SCL_PIN, PI_OUTPUT);

    if (!gpioI2COpen(I2C_BUS, SDA_PIN, SCL_PIN)) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    struct sht31_data data;
    uint8_t write_buf[3] = {SHT31_CMD, 0x00, 0x00};
    uint8_t read_buf[6];

    while (1) {
        int retry = RETRY_COUNT;
        while (retry--) {
            if (i2c_write(write_buf, sizeof(write_buf))) {
                if (i2c_read(read_buf, sizeof(read_buf))) {
                    data.crc = read_buf[5];
                    if (data.crc != crc8(read_buf, 5, CRC_INIT)) {
                        fprintf(stderr, "CRC validation failed\n");
                        continue;
                    }

                    data.temp_raw = read_buf[1] << 8 | read_buf[2];
                    data.hum_raw = read_buf[3] << 8 | read_buf[4];

                    double temp = -45 + 175 * (data.temp_raw / 65535.0);
                    double humidity = 100 * (data.hum_raw / 65535.0);

                    time_t now = time(NULL);
                    struct tm *tm_info = localtime(&now);

                    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                            1900 + tm_info->tm_year, tm_info->tm_mon + 1, tm_info->tm_mday,
                            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                            temp, humidity);
                    break;
                }
            }
        }

        if (retry == -1) {
            fprintf(stderr, "Persistent sensor failure\n");
        }

        sleep(5);
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

