#define SENSOR_ADDR1 0x64
#define SENSOR_ADDR2 0x65
#define DEVICE_ID 0x2A

struct sensor_data {
    int16_t red, green, blue;
    double cct;
};

void calculate_cct(int16_t r, int16_t g, int16_t b, double *cct) {
    *cct = 449.0 / (r + 0.045) + 3259.0 / (g + 0.055) + 0.00825 / (b + 0.075);
}

int main() {
    struct sensor_data sensor_data1, sensor_data2;
    FILE *fp = NULL;
    int ret;
    gpioInitialise();

    if ((ret = gpioSetMode(0, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        goto exit_cleanup;
    }

    if ((ret = pigpio_initialise()) < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        goto exit_gpio_cleanup;
    }

    if ((fp = fopen("cct_log.csv", "a")) == NULL) {
        fprintf(stderr, "Failed to open cct_log.csv\n");
        goto exit_pigpio_cleanup;
    }

    if (fopen_s(&fp, "cct_log.csv", "w") == 0) {
        fprintf(fp, "Timestamp,Average_CCT\n");
    }

    while (1) {
        int16_t red1, green1, blue1;
        int16_t red2, green2, blue2;
        double cct1, cct2;

        if ((ret = i2cWriteI2CBlockData(1, SENSOR_ADDR1, 0x00, (uint8_t *) &DEVICE_ID, 1)) < 0) {
            fprintf(stderr, "Error reading device ID from sensor 1\n");
            continue;
        }

        if ((ret = i2cReadI2CBlockData(1, SENSOR_ADDR1, 0x64, (uint8_t *) &red1, 2)) < 0) {
            fprintf(stderr, "Error reading red data from sensor 1\n");
            continue;
        }
        if ((ret = i2cReadI2CBlockData(1, SENSOR_ADDR1, 0x66, (uint8_t *) &green1, 2)) < 0) {
            fprintf(stderr, "Error reading green data from sensor 1\n");
            continue;
        }
        if ((ret = i2cReadI2CBlockData(1, SENSOR_ADDR1, 0x68, (uint8_t *) &blue1, 2)) < 0) {
            fprintf(stderr, "Error reading blue data from sensor 1\n");
            continue;
        }

        if ((ret = i2cWriteI2CBlockData(1, SENSOR_ADDR2, 0x00, (uint8_t *) &DEVICE_ID, 1)) < 0) {
            fprintf(stderr, "Error reading device ID from sensor 2\n");
            continue;
        }

        if ((ret = i2cReadI2CBlockData(1, SENSOR_ADDR2, 0x64, (uint8_t *) &red2, 2)) < 0) {
            fprintf(stderr, "Error reading red data from sensor 2\n");
            continue;
        }
        if ((ret = i2cReadI2CBlockData(1, SENSOR_ADDR2, 0x66, (uint8_t *) &green2, 2)) < 0) {
            fprintf(stderr, "Error reading green data from sensor 2\n");
            continue;
        }
        if ((ret = i2cReadI2CBlockData(1, SENSOR_ADDR2, 0x68, (uint8_t *) &blue2, 2)) < 0) {
            fprintf(stderr, "Error reading blue data from sensor 2\n");
            continue;
        }

        calculate_cct(red1, green1, blue1, &cct1);
        calculate_cct(red2, green2, blue2, &cct2);

        sensor_data1.red = (red1 >> 8) | red1;
        sensor_data1.green = (green1 >> 8) | green1;
        sensor_data1.blue = (blue1 >> 8) | blue1;
        sensor_data1.cct = cct1;

        sensor_data2.red = (red2 >> 8) | red2;
        sensor_data2.green = (green2 >> 8) | green2;
        sensor_data2.blue = (blue2 >> 8) | blue2;
        sensor_data2.cct = cct2;

        double avg_cct = (cct1 + cct2) / 2;
        time_t now = time(NULL);
        printf("%ld,%.2f\n", (long)now, avg_cct);
        fflush(stdout);

        if (fp != NULL) {
            fprintf(fp, "%ld,%.6f\n", (long)now, avg_cct);
            fflush(fp);
        }

        gpioTerminate();
        pigpio_terminate();
        sleep(1);
    }

exit_pigpio_cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
exit_gpio_cleanup:
    gpioTerminate();
exit_cleanup:
    pigpio_terminate();
    return 0;
}

