#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define I2C_ADDR 0x60
#define RAW_PRESS_REG 0x0A2C
#define RAW_TEMP_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN_KPA 0
#define PMAX_KPA 800

int main() {
    const char *log_file = "pressure_log.txt";
    FILE *log_fp = fopen(log_file, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        return 1;
    }

    int i2c_fd = pigpio_i2c_open(1);
    if (!i2c_fd) {
        perror("Failed to open I2C bus 1");
        fclose(log_fp);
        return 1;
    }

    if (pigpio_i2c_address(i2c_fd, I2C_ADDR)) {
        fprintf(stderr, "Failed to set I2C address\n");
        pigpio_i2c_close(i2c_fd);
        fclose(log_fp);
        return 1;
    }

    int ret = pigpio_initialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        pigpio_i2c_close(i2c_fd);
        fclose(log_fp);
        return 1;
    }

    while (1) {
        uint16_t raw_pressure, raw_temp;

        ret = pigpio_i2c_read(i2c_fd, RAW_PRESS_REG, &raw_pressure, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read pressure register: %d\n", ret);
            continue;
        }

        ret = pigpio_i2c_read(i2c_fd, RAW_TEMP_REG, &raw_temp, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature register: %d\n", ret);
            continue;
        }

        double pressure_kPa = (double)(raw_pressure - OUTPUT_MIN) * (PMAX_KPA - PMIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN) + PMIN_KPA;
        double temp_C = raw_temp * 0.01 - 40;

        time_t now_time = time(NULL);
        struct tm *local_time = localtime(&now_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", local_time);

        fprintf(log_fp, "%s: Pressure = %.2f kPa, Temperature = %.2f C\n", timestamp, pressure_kPa, temp_C);
        fflush(log_fp);

        sleep(2);
    }

    pigpio_terminate();
    pigpio_i2c_close(i2c_fd);
    fclose(log_fp);

    return 0;
}

