        fprintf(stderr, "pigpio initialization failed\n");
        exit(1);
    }
}

void cleanup_pigpio() {
    gpioTerminate();
}

uint16_t read_temperature_register(int bus, uint8_t addr) {
    uint16_t temp_raw;
    int ret;

    ret = piGetI2CMsg(&temp_raw, addr, 2, bus);
    if (ret < 0) {
        fprintf(stderr, "I2C read failed\n");
        return 0;
    }

    return temp_raw;
}

float convert_temperature(uint16_t raw_temp) {
    int sign_bit = (raw_temp >> 15) & 0x1;
    int temp_value = (raw_temp >> 1) & 0x7FF;

    if (sign_bit) {
        temp_value = -(temp_value + 1);
    }

    return (float)temp_value / 8.0;
}

void update_running_average(float new_temp) {
    running_average = (running_average * (buffer_index) + new_temp) / (buffer_index + 1);
    buffer[buffer_index] = new_temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main(int argc, char *argv[]) {
    init_pigpio();

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        cleanup_pigpio();
        return 1;
    }

    gpioSetWarningOnOverrun(true);
    gpioSetOutputLevel(FAN_GPIO, 0);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        uint16_t raw_temp = read_temperature_register(1, I2C_ADDR);
        float temp = convert_temperature(raw_temp);

        update_running_average(temp);

        if (running_average > TURN_ON_THRESHOLD && !fan_state) {
            gpioWrite(FAN_GPIO, 1);
            fan_state = 1;
        } else if (running_average < TURN_OFF_THRESHOLD && fan_state) {
            gpioWrite(FAN_GPIO, 0);
            fan_state = 0;
        }

        usleep(1000000);
    }

    cleanup_pigpio();
    return 0;
}
