int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigfillset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting signal handlers\n");
        return 1;
    }

    i2c_fd = i2c_open(1, 0);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

