        i2c_close(i2c_fd);
        return 1;
    }

    if (i2c_write(SENS_ADDR, &CMD_CONT_MEAS, 2) == -1) {
        fprintf(stderr, "Failed to send command to sensor\n");
        goto cleanup;
    }

    usleep(45000);

    while (1) {
        uint8_t buf[9];
        if (i2c_read(SENS_ADDR, buf, 9) == -1) {
            fprintf(stderr, "Failed to read from sensor\n");
            goto cleanup;
        }

        crc8(buf, 9, buf);

        int16_t pressure = (int16_t)((buf[1] << 8) | buf[2]);
        int16_t temperature = (int16_t)((buf[3] << 8) | buf[4]);

        float press_pa = pressure * SCALE_PRESS;
        float temp_c = temperature * SCALE_TEMP;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        fprintf(stdout, "%ld,%.2f,%.2f\n", (long)(tm_info->tm_hour * 3600 + tm_info->tm_min * 60 + tm_info->tm_sec), press_pa, temp_c);

        if (press_pa > 5.0) {
            fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");
        }

        fflush(stdout);

        usleep(1000000);
    }

cleanup:
    gpioTerminate();
    close(i2c_fd);
    close(log_fd);
    return 0;
}

void crc8(uint8_t *data, size_t len, uint8_t *crc) {
    *crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        uint8_t crc_temp;
        for (int j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ CRC8_POLY;
            } else {
                *crc <<= 1;
            }
            if (*data & 0x80) {
                *crc ^= CRC8_POLY;
            }
            *data <<= 1;
        }
        crc_temp = *crc;
    }
    *crc = crc_temp;
}

