    if (write(i2c_fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int i2c_write(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

