#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define STTS2004_ADDR 0x4A
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28
#define TEMP_THRESHOLD_LOW 27

int main() {
    int fd, res;
    gpiod_chip_reg_desc_t chip_reg;
    gpiod_line_request_t lr;
    struct i2c_rdwr_ioctl_data rdwr_data;
    struct i2c_client *client;
    uint16_t temp;
    float temp_celsius;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    ioctl(fd, I2C_SLAVE, STTS2004_ADDR);

    chip_reg.gpio = gpiod_chip_register_acquire(LED_GPIO);
    if (!chip_reg.gpio) {
        perror("Failed to acquire GPIO chip");
        close(fd);
        return 1;
    }

    lr.index = chip_reg.gpio->id;
    lr.flags = GPIO_DIR_OUT;
    if (gpiod_line_request_add(&chip_reg.chip, &lr) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_release(chip_reg.gpio);
        close(fd);
        return 1;
    }

    rdwr_data.u8 = &temp;
    rdwr_data.u8_rw = I2C_M_RD;
    rdwr_data.len = sizeof(temp);

    while (1) {
        rdwr_data.u8_rw = I2C_M_RD;
        res = ioctl(fd, I2C_RDWR, &rdwr_data);
        if (res < 0) {
            if (errno == EAGAIN) {
                printf("I2C read failed (EAGAIN), retrying...\n");
                continue;
            }
            perror("Failed to read from I2C bus");
            break;
        }

        temp = (temp << 8) | rdwr_data.u8[0];
        temp_celsius = (float)temp / 16.0;

        printf("Temperature: %.2f °C\n", temp_celsius);

        if (temp_celsius > TEMP_THRESHOLD_HIGH) {
            gpiod_line_set_value(chip_reg.gpio, 1);
        } else if (temp_celsius < TEMP_THRESHOLD_LOW) {
            gpiod_line_set_value(chip_reg.gpio, 0);
        }

        sleep(1);
    }

    gpiod_line_request_free(&lr);
    gpiod_chip_release(chip_reg.gpio);
    close(fd);

    return 0;
}

