#define SDP800_ADDR 0x25
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

int main() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    gpioInitialise();
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    gpioSetMode(0, PI_OUTPUT);
    gpioSetMode(1, PI_INPUT);

    signal(SIGINT, sigint_handler);

    while (!sigint_received) {
        if (gpioRead(1) & (1 << 24)) { // Check for sensor presence
            uint8_t cmd[2] = {0x36, 0x2F};
            gpioWrite(0, cmd, 2, 1);

            clock_gettime(CLOCK_MONOTONIC, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

            uint8_t data[9];
            int rd = gpioRead(1, data, 9);
            if (rd < 9) {
                fprintf(stderr, "I2C read error: only %d bytes received instead of 9.\n", rd);
                continue;
            }

            int crc_pressure = crc8((uint8_t*)data, 4, CRC_INIT, CRC_POLY);
            if (data[0] != crc_pressure) {
                fprintf(stderr, "CRC error for pressure data.\n");
                continue;
            }

            int16_t scale_factor = (int16_t)(data[6] << 8 | data[7]);
            float pressure = (float)(data[2] << 8 | data[3]) / scale_factor;

            crc_pressure = crc8((uint8_t*)&pressure, 4, CRC_INIT, CRC_POLY);
            if (pressure_data[0] != crc_pressure) {
                fprintf(stderr, "CRC error for pressure data.\n");
                continue;
            }

            int crc_temp = crc8(&data[4], 5, CRC_INIT, CRC_POLY);
            if (data[4] != crc_temp) {
                fprintf(stderr, "CRC error for temperature data.\n");
                continue;
            }

            float temp = (float)(data[4] << 8 | data[5]) / 200.0;

            FILE *fp = fopen("flow_data.txt", "a");
            if (!fp) {
                fprintf(stderr, "Failed to open flow_data.txt for writing.\n");
                gpioTerminate();
                return 1;
            }

            fprintf(fp, "%s: Pressure = %.2f hPa, Temperature = %.2f °C\n", timestamp, pressure, temp);
            fclose(fp);
        } else {
            fprintf(stderr, "No sensor detected on I2C bus 1 at address 0x25.\n");
        }
    }

    gpioTerminate();
    return 0;
}

uint8_t crc8(const void *data, size_t len, uint8_t init_crc, uint8_t poly) {
    const uint8_t *d = data;
    uint8_t crc = init_crc;

    for (size_t i = 0; i < len; i++) {
        crc ^= (uint8_t)d[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

