#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define SI7021_ADDR 0x40
#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define MAX_RETRIES 3
#define WAIT_TIME_MS 20000

static int i2c_fd = -1;
static gpio_init rpi;

void sigint_handler(int signum) {
    gpioTerminate(rpi);
    exit(0);
}

void sigterm_handler(int signum) {
    gpioTerminate(rpi);
    exit(0);
}

int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    i2c_fd = i2cOpen(I2C_BUS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate(rpi);
        return -1;
    }

    gpioSetMode(SDA_PIN, PI_OUTPUT);
    gpioSetMode(SCL_PIN, PI_OUTPUT);

    return 0;
}

void close_i2c() {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
        i2c_fd = -1;
    }
    gpioTerminate(rpi);
}

int read_si7021_byte(uint8_t command) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        gpioSetLow(SCL_PIN);
        gpioSetLow(SDA_PIN);
        gpioSetHigh(SCL_PIN);

        i2cWriteDevice(i2c_fd, &command, 1);

        for (int i = 0; i < 9; i++) {
            if (i2cReadDevice(i2c_fd, &result, 1) < 0) {
                retries++;
