#define HDC1080_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMIDITY_REG 0x01
#define CONVERSION_DELAY_MS 20

static const char *log_file = "enviro_log.txt";
static const char *timestamp_format = "%Y-%m-%d %H:%M:%S";

int main() {
    struct pi_addr i2c_addr = {HDC1080_ADDR, I2C_OPEN_FAST | I2C_DMA_OPEN};
    int rc;
    gpioInitialise();

    if ((rc = piGpioI2cOpen(&i2c_addr, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto exit_cleanup;
    }

    if ((rc = piGpioWrite(&i2c_addr, CONFIG_REG, &config_value)) < 0) {
        fprintf(stderr, "Failed to write to configuration register\n");
        goto i2c_close;
    }

    config_value |= (1 << 6); // Enable 14-bit resolution
    if ((rc = piGpioWrite(&i2c_addr, CONFIG_REG, &config_value)) < 0) {
        fprintf(stderr, "Failed to update configuration register\n");
        goto i2c_close;
    }

    while (1) {
        gpioWaitEvent(i2c_addr.gpio, GPIO_EDGE_RISING, 0, 1000000);
        if ((rc = piGpioI2cRead(&i2c_addr, TEMP_REG, (uint8_t *)&raw_temp)) < 0) {
            fprintf(stderr, "I2C read error for temperature\n");
            continue;
        }
        if ((rc = piGpioI2cRead(&i2c_addr, HUMIDITY_REG, (uint8_t *)&raw_humidity)) < 0) {
            fprintf(stderr, "I2C read error for humidity\n");
            continue;
        }

        temperature = (raw_temp >> 4) * 165.0 - 40.0;
        humidity = (raw_humidity >> 4) * 100.0;

        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), timestamp_format, lt);

        FILE *fp = fopen(log_file, "a");
        if (fp != NULL) {
            fprintf(fp, "%s, %.2f, %.2f\n", timestamp, temperature, humidity);
            fclose(fp);
        } else {
            fprintf(stderr, "Failed to open log file\n");
        }
    }

i2c_close:
    piGpioI2cClose(&i2c_addr);
exit_cleanup:
    gpioTerminate();
    return 0;
}

