#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define SENS_ADDR 0x44
#define CRC_POLY 0x31

int i2c_fd = -1;

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main() {
    struct i2c_rdwr_ioctl_data rdwr_data;
    struct i2c_msg messages[1];
    int ret;
    int log_fd = -1;

    // Register signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENS_ADDR) < 0) {
        perror("Failed to set slave address");
        close(i2c_fd);
        return 1;
    }

    // Prepare read/write data
    messages[0].len = 1;
    messages[0].addr = SENS_ADDR;
    messages[0].flags = 0;
    messages[0].data = (unsigned char *)"\x2C\xE0";
    rdwr_data.msgs = messages;
    rdwr_data.nmsgs = 1;

    // Write command bytes
    if (write(i2c_fd, &rdwr_data, sizeof(rdwr_data)) != rdwr_data.len) {
        perror("Failed to write to I2C bus");
        close(i2c_fd);
        return 1;
    }

    // Wait for conversion
    usleep(10000);

    // Read 3 bytes
    if ((ret = read(i2c_fd, &rdwr_data, sizeof(rdwr_data))) != 3) {
        perror("Failed to read from I2C bus");
        close(i2c_fd);
        return 1;
    }

    // Validate CRC8
    if (crc8((unsigned char *)rdwr_data.data, 2, CRC_POLY) != rdwr_data.data[1]) {
        fprintf(stderr, "CRC mismatch\n");
        close(i2c_fd);
        return 1;
    }

    // Convert raw ticks to Celsius
    double raw = (rdwr_data.data[0] << 8) | rdwr_data.data[1];
    double temp = -45 + 175 * raw / 65535.0;

    // Open log file
    log_fd = open("temperature_log.txt", O_APPEND | O_WRONLY | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Log temperature
    time_t now = time(NULL);
    fprintf(log_fd, "%ld.%03ld\t%.2f C\n", (long)now, (now % 1000) * 1000 + 500, temp);
    fflush(log_fd);

    // Infinite loop
    while (1) {
        // Sleep for 5 seconds
        sleep(5);

        // Repeat reading and logging
        // ...
    }

    // Clean shutdown
    close(i2c_fd);
    close(log_fd);

    return 0;
}

// CRC8 calculation
unsigned char crc8(const unsigned char *data, size_t len, unsigned char poly) {
    unsigned char crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

