#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <i2c/i2c.h>

#define SDP810_I2C_ADDR 0x25
#define SDP810_CMD_CONT_MEAS 0x3615
#define SDP810_CRC_POLY 0x31
#define SDP810_CRC_INIT 0xFF
#define SDP810_PRESS_SCALE_FACTOR 100.0

static int i2c_fd;
static FILE *log_file;

static uint8_t sdp810_read(uint8_t reg) {
    uint8_t data;
    int ret = i2c_rdwr_ptr(i2c_fd, &reg, 1, &data, 1);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return data;
}

static int sdp810_write(uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    int ret = i2c_rdwr(i2c_fd, data, 2);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static uint8_t crc8(uint8_t *data, size_t len, uint8_t init_crc) {
    uint8_t crc = init_crc;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int ret;

    // Initialize GPIO
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(-ret));
        return 1;
    }

    // Open I2C bus 1
    i2c_fd = i2cOpen(1, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("hvac_pressure_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    sdp810_write(SDP810_I2C_ADDR << 1, SDP810_CMD_CONT_MEAS);

    while (1) {
        // Wait for at least 50 ms
        usleep(50000);

        // Read pressure and temperature data
        uint8_t pressure_raw[3], temp_raw[3];
        pressure_raw[0] = sdp810_read(0x00);
        pressure_raw[1] = sdp810_read(0x01);
        temp_raw[0] = sdp810_read(0x02);
        temp_raw[1] = sdp810_read(0x03);

        // Validate CRC
        uint8_t crc_received = (pressure_raw[2] << 8) | pressure_raw[3];
        if (crc8((uint8_t *)pressure_raw, 4, SDP810_CRC_INIT) != crc_received) {
            fprintf(stderr, "CRC error (pressure)\n");
            continue;
        }

        crc_received = (temp_raw[2] << 8) | temp_raw[3];
        if (crc8((uint8_t *)temp_raw, 4, SDP810_CRC_INIT) != crc_received) {
            fprintf(stderr, "CRC error (temperature)\n");
            continue;
        }

        // Convert raw data
        float pressure_Pa = (float)(pressure_raw[0] << 8 | pressure_raw[1]) / SDP810_PRESS_SCALE_FACTOR;
        float temp_C = (float)(temp_raw[0] << 8 | temp_raw[1]) / 200.0;

        // Log data
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f,%.2f\n", (long)now, pressure_Pa, temp_C);
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

