#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_COMMAND 0xE000
#define CO2_REG 0x0
#define TEMP_REG 0x2
#define HUMIDITY_REG 0x4

typedef struct {
    volatile sig_atomic_t running;
    gpio *gpio;
    int fd;
} scd40_context;

typedef struct {
    time_t timestamp;
    int64_t co2;
    float temperature;
    float humidity;
} reading;

reading buffer[BUFFER_CAPACITY];
int buffer_index = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

void *logging_thread(void *arg) {
    scd40_context *ctx = (scd40_context *)arg;
    FILE *file = fopen("/var/log/scd40_data/scd40_data.csv", "a");
    if (!file) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        return NULL;
    }
    fprintf(file, "timestamp,CO2,Temperature,Humidity\n");

    while (ctx->running) {
        pthread_mutex_lock(&buffer_mutex);
        int count = 0;
        for (int i = 0; i < BUFFER_CAPACITY; i++) {
            if (buffer[i].timestamp != 0) {
                fprintf(file, "%ld,%lld,%f,%f\n",
                        buffer[i].timestamp, buffer[i].co2, buffer[i].temperature, buffer[i].humidity);
                count++;
            }
        }
        pthread_mutex_unlock(&buffer_mutex);

        if (count) {
            fprintf(file, "\n");
        }

        sleep(60);
    }

    pthread_mutex_lock(&buffer_mutex);
    int count = 0;
    for (int i = 0; i < BUFFER_CAPACITY; i++) {
        if (buffer[i].timestamp != 0) {
            fprintf(file, "Final Data:\n");
            fprintf(file, "%ld,%lld,%f,%f\n",
                    buffer[i].timestamp, buffer[i].co2, buffer[i].temperature, buffer[i].humidity);
            count++;
        }
    }
    pthread_mutex_unlock(&buffer_mutex);

    fclose(file);
    return NULL;
}

void init_pigpio(scd40_context *ctx) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    ctx->gpio = gpio;
    ctx->fd = gpioI2COpen(I2C_BUS, SCD40_I2C_ADDR);
    if (ctx->fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void send_command(scd40_context *ctx, uint8_t command) {
    if (gpioI2CWrite(ctx->fd, &command, 1) != 1) {
        fprintf(stderr, "Error: Failed to send command 0x%02X\n", command);
    }
}

uint8_t read_byte(scd40_context *ctx) {
    uint8_t byte;
    if (gpioI2CRead(ctx->fd, &byte, 1) != 1) {
        fprintf(stderr, "Error: Failed to read byte from I2C\n");
        return 0;
    }
    return byte;
}

uint16_t crc8(uint8_t *data, int len, uint8_t init_value, uint8_t polynomial) {
    uint8_t crc = init_value;
    for (int i = 0; i < len; i++) {
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ polynomial;
            } else {
                crc = crc >> 1;
            }
            if (i == len - 1) {
                break;
            }
            crc <<= 1;
            if (data[i + 1] & 0x01) {
                crc ^= polynomial;
            }
            data[i + 1] >>= 1;
        }
    }
    return crc;
}

void read_data(scd40_context *ctx) {
    send_command(ctx, READ_COMMAND);

    uint8_t data[9];
    for (int i = 0; i < 9; i++) {
        data[i] = read_byte(ctx);
    }

    if (crc8(&data[1], 8, data[0], CRC_POLYNOMIAL) != data[1]) {
        fprintf(stderr, "Error: CRC check failed for data\n");
        return;
    }

    uint16_t co2_raw = (data[CO2_REG] << 8) | data[CO2_REG + 1];
    uint16_t temp_raw = (data[TEMP_REG] << 8) | data[TEMP_REG + 1];
    uint16_t humidity_raw = (data[HUMIDITY_REG] << 8) | data[HUMIDITY_REG + 1];

    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].co2 = co2_raw;
    buffer[buffer_index].temperature = -45 + 175 * co2_raw / 65535;
    buffer[buffer_index].humidity = 100 * humidity_raw / 65535;

    buffer_index = (buffer_index + 1) % BUFFER_CAPACITY;
}

void *main_loop(void *arg) {
    scd40_context *ctx = (scd40_context *)arg;
    init_pigpio(ctx);

    send_command(ctx, START_PERIODIC_MEASUREMENT);
    sleep(5);

    while (ctx->running) {
        read_data(ctx);
        sleep(5);
    }

    send_command(ctx, STOP_PERIODIC_MEASUREMENT);
    return NULL;
}

int main(int argc, char *argv[]) {
    scd40_context ctx;
    ctx.running = 1;

    if (signal(SIGINT, ([](int) {
        ctx.running = 0;
    })) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to set SIGINT handler\n");
        return EXIT_FAILURE;
    }

    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, &ctx) != 0) {
        fprintf(stderr, "Error: Failed to create logging thread\n");
        return EXIT_FAILURE;
    }

    if (pthread_create(&pthread_self(), NULL, main_loop, &ctx) != 0) {
        fprintf(stderr, "Error: Failed to create main loop thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(logging_thread_id, NULL);
    pthread_join(pthread_self(), NULL);

    gpioTerminate();
    return EXIT_SUCCESS;
}

