struct sdp810_reading {
    double timestamp;
    int32_t pressure_Pa;
    float temperature_C;
};

void sigint_handler(int signum) {
    gpioTerminate();
    close(i2c_fd);
    remove("sdp810_log.txt");
    exit(0);
}

int main() {
    struct sdp810_reading reading;
    int i2c_fd;
    char msg[100];
    int ret;

    signal(SIGINT, sigint_handler);

    i2c_fd = i2c_open(I2C_BUS, SDP810_ADDR);
    if (i2c_fd < 0) {
        perror("i2c_open");
        return 1;
    }

    gpioInitialise();

    while (1) {
        time(&reading.timestamp);
        sprintf(msg, "%%04d,%%d,%%f\n", (int)(reading.timestamp), 0, 0);

        ret = i2c_write(i2c_fd, "362F", 2);
        if (ret < 0) {
            fprintf(stderr, "i2c_write error: %s\n", i2c_get_error());
            continue;
        }

        usleep(45000);

        ret = i2c_rdwr(i2c_fd, .k_rd = NULL, 0, .d_rd = NULL, 9, .d_wr = NULL, 0);
        if (ret < 0) {
            fprintf(stderr, "i2c_rdwr error: %s\n", i2c_get_error());
            continue;
        }

        uint8_t data[9] = {0};
        memcpy(data, i2c_rd_buf, 9);

        uint16_t raw_pressure = (data[0] << 8) | data[1];
        uint16_t crc_pressure = calculate_crc(data, 2, CRC_POLY, CRC_INIT);
        if (crc_pressure != (data[2] << 8) | data[3]) {
            fprintf(stderr, "CRC pressure error\n");
            continue;
        }

        uint16_t raw_temp = (data[4] << 8) | data[5];
        crc_pressure = calculate_crc(data, 6, CRC_POLY, CRC_INIT);
        if (crc_temp != (data[7] << 8) | data[8]) {
            fprintf(stderr, "CRC temperature error\n");
            continue;
        }

        float scale_factor = (float)(data[6] << 8) | data[7] / 1000;
        reading.pressure_Pa = raw_pressure * scale_factor / 1000;
        reading.temperature_C = -45 + 175 * raw_temp / 65535;

        FILE *log_file = fopen("sdp810_log.txt", "a");
        if (log_file != NULL) {
            fprintf(log_file, "%s", msg);
            fclose(log_file);
        }

        usleep(1000000000);
    }

    gpioTerminate();
    close(i2c_fd);
    remove("sdp810_log.txt");
    return 0;
}

uint8_t calculate_crc(const uint8_t *data, int len, uint8_t poly, uint8_t init_val) {
    uint8_t crc = init_val;
    for (int i = 0; i < len; i++) {
        for (int j = 0; j < 8; j++) {
            crc ^= data[i] << j;
            if (crc & 0x80) {
                crc ^= poly;
            }
        }
    }
    return crc;
}

