#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_ADDR 0x63
#define LED_GPIO 17
#define POLL_INTERVAL 1
#define WARNING_PRESSURE 95000

static int i2c_fd;
static int led_chip;
static int led_line;

void blink_led(int pressure) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int blink_freq = (pressure < WARNING_PRESSURE) ? 5 : 1;
    int blink_period = (pressure < WARNING_PRESSURE) ? 100 : 500;

    chip = gpiod_chip_open(led_chip, "user-led");
    if (!chip) {
        fprintf(stderr, "Failed to open LED chip\n");
        return;
    }

    line = gpiod_chip_get_line(chip, "led");
    if (!line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        return;
    }

    gpiod_line_set_direction(line, GPIO_OUTPUT);
    gpiod_line_set_value(line, 0);

    for (int i = 0; i < 10000000 / blink_freq; ++i) {
        gpiod_line_set_value(line, (i % blink_period) < blink_period / 2);
        usleep(16666); // Approximate 1 ms
    }

    gpiod_line_set_value(line, 0);
    gpiod_chip_close(chip);
}

int main() {
    int ret;
    struct i2c_rdwr_ioctl_data rdwr;
    uint8_t otp_data[4];
    uint32_t pressure, temperature;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus\n");
        close(i2c_fd);
        return 1;
    }

    led_chip = gpiod_chip_open(NULL, "GPIO17");
    if (!led_chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(led_chip, "user-led");
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return 1;
    }

    gpiod_line_set_direction(led_line, GPIO_OUTPUT);
    gpiod_line_set_value(led_line, 0);

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        fprintf(stderr, "Failed to prepare I2C read\n");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return 1;
    }

    rdwr.u8 = otp_data;
    rdwr.u8_len = sizeof(otp_data);
    rdwr.u32_len = 0;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        fprintf(stderr, "Failed to read OTP data\n");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return 1;
    }

    if (write(i2c_fd, 0x4011, 1) < 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return 1;
    }

    usleep(20000);

    if (read(i2c_fd, &rdwr, sizeof(rdwr)) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return 1;
    }

    pressure = (rdwr.u32[0] << 16) | (rdwr.u32[1] << 8) | rdwr.u32[2];
    temperature = (rdwr.u32[3] << 16) | (rdwr.u32[4] << 8) | rdwr.u32[5];

    if (crc32(0, (uint8_t *)&rdwr, sizeof(rdwr)) != rdwr.crc) {
        fprintf(stderr, "CRC mismatch\n");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return 1;
    }

    pressure = (pressure >> 4) * 0.000194384; // Convert to Pa
    temperature = (temperature >> 4) - 46.852; // Convert to C

    printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

    while (1) {
        blink_led(pressure);
        pressure = (read(i2c_fd, &rdwr, sizeof(rdwr)) < 0) ? -1 : (rdwr.u32[0] << 16) | (rdwr.u32[1] << 8) | rdwr.u32[2];
        temperature = (read(i2c_fd, &rdwr, sizeof(rdwr)) < 0) ? -1 : (rdwr.u32[3] << 16) | (rdwr.u32[4] << 8) | rdwr.u32[5];

        if (pressure != -1) {
            if (crc32(0, (uint8_t *)&rdwr, sizeof(rdwr)) != rdwr.crc) {
                fprintf(stderr, "CRC mismatch\n");
                break;
            }

            pressure = (pressure >> 4) * 0.000194384; // Convert to Pa
            temperature = (temperature >> 4) - 46.852; // Convert to C

            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        }

        usleep(POLL_INTERVAL * 1000000);
    }

    gpiod_chip_close(led_chip);
    close(i2c_fd);

    return 0;
}

