#include <stdio.h>
#include <stdlib.h>
#include <string.Fan.h>
#include <time.h>
#include <pigpio.h>

#define I2C_ADDR 0x5A
#define FAN_PIN 18
#define TEMP_LOG_FILE "temperature_log.txt"
#define READ_RETRY_COUNT 3
#define READ_DELAY_MS 10

float read_temp_celsius(uint16_t raw_temp);
void setup_logging();
void log_temperature(float ambient_temp, float obj_temp);
void control_fan(float obj_temp);

int main() {
    struct gpio p;
    int i2c_fd;
    int ret;

    // Initialize pigpio library
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    // Initialize GPIO for fan control
    gpio_set_mode(FAN_PIN, PI_OUTPUT);
    gpio_write(FAN_PIN, 0);

    // Open I2C bus 1
    i2c_fd = i2c_open(1, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        pigpio_terminate();
        return 1;
    }

    // Setup logging
    setup_logging();

    while (1) {
        float ambient_temp, obj_temp;
        for (int retry = 0; retry < READ_RETRY_COUNT; retry++) {
            // Read ambient temperature
            if (pigpio_i2c_rd(i2c_fd, I2C_ADDR, 0x06, &ambient_temp, 2) != 2) {
                if (retry == READ_RETRY_COUNT - 1) {
                    fprintf(stderr, "Failed to read ambient temperature after %d retries.\n", READ_RETRY_COUNT);
                    break;
                }
                printf("Failed to read ambient temperature, retrying in %d ms...\n", READ_DELAY_MS);
                sleep(READ_DELAY_MS / 1000);
                continue;
            }
            ambient_temp = read_temp_celsius(ambient_temp);

            // Read object temperature
            if (pigpio_i2c_rd(i2c_fd, I2C_ADDR, 0x07, &obj_temp, 2) != 2) {
                if (retry == READ_RETRY_COUNT - 1) {
                    fprintf(stderr, "Failed to read object temperature after %d retries.\n", READ_RETRY_COUNT);
                    break;
                }
                printf("Failed to read object temperature, retrying in %d ms...\n", READ_DELAY_MS);
                sleep(READ_DELAY_MS / 1000);
                continue;
            }
            obj_temp = read_temp_celsius(obj_temp);

            control_fan(obj_temp);
            log_temperature(ambient_temp, obj_temp);
            break;
        }

        sleep(2);
    }

    // Clean up
    pigpio_stop();
    i2c_close(i2c_fd);
    pigpio_terminate();

    return 0;
}

float read_temp_celsius(uint16_t raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

void setup_logging() {
    FILE *log_file = fopen(TEMP_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s for writing.\n", TEMP_LOG_FILE);
        exit(1);
    }
    fmtdtime_s fmtd;
    fmtdtime_now(&fmtd);

    fprintf(log_file, "%02d:%02d:%02d %f %f\n",
            fmtd.hour, fmtd.min, fmtd.sec,
            read_temp_celsius(0), read_temp_celsius(0));
    fclose(log_file);
}

void log_temperature(float ambient_temp, float obj_temp) {
    FILE *log_file = fopen(TEMP_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s for writing.\n", TEMP_LOG_FILE);
        return;
    }

    fmtdtime_s fmtd;
    fmtdtime_now(&fmtd);

    fprintf(log_file, "%02d:%02d:%02d %f %f\n",
            fmtd.hour, fmtd.min, fmtd.sec,
            ambient_temp, obj_temp);
    fclose(log_file);
}

void control_fan(float obj_temp) {
    if (obj_temp > 30.0) {
        gpio_write(FAN_PIN, 1);
    } else if (obj_temp < 28.0) {
        gpio_write(FAN_PIN, 0);
    }
}

