        } else if (bytes_read < 0) {
            fprintf(stderr, "I2C communication error, retrying...\n");
            retries++;
            continue;
        } else {
            fprintf(stderr, "Unexpected number of bytes read: %d\n", bytes_read);
            return -1;
        }
    }

    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read data from SHT40 after %d retries\n", RETRY_COUNT);
        return -1;
    }

    return buffer[1] << 8 | buffer[2];
}

float convert_temperature(uint16_t raw_temp) {
    return -45 + 175 * (float)raw_temp / 65535;
}

float convert_humidity(uint16_t raw_humidity) {
    return -6 + 125 * (float)raw_humidity / 65535;
}

