            usleep(100000); // Wait for heater to disable
            continue;
        }

        if (i2c_read(i2c_fd, 0x00, &temp) < 0) {
            return -1;
        }

        if (i2c_read(i2c_fd, 0x02, &humidity) < 0) {
            return -1;
        }

        return (temp << 8 | humidity);
    }

    return -1;
}

