#include <pigio.h>

#define SDP800_ADDR 0x25
#define CONT_MEAS_CMD 0x362F
#define CRC_POLYNOMIAL 0x31

typedef struct {
    int16_t pressure;
    int16_t temperature;
} SensorData;

static volatile sig_atomic_t running = 1;
static pigpio *gpio;
static gpioI2C *i2c;
SensorData sensor_data;

static void sigint_handler(int signo) {
    running = 0;
}

static void read_sensor(void) {
    if (!gpio || !i2c) {
        fprintf(stderr, "Error: Sensor or I2C not initialized.\n");
        return;
    }

    gpioTerminate();

    // Trigger continuous measurement
    gpioWrite(SDP800_ADDR, CONT_MEAS_CMD);

    // Wait for measurement completion
    usleep(45000);

    // Read pressure data
    if (i2c_read_word(i2c, SDP800_ADDR, &sensor_data.pressure) != 2) {
        fprintf(stderr, "Error: Failed to read pressure data.\n");
        return;
    }

    // Read temperature data
    if (i2c_read_word(i2c, SDP800_ADDR, &sensor_data.temperature) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data.\n");
        return;
    }

    // Verify CRC-8 for pressure data
    uint8_t crc_calc = crc8(sensor_data.pressure >> 8, sensor_data.pressure, CRC_POLYNOMICAL);
    if (crc_calc != (sensor_data.pressure >> 8) || crc_calc != sensor_data.pressure) {
        fprintf(stderr, "Error: Invalid CRC for pressure data.\n");
        return;
    }

    // Verify CRC-8 for temperature data
    crc_calc = crc8(sensor_data.temperature >> 8, sensor_data.temperature, CRC_POLYNOMICAL);
    if (crc_calc != (sensor_data.temperature >> 8) || crc_calc != sensor_data.temperature) {
        fprintf(stderr, "Error: Invalid CRC for temperature data.\n");
        return;
    }

    printf("Pressure: %d, Temperature: %d\n", sensor_data.pressure, sensor_data.temperature);
}

int main(void) {
    gpio = gpioInitialise(0);
    if (!gpio) {
        fprintf(stderr, "Error: Failed to initialize pigpio.\n");
        return 1;
    }

    i2c = i2cOpen(gpio, 1);
    if (!i2c) {
        fprintf(stderr, "Error: Failed to open I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        read_sensor();
        sleep(1);
    }

    i2cClose(i2c);
    gpioTerminate();

    return 0;
}

uint8_t crc8(uint8_t crc, uint8_t data, uint8_t polynomial) {
    uint8_t xor_val;
    crc ^= data;

    for (int i = 0; i < 8; i++) {
        xor_val = (crc >> 1) ^ (crc << 7);
        if (xor_val & 0x80) {
            xor_val ^= polynomial;
        }
        crc = xor_val;
    }

    return crc;
}

