        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        read_sensor();
        sleep(1);
    }

    i2cClose(i2c);
    gpioTerminate();

    return 0;
}

uint8_t crc8(uint8_t crc, uint8_t data, uint8_t polynomial) {
    uint8_t xor_val;
    crc ^= data;

    for (int i = 0; i < 8; i++) {
        xor_val = (crc >> 1) ^ (crc << 7);
        if (xor_val & 0x80) {
            xor_val ^= polynomial;
        }
        crc = xor_val;
    }

    return crc;
}
