#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <gpiod.hpp>

#define TEMP_FILE "/sys/bus/w1/devices/28-0x5b006a0000ef/temperature"
#define RELAY_GPIO 17
#define PWM_GPIO 18

float setpoint, Ki, Kd, Kp;
float prev_error, integral;

float read_temperature() {
    FILE *fp;
    char filename[256];
    sprintf(filename, "%s/temperature", TEMP_FILE);
    fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        exit(1);
    }
    char raw_temp[12];
    fgets(raw_temp, sizeof(raw_temp), fp);
    raw_temp[strcspn(raw_temp, "\n")] = 0;
    float temp = atof(raw_temp);
    fclose(fp);
    return temp;
}

float pid_control(float measured_temp) {
    float error = setpoint - measured_temp;
    integral += error;
    float derivative = (error - prev_error) / 5.0;
    float output = Kp * error + Ki * integral + Kd * derivative;
    prev_error = error;
    return output;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    gpiod_context ctx = gpiod_new();
    gpiod_chip chip = gpiod_chip_open(ctx, "GPIO18");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip.\n");
        return 1;
    }

    gpiod_chip_export(chip, RELAY_GPIO, gpiod_export_type_out);
    gpiod_chip_export(chip, PWM_GPIO, gpiod_export_type_out);

    gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_GPIO);
    gpiod_line *pwm = gpiod_chip_get_line(chip, PWM_GPIO);

    if (!relay || !pwm) {
        fprintf(stderr, "Error: Could not get GPIO lines.\n");
        gpiod_chip_unexport(chip, RELAY_GPIO);
        gpiod_chip_unexport(chip, PWM_GPIO);
        gpiod_free(ctx);
        return 1;
    }

    gpiod_line_direction_set(relay, 0);
    gpiod_line_direction_set(pwm, 0);

    FILE *log_file = fopen("greenhouse.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpiod_chip_unexport(chip, RELAY_GPIO);
        gpiod_chip_unexport(chip, PWM_GPIO);
        gpiod_free(ctx);
        return 1;
    }

    pid_t pid = pid_t(0);
    pid_t cpid;
    float avg_temp = 0;
    int count = 0;

    while ((cpid = wait(&pid)) > 0) {}

    while (1) {
        float measured_temp = read_temperature();
        float pwm_output = pid_control(measured_temp);

        avg_temp = (avg_temp * count + measured_temp) / (count + 1);
        count++;

        gpiod_line_set_value(pwm, pwm_output * 100);

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f,%.2f,%.2f,%d\n", time(NULL), avg_temp, setpoint, pwm_output, gpiod_line_get_value(relay));
        fprintf(stdout, "Avg Temp: %.2f, Setpoint: %.2f, PWM: %.2f\n", avg_temp, setpoint, pwm_output);
        fflush(stdout);

        usleep(5000000);
    }

    gpiod_line_set_value(relay, 0);
    gpiod_line_set_value(pwm, 0);
    fclose(log_file);
    gpiod_chip_unexport(chip, RELAY_GPIO);
    gpiod_chip_unexport(chip, PWM_GPIO);
    gpiod_free(ctx);

    return 0;
}

