#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <string.h>

#define I2C_ADDR 0x38
#define RELAY_GPIO 17
#define TRIGGER_CMD 0xAC
#define CALIBRATE_CMD 0xBE
#define STATUS_BYTE_CALIBRATED 0x02
#define STATUS_BYTE_BUSY 0x01
#define MAX_RETRIES 3
#define RETRY_DELAY 10

int i2c_fd = -1;
int gpio_chip = -1;
int gpio_line = -1;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    gpio_chip = gpiod_chip_open(0, "GPIO");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, "GPIO17");
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(gpio_line, "dehumidifier_relay");
}

void cleanup_gpio() {
    gpiod_line_unref(gpio_line);
    gpiod_chip_close(gpio_chip);
}

void init_aht20() {
    uint8_t cmd[] = {CALIBRATE_CMD, 0x08, 0x00};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, cmd, 3) != 3) {
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(RETRY_DELAY / 1000);
                continue;
            }
        }
        break;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize AHT20 after %d retries\n", MAX_RETRIES);
    }
}

uint8_t read_aht20() {
    uint8_t data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read(i2c_fd, data, 6) != 6) {
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(RETRY_DELAY / 1000);
                continue;
            }
        }
        break;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read AHT20 data after %d retries\n", MAX_RETRIES);
        return 0;
    }

    if (data[0] & (STATUS_BYTE_CALIBRATED | STATUS_BYTE_BUSY)) {
        fprintf(stderr, "AHT20 not calibrated or busy\n");
        return 0;
    }

    return data[1];
}

int main() {
    init_i2c();
    init_gpio();
    init_aht20();

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    while (1) {
        uint8_t humidity = read_aht20();
        if (humidity) {
            if (humidity > 60) {
                gpiod_line_trigger(gpio_line, true);
            } else if (humidity < 55) {
                gpiod_line_trigger(gpio_line, false);
            }
        }

        printf("Timestamp: %ld.%09ld, Humidity: %d%%\n",
               ts.tv_sec, ts.tv_nsec, humidity);
        sleep(5);
    }

    cleanup_gpio();
    close(i2c_fd);

    return 0;
}

