#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "sensor_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY 10000

int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return fd;
}

void i2c_close(int fd) {
    close(fd);
}

int i2c_read(int fd, uint8_t reg, uint16_t *value, int retries) {
    int ret;
    for (int i = 0; i < retries; ++i) {
        if ((ret = ioctl(fd, I2C_SLAVE, reg)) < 0) {
            if (i < MAX_RETRIES - 1) {
                msleep(RETRY_DELAY);
                continue;
            }
            perror("Failed to communicate with I2C device");
            return -1;
        }

        if ((ret = read(fd, value, 2)) != 2) {
            perror("Failed to read from I2C device");
            return -1;
        }
        break;
    }
    return 0;
}

int check_sensor_presence(int fd) {
    uint8_t buf = 0;
    if (i2c_read(fd, 0x00, &buf, 1) < 0)
        return 0;
    return buf != 0;
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    int tmp117_fd, aht20_fd;
    uint16_t tmp_temp;
    uint8_t aht_data[9];
    int motion_state = 0;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[64];
    FILE *fp;

    gpiod_chip_init(0);
    if (gpiod_chip_get_line(gpiod_chip_get_by_label(NULL, "gpiochip4"), 17, &line) < 0) {
        fprintf(stderr, "Failed to get PIR GPIO line\n");
        return 1;
    }
    gpiod_add_line_watch(&line, GPIOD_LINE_ACTIVE_LOW,
            (gpiod_callback_fn_t)motion_callback, NULL);

    tmp117_fd = i2c_open(I2C_BUS);
    if (!check_sensor_presence(tmp117_fd)) {
        fprintf(stderr, "Warning: TMP117 sensor not found\n");
    }
    aht20_fd = i2c_open(I2C_BUS);
    if (!check_sensor_presence(aht20_fd)) {
        fprintf(stderr, "Warning: AHT20 sensor not found\n");
    }

    while (1) {
        rawtime = time(NULL);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), "%Y-%m-%d", timeinfo);

        fp = fopen(filename, "a");
        if (!fp) {
            fprintf(stderr, "Failed to open file: %s\n", filename);
            continue;
        }

        fprintf(fp, "%ld,%d,%d,%d\n", rawtime,
                (tmp_temp * 0.0078125),
                (aht_data[1] >> 3) * 100,
                motion_state);
        fclose(fp);

        tmp_temp = 0;
        if (i2c_read(tmp117_fd, 0x00, &tmp_temp, MAX_RETRIES) < 0) {
            fprintf(stderr, "Failed to read TMP117 temperature\n");
            break;
        }

        memset(aht_data, 0, sizeof(aht_data));
        if (i2c_read(aht20_fd, 0xBE, aht_data, 2) < 0) {
            fprintf(stderr, "Failed to send init command to AHT20\n");
            break;
        }
        if ((aht_data[0] & 0x80) == 0) { // Check busy bit
            if (i2c_read(aht20_fd, 0xAC, aht_data + 1, 6) < 0) {
                fprintf(stderr, "Failed to read AHT20 data\n");
                break;
            }
        } else {
            fprintf(stderr, "AHT20 sensor busy, retry later\n");
            sleep(5);
            continue;
        }

        motion_state = gpiod_line_get_value(&line);

        usleep(1000000); // Sleep for 1 second
    }

    gpiod_chip_put(&chip);
    i2c_close(tmp117_fd);
    i2c_close(aht20_fd);

    return 0;
}

static void motion_callback(struct gpiod_line *line, uint32_t flags, void *user_data) {
    motion_state = gpiod_line_get_value(line);
}

