#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>
#include <time.h>
#include <pigpio.h>

#define RED_GPIO 17
#define GREEN_GPIO 22
#define BLUE_GPIO 27

#define MAX_SAMPLES 2
#define UPDATE_INTERVAL_MS 500

static int red_gpio, green_gpio, blue_gpio;
static char prev_load[MAX_SAMPLES][3] = { {0, 0, 0} };
static char curr_load[3];
static int prev_load_idx = 0;
static int cpu_load;

void get_cpu_load(char load[]) {
    FILE *fp;
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open /proc/stat\n");
        exit(1);
    }

    fgets(load, sizeof(load), fp);
    fclose(fp);

    sscanf(load, "%*s %d %*d %*d %*d %*d %*d %*d %d.%0*d", &cpu_load, NULL);
}

void map_load_to_color(char color[]) {
    if (cpu_load < 25) {
        color[0] = 0;
        color[1] = 255;
        color[2] = 0;
    } else if (cpu_load < 75) {
        color[0] = 255;
        color[1] = 255;
        color[2] = 0;
    } else {
        color[0] = 255;
        color[1] = 0;
        color[2] = 0;
    }
}

int main(int argc, char *argv[]) {
    int rd, pi;

    if ((rd = pigpio_initialise()) < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed with code %d\n", rd);
        return 1;
    }

    pi = rd;
    red_gpio = gpioInitialise(RED_GPIO);
    if (red_gpio < 0) {
        fprintf(stderr, "Error: Failed to initialise GPIO %d\n", RED_GPIO);
        pigpio_terminate(pi);
        return 1;
    }

    green_gpio = gpioInitialise(GREEN_GPIO);
    if (green_gpio < 0) {
        fprintf(stderr, "Error: Failed to initialise GPIO %d\n", GREEN_GPIO);
        pigpio_terminate(pi);
        return 1;
    }

    blue_gpio = gpioInitialise(BLUE_GPIO);
    if (blue_gpio < 0) {
        fprintf(stderr, "Error: Failed to initialise GPIO %d\n", BLUE_GPIO);
        pigpio_terminate(pi);
        return 1;
    }

    gpioSetMode(red_gpio, PI_OUTPUT);
    gpioSetMode(green_gpio, PI_OUTPUT);
    gpioSetMode(blue_gpio, PI_OUTPUT);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        get_cpu_load(curr_load);

        if (memcmp(prev_load[prev_load_idx], curr_load, sizeof(prev_load[0])) != 0) {
            cpu_load = curr_load[8] - prev_load[prev_load_idx][8];
            prev_load[prev_load_idx++] = curr_load;
            if (prev_load_idx >= MAX_SAMPLES)
                prev_load_idx = 0;

            map_load_to_color(curr_load);
        }

        gpioWrite(red_gpio, curr_load[0]);
        gpioWrite(green_gpio, curr_load[1]);
        gpioWrite(blue_gpio, curr_load[2]);

        usleep(UPDATE_INTERVAL_MS * 1000);
    }

    cleanup();

    return 0;
}

void cleanup(int signum) {
    gpioTerminate();
    pigpio_stop();
    exit(signum == SIGINT || signum == SIGTERM ? 0 : 1);
}

