    if (ret < 0) {
        fprintf(stderr, "I2C read error: %d\n", ret);
        return -1;
    }
    return ret;
}

int i2c_write(gpio p, uint8_t reg, uint8_t val) {
    int ret;
    ret = pi_i2c_wr(p, BMP280_ADDR, reg, &val, 1);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %d\n", ret);
        return -1;
    }
    return ret;
}

int init_bmp280(struct bmp280_data *data) {
    uint8_t buf[2];

    // Verify chip ID
    if (i2c_read(GPIO_I2C_0, 0xD0, buf, 1) < 0)
        return -1;
    if (buf[0] != CHIP_ID) {
        fprintf(stderr, "Invalid chip ID\n");
        return -1;
    }

    // Read calibration data
    if (i2c_read(GPIO_I2C_0, CALIB_OFFSET, data, CALIB_LEN) < 0)
        return -1;

    // Apply Bosch 64-bit compensation formulas (implementation omitted for brevity)

    return 0;
}

int main() {
    gpio chip_select = GPIO_I2C_0;
    struct bmp280_data data;
    int udp_sockfd;
    struct sockaddr_in server_addr;
    char json[256];

    pigpio pi(chip_select);

    if (pi.init()) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set I2C bus speed
    pi.set_mode(chip_select, PiGpioI2c);
    pi.i2c_set_baud(chip_select, 400000);

    // Initialize UDP socket
    udp_sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_sockfd < 0) {
        fprintf(stderr, "Socket creation failed\n");
        pi.terminate();
        return 1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    if (inet_pton(AF_INET, UDP_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported\n");
        close(udp_sockfd);
        pi.terminate();
        return 1;
    }

    // Initialize BMP280
    if (init_bmp280(&data) < 0) {
        pi.terminate();
        close(udp_sockfd);
        return 1;
    }

    // Force mode and wait for measurement completion
    i2c_write(chip_select, FORCED_MODE, 1);
    while (i2c_read(chip_select, MEASURE_REG, NULL, 6) < 0);

    // Read temperature and pressure
    uint16_t temp_lsb, temp_msb;
    uint16_t pres_lsb, pres_msb;
    if (i2c_read(chip_select, MEASURE_REG, (uint8_t *)&temp_lsb, 2) < 0 ||
        i2c_read(chip_select, MEASURE_REG + 2, (uint8_t *)&pres_lsb, 2) < 0 ||
        i2c_read(chip_select, MEASURE_REG + 4, (uint8_t *)&pres_msb, 2) < 0) {
        fprintf(stderr, "Error reading temperature/pressure\n");
        pi.terminate();
        close(udp_sockfd);
        return 1;
    }

    // Construct JSON string
    sprintf(json, "{\"temperature\": %d, \"pressure\": %d}", temp_lsb, pres_lsb | (pres_msb << 8));

    // Send data over UDP
    if (sendto(udp_sockfd, json, strlen(json), 0, (const struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "UDP send failed\n");
    }

    // Clean up
    pi.terminate();
    close(udp_sockfd);

    return 0;
}

