#define SPI_SPEED 500000
#define FAULT_MASK 0x00040000

typedef struct {
    uint64_t timestamp;
    int16_t temperature;
    uint8_t duty_cycle;
} Reading;

Reading readings[BUFFER_SIZE];
int buffer_index = 0;

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (i != 0) printf(",");
        printf("{%lu, %d, %d}", readings[i].timestamp, readings[i].temperature, readings[i].duty_cycle);
    }
    printf("\n");
}

void fan_control(int temp) {
    uint8_t duty = 0;

    if (temp < 25) {
        duty = 0;
    } else if (temp >= 25 && temp <= 40) {
        duty = (temp - 25) * 10;
    } else if (temp >= 40 && temp <= 60) {
        duty = (temp - 40) * 50;
    } else {
        duty = 255;
    }

    gpioPWM(18, duty);
}

int main() {
    int spi_channel;
    int ret;

    gpioInitialise();
    spi_channel = spiOpen(0, SPI_SPEED);
    if (spi_channel < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    ret = gpioSetMode(18, PI_OUTPUT);
    if (ret) {
        fprintf(stderr, "Failed to set GPIO18 mode\n");
        spiClose(spi_channel);
        gpioTerminate();
        return 1;
    }

    ret = gpioPWM(18, 100);
    if (ret) {
        fprintf(stderr, "Failed to initialize PWM on GPIO18\n");
        spiClose(spi_channel);
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint32_t spi_data;
        ret = spiXfer(spi_channel, NULL, &spi_data, 4);
        if (ret) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        int16_t temp = (int16_t)((spi_data >> 16) & 0x00007FFF);
        uint32_t faults = spi_data & FAULT_MASK;

        if (faults) {
            fprintf(stderr, "MAX31855 fault detected: %02x\n", faults);
            continue;
        }

        readings[buffer_index].timestamp = time(NULL);
        readings[buffer_index].temperature = temp;
        readings[buffer_index].duty_cycle = (uint8_t)fan_control(temp);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        usleep(1000000);
    }

    gpioPWM(18, 0);
    spiClose(spi_channel);
    print_buffer();
    gpioTerminate();

    return 0;
}

