#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <wiringPiI2C.h>

#define BMP180_ADDR 0x77
#define OSS 3

int main() {
    int fd;
    gpioInit();
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    fd = wiringPiI2CSetup(0x77);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, 0xF4, 0xD0) != 1) {
        fprintf(stderr, "Failed to write calibration data check\n");
        wiringPiI2CClose(fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(2, PI_OUTPUT);
    gpioSetPullUpDown(2, 1);
    gpioSetAlertMode(2, PI_FALLING);
    gpioSetAlertFunc(2, NULL);
    gpioSetAlertMask(2, 2);

    char timestamp[20];
    FILE *log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

        int pressure, temp;
        if (wiringPiI2CReadReg16(fd, 0xF6) != 2) {
            fprintf(stderr, "Failed to read pressure data\n");
            continue;
        }
        if (wiringPiI2CReadReg16(fd, 0xF4) != 2) {
            fprintf(stderr, "Failed to read temperature data\n");
            continue;
        }

        pressure = (wiringPiI2CReadReg16(fd, 0xF6) << 8) | wiringPiI2CReadReg8(fd, 0xF7);
        temp = ((wiringPiI2CReadReg16(fd, 0xF4) << 8) | wiringPiI2CReadReg8(fd, 0xF5)) / 10.0;

        if (pressure == 0 || temp == 0) {
            fprintf(stderr, "Failed to read valid data from BMP180\n");
            continue;
        }

        float altitude = (float)pressure / 100 * (1 - pow((1 - 0.0065), (double)OSS));
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, altitude);
        fclose(log_file);
        log_file = fopen("altitude_log.txt", "a");

        fflush(log_file);
        sleep(1);
    }

    gpioTerminate();
    fclose(log_file);
    wiringPiI2CClose(fd);
    return 0;
}

