#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_ADDR 0x76
#define I2C_BUS "0x28"
#define CSV_FILE "bme280_log.csv"
#define LOG_INTERVAL 5

enum { TEMP_X, HUMIDITY_X, PRESSURE_X };

struct bme280_data {
    float temperature;
    float humidity;
    float pressure;
};

void log_data(struct bme280_data data) {
    FILE *fp;
    char timestamp[20];

    time_t t = time(NULL);
    struct tm *tm_info = localtime(&t);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fp = fopen(CSV_FILE, "a");
    if (!fp) {
        perror("Failed to open CSV file");
        return;
    }

    fprintf(fp, "%s, %.2f, %.2f, %.2f\n", timestamp, data.temperature, data.humidity, data.pressure);
    fclose(fp);
}

int read_bme280(int fd, struct bme280_data *data) {
    uint8_t buf[7];
    int ret;

    if (ioctl(fd, I2C_SLAVE, BME280_ADDR) < 0) {
        perror("Failed to acquire bus access and/or perform eof on i2c bus");
        return -1;
    }

    if (buf[TEMP_X] != 0x60) {
        fprintf(stderr, "Invalid BME280 chip ID: 0x%02X\n", buf[TEMP_X]);
        return -1;
    }

    ret = ioctl(fd, I2C_RDWR, buf);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }

    data->temperature = (buf[HUMIDITY_X] << 2 | (buf[TEMP_X] >> 4)) * 175.0 / (65535 >> 4) - 45.0;
    data->humidity = (buf[HUMIDITY_X] << 6 | (buf[HUMIDITY_X] >> 2)) * 100.0 / (65535 >> 2);
    data->pressure = (buf[PRESSURE_X] << 4 | (buf[PRESSURE_X] >> 4)) * 100.0 / (65535 >> 4);

    return 0;
}

int main() {
    int fd;
    struct bme280_data data;
    int ret;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    ioctl(fd, I2C_SLAVE, BME280_ADDR);

    if (read_bme280(fd, &data) < 0) {
        close(fd);
        return 1;
    }

    while (1) {
        log_data(data);
        sleep(LOG_INTERVAL);
    }

    close(fd);
    return 0;
}

