#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define BUFFER_SIZE (60 * 50 / 1000) // 60 seconds of data, 50 ms interval

typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int tail;
} CircularBuffer;

CircularBuffer cb;

void cbInit(CircularBuffer *cb) {
    cb->head = cb->tail = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->data[i] = 0.0;
    }
}

int cbAdd(CircularBuffer *cb, float value) {
    if ((cb->head + 1) % BUFFER_SIZE == cb->tail)
        return 0; // buffer is full

    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    return 1;
}

float cbGetAverage(CircularBuffer *cb) {
    float sum = 0.0;
    int count = 0;

    for (int i = cb->tail; i != cb->head; i = (i + 1) % BUFFER_SIZE) {
        sum += cb->data[i];
        count++;
    }

    return count > 0 ? sum / count : 0.0;
}

