    int head;
    int tail;
} CircularBuffer;

CircularBuffer cb;

void cbInit(CircularBuffer *cb) {
    cb->head = cb->tail = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->data[i] = 0.0;
    }
}

int cbAdd(CircularBuffer *cb, float value) {
    if ((cb->head + 1) % BUFFER_SIZE == cb->tail)
        return 0; // buffer is full

    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    return 1;
}

