#define TEMP_THRESHOLD_HIGH 70
#define PWM_FREQ 25000
#define DUTY_RANGE 255
#define LOG_INTERVAL 5

int main() {
    int fd_log = -1;
    gpioInit();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    fd_log = open("fan_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd_log < 0) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    while (1) {
        char temp_str[16];
        int temp;

        if (read_temperature("/sys/class/thermal/thermal_zone0/temp", temp_str, sizeof(temp_str)) != 0) {
            fprintf(stderr, "Failed to read CPU temperature\n");
            break;
        }

        temp = atoi(temp_str);

        int duty = (temp - TEMP_THRESHOLD_LOW) * (DUTY_RANGE - 1) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW);
        duty = clamp(duty, 0, DUTY_RANGE - 1);

        gpioSetMode(GPIO_FAN, PI_OUTPUT);
        gpioSetPWMfrequency(GPIO_FAN, PWM_FREQ);
        gpioSetPWMdolazy(GPIO_FAN, duty);

        time_t now = time(NULL);
        struct tm tm = *localtime(&now);

        fprintf(fd_log, "%02d:%02d:%02d, %d°C, %d%% duty\n",
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, duty);
        fflush(fd_log);

        sleep(LOG_INTERVAL);
    }

    gpioTerminate();
    close(fd_log);
    return 0;
}

