    int fd = open(path, O_RDONLY);
    if (fd < 0)
        return -1;

    if (read(fd, str, len) != len) {
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int clamp(int val, int min, int max) {
    return (val < min) ? min : (val > max) ? max : val;
}

