#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define BMP280_ADDR_DEFAULT 0x76
#define BMP280_ADDR_FALLBACK 0x77
#define I2C_BUS "i2c-1"
#define I2C_ADDR_DEFAULT "/dev/i2c-1"
#define I2C_ADDR_FALLBACK "/dev/i2c-1"
#define CHECK_I2C_ERROR(call) do { \
    int err = (call); \
    if (err < 0) { \
        fprintf(stderr, "I2C error: %s\n", strerror(errno)); \
        exit(EXIT_FAILURE); \
    } } while (0)

struct bmp280_data {
    int fd;
    int addr;
    unsigned char chip_id;
    unsigned int dig_T1, dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    float over_temp, over_pressure;
};

static int bmp280_read_reg(struct bmp280_data *data, unsigned char reg, unsigned char *val, int len) {
    if (len != 1) {
        return -EINVAL;
    }
    if (write(data->fd, &reg, 1) != 1) {
        return -EIO;
    }
    if (read(data->fd, val, len) != len) {
        return -EIO;
    }
    return 0;
}

static int bmp280_write_reg(struct bmp280_data *data, unsigned char reg, const unsigned char *val, int len) {
    if (len != 1) {
        return -EINVAL;
    }
    if (write(data->fd, &reg, 1) != 1) {
        return -EIO;
    }
    if (write(data->fd, val, len) != len) {
        return -EIO;
    }
    return 0;
}

static int bmp280_get_calibration(struct bmp280_data *data) {
    if (bmp280_read_reg(data, 0x88, &data->dig_T1, 1) ||
        bmp280_read_reg(data, 0x8A, &data->dig_T2, 1) ||
        bmp280_read_reg(data, 0x8C, &data->dig_T3, 1) ||
        bmp280_read_reg(data, 0x8E, &data->dig_P1, 1) ||
        bmp280_read_reg(data, 0x90, &data->dig_P2, 1) ||
        bmp280_read_reg(data, 0x92, &data->dig_P3, 1) ||
        bmp280_read_reg(data, 0x94, &data->dig_P4, 1) ||
        bmp280_read_reg(data, 0x96, &data->dig_P5, 1) ||
        bmp280_read_reg(data, 0x98, &data->dig_P6, 1) ||
        bmp280_read_reg(data, 0x9A, &data->dig_P7, 1) ||
        bmp280_read_reg(data, 0x9C, &data->dig_P8, 1) ||
        bmp280_read_reg(data, 0x9E, &data->dig_P9, 1)) {
        return -EIO;
    }
    return 0;
}

static float bmp280_comp_temp(int ac1, int ac2, int tm, int t1, int t2) {
    float var1, var2;
    var1 = ((tm >> 3) * (tm >> 3)) * (ac2 >> 12);
    var1 = var1 * (var1 + ((ac1 * t2) >> 12));
    var2 = t1 * ac1 >> 11;
    return ((var1 + var2) >> 4);
}

static float bmp280_comp_pres(int ac3, int b1, int b2, int mb, int mc, int md, int temp) {
    float var1, var2;
    var1 = (temp - 7.65) * (temp - 7.65);
    var1 = var1 * var1 * (343.224 / 65536);
    var2 = temp;
    var2 = (var2 * var2) >> 12;
    var1 = ((ac3 * var1) >> 11) + ((b1 * var2) >> 7);
    var1 = var1 + ((b2 * temp) >> 4);
    var2 = ((ac4 * var1) >> 13) + ((ac5 * temp) >> 3);
    var2 = (var2 >> 2) + 16384;
    if (md != 0) {
        var2 = (md / 2) * (var2 >> md);
    }
    if (mb != 0) {
        var2 = (mb >> 1) * (var2 >> (mb - 3));
    }
    if (mc != 0) {
        var2 = var2 * (1 << (mc - 11));
    }
    return (float)var2;
}

static int bmp280_read_raw(struct bmp280_data *data, unsigned char *raw_data) {
    if (bmp280_read_reg(data, 0xF7, raw_data, 6) != 6) {
        return -EIO;
    }
    return 0;
}

static int bmp280_init(struct bmp280_data *data, int addr) {
    data->addr = addr;
    data->fd = open(I2C_ADDR_DEFAULT, O_RDWR);
    if (data->fd < 0) {
        return -ENODEV;
    }
    if (ioctl(data->fd, I2C_SLAVE, addr) < 0) {
        close(data->fd);
        return -EIO;
    }

    if (bmp280_read_reg(data, 0xD0, &data->chip_id, 1) != 0) {
        close(data->fd);
        return -EIO;
    }
    if (data->chip_id != 0x58) {
        close(data->fd);
        fprintf(stderr, "BMP280 chip ID mismatch, expected 0x58, got 0x%02X\n", data->chip_id);
        return -EINVAL;
    }

    if (bmp280_get_calibration(data) != 0) {
        close(data->fd);
        return -EIO;
    }

    return 0;
}

static void bmp280_set_ctrl_meas(struct bmp280_data *data, int mode, int oversampling) {
    unsigned char buf[2];
    buf[0] = (mode & 0xF0) | ((oversampling & 0x0F) << 4);
    buf[1] = 0;
    if (bmp280_write_reg(data, 0xF4, buf, 2) != 0) {
        fprintf(stderr, "Failed to set control measurement register\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct bmp280_data data;
    FILE *fp;
    char timestamp[32];
    unsigned char raw_data[6];

    if (bmp280_init(&data, BMP280_ADDR_DEFAULT) != 0) {
        fprintf(stderr, "Failed to initialize BMP280 sensor\n");
        return EXIT_FAILURE;
    }

    if (time(&data.timestamp)) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&data.timestamp));
    }

    fp = fopen("weather_data.txt", "a");
    if (!fp) {
        perror("Failed to open weather_data.txt");
        return EXIT_FAILURE;
    }

    while (1) {
        bmp280_set_ctrl_meas(&data, 0x2C, 1); // Forced mode, x1 oversampling

        while (1) {
            if (bmp280_read_raw(&data, raw_data) != 0) {
                fprintf(stderr, "Failed to read raw data from BMP280\n");
                break;
            }

            unsigned int ac6 = (data.dig_T1 << 15) | (data.dig_T2);
            unsigned int ac7 = (data.dig_T3 << 8) | data.dig_T1;
            unsigned int ac8 = data.dig_T4;
            unsigned int ac9 = (data.dig_P1 << 8) | data.dig_P2;
            unsigned int b1 = (data.dig_P3 << 7) | (data.dig_P4 << 4) | (data.dig_P5 << 1);
            unsigned int b2 = (data.dig_P6 << 6) | (data.dig_P7 << 5) | (data.dig_P8 << 4);
            unsigned int mb = (data.dig_P9 << 7) | data.dig_P10;
            unsigned int mc = (data.dig_P11 << 0) | (data.dig_P12 << 1) | (data.dig_P13 << 2) | (data.dig_P14 << 3) | (data.dig_P15 << 4) | (data.dig_P16 << 5);
            unsigned int md = (data.dig_P17 << 8);

            float var1 = ((float)data.timestamp - (float)ac6) / 100000;
            float var2 = (var1 * var1 * var1 * ac2) >> 16;
            var2 = (var2 * var2) >> 11;
            var1 = ((float)ac3 * var1 * var1) >> 20;
            var1 = (var1 * var1) >> 10;
            var2 += ac4;
