#include <libgpiod.h>

#define BUFFER_SIZE 60
#define LED_GPIO 18
#define TEMP_SENSOR_ADDR 0x48
#define TEMP_REG 0x00

int i2c_fd = -1;
int gpio_led = -1;
gpiod_chip_reg_handler_t chip;
gpiod_chip_reg_t reg;
gpiod_context_t *ctx;

int buffer[BUFFER_SIZE];
int buffer_index = 0;
int sum = 0;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TEMP_SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_temperature() {
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    return (int16_t)((data[1] << 8) | data[0]);
}

float compute_avg() {
    return (float)sum / BUFFER_SIZE;
}

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void init_gpio() {
    if (gpiod_chip_open(&ctx, "gpiochip0") < 0) {
        log_error("Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_get_line(ctx, LED_GPIO, &reg) < 0) {
        log_error("Failed to get GPIO line\n");
        exit(EXIT_FAILURE);
    }

    gpio_led = gpiod_line_get_id(reg.line);
    if (gpiod_line_export(reg.line, "user") < 0) {
        log_error("Failed to export GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_direction(reg.line, GPIO_DIR_OUT);
}

void cleanup_gpio() {
    gpiod_line_release(reg.line);
    gpiod_chip_close(ctx);
}

void *thread_func(void *arg) {
    while (1) {
        uint16_t temp = read_temperature();
        float temp_celsius = (float)temp / 256.0;

        buffer[buffer_index] = (int)temp_celsius;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        sum = 0;

        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[i];
        }

        printf("Temperature: %.2f°C\n", compute_avg());

        if (compute_avg() > 28.0) {
            gpiod_line_trigger(reg.line, GPIO_FALLING_EDGE);
        } else {
            gpiod_line_trigger(reg.line, GPIO_RISING_EDGE);
        }

        sleep(1);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    init_i2c();
    init_gpio();

    gpiod_add_override(gpio_led, gpiod_line_from_id(gpio_led, "user"));

    pthread_t thread;
    pthread_create(&thread, NULL, thread_func, NULL);

    // Keep the main thread alive
    while (1) {
        sleep(1);
    }

    pthread_cancel(thread);
    pthread_join(thread, NULL);

    cleanup_gpio();
    close(i2c_fd);

    return 0;
}

