static const float BMP180_CALIB_AC2 = 0.0;
static const uint16_t BMP180_CALIB_AC3 = 0;
static const uint16_t BMP180_CALIB_B1 = 0;
static const uint16_t BMP180_CALIB_B2 = 0;
static const uint16_t BMP180_CALIB_MB = 0;
static const uint16_t BMP180_CALIB_MC = 0;
static const uint16_t BMP180_CALIB_MD = 0;

static FILE *log_file = NULL;
static int logging_enabled = 0;
static int last_edge_timestamp = 0;

void cleanup(int signum) {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(signum);
}

void init_bmp180_calibration(float *ac1, float *ac2, uint16_t *ac3, uint16_t *b1, uint16_t *b2, uint16_t *mb, uint16_t *mc, uint16_t *md) {
    // Replace these with actual calibration data from your BMP180 sensor
    *ac1 = BMP180_CALIB_AC1;
    *ac2 = BMP180_CALIB_AC2;
    *ac3 = BMP180_CALIB_AC3;
    *b1 = BMP180_CALIB_B1;
    *b2 = BMP180_CALIB_B2;
    *mb = BMP180_CALIB_MB;
    *mc = BMP180_CALIB_MC;
    *md = BMP180_CALIB_MD;
}

float compute_pressure(uint16_t x1, uint16_t x2) {
    float var1, var2;
    int32_t x;
    uint8_t s, c, p;

    var1 = (float)((x1 - (*ac1)) * (x1 - (*ac1))) >> 12;
    var2 = (*ac2) * var1 * var1 >> 24;
    var1 = var1 + var2;

    x = var1 + (*ac3);

    if (x > 0x80000000) {
        return (float)(x - 0x100000000) / 100.0;
    }

    if (x < -0x80000000) {
        return (float)(x + 0x100000000) / 100.0;
    }

    var1 = (*b1) * (x >> 13) * (x >> 13);
    var2 = (*mc) * var1;
    var1 = var1 + (*b2) * x;
    var2 = var1 + (*md);
    var1 = (((var2 >> 12) * (32768 + var1)) >> 16);

    if (var1 == 0) {
        return 0.0;
    }

    var1 = (float)((1048576 - x) * 100) / var1;

    if (p = (uint8_t)(var1 >> 8), p > 15) {
        p = 15;
    }

    if (c = (uint8_t)(var1 >> 4), c > 255) {
        c = 255;
    }

    if (s = (uint8_t)var1, s > 1023) {
        s = 1023;
    }

    return (float)((p << 8) | (c << 4) | (s >> 4)) / 100.0;
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    int gpio_pin = 27;
    struct timespec last_log_time;
    int ret;

    gpioInitialize();
    i2c_fd = i2c_open(BMP180_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    init_bmp180_calibration(&BMP180_CALIB_AC1, &BMP180_CALIB_AC2, &BMP180_CALIB_AC3, &BMP180_CALIB_B1, &BMP180_CALIB_B2, &BMP180_CALIB_MB, &BMP180_CALIB_MC, &BMP180_CALIB_MD);

    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &last_log_time);

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioSetPullUpDown(gpio_pin, 1);
    gpioSetAlert(gpio_pin, 1, 0);

    while (1) {
        ret = gpioWaitEdge(gpio_pin, 1, DEBOUNCE_WINDOW_MS * 1000 / 1000);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for edge\n");
            goto cleanup_and_exit;
        }

        if (timespecDiff(&last_log_time, clock_gettime(CLOCK_MONOTONIC)) > LOG_INTERVAL_SEC) {
            if (logging_enabled) {
                uint16_t x1, x2;
                float pressure;

                i2c_read_word(i2c_fd, BMP180_REG_PRESS_MSB, &x1);
                i2c_read_word(i2c_fd, BMP180_REG_PRESS_LSB, &x2);
                pressure = compute_pressure(x1, x2);

                time_t now = time(NULL);
                struct tm tm;
                localtime_r(&now, &tm);

                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm_sec, pressure);

                last_log_time = clock_gettime(CLOCK_MONOTONIC);
            }
        }

        if (gpioRead(gpio_pin) == 0) {
            logging_enabled = !logging_enabled;
        }
    }

cleanup_and_exit:
    i2c_close(i2c_fd);
    gpioTerminate();
    cleanup(SIGINT);
    cleanup(SIGTERM);
    return 0;
}

