        fprintf(stderr, "Failed to initialize pigpio library. Exiting.\n");
        return 1;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler. Exiting.\n");
        return 1;
    }

    if (signal(SIGTERM, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler. Exiting.\n");
        return 1;
    }

    temp_fd = open(temp_file, O_RDONLY);
    if (temp_fd < 0) {
        perror("Failed to open temperature file");
        return 1;
    }

    while (!stop_flag) {
        if (read(temp_fd, temp_buf, sizeof(temp_buf)) != sizeof(temp_buf)) {
            perror("Failed to read temperature file");
            close(temp_fd);
            break;
        }

        if (sscanf(temp_buf, "%f", &temp_mdegC) != 1) {
            fprintf(stderr, "Failed to parse temperature value. Skipping update.\n");
            close(temp_fd);
            continue;
        }

        printf("Temperature: %.0f m°C\n", temp_mdegC);

        int red_pwm = 255, green_pwm = 255, blue_pwm = 255;
        if (temp_mdegC < 40000) {
            red_pwm = 0;
            green_pwm = 0;
            blue_pwm = 255;
        } else if (temp_mdegC < 60000) {
            red_pwm = 0;
            green_pwm = 255;
            blue_pwm = 0;
        } else {
            red_pwm = 255;
            green_pwm = 0;
            blue_pwm = 0;
        }

        gpioSetMode(GPIO_RED, PI_OUTPUT);
        gpioSetMode(GPIO_GREEN, PI_OUTPUT);
        gpioSetMode(GPIO_BLUE, PI_OUTPUT);

        gpioPWM(GPIO_RED, red_pwm);
        gpioPWM(GPIO_GREEN, green_pwm);
        gpioPWM(GPIO_BLUE, blue_pwm);

        sleep(0.5);
    }

    gpioTerminate();
    close(temp_fd);

    return 0;
}

