#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <curl/curl.h>
#include <pigio.h>

#define DHT22_GPIO 4
#define START_SIGNAL 0
#define CHECKSUM_POS 39
#define RETRY_LIMIT 3

struct curl_slist *headers = NULL;

static void sigint_handler(int signum) {
    gpioTerminate();
    curl_easy_abort(curl);
    exit(signum);
}

static void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    gpioInitialise();
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    curl = curl_easy_init();
    if(curl) {
        headers = curl_slist_append(NULL, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    }

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    for(int i = 0; i < RETRY_LIMIT; i++) {
        // Pull data line low for at least 1ms
        gpioSet(DHT22_GPIO, START_SIGNAL);
        usleep(1000000);
        gpioSet(DHT22_GPIO, 1);

        // Read 40-bit response
        char response[41];
        int j = 0;
        for(int k = 0; k < 40; k++) {
            while(gpioGet(DHT22_GPIO) == 1);
            response[j++] = gpioGet(DHT22_GPIO);
        }

        // Validate checksum
        int checksum = response[CHECKSUM_POS];
        int calculated_checksum = 0;
        for(int k = 0; k < 39; k++) {
            calculated_checksum ^= response[k];
        }
        calculated_checksum ^= (calculated_checksum >> 4);

        if(checksum != calculated_checksum) {
            continue; // Invalid checksum, retry
        }

        break; // Valid response, exit loop
    }

    if(i == RETRY_LIMIT) {
        fprintf(stderr, "Failed to read DHT22 after %d retries.\n", RETRY_LIMIT);
        gpioTerminate();
        curl_easy_abort(curl);
        return 1;
    }

    gpioTerminate();

    // Prepare JSON payload
    char json[100];
    snprintf(json, sizeof(json), "{\"humidity\": %d, \"temperature\": %d}", response[36], response[37]);

    // Perform HTTP POST
    curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_perform(curl);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    return 0;
}

