        return EXIT_FAILURE;
    }

    headers = curl_sliststrdup(curl_slist_append(headers, "Content-Type: application/json"));
    if (!headers) {
        syslog(LOG_ERR, "Failed to allocate memory for curl headers");
        gpioTerminate();
        curl_global_cleanup();
        return EXIT_FAILURE;
    }

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, URL);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, "error");
        curl_easy_setopt(curl, CURLOPT_HEADER, 0L);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "humidity=");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        int retry = 0;
        while (retry < MAX_RETRIES) {
            uint8_t dht22_data[40];
            if (read_dht22(dht22_data, sizeof(dht22_data)) < 0) {
                retry++;
                delayMicroseconds(BACKOFF_SECONDS * 1000000);
                continue;
            }

            // Validate checksum and extract humidity value

            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, curl_slist_append(curl_slist_copy(headers), humidity_value));

            CURLCode res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
                retry++;
                delayMicroseconds(BACKOFF_SECONDS * 1000000);
                continue;
            }

            curl_slist_free_all(headers);
            curl_easy_reset(curl);
            break;
        }

        curl_easy_cleanup(curl);
    }

    gpioTerminate();
    curl_global_cleanup();

    return EXIT_SUCCESS;
}
