#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"

enum {
    STATE_OFF = 0,
    STATE_LOW = 1,
    STATE_MEDIUM = 2,
    STATE_HIGH = 3
};

int fan_state = STATE_OFF;
int max_fan_state = 0;

void read_temp() {
    int fd;
    char temp_str[16];
    long temp_value;

    fd = open(TEMP_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open temperature file");
        return;
    }

    if (read(fd, temp_str, sizeof(temp_str)) != sizeof(temp_str)) {
        close(fd);
        return;
    }

    temp_value = strtol(temp_str, NULL, 10);
    close(fd);

    // Convert millidegrees Celsius to degrees Celsius
    int temp = temp_value / 1000;

    if (temp < 45) {
        fan_state = STATE_OFF;
    } else if (temp < 55) {
        fan_state = STATE_LOW;
    } else if (temp < 65) {
        fan_state = STATE_MEDIUM;
    } else {
        fan_state = STATE_HIGH;
    }
}

void set_fan_speed() {
    int fd;

    fd = open(FAN_STATE_FILE, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open fan state file");
        return;
    }

    if (fan_state > max_fan_state) {
        fprintf(stderr, "Warning: Requested fan state (%d) exceeds max_state (%d)\n", fan_state, max_fan_state);
        fan_state = max_fan_state;
    }

    write(fd, &fan_state, sizeof(fan_state));
    close(fd);
}

void log_fan_speed_change() {
    time_t now;
    struct tm *time_struct;
    char timestamp[20];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    if (fan_state != 0) {
        fd = open(LOG_FILE, O_APPEND | O_WRONLY);
        if (fd < 0) {
            perror("Failed to open log file");
            return;
        }

        if (fprintf(fd, "%s: Fan speed changed to %d\n", timestamp, fan_state) < 0) {
            close(fd);
        }
        close(fd);
    }
}

void sigint_handler(int signum) {
    fan_state = STATE_OFF;
    log_fan_speed_change();
    _exit(0);
}

void sigterm_handler(int signum) {
    fan_state = STATE_OFF;
    log_fan_speed_change();
    _exit(0);
}

int main() {
    struct sigaction sa;
    int fd;
    long temp_value;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    fd = open(FAN_STATE_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open fan state file");
        return 1;
    }

    if (read(fd, &temp_value, sizeof(temp_value)) != sizeof(temp_value)) {
        close(fd);
        return 1;
    }

    close(fd);

    while (1) {
        read_temp();
        set_fan_speed();
        log_fan_speed_change();

        usleep(5000000); // Sleep for 5 seconds
    }

    return 0;
}

