#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define PWM_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9
#define TARGET_TEMP 50
#define MAX_TEMP 100
#define MIN_TEMP 0

float Kp = 1.0, Ki = 0.1, Kd = 0.01;
float prev_error = 0, integral = 0;
float sample_time = 1.0;
float pwm_output = 0;

int spi_fd = -1;
FILE *log_file = NULL;

void spi_init() {
    spi_fd = spiOpen(SPI_CLK, SPI_CS, SPI_DO, 500000);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device\n");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_temp() {
    uint8_t data[4];
    int bytes_read = spiRead(spi_fd, data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from SPI device\n");
        exit(EXIT_FAILURE);
    }

    uint16_t temp = (data[0] << 8) | data[1];
    int fault = (data[2] >> 6) & 0x03;

    if (fault) {
        fprintf(stderr, "Thermocouple fault: %d\n", fault);
        pwm_output = 0; // Disable heater
    }

    return temp;
}

void pid_control(float measured_temp) {
    float se = TARGET_TEMP - measured_temp;
    integral += se * sample_time;
    float de = (se - prev_error) / sample_time;
    pwm_output = Kp * se + Ki * integral + Kd * de;

    if (measured_temp > MAX_TEMP || measured_temp < MIN_TEMP) {
        pwm_output = 0; // Failsafe
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initialising pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    pwmSetMode(PWM_PIN, 1);
    pwmSetFrequency(PWM_PIN, 1000);
    pwmSetRange(PWM_PIN, 100);
}

void cleanup() {
    pwmStop(PWM_PIN);
    spiClose(spi_fd);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void log_data(float measured_temp, float pwm) {
    if (log_file == NULL) {
        log_file = fopen("heater_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            exit(EXIT_FAILURE);
        }
    }

    fprintf(log_file, "%f %f %f\n", measured_temp, pwm, pwm_output);
    fflush(log_file);
}

void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    spi_init();
    setup_gpio();

    while (1) {
        float measured_temp = read_temp();
        pid_control(measured_temp);
        pwmSetDutyCycle(PWM_PIN, pwm_output);
        log_data(measured_temp, pwm_output);
        usleep(sample_time * 1000000 - get_system_time() % (sample_time * 1000000));
    }

    return 0;
}

