#define GPIO_FAN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define SAMPLE_INTERVAL 5
#define MIN_TEMP 40
#define MAX_TEMP 70

int main() {
    int fd_temp;
    char temp_str[12];
    double cpu_temp;
    float duty_cycle;
    time_t now;
    struct tm *time_struct;
    int gpio_status;

    pigpio *gpio;

    if ((gpio = pigpio_initialise()) == NULL) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpio_request(GPIO_FAN, PI_OUTPUT, &gpio_status) < 0) {
        fprintf(stderr, "Failed to request GPIO %d\n", GPIO_FAN);
        pigpio_terminate(gpio);
        return 1;
    }

    if (set_PWM_frequency(GPIO_FAN, 25000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_FAN);
        gpio_terminate(gpio_status);
        pigpio_terminate(gpio);
        return 1;
    }

    if (pio_set_mode(GPIO_FAN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_FAN);
        gpio_terminate(gpio_status);
        pigpio_terminate(gpio);
        return 1;
    }

    if (fd_temp = open(TEMP_FILE, O_RDONLY) < 0) {
        fprintf(stderr, "Failed to open temperature file\n");
        gpio_terminate(gpio_status);
        pigpio_terminate(gpio);
        return 1;
    }

    if (read(fd_temp, temp_str, sizeof(temp_str)) != sizeof(temp_str)) {
        fprintf(stderr, "Failed to read temperature\n");
        close(fd_temp);
        gpio_terminate(gpio_status);
        pigpio_terminate(gpio);
        return 1;
    }

    cpu_temp = atoi(temp_str) / 1000.0;
    duty_cycle = map_value(cpu_temp, MIN_TEMP, MAX_TEMP, 0.0, 100.0);
    set_PWM_dutycycle(GPIO_FAN, (long)duty_cycle * 1000000);

    if ((fp_log = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd_temp);
        gpio_terminate(gpio_status);
        pigpio_terminate(gpio);
        return 1;
    }

    fprintf(fp_log, "Timestamp,Temperature (°C),Duty Cycle (%)\n");

    while (1) {
        now = time(NULL);
        time_struct = localtime(&now);
        fprintf(fp_log, "%ld,%.2f,%.2f\n", (long)(time_struct->tm_sec), cpu_temp, duty_cycle);
        fflush(fp_log);

        cpu_temp = atoi(temp_str) / 1000.0;
        duty_cycle = map_value(cpu_temp, MIN_TEMP, MAX_TEMP, 0.0, 100.0);
        set_PWM_dutycycle(GPIO_FAN, (long)duty_cycle * 1000000);

        usleep(SAMPLE_INTERVAL * 1000000);
    }

    fclose(fp_log);
    gpio_terminate(gpio_status);
    pigpio_terminate(gpio);
    close(fd_temp);

    return 0;
}

float map_value(float x, float in_min, float in_max, float out_min, float out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

