#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define CHANNEL_A GPIO_PIN 17
#define CHANNEL_B GPIO_PIN 18
#define PULSES_PER_REVOLUTION 360

enum encoder_state {
    IDLE,
    A_RISING,
    A_FALLING,
    B_RISING,
    B_FALLING
};

enum encoder_state state = IDLE;
unsigned int count = 0;
float angle = 0.0;

void encoder_callback(int pin, pigpio_callback_data_t *d) {
    static int last_a = 0, last_b = 0;
    int a = pin == CHANNEL_A ? gpioGetLevel(CHANNEL_A) : last_a;
    int b = pin == CHANNEL_B ? gpioGetLevel(CHANNEL_B) : last_b;

    if (a != last_a || b != last_b) {
        last_a = a;
        last_b = b;

        if (a && !b) {
            state = A_RISING;
        } else if (!a && b) {
            state = B_RISING;
        } else if (!a && !b) {
            state = IDLE;
        } else {
            state = A_FALLING;
        }

        switch (state) {
            case A_RISING:
                count++;
                break;
            case B_RISING:
                if (count % 2) count++;
                break;
            case A_FALLING:
                if (count % 2) count++;
                break;
            case B_FALLING:
                count--;
                break;
            default:
                break;
        }

        angle = (float)count / PULSES_PER_REVOLUTION * 360.0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(CHANNEL_A, PI_OUTPUT) < 0 || gpioSetMode(CHANNEL_B, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(CHANNEL_A, 1);
    gpioSetPullUpDown(CHANNEL_B, 1);

    if (gpioSetMode(CHANNEL_A, PI_INPUT) < 0 || gpioSetMode(CHANNEL_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for input\n");
        gpioTerminate();
        return 1;
    }

    gpioSetCallback(CHANNEL_A, encoder_callback);
    gpioSetCallback(CHANNEL_B, encoder_callback);

    FILE *fp = fopen("encoder_log.txt", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open encoder_log.txt\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        fprintf(fp, "%ld: Angle = %.2f degrees\n", (long)now, angle);
        usleep(100000); // 100ms delay
    }

    gpioTerminate();
    fclose(fp);
    return 0;
}

