#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds

int i2c_fd;
int gpiofd;
FILE *log_file;

void log_reading(uint16_t red, uint16_t ir) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    fprintf(log_file, "%s, %u, %u\n", timestamp, red, ir);
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    struct gpiod_chip_data chip_data;
    int r;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus for I2C communication");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("adpd144ri_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    if (gpiod_chip_open(&chip, "GPIO17") < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    line = gpiod_chip_get_line(&chip, "GPIO17");
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(&chip);
        close(i2c_fd);
        return 1;
    }

    gpiod_chip_enable_line(line, 1);

    while (1) {
        uint8_t data[2];
        r = read(i2c_fd, data, 2);
        if (r != 2) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        uint16_t red = (data[1] << 8) | data[0];
        uint16_t ir = (data[3] << 8) | data[2];

        log_reading(red, ir);

        if (ir > IR_THRESHOLD) {
            gpiod_line_trigger(line, 1);
        } else {
            gpiod_line_trigger(line, 0);
        }

        usleep(SAMPLE_INTERVAL);
    }

    gpiod_line_trigger(line, 0);
    gpiod_chip_close(&chip);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

