#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define INTERVAL_SECONDS 1

static int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

void sigint_handler(int signum) {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
    exit(0);
}

void setup_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "RPM,Timestamp\n");
    fflush(log_file);
}

void cleanup_logging() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void *pulse_counter_thread(void *arg) {
    setup_logging();
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pthread_mutex_unlock(&pulse_Mutex);

        double rpm = pulses * 60.0 / INTERVAL_SECONDS;
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(log_file, "%.2f,%s\n", rpm, timestamp);

        pulse_count = 0;
        usleep(INTERVAL_SECONDS * 1000000);
    }
    cleanup_logging();
    return NULL;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        perror("pigpio initialization failed");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    if (gpioSetAlertFunc(GPIO_PIN, PI_RISING_EDGE, pulse_handler) < 0) {
        perror("pigpio ISR registration failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, pulse_counter_thread, NULL) != 0) {
        perror("pthread creation failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    gpioTerminate();
    return 0;
}

void pulse_handler(int pin, uint pulse_time_us, uint edge, void *user_data) {
    pthread_mutex_lock(&pulse_Mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_Mutex);
}

