#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define OUT_GPIO 17
#define GAIN_GPIO 18
#define SAMPLE_INTERVAL_US (10000)

static int out_gpio_state = 0;
static struct gpiod_chip *chip;
static struct gpiod_line *out_line;
static struct gpiod_line *gain_line;

static void set_gain_low(void) {
    if (out_gpio_state) {
        gpiod_line_set_value(gain_line, 0);
        out_gpio_state = 0;
    }
}

static void sample_callback(const struct gpiod_line *line, uint64_t ts, uint32_t value, void *user_data) {
    if (line == out_line) {
        static FILE *log_file = NULL;
        char timestamp[20];
        time_t t;
        struct tm *tm;

        time(&t);
        tm = localtime(&t);
        strftime(timestamp, sizeof(timestamp), "%F %T", tm);

        if (!log_file) {
            log_file = fopen("audio_log.txt", "w");
            if (!log_file) {
                fprintf(stderr, "Failed to open audio_log.txt\n");
                exit(EXIT_FAILURE);
            }
        }

        fprintf(log_file, "%s 1\n", timestamp);
        fflush(log_file);
    }
}

int main(void) {
    int ret;
    char *err;

    printf("Starting audio peak detection...\n");

    ret = gpiod_new(&chip);
    if (ret) {
        fprintf(stderr, "Failed to create gpiod instance: %s\n", err);
        return EXIT_FAILURE;
    }

    ret = gpiod_chip_add_override(chip, "OUT", OUT_GPIO, gpiod_line_override_create("OUT", OUT_GPIO, GPIOD_LINE_INACTIVE, 0));
    if (ret) {
        fprintf(stderr, "Failed to add OUT line: %s\n", err);
        goto out;
    }
    out_line = gpiod_chip_get_line(chip, "OUT");

    ret = gpiod_chip_add_override(chip, "GAIN", GAIN_GPIO, gpiod_line_override_create("GAIN", GAIN_GPIO, GPIOD_LINE_OUTPUT_ACTIVE_LOW, 0));
    if (ret) {
        fprintf(stderr, "Failed to add GAIN line: %s\n", err);
        goto out;
    }
    gain_line = gpiod_chip_get_line(chip, "GAIN");

    ret = gpiod_line_export(out_line, &err);
    if (ret) {
        fprintf(stderr, "Failed to export OUT line: %s\n", err);
        goto out;
    }
    ret = gpiod_line_export(gain_line, &err);
    if (ret) {
        fprintf(stderr, "Failed to export GAIN line: %s\n", err);
        goto out;
    }

    set_gain_low();

    ret = gpiod_add_callback(out_line, GPIOD_LINE_RISING, sample_callback, NULL);
    if (ret) {
        fprintf(stderr, "Failed to add callback for OUT line: %s\n", err);
        goto out;
    }

    while (1) {
        usleep(SAMPLE_INTERVAL_US);
        set_gain_low();
    }

out:
    gpiod_line_unregister(out_line);
    gpiod_line_unregister(gain_line);
    gpiod_chip_free(chip);

    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

