#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <unistd.h>

#define SENSOR_ADDR 0x36
#define START_CMD  0x3608
#define CRC_POLY  0x31
#define CRC_INIT  0xFF

int i2c_fd;
int log_fd;

void crc8(unsigned char *data, int len, unsigned char *crc);
int i2c_read(int fd, unsigned char *buf, int len);

int main() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    i2c_fd = i2cOpen(1, SENSOR_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    log_fd = open("flow_log.csv", O_APPEND | O_WRONLY);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    unsigned char cmd[3] = {START_CMD >> 8, START_CMD & 0xFF, 0};
    if (gpioI2CWrite(i2c_fd, cmd, 3) != 3) {
        fprintf(stderr, "Failed to send start command to sensor.\n");
        close(log_fd);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        unsigned char raw_flow[3];
        if (i2c_read(i2c_fd, raw_flow, 3) != 3) {
            fprintf(stderr, "Failed to read from sensor.\n");
            continue;
        }

        unsigned char crc;
        crc8(raw_flow, 2, &crc);
        if (crc != raw_flow[2]) {
            fprintf(stderr, "CRC check failed. Skipping reading.\n");
            continue;
        }

        int16_t flow_value = (int16_t)(raw_flow[0] << 8 | raw_flow[1]);
        double flow_rate_ul_min = (double)flow_value / 1000.0;

        fprintf(log_fd, "%s,%f\n", timestamp, flow_rate_ul_min);
        fflush(log_fd);

        sleep(1);
    }

    close(log_fd);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

void crc8(unsigned char *data, int len, unsigned char *crc) {
    *crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        unsigned char bit;
        for (bit = 0; bit < 8; bit++) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ 0x31;
            } else {
                *crc <<= 1;
            }
            if ((*data >> (len - i - 1)) & 0x01) {
                *crc ^= 0x31;
            }
        }
    }
}

int i2c_read(int fd, unsigned char *buf, int len) {
    return read(fd, buf, len);
}

