#define SENSOR_ADDR 0x70
#define REG_START 0x00
#define TVOC_BYTES (REG_START + 1)
#define eCO2_BYTES (REG_START + 5)
#define I2C_BUS 1

int main() {
    gpioInitialise();
    pigpio_initialise();

    int fd = gpioI2COpen(I2C_BUS, SENSOR_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        goto exit_cleanup;
    }

    char filename[] = "air_quality_log.csv";
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", filename);
        gpioI2CClose(fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t state[7];
        int r = gpioI2CGet(fd, REG_START, state, 7);
        if (r < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        uint16_t tvoc = (state[TVOC_BYTES] << 8) | state[TVOC_BYTES + 1];
        uint16_t eCO2 = (state[eCO2_BYTES] << 8) | state[eCO2_BYTES + 1];

        double iaq = clamp(100 - (tvoc / 10.0) - ((eCO2 - 400) / 50.0), 0, 100);

        time_t t = time(NULL);
        fprintf(fp, "%ld,%d,%d\n", t, (int)iaq, tvoc, eCO2);
        fprintf(stdout, "IAQ: %d, TVOC: %d ppb, eCO2: %d ppm\n", (int)iaq, tvoc, eCO2);

        sleep(5);
    }

exit_cleanup:
    gpioI2CClose(fd);
    fclose(fp);
    pigpio_terminate();
    gpioTerminate();

    return EXIT_SUCCESS;
}

// Clamp value between min and max
static inline int clamp(int val, int min, int max) {
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

