#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TOUCH_DURATION_SECONDS 5
#define POLL_INTERVAL_MS 100

struct timespec last_touch_time;
int touch_duration = 0;
int touch_detected = 0;

static int touch_callback(const struct gpiod_chip *chip, const struct gpiod_line *line, uint32_t events) {
    if (events & (1 << GPIOD_LINE_REQUESTS_INPUT)) {
        if (gpiod_get_value(line) == 1) {
            touch_detected = 1;
            last_touch_time = clock_gettime(CLOCK_MONOTONIC);
            touch_duration = 0;
        } else if (touch_detected) {
            touch_duration++;
            if (touch_duration >= TOUCH_DURATION_SECONDS * 1000) {
                printf("Intrusion Alert!\n");
                touch_detected = 0;
                touch_duration = 0;
            }
        }
    }
    return 0;
}

static void sigint_handler(int signum) {
    gpiod_line_disable_callback(line, touch_callback);
    gpiod_chip_drain_del(chip);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
