#include <errno.h>
#include <gpiod.h>
#include <alsa/asoundlib.h>

#define SAMPLE_RATE 48000
#define CHANNELS 1
#define BUFFER_SIZE (SAMPLE_RATE * 2)
#define FILENAME "audio_capture.pcm"

struct audio_data {
    int16_t samples[BUFFER_SIZE];
    ssize_t read_index;
};

static int setup_gpio(struct gpiod_chip *chip) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, "GPIO17");
    if (!line) {
        fprintf(stderr, "Failed to get GPIO17 line\n");
        return -1;
    }

    int ret = gpiod_line_export(line, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO17\n");
        return ret;
    }

    ret = gpiod_line_direction_set(line, GPIO_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO17 direction\n");
        return ret;
    }

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO17 value\n");
        return ret;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip) {
    gpiod_line_free(gpiod_chip_get_line(chip, "GPIO17"));
    gpiod_chip_unexport(chip);
}

static int init_alsa() {
    snd_pcm_t *handle;
    int ret;

    ret = snd_pcm_open(&handle, "dmix", SND_PCM_STREAM_CAPTURE, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to open ALSA PCM device: %s\n", snd_strerror(ret));
        return ret;
    }

    snd_pcm_hw_params_t *params;
    ret = snd_pcm_hw_params_malloc(handle);
    if (ret < 0) {
        fprintf(stderr, "Failed to allocate hardware parameters: %s\n", snd_strerror(ret));
        snd_pcm_close(handle);
        return ret;
    }

    ret = snd_pcm_hw_params_any(handle, params);
    if (ret < 0) {
        fprintf(stderr, "Failed to get default hardware parameters: %s\n", snd_strerror(ret));
        snd_pcm_hw_params_free(params);
        snd_pcm_close(handle);
        return ret;
    }

    snd_pcm_hw_params_set_access(params, handle, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_hw_params_set_format(params, handle, SND_PCM_FORMAT_S16_LE);
    snd_pcm_hw_params_set_rate_near(params, handle, SAMPLE_RATE, 0);
    snd_pcm_hw_params_set_channels(params, handle, CHANNELS);
    snd_pcm_hw_params_set_buffer_size_near(params, handle, BUFFER_SIZE);

    ret = snd_pcm_hw_params(handle, params);
    if (ret < 0) {
        fprintf(stderr, "Failed to set hardware parameters: %s\n", snd_strerror(ret));
        snd_pcm_hw_params_free(params);
        snd_pcm_close(handle);
        return ret;
    }

    snd_pcm_hw_params_free(params);

    return 0;
}

static void cleanup_alsa(snd_pcm_t *handle) {
    snd_pcm_close(handle);
}

static ssize_t read_alsa(struct audio_data *data, void *buffer, size_t size) {
    return snd_pcm_readi(data->handle, buffer, size);
}

static int write_pcm_file(const struct audio_data *data, const void *buffer, size_t size) {
    int fd = open(FILENAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("Failed to open PCM file");
        return -1;
    }

    ssize_t written = write(fd, buffer, size);
    if (written != size) {
        perror("Failed to write to PCM file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    struct gpiod_chip chip;
    gpiod_chip_init(&chip);
    if (setup_gpio(&chip) < 0) {
        return EXIT_FAILURE;
    }

    snd_pcm_t *handle = NULL;
    if (init_alsa() < 0) {
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    struct audio_data data;
    data.read_index = 0;
    data.samples = malloc(sizeof(data.samples));
    if (!data.samples) {
        cleanup_alsa(handle);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    if (snd_pcm_open_nomem(&handle, "dmix", SND_PCM_STREAM_CAPTURE, 0) < 0) {
        free(data.samples);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_malloc(&handle) < 0) {
        snd_pcm_close(handle);
        free(data.samples);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_any(handle, NULL) < 0) {
        snd_pcm_hw_params_free(handle);
        free(data.samples);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_set_access(handle, SND_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        snd_pcm_hw_params_free(handle);
        free(data.samples);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_set_format(handle, SND_PCM_FORMAT_S16_LE) < 0) {
        snd_pcm_hw_params_free(handle);
        free(data.samples);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_set_rate(handle, handle, SAMPLE_RATE, 0) < 0) {
        snd_pcm_hw_params_free(handle);
        free(data.samples);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_set_channels(handle, CHANNELS) < 0) {
        snd_pcm_hw_params_free(handle);
        free(data.samples);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_set_buffer_size(handle, BUFFER_SIZE) < 0) {
        snd_pcm_hw_params_free(handle);
        free(data.samples);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params(handle, NULL) < 0) {
        snd_pcm_hw_params_free(handle);
        free(data.samples);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    snd_pcm_hw_params_free(handle);

    data.samples = realloc(data.samples, BUFFER_SIZE * sizeof(int16_t));
    if (!data.samples) {
        cleanup_alsa(handle);
        cleanup_gpio(&chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int bytes_read = read_alsa(&data, data.samples + data.read_index * 2, BUFFER_SIZE * 2);
        if (bytes_read < 0) {
            break;
        }

        if (bytes_read % 3 != 0) {
            fprintf(stderr, "Invalid I2S frame size: %d\n", bytes_read);
            break;
        }

        uint32_t sample = (uint32_t)data.samples[data.read_index * 2] << 8 | data.samples[data.read_index * 2 + 1];
        data.samples[data.read_index] = (int16_t)(sample >> 8);
        data.read_index = (data.read_index + 1) % BUFFER_SIZE;

        if (write_pcm_file(&data, data.samples, BUFFER_SIZE * sizeof(int16_t)) < 0) {
            break;
        }
    }

    free(data.samples);
    cleanup_alsa(handle);
    cleanup_gpio(&chip);

    return EXIT_SUCCESS;
}

