#include <signal.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define SENSOR_GPIO 4
#define DEBOUNCE_DELAY 50000 // 50 ms
#define POLL_DELAY 50000 // 50 ms
#define PWM_FREQ 100
#define MAX_DUTY_CYCLE 80

int fan_duty = 0;
int flame_state = 0;
int last_flame_state = 0;
int flame_duration = 0;
int flame_timeout = 0;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(signum == SIGINT ? 0 : 1);
}

void setup_logging() {
    FILE *log_file = fopen("flame_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        exit(1);
    }
    fprintf(log_file, "Timestamp,Event\n");
    fflush(log_file);
}

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm tm_struct;
    localtime_r(&now, &tm_struct);

    fprintf(stdout, "%04d-%02d-%02d %02d:%02d:%02d, %s\n",
            1900 + tm_struct.tm_year, tm_struct.tm_mon + 1, tm_struct.tm_mday,
            tm_struct.tm_hour, tm_struct.tm_min, tm_struct.tm_sec, event);
    fprintf(stdout, "\n");

    fputs(sprintf(
        "%04d-%02d-%02d %02d:%02d:%02d, %s\n",
        1900 + tm_struct.tm_year, tm_struct.tm_mon + 1, tm_struct.tm_mday,
        tm_struct.tm_hour, tm_struct.tm_min, tm_struct.tm_sec, event).c_str(),
        log_file);
    fflush(log_file);
}

void setup_pwm() {
    if (gpioInitialise() < 0) {
        perror("pigpio initialization failed");
        exit(1);
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    const int pwm_value = gpioPWM(FAN_GPIO, PWM_FREQ, 0, MAX_DUTY_CYCLE);
    if (pwm_value < 0) {
        perror("Failed to set PWM");
        gpioTerminate();
        exit(1);
    }
}

void setup_sensor() {
    if (gpioInitialise() < 0) {
        perror("pigpio initialization failed");
        exit(1);
    }

    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    const int pullup = gpioSetPullUpDown(SENSOR_GPIO, PI_UP);
    if (pullup < 0) {
        perror("Failed to set pull-up resistor");
        gpioTerminate();
        exit(1);
    }
}

void poll_sensor() {
    int sensor_state;
    do {
        sensor_state = gpioRead(SENSOR_GPIO);
        if (sensor_state < 0) {
            perror("Failed to read sensor");
            break;
        }

        if (sensor_state != last_flame_state) {
            flame_duration++;
            last_flame_state = sensor_state;
        }

        if (sensor_state == 0 && flame_timeout < 5 * DEBOUNCE_DELAY) {
            flame_timeout++;
        } else {
            flame_timeout = 0;
        }

        if (sensor_state == 0 && flame_timeout >= 5 * DEBOUNCE_DELAY) {
            if (flame_state != 1) {
                flame_state = 1;
                log_event("Flame detected");
            }
        } else {
            if (flame_state == 1) {
                flame_state = 0;
                log_event("Flame ended");
            }
        }

    } while (sensor_state != last_flame_state);
}

void update_fan_duty() {
    if (flame_state == 1) {
        fan_duty = (int)(100.0 * exp(-flame_duration / 100.0) + 0.5);
        gpioPWM(FAN_GPIO, PWM_FREQ, 0, fan_duty);
    } else {
        gpioPWM(FAN_GPIO, PWM_FREQ, 0, 0);
    }
}

int main(int argc, char *argv[]) {
    setup_logging();
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_pwm();
    setup_sensor();

    while (1) {
        poll_sensor();
        update_fan_duty();
        usleep(POLL_DELAY);
    }

    gpioTerminate();
    return 0;
}
