#include <pigio.h>

#define SPI_CHANNEL 0
#define CE0_GPIO 8
#define TRIG_GPIO 23
#define DR_GPIO 24
#define FRAME_SIZE 32768
#define START_FREQ 77000000
#define END_FREQ 79000000
#define NUM_CHIRPS 64
#define NUM_SAMPLES 256
#define FRAME_PERIOD_MS 100

typedef struct {
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_ms;
} Config;

int main() {
    int spi_fd;
    int ret;
    gpioInit();
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    spi_fd = spiOpen(SPI_CHANNEL, 1000000);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CE0_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CE0_GPIO as output\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TRIG_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG_GPIO as input\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(DR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set DR_GPIO as input\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(TRIG_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(DR_GPIO, PI_PUD_UP);

    Config config = {START_FREQ, END_FREQ, NUM_CHIRPS, NUM_SAMPLES, FRAME_PERIOD_MS};

    FILE *fp = fopen("radar_data.bin", "ab");
    if (!fp) {
        fprintf(stderr, "Failed to open binary log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t header[16] = {0x44, 0x41, 0x52, 0x44, 0x00, 0x00, 0x00, 0x00,
                           0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (fwrite(header, 1, 16, fp) != 16) {
        fprintf(stderr, "Failed to write header to file\n");
        fclose(fp);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    uint64_t timestamp = time(NULL);
    if (fwrite(&timestamp, sizeof(uint64_t), 1, fp) != 1) {
        fprintf(stderr, "Failed to write timestamp to file\n");
        fclose(fp);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    uint32_t frame_num = 0;
    while (1) {
        gpioWrite(CE0_GPIO, 0);
        gpioWrite(TRIG_GPIO, 1);
        while (gpioRead(DR_GPIO) == 0);
        gpioWrite(TRIG_GPIO, 0);

        uint8_t buffer[FRAME_SIZE];
        ret = spiTransfer(spi_fd, buffer, FRAME_SIZE);
        if (ret != FRAME_SIZE) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        uint64_t frame_timestamp = time(NULL);
        fwrite(&frame_timestamp, sizeof(uint64_t), 1, fp);
        fwrite(&frame_num, sizeof(uint32_t), 1, fp);
        frame_num++;
    }

    fclose(fp);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

