#include <libgpiod.h>

#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL (100 * 1000) // 100 milliseconds

int flame_state = 0;
int previous_state = 0;
FILE *log_file = NULL;

void log_state(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s: %s\n", timestamp, message);
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_unrequest_params(chip, params);
        fclose(log_file);
        exit(0);
    }
}

int main() {
    struct gpiod_chipchip *chip;
    struct gpiod_chip_params params;
    struct gpiod_request *request;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    if (gpiod_request_open(&chip, "GPIO20") < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO pin
    memset(&params, 0, sizeof(params));
    params.consumer_id = "flame_sensor";
    params.direction = GPIO_DIR_IN;
    params.flags = 0;
    if (gpiod_request_add(chip, &params, &request) < 0) {
        fprintf(stderr, "Failed to request GPIO pin\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_request_free(request);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int current_state = gpiod_request_get_value(request);
        if (current_state != previous_state) {
            if (current_state) {
                log_state("Flame detected");
            } else {
                log_state("Flame cleared");
            }
            previous_state = current_state;
        }

        usleep(POLL_INTERVAL);
    }

    // Clean up
    gpiod_request_free(request);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

