#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define CONVERSION_TIME 100
#define FULL_SCALE_AUTO 0x00

static pigio_handle_t *bus_handle;
static FILE *log_file;

void cleanup() {
    gpioTerminate();
    close(fileno(log_file));
}

void sigint_handler(int signum) {
    gpioCancelAI();
    cleanup();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    bus_handle = pigpio_open(0, 0);
    if (!bus_handle) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    log_file = fopen("light_data.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    if (pigpio_i2c_init(bus_handle, 1) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    if (pigpio_i2c_open(bus_handle, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Failed to open OPT3001 sensor.\n");
        gpioTerminate();
        return 1;
    }

    if (pigpio_i2c_write_read(bus_handle, 0x10, NULL, 0, &REG_RESULT, 1) < 0) {
        fprintf(stderr, "Failed to write to OPT3001 register.\n");
        gpioTerminate();
        return 1;
    }

    uint16_t raw_value = (pigpio_i2c_read(bus_handle, &REG_RESULT, 1)[0] << 8) | pigpio_i2c_read(bus_handle, &REG_RESULT, 1)[1];

    int exponent = (raw_value >> 12) & 0x0F;
    int mantissa = raw_value & 0x0FFF;
    double lux = 0.01 * (1 << exponent) * mantissa;

    time_t now_time = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&now_time));

    fprintf(log_file, "%s, Lux: %.3f\n", timestamp, lux);

    while (1) {
        if (pigpio_i2c_write_read(bus_handle, 0x10, NULL, 0, &REG_RESULT, 1) < 0) {
            fprintf(stderr, "Failed to read from OPT3001 register.\n");
            break;
        }

        raw_value = (pigpio_i2c_read(bus_handle, &REG_RESULT, 1)[0] << 8) | pigpio_i2c_read(bus_handle, &REG_RESULT, 1)[1];

        exponent = (raw_value >> 12) & 0x0F;
        mantissa = raw_value & 0x0FFF;
        lux = 0.01 * (1 << exponent) * mantissa;

        time_t now_time = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&now_time));

        fprintf(log_file, "%s, Lux: %.3f\n", timestamp, lux);

        sleep(1);
    }

    gpioTerminate();
    cleanup();
    return 0;
}

