#include <signal.h>
#include <unistd.h>

#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

static volatile sig_atomic_t got_sigint = 0;

static void sigint_handler(int signum)
{
    got_sigint = 1;
}

static void cleanup(int signum)
{
    gpioTerminate();
    exit(signum);
}

int main()
{
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    if (gpioSetMode(LEFT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to output.\n", LEFT_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CENTER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to output.\n", CENTER_PIN);
        gpioTerminate();
        return 1;
