    if (gpioSetMode(RIGHT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to output.\n", RIGHT_PIN);
        gpioTerminate();
        return 1;
    }

    while (!got_sigint) {
        gpioWrite(LEFT_PIN, 0);
        gpioWrite(CENTER_PIN, 0);
        gpioWrite(RIGHT_PIN, 0);

