#define TTP226_PINS {2, 3, 4, 5, 6, 7, 8, 9}
#define NUM_CHANNELS (sizeof(TTP226_PINS) / sizeof(TTP226_PINS[0]))
#define CHECK_ERROR(call) \
    do { \
        const int err = (call); \
        if (err) { \
            fprintf(stderr, "Error: %s\n", gpiod_strerror(err)); \
            goto err_release; \
        } \
    } while (0)

static gpiod_chip *chip;
static gpiod_line *lines[NUM_CHANNELS];

void sigint_handler(int signum) {
    if (chip) {
        gpiod_chip_unrequest(chip);
        chip = NULL;
    }
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    CHECK_ERROR(gpiod_chip_open(&chip, "GPIOAUTO", 0));
    CHECK_ERROR(gpiod_chip_request_lines(chip, &lines, NUM_CHANNELS, TTP226_PINS, NULL));

    for (int i = 0; i < NUM_CHANNELS; ++i) {
        CHECK_ERROR(gpiod_line_request_read(lines[i], &i));
    }

    while (1) {
        uint32_t values[NUM_CHANNELS];
        CHECK_ERROR(gpiod_batch(&values, NUM_CHANNELS));

        for (int i = 0; i < NUM_CHANNELS; ++i) {
            printf("Channel %d: %d\n", TTP226_PINS[i], values[i]);
        }

        timespec ts = {0, 100 * 1000000};
        CHECK_ERROR(gpiod_batch_exec(chip, &ts, 1));
    }

err_release:
    for (int i = 0; i < NUM_CHANNELS; ++i) {
        if (lines[i]) {
            gpiod_line_unref(lines[i]);
            lines[i] = NULL;
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    return EXIT_SUCCESS;
}

