#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define NUM_CHANNELS 8
#define GPIO_BASE 2
#define GPIO_LIMIT 9

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static void cleanup_and_exit(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    struct timespec ts;
    gpioInitialise();
    if (gpioFailed()) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    for (int i = GPIO_BASE; i <= GPIO_LIMIT; ++i) {
        int gpio = i;
        if (gpioSetMode(gpio, PI_INPUT) < 0 || gpioSetPullUpDown(gpio, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to configure GPIO %d.\n", gpio);
            gpioTerminate();
            return 1;
        }
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, cleanup_and_exit);

    while (!sigint_received) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%06d ms", (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000));

        int states[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; ++i) {
            int gpio = GPIO_BASE + i;
            states[i] = gpioGet(gpio);
        }

        printf("[%s] ", timestamp);
        for (int i = 0; i < NUM_CHANNELS; ++i) {
            printf("CH%d=%d", i + 1, states[i]);
            if (i < NUM_CHANNELS - 1) {
                printf(" ");
            }
        }
        printf("\n");

        gpioDelay(100000);
    }

    gpioTerminate();
    return 0;
}

