    gpioSetMode(GPIO_TMAG5110_2, PI_OUTPUT);

    gpioSetPullUpDown(GPIO_TMAG5110_1, 1);
    gpioSetPullUpDown(GPIO_TMAG5110_2, 1);

    gpioWrite(GPIO_TMAG5110_1, 1);
    gpioWrite(GPIO_TMAG5110_2, 1);

    signal(SIGINT, sigint_handler);

    while (!got_sigint)
    {
        uint state1 = gpioRead(GPIO_TMAG5110_1);
        uint state2 = gpioRead(GPIO_TMAG5110_2);

        printf("Sensor 1: %s\n", state1 ? "LOW" : "HIGH");
        printf("Sensor 2: %s\n", state2 ? "LOW" : "HIGH");

        nanosleep(&period, NULL);
    }

    gpioTerminate();
    pigpio_stop();
    init();

    return 0;
}

