#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static gpiod_chip *chip;
static gpiod_line *lines[NUM_CHANNELS];
static struct timespec poll_ts;

void sigint_handler(int signum) {
    if (chip) {
        gpiod_chip_drain(chip);
        gpiod_chip_unrequest(chip);
        chip = NULL;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR | O_CLOEXEC);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip\n");
        return 1;
    }

    for (int i = 0; i < NUM_CHANNELS; ++i) {
        const char *pins[1] = {(char *)"2:3:4:17:27:22:10:9"};
        const char *params[] = {"bias-pulldown"};
        lines[i] = gpiod_chip_request_available(chip, pins, params, i + 1);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request line %d\n", i + 1);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    poll_ts.tv_sec = 0;
    poll_ts.tv_nsec = POLL_INTERVAL_MS * 1000000 / 2;

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

        for (int i = 0; i < NUM_CHANNELS; ++i) {
            uint32_t value;
            int rc = gpiod_line_read(lines[i], &value);
            if (rc) {
                fprintf(stderr, "Failed to read line %d, error %d\n", i + 1, rc);
                goto release_lines;
            }
            printf("%s,%d\n", timestamp, (value ? 1 : 0));
        }

        if (nanosleep(&poll_ts, NULL) && errno != 0) {
            fprintf(stderr, "nanosleep failed\n");
            goto release_lines;
        }
    }

release_lines:
    for (int i = 0; i < NUM_CHANNELS; ++i) {
        gpiod_line_unref(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

