#define TILT_SENSOR_GPIO 4

static volatile sig_atomic_t got_sigint = 0;

static void sigint_handler(int signum)
{
    got_sigint = 1;
}

static int poll_tilt_sensor(pigpio_t *gpio)
{
    int state;

    state = gpioRead(gpio, TILT_SENSOR_GPIO);

    if (state == LOW && last_state == HIGH) {
        log_message("Tilted", true);
    } else if (state == HIGH && last_state == LOW) {
        log_message("Not Tilted", false);
    }

    last_state = state;
    return 1;
}

int main(int argc, char **argv)
{
    pigpio_init();
    pigpio_set_mode(TILT_SENSOR_GPIO, PI_INPUT);
    pigpio_set_pull_up_down(TILT_SENSOR_GPIO, PI_PUD_UP);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

