void setup_sensor() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SI1145_ADDR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C address as output.\n");
        gpioTermination();
        exit(EXIT_FAILURE);
    }

    if (gpioWrite(SI1145_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to pull I2C address low.\n");
        gpioTermination();
        exit(EXIT_FAILURE);
    }
    delay(1);

    if (gpioWrite(SI1145_ADDR, 1) < 0) {
        fprintf(stderr, "Failed to release I2C address.\n");
        gpioTermination();
        exit(EXIT_FAILURE);
    }
    delay(1);

