        fprintf(stderr, "Failed to write to register 0x0F.\n");
        gpioTermination();
        exit(EXIT_FAILURE);
    }

    uint8_t part_id;
    if (i2cReadBytes(SI1145_ADDR, 0x00, &part_id, 1) < 0) {
        fprintf(stderr, "Failed to read PART ID.\n");
        gpioTermination();
        exit(EXIT_FAILURE);
