        fprintf(stderr, "Unexpected PART ID: 0x%02X\n", part_id);
        gpioTermination();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(SI1145_ADDR, 0x17) < 0) {
        fprintf(stderr, "Failed to write HW_KEY.\n");
        gpioTermination();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(SI1145_ADDR, CHLIST_UV | CHLIST_ALS_VIS) < 0) {
        fprintf(stderr, "Failed to write CHLIST register.\n");
        gpioTermination();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(SI1145_ADDR, 0x06) < 0) {
        fprintf(stderr, "Failed to write ALS_FORCE command.\n");
        gpioTermination();
        exit(EXIT_FAILURE);
