#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SENSOR_ADDR_1 0x36
#define SENSOR_ADDR_2 0x37
#define SCALE_FACTOR 0.036
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

int i2c_fd;
int gpio_chip;
int gpio_line;
FILE *log_file;

void crc_calc(uint8_t *data, uint8_t len, uint8_t *crc);
int i2c_read(int fd, uint16_t addr, uint8_t reg, uint8_t *buf, int len);

int main() {
    int ret;
    struct i2c_rdwr_ioctl_data rdwr_data;
    struct i2c_req req;
    gpiod_chip_config chip_config;
    gpiod_line_config line_config;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    gpio_chip = gpiod_chip_open(&ret, "GPIO17");
    if (gpio_chip == -1) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, "GPIO17");
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    line_config = gpiod_line_configuration_default();
    line_config.direction = GPIO_DIR_OUT;
    ret = gpiod_line_configure(gpio_line, &line_config);
    if (ret < 0) {
        perror("Failed to configure GPIO line");
        return -1;
    }

    log_file = fopen("flow_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    while (1) {
        uint8_t buf[9];
        int flow1, flow2;
        double avg_flow;

        // Initialize sensor 1
        req.addr = SENSOR_ADDR_1;
        req.flags = 0;
        req.len = sizeof(buf);
        rdwr_data.buf = &buf;
        rdwr_data.len = req.len;
        ioctl(i2c_fd, I2C_RDWR, &req);

        // Send start-measurement command
        write(i2c_fd, &0x3608, 2);
        usleep(100000);

        // Read 9 bytes (3 measurements: flow, temp, CRC)
        if (i2c_read(i2c_fd, 0x00, 9, buf, 9) < 0) {
            fprintf(stderr, "I2C error reading from sensor 1\n");
            continue;
        }

        crc_calc(buf, 9, buf + 8);
        if (buf[8] != buf[5] ^ buf[6] ^ buf[7]) {
            fprintf(stderr, "CRC error for sensor 1\n");
            continue;
        }

        flow1 = (buf[1] << 8) | buf[2];
        flow1 = (int16_t)flow1 * SCALE_FACTOR;

        // Initialize sensor 2
        req.addr = SENSOR_ADDR_2;
        ioctl(i2c_fd, I2C_RDWR, &req);

        // Send start-measurement command
        write(i2c_fd, &0x3608, 2);
        usleep(100000);

        // Read 9 bytes (3 measurements: flow, temp, CRC)
        if (i2c_read(i2c_fd, 0x00, 9, buf, 9) < 0) {
            fprintf(stderr, "I2C error reading from sensor 2\n");
            continue;
        }

        crc_calc(buf, 9, buf + 8);
        if (buf[8] != buf[5] ^ buf[6] ^ buf[7]) {
            fprintf(stderr, "CRC error for sensor 2\n");
            continue;
        }

        flow2 = (buf[1] << 8) | buf[2];
        flow2 = (int16_t)flow2 * SCALE_FACTOR;

        avg_flow = (flow1 + flow2) / 2;
        fprintf(log_file, "%f\n", avg_flow);

        if (avg_flow < 0.5) {
            gpiod_line_set_value(gpio_line, 1);
        } else {
            gpiod_line_set_value(gpio_line, 0);
        }

        sleep(1);
    }

    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

void crc_calc(uint8_t *data, uint8_t len, uint8_t *crc) {
    uint8_t crc_reg;
    uint8_t i;

    *crc = CRC_INIT_VALUE;
    for (i = 0; i < len; i++) {
        *crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (*crc & 0x01) {
                *crc = (*crc >> 1) ^ CRC_POLYNOMIAL;
            } else {
                *crc >>= 1;
            }
        }
    }
}

int i2c_read(int fd, uint16_t addr, uint8_t reg, uint8_t *buf, int len) {
    struct i2c_rdwr_ioctl_data rdwr_data;
    struct i2c_msg messages[1];

    messages[0].addr = addr;
    messages[0].flags = 0;
    messages[0].len = len;
    messages[0].buf = (uint8_t *)buf;

    rdwr_data.fd = fd;
    rdwr_data.msgs = messages;
    rdwr_data.nmsgs = 1;

    return ioctl(fd, I2C_RDWR, &rdwr_data);
}

