#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define BUFFER_SIZE 100
#define GPIO_PIN 4

typedef struct {
    time_t timestamp;
    int reading;
} Entry;

Entry buffer[BUFFER_SIZE];
int buffer_index = 0;

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %s, Reading: %d\n", ctime(&buffer[(buffer_index - i + BUFFER_SIZE) % BUFFER_SIZE].timestamp), buffer[(buffer_index - i + BUFFER_SIZE) % BUFFER_SIZE].reading);
    }
}

void sigint_handler(int signum) {
    print_buffer();
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input.\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(GPIO_PIN, 1);

    signal(SIGINT, sigint_handler);

    while (1) {
        int reading = gpioRead(GPIO_PIN);

        if (reading == 0) {
            time_t timestamp = time(NULL);
            buffer[buffer_index] = (Entry){timestamp, reading};
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            printf("Obstacle detected! Timestamp: %s, Reading: %d\n", ctime(&timestamp), reading);
        }

        gpioDelay(50000);
    }

    gpioTerminate();
    return 0;
}

