#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define D7S_ADDR 0x55
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define ACCEL_X_LSB 0x2A
#define ACCEL_Y_LSB 0x2C
#define ACCEL_Z_LSB 0x2E
#define SAMPLING_INTERVAL 500000 // 500 ms
#define MAX_WAIT_TIME 1000000 // 1 second

int i2c_fd = -1;

void log_sample(int64_t timestamp, int16_t x, int16_t y, int16_t z) {
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%FT%T", localtime(&timestamp));

    FILE *csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL && fopen_s(csv_file, "fan_health.csv", "a") != 0) {
        fprintf(stderr, "Error: Unable to open 'fan_health.csv' for appending.\n");
        return;
    }

    if (fopen_s(csv_file, "fan_health.csv", "a") == 0 && feof(csv_file)) {
        fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");
    }

    fprintf(csv_file, "%s,%ld,%ld,%ld\n", timestamp_str, x / 0.0009765625, y / 0.0009765625, z / 0.0009765625);
    fclose(csv_file);
}

int main() {
    int i2c_addr = D7S_ADDR;
    int i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, i2c_addr) < 0) {
        perror("Failed to set I2C address");
        close(i2c_file);
        return 1;
    }

    i2c_fd = i2c_file;

    if (write(i2c_fd, &0x10, 1) != 1) {
        fprintf(stderr, "Failed to write to MODE_CONTROL register.\n");
        close(i2c_fd);
        return 1;
    }

    int status = 0;
    int timeout = 0;

    while (timeout < MAX_WAIT_TIME) {
        if (read(i2c_fd, &status, 1) != 1) {
            fprintf(stderr, "Failed to read from OPERATING_STATUS register.\n");
            continue;
        }

        if ((status & 0x01) == 1) {
            break;
        }

        timeout++;
        usleep(SAMPLING_INTERVAL);
    }

    if (timeout >= MAX_WAIT_TIME) {
        fprintf(stderr, "Error: Omron D7S sensor did not become active within 1 second.\n");
        close(i2c_fd);
        return 1;
    }

    int16_t x_raw, y_raw, z_raw;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    int64_t timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;

    while (1) {
        if (read(i2c_fd, &x_raw, 2) != 2) {
            fprintf(stderr, "Failed to read acceleration X register.\n");
            continue;
        }

        if (read(i2c_fd, &y_raw, 2) != 2) {
            fprintf(stderr, "Failed to read acceleration Y register.\n");
            continue;
        }

        if (read(i2c_fd, &z_raw, 2) != 2) {
            fprintf(stderr, "Failed to read acceleration Z register.\n");
            continue;
        }

        int16_t x = (x_raw << 8) | x_raw;
        int16_t y = (y_raw << 8) | y_raw;
        int16_t z = (z_raw << 8) | z_raw;

        log_sample(timestamp, x, y, z);

        clock_gettime(CLOCK_MONOTONIC, &ts);
        timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;
        usleep(SAMPLING_INTERVAL);
    }

    close(i2c_fd);
    return 0;
}

