#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define LED_GPIO 25

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

int main() {
    gpioInitialise();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_OUTPUT) < 0 || gpioSetMode(SENSOR2_GPIO, PI_OUTPUT) < 0 || gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetWarningHandler(NULL);

    signal(SIGINT, sigint_handler);

    while (1) {
        if (sigint_received) {
            break;
        }

        int sensor1 = gpioRead(SENSOR1_GPIO);
        int sensor2 = gpioRead(SENSOR2_GPIO);

        if (sensor1 == 0 || sensor2 == 0) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        usleep(100000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

