#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define STALL_THRESHOLD_SECONDS 2

static const char *log_file = "stall_log.txt";
static const int sensor_pins[2] = {17, 18};
static const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

static FILE *log_fp = NULL;
static volatile int stall_detected = 0;
static struct timespec last_stall_time;

void sigint_handler(int signum) {
    gpioTerminate();
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    log_fp = fopen("stall_log.txt", "a");
    if (!log_fp) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < num_sensors; i++) {
        if (gpioSetMode(sensor_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode for sensor %d.\n", sensor_pins[i]);
            gpioTerminate();
            return 1;
        }
        gpioSetOutput(sensor_pins[i], 1); // Ensure initial HIGH state
    }

    while (1) {
        int sensor_states[num_sensors];
        for (int i = 0; i < num_sensors; i++) {
            sensor_states[i] = gpioRead(sensor_pins[i]);
            if (sensor_states[i] < 0) {
                fprintf(stderr, "Failed to read sensor %d.\n", sensor_pins[i]);
                gpioTerminate();
                return 1;
            }
        }

        if (sensor_states[0] == 0 && sensor_states[1] == 0) {
            struct timespec current_time;
            clock_gettime(CLOCK_MONOTONIC, &current_time);

            if (stall_detected && (current_time.tv_sec - last_stall_time.tv_sec) >= STALL_THRESHOLD_SECONDS) {
                log_entry(current_time);
                stall_detected = 0;
            }

            if (!stall_detected && (current_time.tv_sec - last_stall_time.tv_sec) > 1) {
                stall_detected = 1;
                last_stall_time = current_time;
            }
        } else {
            stall_detected = 0;
        }

        gpioFlushOutput(sensor_pins);
        usleep(100000); // Delay to avoid excessive CPU usage
    }

    gpioTerminate();
    fclose(log_fp);
    return 0;
}

void log_entry(struct timespec timestamp) {
    char timestamp_str[64];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp.tv_sec));

    if (fputs(timestamp_str, log_fp) == EOF) {
        perror("Failed to write to log file");
    }
    fputc('\n', log_fp);
}

