#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x0E
#define REG_CTRL1 0x00
#define REG_ID     0x00
#define LSB_SCALE_FACTOR_50MT 16384

static FILE *fp;

void sigint_handler(int signum) {
    gpioTerminate();
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct tm tm;
    time_t now;
    time(&now);
    localtime_r(&now, &tm);

    gpioInitialise();
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio_initialise() failed\n");
        return 1;
    }

    fp = fopen("magnetic_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open magnetic_log.csv\n");
        pigpio_terminate();
        return 1;
    }

    if (fopen_s(&fp, "magnetic_log.csv", "w") == 0) {
        fprintf(fp, "Time,X (mT),Y (mT),Z (mT)\n");
    }

    if (i2c_open(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        pigpio_terminate();
        return 1;
    }

    if (i2c_write_read(I2C_ADDR, REG_ID, NULL, 1, (uint8_t *) &tm.tm_year + 1980, 1) != 1) {
        fprintf(stderr, "Failed to read device ID register\n");
    }

    if (i2c_write_read(I2C_ADDR, REG_CTRL1, NULL, 1, (uint8_t *)&(0x0100), 1) != 1) {
        fprintf(stderr, "Failed to configure sensor\n");
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        uint16_t raw_x, raw_y, raw_z;

        if (i2c_write_read(I2C_ADDR, 0x03, (uint8_t *)&raw_x, 2, NULL, 0) != 2) {
            fprintf(stderr, "Failed to read X axis\n");
            continue;
        }

        if (i2c_write_read(I2C_ADDR, 0x05, (uint8_t *)&raw_y, 2, NULL, 0) != 2) {
            fprintf(stderr, "Failed to read Y axis\n");
            continue;
        }

        if (i2c_write_read(I2C_ADDR, 0x07, (uint8_t *)&raw_z, 2, NULL, 0) != 2) {
            fprintf(stderr, "Failed to read Z axis\n");
            continue;
        }

        int x_mt = raw_x * LSB_SCALE_FACTOR_50MT / 16384;
        int y_mt = raw_y * LSB_SCALE_FACTOR_50MT / 16384;
        int z_mt = raw_z * LSB_SCALE_FACTOR_50MT / 16384;

        fprintf(fp, "%ld,%d,%d,%d\n", (long)mktime(&tm), x_mt, y_mt, z_mt);

        sleep(0.1);
    }

    i2c_close();
    pigpio_terminate();
    return 0;
}

