#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

typedef enum { IDLE, A_RISING, A_FALLING, B_RISING, B_FALLING } state_t;

state_t state = IDLE;
int prev_state = IDLE;
int direction = 0; // 1 for CW, -1 for CCW
pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;

void rotation_event_callback(int pin, pigpio_callback_data_t data) {
    state = (pigpio_pulseLength(pin, data.pulse_time_us) > 1000) ? (data.edge == RISING ? A_RISING : A_FALLING) : (data.edge == RISING ? B_RISING : B_FALLING);
    pthread_mutex_lock(&state_mutex);
    if (prev_state != state) {
        prev_state = state;
        if (state == A_RISING && prev_state == B_FALLING) {
            direction = 1; // CW
        } else if (state == A_FALLING && prev_state == B_RISING) {
            direction = -1; // CCW
        }
        pthread_mutex_unlock(&state_mutex);
        log_event();
    }
    pthread_mutex_unlock(&state_Mutex);
}

void log_event() {
    char timestamp[32];
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return;
    }

    if (direction == 1) {
        fprintf(log_file, "%s CW\n", timestamp);
    } else if (direction == -1) {
        fprintf(log_file, "%s CCW\n", timestamp);
    }

    fclose(log_file);
}

void *main_loop(void *arg) {
    gpioInitialise();
    if (gpioFail()) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return NULL;
    }

    if (gpioSetMode(SENSOR_A_GPIO, PI_OUTPUT) || gpioSetPullUpDown(SENSOR_A_GPIO, 2)) {
        fprintf(stderr, "Failed to set GPIO mode or pull-ups\n");
        gpioTerminate();
        return NULL;
    }

    if (gpioSetMode(SENSOR_B_GPIO, PI_OUTPUT) || gpioSetPullUpDown(SENSOR_B_GPIO, 2)) {
        fprintf(stderr, "Failed to set GPIO mode or pull-ups\n");
        gpioTerminate();
        return NULL;
    }

    if (gpioSetAlertFunc(SENSOR_A_GPIO, rotation_event_callback) || gpioSetAlertFunc(SENSOR_B_GPIO, rotation_event_callback)) {
        fprintf(stderr, "Failed to set alert functions\n");
        gpioTerminate();
        return NULL;
    }

    log_event();

    while (1) {
        pthread_cond_wait(&cv, &state_mutex);
        // Sleep or wait on a condition variable instead of busy-spinning
    }

    gpioTerminate();
    return NULL;
}

void sigint_handler(int signum) {
    gpioTerminate();
    printf("Received SIGINT, cleaning up...\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    pthread_t thread;
    if (pthread_create(&thread, NULL, main_loop, NULL)) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread, NULL);
    return 0;
}

