#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <libgpiod.h>

#define TOUCH_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL 50000 // 50 ms

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
  running = 0;
}

static void sigterm_handler(int signum) {
  running = 0;
}

static int setup_gpio(gpiod_chip *chip) {
  struct gpiod_line_request req;
  memset(&req, 0, sizeof(req));
  req.line.pin = TOUCH_PIN;
  req.line.dev = chip->dev;
  req.flags = GPIO_LINE_REQUEST_IN;

  if (gpiod_line_request_add_bulk(&chip->dev, &req) < 0) {
    syslog(LOG_ERR, "Failed to request touch sensor line");
    return -1;
  }

  req.line.pin = LED_PIN;
  req.flags = GPIO_LINE_REQUEST_OUT;
  if (gpiod_line_request_add_bulk(&chip->dev, &req) < 0) {
    syslog(LOG_ERR, "Failed to request LED line");
    return -1;
  }

  return 0;
}

int main() {
  struct gpiod_chip *chip;
  int fd;
  int ret;

  if (openlog("touch_led_control", LOG_PID, LOG_DAEMON) < 0) {
    syslog(LOG_ERR, "Failed to initialize syslog");
    return -1;
  }

  signal(SIGINT, sigint_handler);
  signal(SIGTERM, sigterm_handler);

  fd = gpiod_chip_open(0, &chip);
  if (fd < 0) {
    syslog(LOG_ERR, "Failed to open GPIO chip");
    return -1;
  }

  if (setup_gpio(chip) < 0) {
    gpiod_chip_close(fd);
    return -1;
  }

  gpiod_line_request_get_value(chip->dev, TOUCH_PIN, 0); // Initialize touch sensor

  while (running) {
    ret = gpiod_line_get_value(chip->dev, TOUCH_PIN);
    if (ret < 0) {
      syslog(LOG_ERR, "Failed to read touch sensor value");
      continue;
    }

    if (ret) {
      syslog(LOG_INFO, "Touch detected");
      gpiod_line_set_value(chip->dev, LED_PIN, 1);
    } else {
      syslog(LOG_INFO, "Touch released");
      gpiod_line_set_value(chip->dev, LED_PIN, 0);
    }

    usleep(POLL_INTERVAL);
  }

  gpiod_line_set_value(chip->dev, LED_PIN, 0);
  gpiod_chip_close(fd);
  closelog();
  return 0;
}

