  fd = gpiod_chip_open(0, &chip);
  if (fd < 0) {
    syslog(LOG_ERR, "Failed to open GPIO chip");
    return -1;
  }

  if (setup_gpio(chip) < 0) {
    gpiod_chip_close(fd);
    return -1;
  }

  gpiod_line_request_get_value(chip->dev, TOUCH_PIN, 0); // Initialize touch sensor

  while (running) {
    ret = gpiod_line_get_value(chip->dev, TOUCH_PIN);
    if (ret < 0) {
      syslog(LOG_ERR, "Failed to read touch sensor value");
      continue;
    }

    if (ret) {
      syslog(LOG_INFO, "Touch detected");
      gpiod_line_set_value(chip->dev, LED_PIN, 1);
    } else {
      syslog(LOG_INFO, "Touch released");
      gpiod_line_set_value(chip->dev, LED_PIN, 0);
    }

    usleep(POLL_INTERVAL);
  }

  gpiod_line_set_value(chip->dev, LED_PIN, 0);
  gpiod_chip_close(fd);
  closelog();
  return 0;
