        return 1;
    }

    line = gpiod_chip_get_line(chip, "GPIO17");
    if (!line) {
        gpiod_chip_close(fd);
        return 1;
    }

    if (gpiod_line_request_line(line, "input") < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        gpiod_chip_close(fd);
        return 1;
    }

    if (gpiod_line_export(line) < 0) {
        fprintf(stderr, "Failed to export line\n");
        gpiod_line_release(line);
        gpiod_chip_close(fd);
        return 1;
    }

    if (gpiod_line_set_direction(line, GPIOD_LINE_DIRECTION_IN) < 0) {
        fprintf(stderr, "Failed to set line direction\n");
        gpiod_line_release(line);
        gpiod_chip_close(fd);
        return 1;
    }

    if (gpiod_line_set_debounce(line, DEBOUNCE_DELAY) < 0) {
        fprintf(stderr, "Failed to set debounce delay\n");
        gpiod_line_release(line);
        gpiod_chip_close(fd);
        return 1;
    }

    if (gpiod_line_set_callback(line, touch_callback) < 0) {
        fprintf(stderr, "Failed to set callback\n");
        gpiod_line_release(line);
        gpiod_chip_close(fd);
        return 1;
    }

    if (gpiod_line_request_line(line, "output") < 0) {
        fprintf(stderr, "Failed to request line as output\n");
        gpiod_line_release(line);
        gpiod_chip_close(fd);
        return 1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set initial LED value\n");
        gpiod_line_release(line);
        gpiod_chip_close(fd);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        if (sigint_received) {
            break;
        }

        struct timespec ts = {0, DEBOUNCE_DELAY * 1000};
        nanosleep(&ts, NULL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(fd);

    return 0;
