#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define GPIO_SENSOR1 4
#define GPIO_SENSOR2 17
#define GPIO_LED1 27
#define GPIO_LED2 22

typedef struct {
    int pin;
    time_t timestamp;
    bool state;
} Event;

Event buffer[BUFFER_SIZE];
int head = 0, tail = 0;
int overflow_count = 0;

void log_event(int pin, bool state) {
    if (head == BUFFER_SIZE) {
        overflow_count++;
    }
    buffer[head] = (Event){.pin = pin, .timestamp = time(NULL), .state = state};
    head = (head + 1) % BUFFER_SIZE;
}

void print_log() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer[(head + i) % BUFFER_SIZE].state) {
            fprintf(stderr, "Touch: GPIO%d (%ld), State: ON\n", buffer[(head + i) % BUFFER_SIZE].pin, buffer[(head + i) % BUFFER_SIZE].timestamp);
        } else {
            fprintf(stderr, "Release: GPIO%d (%ld), State: OFF\n", buffer[(head + i) % BUFFER_SIZE].pin, buffer[(head + i) % BUFFER_SIZE].timestamp);
        }
    }
    fprintf(stderr, "Overflow count: %d\n", overflow_count);
}

void signal_handler(int signum) {
    gpioTerminate();
    print_log();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(GPIO_SENSOR1, PI_OUTPUT);
    gpioSetMode(GPIO_LED1, PI_OUTPUT);
    gpioSetMode(GPIO_SENSOR2, PI_OUTPUT);
    gpioSetMode(GPIO_LED2, PI_OUTPUT);

    gpioWrite(GPIO_LED1, 0);
    gpioWrite(GPIO_LED2, 0);

    while (true) {
        int sensor1 = gpioRead(GPIO_SENSOR1);
        int sensor2 = gpioRead(GPIO_SENSOR2);

        if (sensor1) {
            gpioWrite(GPIO_LED1, 1);
            log_event(GPIO_SENSOR1, true);
        } else {
            gpioWrite(GPIO_LED1, 0);
            log_event(GPIO_SENSOR1, false);
        }

        if (sensor2) {
            gpioWrite(GPIO_LED2, 1);
            log_event(GPIO_SENSOR2, true);
        } else {
            gpioWrite(GPIO_LED2, 0);
            log_event(GPIO_SENSOR2, false);
        }

        usleep(50000);
    }

    gpioTerminate();
    return 0;
}

