#define GPIO_PIN 17
#define POLL_INTERVAL 500000 // 500 ms
#define LOG_FILE "/var/log/rain_events.log"

int sensor_state = 0;
int previous_state = 0;
FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup();
        exit(0);
    }
}

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    if (gpioInitialise() == -1) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return;
    }

    gpioTerminate();
}

void setup() {
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        exit(1);
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) == -1) {
        fprintf(stderr, "Error setting GPIO mode.\n");
        cleanup();
        exit(1);
    }

    gpioSetPullUpDown(GPIO_PIN, 1); // Enable internal pull-up resistor
    gpioWrite(GPIO_PIN, 1); // Ensure the pin is HIGH initially

    log_file = fopen("/var/log/rain_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
}

void poll_sensor() {
    while (1) {
        if (gpioRead(GPIO_PIN) == 0) {
            sensor_state = 1;
        } else {
            sensor_state = 0;
        }

        if (sensor_state != previous_state) {
            log_message();
            previous_state = sensor_state;
        }

        gpioWaitEvent(GPIO_PIN, RISING, POLL_INTERVAL);
        usleep(POLL_INTERVAL);
    }
}

void log_message() {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s: %s\n", timestamp, sensor_state == 1 ? "Rain Detected" : "No Rain");
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    setup();
    poll_sensor();
    cleanup();
    return 0;
}

