#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <pigio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define DEBOUNCE_DELAY 5000 // 5 ms

int main() {
    int fd;
    gpioInitialise();
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library. Error %d\n", errno);
        return 1;
    }

    gpioSetMode(GPIO_SENSOR1, PI_OUTPUT);
    gpioSetMode(GPIO_SENSOR2, PI_OUTPUT);

    fd = fopen("shaft_log.txt", "w");
    if (!fd) {
        fprintf(stderr, "Failed to open shaft_log.txt for writing. Error %d\n", errno);
        gpioTerminate();
        return 1;
    }

    while (1) {
        static int last_state1 = 0, last_state2 = 0;
        static time_t last_time = 0;
        int state1, state2;

        gpioRead(GPIO_SENSOR1, &state1);
        gpioRead(GPIO_SENSOR2, &state2);

        if (state1 != last_state1 || state2 != last_state2) {
            if (time(&last_time) - time(NULL) > DEBOUNCE_DELAY) {
                fprintf(fd, "%ld,%d,%d\n", time(NULL), state1, state2);
                last_state1 = state1;
                last_state2 = state2;
            }
        }

        if (state1 != last_state1 || state2 != last_state2) {
            double rpm = 2.0 * 60.0 / DEBOUNCE_DELAY; // Assuming 2 pulses per revolution
            printf("RPM: %.2f\n", rpm);
        }
    }

    gpioTerminate();
    fclose(fd);
    return 0;
}

