#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04

static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    piClose(gpio_handle, 0);
    exit(0);
}

int main() {
    gpio_init();
    gpio_handle = piGetGPIOHandle();

    if (gpio_set_mode(gpio_handle, 0, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    if (piI2COpen(gpio_handle, 1, SI1182_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    int part_id;
    if (piI2CGet(gpio_handle, SI1182_ADDR, PART_ID_REG, &part_id, 1) != 1) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        return 1;
    }

    if (part_id != 0x11) {
        fprintf(stderr, "Invalid part ID: 0x%02X\n", part_id);
        return 1;
    }

    if (piI2CSetRegister(gpio_handle, SI1182_ADDR, CONFIG_REG, 0x0100) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        time_t now_time = time(NULL);
        struct tm *local_time = localtime(&now_time);

        if (local_time->tm_sec == 0) {
            int heart_rate, spo2;
            if (piI2CGet(gpio_handle, SI1182_ADDR, HEART_RATE_REG, &heart_rate, 1) != 1) {
                fprintf(stderr, "Failed to read heart rate register\n");
                continue;
            }
            if (piI2CGet(gpio_handle, SI1182_ADDR, SPO2_REG, &spo2, 1) != 1) {
                fprintf(stderr, "Failed to read SPO2 register\n");
                continue;
            }

            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Heart Rate: %d BPM, SpO2: %d%%\n",
                    local_time->tm_year + 1900,
                    local_time->tm_mon + 1,
                    local_time->tm_mday,
                    local_time->tm_hour,
                    local_time->tm_min,
                    local_time->tm_sec,
                    heart_rate,
                    spo2);
            fflush(log_file);
        }

        gpio_sleep(1000000);
    }

    return 0;
}

