            if (gpioRead(ALARM_GPIO) == 0) {
                log_event("Tilt-start detected on sensor 1");
            }
            gpioWrite(ALARM_GPIO, 1);
        } else if (sensor1_state == 1) {
            if (gpioRead(ALARM_GPIO) == 0) {
                log_event("Tilt-start detected on sensor 2");
            }
            gpioWrite(ALARM_GPIO, 1);
        } else if (sensor2_state == 1) {
