#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define SENSOR_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_REG 0x28
#define ACCEL_Y_REG 0x29
#define ACCEL_Z_REG 0x2A
#define ACCEL_DATA_LEN 6
#define THRESHOLD 500
#define LED_GPIO 17
#define MAX_RETRIES 3

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len);
void log_event(double peak_vibration);

int main() {
    int i2c_fd = pigpio_i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        pigpio_i2c_close(i2c_fd);
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(LED_GPIO, PI_UP);
    gpioWrite(LED_GPIO, 0);

    uint8_t ctrl1 = 0;
    if (i2c_read(i2c_fd, CTRL1_REG, &ctrl1, 1) < 0) {
        fprintf(stderr, "Failed to read CTRL1 register\n");
        pigpio_terminate();
        pigpio_i2c_close(i2c_fd);
        return 1;
    }

    ctrl1 &= ~0x08; // Clear power-down bit
    if (i2c_read(i2c_fd, CTRL1_REG, &ctrl1, 1) < 0) {
        fprintf(stderr, "Failed to write to CTRL1 register\n");
        pigpio_terminate();
        pigpio_i2c_close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen("seismic_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_terminate();
        pigpio_i2c_close(i2c_fd);
        return 1;
    }

    double peak_vibration = 0;
    while (1) {
        uint8_t accel_data[ACCEL_DATA_LEN];
        for (int i = 0; i < MAX_RETRIES; ++i) {
            int bytes_read = i2c_read(i2c_fd, ACCEL_X_REG, accel_data, ACCEL_DATA_LEN);
            if (bytes_read == ACCEL_DATA_LEN) {
                break;
            }
            if (bytes_read < 0) {
                fprintf(stderr, "I2C communication error, retrying...\n");
                continue;
            }
        }

        if (bytes_read != ACCEL_DATA_LEN) {
            fprintf(stderr, "Failed to read acceleration data after %d retries\n", MAX_RETRIES);
            break;
        }

        double x = (accel_data[0] << 8 | accel_data[1]) * 0.0048828125;
        double y = (accel_data[2] << 8 | accel_data[3]) * 0.0048828125;
        double z = (accel_data[4] << 8 | accel_data[5]) * 0.0048828125;

        peak_vibration = sqrt(x * x + y * y + z * z);

        if (peak_vibration > THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            delay(1000000000 / 100); // 1 second
            gpioWrite(LED_GPIO, 0);

            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

            fprintf(log_file, "%s, Peak vibration: %.2f\n", timestamp, peak_vibration);
        }
    }

    fclose(log_file);
    pigpio_terminate();
    pigpio_i2c_close(i2c_fd);

    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    struct i2c_rdwr_ioctl_data rd_wr;
    rd_wr.iorbno = 0;
    rd_wr.addr = SENSOR_ADDR;
    rd_wr.flags = 0;
    rd_wr.len = len;
    rd_wr.buf = (unsigned char *)buf;

    if (ioctl(fd, I2C_RDWR, &rd_wr) < 0) {
        return -1;
    }

    return len;
}

void log_event(double peak_vibration) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(stderr, "Event: %s, Peak vibration: %.2f\n", timestamp, peak_vibration);
}

