#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define LED_GPIO 18
#define POLL_INTERVAL_MS 50

struct sensor_data {
    int fd;
    int line;
};

struct sensor_data sensors[NUM_SENSORS];
bool led_on = false;

static int sensor_callback(struct gpiod_chip *chip, const struct gpiod_line_info *line, uint32_t flags) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (line->user_data == sensors[i].line) {
            led_on = !gpiod_get_value(chip, line);
            break;
        }
    }
    return 0;
}

static void signal_handler(int signum) {
    (void)signum;
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_drain_delete(sensors[i].fd);
    }
    gpiod_rmdev(led_gpio);
    exit(0);
}

int main() {
    struct gpiod_chipchip_info chip_info;
    struct gpiod_chip *chip;
    int ret;

    chip_info.dev_name = "gpiochip0";
    chip = gpiod_chip_open(&chip_info, O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    chip_info.dev_name = NULL;
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].fd = gpiod_chip_get_line(chip, "P" + to_string(4 + i));
        if (!sensors[i].fd) {
            fprintf(stderr, "Failed to get line for sensor %d\n", i + 1);
            return 1;
        }
        sensors[i].line = gpiod_line_from_fd(sensors[i].fd);
        if (!sensors[i].line) {
            fprintf(stderr, "Failed to get line info for sensor %d\n", i + 1);
            return 1;
        }
        gpiod_line_export(sensors[i].line, "Sensor" + to_string(i));
        gpiod_line_set_direction(sensors[i].line, GPIO_DIR_IN);
        gpiod_line_set_pull(sensors[i].line, GPIO_PULL_DOWN);
        gpiod_add_callback(sensors[i].line, &sensor_callback);
    }

    if (gpiod_line_request(gpiod_chip_get_line(chip, "gpio" + to_string(LED_GPIO)), "led") < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        return 1;
    }

    gpiod_line_export(gpiod_chip_get_line(chip, "gpio" + to_string(LED_GPIO)), "led");
    gpiod_line_set_direction(gpiod_chip_get_line(chip, "gpio" + to_string(LED_GPIO)), GPIO_DIR_OUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (true) {
        struct timespec ts = {0, POLL_INTERVAL_MS * 1000 / 1000};
        nanosleep(&ts, NULL);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_drain_delete(sensors[i].fd);
    }
    gpiod_rmdev(LED_GPIO);
    gpiod_chip_put(chip);
    return 0;
}

