#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>

#define NUM_TOUCH_SENSORS 8
#define POLL_INTERVAL_MS 50

static const int touch_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
static const char *sensor_names[] = {"OUT0", "OUT1", "OUT2", "OUT3", "OUT4", "OUT5", "OUT6", "OUT7"};

static int touch_states[NUM_TOUCH_SENSORS] = {0};

static void print_touch_state(int sensor_index, int pin, bool is_touched) {
    char timestamp[32];
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    printf("%s: Sensor %s (GPIO %d) %s\n", timestamp, sensor_names[sensor_index], pin, is_touched ? "touched" : "released");
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_TOUCH_SENSORS];

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return ret;
    }

    for (int i = 0; i < NUM_TOUCH_SENSORS; ++i) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d: %s\n", touch_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return ret;
        }

        ret = gpiod_line_request_bulk(lines[i], 1, &touch_states[i]);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d in bulk: %s\n", touch_pins[i], strerror(errno));
            gpiod_line_free(lines[i]);
            gpiod_chip_close(chip);
            return ret;
        }
    }

    while (true) {
        for (int i = 0; i < NUM_TOUCH_SENSORS; ++i) {
            ret = gpiod_bulk_read(lines[i], (uint8_t *)&touch_states[i], 1);
            if (ret < 0) {
                fprintf(stderr, "Failed to read line %d: %s\n", touch_pins[i], strerror(errno));
                gpiod_line_free(lines[i]);
                gpiod_chip_close(chip);
                return ret;
            }

            if (touch_states[i] != (touch_states[i] & (touch_states[i] - 1))) {
                print_touch_state(i, touch_pins[i], true);
                touch_states[i] = 0;
            } else {
                print_touch_state(i, touch_pins[i], false);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    for (int i = 0; i < NUM_TOUCH_SENSORS; ++i) {
        gpiod_line_free(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

