#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <wiringPiI2C.h>

#define LED_GPIO 18
#define VEML7700_ADDR 0x10
#define ALS_GAIN 0x00
#define ALS_INT_TIME 0x00
#define CONFIG_REG 0x00
#define ALS_REG 0x04

void log_sample(int lux, int brightness) {
    char timestamp[20];
    time_t t = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));

    FILE *log_file = fopen("grow_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s, Lux: %.2f, Brightness: %d%%, Error: %d\n", timestamp, lux, brightness, pigpio_error());
        fflush(log_file);
        fclose(log_file);
    }
}

int main() {
    int ret;
    gpioInitialise();
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (wiringPiI2CInitialised() == false) {
        fprintf(stderr, "I2C bus initialization failed\n");
        pigpio_terminate();
        return 1;
    }

    if (i2c_open(1, VEML7700_ADDR) < 0) {
        fprintf(stderr, "I2C open failed\n");
        pigpio_terminate();
        return 1;
    }

    uint16_t config_value = (ALS_GAIN << 8) | ALS_INT_TIME;
    if (i2c_write_word(1, CONFIG_REG, config_value) != 1) {
        fprintf(stderr, "Config register write failed\n");
        i2c_close(1);
        pigpio_terminate();
        return 1;
    }

    while (1) {
        if ((ret = i2c_read_word(1, ALS_REG, &raw_lux)) != 2) {
            fprintf(stderr, "ALS read failed, error code: %d\n", ret);
            break;
        }

        double lux = (double)raw_lux * 0.0576;
        int brightness = 100;
        if (lux < 100) brightness = 100;
        else if (lux < 500) brightness = 75;
        else if (lux < 1000) brightness = 50;
        else brightness = 25;

        log_sample(lux, brightness);

        gpioSetMode(LED_GPIO, PI_OUTPUT);
        gpioSetPWMfrequency(LED_GPIO, 1000);
        gpioSetPWMdutycycle(LED_GPIO, brightness);
        sleep(1);
    }

    gpioTerminate();
    pigpio_terminate();
    i2c_close(1);
    return 0;
}

void sigint_handler(int signum) {
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, 0);
    gpioSetPWMdutycycle(LED_GPIO, 0);
    fprintf(stderr, "Shutting down...\n");
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Rest of the main function remains the same
}

