#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define GPIO_BASE 2
#define LED_GPIO 17

static volatile sig_atomic_t sigint_received = 0;

static void signal_handler(int signum) {
    sigint_received = signum;
}

int main() {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 50 * 1000 * 1000;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_BASE, PI_INPUT) < 0) {
        fprintf(stderr, "GPIO configuration failed\n");
        gpioTermination();
        return 1;
    }

    gpioSetPullUpDown(GPIO_BASE, PI_PUD_OFF);
    gpioSetOutputLevel(LED_GPIO, 0);

    if (gpioSetLED(LED_GPIO) < 0) {
        fprintf(stderr, "Failed to set LED GPIO\n");
        gpioTermination();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int touched_channels[NUM_CHANNELS] = {0};

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int channel_state = gpioRead(GPIO_BASE + i);
            if (channel_state && !touched_channels[i]) {
                touched_channels[i] = 1;
                if (gpioWrite(LED_GPIO, 1) < 0) {
                    fprintf(stderr, "Failed to turn on LED\n");
                    break;
                }
            }
        }

        if (!any_touched(touched_channels, NUM_CHANNELS)) {
            gpioWrite(LED_GPIO, 0);
        }

        if (gpioWrite(LED_GPIO, 0) < 0) {
            fprintf(stderr, "Failed to turn off LED\n");
            break;
        }

        if (sigint_received) {
            break;
        }

        nanosleep(&ts, NULL);
    }

    gpioTermination();
    return 0;
}

int any_touched(const int *touched, int count) {
    for (int i = 0; i < count; i++) {
        if (touched[i]) {
            return 1;
        }
    }
    return 0;
}

