#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define CONVERSION_TIME_MS 100

static pigpio *gpio;
static int i2c_fd;

void sigint_handler(int signum) {
    gpioTerminate();
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigeset(&sa.sa_mask, signum(SIGINT));
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    i2c_fd = i2cOpen(1, OPT3001_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteWordData(i2c_fd, CONFIG_REG, CONFIG_WORD) < 0) {
        fprintf(stderr, "Failed to write configuration word to OPT3001.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    usleep(CONVERSION_TIME_MS * 1000);

    FILE *log_file = fopen("light_data.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint16_t raw_result;
        if (i2cReadWordData(i2c_fd, RESULT_REG, &raw_result) < 0) {
            fprintf(stderr, "Failed to read result from OPT3001.\n");
            break;
        }

        // Byte-swap the 16-bit value
        raw_result = (raw_result >> 8) | (raw_result << 8);

        double lux = (raw_result & 0xF00) >> 8 * 0.01 * (1 << ((raw_result >> 12) & 0x0F));

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));

        fprintf(log_file, "%s, %.2f\n", timestamp, lux);
        printf("%s, %.2f\n", timestamp, lux);

        fflush(log_file);
        usleep(1000000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

