#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define ALERT_GPIO 17
#define POLL_INTERVAL 500000 // 500 milliseconds

static volatile sig_atomic_t sigint_received = 0;

static void signal_handler(int signum) {
    sigint_received = signum;
}

static int setup_gpio(int gpio) {
    if (gpio < 0 || gpio > 31) return -1;
    if (piGetMode() != PI_HARD) return -2;
    if (gpioInit() < 0) return -3;
    if (piSetMode(gpio, PI_OUTPUT) < 0) return -4;
    return 0;
}

static void cleanup_gpio(int gpio) {
    if (gpio >= 0 && gpio <= 31) {
        piSetMode(gpio, PI_INPUT, 0);
        piTerminate();
    }
}

static FILE *open_log_file() {
    if ((fopen("fire_events.log", "a")) == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    return fopen("fire_events.log", "a");
}

static void close_log_file(FILE *log_file) {
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    struct timespec ts;
    gpio alarm_triggered = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("pigpio initialization failed");
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up GPIOs
    if (setup_gpio(FLAME_SENSOR_GPIO) < 0 || setup_gpio(ALERT_GPIO) < 0) {
        cleanup_gpio(FLAME_SENSOR_GPIO);
        cleanup_gpio(ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    FILE *log_file = open_log_file();

    while (!sigint_received) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        int flame_detected = gpioRead(FLAME_SENSOR_GPIO);

        if (flame_detected == 0) {
            fprintf(log_file, "Flame detected at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            gpioWrite(ALERT_GPIO, 1);
            sleep_ms(1000);
            gpioWrite(ALERT_GPIO, 0);
        } else {
            fprintf(log_file, "No flame detected at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
        }

        nanosleep(&ts, NULL);
    }

    // Clean up resources
    close_log_file(log_file);
    cleanup_gpio(FLAME_SENSOR_GPIO);
    cleanup_gpio(ALERT_GPIO);
    gpioTerminate();

    return EXIT_SUCCESS;
}

