#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define DEBOUNCE_INTERVAL (50 * 1000) // 50 ms
#define GPIO_PIN 4

struct timespec ts;
int touch_state = 0;

static int handle_touch_event(gpiod_chip *chip, const uint64_t event, uint64_t value, void *user_data) {
    (void)chip;
    (void)event;
    (void)value;
    (void)user_data;

    if (touch_state != (int)value) {
        touch_state = (int)value;

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", gpiod_chip_get_time(chip));

        FILE *log_file = fopen("touch_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            gpiod_chip_drain_del(chip);
            return -1;
        }

        if (value == 0) {
            fprintf(log_file, "Touch Released\n");
        } else {
            fprintf(log_file, "Touch Detected\n");
        }

        fflush(log_file);
        fclose(log_file);
    }

    return 0;
}

static void sigint_handler(int signum) {
    gpiod_chip_drain_del(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    struct gpiod_chip chip;
    int ret;

    ret = gpiod_chip_open(&chip, GPIO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", GPIO_PIN);
        return ret;
    }

    ret = gpiod_chip_set_owner(chip, __RUN_IN_INTERPRETER);
    if (ret < 0) {
        fprintf(stderr, "Failed to claim GPIO %d\n", GPIO_PIN);
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_set_direction(&chip, GPIO_PIN, GPIO_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_set_pull(&chip, GPIO_PIN, GPIO_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", GPIO_PIN);
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_add_event(&chip, NULL, DEBOUNCE_INTERVAL, handle_touch_event, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to add event for GPIO %d\n", GPIO_PIN);
        gpiod_chip_close(&chip);
        return ret;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        nanosleep(&ts, NULL);
    }

    gpiod_chip_close(&chip);
    return 0;
}

