#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <wiringPiI2C.h>

#define SENSOR_ADDR 0x08
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define MAX_FLOW_RATE 100.0

struct flow_data {
    double flow_rate;
    int raw_value;
    char status[32];
};

int crc8(unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

void log_flow_data(FILE *fp, struct flow_data data) {
    time_t t = time(NULL);
    strftime(data.status, sizeof(data.status), "%F %T", localtime(&t));
    fprintf(fp, "%s,%.2f,%s\n", data.status, data.flow_rate, data.status);
}

int main() {
    pigpio *gpio;
    int fd = wiringPiI2CSetup(SENSOR_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    gpio = pigpio_initialise();
    if (!gpio) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    FILE *fp = fopen("cooling_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open cooling_log.csv\n");
        return 1;
    }

    if (fgets(fp, "First row of headers\n")) {
        fclose(fp);
        fp = fopen("cooling_log.csv", "w");
        if (!fp) {
            fprintf(stderr, "Failed to open cooling_log.csv for writing\n");
            return 1;
        }
    }

    uint8_t command[3] = {0x36, 0x08, 0x00};
    gpio_write(gpio, 0, 0); // Ensure GPIOs are in input mode
    delay(2);
    gpio_write(gpio, 0, 1); // Set GPIOs as outputs for command sequence

    for (int i = 0; i < 3; i++) {
        wiringPiI2CWriteReg8(fd, i, command[i]);
        delay(10);
    }

    while (1) {
        uint8_t data[3];
        int rc = wiringPiI2CReadReg8(fd, 0, &data[0]);
        if (rc < 0) {
            fprintf(stderr, "I2C read failed\n");
            pigpio_terminate(gpio);
            return 1;
        }

        for (int i = 1; i < 3; i++) {
            rc = wiringPiI2CReadReg8(fd, i, &data[i]);
            if (rc < 0) {
                fprintf(stderr, "I2C read failed\n");
                pigpio_terminate(gpio);
                return 1;
            }
        }

        if (crc8((uint8_t *)&data, 3) != data[2]) {
            log_flow_data(fp, {0.0, data[0], "ERROR"});
            pigpio_terminate(gpio);
            return 1;
        }

        struct flow_data flow_data;
        flow_data.raw_value = (int16_t)(data[0] | (data[1] << 8));
        flow_data.flow_rate = (double)flow_data.raw_value / 90.0;

        if (flow_data.flow_rate < 0.0 || flow_data.flow_rate > MAX_FLOW_RATE) {
            sprintf(flow_data.status, "INVALID");
        } else {
            sprintf(flow_data.status, "OK");
        }

        log_flow_data(fp, flow_data);
        delay(1000000); // Sleep for 1 second
    }

    pigpio_terminate(gpio);
    fclose(fp);
    return 0;
}

