#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define LED_GPIO 24
#define TOUCH_GPIO 23
#define POLL_TIMEOUT 1000000 // 1 second

static int touch_detected = 0;
static FILE *log_file = NULL;

static int handle_event(const struct gpiod_chip *chip,
                        const struct gpiod_line *line,
                        uint32_t events,
                        void *user_data) {
    if (events & GPIO_EVENT_FALLING_EDGE) {
        touch_detected = 1;
    }
    return 0;
}

static int setup_gpio(int touch_gpio, int led_gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip4", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, touch_gpio);
    if (!line) {
        gpiod_chip_close(chip);
        fprintf(stderr, "Failed to acquire touch GPIO line\n");
        return -1;
    }

    ret = gpiod_line_export(line, &gpiod_flags_t{ .debounce = false });
    if (ret) {
        gpiod_chip_close(chip);
        fprintf(stderr, "Failed to export touch GPIO line\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, led_gpio);
    if (!line) {
        gpiod_line_unexport(line);
        gpiod_chip_close(chip);
        fprintf(stderr, "Failed to acquire LED GPIO line\n");
        return -1;
    }

    ret = gpiod_line_request_device(line);
    if (ret) {
        gpiod_line_unexport(line);
        gpiod_chip_close(chip);
        fprintf(stderr, "Failed to request LED GPIO line\n");
        return -1;
    }

    gpiod_line_set_config(line,
                          GPIO_CONFIG_PULL_UP |
                          GPIO_CONFIG_INPUT);

    gpiod_add_event(line,
                    GPIO_EVENT_FALLING_EDGE,
                    handle_event,
                    NULL);

    gpiod_chip_close(chip);
    return 0;
}

static void cleanup_gpio(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    if (gpiod_chip_close(chip)) {
        fprintf(stderr, "Failed to close GPIO chip\n");
    }
}

static void log_touch_event(const char *timestamp, int led_state) {
    char buf[64];
    if (asctime_r(localtime(nullptr), buf) == nullptr) {
        fprintf(stderr, "Failed to get timestamp\n");
        return;
    }

    if (log_file) {
        fprintf(log_file, "%s LED_STATE=%d\n", buf, led_state);
    }
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip4", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = setup_gpio(TOUCH_GPIO, LED_GPIO);
    if (ret) {
        cleanup_gpio();
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        gpiod_batch_process(chip, POLL_TIMEOUT);

        if (touch_detected) {
            touch_detected = 0;
            log_touch_event(ctime(nullptr), !!(gpiod_line_get_value(line)));
            gpio_put(line, 1); // Turn on LED
        }

        usleep(100000); // Poll every 100ms
    }

    cleanup_gpio();
    gpiod_chip_close(chip);
    return 0;
}

