#include <errno.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define POLL_INTERVAL 500
#define BUZZER_DURATION 2000
#define LOG_FILE "alert_log.txt"

FILE *log_file = NULL;
int flame_detected = 0;

void log_event(const char *event) {
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), event);
        fflush(log_file);
    }
}

void shutdown_handler(int signum) {
    flame_detected = 0;
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = shutdown_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    GPIOD *chip;
    GPIOD_LINE *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0", NULL);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, "GPIO" STRINGIFY(FLAME_SENSOR_PIN));
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line) < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_chip_close(chip);
        return 1;
    }
    fprintf(log_file, "System started\n");

    while (1) {
        int prev_value = gpiod_line_get_value(line);
        usleep(POLL_INTERVAL);
        int curr_value = gpiod_line_get_value(line);

        if (prev_value && !curr_value) { // HIGH-to-LOW transition
            flame_detected = 1;
            log_event("Flame detected");
            activate_buzzer();
        }

        if (flame_detected) {
            if (BUZZER_DURATION-- <= 0) {
                flame_detected = 0;
                deactivate_buzzer();
            }
        }
    }

    gpiod_chip_close(chip);
    fclose(log_file);
    fprintf(stderr, "System stopped\n");
    return 0;
}

void activate_buzzer() {
    gpiod_line_set_value(line, 1);
}

void deactivate_buzzer() {
    gpiod_line_set_value(line, 0);
}

