    gpioTerminate();
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    exit(0);
}

static void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library.\n");
        exit(1);
    }

    if (gpioSetMode(4, PI_INPUT) < 0 || gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetPullUpDown(4, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up/pull-down resistors for GPIO4.\n");
        gpioTerminate();
        exit(1);
    }
}

static int read_touch_sensor() {
    int last_state = touch_state;
    if (gpioRead(4) == 1) {
        touch_state = 1;
        return 1;
    } else {
        touch_state = 0;
        return 0;
    }
}

static void toggle_led_and_log(int touch) {
    static unsigned long last_touch_time = 0;
    static int debounce_timer = 0;

    if (touch && (debounce_timer == 0 || (time_t)(time(NULL) - last_touch_time) > DEBOUNCE_DELAY)) {
        gpioWrite(17, 1);
        if (log_fp != NULL) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
            fprintf(log_fp, "%s, Touch detected\n", timestamp);
            fflush(log_fp);
        }
        last_touch_time = time(NULL);
        debounce_timer = POLL_DELAY;
    } else if (!touch && debounce_timer > 0) {
        debounce_timer--;
    }
}

