#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SENSORS_GPIO {4, 17, 27}
#define NUM_SENSORS (sizeof(SENSORS_GPIO) / sizeof(SENSORS_GPIO[0]))

// Function prototypes
static int init_gpio(int sensor_gpio);
static void log_state_change(int sensor_index, int state);
static void cleanup(void);

int main(void) {
    int sensor_gpio;
    int i;
    gpioInitialise();

    for (i = 0; i < NUM_SENSORS; i++) {
        sensor_gpio = SENSORS_GPIO[i];
        if (init_gpio(sensor_gpio) != 0) {
            fprintf(stderr, "Error setting up GPIO %d\n", sensor_gpio);
            goto cleanup_and_exit;
        }
    }

    const int poll_interval_ms = 100;
    int initial_states[NUM_SENSORS] = {0};

    for (i = 0; i < NUM_SENSORS; i++) {
        sensor_gpio = SENSORS_GPIO[i];
        initial_states[i] = gpioRead(sensor_gpio);
        if (initial_states[i] == -1) {
            fprintf(stderr, "Error reading initial state of GPIO %d\n", sensor_gpio);
            goto cleanup_and_exit;
        }
    }

    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    FILE *log_file = fopen("magnet_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        goto cleanup_and_exit;
    }

    while (1) {
        static int last_states[NUM_SENSORS] = {0};
        time_t now;
        struct tm *time_info;
        char timestamp[64];

        time(&now);
        time_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

        for (i = 0; i < NUM_SENSORS; i++) {
            sensor_gpio = SENSORS_GPIO[i];
            int current_state = gpioRead(sensor_gpio);
            if (current_state == -1) {
                fprintf(stderr, "Error reading current state of GPIO %d\n", sensor_gpio);
                continue;
            }

            if (current_state != last_states[i]) {
                log_state_change(i, current_state);
                last_states[i] = current_state;
            }
        }

        fprintf(log_file, "%s: ", timestamp);
        for (i = 0; i < NUM_SENSORS; i++) {
            fprintf(log_file, "Sensor %d: %s", SENSORS_GPIO[i], current_state ? "High" : "Low");
            if (i < NUM_SENSORS - 1) {
                fprintf(log_file, ", ");
            }
        }
        fprintf(log_file, "\n");

        gpioDelay(poll_interval_ms);
    }

cleanup_and_exit:
    cleanup(void);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

static int init_gpio(int sensor_gpio) {
    return gpioSetMode(sensor_gpio, PI_OUTPUT) &&
           gpioSetPullUpDown(sensor_gpio, PI_PUD_OFF) &&
           gpioWrite(sensor_gpio, 1);
}

static void log_state_change(int sensor_index, int state) {
    fprintf(stdout, "%s: Sensor %d: %s\n", timestamp, SENSORS_GPIO[sensor_index], state ? "High" : "Low");
}

static void cleanup(void) {
    int i;
    for (i = 0; i < NUM_SENSORS; i++) {
        gpioWrite(SENSORS_GPIO[i], 0);
    }
    gpioTerminate();
}

