#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <unistd.h>

#define SI1182_ADDR 0x4A
#define LED_CURRENT 0x3F
#define AVERAGING 0x04
#define ENABLE 0x01
#define HEART_RATE_REG 0x2A
#define PART_ID 0x00
#define HW_REV 0x01
#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

int i2c_fd = -1;
gpio *gpio_handle = NULL;
FILE *log_file = NULL;

void log_heart_rate(unsigned int bpm) {
    if (log_file != NULL) {
        time_t now;
        time(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%u\n", 1900 + (now / 3600 % 100), 1 + (now / 3600 % 10000 / 100), 1 + (now / 60 % 100), 1 + (now % 60), 1 + (now % 60000 / 1000), bpm);
        fflush(log_file);
    }
}

unsigned int raw_to_bpm(uint16_t raw) {
    return (unsigned int) (raw * 0.5);
}

float moving_average(float x, float ma[], int size) {
    if (size == 0) return 0;
    ma[size - 1] = x;
    float sum = 0;
    for (int i = 0; i < size; i++) {
        sum += ma[i];
    }
    return sum / size;
}

int main() {
    gpioInitialise();
    gpio_handle = gpio;

    i2c_fd = i2cOpen(1, 0x4A);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        goto exit_cleanup;
    }

    if (i2cWriteWordData(i2c_fd, PART_ID, 0x02) != 2) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        goto exit_i2c_close;
    }

    if (i2cWriteWordData(i2c_fd, HW_REV, 0x01) != 2) {
        fprintf(stderr, "Failed to read HW_REV register\n");
        goto exit_i2c_close;
    }

    if (i2cWriteWordData(i2c_fd, LED_CURRENT, 0x3F) != 2) {
        fprintf(stderr, "Failed to write LED current register\n");
        goto exit_i2c_close;
    }

    if (i2cWriteWordData(i2c_fd, AVERAGING, 0x04) != 2) {
        fprintf(stderr, "Failed to write averaging register\n");
        goto exit_i2c_close;
    }

    if (i2cWriteWordData(i2c_fd, ENABLE, 0x01) != 2) {
        fprintf(stderr, "Failed to write enable register\n");
        goto exit_i2c_close;
    }

    log_file = fopen("heart_rate.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        goto exit_i2c_close;
    }

    float ma[MOVING_AVG_SIZE];
    memset(ma, 0, sizeof(ma));

    for (;;) {
        uint16_t raw;
        int retries = 3;

        while (retries > 0) {
            if (i2cReadWordData(i2c_fd, HEART_RATE_REG, &raw) == 2) {
                break;
            }
            retries--;
            sleep(1);
        }

        unsigned int bpm = raw_to_bpm(raw);
        ma[0] = bpm;
        for (int i = 1; i < MOVING_AVG_SIZE; i++) {
            ma[i] = ma[i - 1];
        }

        float filtered_bpm = moving_average(bpm, ma, MOVING_AVG_SIZE);

        if (filtered_bpm >= MIN_BPM && filtered_bpm <= MAX_BPM) {
            log_heart_rate(filtered_bpm);
        }
    }

exit_i2c_close:
    i2cClose(i2c_fd);
exit_cleanup:
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

