#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_BROADCOM 17
#define GPIO_PIN 11
#define POLL_INTERVAL_MS 100
#define LOG_FILE "flame_log.txt"

static int flame_sensor_line_available = 0;
static struct gpiod_chip *chip = NULL;
FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    // Register SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize libgpiod
    ret = gpiod_chip_open(&chip, "GPIO17");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return ret;
    }

    // Get the line for GPIO17
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_BROADCOM);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO%d line\n", GPIO_PIN);
        gpiod_chip_put(chip);
        return -1;
    }

    // Configure the line as input with pull-up
    ret = gpiod_line_request_cooked(line, "input", GPIO_PULLUP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line\n");
        gpiod_chip_put(chip);
        return ret;
    }

    flame_sensor_line_available = 1;

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s for writing\n", LOG_FILE);
        gpiod_chip_put(chip);
        return -1;
    }

    // Start polling
    while (1) {
        if (!flame_sensor_line_available) {
            fprintf(stderr, "Flame sensor line is not available\n");
            break;
        }

        uint32_t value;
        ret = gpiod_line_read(line, &value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read line value\n");
            break;
        }

        if (value & (1 << GPIO_PIN)) {
            // Wait for a falling edge
            uint32_t edge_value;
            ret = gpiod_line_event_read(line, &edge_value);
            if (ret < 0) {
                fprintf(stderr, "Failed to read edge event\n");
                break;
            }

            if ((edge_value & (1 << GPIO_PIN)) == 0) {
                // Flame detected
                printf("FLAME DETECTED\n");

                // Write to log file
                time_t now = time(NULL);
                fprintf(log_file, "%ld FLAME DETECTED\n", now);
                fflush(log_file);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Release resources on exit
    gpiod_chip_put(chip);
    fclose(log_file);

    return 0;
}

