#define OUTPUT_MASK 0x1F
#define STABILIZATION_DELAY_MS 200

struct sensor_state {
    int line;
    int prev_state;
    int touch_count;
};

static int touch_counter_init(struct sensor_state *states) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open(0, "TP226");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; ++i) {
        struct gpiod_line *line;
        char line_name[32];

        snprintf(line_name, sizeof(line_name), "TP226_OUT%d", i + 1);
        line = gpiod_chip_get_line(chip, line_name);
        if (!line) {
            fprintf(stderr, "Failed to get line %s: %s\n", line_name, strerror(errno));
            gpiod_chip_release(chip);
            return -1;
        }

        ret = gpiod_line_request_add(line, "input");
        if (ret) {
            fprintf(stderr, "Failed to request line %s: %s\n", line_name, strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_release(chip);
            return -1;
        }

        states[i].line = line->line;
        states[i].prev_state = 0;
        states[i].touch_count = 0;
    }

    ret = gpiod_chip_request_lines(chip, NUM_SENSORS);
    if (ret) {
        fprintf(stderr, "Failed to request lines: %s\n", strerror(errno));
        gpiod_chip_release(chip);
        return -1;
    }

    usleep_delay(STABILIZATION_DELAY_MS * 1000); // Convert to microseconds
    gpiod_chip_release(chip);

    return 0;
}

static void touch_counter_cleanup(struct sensor_state *states) {
    struct gpiod_chip *chip;
    int i;

    chip = gpiod_chip_open(0, "TP226");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip for cleanup: %s\n", strerror(errno));
        return;
    }

    for (i = 0; i < NUM_SENSORS; ++i) {
        gpiod_line_release(gpiod_chip_get_line(chip, (char *)states[i].line));
    }

    gpiod_chip_release(chip);
}

static void touch_counter_output(unsigned int value) {
    int i;

    for (i = 0; i < 8; ++i) {
        if (value & (1 << i)) {
            gpio_putv(OUTPUT_PINS[i]);
        } else {
            gpio_putv(OUTPUT_PINS[i], 0);
        }
    }
}

static int touch_counter_read_sensor(struct sensor_state *states) {
    struct gpiod_line *line;
    int ret;
    int i;

    line = gpiod_chip_get_line((struct gpiod_chip *)0, states->line);
    if (!line) {
        fprintf(stderr, "Failed to get line for reading: %s\n", states->line);
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to read line %s: %s\n", states->line, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    if (ret != states->prev_state) {
        states->touch_count++;
        if (states->touch_count == 256) {
            states->touch_count = 0;
        }

        states->prev_state = ret;

        FILE *log_file = fopen("touch_log.txt", "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        } else {
            time_t now = time(NULL);
            fprintf(log_file, "%s, Channel: %d, Counter: %d\n", ctime(&now), states->line - 5, states->touch_count);
            fclose(log_file);
        }

        printf("Touch on channel %d | Counter: %d\n", states->line - 5, states->touch_count);
    }

    return 0;
}

int main(int argc, char *argv[]) {
    struct sensor_state states[NUM_SENSORS];
    int ret;

    ret = touch_counter_init(states);
    if (ret) {
        return ret;
    }

    // Initialize GPIO outputs
    for (int i = 0; i < 8; ++i) {
        gpio_init(OUTPUT_PINS[i]);
    }

    gpio_setv(OUTPUT_PINS[0], OUTPUT_MASK); // Set initial counter value

    while (1) {
        for (int i = 0; i < NUM_SENSORS; ++i) {
            ret = touch_counter_read_sensor(&states[i]);
            if (ret) {
                break;
            }
        }

        if (ret) {
            touch_counter_cleanup(states);
            return ret;
        }
    }

    touch_counter_cleanup(states);
    return 0;
}

