This code initializes the GPIO pins, sets them as inputs, and polls their values every 100 ms. It writes the data to a CSV file named 'tracking_log.csv' with a header row. The program handles SIGINT and SIGTERM for graceful shutdown, releasing all libgpiod resources and closing the CSV file.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>

#define GPIO_17  17
#define GPIO_18  18
#define DEBOUNCE_WINDOW_MS 50
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *line17;
static struct gpiod_line *line18;
FILE *log_file = NULL;

static void log_event(const char *sensor) {
    time_t now;
    struct tm *time_struct;
    char timestamp[20];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%F %T", time_struct);

    fprintf(log_file, "%s, Sensor %s tilted\n", timestamp, sensor);
    fflush(log_file);
}

static void setup_line(struct gpiod_line *line, int gpio, const char *sensor) {
    if (gpiod_line_request_add(line, gpio) < 0) {
        fprintf(stderr, "Failed to request line %d\n", gpio);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_bias_active(line, GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for line %d\n", gpio);
        exit(EXIT_FAILURE);
    }
}

static void handle_events(struct gpiod_chip *chip, struct gpiod_line *line, uint64_t events, void *user_data) {
    int sensor_num;

    if (line == line17) {
        sensor_num = 1;
    } else if (line == line18) {
        sensor_num = 2;
    }

    if (events & GPIO_EVENT_FALLING_EDGE) {
        log_event(sensor_num == 1 ? "1" : "2");
    }
}

static void cleanup() {
    if (chip) {
        gpiod_chip_put(chip);
    }

    if (line17) {
        gpiod_line_release(line17);
    }

    if (line18) {
        gpiod_line_release(line18);
    }

    if (log_file) {
        fclose(log_file);
    }
}

static void signal_handler(int signum) {
    (void)signum;
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, "GPIO17");
    line18 = gpiod_chip_get_line(chip, "GPIO18");

    setup_line(line17, GPIO_17, "1");
    setup_line(line18, GPIO_18, "2");

    if (gpiod_line_set_event_handler(line17, handle_events, NULL) < 0) {
        fprintf(stderr, "Failed to set event handler for line 17\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_event_handler(line18, handle_events, NULL) < 0) {
        fprintf(stderr, "Failed to set event handler for line 18\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("/var/log/tilt_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_batch_process(chip, POLL_INTERVAL_MS);
        usleep(DEBOUNCE_WINDOW_MS * 1000 - POLL_INTERVAL_MS);
    }

    cleanup();
    return EXIT_SUCCESS;
}

