#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define SAMPLE_PERIOD 125  // in microseconds

volatile sig_atomic_t stop_sampling = 0;

void signal_handler(int signum) {
    stop_sampling = 1;
}

int main() {
    const char *error;
    int fd;

    // Initialize pigpio library
    if ((fd = pigpio_initialise()) < 0) {
        fprintf(stderr, "pigpio_initialise() failed: %s\n", error);
        return 1;
    }

    // Set GPIO pins
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        pigpio_terminate(fd, true);
        return 1;
    }

    gpioSetMode(MIC_GPIO, PI_INPUT);
    gpioSetPullUpDown(MIC_GPIO, PI_PUD_OFF);
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Set LED to OFF initially
    gpioWrite(LED_GPIO, 0);

    while (!stop_sampling) {
        // Read GPIO4
        int mic_state = gpioRead(MIC_GPIO);
        if (mic_state < 0) {
            fprintf(stderr, "gpioRead() failed\n");
            break;
        }

        // Check for sound peak
        if (mic_state == 1) {
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            printf("Sound peak detected at %ld.%09ld ms\n",
                   (long)ts.tv_sec, (long)ts.tv_nsec / 1000);

            // Turn LED ON for 100 ms
            gpioWrite(LED_GPIO, 1);
            usleep(100000);
            gpioWrite(LED_GPIO, 0);
        }

        // Delay for the required period
        gpioDelay(SAMPLE_PERIOD);
    }

    // Clean up
    gpioTerminate(fd, true);
    pigpio_terminate(fd, true);
    return 0;
}

