#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define LEFT_PIN 17
#define CENTER_PIN 27
#define RIGHT_PIN 22

#define BUFFER_SIZE 1024

static struct gpiod_chip *chip;
static struct gpiod_line *left_line;
static struct gpiod_line *center_line;
static struct gpiod_line *right_line;

static void signal_handler(int signum) {
    gpiod_unrequest(chip);
    exit(signum);
}

static int init_gpio(void) {
    int ret;

    ret = gpiod_in_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return ret;
    }

    chip = gpiod_chip_open(gpiod_chip_register_get(0), "sunfounder_sensor");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        gpiod_in_exit();
        return -1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);

    if (!left_line || !center_line || !right_line) {
        fprintf(stderr, "Failed to get lines\n");
        gpiod_chip_close(chip);
        gpiod_in_exit();
        return -1;
    }

    if (gpiod_line_request_get(left_line) || gpiod_line_request_get(center_line) || gpiod_line_request_get(right_line)) {
        fprintf(stderr, "Lines already in use\n");
        gpiod_chip_close(chip);
        gpiod_in_exit();
        return -1;
    }

    if (gpiod_line_request(left_line, GPIO_IN, NULL, NULL) < 0 ||
        gpiod_line_request(center_line, GPIO_IN, NULL, NULL) < 0 ||
        gpiod_line_request(right_line, GPIO_IN, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to request lines\n");
        gpiod_chip_close(chip);
        gpiod_in_exit();
        return -1;
    }

    if (gpiod_line_set_pull(left_line, GPIO_PUD_UP) < 0 ||
        gpiod_line_set_pull(center_line, GPIO_PUD_UP) < 0 ||
        gpiod_line_set_pull(right_line, GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up\n");
        gpiod_chip_close(chip);
        gpiod_in_exit();
        return -1;
    }

    return 0;
}

static void read_sensors(void) {
    uint32_t left_value, center_value, right_value;

    left_value = gpiod_line_read(left_line);
    center_value = gpiod_line_read(center_line);
    right_value = gpiod_line_read(right_line);

    printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);
}

int main(void) {
    int ret;
    struct timespec next_read;
    clock_gettime(CLOCK_MONOTONIC, &next_read);

    ret = init_gpio();
    if (ret < 0) {
        return ret;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (true) {
        read_sensors();

        timespec_add_ns(&next_read, 100 * 1000 * 1000);
        ret = nanosleep(&next_read, NULL);
        if (ret != 0) {
            fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
            break;
        }
    }

    gpiod_line_release(left_line);
    gpiod_line_release(center_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);
    gpiod_in_exit();

    return 0;
}

