#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define SI1175_ADDR 0x49
#define ALS_LSB 0x24
#define ALS_MSB 0x25
#define READ_INTERVAL 100000 // 100 ms

int main() {
    int file;
    char filename[] = "/dev/i2c-1";
    gpiod_chip_reg_desc_t *chip;
    gpiod_chip_reg_t *reg;
    gpiod_context *ctx;
    struct i2c_rdwr_ioctl_data rdwr;
    uint8_t data[2];
    uint16_t als_value;

    ctx = gpiod_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create GPIO context\n");
        return 1;
    }

    chip = gpiod_chip_open(ctx, "i2c-1", GPIO_IN);
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip\n");
        gpiod_free(ctx);
        return 1;
    }

    reg = gpiod_chip_get_reg(chip, 0);
    if (!reg) {
        fprintf(stderr, "Failed to get I2C register\n");
        gpiod_chip_close(chip);
        gpiod_free(ctx);
        return 1;
    }

    file = open(filename, O_RDWR);
    if (file < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_chip_close(chip);
        gpiod_free(ctx);
        return 1;
    }

    ioctl(file, I2C_SLAVE, SI1175_ADDR);

    rdwr.addr = ALS_LSB;
    rdwr.len = 1;
    rdwr.buf = &data[0];
    if (ioctl(file, I2C_MASTER_RX_BUF, &rdwr) < 0) {
        fprintf(stderr, "Failed to read ALS LSB\n");
        close(file);
        gpiod_chip_close(chip);
        gpiod_free(ctx);
        return 1;
    }
    data[0] &= 0x1F;

    rdwr.addr = ALS_MSB;
    rdwr.len = 1;
    rdwr.buf = &data[1];
    if (ioctl(file, I2C_MASTER_RX_BUF, &rdwr) < 0) {
        fprintf(stderr, "Failed to read ALS MSB\n");
        close(file);
        gpiod_chip_close(chip);
        gpiod_free(ctx);
        return 1;
    }
    data[1] &= 0x7F;

    als_value = (data[1] << 7) | data[0];
    printf("ALS: %d\n", als_value);

    gpiod_chip_close(chip);
    close(file);
    gpiod_free(ctx);

    return 0;
}

