static int left_line = -1;
static int middle_line = -1;
static int right_line = -1;

static void sigint_handler(int signum) {
    gpiod_unrequest_all();
    exit(0);
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line_left, line_middle, line_right;
    int ret;

    // Initialize signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return ret;
    }

    // Request lines for input
    left_line = gpiod_line_request_input(&chip, LEFT_PIN);
    if (left_line < 0) {
        fprintf(stderr, "Failed to request input for left pin\n");
        gpiod_chip_close(&chip);
        return left_line;
    }

    middle_line = gpiod_line_request_input(&chip, MIDDLE_PIN);
    if (middle_line < 0) {
        fprintf(stderr, "Failed to request input for middle pin\n");
        gpiod_line_free(left_line);
        gpiod_chip_close(&chip);
        return middle_line;
    }

    right_line = gpiod_line_request_input(&chip, RIGHT_PIN);
    if (right_line < 0) {
