#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

// Function prototypes
static void sigint_handler(int signum);
static int poll_touch_sensor(gpiod_chip *chip);

int main(void) {
    struct timespec ts;
    gpiod_chip *chip;
    gpiod_line *lines[NUM_CHANNELS];
    int i;

    // Initialize libgpiod
    if (gpiod_chip_open(0, &chip) < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    // Request all 8 lines as inputs
    for (i = 0; i < NUM_CHANNELS; ++i) {
        const char *line_name = (i + 1) < 10 ? "TP" : "TP";
        line_name += i;
        if (gpiod_chip_get_line(chip, line_name, &lines[i]) < 0) {
            fprintf(stderr, "Failed to get line %s\n", line_name);
            gpiod_chip_close(chip);
            return 1;
        }
        if (gpiod_line_request_input(lines[i]) < 0) {
            fprintf(stderr, "Failed to request input for line %s\n", line_name);
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("[%ld.%09ld] ", ts.tv_sec, ts.tv_nsec);

        for (i = 0; i < NUM_CHANNELS; ++i) {
            const char *line_name = (i + 1) < 10 ? "TP" : "TP";
            line_name += i;
            int value;
            if (gpiod_line_get_value(lines[i], &value) < 0) {
                fprintf(stderr, "Failed to read line %s\n", line_name);
                break;
            }
            printf("%d", value);
        }
        printf(" ");

        // Sleep for POLL_INTERVAL_MS milliseconds
        nanosleep(&ts, NULL);

        // Check for SIGINT/SIGTERM
        if (i == NUM_CHANNELS) {
            break;
        }
    }

    // Release all resources
    for (i = 0; i < NUM_CHANNELS; ++i) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

// SIGINT/SIGTERM handler
static void sigint_handler(int signum) {
    printf("\nExiting gracefully...\n");
    for (int i = 0; i < NUM_CHANNELS; ++i) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

