#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_GPIO 17
#define GREEN_GPIO 18
#define BLUE_GPIO 27
#define FREQ 1000
#define RESOLUTION 8
#define FADE_STEPS 50

void hsv_to_rgb(float h, float s, float v, unsigned char *r, unsigned char *g, unsigned char *b);

int main() {
    const char *log_ident = "mood_lamp";
    openlog(log_ident, LOG_PID, LOG_LOCAL0);

    int pi_status = pigpio_initialise();
    if (pi_status < 0) {
        syslog(LOG_ERR, "pigpio initialization failed: %s", strerror(pi_status));
        return 1;
    }

    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise failed");
        pigpio_terminate(0);
        return 1;
    }

    unsigned int red, green, blue;
    float hue;
    srand(getpid());

    while (1) {
        pi_status = gpioPWM(RED_GPIO, RESOLUTION, 1000, 0);
        if (pi_status < 0) {
            syslog(LOG_ERR, "gpioPWM(red) failed: %s", strerror(pi_status));
            break;
        }

        pi_status = gpioPWM(GREEN_GPIO, RESOLUTION, 1000, 0);
        if (pi_status < 0) {
            syslog(LOG_ERR, "gpioPWM(green) failed: %s", strerror(pi_status));
            break;
        }

        pi_status = gpioPWM(BLUE_GPIO, RESOLUTION, 1000, 0);
        if (pi_status < 0) {
            syslog(LOG_ERR, "gpioPWM(blue) failed: %s", strerror(pi_status));
            break;
        }

        hue = (float)rand() / RAND_MAX;
        hsv_to_rgb(hue, 1.0, 1.0, &red, &green, &blue);

        for (int i = 0; i < FADE_STEPS; ++i) {
            int duty = 255 - ((255 - red) * i / FADE_STEPS);
            pi_status = gpioPWMSet(RED_GPIO, duty);
            if (pi_status < 0) {
                syslog(LOG_ERR, "gpioPWMSet(red) failed: %s", strerror(pi_status));
                break;
            }

            duty = 255 - ((255 - green) * i / FADE_STEPS);
            pi_status = gpioPWMSet(GREEN_GPIO, duty);
            if (pi_status < 0) {
                syslog(LOG_ERR, "gpioPWMSet(green) failed: %s", strerror(pi_status));
                break;
            }

            duty = 255 - ((255 - blue) * i / FADE_STEPS);
            pi_status = gpioPWMSet(BLUE_GPIO, duty);
            if (pi_status < 0) {
                syslog(LOG_ERR, "gpioPWMSet(blue) failed: %s", strerror(pi_status));
                break;
            }

            usleep(1000000 / FREQ);
        }

        red = green = blue = 0;
    }

    pigpio_terminate(0);
    closelog();
    return 0;
}

void hsv_to_rgb(float h, float s, float v, unsigned char *r, unsigned char *g, unsigned char *b) {
    int i;
    float f, p, q, t;

    if (s == 0) {
        *r = *g = *b = v;
    } else {
        h /= 6.0;
        f = floor(h);
        p = h - f;
        q = v * (1.0 - s);
        t = v * (1.0 - s * p);
        i = (int)floor(h * 6.0);

        switch (i) {
            case 0:
                *r = v;
                *g = t;
                *b = q;
                break;
            case 1:
                *r = q + (t - q) * p;
                *g = v;
                *b = q;
                break;
            case 2:
                *r = q;
                *g = v;
                *b = t + (q - t) * p;
                break;
            case 3:
                *r = q;
                *g = t + (q - t) * p;
                *b = v;
                break;
            case 4:
                *r = t + (q - t) * p;
                *g = q;
                *b = v;
                break;
            case 5:
            default:
                *r = v;
                *g = q;
                *b = t + (q - t) * p;
        }
    }

    *r = (unsigned char)(255.0 * (*r));
    *g = (unsigned char)(255.0 * (*g));
    *b = (unsigned char)(255.0 * (*b));
}

