#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <getopt.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define TCS34725_ADDR 0x29
#define ATIME 0x00
#define GAIN 0x00
#define ID_REG 0x12
#define CLEAR_REG 0x14
#define RED_REG 0x16
#define GREEN_REG 0x18
#define BLUE_REG 0x1A
#define LED_GPIO 17
#define RED_THRESHOLD 200

int i2c_fd = -1;
int gpio_chip = -1;
int gpio_line = -1;

void calibrate_channels(uint16_t *channels, int gain) {
    // Apply per-channel gain and offset calibration
    // This is a placeholder, replace with actual calibration values
    for (int i = 0; i < 4; i++) {
        channels[i] *= gain;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "i:h")) != -1) {
        switch (opt) {
            case 'i':
                i2c_fd = open("/dev/i2c-1", O_RDWR);
                if (i2c_fd < 0) {
                    perror("Failed to open I2C bus");
                    return 1;
                }
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-i <i2c-bus>]\n", argv[0]);
                return 1;
        }
    }

    if (!i2c_fd) {
        fprintf(stderr, "No I2C bus specified\n");
        return 1;
    }

    if (gpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        return 1;
    }

    gpio_chip = gpiod_find_chip(NULL, "GPIO17", 0);
    if (gpio_chip < 0) {
        fprintf(stderr, "Failed to find GPIO17\n");
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, "GPIO17");
    if (gpio_line < 0) {
        fprintf(stderr, "Failed to get GPIO17 line\n");
        return 1;
    }

    if (gpiod_export(gpio_line) < 0) {
        perror("Failed to export GPIO17");
        return 1;
    }

    if (gpiod_set_value(gpio_line, 0) < 0) {
        perror("Failed to set GPIO17 low");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to set TCS34725 address");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0) < 0) {
        perror("Failed to reset TCS34725");
        return 1;
    }

    uint8_t id;
    if (ioctl(i2c_fd, I2C_RDWR, &id) < 0) {
        perror("Failed to read ID register");
        return 1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Invalid sensor ID\n");
        return 1;
    }

    uint16_t clear, red, green, blue;
    if (ioctl(i2c_fd, I2C_RDWR, &clear) < 0) {
        perror("Failed to read clear channel");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &red) < 0) {
        perror("Failed to read red channel");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &green) < 0) {
        perror("Failed to read green channel");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &blue) < 0) {
        perror("Failed to read blue channel");
        return 1;
    }

    calibrate_channels((uint16_t[]){clear, red, green, blue}, 1);

    printf("Calibrated Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear, red, green, blue);

    while (1) {
        if (red > RED_THRESHOLD) {
            gpiod_set_value(gpio_line, 1);
        } else {
            gpiod_set_value(gpio_line, 0);
        }

        sleep(0.001);
    }

    gpiod_unexport(gpio_line);
    close(i2c_fd);
    return 0;
}

