        return 1;
    }

    uint16_t clear, red, green, blue;
    if (ioctl(i2c_fd, I2C_RDWR, &clear) < 0) {
        perror("Failed to read clear channel");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &red) < 0) {
        perror("Failed to read red channel");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &green) < 0) {
        perror("Failed to read green channel");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &blue) < 0) {
        perror("Failed to read blue channel");
        return 1;
    }

    calibrate_channels((uint16_t[]){clear, red, green, blue}, 1);

