                continue;
            fprintf(stderr, "Error communicating with BH1750: %s\n", strerror(errno));
            return 0;
        }

        if (write(file, &READ_LUX_CMD, 1) != 1) {
            fprintf(stderr, "Error writing to BH1750\n");
            return 0;
        }

        if (read(file, &msb, 1) != 1) {
            fprintf(stderr, "Error reading MSB from BH1750\n");
            return 0;
        }

        if (read(file, &lsb, 1) != 1) {
            fprintf(stderr, "Error reading LSB from BH1750\n");
            return 0;
        }

        return (msb << 8 | lsb) / 1.2;
    }

    fprintf(stderr, "Failed to read lux after %d retries\n", I2C_RETRY_COUNT);
    return 0;
}

int main() {
    int fd, res;
    uint8_t lux;
    uint32_t led_brightness[LED_COUNT];

    gpioInitialise();

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        goto finish;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting BH1750 address\n");
        close(fd);
        goto finish;
    }

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Error initialising pigpio library\n");
        close(fd);
        goto finish;
    }

    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    while (1) {
        lux = i2c_read_lux(fd, BH1750_ADDR);

        if (lux == 0)
            continue;

        // Logarithmic brightness mapping (0-1000 lux to 0-65535 brightness)
        for (int i = 0; i < LED_COUNT; i++) {
            led_brightness[i] = (uint32_t)(65535 * log10(1 + (lux / 1000)));
        }

        // Generate WS2812B waveform using pigpio hardware PWM/wave
        for (int i = 0; i < LED_COUNT; i++) {
            gpioSetPWMwave(WS2812B_GPIO, i + 1, led_brightness[i]);
        }

        usleep(100000); // Adjust delay as needed
    }

finish:
    gpioTerminate();
    close(fd);
    pigpio_terminate();
    return 0;
}

