#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <spi/spidev.h>

#define BH1750_ADDR 0x23
#define APA102_LED_COUNT 32
#define SPI_CLOCK 1000000

int bh1750_read(int fd, uint8_t *data) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, "W", 1) != 1) {
        perror("Failed to write command to sensor");
        return -1;
    }

    if (ndelay(120) < 0) {
        perror("Failed to wait for conversion");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Failed to read data from sensor");
        return -1;
    }

    return 0;
}

float bh1750_to_lux(uint8_t data[2]) {
    return (float)(data[0] << 8 | data[1]) / 1.2;
}

uint8_t lux_to_brightness(float lux) {
    if (lux < 10) lux = 10;
    if (lux > 300) lux = 300;
    return (uint8_t)((lux / 300.0) * 31);
}

int apa102_write(int fd, uint8_t *data) {
    if (write(fd, data, APA102_LED_COUNT * 4) != 4 * APA102_LED_COUNT) {
        perror("Failed to write data to APA102");
        return -1;
    }
    return 0;
}

int main() {
    int bh1750_fd = open("/dev/i2c-1", O_RDWR);
    if (bh1750_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }
    int apa102_fd = open("/dev/spidev0.0", O_RDWR);
    if (apa102_fd < 0) {
        perror("Failed to open SPI bus");
        close(bh1750_fd);
        return 1;
    }

    uint8_t bh1750_data[2];
    if (bh1750_read(bh1750_fd, bh1750_data) < 0) {
        close(bh1750_fd);
        close(apa102_fd);
        return 1;
    }

    float lux = bh1750_to_lux(bh1750_data);
    uint8_t brightness = lux_to_brightness(lux);

    uint8_t apa102_data[APA102_LED_COUNT * 4];
    for (int i = 0; i < APA102_LED_COUNT; ++i) {
        apa102_data[i * 4 + 0] = 0xE0 | brightness;
        apa102_data[i * 4 + 1] = 0;
        apa102_data[i * 4 + 2] = 0;
        apa102_data[i * 4 + 3] = 0;
    }
    apa102_data[APA102_LED_COUNT * 4 - 4] = 0xFF;

    if (apa102_write(apa102_fd, apa102_data) < 0) {
        close(bh1750_fd);
        close(apa102_fd);
        return 1;
    }

    close(bh1750_fd);
    close(apa102_fd);

    struct sigaction sa;
    sa.sa_handler = [](int signum) {
        close(bh1750_fd);
        close(apa102_fd);
        printf("SIGINT received, turning off LEDs and exiting.\n");
    };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        sleep(1);
    }

    return 0;
}

