        gpiod_chip_put(chip);
        return ret;
    }

    uint32_t cycle = 1 / 800000; // 800 kHz
    uint32_t phase = 0;
    uint32_t data = 0;

    for (int i = 0; i < 24; ++i) {
        if (i == 0) {
            data |= (brightness << phase);
        } else {
            data <<= 1;
            if (brightness & (1 << (23 - i))) {
                data |= 0x01;
            }
        }

        phase += (cycle / 32);
        while (phase >= cycle) {
            phase -= cycle;
            gpiod_trigger_export(line, &trigger);
        }

        usleep(cycle * (uint32_t)(100 - brightness / 255 * 100));
    }

    gpiod_trigger_disable(line, &trigger);
    gpiod_line_release(line);
    gpiod_chip_put(chip);

    return 0;
}

static void i2c_error_handler(int signum) {
    printf("Error: I2C communication failed. Continuing...\n");
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    int ret;
    int fd;
    int retries = 0;

    signal(SIGINT, i2c_error_handler);
    signal(SIGTERM, i2c_error_handler);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    ioctl(fd, I2C_SLAVE, VEML7700_ADDR);

    if (veml7700_init(fd) < 0) {
        close(fd);
        return -1;
    }

    ret = gpiod_chip_get_by_label(NULL, "gpiochip0", &chip);
    if (ret < 0) {
        close(fd);
        return ret;
    }

    led.gpio = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!led.gpio) {
        gpiod_chip_put(chip);
        close(fd);
        return -1;
    }

    gpiod_chip_remove_override(led.gpio);

    struct gpiod_trigger trigger;
    trigger.type = GPIO_TRIGGER_FALLING_EDGE;
    trigger.flags = 0;
    trigger.id = led.gpio->id;

    ret = gpiod_add_override(led.gpio, &trigger);
    if (ret < 0) {
        gpiod_line_release(led.gpio);
        gpiod_chip_put(chip);
        close(fd);
        return ret;
    }

    while (1) {
        uint16_t raw = veml7700_get_raw(fd);
        double lux = veml7700_raw_to_lux(raw);
        uint8_t brightness = veml7700_lux_to_brightness(lux);

        printf("Lux: %f, Brightness: %d\n", lux, brightness);

        if (bitbang_ws2812b(&led, brightness) < 0) {
            printf("Bit-banging failed. Falling back to threshold control.\n");
            // Implement threshold-based control here if needed
        }

        usleep(200000);

        if (retries++ >= MAX_RETRIES) {
            close(fd);
            gpiod_line_release(led.gpio);
            gpiod_chip_put(chip);
            return 0;
        }
    }

    close(fd);
    gpiod_line_release(led.gpio);
    gpiod_chip_put(chip);

    return 0;
}
