        gpiod_line_write(led_line, 1);

        clock_gettime(CLOCK_MONOTONIC, &start_time);
        while ((end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) < FLAME_DETECTED_INTERVAL) {
            if (!gpiod_line_get_value(flame_sensor_line)) {
                // Flame gone
                gpiod_line_write(buzzer_line, 0);
                gpiod_line_write(led_line, 0);
                break;
            }
        }
    }

    cleanup();
    return 0;
}

void cleanup() {
    gpiod_line_free(led_line);
    gpiod_line_free(buzzer_line);
    gpiod_line_free(flame_sensor_line);
    gpiod_chip_close(chip);
