#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdbool.h>
#include <signal.h>
#include <string.h>

#define DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x23
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define RAW_TO_LUX 1.2

#define MIN_RATE 0.5
#define MAX_RATE 5.0
#define MIN_LUX 0
#define MAX_LUX 1000

int i2c_fd = -1;
int gpio_fd = -1;
uint8_t buffer[BUFFER_SIZE];
size_t head = 0;
size_t tail = 0;

void init_i2c() {
    i2c_fd = open(DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set i2c address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    const char *gpio_path = "/sys/class/gpio/gpio" GPIO_PIN "/value";
    gpio_fd = open(gpio_path, O_WRLR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_fd, IOC_GPIO_ direction_output) < 0) {
        perror("Failed to set GPIO direction");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

uint16_t read_light_sensor() {
    uint8_t cmd[2] = {0x10, 0};
    uint16_t raw;

    if (write(i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write to I2C\n");
        return 0;
    }

    if (read(i2c_fd, &raw, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C\n");
        return 0;
    }

    return raw;
}

double get_average_lux() {
    double sum = 0;
    size_t i;

    for (i = 0; i < BUFFER_SIZE && head != tail; ++i) {
        sum += buffer[tail];
        tail = (tail + 1) % BUFFER_SIZE;
    }

    return sum / BUFFER_SIZE;
}

double get_blink_rate(double avg_lux) {
    return fmax(MIN_RATE, fmin(MAX_RATE, 0.5 + (avg_lux / 1000) * 4.5));
}

void toggle_gpio(double rate) {
    double period = 1.0 / rate;
    usleep(period / 2);
    if (write(gpio_fd, "1") < 0) {
        perror("Failed to set GPIO high");
    } else {
        usleep(period / 2);
        if (write(gpio_fd, "0") < 0) {
            perror("Failed to set GPIO low");
        }
    }
}

void signal_handler(int sig) {
    if (sig == SIGINT) {
        close(i2c_fd);
        close(gpio_fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    init_i2c();
    init_gpio();

    while (1) {
        uint16_t raw = read_light_sensor();
        double lux = (raw << 8) | raw / 100;
        buffer[head] = lux;
        head = (head + 1) % BUFFER_SIZE;

        double avg_lux = get_average_lux();
        double rate = get_blink_rate(avg_lux);
        toggle_gpio(rate);

        usleep(1000000);
    }

    return 0;
}

