#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define SEGMENT_PINS {2, 3, 4, 5, 6, 7, 8} // Map 74HC595 outputs to display segments
#define DIGIT_5 "3E2" // Segments for digit '5'

static int digit_5_pattern = 0;
static int blink_state = 0;

static int shift_out(uint8_t data) {
    for (int i = 0; i < 8; i++) {
        gpiod_chip_set_value(chip, data_pin, 1);
        gpiod_chip_set_value(chip, clock_pin, 1);
        gpiod_chip_set_value(chip, latch_pin, 0);
        usleep(1000); // Clock low
        gpiod_chip_set_value(chip, clock_pin, 0);
        gpiod_chip_set_value(chip, latch_pin, 1);
        usleep(1000); // Clock high
        data >>= 1;
    }
    return 0;
}

int main(int argc, char **argv) {
    struct gpiod_chip chip;
    struct gpiod_line *data_pin, *clock_pin, *latch_pin;
    int ret;

    ret = gpiod_chip_open(&chip, "GPIO17");
    if (ret) {
        fprintf(stderr, "Failed to open GPIO17 (data)\n");
        goto out;
    }
    data_pin = gpiod_chip_get_line(&chip, "GPIO17");

    ret = gpiod_chip_open(&chip, "GPIO18");
    if (ret) {
        fprintf(stderr, "Failed to open GPIO18 (clock)\n");
        goto out_data;
    }
    clock_pin = gpiod_chip_get_line(&chip, "GPIO18");

    ret = gpiod_chip_open(&chip, "GPIO27");
    if (ret) {
        fprintf(stderr, "Failed to open GPIO27 (latch)\n");
        goto out_clock;
    }
    latch_pin = gpiod_chip_get_line(&chip, "GPIO27");

    if (gpiod_line_request_add(data_pin, "output") ||
        gpiod_line_request_add(clock_pin, "output") ||
        gpiod_line_request_add(latch_pin, "output")) {
        fprintf(stderr, "Failed to request lines\n");
        ret = -1;
        goto out_latch;
    }

    while (1) {
        blink_state = !blink_state;

        for (int i = 0; i < strlen(DIGIT_5); i++) {
            digit_5_pattern = DIGIT_5[i] - '0';
            shift_out(digit_5_pattern);
            usleep(500000); // 500 ms
        }

        usleep(500000); // 500 ms off
    }

out_latch:
    gpiod_line_release(latch_pin);
out_clock:
    gpiod_line_release(clock_pin);
out_data:
    gpiod_chip_close(&chip);
