#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define LED_GPIO 17
#define BUTTON_GPIO 18
#define TOGGLE_INTERVAL_MS 2000
#define BUTTON_TIMEOUT_MS 1000

static volatile sig_atomic_t sigint_received = 0;

static int toggle_led_callback(const struct gpiod_line *line, uint32_t event, uint32_t value) {
    if (event == GPIOD_EVENT_FALLING && value == 0) {
        printf("Button pressed, stopping LED blinking and exiting.\n");
        gpiod_line_release(line);
        exit(0);
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    int ret;

    chip = gpiod_chip_open(0, "GPIO");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_get(led_line, "output", 0);
    if (ret) {
        fprintf(stderr, "Failed to request LED line as output\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_set_value(led_line, 0);

    button_line = gpiod_chip_get_line(chip, BUTTON_GPIO);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_add(button_line, "input", GPIOD_FLAG_ACTIVE_HIGH | GPIOD_FLAG_PULLUP);
    if (ret) {
        fprintf(stderr, "Failed to request button line as input\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_event_add(button_line, GPIOD_EVENT_FALLING, toggle_led_callback);
    if (ret) {
        fprintf(stderr, "Failed to add button event\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, [](int) { sigint_received = 1; });

    while (!sigint_received) {
        gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
        ret = gpiod_line_event_wait(button_line, BUTTON_TIMEOUT_MS, 0);
        if (ret < 0 && ret != -ETIMEDOUT) {
            fprintf(stderr, "Error waiting for button event\n");
            break;
        }

        if (ret == -ETIMEDOUT) {
            printf("Button timeout, stopping LED blinking and exiting.\n");
            gpiod_line_release(led_line);
            gpiod_line_release(button_line);
            gpiod_chip_close(chip);
            exit(0);
        }
    }

    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

