#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

int main() {
    struct sigaction sa;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handling for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Set GPIO5 as output
    if (gpioSetMode(5, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO5 as output\n");
        gpioTermination();
        return 1;
    }

    // Infinite loop
    while (1) {
        gpioWrite(5, 1);
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(750000);

        gpioWrite(5, 0);
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(750000);
    }

    // Check for SIGINT
    if (sigint_received) {
        gpioWrite(5, 0);
        printf("\nLED turned off on SIGINT\n");
        fflush(stdout);
        gpioTermination();
        exit(0);
    }

    return 0;
}

