#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define LED_GPIO 24
#define BUTTON_GPIO 22

static int led_line;
static int button_line;

static int chip_init(const char *label) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open(label, "GPIO24, GPIO22");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip: %s\n", strerror(errno));
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, "GPIO24");
    button_line = gpiod_chip_get_line(chip, "GPIO22");

    if (!led_line || !button_line) {
        fprintf(stderr, "Failed to get line for GPIO%d or %d\n", LED_GPIO, BUTTON_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_get(led_line, "output");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO%d as output: %s\n", LED_GPIO, strerror(errno));
        gpiod_line_free(led_line);
        gpiod_line_free(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_get(button_line, "input");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO%d as input: %s\n", BUTTON_GPIO, strerror(errno));
        gpiod_line_free(led_line);
        gpiod_line_free(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(led_line, 0);
    gpiod_line_set_value(button_line, 1);
    gpiod_line_set_pull(button_line, GPIO_PUD_DOWN);

    return 0;
}

static void chip_destroy() {
    gpiod_line_free(led_line);
    gpiod_line_free(button_line);
    gpiod_chip_close();
}

static void blink_led() {
    static int led_state = 0;
    int ret;

    ret = gpiod_line_set_value(led_line, led_state);
    if (ret) {
        fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
        return;
    }

    led_state = !led_state;
    usleep(500000);
}

int main(int argc, char *argv[]) {
    int ret;

    ret = chip_init("gpiochip0");
    if (ret) {
        return ret;
    }

    while (1) {
        int button_value = gpiod_line_get_value(button_line);

        if (button_value) {
            printf("Button pressed, starting LED blinking\n");
            while (1) {
                blink_led();
                usleep(500000);
                blink_led();
                usleep(500000);
            }
        } else {
            printf("Button released, LED off\n");
            gpiod_line_set_value(led_line, 0);
        }
    }

    chip_destroy();
    return 0;
}

