#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define RED_GPIO 24
#define GREEN_GPIO 23
#define BLUE_GPIO 18
#define PWM_FREQ 100 // Hz
#define PWM_PERIOD (1000000000 / PWM_FREQ) // nanoseconds

static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;

static void pwm_loop(void *arg) {
    uint64_t last_time = 0;
    while (1) {
        uint64_t now = gpiod_get_current_time();
        if (now - last_time >= PWM_PERIOD / 2) {
            uint8_t r = rand() % 101;
            uint8_t g = rand() % 101;
            uint8_t b = rand() % 101;
            gpiod_line_set_value(red_line, r);
            gpiod_line_set_value(green_line, g);
            gpiod_line_set_value(blue_line, b);
            last_time = now;
        }
        clock_nanosleep(CLOCK_MONOTONIC, 0, &PWM_PERIOD / 10, NULL);
    }
}

static void sigint_handler(int signum) {
    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_release(chip);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_GPIO);
    if (!red_line) {
        fprintf(stderr, "Failed to get line for GPIO%d\n", RED_GPIO);
        gpiod_chip_release(chip);
        return 1;
    }
    if (gpiod_line_request_output(red_line) < 0) {
        fprintf(stderr, "Failed to request output for GPIO%d\n", RED_GPIO);
        gpiod_line_release(red_line);
        gpiod_chip_release(chip);
        return 1;
    }

    green_line = gpiod_chip_get_line(chip, GREEN_GPIO);
    if (!green_line) {
        fprintf(stderr, "Failed to get line for GPIO%d\n", GREEN_GPIO);
        gpiod_line_release(red_line);
        gpiod_chip_release(chip);
        return 1;
    }
    if (gpiod_line_request_output(green_line) < 0) {
        fprintf(stderr, "Failed to request output for GPIO%d\n", GREEN_GPIO);
        gpiod_line_release(green_line);
        gpiod_chip_release(chip);
        return 1;
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_GPIO);
    if (!blue_line) {
        fprintf(stderr, "Failed to get line for GPIO%d\n", BLUE_GPIO);
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_chip_release(chip);
        return 1;
    }
    if (gpiod_line_request_output(blue_line) < 0) {
        fprintf(stderr, "Failed to request output for GPIO%d\n", BLUE_GPIO);
        gpiod_line_release(blue_line);
        gpiod_line_release(red_line);
        gpiod_chip_release(chip);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpiod_line_set_value(red_line, 0);
    gpiod_line_set_value(green_line, 0);
    gpiod_line_set_value(blue_line, 0);

    pthread_t pwm_thread;
    pthread_create(&pwm_thread, NULL, pwm_loop, NULL);

    pthread_join(pwm_thread, NULL);

    return 0;
}

