#include <signal.h>
#include <pigio.h>

#define I2C_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define PWM_PIN 18
#define SAMPLE_INTERVAL 500000 // 500 ms
#define RETRY_DELAY 100000 // 100 ms

pigpio *giopio;
FILE *csv_file;

void i2c_error_handler(const char *msg) {
    fprintf(stderr, "I2C Error: %s\n", msg);
}

uint16_t read_i2c_register(uint8_t reg) {
    uint16_t val = 0;
    int ret;

    ret = pigpio_i2c_write(giopio, I2C_ADDR, &reg, 1);
    if (ret < 0) {
        i2c_error_handler("Failed to write register address");
        return 0;
    }

    ret = pigpio_i2c_read(giopio, I2C_ADDR, &val, 2);
    if (ret < 0) {
        i2c_error_handler("Failed to read register data");
        return 0;
    }

    return val;
}

void init_gpio() {
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
}

void cleanup_gpio() {
    pigpio_terminate();
}

void sample_and_log() {
    uint16_t als, red, green, blue;
    time_t now;

    als = (read_i2c_register(ALS_LSB_REG) << 8) | read_i2c_register(ALS_MSB_REG);
    red = read_i2c_register(RED_REG);
    green = read_i2c_register(GREEN_REG);
    blue = read_i2c_register(BLUE_REG);

    now = time(NULL);
    fprintf(csv_file, "%ld,%d,%d,%d\n", now, als, red, green);

    uint16_t pwm_duty = als / 4; // Map ALS to PWM duty cycle (0-255)
    gpioSetPWMduty(PWM_PIN, pwm_duty);
}

void sigint_handler(int signum) {
    cleanup_gpio();
    pigpio_stop();
    fclose(csv_file);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    giopio = pigpio_initialise();
    if (!giopio) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (pigpio_set_mode(giopio, I2C_ADDR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (pigpio_i2c_write(giopio, I2C_ADDR, &MODE_REG, 1) < 0) {
        fprintf(stderr, "Failed to write MODE register\n");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    csv_file = fopen("color_log.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "Time,ALS,Red,Green,Blue\n");

    init_gpio();

    while (1) {
        sample_and_log();
        sleep(SAMPLE_INTERVAL);
    }

    cleanup_gpio();
    pigpio_stop();
    fclose(csv_file);
    return 0;
}

