    gpioInitialise();
    if (gpioI2CInitialise(1) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus 1\n");
        goto exit_cleanup;
    }

    if (gpioI2CWrite(I2C_ADDR, 0x0D, &WHO_AM_I, 1) != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
    }
    int who_am_i = gpioI2CRead(I2C_ADDR, 0x0D, 1);
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Sensor ID mismatch: expected 0xC7, got 0x%02X\n", who_am_i);
        goto exit_cleanup;
    }

    gpioI2CWrite(I2C_ADDR, XYZ_DATA_CFG, &0x00, 1);
    gpioI2CWrite(I2C_ADDR, CTRL_REG1, &0x2A, 1);

