    if (!fp) {
        fprintf(stderr, "Failed to open impact_log.txt\n");
        goto exit_cleanup;
    }

    while (1) {
        int16_t x, y, z;
        if (gpioI2CRead(I2C_ADDR, OUT_X_MSB, 6, &x, &y, &z) != 6) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
