        x >>= 2;
        y >>= 2;
        z >>= 2;
        double ax = x * SENSITIVITY / 100.0;
        double ay = y * SENSITIVITY / 100.0;
        double az = z * SENSITIVITY / 100.0;
        double magnitude = sqrt(ax * ax + ay * ay + az * az);

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, ax, ay, az, magnitude);

        gpioDelay(SAMPLING_INTERVAL);
    }

exit_cleanup:
    gpioTerminate();
    if (fp) fclose(fp);
    return 0;
}

