#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define SENSITIVITY 0.00875
#define CALIBRATION_SAMPLES 100
#define LOG_PERIOD_MS 50
#define MAX_DPS 50

int i2c_fd = -1;
FILE *log_file = NULL;
int calibration_samples = 0;
int64_t calibration_offsets[3] = {0};
uint8_t buffer[7];

void calibrate() {
    int64_t sum_x = 0, sum_y = 0, sum_z = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR);
        buffer[0] = OUT_X_L;
        ioctl(i2c_fd, I2C_RDWR, buffer + 1);
        sum_x += ((int16_t)(buffer[1] << 8 | buffer[2])) >> 4;
        sum_y += ((int16_t)(buffer[3] << 8 | buffer[4])) >> 4;
        sum_z += ((int16_t)(buffer[5] << 8 | buffer[6])) >> 4;
        usleep(10000); // 100 Hz
    }
    calibration_offsets[0] = sum_x / CALIBRATION_SAMPLES;
    calibration_offsets[1] = sum_y / CALIBRATION_SAMPLES;
    calibration_offsets[2] = sum_z / CALIBRATION_SAMPLES;
}

int main() {
    int ret;
    struct gi1000_chip chip;
    struct gpiod_chip gpiod_chip;
    gpiod_chip_init();

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, NULL) < 0) {
        perror("Failed to init I2C");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &chip) < 0) {
        perror("Failed to get chip info");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &chip.reg_hw_addr) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

