#define Z_LSB 5

int main() {
    int fd;
    gpioInitialise();
    if ((fd = wiringPiI2CSetup(1)) < 0) {
        fprintf(stderr, "I2C setup failed\n");
        return 1;
    }

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (i2c_rdwr_start(fd) < 0) {
        fprintf(stderr, "I2C start failed\n");
        return 1;
    }

    if (i2c_write_byte(fd, ADXL345_ADDR << 1) < 0) {
        fprintf(stderr, "Failed to write address\n");
        return 1;
    }

    if (i2c_rdwr(fd, 1, (uint8_t *)&devid, 1) != 1) {
        fprintf(stderr, "Failed to read DEVID register\n");
        return 1;
    }

    if (devid[0] != 0xE5) {
        fprintf(stderr, "Invalid DEVID\n");
        return 1;
    }

    if (i2c_rdwr_restart(fd) < 0) {
        fprintf(stderr, "I2C restart failed\n");
        return 1;
    }

    if (i2c_write_byte(fd, 0x00 << 1)) {
        fprintf(stderr, "Failed to write to 0x00 register\n");
        return 1;
    }

    if (i2c_rdwr(fd, 1, (uint8_t *)&data, 6) != 6) {
        fprintf(stderr, "Failed to read 6 bytes from registers 0x32-0x37\n");
        return 1;
    }

    FILE *log_file = fopen("accel_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    while (1) {
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&now));

        printf("%s, %.3f, %.3f, %.3f\n", timestamp, data[X_MSB] / 16.0, data[Y_MSB] / 16.0, data[Z_MSB] / 16.0);
        fprintf(log_file, "%s, %.3f, %.3f, %.3f\n", timestamp, data[X_MSB] / 16.0, data[Y_MSB] / 16.0, data[Z_MSB] / 16.0);

        double abs_accel = sqrt(pow(data[X_MSB] / 16.0, 2) + pow(data[Y_MSB] / 16.0, 2) + pow(data[Z_MSB] / 16.0, 2));
        if (abs_accel > 2.0) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        pigpio_delay(100000); // 100 ms delay
    }

    gpioTerminate();
    pigpio_terminate();
    fclose(log_file);

    return 0;
}

