void init_i2c(int bus) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(bus, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C bus %d as output.\n", bus);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c(int bus) {
    gpioTerminate();
}

