    if (gpioI2CWrite(bus, LSM303_ACCEL_ADDR, ACCEL_CTRL_REG1, 0x27) < 0) {
        fprintf(stderr, "Failed to configure accelerometer.\n");
        exit(EXIT_FAILURE);
    }
}

void configure_mag(int bus) {
    if (gpioI2CWrite(bus, LSM303_MAG_ADDR, MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to configure magnetometer.\n");
        exit(EXIT_FAILURE);
    }
}

