    if (gpioI2CRead(bus, LSM303_ACCEL_ADDR, ACCEL_OUT_X_L_A, 3, (uint8_t *)accel) < 3) {
        fprintf(stderr, "Failed to read accelerometer data.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioI2CRead(bus, LSM303_MAG_ADDR, MAG_OUT_X_H_M, 3, (uint8_t *)mag) < 3) {
        fprintf(stderr, "Failed to read magnetometer data.\n");
        exit(EXIT_FAILURE);
    }
}

