    SensorData sensor_data;
    Vector3i16 accel, mag;
    struct timespec ts;

    init_i2c(bus);
    configure_accel(bus);
    configure_mag(bus);

    if ((log_file = fopen("compass_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup_i2c(bus);
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) != 0) {
        fprintf(stderr, "Failed to seek end of log file.\n");
        fclose(log_file);
        cleanup_i2c(bus);
        return EXIT_FAILURE;
    }

    if (feof(log_file)) {
        fprintf(log_file, "%s", log_header);
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        sensor_data.heading = calculate_heading(accel, mag);

        printf(
            "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000),
            sensor_data.heading,
            sensor_data.acceleration.x / 16.0,
            sensor_data.acceleration.y / 16.0,
            sensor_data.acceleration.z / 16.0,
            mag.x / 4096.0,
            mag.y / 4096.0,
            mag.z / 4096.0
        );

        fflush(stdout);

        read_accel_mag(bus, &accel, &mag);
        sleep(SAMPLE_INTERVAL);

        if (gpioReceivedSignal(0)) { // Check for SIGINT/SIGTERM
            break;
        }
    }

    cleanup_i2c(bus);
    fclose(log_file);

    return EXIT_SUCCESS;
}

