#define REG_RANGE_STATUS 0x04d
#define SAMPLE_INTERVAL 100000 // 100 ms
#define LOG_FILE "distance_log.txt"

void init_i2c(void);
void init_vl6180x(void);
uint16_t read_register(uint8_t reg_addr);
void log_reading(uint16_t distance);

int main(void) {
    gpioInitialise();
    init_i2c();
    init_vl6180x();

    const clock_t start_time = clock();
    while (1) {
        uint16_t distance = read_range();
