#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <pigpio.h>

#define SENSOR_ADDR1 0x68
#define SENSOR_ADDR2 0x69
#define REG_DATA 0x01
#define REG_CTRL 0x00
#define CTRL_ENABLE 0x80
#define SAMPLING_INTERVAL (10 * 1000 * 1000) // 10 ms

static FILE *log_file = NULL;
static int gpio_initialized = 0;

void sigint_handler(int signum) {
    gpioStop();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(signum == SIGINT);
}

int main() {
    struct timespec ts;
    int ret;
    long sample1, sample2, tdoa;
    int fd;

    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    gpio_initialized = 1;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (i2c_rdwr_setup(fd, SENSOR_ADDR1) < 0) {
        perror("Failed to setup I2C communication with sensor 1");
        return 1;
    }

    if (i2c_rdwr_setup(fd, SENSOR_ADDR2) < 0) {
        perror("Failed to setup I2C communication with sensor 2");
        return 1;
    }

    log_file = fopen("audio_log.dat", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);

        sample1 = i2c_rdwr_get_dma(fd, REG_DATA, NULL, 2);
        if (sample1 == -2) {
            fprintf(stderr, "Sensor 1 not responding, retrying...\n");
            continue;
        }
        sample1 = (int16_t)((sample1 >> 8) | (sample1 << 8));

        sample2 = i2c_rdwr_get_dma(fd, REG_DATA, NULL, 2);
        if (sample2 == -2) {
            fprintf(stderr, "Sensor 2 not responding, retrying...\n");
            continue;
        }
        sample2 = (int16_t)((sample2 >> 8) | (sample2 << 8));

        tdoa = sample2 - sample1;

        fprintf(log_file, "%ld,%ld,%d,%d,%d\n",
                ts.tv_sec, ts.tv_nsec, sample1, sample2, tdoa);

        usleep(SAMPLING_INTERVAL);
    }

    gpioStop();
    close(fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

