#define ADIS16488_SPI_FLAGS 0b11000000000
#define ADIS16488_GYRO_X_REG 0x04
#define ADIS16488_GYRO_Y_REG 0x06
#define ADIS16488_GYRO_Z_REG 0x08
#define ADIS16488_ACCEL_X_REG 0x0A
#define ADIS16488_ACCEL_Y_REG 0x0C
#define ADIS16488_ACCEL_Z_REG 0x0E

#define GYRO_SENS 0.005f
#define ACCEL_SENS 0.00025f

static FILE *csv_file = NULL;
static int running = 1;

static void cleanup() {
    gpioTerminate();
    if (csv_file) {
        fclose(csv_file);
        csv_file = NULL;
    }
    at_exit(cleanup);
}

static int spiXfer(uint8_t tx_buf[], uint8_t rx_buf[], uint32_t len) {
    static int spi_handle;
    int ret;

    if (spi_handle == 0) {
        spi_handle = spiOpen(ADIS16488_SPI_CHANNEL, 1000000);
        if (spi_handle < 0) {
            fprintf(stderr, "Error opening SPI channel\n");
            return -1;
        }
        gpioSetMode(ADIS16488_CE0_GPIO, pigpio.gpioInitialise, pigpio.piPinOutput);
    }

    ret = spiWriteRead(spi_handle, tx_buf, rx_buf, len, ADIS16488_SPI_FLAGS);
    if (ret < 0) {
        fprintf(stderr, "Error during SPI transfer\n");
    }
    return ret;
}

static void sample_imu() {
    uint8_t tx_buf[2] = {0x00, 0x00};
    uint8_t rx_buf[2];
    int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    // Read gyroscope X
    tx_buf[0] = ADIS16488_GYRO_X_REG;
    spiXfer(tx_buf, rx_buf, sizeof(rx_buf));
    gyro_x = (int16_t)rx_buf[1];

    // Stall for 40 microseconds
    usleep(40000);

    // Read gyroscope Y
    tx_buf[0] = ADIS16488_GYRO_Y_REG;
    spiXfer(tx_buf, rx_buf, sizeof(rx_buf));
    gyro_y = (int16_t)rx_buf[1];

    // Read gyroscope Z
    tx_buf[0] = ADIS16488_GYRO_Z_REG;
    spiXfer(tx_buf, rx_buf, sizeof(rx_buf));
    gyro_z = (int16_t)rx_buf[1];

    // Read accelerometer X
    tx_buf[0] = ADIS16488_ACCEL_X_REG;
    spiXfer(tx_buf, rx_buf, sizeof(rx_buf));
    accel_x = (int16_t)rx_buf[1];

    // Read accelerometer Y
    tx_buf[0] = ADIS16488_ACCEL_Y_REG;
    spiXfer(tx_buf, rx_buf, sizeof(rx_buf));
    accel_y = (int16_t)rx_buf[1];

    // Read accelerometer Z
    tx_buf[0] = ADIS16488_ACCEL_Z_REG;
    spiXfer(tx_buf, rx_buf, sizeof(rx_buf));
    accel_z = (int16_t)rx_buf[1];

    // Print the sample with a timestamp
    time_t t;
    struct tm tm;
    time(&t);
    localtime_r(&t, &tm);

    fprintf(csv_file, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)(tm.tm_sec + tm.tm_min * 60 + tm.tm_hour * 3600),
            gyro_x * GYRO_SENS, gyro_y * GYRO_SENS, gyro_z * GYRO_SENS,
            accel_x * ACCEL_SENS, accel_y * ACCEL_SENS, accel_z * ACCEL_SENS);
}

int main(int argc, char *argv[]) {
    gpioInitialise();
    atexit(cleanup);

    if ((csv_file = fopen("imu_data.csv", "w")) == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        return 1;
    }

    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    while (running) {
        sample_imu();

        // Check every 10 ms if the running flag has changed
        gpioSetMode(getpid(), pigpio.gpioInitialise, pigpio.piPinInput);
        if (gpioRead(getpid()) == 0) {
            running = 0;
        }
        usleep(10000);
    }

    spiClose(spi_handle);
    return 0;
}

