#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define ADIS16448_SPI_BUS 0
#define ADIS16448_SPI_DEVICE 0
#define ADIS16448_CS_GPIO 8
#define ADIS16448_SPI_MODE 3

#define REG_XGyroOut 0x04
#define REG_YGyroOut 0x06
#define REG_ZGyroOut 0x08
#define REG_XAcclOut 0x0A
#define REG_YAcclOut 0x0C
#define REG_ZAcclOut 0x0E

#define SCALE_GYRO 0.02
#define SCALE_ACCEL 0.00025

static int spi_fd;
static int cs_chip;

static int spi_init() {
    spi_fd = open("/dev/spidev" WRITE_ONLY, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_WRITER_DUART, 0) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int cs_init() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(ADIS16448_CS_GPIO, "ADIS16448_CS");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, "ADIS16448_CS");
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_export(line, NULL);
    gpiod_line_set_direction(line, GPIO_OUT);

    return 0;
}

static void spi_deinit() {
    close(spi_fd);
    spi_fd = -1;

    gpiod_line_free(cs_chip->lines[0]);
    gpiod_chip_close(cs_chip);
}

static uint16_t spi_transfer(uint8_t reg_addr) {
    struct spi_transfer spi_txrx[2];

    spi_txrx[0].tx_buf = &reg_addr;
    spi_txrx[0].bits_per_word = 8;
    spi_txrx[0].delay_usecs = 0;
    spi_txrx[0].speed_hz = 1000000;
    spi_txrx[0].bits = SPI_TRANSFER_WORD | SPI_TRANSFER_MSBFIRST;

    spi_txrx[1].rx_buf = (uint8_t *)&spi_txrx[1].rx_buf;
    spi_txrx[1].bits_per_word = 16;
    spi_txrx[1].delay_usecs = 0;
    spi_txrx[1].speed_hz = 1000000;
    spi_txrx[1].bits = SPI_TRANSFER_WORD | SPI_TRANSFER_MSBFIRST;

    if (ioctl(spi_fd, SPI_IO_WRITEN, spi_txrx) != 2) {
        perror("SPI transfer failed");
        return -1;
    }

    return (spi_txrx[1].rx_buf[0] << 8) | spi_txrx[1].rx_buf[1];
}

static float read_gyro_x() {
    uint16_t raw_gyro_x = spi_transfer(REG_XGyroOut);
    return raw_gyro_x * SCALE_GYRO;
}

static float read_gyro_y() {
    uint16_t raw_gyro_y = spi_transfer(REG_YGyroOut);
    return raw_gyro_y * SCALE_GYRO;
}

static float read_gyro_z() {
    uint16_t raw_gyro_z = spi_transfer(REG_ZGyroOut);
    return raw_gyro_z * SCALE_GYRO;
}

static float read_accel_x() {
    uint16_t raw_accel_x = spi_transfer(REG_XAcclOut);
    return raw_accel_x * SCALE_ACCEL;
}

static float read_accel_y() {
