#include <sys/ioctl.h>
#include <errno.h>

#define TDK_MPU_6886_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x21
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define ACCEL_XOUT_H_REG 0x3B
#define ACCEL_XOUT_L_REG 0x3C
#define ACCEL_YOUT_H_REG 0x3D
#define ACCEL_YOUT_L_REG 0x3E
#define ACCEL_ZOUT_H_REG 0x3F
#define ACCEL_ZOUT_L_REG 0x40
#define GYRO_XOUT_H_REG 0x43
#define GYRO_XOUT_L_REG 0x44
#define GYRO_YOUT_H_REG 0x45
#define GYRO_YOUT_L_REG 0x46
#define GYRO_ZOUT_H_REG 0x47
#define GYRO_ZOUT_L_REG 0x48

int main() {
    int file;
    char filename[20] = "/dev/i2c-1";
    struct i2c_rdwr_ioctl_data rdwr;
    int retry_count = 3;
    int ret;

    file = open(filename, O_RDWR);
    if (file < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, TDK_MPU_6886_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Verify sensor is present
    rdwr.u.rd = (struct i2c_rdwr_regs) {
        .regs2be = { WHO_AM_I_REG, 1 },
    };
    if (ioctl(file, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to read WHO_AM_I register");
        goto err_close;
    }

    if (rdwr.len != 1 || rdwr.buf[0] != 0x86) {
        fprintf(stderr, "Sensor not present or incorrect\n");
        goto err_close;
    }

    // Initialize sensor
    rdwr.u.wr = (struct i2c_rdwr_regs) {
        .regs2be = { PWR_MGMT_1_REG, 1, 0x00 },
    };
    if (ioctl(file, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to write PWR_MGMT_1 register");
        goto err_close;
    }

    rdwr.u.wr = (struct i2c_rdwr_regs) {
        .regs2be = { ACCEL_CONFIG_REG, 1, 0x00 },
    };
    if (ioctl(file, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to write ACCEL_CONFIG register");
        goto err_close;
    }

    rdwr.u.wr = (struct i2c_rdwr_regs) {
        .regs2be = { GYRO_CONFIG_REG, 1, 0x00 },
    };
    if (ioctl(file, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to write GYRO_CONFIG register");
        goto err_close;
    }

    while (1) {
        for (int i = 0; i < retry_count; ++i) {
            rdwr.u.rd = (struct i2c_rdwr_regs) {
                .regs2be = { ACCEL_XOUT_H_REG, 2 },
            };
            if (ioctl(file, I2C_RDWR, &rdwr) == 2) {
                int16_t accel_x = ((int16_t)rdwr.buf[1] << 8) | rdwr.buf[0];
                int16_t accel_y = ((int16_t)rdwr.buf[3] << 8) | rdwr.buf[2];
                int16_t accel_z = ((int16_t)rdwr.buf[5] << 8) | rdwr.buf[4];
                printf("Accelerometer: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
                break;
            } else if (errno != EAGAIN) {
                fprintf(stderr, "Failed to read accelerometer data, retrying...\n");
                close(file);
                return 1;
            }
        }

        for (int i = 0; i < retry_count; ++i) {
            rdwr.u.rd = (struct i2c_rdwr_regs) {
                .regs2be = { GYRO_XOUT_H_REG, 2 },
            };
            if (ioctl(file, I2C_RDWR, &rdwr) == 2) {
                int16_t gyro_x = ((int16_t)rdwr.buf[1] << 8) | rdwr.buf[0];
                int16_t gyro_y = ((int16_t)rdwr.buf[3] << 8) | rdwr.buf[2];
                int16_t gyro_z = ((int16_t)rdwr.buf[5] << 8) | rdwr.buf[4];
                printf("Gyroscope: X=%d, Y=%d, Z=%d\n", gyro_x, gyro_y, gyro_z);
                break;
            } else if (errno != EAGAIN) {
                fprintf(stderr, "Failed to read gyroscope data, retrying...\n");
                close(file);
                return 1;
            }
        }

        usleep(50000);
    }

err_close:
    close(file);
    return 0;
}

