    if (pigpio_i2c_write(i2c_fd, I2C_ADDR, (void *)device_id, strlen(device_id)) < 0) {
        fprintf(stderr, "Failed to write to ADXL345 register 0x00\n");
        pigpio_close(i2c_fd, 1);
        return 1;
    }

    uint8_t buf[6];
