        fprintf(stderr, "Failed to read from ADXL345 register 0x00\n");
        pigpio_close(i2c_fd, 1);
        return 1;
    }

    if (memmem(device_id, strlen(device_id), buf, 6) == NULL) {
        fprintf(stderr, "ADXL345 device ID mismatch\n");
        pigpio_close(i2c_fd, 1);
        return 1;
    }

    printf("ADXL345 detected and configured\n");

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_close(i2c_fd, 1);
        gpioTerminate();
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double magnitude;
        uint16_t x, y, z;

        if (pigpio_i2c_read(i2c_fd, I2C_ADDR, (void *)&x, 2) < 0 ||
            pigpio_i2c_read(i2c_fd, I2C_ADDR, (void *)&y, 2) < 0 ||
