            fprintf(stderr, "Failed to read from ADXL345 registers\n");
            break;
        }

        magnitude = sqrt((x * x) + (y * y) + (z * z)) / 256.0;

        if (magnitude > IMPACT_THRESHOLD_G) {
            gpioWrite(LED_PIN, 1);
            clock_gettime(CLOCK_MONOTONIC, &ts);
            fprintf(log_file, "%ld.%06ld: %f g (%d %d %d)\n",
