            sleep_ms(LED_ON_TIME_MS);
            gpioWrite(LED_PIN, 0);
        }

        usleep(CHECK_INTERVAL_MS * 1000);
    }

    pigpio_close(i2c_fd, 1);
    gpioTerminate();
    return 0;
