#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define TMAG5273_ADDR 0x35
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12
#define SAMPLE_INTERVAL 1

int i2c_fd = -1;
FILE *csv_file = NULL;

void log_data(int x, int y, int z) {
    static char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    if (csv_file == NULL) {
        csv_file = fopen("magnetic_field_log.csv", "w");
        if (csv_file == NULL) {
            perror("Failed to open CSV file");
            exit(EXIT_FAILURE);
        }
        fprintf(csv_file, "Time,X,Y,Z\n");
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(csv_file);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (i2c_fd != -1) {
            close(i2c_fd);
            i2c_fd = -1;
        }
        if (csv_file != NULL) {
            fclose(csv_file);
            csv_file = NULL;
        }
        exit(0);
    }
}

int main() {
    struct i2c_rdwr_ioctl_data rdwr;
    struct i2c_msg messages[2];
    int ret;

    key_t key = ftok("magnetic_field_log.csv", 65);
    if (key == -1) {
        perror("ftok");
        exit(EXIT_FAILURE);
    }

    if (mkfifo("magnetic_field_fifo", 0666) == -1) {
        perror("mkfifo");
        exit(EXIT_FAILURE);
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("open i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    rdwr.u.rd = (struct i2c_rdwr_desc) {
        .addr = i2c_fd,
        .flags = 0,
        .len = 2,
        .buf = &messages[0].len,
        .buf_len = 2,
    };

    messages[0].len = 1;
    messages[0].flags = 0;
    messages[0].addr = TMAG5273_ADDR;
    messages[0].buf = (unsigned char *) &X_REG;

    messages[1].len = 1;
    messages[1].flags = 0;
    messages[1].addr = TMAG5273_ADDR;
    messages[1].buf = (unsigned char *) &Y_REG;

    if ((ret = ioctl(i2c_fd, I2C_RDWR(rdwr))) < 0) {
        perror("I2C_RDWR");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    rdwr.u.wr = (struct i2c_rdwr_desc) {
        .addr = i2c_fd,
        .flags = 0,
        .len = 2,
        .buf = &messages[1].len,
        .buf_len = 2,
    };

    if ((ret = ioctl(i2c_fd, I2C_RDWR(rdwr))) < 0) {
        perror("I2C_RDWR");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    rdwr.u.wr = (struct i2c_rdwr_desc) {
        .addr = i2c_fd,
        .flags = 0,
        .len = 2,
        .buf = &messages[2].len,
        .buf_len = 2,
    };

    messages[2].len = 1;
    messages[2].flags = 0;
    messages[2].addr = TMAG5273_ADDR;
    messages[2].buf = (unsigned char *) &Z_REG;

    if ((ret = ioctl(i2c_fd, I2C_RDWR(rdwr))) < 0) {
        perror("I2C_RDWR");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    close(i2c_fd);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        sleep(SAMPLE_INTERVAL);

        if (i2c_fd != -1 && csv_file != NULL) {
            log_data(*(int16_t *)messages[0].buf, *(int16_t *)messages[1].buf, *(int16_t *)messages[2].buf);
        }
    }

    return 0;
}

