#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define FREEFALL_THRESH 0.2f
#define IMPACT_THRESH 2.5f
#define FALL_WINDOW_MS 1000

enum { IDLE, FREEFALL, IMPACT };
static enum state current_state = IDLE;
static float last_accel_mag = 0;
static time_t last_impact_time = 0;

static void init_i2c(int bus, int sda, int scl) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library.\n");
        exit(EXIT_FAILURE);
    }
    if (piGiocontrol(bus, GPIO_OUTPUT, sda) < 0 || piGiocontrol(bus, GPIO_OUTPUT, scl) < 0) {
        fprintf(stderr, "Failed to set I2C pins.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

static void cleanup_i2c() {
    gpioTerminate();
}

static int read_accel_data(int bus, int sda, int scl, float *x, float *y, float *z) {
    struct spi_buf spi_buf;
    spi_buf.buf[0] = LSM6DSR_ADDR << 1;
    spi_buf.buf[1] = (LSM6DSR_ADDR >> 5) | 0x80; // WHO_AM_I register
    spi_buf.len = 2;

    if (piSpiTransfer(bus, sda, scl, &spi_buf) < 0) {
        fprintf(stderr, "I2C read error.\n");
        return -1;
    }

    if (spi_buf.buf[1] != 0x68) { // WHO_AM_I check
        fprintf(stderr, "Sensor not detected.\n");
        return -1;
    }

    spi_buf.buf[1] = LSM6DSR_ADDR << 1 | 0x20; // OUT_X_L_G register
    spi_buf.len = 1;

    if (piSpiTransfer(bus, sda, scl, &spi_buf) < 0) {
        fprintf(stderr, "I2C read error.\n");
        return -1;
    }

    *x = (float)((spi_buf.buf[0] << 8) | spi_buf.buf[1]);
    *x /= 16384.0f; // Convert to g

    spi_buf.buf[1] = LSM6DSR_ADDR << 1 | 0x22; // OUT_Y_L_G register
    piSpiTransfer(bus, sda, scl, &spi_buf);

    *y = (float)((spi_buf.buf[0] << 8) | spi_buf.buf[1]);
    *y /= 16384.0f; // Convert to g

    spi_buf.buf[1] = LSM6DSR_ADDR << 1 | 0x24; // OUT_Z_L_G register
    piSpiTransfer(bus, sda, scl, &spi_buf);

    *z = (float)((spi_buf.buf[0] << 8) | spi_buf.buf[1]);
    *z /= 16384.0f; // Convert to g

    return 0;
}

int main(int argc, char *argv[]) {
    int bus = 1, sda = 2, scl = 3;
    float x, y, z;
    time_t curr_time;
    char timestamp[20];

    init_i2c(bus, sda, scl);

    FILE *log_file = fopen("motion_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup_i2c();
        return EXIT_FAILURE;
    }

    while (1) {
        curr_time = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&curr_time));

        if (read_accel_data(bus, sda, scl, &x, &y, &z)) {
            fprintf(stderr, "I2C read error.\n");
            break;
        }

        float accel_mag = sqrt(x * x + y * y + z * z);

        switch (current_state) {
            case IDLE:
                if (accel_mag < FREEFALL_THRESH) {
                    current_state = FREEFALL;
                }
                break;
            case FREEFALL:
                if (accel_mag > FREEFALL_THRESH) {
                    curr_time = time(NULL);
                    if (curr_time - last_impact_time > FALL_WINDOW_MS) {
                        current_state = IDLE;
                    } else {
                        last_accel_mag = accel_mag;
                    }
                } else {
                    current_state = IDLE;
                }
                break;
            case IMPACT:
                if (accel_mag < IMPACT_THRESH) {
                    current_state = IDLE;
                }
                break;
        }

        fprintf(log_file, "%s,Accel X: %.3f,Accel Y: %.3f,Accel Z: %.3f,State: %d\n",
                timestamp, x, y, z, current_state);

        usleep(104000); // 104 Hz ODR
    }

    cleanup_i2c();
    fclose(log_file);
    return 0;
}

