#define ADIS16266_ADDR 0x1E
#define X_GYRO_OUT 0x14
#define SPI_MODE 3
#define CPOL 1
#define CPHA 1
#define SPI_SPEED_HZ 1000000
#define READ_INTERVAL_MS 10

static const char *log_file = "gyro_log.csv";
static FILE *log_fp = NULL;

void log_timestamp(const char *format, ...) {
    time_t now;
    struct tm *time_struct;
    char timestamp[64];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    fprintf(log_fp, "%s,", timestamp);
}

int main() {
    int spi_fd;
    int ret;
    gpioInitialise();
    pigpio spi_init;

    spi_fd = gpioInitialiseSPI(0, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI channel 0\n");
        return 1;
    }

    spi_init = pigpio_SPI_open(ADIS16266_ADDR, spi_fd, CPOL, CPHA, SPI_SPEED_HZ);
    if (spi_init < 0) {
        fprintf(stderr, "Failed to open SPI with pigpio\n");
        gpioTerminate();
        return 1;
    }

    if (pigpio_SPI_write(spi_init, 0x00 | X_GYRO_OUT) != 1) {
        fprintf(stderr, "Failed to write to X_GYRO_OUT register\n");
        pigpio_SPI_close(spi_init);
        gpioTerminate();
        return 1;
