#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x24
#define OUT_X_L 0x28
#define WHO_AM_I 0xD3

#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_MS 10

static int i2c_fd = -1;
static gpio *gpio = NULL;
FILE *log_file = NULL;

void init_i2c() {
    if ((i2c_fd = i2c_open(0)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (i2c_write(i2c_fd, GYRO_ADDR, CTRL_REG1, &0x0F, 1) != 1) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        exit(EXIT_FAILURE);
    }

    if (i2c_write(i2c_fd, GYRO_ADDR, CTRL_REG4, &0x00, 1) != 1) {
        fprintf(stderr, "Failed to write CTRL_REG4\n");
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, GYRO_ADDR, OUT_X_L, 6, NULL) != 6) {
        fprintf(stderr, "Failed to read OUT_X_L\n");
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, GYRO_ADDR, WHO_AM_I, 1, &read_value) != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I\n");
        exit(EXIT_FAILURE);
    }

    if (read_value != 0xD3) {
        fprintf(stderr, "Invalid WHO_AM_I register value\n");
        exit(EXIT_FAILURE);
    }
}

int read_gyro_data(uint8_t *data) {
    if (i2c_read(i2c_fd, GYRO_ADDR, OUT_X_L, 6, data) != 6) {
        return -1;
    }
    return 0;
}

void log_sample(uint8_t timestamp, int x, int y, int z) {
    if (log_file == NULL) {
        log_file = fopen("gyro_log.csv", "w");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t timestamp_ns = ts.tv_sec * 1000000000ULL + ts.tv_nsec;

    fprintf(log_file, "%llu,%d,%d,%d\n", timestamp_ns, x, y, z);
    fflush(log_file);
}

void sigint_handler(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    gpio = gpioInitialise(0);
    if (gpio == NULL) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    init_i2c();

    while (1) {
        uint8_t data[6];
        int retries = 0;

        while (retries < MAX_RETRIES) {
            if (read_gyro_data(data) == 0) {
                break;
            }
            retries++;
            sleep(1);
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read gyro data after %d retries\n", MAX_RETRIES);
            break;
        }

        int16_t x = (int16_t)((data[0] << 8) | data[1]);
        int16_t y = (int16_t)((data[2] << 8) | data[3]);
        int16_t z = (int16_t)((data[4] << 8) | data[5]);

        double gx = x * 8.75 / 114.285;
        double gy = y * 8.75 / 114.285;
        double gz = z * 8.75 / 114.285;

        log_sample(gettimeofday(), (int)gx, (int)gy, (int)gz);

        sleep(SAMPLE_INTERVAL_MS / 1000);
    }

    gpioTerminate();
    return 0;
}

