            fprintf(stderr, "Error reading sensor: %d\n", sensor_value);
            continue;
        }

        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        if (sensor_value == 0) {
