#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define OMRON_D7S_ADDR 0x53
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D

#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds

struct i2c_rdwr_ctrlg ctrl;
struct i2c_rdwr_data data;

int i2c_read(int file, unsigned char reg_addr, char *buf, int len) {
    ctrl.ctrl_len = 1;
    ctrl.addr = OMRON_D7S_ADDR;
    ctrl.reg = reg_addr;
    data.len = len;
    data.buf = buf;

    if (ioctl(file, I2C_RDWR, &ctrl) < 0) {
        perror("I2C read error");
        return -1;
    }

    return 0;
}

int main() {
    int fd, res;
    char buf[3];
    FILE *fp;
    struct timespec ts;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OMRON_D7S_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(fd);
        return EXIT_FAILURE;
    }

    fp = fopen("vibration_log.csv", "w");
    if (!fp) {
        perror("Failed to open CSV file");
        close(fd);
        return EXIT_FAILURE;
    }

    fprintf(fp, "Timestamp,X,Y,Z\n");

    sigset_t sigset;
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    if (sigprocmask(SIG_BLOCK, &sigset, NULL) == -1) {
        perror("sigprocmask");
        close(fd);
        fclose(fp);
        return EXIT_FAILURE;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(fp, "%ld,%d,%d,%d\n",
                (long)(ts.tv_sec * 1000000 + ts.tv_nsec / 1000),
                (int16_t)((i2c_read(fd, REG_X_LSB, buf, 1) && buf[0] != 0xFF) ?
                        ((buf[0] << 8) | buf[1]) : 0),
                (int16_t)((i2c_read(fd, REG_Y_LSB, buf, 1) && buf[0] != 0xFF) ?
                        ((buf[0] << 8) | buf[1]) : 0),
                (int16_t)((i2c_read(fd, REG_Z_LSB, buf, 1) && buf[0] != 0xFF) ?
                        ((buf[0] << 8) | buf[1]) : 0));

        usleep(SAMPLE_INTERVAL);
    }

    sigdelset(&sigset, SIGINT);
    if (sigprocmask(SIG_UNBLOCK, &sigset, NULL) == -1) {
        perror("sigprocmask");
    }

    fclose(fp);
    close(fd);

    return EXIT_SUCCESS;
}

