#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define LOG_FILE "conveyor_log.txt"
#define CHECK_INTERVAL_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *line1;
static struct gpiod_line *line2;
static FILE *log_file;

void sigint_handler(int signum) {
    gpiod_drain_delete(line1);
    gpiod_drain_delete(line2);
    gpiod_chip_put(chip);
    fclose(log_file);
    exit(0);
