#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1D
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define DATA_RATE_MASK (0x7 << 3)
#define STANDBY_MODE (1 << 0)
#define X_OUT_L 0x01
#define X_OUT_H 0x02
#define Y_OUT_L 0x03
#define Y_OUT_H 0x04
#define Z_OUT_L 0x05
#define Z_OUT_H 0x06
#define GRAVITY 9.81

int i2c_fd = -1;
FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

void cleanup_i2c() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

uint16_t read_register(uint8_t reg_addr) {
    uint8_t msb, lsb;
    if (ioctl(i2c_fd, I2C_RDWR, &reg_addr) < 0) {
        perror("Failed to read register");
        return 0;
    }

    if (read(i2c_fd, &msb, 1) != 1) {
        perror("Failed to read MSB");
        return 0;
    }

    if (read(i2c_fd, &lsb, 1) != 1) {
        perror("Failed to read LSB");
        return 0;
    }

    return (msb << 8) | lsb;
}

int write_register(uint8_t reg_addr, uint16_t value) {
    if (ioctl(i2c_fd, I2C_RDWR, &reg_addr) < 0) {
        perror("Failed to write register");
        return -1;
    }

    if (write(i2c_fd, &value, sizeof(value)) != sizeof(value)) {
        perror("Failed to write value");
        return -1;
    }

    return 0;
}

double compute_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude == 0) {
        return 0;
    }

    return atan2(x, magnitude) * 180 / M_PI;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) {
        return -1;
    }

    if ((log_file = fopen("fall_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        cleanup_i2c();
        return -1;
    }

    if (write_register(WHO_AM_I, 0x2A) < 0) {
        cleanup_i2c();
        return -1;
    }

    uint8_t ctrl_reg1 = read_register(CTRL_REG1);
    ctrl_reg1 &= ~STANDBY_MODE;
    ctrl_reg1 |= DATA_RATE_MASK;
    write_register(CTRL_REG1, ctrl_reg1);

    while (1) {
        int16_t x, y, z;
        x = (read_register(X_OUT_L) << 8) | read_register(X_OUT_H);
        y = (read_register(Y_OUT_L) << 8) | read_register(Y_OUT_H);
        z = (read_register(Z_OUT_L) << 8) | read_register(Z_OUT_H);

        double tilt_angle = compute_tilt_angle(x, y, z);
        if (abs(tilt_angle) > 45) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld: X=%d, Y=%d, Z=%d\n", now, x, y, z);
            fflush(log_file);
        }

        usleep(10000);
    }

    cleanup_i2c();
    fclose(log_file);
    return 0;
}

