#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x1E
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG3 0x22
#define CTRL_REG4 0x24
#define OUT_X_L_G 0x28
#define OUT_Y_L_G 0x2A
#define OUT_Z_L_G 0x2C

#define MAX_RETRIES 3
#define READINGS_PER_SECOND 10
#define SENSITIVITY 0.146
#define METAL_DETECT_THRESHOLD 800

int i2c_fd = -1;
int retries = 0;

void calibrate_and_convert(int16_t x, int16_t y, int16_t z, float *mx, float *my, float *mz) {
    // Apply fixed offset/scale calibration constants here
    *mx = (float)x;
    *my = (float)y;
    *mz = (float)z;

    // Convert to milliGauss
    *mx *= SENSITIVITY;
    *my *= SENSITIVITY;
    *mz *= SENSITIVITY;
}

void log_magnetic_data(float mx, float my, float mz) {
    FILE *log_file = fopen("magnetic_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%f,%f,%f\n", mx, my, mz);
    fflush(log_file);
    fclose(log_file);
}

void check_metal_threshold(float magnitude) {
    if (magnitude > METAL_DETECT_THRESHOLD) {
        fprintf(stderr, "Metal detected! Total field magnitude: %f mG\n", magnitude);
    }
}

int i2c_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or perform i2c transfer");
        return -1;
    }

    if (write(i2c_fd, tx_buf, len) != len) {
        perror("Failed to write to i2c bus");
        return -1;
    }

    if (len > 0 && read(i2c_fd, rx_buf, len) != len) {
        perror("Failed to read from i2c bus");
        return -1;
    }

    return 0;
}

int main() {
    int tx_buf[3], rx_buf[6];
    int ret;
    float mx, my, mz, magnitude;

    i2c_fd = open(DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        return 1;
    }

    for (retries = 0; retries < MAX_RETRIES; retries++) {
        if (i2c_transfer((uint8_t *)&WHO_AM_I, rx_buf, 1) == 0) {
            if (rx_buf[0] == 0x3D) {
                break;
            } else {
                printf("WHO_AM_I register does not match expected value (0x3D).\n");
            }
        }

        if (retries == MAX_RETRIES - 1) {
            printf("Failed to initialize sensor after %d retries.\n", MAX_RETRIES);
            close(i2c_fd);
            return 1;
        }
    }

    uint8_t ctrl_reg1 = 0x70;
    uint8_t ctrl_reg3 = 0x00;
    uint8_t ctrl_reg4 = 0x0C;

    if (i2c_transfer((uint8_t *)&CTRL_REG1, NULL, 0) < 0 ||
        i2c_transfer((uint8_t *)&CTRL_REG3, NULL, 0) < 0 ||
        i2c_transfer((uint8_t *)&CTRL_REG4, NULL, 0) < 0) {
        printf("Failed to configure sensor registers.\n");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }
    fprintf(log_file, "Time,X(mG),Y(mG),Z(mG)\n");

    while (1) {
        if (i2c_transfer((uint8_t *)&OUT_X_L_G, tx_buf, 0) < 0 ||
            i2c_transfer((uint8_t *)&OUT_Y_L_G, tx_buf + 1, 0) < 0 ||
            i2c_transfer((uint8_t *)&OUT_Z_L_G, tx_buf + 2, 0) < 0) {
            printf("Failed to read magnetic field data.\n");
            break;
        }

        int16_t x = (tx_buf[0] << 8) | tx_buf[1];
        int16_t y = (tx_buf[2] << 8) | tx_buf[3];
        int16_t z = (tx_buf[4] << 8) | tx_buf[5];

        calibrate_and_convert(x, y, z, &mx, &my, &mz);

        magnitude = sqrt(mx * mx + my * my + mz * mz);
        log_magnetic_data(mx, my, mz);
        check_metal_threshold(magnitude);

        usleep(1000000 / READINGS_PER_SECOND);
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

