            if (pigpio_spi_transfer(spi_handle, (uint8_t *)&XDATA, data + 0) < 0) {
                continue;
            }
            if (pigpio_spi_transfer(spi_handle, (uint8_t *)&YDATA, data + 1) < 0) {
                continue;
            }
            if (pigpio_spi_transfer(spi_handle, (uint8_t *)&ZDATA, data + 2) < 0) {
                continue;
            }

            x = (data[0] << 16) | ((data[1] & 0x7F) << 8) | (data[2] & 0xFF);
            y = (data[1] >> 7) | ((data[2] & 0x7F) << 8) | (data[0] & 0xFF);
            z = (data[2] >> 7) | ((data[0] & 0x7F) << 8) | (data[1] & 0xFF);

            break;
        }

        if (i == READ_RETRY_COUNT) {
            fprintf(stderr, "Failed to read acceleration data after retries.\n");
            break;
        }

        x *= 3.9;
        y *= 3.9;
        z *= 3.9;

        time_t now = time(NULL);
        fprintf(fp, "%ld,%d,%d,%d\n", now, x, y, z);

        delay(MEASUREMENT_MODE_DELAY_MS);
    }

    spi_cleanup();
    fclose(fp);
    return 0;
}

