#define ADIS16362_SPI_CHANNEL 0
#define ADIS16362_BAUD_RATE 1000000
#define ADIS16362_MODE 3
#define GYRO_X_REG 0x04
#define GYRO_Y_REG 0x06
#define GYRO_Z_REG 0x08
#define ACCL_X_REG 0x0A
#define ACCL_Y_REG 0x0C
#define ACCL_Z_REG 0x0E
#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.0025
#define SAMPLE_INTERVAL 10000000 // 10 ms in microseconds

struct spi_data {
    uint16_t gyro_x, gyro_y, gyro_z;
    uint16_t accl_x, accl_y, accl_z;
};

void read_adis16362(struct spi_data *data) {
    uint8_t reg_addr[2];
    reg_addr[0] = GYRO_X_REG | 0x80;
    spi_transfer(ADIS16362_SPI_CHANNEL, reg_addr, NULL, 1);

    spi_transfer(ADIS16362_SPI_CHANNEL, NULL, (uint8_t *)&data->gyro_x, 2);

    reg_addr[0] = GYRO_Y_REG | 0x80;
    spi_transfer(ADIS16362_SPI_CHANNEL, reg_addr, NULL, 1);

    spi_transfer(ADIS16362_SPI_CHANNEL, NULL, (uint8_t *)&data->gyro_y, 2);

    reg_addr[0] = GYRO_Z_REG | 0x80;
    spi_transfer(ADIS16362_SPI_CHANNEL, reg_addr, NULL, 1);

    spi_transfer(ADIS16362_SPI_CHANNEL, NULL, (uint8_t *)&data->gyro_z, 2);

    reg_addr[0] = ACCL_X_REG | 0x80;
    spi_transfer(ADIS16362_SPI_CHANNEL, reg_addr, NULL, 1);

    spi_transfer(ADIS16362_SPI_CHANNEL, NULL, (uint8_t *)&data->accl_x, 2);

    reg_addr[0] = ACCL_Y_REG | 0x80;
    spi_transfer(ADIS16362_SPI_CHANNEL, reg_addr, NULL, 1);

    spi_transfer(ADIS16362_SPI_CHANNEL, NULL, (uint8_t *)&data->accl_y, 2);

    reg_addr[0] = ACCL_Z_REG | 0x80;
    spi_transfer(ADIS16362_SPI_CHANNEL, reg_addr, NULL, 1);

    spi_transfer(ADIS16362_SPI_CHANNEL, NULL, (uint8_t *)&data->accl_z, 2);
}

int log_imu_readings(FILE *log_file) {
    struct spi_data data;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;

    if (fprintf(log_file, "%llu,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
               timestamp,
               data.gyro_x * GYRO_SCALE,
               data.gyro_y * GYRO_SCALE,
               data.gyro_z * GYRO_SCALE,
               data.accl_x * ACCL_SCALE,
               data.accl_y * ACCL_SCALE,
               data.accl_z * ACCL_SCALE) < 0) {
        return -1;
    }

    return 0;
}

int main() {
    int spi_fd;
    struct spi_data data;
    FILE *log_file = fopen("imu_log.csv", "w");

    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(0, PI_OUTPUT);
    gpioSetMode(8, PI_OUTPUT);
    spi_fd = spiOpen(ADIS16362_SPI_CHANNEL, ADIS16362_BAUD_RATE);

    if (spi_fd < 0) {
        perror("Failed to open SPI channel");
        gpioTerminate();
        return 1;
    }

    while (1) {
        read_adis16362(&data);

        if (log_imu_readings(log_file) < 0) {
            break;
        }

        nanosleep((struct timespec[]){{10, 0}, }, NULL);
    }

    gpioClose(spi_fd);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

void sigint_handler(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    return main();
}

