#define SENSOR_PINS "17,27"
#define POLL_INTERVAL_MS 100

static int sensor_lines[2];
static struct gpiod_chip *chip;

static int init_gpio(void) {
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return ret;
    }

    ret = gpiod_chip_request_lines(chip, SENSOR_PINS, &sensor_lines[0], &sensor_lines[1]);
    if (ret < 0) {
        fprintf(stderr, "Failed to request lines 17 and 27\n");
        gpiod_chip_close(chip);
        return ret;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpiod_chip_close(chip);
}

static int read_sensors(void) {
    uint8_t values[2];
    int ret;

    ret = gpiod_line_get_values(sensor_lines, values, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read sensor values\n");
    }

    return ret;
}

int main(void) {
    int ret;
    struct timespec ts;

    if (init_gpio() < 0) {
        return 1;
    }

    while (1) {
        ret = clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to get time\n");
            break;
        }

        if (ts.tv_sec != (clock_t)ts.tv_sec) { // Check for overflow
            fprintf(stderr, "Time overflow detected\n");
            break;
        }

        ret = read_sensors();
        if (ret < 0) {
            break;
        }

        if (values[0] == 0 || values[1] == 0) {
            printf("Obstacle detected at %ld.%09ld us\n",
                   (long)(ts.tv_sec), (long)(ts.tv_nsec / 1000));
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio();
    return 0;
}

