#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <libgpiod.h>
#include <spidev.h>

#define ADIS16266_ADDR 0x1E
#define MSC_CTRL 0x24
#define X_RATE 0x04
#define Y_RATE 0x06
#define Z_RATE 0x08
#define SCALE_FACTOR 0.02

static gpiod_chip *chip;
static int spi_fd;

void read_adis16266(void) {
    uint16_t x, y, z;
    int ret;

    // Pull CS low
    ret = gpiod_trigger_output(chip->chip, "CE0", 0);
    if (ret < 0) {
        fprintf(stderr, "Error pulling CS low: %s\n", strerror(errno));
        return;
    }

    // Write to MSC_CTRL register
    struct spi_transfer transf[] = {
        {0x80 | X_RATE, NULL, 0},
        {0x00, &x, 0},
        {0x80 | Y_RATE, NULL, 0},
        {0x00, &y, 0},
        {0x80 | Z_RATE, NULL, 0},
        {0x00, &z, 0}
    };

    if (write(spi_fd, transf, sizeof(transf)) != sizeof(transf)) {
        fprintf(stderr, "Error writing to SPI: %s\n", strerror(errno));
        gpiod_trigger_input(chip->chip, "CE0");
        return;
    }

    // Pull CS high
    gpiod_trigger_input(chip->chip, "CE0");

    // Print data
    printf("X: %.2f, Y: %.2f, Z: %.2f deg/s\n", x * SCALE_FACTOR, y * SCALE_FACTOR, z * SCALE_FACTOR);
}

int main(void) {
    int ret;
    struct gpiod_chipchip_info info;
    struct gpiod_chip_line *line;

    chip = gpiod_chip_open(0, "CE0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, "CE0");
    if (!line) {
        fprintf(stderr, "Error getting line CE0: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_export(line, "CE0") < 0) {
        fprintf(stderr, "Error exporting line CE0: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_add(line, "output") < 0) {
        fprintf(stderr, "Error requesting output for line CE0: %s\n", strerror(errno));
        gpiod_line_export_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(spi_fd, SPI_WRITER_DUART, NULL) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(spi_fd, SPI_MRBIT(8), &SPI_MODE3) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(spi_fd, SPI_WRBIT(16), &SPI_MSBFIRST) < 0) {
        fprintf(stderr, "Error setting MSB first: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(spi_fd, SPI_LRCLK(1000000), NULL) < 0) {
        fprintf(stderr, "Error setting clock speed: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_WR_FRAMING, 0) < 0) {
        fprintf(stderr, "Error setting framing: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IO_MODE, SPI_MODE_IO) < 0) {
        fprintf(stderr, "Error setting I/O mode: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_WRITEONLY, 1) < 0) {
        fprintf(stderr, "Error setting write-only mode: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_CS_HIGH, NULL) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_CS_LOW, NULL) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (write(spi_fd, &MSC_CTRL, sizeof(MSC_CTRL)) != sizeof(MSC_CTRL)) {
        fprintf(stderr, "Error writing to MSC_CTRL: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    while (1) {
        read_adis16266();
        sleep(0.1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

