#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6B
#define WHO_AM_I_REG 0xD0
#define CTRL1_XL 0x28
#define CTRL2_G 0x29
#define OUTX_L_G 0x28

#define GYRO_SENS 0.00875
#define ACCEL_SENS 0.000061

static pigpio *gpio;
static int i2c_fd;

void sigint_handler(int signum) {
    gpioTerminate();
    close(i2c_fd);
    exit(0);
}

int main() {
    gpio = gpioInitialise(0);
    if (!gpio) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_fd = i2cOpen(1, LSM6DSR_ADDR);
    if (i2cOpen(1, LSM6DSR_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2cGetReg8(i2c_fd, WHO_AM_I_REG) != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch, expected 0x6B, got 0x%02X\n", who_am_i);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (i2cPut(i2c_fd, CTRL1_XL, 0x42) < 0 ||
        i2cPut(i2c_fd, CTRL2_G, 0x42) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint8_t data[12];
        int bytes_read = i2cGetRegBlock(i2c_fd, OUTX_L_G, 12);
        if (bytes_read != 12) {
            fprintf(stderr, "Failed to read burst data, expected 12 bytes, got %d\n", bytes_read);
            break;
        }

        float gyro_x = (float)((data[0] << 8 | data[1]) * GYRO_SENS);
        float gyro_y = (float)((data[2] << 8 | data[3]) * GYRO_SENS);
        float gyro_z = (float)((data[4] << 8 | data[5]) * GYRO_SENS);
        float accel_x = (float)((data[6] << 8 | data[7]) * ACCEL_SENS);
        float accel_y = (float)((data[8] << 8 | data[9]) * ACCEL_SENS);
        float accel_z = (float)((data[10] << 8 | data[11]) * ACCEL_SENS);

        printf("Gyro: %f, %f, %f; Accel: %f, %f, %f\n", gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        usleep(100000);
    }

    close(i2c_fd);
    gpioTerminate();
    return 0;
}

int main(int argc, char *argv[]) {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    return main();
}

