#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdint.h>
#include <string.h>

#define DEVICE_ADDR 0x1D
#define I2C_BUS 1
#define REG_WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

static const int I2C_REG_LEN = 12;
static const int ACCEL_DATA_LEN = 6;
static const int MAG_DATA_LEN = 6;

static int i2c_fd;
static gpio pigpio;

void cleanup(int sig) {
    piClose(i2c_fd, TRUE);
    pigpioTerminate();
    exit(sig);
}

int main() {
    const char *dev = "FXOS8700";
    struct pi_i2c_dev i2c;
    int ret;

    pigpioInit(&pigpio);
    i2c_fd = piOpenI2C(I2C_BUS, &pigpio, dev, TRUE);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", piGetError());
        return 1;
    }

    i2c.fd = i2c_fd;
    i2c.gpio = &pigpio;

    if (piI2CGetInfo(&i2c) < 0) {
        fprintf(stderr, "Failed to get I2C info: %s\n", piGetError());
        return 1;
    }

    if (piI2CReadRegByte(&i2c, DEVICE_ADDR, REG_WHO_AM_I) != 0xC7) {
        fprintf(stderr, "Device 0x%02x (FXOS8700) not found at address 0x%02x\n", DEVICE_ADDR, REG_WHO_AM_I);
        return 1;
    }

    if (piI2CWriteReg8(&i2c, DEVICE_ADDR, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return 1;
    }

    if (piI2CWriteReg8(&i2c, DEVICE_ADDR, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG2\n");
        return 1;
    }

    if (piI2CWriteReg8(&i2c, DEVICE_ADDR, M_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to write M_CTRL_REG1\n");
        return 1;
    }

