#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <time.h>
#include <signal.h>

#define ADXL345_ADDR 0x53
#define REG_X_L 0x32
#define REG_X_H 0x33
#define REG_Y_L 0x34
#define REG_Y_H 0x35
#define REG_Z_L 0x36
#define REG_Z_H 0x37
#define TILT_THRESHOLD 30.0
#define LOG_INTERVAL 100 // ms

int i2c_fd = -1;
struct timespec last_log_time;

void log_tilt_event(double x, double y, double z) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    FILE *log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file) {
        fprintf(log_file, "%s: X=%.2f, Y=%.2f, Z=%.2f\n", timestamp, x, y, z);
        fclose(log_file);
    }
}

double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double roll, pitch;
    if (z == 0) {
        roll = 90.0;
        pitch = 0.0;
    } else {
        roll = atan2(y, z) * 180 / M_PI;
        pitch = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
    }
    return acos(fabs(z / sqrt(x * x + y * y + z * z))) * 180 / M_PI;
}

void signal_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct i2c_rdwr_ioctl_data rdwr_data;
    rdwr_data.u16_flags = 0;
    rdwr_data.u8_rd_buf = NULL;
    rdwr_data.u8_wr_buf = NULL;
    rdwr_data.u32_len = 0;
    rdwr_data.u32_delays = 0;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c-1");
        return 1;
    }

    ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR);

    while (1) {
        rdwr_data.u8_rd_buf = (unsigned char *)&rdwr_data.u16_flags;
        rdwr_data.u32_len = 2;
        if (ioctl(i2c_fd, I2C_RDWR, &rdwr_data) < 0) {
            fprintf(stderr, "I2C read failed\n");
            break;
        }

        int16_t x_l = (rdwr_data.u16_flags >> 16) & 0xFF;
        int16_t x_h = (rdwr_data.u16_flags >> 8) & 0xFF;
        int16_t y_l = (rdwr_data.u16_flags >> 24) & 0xFF;
        int16_t y_h = (rdwr_data.u16_flags >> 16) & 0xFF;
        int16_t z_l = (rdwr_data.u16_flags >> 30) & 0xFF;
        int16_t z_h = (rdwr_data.u16_flags >> 24) & 0xFF;

        int16_t x = (x_h << 8) | x_l;
        int16_t y = (y_h << 8) | y_l;
        int16_t z = (z_h << 8) | z_l;

        double tilt = calculate_tilt(x, y, z);

        struct timespec curr_time;
        clock_gettime(CLOCK_MONOTONIC, &curr_time);

        if (tilt > TILT_THRESHOLD || (tilt < TILT_THRESHOLD && diff_time(&last_log_time, &curr_time) > LOG_INTERVAL * 1000)) {
            log_tilt_event(x, y, z);
            last_log_time = curr_time;
        }

        usleep(LOG_INTERVAL * 1000);
    }

    close(i2c_fd);
    return 0;
}

int diff_time(struct timespec *t1, struct timespec *t2) {
    if (t2->tv_nsec < t1->tv_nsec) {
        t2->tv_nsec += 1000000000;
    }
    if ((t2->tv_nsec - t1->tv_nsec) > 0) {
        return 1;
    }
    if (t2->tv_sec - t1->tv_sec > 0) {
        return 1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    return main();
}

