#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_S 5

void print_status(int high_count) {
    char status[256];
    if (high_count >= THRESHOLD) {
        time_t now = time(NULL);
        strftime(status, sizeof(status), "%Y-%m-%d %H:%M:%S", localtime(&now));
        printf("%s ALERT\n", status);
    } else {
        printf("%s NORMAL\n", asctime(localtime(time(NULL))));
    }
}

int main(int argc, char *argv[]) {
    int gpio_status;
    int high_count = 0;
    int threshold;
    int i;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    threshold = strtol(argv[1], NULL, 10);
    if (threshold <= 0 || !threshold) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library.\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    while (1) {
        for (i = 0; i < (WINDOW_DURATION_S * 1000) / SAMPLE_INTERVAL_MS; ++i) {
            gpio_status = pigpio_read(GPIO_PIN);
            if (gpio_status) {
                high_count++;
            }
        }

        print_status(high_count);
        high_count = 0;
        usleep(1000000); // Sleep for 1 second before the next window
    }

    gpioTerminate();
    return 0;
}

