#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27
#define MAX_ATTEMPTS 3

volatile sig_atomic_t sigint_flag = 0;

static int door_access_init(void) {
    const char *dev_name = "/dev/gpiod";
    int fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s\n", dev_name);
        return -1;
    }

    struct gpiod_chip *chip;
    int ret = gpiod_chip_open(fd, "GPIO17-GPIO27");
    if (ret < 0) {
        fprintf(stderr, "Failed to open chip\n");
        close(fd);
        return -1;
    }

    chip = gpiod_chip_get(ret);
    if (!chip) {
        fprintf(stderr, "Failed to get chip\n");
        gpiod_chip_close(ret);
        close(fd);
        return -1;
    }

    struct gpiod_line *line_a = gpiod_chip_get_line(chip, DOOR_A_GPIO);
    struct gpiod_line *line_b = gpiod_chip_get_line(chip, DOOR_B_GPIO);

    if (!line_a || !line_b) {
        fprintf(stderr, "Failed to get lines\n");
        gpiod_chip_close(ret);
        close(fd);
        return -1;
    }

    ret = gpiod_line_request_output(line_a, "Door A Lock");
    if (ret < 0) {
        fprintf(stderr, "Failed to request output on GPIO17\n");
        gpiod_line_release(line_a);
        gpiod_chip_close(ret);
        close(fd);
        return -1;
    }

    ret = gpiod_line_request_output(line_b, "Door B Lock");
    if (ret < 0) {
        fprintf(stderr, "Failed to request output on GPIO27\n");
        gpiod_line_release(line_a);
        gpiod_chip_close(ret);
        close(fd);
        return -1;
    }

    return 0;
}

static void door_access_cleanup(void) {
    struct gpiod_line *line_b = gpiod_chip_get_line(chip, DOOR_B_GPIO);
    struct gpiod_line *line_a = gpiod_chip_get_line(chip, DOOR_A_GPIO);

    if (line_a) gpiod_line_release(line_a);
    if (line_b) gpiod_line_release(line_b);

    gpiod_chip_close(chip);
    close(fd);
}

static void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main(void) {
    struct tm tm;
    time_t now = time(NULL);
    localtime_r(&now, &tm);

    if (door_access_init() < 0)
        return 1;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpiod_line_set_value(line_a, 0);
    gpiod_line_set_value(line_b, 0);

    uint64_t code = rand() % 900000 + 100000;
    printf("Security Code: %llu\n", code);

    FILE *log_file = fopen("access_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open access_log.txt\n");
        door_access_cleanup();
        return 1;
    }

    while (1) {
        char input[10];
        int attempts = 0;

        printf("Enter security code: ");
        if (fgets(input, sizeof(input), stdin) != NULL) {
            input[strcspn(input, "\n")] = 0;
            if (sscanf(input, "%llu", &code) != 1) {
                fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
                continue;
            }

            attempts++;
            if (code == code_to_check) {
                printf("Access granted.\n");
                gpiod_line_set_value(line_a, 1);
                sleep(5);
                gpiod_line_set_value(line_a, 0);
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %llu\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                        tm.tm_hour, tm.tm_min, tm.tm_sec, code);
                code = rand() % 900000 + 100000;
                printf("New security code: %llu\n", code);
            } else if (attempts >= MAX_ATTEMPTS) {
                printf("Access denied.\n");
            }
        }

        if (sigint_flag)
            break;
    }

    door_access_cleanup();
    fclose(log_file);
    return 0;
}

