#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define BH1750_ADDR 0x23
#define BH1750_REG_ONE_TIME_HIGH_RES 0x21
#define MAX_CONVERSION_TIME 180000 // 180 ms

int i2c_fd = -1;

void log_reading(double lux) {
    time_t now;
    time(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *fp = fopen("light_log.txt", "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fp, "%s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
}

int main() {
    struct i2c_rdwr_ioctl_data rdwr;
    int i2c_addr = BH1750_ADDR;
    int r;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        return 1;
    }

    ioctl(i2c_fd, I2C_SLAVE, i2c_addr);

    rdwr.u8 = 0;
    rdwr.u8len = 1;
    rdwr.u8 = BH1750_REG_ONE_TIME_HIGH_RES;
    rdwr.u8len = 1;

    r = ioctl(i2c_fd, I2C_RDWR, &rdwr);
    if (r < 0) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }

    usleep(MAX_CONVERSION_TIME);

    rdwr.u8 = 0;
    rdwr.u8len = 2;
    r = ioctl(i2c_fd, I2C_RDWR, &rdwr);
    if (r < 0) {
        perror("Failed to read from I2C device");
        close(i2c_fd);
        return 1;
    }

    uint16_t raw_value = (rdwr.u8[0] << 8) | rdwr.u8[1];
    double lux = (raw_value * 5) / 6;
    log_reading(lux);

    while (1) {
        sleep(5);
    }

    close(i2c_fd);
    return 0;
}

