#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 12345
#define I2C_ADDR 0x5A
#define PWM_PIN 18
#define MAX_TOUCHES 12
#define SAMPLE_INTERVAL 20000 // 20 ms
#define PLAYBACK_DURATION 5000 // 5 seconds

float freq_map[1024];
int touch_data[MAX_TOUCHES];
int touch_count = 0;
int start_time = 0;
int pwm_frequency = 440; // A4

void sigint_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        stop_pwm();
        close_i2c();
        close_socket();
        pigpio_terminate();
        exit(0);
    }
}

void init_pigpio() {
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(1);
    }
}

void close_pigpio() {
    pigpio_terminate();
}

void init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        exit(1);
    }

    if (i2c_open(1, I2C_ADDR) < 0) {
        fprintf(stderr, "i2c_open failed\n");
        exit(1);
    }
}

void close_i2c() {
    i2c_close();
    gpioTerminate();
}

void init_touch_sensor() {
    // Soft reset and electrode configuration
    // ...
}

void init_pwm() {
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    pwmSetRange(PWM_PIN, 1000);
    pwmSetFrequency(PWM_PIN, 440); // A4
}

void stop_pwm() {
    pwmStop(PWM_PIN);
}

void update_pwm(int freq) {
    pwmSetFrequency(PWM_PIN, freq);
}

void handle_client(int client_socket) {
    char buffer[1024];
    int valread;

    while ((valread = recv(client_socket, buffer, sizeof(buffer), 0)) > 0) {
        if (strstr(buffer, "MOTION_DETECTED:") && strstr(buffer, "MySecretKey")) {
            if (!start_time) {
                start_time = get_tick_count();
            }

            init_touch_sensor();
            for (int i = 0; i < MAX_TOUCHES; ++i) {
                touch_data[i] = i2c_read_word(I2C_ADDR, i * 2);
            }
            touch_count = 0;

            for (int i = 0; i < 1000 / SAMPLE_INTERVAL; ++i) {
                int max_touch = 0;
                for (int j = 0; j < MAX_TOUCHES; ++j) {
                    if (touch_data[j] > touch_data[max_touch]) {
                        max_touch = j;
                    }
                }
                int filtered_data = touch_data[max_touch]; // Simple filtering
                int freq_index = (int)((log(filtered_data / 1023.0) / log(2)) * 1023);
                update_pwm(freq_map[freq_index]);
                touch_count++;
                touch_data[max_touch] = i2c_read_word(I2C_ADDR, max_touch * 2);

                if (get_tick_count() - start_time >= PLAYBACK_DURATION) {
                    break;
                }
                sleep(SAMPLE_INTERVAL / 1000);
            }

            FILE *log_file = fopen("frequency_log.txt", "a");
            if (log_file) {
                for (int i = 0; i < touch_count; ++i) {
                    fprintf(log_file, "%d\n", freq_map[touch_data[i] / 1023 * 1023]);
                }
                fclose(log_file);
            }
        }
    }

    close(client_socket);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_pigpio();
    init_i2c();
    init_touch_sensor();
    init_pwm();

    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        fprintf(stderr, "socket creation failed\n");
        exit(1);
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "bind failed\n");
        exit(1);
    }

    if (listen(server_socket, 5) < 0) {
        fprintf(stderr, "listen failed\n");
        exit(1);
    }

    printf("Server started on port %d\n", PORT);

    while (1) {
        int client_socket = accept(server_socket, NULL, NULL);
        if (client_socket < 0) {
            fprintf(stderr, "accept failed\n");
            continue;
        }
        handle_client(client_socket);
    }

    close_pigpio();
    close_i2c();
    close(server_socket);

    return 0;
}

