#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "1"
#define I2C_ADDR 0x1E
#define PWM_GPIO 17
#define SAMPLE_INTERVAL_MS 100
#define MAG_REG_CTRL1_M 0x20
#define MAG_OUT_X_L_M 0x08

struct sensor_data {
    int32_t x, y, z;
    float magnitude;
};

int init_i2c(const char *bus) {
    int file_desc = open(bus, O_RDWR);
    if (file_desc < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(file_desc, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or perform slave address ACK");
        close(file_desc);
        return -1;
    }

    return file_desc;
}

void cleanup_i2c(int file_desc) {
    close(file_desc);
}

int init_magnetometer(int fd) {
    struct i2c_rdwr_ioctl_data rdwr;
    rdwr.msgs = (struct i2c_rdwr_data[]){
        {
            .addr = I2C_ADDR,
            .flags = 0,
            .len = 1,
            .buf = &rdwr_ctrl1_m,
        },
        {
            .addr = I2C_ADDR,
            .flags = I2C_M_RD,
            .len = 1,
            .buf = &mag_data,
        }
    };
    rdwr.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to write to magnetometer register");
        return -1;
    }

    return 0;
}

int read_magnetometer_data(int fd, struct sensor_data *data) {
    if (ioctl(fd, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to read from magnetometer register");
        return -1;
    }

    data->x = ((int16_t)(mag_data[1] << 8 | mag_data[0])) * 0.015625;
    data->y = ((int16_t)(mag_data[3] << 8 | mag_data[2])) * 0.015625;
    data->z = ((int16_t)(mag_data[5] << 8 | mag_data[4])) * 0.015625;

    data->magnitude = (float)sqrt(data->x * data->x + data->y * data->y + data->z * data->z);

    return 0;
}

int init_pwm(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(&gpiod_chip_default, "GPIO17");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO17\n");
        gpiod_chip_put(chip);
        return -1;
    }

    gpiod_line_export(line, NULL);

    return 0;
}

void cleanup_pwm(int gpio) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio);
    gpiod_line_unexport(line);
    gpiod_chip_put(chip);
}

int main() {
    int i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    int mag_fd = init_magnetometer(i2c_fd);
    if (mag_fd < 0) {
        cleanup_i2c(i2c_fd);
        return EXIT_FAILURE;
    }

    struct sensor_data data;
    while (1) {
        if (init_pwm(PWM_GPIO) < 0) {
            cleanup_i2c(i2c_fd);
            return EXIT_FAILURE;
        }

        read_magnetometer_data(i2c_fd, &data);

        // Adjust PWM duty cycle based on the magnitude of the Z-axis field
        // (This is a placeholder for the actual PWM control logic)
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup_pwm(PWM_GPIO);
    cleanup_i2c(i2c_fd);

    return EXIT_SUCCESS;
}

