#define REG_CONFIG_A 0x00
#define REG_CONFIG_B 0x01
#define REG_MODE 0x02
#define REG_DATA_X_L 0x03
#define REG_DATA_Y_L 0x05
#define REG_DATA_Z_L 0x07
#define SAMPLE_COUNT 100
#define OFFSET_UPDATE_INTERVAL_MS 500

static int i2c_fd = -1;
static gpio *gpio = NULL;
static uint8_t raw_samples[SAMPLE_COUNT * 3];
static int16_t offset_x = 0, offset_y = 0, offset_z = 0;
static int sample_index = 0;

void configure_magnetometer() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }

    if (i2c_fd < 0) {
        i2c_fd = i2cOpen(1, I2C_ADDR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }
    }

    // Configure registers
    const uint8_t config_a = 0x70;
    const uint8_t config_b = 0x20;
    const uint8_t mode = 0x00;

    if (i2cWrite(i2c_fd, REG_CONFIG_A, &config_a, 1) != 1) {
        fprintf(stderr, "Failed to write to CONFIG_A register\n");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWrite(i2c_fd, REG_CONFIG_B, &config_b, 1) != 1) {
        fprintf(stderr, "Failed to write to CONFIG_B register\n");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWrite(i2c_fd, REG_MODE, &mode, 1) != 1) {
        fprintf(stderr, "Failed to write to MODE register\n");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }
}

void read_raw_samples() {
    if (sample_index >= SAMPLE_COUNT) {
        sample_index = 0;
    }

    for (int i = 0; i < 3; i++) {
        if (i2cRead(i2c_fd, REG_DATA_X_L + (i * 2), raw_samples + sample_index * 3 + i, 2) != 2) {
            fprintf(stderr, "Failed to read from magnetometer\n");
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }
    }

    sample_index++;
}

void compute_hard_iron_offsets() {
    static int count = 0;
    if (count++ % 100 == 0) {
        int total_x = 0, total_y = 0, total_z = 0;
        for (int i = 0; i < SAMPLE_COUNT; i++) {
            total_x += raw_samples[i * 3] - offset_x;
            total_y += raw_samples[i * 3 + 1] - offset_y;
            total_z += raw_samples[i * 3 + 2] - offset_z;
        }

        offset_x = total_x / SAMPLE_COUNT;
        offset_y = total_y / SAMPLE_COUNT;
        offset_z = total_z / SAMPLE_COUNT;
    }
}

int main(int argc, char *argv[]) {
    configure_magnetometer();

    while (1) {
        read_raw_samples();
        compute_hard_iron_offsets();

        if (sample_index == SAMPLE_COUNT) {
            sample_index = 0;

            int offset_x_corrected = raw_samples[sample_index * 3] - offset_x;
            int offset_y_corrected = raw_samples[sample_index * 3 + 1] - offset_y;
            int offset_z_corrected = raw_samples[sample_index * 3 + 2] - offset_z;

            printf("X: %d, Y: %d, Z: %d\n", offset_x_corrected, offset_y_corrected, offset_z_corrected);
        }

        usleep(20000); // 15 Hz sampling rate
    }

    pigpio_terminate();
    close(i2c_fd);

    return 0;
}

