#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define DEVICE "/dev/i2c-1"
#define LSM303D_ADDR 0x1D
#define BUFFER_SIZE 64
#define ODR_50HZ 0x00000024
#define CTRL_REG1_50HZ 0x57
#define CTRL_REG4_2G 0x00
#define INT1_CFG_2000MG 0x7D
#define INT_DUR_0 0
#define INT_THS_LOW 0
#define INT_THS_HIGH 2000

typedef struct {
    int16_t buffer[BUFFER_SIZE][3];
    int head;
    int tail;
} CircularBuffer;

int lsm303d_read_reg(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (len == 0) {
        return -1;
    }

    if (write(fd, &reg_addr, sizeof(reg_addr)) != sizeof(reg_addr)) {
        fprintf(stderr, "Error writing register address\n");
        return -1;
    }

    if (len == 1) {
        return read(fd, data, len);
    } else {
        return read(fd, data, len);
    }
}

int lsm303d_write_reg(int fd, uint8_t reg_addr, const uint8_t *data, int len) {
    if (write(fd, &reg_addr, sizeof(reg_addr)) != sizeof(reg_addr)) {
        fprintf(stderr, "Error writing register address\n");
        return -1;
    }

    if (len == 1) {
        return write(fd, data, len);
    } else {
        return write(fd, data, len);
    }
}

int init_lsm303d(int *lsm303d_fd) {
    *lsm303d_fd = open(DEVICE, O_RDWR);
    if (*lsm303d_fd < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        return -1;
    }

    if (ioctl(*lsm303d_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address\n");
        close(*lsm303d_fd);
        return -1;
    }

    uint8_t who_am_i = 0x0F;
    if (lsm303d_read_reg(*lsm303d_fd, who_am_i, &who_am_i, 1) < 0) {
        close(*lsm303d_fd);
        return -1;
    }

    if (who_am_i != 0x49) {
        fprintf(stderr, "Invalid LSM303D device\n");
        close(*lsm303d_fd);
        return -1;
    }

    // Configure LSM303D
    uint8_t ctrl_reg1 = CTRL_REG1_50HZ;
    uint8_t ctrl_reg4 = CTRL_REG4_2G;
    uint8_t int1_cfg = INT1_CFG_2000MG | INT_DUR_0 | INT_THS_HIGH;

    if (lsm303d_write_reg(*lsm303d_fd, 0x20, &ctrl_reg1, 1) < 0 ||
        lsm303d_write_reg(*lsm303d_fd, 0x21, &ctrl_reg4, 1) < 0 ||
        lsm303d_write_reg(*lsm303d_fd, 0x2C, &int1_cfg, 1) < 0) {
        close(*lsm303d_fd);
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int lsm303d_fd;
    CircularBuffer cb;
    int gpio_int_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    if (init_lsm303d(&lsm303d_fd) < 0) {
        return 1;
    }

    cb.head = cb.tail = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb.buffer[i][0] = cb.buffer[i][1] = cb.buffer[i][2] = 0;
    }

    gpio_int_fd = gpiod_open_rtl();
    if (!gpio_int_fd) {
        fprintf(stderr, "Error opening GPIO library\n");
        close(lsm303d_fd);
        return 1;
    }

    chip = gpiod_chip_open(gpio_int_fd, "GPIO23");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO23\n");
        gpiod_close(gpio_int_fd);
        close(lsm303d_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, "INT1");
    if (!line) {
        fprintf(stderr, "Error getting GPIO23 line\n");
        gpiod_chip_close(chip);
        gpiod_close(gpio_int_fd);
        close(lsm303d_fd);
        return 1;
    }

    gpiod_add_event(line, GPIO_FALLING_EDGE, 0);

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        int16_t accel_data[3];
        uint8_t reg_addr = 0x28;
        if (lsm303d_read_reg(lsm303d_fd, reg_addr, accel_data, 3) < 0) {
            fprintf(stderr, "Error reading acceleration data\n");
            continue;
        }

        cb.buffer[cb.head] = accel_data;
        cb.head = (cb.head + 1) % BUFFER_SIZE;

        if (gpiod_event_check(line)) {
            printf("Interrupt detected at %ld\n", (long)(ts.tv_sec * 1000000 + ts.tv_nsec / 1000));
            for (int i = cb.tail; i < cb.tail + 10 && i < cb.head; i++) {
                printf("  X: %d, Y: %d, Z: %d\n", cb.buffer[i][0], cb.buffer[i][1], cb.buffer[i][2]);
            }
            cb.tail = (cb.tail + 1) % BUFFER_SIZE;
        }

        usleep(10000);
    }

    gpiod_remove_event(line);
    gpiod_chip_close(chip);
    gpiod_close(gpio_int_fd);
    close(lsm303d_fd);

    return 0;
}

