#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpio.h>

#define DELAY_MS 500

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static int init_gpio(void) {
    struct gi10 gi;
    int ret;

    ret = gi_open(&gi, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Error: gi_open failed: %s\n", gi_strerror(ret));
        return ret;
    }

    const char *labels[] = {"solenoid1", "solenoid2"};
    ret = gi_line_request(&gi, labels[0], 17);
    if (ret < 0) {
        fprintf(stderr, "Error: gi_line_request for %s failed: %s\n", labels[0], gi_strerror(ret));
        gi_close(&gi);
        return ret;
    }

    ret = gi_line_request(&gi, labels[1], 27);
    if (ret < 0) {
        fprintf(stderr, "Error: gi_line_request for %s failed: %s\n", labels[1], gi_strerror(ret));
        gi_line_free(&gi, labels[0]);
        gi_close(&gi);
        return ret;
    }

    return 0;
}

static void cleanup_gpio(void) {
    struct gi10 gi;
    int ret;

    ret = gi_open(&gi, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Error: gi_open failed: %s\n", gi_strerror(ret));
        return;
    }

    gi_line_free(&gi, "solenoid1");
    gi_line_free(&gi, "solenoid2");
    gi_close(&gi);
}

int main(void) {
    struct timespec delay_spec;
    struct gi10 gi;
    int ret;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    ret = init_gpio();
    if (ret < 0) {
        return ret;
    }

    gi_line_direction_out(&gi, "solenoid1");
    gi_line_direction_out(&gi, "solenoid2");

    gi_line_get(&gi, "solenoid1") -> value = 0;
    gi_line_get(&gi, "solenoid2") -> value = 0;

    while (1) {
        gi_line_get(&gi, "solenoid1") -> value = 1;
        nanosleep(&delay_spec, NULL);

        gi_line_get(&gi, "solenoid1") -> value = 0;
        nanosleep(&delay_spec, NULL);

        gi_line_get(&gi, "solenoid2") -> value = 1;
        nanosleep(&delay_spec, NULL);

        gi_line_get(&gi, "solenoid2") -> value = 0;
        nanosleep(&delay_spec, NULL);

        if (sigint_received) {
            break;
        }
    }

    cleanup_gpio();
    return 0;
}

