void sigint_handler(int signum) {
    gpioTerminate();
    for (int i = 0; i < 2; i++) {
        if (serial_ports[i] > 0) {
            close(serial_ports[i]);
            serial_ports[i] = 0;
        }
    }
    exit(0);
}

void initialize_pigpio() {
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", strerror(errno));
        exit(1);
    }
    gpioSetMode(GPIO_LOCK1, PI_OUTPUT);
    gpioSetMode(GPIO_LOCK2, PI_OUTPUT);
    gpioWrite(GPIO_LOCK1, 0);
    gpioWrite(GPIO_LOCK2, 0);
}

void initialize_serial_ports() {
    for (int i = 0; i < 2; i++) {
        serial_ports[i] = open(i == 0 ? SERIAL_PORT0 : SERIAL_PORT1, O_RDONLY | O_NOCTTY | O_NDELAY);
        if (serial_ports[i] < 0) {
            perror("Failed to open serial port");
            exit(1);
        }
        struct termios options;
        tcgetattr(serial_ports[i], &options);
        cfsetispeed(&options, BAUD_RATE);
        cfsetospeed(&options, BAUD_RATE);
        options.c_cflag |= (CLOCAL | CREAD);
        options.c_cflag &= ~PARENB;
        options.c_cflag &= ~CSTOPB;
        options.c_cflag &= ~CSIZE;
        options.c_cflag |= CS8;
        options.c_cflag &= ~CRTSCTS;
        options.c_cflag |= CREAD;
        options.c_cflag |= CS8;
        options.c_cflag &= ~PARENB;
        options.c_cflag &= ~CSTOPB;
        options.c_cflag &= ~CLOCAL;
        tcflush(serial_ports[i], TCIOFLUSH);
        tcsetattr(serial_ports[i], TCSANOW, &options);
    }
}

int read_serial(int fd, char *buffer, int buffer_size) {
    int bytes_read = read(fd, buffer, buffer_size);
    if (bytes_read < 0) {
        perror("Serial read error");
        return -1;
    }
    buffer[bytes_read] = '\0';
    return bytes_read;
}

int compare_codes(const char *code1, const char *code2) {
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (code1[i] != code2[i]) {
            return 0;
        }
    }
    return 1;
}

