    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    initialize_pigpio();
    initialize_serial_ports();

    while (1) {
        for (int i = 0; i < 2; i++) {
            if (read_serial(i == 0 ? serial_ports[0] : serial_ports[1], received_code, CODE_LENGTH + 1) == CODE_LENGTH) {
                if (code_index < CODE_LENGTH && (received_code[code_index] < '0' || received_code[code_index] > '9')) {
                    code_index = 0;
                    continue;
                }
                received_code[code_index++] = received_code[code_index - CODE_LENGTH];
            }
        }

        if (code_index == CODE_LENGTH && received_code[0] != '\0') {
            int match1 = compare_codes(received_code, EXPECTED_CODE);
            code_index = 0;

            if (read_serial(serial_ports[1] ^ 1, received_code, CODE_LENGTH + 1) == CODE_LENGTH) {
                if (code_index < CODE_LENGTH && (received_code[code_index] < '0' || received_code[code_index] > '9')) {
                    code_index = 0;
                    continue;
                }
                received_code[code_index++] = received_code[code_index - CODE_LENGTH];
            }

            int match2 = compare_codes(received_code, EXPECTED_CODE);

            if (match1 && match2) {
                gpioWrite(GPIO_LOCK1, 1);
                gpioWrite(GPIO_LOCK2, 1);
                sleep(2);
                gpioWrite(GPIO_LOCK1, 0);
                gpioWrite(GPIO_LOCK2, 0);
            }

            code_index = 0;
        }
    }

    gpioTerminate();
    return 0;
}

