#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <syslog.h>
#include <signal.h>

#define PIR_GPIO 4
#define RELAY_GPIO 17
#define STRIKE_DURATION 1000000 // 1 second in microseconds
#define MOTION_POLLING_INTERVAL 50000 // 50 ms
#define FAILSAFE_TIMEOUT 10000000 // 10 seconds in microseconds

struct timespec last_motion_time;
bool motion_detected = false;
bool relay_on = false;

void sigint_handler(int signum) {
    syslog(LOG_INFO, "Received SIGINT, initiating shutdown...");
    relay_off();
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void relay_on() {
    if (!relay_on) {
        relay_on = true;
        syslog(LOG_INFO, "Relay ON");
        gpiod_line_set_value(line, 1);
    }
}

void relay_off() {
    if (relay_on) {
        relay_on = false;
        syslog(LOG_INFO, "Relay OFF");
        gpiod_line_set_value(line, 0);
    }
}

int main() {
    setup_signals();
    int ret;

    struct gpiod_chip *chip;
    struct gpiod_line *line;

    ret = gpiod_chip_open_r("/gpiochip0", &chip);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %d", ret);
        return ret;
    }

    line = gpiod_chip_request_line(chip, "GPIO%d", RELAY_GPIO);
    if (!line) {
        syslog(LOG_ERR, "Failed to request GPIO%d", RELAY_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO%d as input: %d", RELAY_GPIO, ret);
        gpiod_chip_release(line);
        gpiod_chip_close(chip);
        return ret;
    }

    line = gpiod_chip_request_line(chip, "GPIO%d", PIR_GPIO);
    if (!line) {
        syslog(LOG_ERR, "Failed to request GPIO%d", PIR_GPIO);
        gpiod_chip_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO%d as input: %d", PIR_GPIO, ret);
        gpiod_chip_release(line);
        gpiod_chip_close(chip);
        return ret;
    }

    openlog("MotionDetector", LOG_PID | LOG_PERROR, LOG_DAEMON);

    while (true) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ts.tv_sec - last_motion_time.tv_sec > FAILSAFE_TIMEOUT / 1000000) {
            relay_off();
            syslog(LOG_WARNING, "PIR sensor remained HIGH for more than 10 seconds, de-energizing relay");
            last_motion_time = ts;
        }

        if (gpiod_line_get_value(line) == 1) {
            if (!motion_detected) {
                motion_detected = true;
                last_motion_time = ts;
                syslog(LOG_INFO, "Motion detected");
            }
        } else {
            motion_detected = false;
        }

        if (motion_detected) {
            if (!relay_on) {
                relay_on();
                sleep_us(STRIKE_DURATION);
                relay_off();
            }
        }

        usleep(MOTION_POLLING_INTERVAL);
    }

    gpiod_chip_release(line);
    gpiod_chip_close(chip);
    closelog();
    return 0;
}

