#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <syslog.h>
#include <stdatomic.h>

#define RELAY_PINS {4, 17, 27, 22}
#define NUM_RELAYS (sizeof(RELAY_PINS) / sizeof(RELAY_PINS[0]))
#define ACTIVATION_TIME 300000 // 5 minutes in microseconds
#define PAUSE_TIME 60000000 // 1 minute in microseconds

volatile _Atomic sig_atomic_t running = 1;
int relay_state = 0;
int timer_id = -1;

void timer_callback(int timer, void *context) {
    if (relay_state < NUM_RELAYS) {
        gpioWrite(RELAY_PINS[relay_state], 0);
        relay_state++;
    } else {
        relay_state = 0;
        gpioWrite(RELAY_PINS[relay_state], 0);
    }
}

void sigint_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (openlog("irrigation_system", LOG_PID | LOG_NDELAY, LOG_LOCAL0) == -1) {
        syslog(LOG_ERR, "Failed to initialize syslog");
        return 1;
    }

    if (pigpio_initialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        return 1;
    }

    gpioSetMode(RELAY_PINS, PI_OUTPUT);

    if (gpioSetTimerFuncEx(0, ACTIVATION_TIME, timer_callback) < 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        pigpio_terminate();
        return 1;
    }

    while (running) {
        sleep(1);
    }

    gpioSetTimerFuncEx(0, 0, NULL);
    pigpio_terminate();
    closelog();

    return 0;
}

