typedef struct {
    int fd;
    struct gpiod_chip chip;
    struct gpiod_line line;
    volatile int running;
    double buffer[BUFFER_SIZE][3];
    int index;
    struct itimer2 itimer;
    struct timespec ts;
} MPU6050_Context;

static MPU6050_Context ctx;

void sigint_handler(int signum) {
    ctx.running = false;
}

void init_i2c(const char *dev) {
    ctx.fd = open(dev, O_RDWR);
    if (ctx.fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx.fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(ctx.fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio(void) {
