        ret = gpiod_line_set_direction(line, GPIO_DIR_OUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to set direction for pin %d\n", RELAY_PINS[i]);
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            return 1;
        }

        gpiod_line_free(line);
    }

