        for (int i = 0; i < relay_count; i++) {
            if (relays[i].state) {
                toggle_relay(i);
            }
        }

        sleep(1);
    }

    // Clean up on exit
    for (int i = 0; i < relay_count; i++) {
        ret = gpiod_line_export(gpiod_chip_get_line(chip, RELAY_PINS[i]));
        if (ret < 0) {
