        if (ret < 0) {
            fprintf(stderr, "Failed to set low for cleanup\n");
        }

        gpiod_line_free(gpiod_chip_get_line(chip, RELAY_PINS[i]));
    }

    gpiod_chip_close(chip);
    return 0;
}

