#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27
#define THRESHOLD_LEVEL 1
#define ALARM_DURATION 3000 // milliseconds

static volatile sig_atomic_t sigint_received = 0;
static volatile sig_atomic_t sigterm_received = 0;

void signal_handler(int signum) {
    switch (signum) {
        case SIGINT:
            sigint_received = 1;
            break;
        case SIGTERM:
            sigterm_received = 1;
            break;
        default:
            break;
    }
}

void setup_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup_pigpio(void) {
    gpioTerminate();
}

void monitor_sound_sensor(int gpio, int threshold, int relay_gpio) {
    int state;
    time_t last_activation = 0;
    struct tm tm;
    char timestamp[20];

    gpioSetMode(gpio, PI_OUTPUT);
    gpioSetOutput(relay_gpio, 0); // Ensure relay is OFF initially

    while (1) {
        state = gpioRead(gpio);
        if (state >= threshold) {
            if (!sigint_received && !sigterm_received && (time(NULL) - last_activation) > 1) {
                gpioWrite(relay_gpio, 1); // Turn ON the relay
                last_activation = time(NULL);

                time_t now = time(NULL);
                localtime_r(&now, &tm);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

                FILE *log_file = fopen("alarm_log.txt", "a");
                if (log_file != NULL) {
                    fprintf(log_file, "[%s] Alarm triggered.\n", timestamp);
                    fclose(log_file);
                }

                // Wait for 3 seconds
                sleep(ALARM_DURATION / 1000);
                gpioWrite(relay_gpio, 0); // Turn OFF the relay
            }
        }
        gpioSetOutput(relay_gpio, 0); // Ensure relay is OFF on non-trigger conditions
        usleep(100 * 1000); // Poll at 100 ms interval
    }
}

int main(int argc, char *argv[]) {
    setup_pigpio();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    monitor_sound_sensor(SOUND_SENSOR_GPIO, THRESHOLD_LEVEL, RELAY_GPIO);

    cleanup_pigpio();

    return 0;
}

