#define THRESHOLD 50.0
#define SENSITIVITY 131.0

typedef struct {
    float buffer[BUFFER_SIZE][3];
    int head;
    int tail;
} CircularBuffer;

void callback(float x, float y, float z) {
    float magnitude = (float)sqrt(x*x + y*y + z*z);
    printf("Alert: Magnitude %f exceeds threshold %f\n", magnitude, THRESHOLD);
}

int main() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    CircularBuffer cb;
    cb.head = cb.tail = 0;

    if (write(fd, SLEEP_REG, 1) < 0) {
        perror("Failed to wake up the sensor");
        close(fd);
        return 1;
    }

    if (read(fd, (void*) &cb.buffer[cb.head][0], 6) != 6) {
        perror("Failed to read from the sensor");
        close(fd);
        return 1;
    }

    if (cb.buffer[cb.head][0] != 0x68) {
        fprintf(stderr, "WHO_AM_I register does not match expected value\n");
        close(fd);
        return 1;
    }

    // Configure the gyroscope
    if (write(fd, GYRO_CONFIG, 1) < 0) {
        perror("Failed to configure gyroscope");
        close(fd);
        return 1;
    }

    for(int i = 0; i < BUFFER_SIZE; i++) {
        if (read(fd, (void*) &cb.buffer[cb.head][0], 6) != 6) {
            perror("Failed to read gyroscope data");
            close(fd);
            return 1;
        }

        float x = (cb.buffer[cb.head] & 0xFF) | ((cb.buffer[cb.head + 1] & 0xF0) << 4);
        float y = (cb.buffer[cb.head + 2] & 0xFF) | ((cb.buffer[cb.head + 3] & 0xF0) << 4);
        float z = (cb.buffer[cb.head + 4] & 0xFF) | ((cb.buffer[cb.head + 5] & 0xF0) << 4);

        x = x * SENSITIVITY;
        y = y * SENSITIVITY;
        z = z * SENSITIVITY;

        cb.buffer[cb.head][0] = x;
        cb.buffer[cb.head][1] = y;
        cb.buffer[cb.head][2] = z;

        cb.head = (cb.head + 1) % BUFFER_SIZE;

        if (i < BUFFER_SIZE - 1) {
            callback(x, y, z);
        }
    }

    close(fd);
    return 0;
}

