#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define BAUD 9600
#define COMMAND_SIZE 9
#define CHECKSUM_INVERT 0x01
#define CHECKSUM_INCREMENT 1
#define TIMEOUT_MS 1000
#define RETRY_INTERVAL_MS 100
#define JSON_FORMAT "{\"timestamp\":%lu,\"ppm\":%d,\"error\":%d}"

int serial_fd = -1;
pig_address _serial_addr = PI_NO_ADDRESS;

void sigint_handler(int signum) {
    if (serial_fd != -1) {
        close(serial_fd);
        serial_fd = -1;
    }
    if (co2_log_fd != -1) {
        close(co2_log_fd);
        co2_log_fd = -1;
    }
    if (co2_error_fd != -1) {
        close(co2_error_fd);
        co2_error_fd = -1;
    }
    pigpio_stop();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio_initialise() failed\n");
        return 1;
    }

    serial_fd = serOpen(_serial_addr, BAUD);
    if (serial_fd < 0) {
        fprintf(stderr, "serOpen() failed\n");
        pigpio_terminate();
        return 1;
    }

    co2_log_fd = open("co2_log.json", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (co2_log_fd < 0) {
        fprintf(stderr, "Failed to open co2_log.json\n");
        close(serial_fd);
        pigpio_terminate();
        return 1;
    }

    co2_error_fd = open("co2_error.log", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (co2_error_fd < 0) {
        fprintf(stderr, "Failed to open co2_error.log\n");
        close(serial_fd);
        pigpio_terminate();
        return 1;
    }

    uint8_t command[COMMAND_SIZE] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    uint8_t response[COMMAND_SIZE];
    int bytes_read = 0;
    uint32_t start_time = 0;
    uint32_t timeout_time = 0;

    while (1) {
        start_time = get_milliseconds();
        timeout_time = start_time + TIMEOUT_MS;

        while (start_time < timeout_time) {
            if (serDataAvailable(serial_fd)) {
                bytes_read = serRead(serial_fd, response, COMMAND_SIZE);
                if (bytes_read == COMMAND_SIZE) {
                    break;
                } else if (bytes_read > 0) {
                    // Partial read, retry later
                }
            }
            usleep(RETRY_INTERVAL_MS * 1000);
            start_time = get_milliseconds();
        }

        if (bytes_read != COMMAND_SIZE) {
            fprintf(stderr, "Timeout while reading from MH-Z19B\n");
            write_log(co2_error_fd, "Timeout while reading from MH-Z19B\n");
            continue;
        }

        uint16_t checksum = 0;
        for (int i = 0; i < 7; i++) {
            checksum += response[i];
        }
        checksum = ~checksum + CHECKSUM_INCREMENT;
        if (checksum != response[COMMAND_SIZE - 1]) {
            fprintf(stderr, "Checksum mismatch\n");
            write_log(co2_error_fd, "Checksum mismatch\n");
            continue;
        }

        uint16_t co2_ppm = (response[2] << 8) | response[3];

        time_t t = get_milliseconds() / 1000;
        fprintf(co2_log_fd, "{\"timestamp\":%lu,\"ppm\":%d,\"error\":0}\n", t, co2_ppm);
        fflush(co2_log_fd);
        fprintf(stdout, "{\"timestamp\":%lu,\"ppm\":%d,\"error\":0}\n", t, co2_ppm);
        fflush(stdout);

        usleep(5000000); // 5 seconds
    }

    close(serial_fd);
    pigpio_terminate();
    close(co2_log_fd);
    close(co2_error_fd);

    return 0;
}

// Helper functions
uint64_t get_milliseconds(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

void write_log(int fd, const char *message) {
    fprintf(stderr, "%lu: %s\n", get_milliseconds(), message);
    write(fd, message, strlen(message));
}

