#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define I2C_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define X_OFFSET 100
#define Y_OFFSET -50

float buffer[BUFFER_SIZE];
int buffer_index = 0;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

void setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(1);
    }

    if (pigpioRequest(100) < 0) {
        fprintf(stderr, "Failed to request GPIO 17.\n");
        gpioTerminate();
        exit(1);
    }

    if (i2cOpen(1, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate();
        exit(1);
    }

    i2cWriteByte(1, CONFIG_A);
    i2cWriteByte(1, 0x70);

    i2cWriteByte(1, CONFIG_B);
    i2cWriteByte(1, 0x20);

    i2cWriteByte(1, MODE);
    i2cWriteByte(1, 0x00);

    gpioSetMode(17, PI_OUTPUT);
}

void cleanup() {
    gpioTerminate();
}

void read_magnetometer(float *x, float *y, float *z) {
    uint8_t data[6];
    int ret;

    ret = i2cGetBytes(1, I2C_ADDR, 0x03, 6, data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from magnetometer.\n");
        return;
    }

    *x = (float)((data[0] << 8 | data[1]) << 8 | data[2]) * 0.02;
    *y = (float)((data[3] << 8 | data[4]) << 8 | data[5]) * 0.02;
    *z = (float)((data[6] << 8 | data[7]) << 8 | data[8]) * 0.02;

    *x -= X_OFFSET;
    *y -= Y_OFFSET;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup();

    while (1) {
        float x, y, z;
        read_magnetometer(&x, &y, &z);

        float heading = atan2(y, x);
        if (heading < 0) {
            heading += 2 * M_PI;
        }

        heading = fmod(heading * 180 / M_PI, 360);

        buffer[buffer_index] = heading;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        if (fabs(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
            gpioWrite(17, 1);
        } else {
            gpioWrite(17, 0);
        }

        printf("Heading: %.2f\n", heading);

        usleep(100 * 1000);
    }

    cleanup();
    return 0;
}

