#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define BH1750_ADDR 0x23

int i2c_fd;
int red_gpio;
int green_gpio;
int blue_gpio;

void log_message(const char *message) {
    FILE *log_file = fopen("lighting_log.txt", "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %ld\n", ctime(&now), now);
        fprintf(log_file, "Lux: %d, Red: %s, Green: %s, Blue: %s\n", lux,
                (relay_state & 1) ? "ON" : "OFF",
                (relay_state >> 1) & 1 ? "ON" : "OFF",
                (relay_state >> 2) & 1 ? "ON" : "OFF");
        fclose(log_file);
    }
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    struct gpiod_chip_pdata pdata;
    int ret;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus for BH1750");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_MASTER, NULL) < 0) {
        perror("Failed to set BH1750 as master");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_MSG_PTR_TX_DATA, &bh1750_cmd) < 0) {
        perror("Failed to send command to BH1750");
        close(i2c_fd);
        return 1;
    }

    if (read(i2c_fd, &bh1750_data, 2) != 2) {
        perror("Failed to read data from BH1750");
        close(i2c_fd);
        return 1;
    }

    lux = (bh1750_data[1] << 8) | bh1750_data[0];
    lux = lux / 1.2;

    red_gpio = gpiod_chip_get_first_line(&chip, RED_GPIO);
    green_gpio = gpiod_chip_get_first_line(&chip, GREEN_GPIO);
    blue_gpio = gpiod_chip_get_first_line(&chip, BLUE_GPIO);

    if (!red_gpio || !green_gpio || !blue_gpio) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        close(i2c_fd);
        return 1;
    }

    ret = gpiod_chip_add_line(&chip, &line, red_gpio);
    if (ret < 0) {
        fprintf(stderr, "Failed to add red GPIO line\n");
        close(i2c_fd);
        return 1;
    }
    line.direction = GPIO_DIR_OUT;
    ret = gpiod_line_export(&line);
    if (ret < 0) {
        fprintf(stderr, "Failed to export red GPIO line\n");
        gpiod_chip_remove_line(&chip, &line);
        close(i2c_fd);
        return 1;
    }

    ret = gpiod_chip_add_line(&chip, &line, green_gpio);
    if (ret < 0) {
