#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

void cleanup(int signum) {
    gpioTerminate();
    exit(signum);
}

void motor_control(int dist_a, int dist_b) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    int pwm_a, pwm_b;

    // Map distance to PWM duty cycle
    pwm_a = (dist_a < 50) ? (dist_a * 255 / 50) : 0;
    pwm_b = (dist_b < 50) ? (dist_b * 255 / 50) : 0;
    pwm_a = pwm_a > 255 ? 255 : pwm_a;
    pwm_b = pwm_b > 255 ? 255 : pwm_b;

    // Set motor directions
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Control Motor A
    if (dist_a < 50) {
        gpioWrite(MOTOR_A_IN1, 1);
        gpioWrite(MOTOR_A_IN2, 0);
        gpioPWM(MOTOR_A_IN2, pwm_a);
    } else {
        gpioWrite(MOTOR_A_IN1, 0);
        gpioWrite(MOTOR_A_IN2, 0);
    }

    // Control Motor B
    if (dist_b < 50) {
        gpioWrite(MOTOR_B_IN3, 1);
        gpioWrite(MOTOR_B_IN4, 0);
        gpioPWM(MOTOR_B_IN4, pwm_b);
    } else {
        gpioWrite(MOTOR_B_IN3, 0);
        gpioWrite(MOTOR_B_IN4, 0);
    }

    // Sleep for 100 ms
    usleep(100000);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int dist_a = 30, dist_b = 60; // Example distances

