#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>

#define STEPS 512
#define INTER_STEP_DELAY 2000

int lock_button_pressed = 0;
int unlock_button_pressed = 0;

void lock_button_callback(int pin, pig_level_t level) {
    if (level == LOW)
        lock_button_pressed = 1;
    else
        lock_button_pressed = 0;
}

void unlock_button_callback(int pin, pig_level_t level) {
    if (level == LOW)
        unlock_button_pressed = 1;
    else
        unlock_button_pressed = 0;
}

void step_motor(int direction) {
    for (int i = 0; i < STEPS; i++) {
        int* coil_pattern = direction > 0 ? (int[]){1, 0, 1, 0} : (int[]){0, 1, 0, 1};
        for (int j = 0; j < 4; j++)
            gpioSetMode(coil_pattern[j], PI_OUTPUT);

        gpioOutput(17);
        gpioOutput(18);
        gpioOutput(27);
        gpioOutput(22);

        usleep(INTER_STEP_DELAY);

        gpioOutput(17, 0);
        gpioOutput(18, 0);
        gpioOutput(27, 0);
        gpioOutput(22, 0);

        usleep(INTER_STEP_DELAY);
    }
}

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    gpioSetMode(24, PI_INPUT, PI_PULLUP);
    gpioSetMode(23, PI_INPUT, PI_PULLUP);
    gpioSetMode(17, PI_OUTPUT);
    gpioSetMode(18, PI_OUTPUT);
    gpioSetMode(27, PI_OUTPUT);
    gpioSetMode(22, PI_OUTPUT);

    gpioCallback(24, lock_button_callback);
    gpioCallback(23, unlock_button_callback);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        if (lock_button_pressed) {
            printf("Locking...\n");
            step_motor(1);
            lock_button_pressed = 0;
        }

        if (unlock_button_pressed) {
            printf("Unlocking...\n");
            step_motor(-1);
            unlock_button_pressed = 0;
        }

        usleep(100000); // 100 ms loop delay
    }

    gpioTerminate();
    return 0;
}

