#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define MPU_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define PWM_CHIP "pwmchip2"
#define PWM_SUBDEV "pwm0"
#define PWM_CHANNEL 0
#define PWM_FREQ 50
#define RETRY_DELAY 1000000 // 1 ms
#define MAX_RETRIES 5

struct sensor_data {
    float pitch;
    float roll;
};

struct servo_data {
    int position;
};

int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return fd;
}

void i2c_close(int fd) {
    close(fd);
}

int i2c_read(int fd, unsigned char reg, char *buf, int len) {
    if (len > 1) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            return -1;
        }
        if (len - 1 > read(fd, buf, 1)) {
            buf[0] = 0;
            return -1;
        }
        if (read(fd, buf + 1, len - 1) != len - 1) {
            perror("Failed to read data");
            return -1;
        }
    }
    return 0;
}

int mpu_get_data(int fd, struct sensor_data *data) {
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read(fd, 0x3B, buf, 6) < 0) {
            retries++;
            delay(RETRY_DELAY);
            continue;
        }

        data->pitch = (buf[2] << 8 | buf[3]) * 0.0048896;
        data->roll = (buf[4] << 8 | buf[5]) * 0.0048896;

        return 0;
    }

    fprintf(stderr, "Error: Failed to read MPU-6050 data after %d retries\n", MAX_RETRIES);
    return -1;
}

int pwm_init(struct servo_data *servo) {
    int pwm_fd = open("/sys/class/pwm/pwmchip2/export", O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to export PWM chip");
        return -1;
    }

    const char *path = "/sys/class/pwm/pwmchip2/pwm0";
    int ret = gpiod_export(NULL, &servo->pwm_gpio);
    if (ret < 0) {
        perror("Failed to export GPIO");
        return -1;
    }

    servo->pwm_fd = open(path, O_RDWR);
    if (servo->pwm_fd < 0) {
        perror("Failed to open PWM device");
        return -1;
    }

    char freq_str[16];
    snprintf(freq_str, sizeof(freq_str), "%d", PWM_FREQ);
    if (write(servo->pwm_fd, freq_str, strlen(freq_str)) != strlen(freq_str)) {
        perror("Failed to set PWM frequency");
        return -1;
    }

    return 0;
}

void pwm_cleanup(struct servo_data *servo) {
    close(servo->pwm_fd);
    gpiod_unexport(servo->pwm_gpio);
}

int main() {
    int mpu_fd = i2c_open(I2C_BUS);
    if (mpu_fd < 0) {
        return EXIT_FAILURE;
    }

    struct sensor_data data;
    struct servo_data servo;

    while (1) {
        if (mpu_get_data(mpu_fd, &data) < 0) {
            continue;
        }

        int duty_cycle = (data.pitch + 90) * 100 / 180; // Adjust range as needed
        char duty_cycle_str[16];
        snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", duty_cycle);

        if (write(servo.pwm_fd, duty_cycle_str, strlen(duty_cycle_str)) != strlen(duty_cycle_str)) {
            fprintf(stderr, "Error: Failed to set servo position\n");
            break;
        }

        servo.position = atoi(duty_cycle_str);

        time_t now = time(NULL);
        printf("%ld,%d,%d\n", now, data.pitch, servo.position);

        usleep(1000000); // 1 second interval
    }

    i2c_close(mpu_fd);
    pwm_cleanup(&servo);

    return EXIT_SUCCESS;
}

