        perror("Failed to open PWM device");
        return -1;
    }

    char freq_str[16];
    snprintf(freq_str, sizeof(freq_str), "%d", PWM_FREQ);
    if (write(servo->pwm_fd, freq_str, strlen(freq_str)) != strlen(freq_str)) {
        perror("Failed to set PWM frequency");
        return -1;
    }

    return 0;
}

void pwm_cleanup(struct servo_data *servo) {
    close(servo->pwm_fd);
    gpiod_unexport(servo->pwm_gpio);
}

int main() {
    int mpu_fd = i2c_open(I2C_BUS);
    if (mpu_fd < 0) {
        return EXIT_FAILURE;
    }

    struct sensor_data data;
    struct servo_data servo;

    while (1) {
        if (mpu_get_data(mpu_fd, &data) < 0) {
            continue;
        }

        int duty_cycle = (data.pitch + 90) * 100 / 180; // Adjust range as needed
        char duty_cycle_str[16];
        snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", duty_cycle);

        if (write(servo.pwm_fd, duty_cycle_str, strlen(duty_cycle_str)) != strlen(duty_cycle_str)) {
            fprintf(stderr, "Error: Failed to set servo position\n");
            break;
        }

        servo.position = atoi(duty_cycle_str);

        time_t now = time(NULL);
        printf("%ld,%d,%d\n", now, data.pitch, servo.position);

        usleep(1000000); // 1 second interval
    }

    i2c_close(mpu_fd);
    pwm_cleanup(&servo);

    return EXIT_SUCCESS;
}
