#define NUM_LAMPS 4
#define GPIO_PINS {4, 17, 27, 22}
#define PWM_FREQ 100
#define TRANSITION_TIME 1800

void fade_lamp(int relay, int state) {
    int duty = (state == 1) ? (50 * (double)gpioGetLevel(relay) + 50) : 50;
    gpioSetPWMfrequency(relay, PWM_FREQ);
    gpioSetPWMduty(relay, duty);
}

void check_schedule(void) {
    static FILE *fp = NULL;
    static char last_time[32];
    static int last_state[NUM_LAMPS];
    time_t current_time;
    struct tm *tm_info;
    char time_str[32];
    int relay, state;

    time(&current_time);
    tm_info = localtime(&current_time);
    strftime(time_str, sizeof(time_str), "%H:%M:%S", tm_info);

    if (fp != NULL) {
        fseek(fp, 0, SEEK_SET);
        fscanf(fp, "%s %d %d", time_str, &relay, &state);
        if (strcmp(time_str, last_time) != 0) {
            fade_lamp(GPIO_PINS[relay - 1], state);
            memcpy(last_state, state, NUM_LAMPS * sizeof(int));
            strcpy(last_time, time_str);
        }
    }
}

void signal_handler(int signum) {
    gpioTerminate();
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    exit(signum);
}

int main(void) {
    int i;
    gpioInitialise();
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((fp = fopen("lighting_schedule.txt", "r")) == NULL) {
        fprintf(stderr, "Error: Could not open lighting_schedule.txt\n");
        return 1;
    }

    for (i = 0; i < NUM_LAMPS; i++) {
        gpioSetMode(GPIO_PINS[i], PI_OUTPUT);
    }

    while (1) {
        check_schedule();
        usleep(1000000); // Sleep for 1 second
    }

    gpioTerminate();
    return 0;
}

