#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MAX_DISTANCE 30
#define MIN_DISTANCE 2
#define BUZZER_FREQ_MIN 200
#define BUZZER_FREQ_MAX 2000
#define MEASUREMENT_INTERVAL 20 // in ms
#define TRIG_PULSE_US 10

float map(float x, float x_min, float x_max, float y_min, float y_max) {
    return (x - x_min) * (y_max - y_min) / (x_max - x_min) + y_min;
}

int main() {
    struct timespec ts;
    gpioInit();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    int buzzer_freq = BUZZER_FREQ_MIN;
    int distance = 0;
    int timeout_count = 0;

    while (1) {
        ts.tv_sec = 0;
        ts.tv_nsec = MEASUREMENT_INTERVAL * 1000 * 1000;
        if (gpioTimeoutSet(ECHO_PIN, 10000, 0) < 0) {
            fprintf(stderr, "Timeout setting echo pin timeout\n");
            goto cleanup;
        }

        gpioWrite(TRIG_PIN, 1);
        gpioWrite(TRIG_PIN, 0);
        delay(TRIG_PULSE_US);

        if (gpioRead(ECHO_PIN) == 1) {
            ts.tv_sec = 0;
            ts.tv_nsec = 0;
            gpioTick(ECHO_PIN, &ts);

            distance = (ts.tv_sec * 1000000 + ts.tv_nsec / 1000) / 2;
            distance /= 58; // speed of sound in cm/us

            distance = clamp(distance, MIN_DISTANCE, MAX_DISTANCE);
            buzzer_freq = map(distance, MIN_DISTANCE, MAX_DISTANCE, BUZZER_FREQ_MIN, BUZZER_FREQ_MAX);
            buzzer_freq = clamp(buzzer_freq, BUZZER_FREQ_MIN, BUZZER_FREQ_MAX);

            gpioWrite(BUZZER_PIN, 1);
            pulseFrequency(BUZZER_PIN, buzzer_freq);
            gpioWrite(BUZZER_PIN, 0);
        } else {
            timeout_count++;
            if (timeout_count > 10) {
                fprintf(stderr, "Echo timeout, no sensor detected\n");
                goto cleanup;
            }
        }

        delay(100);
    }

cleanup:
    gpioTerminate();
    return 0;
}

