void set_led_color(float proximity) {
    if (proximity < 0.0 || proximity > 1.0) {
        fprintf(stderr, "Invalid proximity value: %f\n", proximity);
        return;
    }

    int red = (int)(proximity * 255);
    int green = (int)((1.0 - proximity) * 255);
    int blue = 0;

    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);

    gpioHardwarePWM(RED_GPIO, 1000, red);
    gpioHardwarePWM(GREEN_GPIO, 1000, green);
    gpioHardwarePWM(BLUE_GPIO, 1000, blue);
}

void update_proximity_value() {
    proximity_value = sin(time(NULL) / 2.0) * 0.5 + 0.5; // Simulate proximity value
}

