#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

#define SENSITIVITY_FACTOR 131.0

int main() {
    int fd;
    char filename[] = "gyro_log.txt";
    FILE *log_file;
    struct timespec ts;
    int ret;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Wake up the sensor
    if (write(fd, 0x00, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1 register");
        close(fd);
        return 1;
    }

    log_file = fopen(filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    while (1) {
        // Read gyroscope data
        if (read(fd, &ret, 1) != 1) {
            perror("Failed to read from I2C bus");
            break;
        }

        if (ret != 0x00) {
            uint16_t x_raw, y_raw, z_raw;

            // Read gyroscope data registers
            if (read(fd, (void *)&x_raw, 2) != 2) {
                perror("Failed to read gyro_xout_h and gyro_xout_l");
                break;
            }
            if (read(fd, (void *)&y_raw, 2) != 2) {
                perror("Failed to read gyro_yout_h and gyro_yout_l");
                break;
            }
            if (read(fd, (void *)&z_raw, 2) != 2) {
                perror("Failed to read gyro_zout_h and gyro_zout_l");
                break;
            }

            // Convert raw values to degrees/second
            double x = (double)x_raw - 0x8000;
            double y = (double)y_raw - 0x8000;
            double z = (double)z_raw - 0x8000;

            x *= SENSITIVITY_FACTOR;
            y *= SENSITIVITY_FACTOR;
            z *= SENSITIVITY_FACTOR;

            // Get current timestamp
            clock_gettime(CLOCK_MONOTONIC, &ts);
            char timestamp[25];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

            fprintf(log_file, "%s: x=%.2f, y=%.2f, z=%.2f\n", timestamp, x, y, z);
        }

        // Sleep for 100 ms
        nanosleep(&ts, NULL);
    }

    fclose(log_file);
    close(fd);
    return 0;
}

