#include <stdbool.h>
#include <pigpio.h>

#define BUTTON_GPIO 17
#define BUZZER_GPIO 18
#define DEBOUNCE_TIME_MS 50

const int8_t melody[] = {60, 64, 67, 69, 64, 60, 64, 67, 69, 64, 60};
volatile bool playing = false;
volatile bool button_pressed = false;

void interrupt_handler(void *ctx) {
    if (button_pressed) {
        playing = false;
        gpioHardwarePWM(BUZZER_GPIO, 0);
    }
}

void play_melody() {
    for (int i = 0; melody[i] != 0; i++) {
        int frequency = melody[i];
        gpioHardwarePWM(BUZZER_GPIO, frequency);
        playing = true;
        while (playing) {
            if (!button_pressed) {
                gpioHardwarePWM(BUZZER_GPIO, frequency);
            } else {
                playing = false;
                gpioHardwarePWM(BUZZER_GPIO, 0);
                break;
            }
        }
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode to input.\n", BUTTON_GPIO);
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode to output.\n", BUZZER_GPIO);
        return 1;
    }

    gpioSetISRFuncEx(BUTTON_GPIO, PI_INTEDGE_FALL, gpioHardwarePWM, BUZZER_GPIO);
    gpioSetCallback(BUTTON_GPIO, interrupt_handler);

    if (gpioHardwarePWM(BUZZER_GPIO, 4000) < 0) {
        fprintf(stderr, "Failed to set hardware PWM on GPIO%d.\n", BUZZER_GPIO);
