volatile bool playing = false;
volatile bool button_pressed = false;

void interrupt_handler(void *ctx) {
    if (button_pressed) {
        playing = false;
        gpioHardwarePWM(BUZZER_GPIO, 0);
    }
}

void play_melody() {
    for (int i = 0; melody[i] != 0; i++) {
        int frequency = melody[i];
        gpioHardwarePWM(BUZZER_GPIO, frequency);
        playing = true;
        while (playing) {
            if (!button_pressed) {
                gpioHardwarePWM(BUZZER_GPIO, frequency);
            } else {
                playing = false;
                gpioHardwarePWM(BUZZER_GPIO, 0);
                break;
            }
        }
    }
