#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <math.h>

#define LSM303_I2C_ADDR 0x1E
#define LSM303_MR_REG_M 0x02
#define LSM303_CRA_REG_M 0x00
#define LSM303_X_MSB_REG 0x03
#define LSM303_X_LSB_REG 0x04
#define LSM303_Z_MSB_REG 0x05
#define LSM303_Z_LSB_REG 0x06
#define LSM303_Y_MSB_REG 0x07
#define LSM303_Y_LSB_REG 0x08

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

int i2c_fd = -1;
FILE *csv_file = NULL;

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int open_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

void close_i2c() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int write_i2c(unsigned char reg, unsigned char value) {
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_MSG_WRITE, &reg) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_MSG_READ, NULL) < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int read_i2c(unsigned char reg) {
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_MSG_WRITE, &reg) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    unsigned char data[2];
    if (ioctl(i2c_fd, I2C_MSG_READ, data) < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return data[0] | (data[1] << 8);
}

float calibrated_value(int16_t raw_value) {
    return (float)raw_value - (X_OFFSET + Y_OFFSET + Z_OFFSET);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (open_i2c() < 0) {
        return -1;
    }

    if (write_i2c(LSM303_MR_REG_M, 0x00) < 0) {
        close_i2c();
        return -1;
    }

    if (write_i2c(LSM303_CRA_REG_M, 0x14) < 0) {
        close_i2c();
        return -1;
    }

    csv_file = fopen("mag_log.csv", "w");
    if (!csv_file) {
        close_i2c();
        return -1;
    }

    fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");

    while (1) {
        int16_t x_msb = read_i2c(LSM303_X_MSB_REG);
        int16_t x_lsb = read_i2c(LSM303_X_LSB_REG);
        int16_t y_msb = read_i2c(LSM303_Y_MSB_REG);
        int16_t y_lsb = read_i2c(LSM303_Y_LSB_REG);
        int16_t z_msb = read_i2c(LSM303_Z_MSB_REG);
        int16_t z_lsb = read_i2c(LSM303_Z_LSB_REG);

        float calibrated_x = calibrated_value(x_msb | (x_lsb << 8));
        float calibrated_y = calibrated_value(y_msb | (y_lsb << 8));
        float calibrated_z = calibrated_value(z_msb | (z_lsb << 8));

        double heading_rad = atan2f(calibrated_y, calibrated_x);
        if (calibrated_x < 0) {
            heading_rad += 2 * M_PI;
        }
        heading_rad = fmod(heading_rad, 2 * M_PI);

        int direction = (int)(heading_rad / (M_PI / 4)) % 8;
        switch (direction) {
            case 0:
                printf("N");
                break;
            case 1:
                printf("NE");
                break;
            case 2:
                printf("E");
                break;
            case 3:
                printf("SE");
                break;
            case 4:
                printf("S");
                break;
            case 5:
                printf("SW");
                break;
            case 6:
                printf("W");
                break;
            case 7:
                printf("NW");
                break;
        }
        printf(" %f\n", heading_rad * 180 / M_PI);

        fprintf(csv_file, "%ld,%.6f,%.6f,%.6f,%d\n", time(NULL), calibrated_x, calibrated_y, calibrated_z, direction);

        usleep(1000000);
    }

    close_i2c();
    fclose(csv_file);
    return 0;
}

