#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_TIME 200000 // 200 ms in µs

static struct timespec last_touch_time;
static int touch_state = 0;
static int relay_state = 0;
static FILE *log_file = NULL;

static void relay_callback(int pin, int level, void *userdata) {
    if (pin != RELAY_GPIO)
        return;

    int current_time_us = gpioGetBootTimeUs();
    struct timespec current_time;
    current_time.tv_sec = current_time_us / 1000000;
    current_time.tv_nsec = current_time_us % 1000000;

    if (level && !touch_state) {
        relay_state = !relay_state;
        touch_state = 1;

        if (log_file != NULL) {
            fprintf(log_file, "{\"timestamp\":\"%ld:%03ld\",\"relay_state\":\"ON\"}\n",
                    current_time.tv_sec, current_time.tv_nsec / 1000000);
            fflush(log_file);
        }
    } else if (!level && touch_state) {
        relay_state = !relay_state;
        touch_state = 0;

        if (log_file != NULL) {
            fprintf(log_file, "{\"timestamp\":\"%ld:%03ld\",\"relay_state\":\"OFF\"}\n",
                    current_time.tv_sec, current_time.tv_nsec / 1000000);
            fflush(log_file);
        }
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, relay_state);
}

int main() {
    int fd;
    int ret;

    fd = pigpio_initialise();
    if (fd < 0) {
        fprintf(stderr, "pigpio_initialise() failed\n");
        return 1;
    }

    if ((ret = gpioSetMode(TOUCH_GPIO, PI_INPUT)) != 0) {
        fprintf(stderr, "gpioSetMode() failed: %d\n", ret);
        pigpio_terminate(fd);
        return 1;
    }

    if ((ret = gpioSetPullUpDown(TOUCH_GPIO, PI_PULL_DOWN)) != 0) {
        fprintf(stderr, "gpioSetPullUpDown() failed: %d\n", ret);
        pigpio_terminate(fd);
        return 1;
    }

    if ((ret = gpioSetISRFunc(TOUCH_GPIO, PI_ISR_EDGE_RISING, relay_callback)) != 0) {
        fprintf(stderr, "gpioSetISRFunc() failed: %d\n", ret);
        pigpio_terminate(fd);
        return 1;
    }

    if ((log_file = fopen("relay_log.json", "a")) == NULL) {
        fprintf(stderr, "Failed to open relay_log.json\n");
        pigpio_terminate(fd);
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    signal(SIGINT, (void (*)(int)) relay_off_and_exit);

    while (1) {
        struct timespec remaining_time;
        remaining_time.tv_sec = DEBOUNCE_TIME / 1000000;
        remaining_time.tv_nsec = 0;

        if (pigpio_delay(remaining_time) < 0) {
            fprintf(stderr, "pigpio_delay() failed\n");
            break;
        }
    }

    relay_off_and_exit(SIGINT);

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    if (log_file != NULL) {
        fprintf(log_file, "{\"timestamp\":\"%ld:%03ld\",\"relay_state\":\"OFF\"}\n",
                timespecToMillis(&last_touch_time).tv_sec,
                timespecToMillis(&last_touch_time).tv_nsec / 1000000);
        fflush(log_file);
        fclose(log_file);
