static struct timespec last_touch_time;
static int touch_state = 0;
static int relay_state = 0;
static FILE *log_file = NULL;

static void relay_callback(int pin, int level, void *userdata) {
    if (pin != RELAY_GPIO)
        return;

    int current_time_us = gpioGetBootTimeUs();
    struct timespec current_time;
    current_time.tv_sec = current_time_us / 1000000;
    current_time.tv_nsec = current_time_us % 1000000;

    if (level && !touch_state) {
        relay_state = !relay_state;
        touch_state = 1;

        if (log_file != NULL) {
            fprintf(log_file, "{\"timestamp\":\"%ld:%03ld\",\"relay_state\":\"ON\"}\n",
                    current_time.tv_sec, current_time.tv_nsec / 1000000);
            fflush(log_file);
        }
    } else if (!level && touch_state) {
        relay_state = !relay_state;
        touch_state = 0;

        if (log_file != NULL) {
            fprintf(log_file, "{\"timestamp\":\"%ld:%03ld\",\"relay_state\":\"OFF\"}\n",
                    current_time.tv_sec, current_time.tv_nsec / 1000000);
            fflush(log_file);
        }
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, relay_state);
}

