#include <time.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define RELAY_PINS {17, 23, 24, 25}
#define MOISTURE_INTERVAL 10
#define RELAY_ON_TIME 5
#define GAP_TIME 1

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];
FILE *log_file = NULL;

void cleanup(int signum) {
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (lines) {
        for (int i = 0; i < 4; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
                lines[i] = NULL;
            }
        }
        free(lines);
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(signum);
}

void sigint_handler(int signum) {
    cleanup(signum);
}

int main() {
    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        perror("Failed to open gpiochip");
        return 1;
    }

    lines[0] = gpiod_chip_get_line(chip, RELAY_PINS[0]);
    lines[1] = gpiod_chip_get_line(chip, RELAY_PINS[1]);
    lines[2] = gpiod_chip_get_line(chip, RELAY_PINS[2]);
    lines[3] = gpiod_chip_get_line(chip, RELAY_PINS[3]);

    if (!lines[0] || !lines[1] || !lines[2] || !lines[3]) {
        for (int i = 0; i < 4; i++) {
            if (!lines[i]) {
                fprintf(stderr, "Failed to get line for relay %d\n", RELAY_PINS[i]);
                return 1;
            }
        }
    }

    gpiod_line_export(lines[0], "Relay1");
    gpiod_line_export(lines[1], "Relay2");
    gpiod_line_export(lines[2], "Relay3");
    gpiod_line_export(lines[3], "Relay4");

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    srand(time(NULL));

    log_file = fopen("irrigation_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        sleep(MOISTURE_INTERVAL);

        int moisture = rand() % 101;
        fprintf(log_file, "[%s] Moisture level: %d\n",
                 timestamp(), moisture);

        if (moisture < 30) {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(lines[i], 0);
                fprintf(log_file, "[%s] Relay %d ON\n",
                        timestamp(), RELAY_PINS[i]);
                sleep(RELAY_ON_TIME);
                gpiod_line_set_value(lines[i], 1);
                fprintf(log_file, "[%s] Relay %d OFF\n",
                        timestamp(), RELAY_PINS[i]);
                sleep(GAP_TIME);
            }
        }
    }

    return 0;
}

char *timestamp() {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm);
    return buf;
}

