#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

volatile sig_atomic_t stop_flag = 0;

#define VALVE_PIN 17
#define NOZZLE_PIN 18
#define MOISTURE_VALUES {20, 40, 60, 80, 100}
#define NUM_MOISTURE_VALUES (sizeof(MOISTURE_VALUES) / sizeof(MOISTURE_VALUES[0]))
#define NOZZLE_ANGLES {0, 45, 90, 135, 180}
#define NUM_NOZZLE_ANGLES (sizeof(NOZZLE_ANGLES) / sizeof(NOZZLE_ANGLES[0]))
#define RETRY_COUNT 3
#define RETRY_DELAY 100000 // 100 ms

void stop_watering(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    signal(SIGINT, stop_watering);
    signal(SIGTERM, stop_watering);

    gpioSetMode(VALVE_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_PIN, PI_OUTPUT);

    int valve_position = 0;
    int nozzle_angle = 0;

    for (int moisture_level = 0; moisture_level < NUM_MOISTURE_VALUES; moisture_level++) {
        int moisture = MOISTURE_VALUES[moisture_level];

        if (moisture < 50) {
            // Water the plant
            valve_position = 90;
            nozzle_angle = NOZZLE_ANGLES[0];

            for (int angle_index = 0; angle_index < NUM_NOZZLE_ANGLES; angle_index++) {
                int angle = NOZZLE_ANGLES[angle_index];

                for (int retry_count = 0; retry_count < RETRY_COUNT; retry_count++) {
                    if (gpioServo(VALVE_PIN, valve_position) < 0) {
                        usleep(RETRY_DELAY);
                        continue;
                    }
                    break;
                }

                if (gpioServo(NOZZLE_PIN, angle) < 0) {
                    fprintf(stderr, "Critical warning: Failed to set nozzle angle to %d degrees.\n", angle);
                    break;
                }

                printf("Setting nozzle to %d degrees...\n", angle);
                usleep(2000000); // Hold for 2 seconds

                for (int retry_count = 0; retry_count < RETRY_COUNT; retry_count++) {
                    if (gpioServo(NOZZLE_PIN, 0) < 0) {
                        usleep(RETRY_DELAY);
                        continue;
                    }
                    break;
                }

                if (gpioServo(VALVE_PIN, 0) < 0) {
                    fprintf(stderr, "Error: Failed to close valve servo.\n");
                }

                usleep(5000000); // Hold for 5 seconds
            }
        } else {
            printf("Moisture level (%d) is sufficient. Skipping watering.\n", moisture);
            usleep(5000000); // Wait for 5 seconds
        }
    }

    gpioTerminate();
    return 0;
}

