#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define SENSITIVITY 131.0

int i2c_fd = -1;

void log_reading(double x, double y, double z) {
    char timestamp[20];
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *log_file = fopen("gyro_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, x, y, z);
        fclose(log_file);
    } else {
        perror("Error opening log file");
    }
}

int read_gyro_data(int file_descriptor) {
    if (file_descriptor < 0) {
        return -1;
    }

    uint8_t reg_addr = GYRO_XOUT_H;
    uint8_t data[6];
    int i;

    if (ioctl(file_descriptor, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or perform i2c transaction");
        return -1;
    }

    if (ioctl(file_descriptor, I2C_RDWR, &reg_addr) < 0) {
        perror("Failed to specify register address for reading");
        return -1;
    }

    if (read(file_descriptor, data, 6) != 6) {
        perror("Failed to read data from the sensor");
        return -1;
    }

    for (i = 0; i < 6; i += 2) {
        int16_t val = (data[i] << 8) | data[i + 1];
        double raw_val = (double)val / 1000.0;
        double deg_per_sec = raw_val * SENSITIVITY;

        log_reading(
            i == 0 ? deg_per_sec : (i == 2 ? -deg_per_sec : 0),  // X, Y, Z
            i == 4 ? deg_per_sec : 0                           // Not used
        );
    }

    return 0;
}

int main() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or perform i2c transaction");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wake up the sensor
    uint8_t pwr_mgmt = 0x00;
    if (ioctl(i2c_fd, I2C_SLAVE, PWR_MGMT_1) < 0) {
        perror("Failed to acquire bus access and/or perform i2c transaction");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    write(i2c_fd, &pwr_mgmt, 1);

    signal(SIGINT, (SIG_SIGIGN));
    signal(SIGTERM, (SIG_SIGIGN));

    while (1) {
        read_gyro_data(i2c_fd);
        usleep(10000000); // 10 Hz sampling rate
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

