int direction = 1; // 1 for clockwise, -1 for counter-clockwise
int last_button_state = 0;
int debounce_delay = 50;

void sigint_handler(int signum) {
    gpioDisableOutput(COIL_PINS);
    gpioTerminate();
    exit(0);
}

void rotate_motor(int steps) {
    int i;
    for (i = 0; i < steps; i++) {
        int coil_pattern[] = {direction, -direction, -direction, direction};
        for (int j = 0; j < 4; j++) {
            gpioWrite(coil_pin_map[j], coil_pattern[j]);
        }
        usleep(INTER_STEP_DELAY);
    }
    gpioWrite(COIL_PINS, 0);
}

int main(int argc, char **argv) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    gpioSetMode(BUTTON_PINS, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PINS, 1);

    gpioSetMode(COIL_PINS, PI_OUTPUT);

    coil_pin_map[0] = gpio4;
    coil_pin_map[1] = gpio17;
    coil_pin_map[2] = gpio27;
    coil_pin_map[3] = gpio22;

    signal(SIGINT, sigint_handler);

    while (1) {
        int lock_button = gpioRead(BUTTON_PINS);
        if (lock_button && !last_button_state) {
            rotate_motor(STEPS);
            printf("Locked\n");
            last_button_state = lock_button;
            delay(debounce_delay);
        } else if (!lock_button && last_button_state) {
            rotate_motor(-STEPS);
            printf("Unlocked\n");
            last_button_state = !lock_button;
            delay(debounce_delay);
        }

        usleep(10000);
    }

    gpioTerminate();
    return 0;
}

