#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define LOG_FILE "distance_log.txt"
#define PULSE_WIDTH_TIMEOUT_US 50000
#define MIN_GUARD_MS 60
#define SPEED_OF_SOUND 343.0

FILE *log_file = NULL;
gpiod_chip *chip = NULL;
gpiod_line *trigger_line = NULL;
gpiod_line *echo_line = NULL;

void log_distance(double distance_cm) {
    if (distance_cm < 0) {
        fprintf(stderr, "Error: Distance calculation failed.\n");
    } else {
        char distance_str[20];
        snprintf(distance_str, sizeof(distance_str), "%.2f", distance_cm);
        fprintf(log_file, "%s\n", distance_str);
    }
}

void init_gpio() {
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to open GPIO chip.\n");
        return;
    }

    ret = gpiod_chip_get_line(chip, TRIG_GPIO, &trigger_line);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to get trigger line.\n");
        gpiod_chip_close(chip);
        return;
    }

    ret = gpiod_line_export(trigger_line, "user");
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to export trigger line.\n");
        gpiod_line_free(trigger_line);
        gpiod_chip_close(chip);
        return;
    }

    ret = gpiod_line_request_output(trigger_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request output on trigger line.\n");
        gpiod_line_free(trigger_line);
        gpiod_chip_close(chip);
        return;
    }

    ret = gpiod_chip_get_line(chip, ECHO_GPIO, &echo_line);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to get echo line.\n");
        gpiod_line_free(trigger_line);
        gpiod_chip_close(chip);
        return;
    }

    ret = gpiod_line_export(echo_line, "user");
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to export echo line.\n");
        gpiod_line_free(trigger_line);
        gpiod_chip_close(chip);
        return;
    }

    ret = gpiod_line_request_input(echo_line);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request input on echo line.\n");
        gpiod_line_free(trigger_line);
        gpiod_chip_close(chip);
        return;
    }
}

void cleanup_gpio() {
    if (echo_line) {
        gpiod_line_free(echo_line);
    }
    if (trigger_line) {
        gpiod_line_free(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void sigint_handler(int signum) {
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return 1;
    }

    init_gpio();

    uint64_t start_time, end_time, duration_us;
    double distance_cm;
    int rising_edge = 0, falling_edge = 0;

    while (1) {
        // Wait for minimum guard time
        usleep(MIN_GUARD_MS * 1000);

        // Generate trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Measure echo pulse width
        start_time = gpiod_line_get_value_now(echo_line);
        while ((gpiod_line_get_value_now(echo_line) == 0) && (duration_us < PULSE_WIDTH_TIMEOUT_US)) {
            usleep(5);
            duration_us = (uint64_t)(usleep(0) - start_time);
        }
        end_time = gpiod_line_get_value_now(echo_line);

        if (start_time == end_time) {
            log_distance(-1);
            continue;
        }

        rising_edge = (start_time != end_time) && (start_time > end_time);
        falling_edge = (start_time < end_time);

        if (rising_edge && falling_edge) {
            duration_us = (end_time - start_time);
            distance_cm = duration_us * 0.01715;
            log_distance(distance_cm);
        } else {
            log_distance(-1);
        }
    }

    cleanup_gpio();
    fclose(log_file);
    return 0;
}

