#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigio.h>
#include <stdbool.h>

#define RELAY_PIN 18
#define I2C_ADDR 0x29

static volatile int running = 1;
static gpio pigpio;
static int i2c_fd;

void sigint_handler(int signum) {
    running = 0;
}

void init_pigpio() {
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(EXIT_FAILURE);
    }
    gpio_setup(RELAY_PIN, pigpio_output);
    gpio_set_mode(RELAY_PIN, pigpio_output);
}

void init_i2c() {
    i2c_fd = i2c_open(I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }
}

void software_reset() {
    if (pigpio_i2c_write_read(i2c_fd, 0x0000, 0x00, NULL, 0) != 0) {
        fprintf(stderr, "Software reset failed\n");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }
}

void init_sensor() {
    if (pigpio_i2c_write_read(i2c_fd, 0x0080, 0x01, NULL, 0) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }
}

uint16_t read_distance() {
    uint8_t msb, lsb;
    if (pigpio_i2c_read(i2c_fd, 0x0096, &msb, 1) != 1 ||
        pigpio_i2c_read(i2c_fd, 0x0097, &lsb, 1) != 1) {
        fprintf(stderr, "Failed to read distance\n");
        return 0;
    }
    return (msb << 8) | lsb;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    init_pigpio();
    init_i2c();
    software_reset();
    init_sensor();

    while (running) {
        if (pigpio_i2c_read_blocking(i2c_fd, 0x0044, NULL, 1) == 1) {
            uint16_t dist = read_distance();
            printf("Distance: %d mm\n", dist);
            if (dist <= 5000) {
                gpio_write(RELAY_PIN, 1);
            } else {
                gpio_write(RELAY_PIN, 0);
            }
        }
        pigpio_delay(100 * 1000);
    }

    pigpio_stop();
    pigpio_terminate();
    i2c_close(i2c_fd);

    return 0;
}

