    gyro_raw[2] = i2c_rdwr(i2c_fd, &bytes_read, 1, GYRO_YOUT_H);
    gyro_raw[3] = i2c_rdwr(i2c_fd, &bytes_read, 1, GYRO_YOUT_L);
    gyro_raw[4] = i2c_rdwr(i2c_fd, &bytes_read, 1, GYRO_ZOUT_H);
    gyro_raw[5] = i2c_rdwr(i2c_fd, &bytes_read, 1, GYRO_ZOUT_L);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading gyro data: expected 6 bytes, got %d\n", bytes_read);
        exit(EXIT_FAILURE);
    }

    // Convert raw values to degrees/second
    double x_deg_s = (double)gyro_raw[0] << 8 | gyro_raw[1];
    double y_deg_s = (double)gyro_raw[2] << 8 | gyro_raw[3];
    double z_deg_s = (double)gyro_raw[4] << 8 | gyro_raw[5];

    x_deg_s = x_deg_s * SENSITIVITY;
    y_deg_s = y_deg_s * SENSITIVITY;
    z_deg_s = z_deg_s * SENSITIVITY;

    printf("X: %.2f, Y: %.2f, Z: %.2f\n", x_deg_s, y_deg_s, z_deg_s);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Wake up the sensor
    write(i2c_fd, &PWR_MGMT_1, 1);

    // Set gyroscope full-scale range to ±250 dps
    unsigned char config[2] = {GYRO_CONFIG, (GYRO_CONFIG << 8) | 0x03};
    write(i2c_fd, config, 2);
}

int main(int argc, char *argv[]) {
    init_i2c();

    signal(SIGINT, [](int) {
        printf("\nExiting...\n");
        close(i2c_fd);
        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int) {
        printf("\nExiting...\n");
        close(i2c_fd);
        exit(EXIT_SUCCESS);
    });

    while (1) {
        read_gyro_data();
        sleep(1);
    }

    return EXIT_SUCCESS;
}
