#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define WATERING_INTERVAL 60
#define WATERING_DURATION 5
#define LOG_FILE "watering_log.txt"

struct timespec start_time, watering_time;
int relay_pins[NUM_RELAYS] = {11, 12, 13, 15}; // BCM GPIO17, GPIO18, GPIO27, GPIO22

static int chip_fd = -1;
static struct gpiod_chip *chip;

static void sigint_handler(int signum) {
    gpiod_request_release_all(chip_fd);
    close(chip_fd);
    exit(signum);
}

static int setup_gpio(void) {
    chip_fd = gpiod_chip_open(0, "gpiochip0");
    if (chip_fd < 0) {
        perror("Failed to open gpiochip0");
        return -1;
    }
    chip = gpiod_chip_get(chip_fd);

    for (int i = 0; i < NUM_RELAYS; i++) {
        struct gpiod_line_request lr = {
            .which = gpiod_line_request_output,
            .pin = relay_pins[i],
        };

        int r = gpiod_chip_request_lines(chip_fd, &lr, NULL);
        if (r < 0) {
            fprintf(stderr, "Failed to request line %d\n", relay_pins[i]);
            return -1;
        }
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpiod_request_release_all(chip_fd);
    close(chip_fd);
}

static void water_plants(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        int r = gpiod_line_set_value_cansleep(chip_fd, relay_pins[i], 0);
        if (r < 0) {
            fprintf(stderr, "Failed to set line %d to LOW\n", relay_pins[i]);
            continue;
        }

        gettimeofday(&start_time, NULL);
        while (clock_elapsed(&start_time, &watering_time, 1) < WATERING_DURATION * 1000000);

        r = gpiod_line_set_value_cansleep(chip_fd, relay_pins[i], 1);
        if (r < 0) {
            fprintf(stderr, "Failed to set line %d to HIGH\n", relay_pins[i]);
            continue;
        }

        char log_time[14];
        strftime(log_time, sizeof(log_time), "%F %T", localtime(&time(NULL)));
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file != NULL) {
            fprintf(log_file, "%s: Watering cycle started for relay %d\n", log_time, i + 1);
            fclose(log_file);
        }
    }
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        water_plants();
        sleep(WATERING_INTERVAL);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

