#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>

#define PWM_FREQ 1000
#define DUTY_CYCLE_STEPS 256
#define SUNRISE_DURATION 30

static const int relay_pins[] = {17, 18, 27, 22};
static const int num_relays = sizeof(relay_pins) / sizeof(relay_pins[0]);

int main() {
    struct timespec ts;
    int i;
    gpioInitialise() == 0 || handle_pigpio_error("Failed to initialize pigpio library");

    for (i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0)
            handle_pigpio_error("Failed to set GPIO mode for pin %d", relay_pins[i]);
    }

    const int pwm_frequency = PWM_FREQ;
    const int duty_cycle_step = 255 / DUTY_CYCLE_STEPS;

    gpioSetPWMfrequency(relay_pins[0], pwm_frequency);
    gpioSetPWMrange(relay_pins[0], 100);

    int duty_cycle = 0;
    time_t start_time = time(NULL);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ts.tv_sec - start_time >= SUNRISE_DURATION) {
            break;
        }

        for (i = 0; i < num_relays; i++) {
            gpioSetPWMdutycycle(relay_pins[i], duty_cycle);
            duty_cycle = (duty_cycle + duty_cycle_step) % 256;
            log_event(relay_pins[i], duty_cycle);
            gpioPWMx(relay_pins[i], duty_cycle);
            usleep(1000000 / pwm_frequency); // 1-second step
        }
    }

    for (i = 0; i < num_relays; i++) {
        gpioSetPWMfrequency(relay_pins[i], 0);
        gpioSetMode(relay_pins[i], PI_INPUT);
    }

    gpioTerminate();
    return 0;
}

void handle_pigpio_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    fprintf(stderr, "Error: %s - ", format);
    vfprintf(stderr, args);
    fprintf(stderr, "\n");
    exit(EXIT_FAILURE);
    va_end(args);
}

void log_event(int pin, int duty_cycle) {
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));

    FILE *log_file = fopen("smart_lighting.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "[%s] Pin %d: Duty Cycle = %d\n", timestamp, pin, duty_cycle);
        fclose(log_file);
    }
}

