#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>

#define BUFFER_SIZE 100
#define SAMPLE_RATE_MS 50
#define MAX_REINIT_ATTEMPTS 3
#define LED_GPIO 17
#define I2C_BUS 1
#define MPU6050_ADDR 0x68

typedef struct {
    int16_t x, y, z;
    double timestamp;
} Mpu6050Reading;

Mpu6050Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initialising GPIO\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetOutputLevel(LED_GPIO, 0);
}

int init_i2c() {
    const int i2c_fd = gpioI2COpen(I2C_BUS, MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error initialising I2C\n");
        return -1;
    }
    return i2c_fd;
}

void close_i2c(int i2c_fd) {
    gpioI2CClose(i2c_fd);
}

void init_mpu6050(int i2c_fd) {
    uint8_t pwr_mgmt1 = 0x00;
    uint8_t smpl_rt_div = 0x07;
    uint8_t gyro_config = 0x00;
    uint8_t who_am_i[2];

    if (gpioI2CWrite(i2c_fd, 0x6B, &pwr_mgmt1, 1) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        close_i2c(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpioI2CWrite(i2c_fd, 0x19, &smpl_rt_div, 1) < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV register\n");
        close_i2c(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpioI2CWrite(i2c_fd, 0x1B, &gyro_config, 1) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG register\n");
        close_i2c(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpioI2CRead(i2c_fd, 0x75, who_am_i, 2) != 2) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        close_i2c(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (who_am_i[0] != 0x68 || who_am_i[1] != 0x68) {
        fprintf(stderr, "MPU-6050 not detected\n");
        close_i2c(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_gyro_data(int i2c_fd, Mpu6050Reading *reading) {
    uint8_t gyro_xout_h = 0, gyro_xout_l = 0, gyro_yout_h = 0, gyro_yout_l = 0, gyro_zout_h = 0, gyro_zout_l = 0;

    if (gpioI2CRead(i2c_fd, 0x43, &gyro_xout_h, 1) != 1 ||
        gpioI2CRead(i2c_fd, 0x44, &gyro_xout_l, 1) != 1 ||
        gpioI2CRead(i2c_fd, 0x45, &gyro_yout_h, 1) != 1 ||
        gpioI2CRead(i2c_fd, 0x46, &gyro_yout_l, 1) != 1 ||
        gpioI2CRead(i2c_fd, 0x47, &gyro_zout_h, 1) != 1 ||
        gpioI2CRead(i2c_fd, 0x48, &gyro_zout_l, 1) != 1) {

        fprintf(stderr, "Error reading gyroscope data\n");
        return;
    }

    int16_t x = (gyro_xout_h << 8 | gyro_xout_l);
    int16_t y = (gyro_yout_h << 8 | gyro_yout_l);
    int16_t z = (gyro_zout_h << 8 | gyro_zout_l);

    reading->x = x;
    reading->y = y;
    reading->z = z;
    reading->timestamp = gpioTime();
}

void update_led_state(Mpu6050Reading *reading) {
    if (abs(reading->x) > 250 || abs(reading->y) > 250 || abs(reading->z) > 250) {
        gpioSetOutputLevel(LED_GPIO, 1);
    } else {
        gpioSetOutputLevel(LED_GPIO, 0);
    }
}

int main() {
    init_gpio();
    int i2c_fd = init_i2c();

    if (i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    init_mpu6050(i2c_fd);

    while (1) {
        Mpu6050Reading reading;
        read_gyro_data(i2c_fd, &reading);

        buffer[buffer_index] = reading;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        update_led_state(&reading);

        gpioDelay(SAMPLE_RATE_MS * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

