#define SPI_DEVICE "spidev0.0"
#define BUFFER_SIZE 6
#define RETRY_ATTEMPTS 3

int spi_fd;
int gpio_chip_handle;
int chip_line;
FILE *log_file = NULL;

void cleanup(int signum) {
    gpiod_unregister(gpio_chip_handle);
    fclose(log_file);
    close(spi_fd);
}

void read_gyro_data(uint16_t *buffer) {
    for (int i = 0; i < NUM_REGISTERS; i++) {
        if (ioctl(spi_fd, SPI_RDWR, &REG_START + i) < 0) {
            fprintf(stderr, "SPI read error, retrying...\n");
            for (int j = 0; j < RETRY_ATTEMPTS; j++) {
                if (ioctl(spi_fd, SPI_RDWR, &REG_START + i) >= 0)
                    break;
                sleep(0); // Retry immediately
            }
            if (ioctl(spi_fd, SPI_RDWR, &REG_START + i) < 0) {
                fprintf(stderr, "Persistent SPI error, continuing...\n");
                return;
            }
        }
        buffer[i] = (uint16_t)((ioctl(spi_fd, SPI_RDWR, &REG_START + i) & 0xFF) << 8 | ioctl(spi_fd, SPI_RDWR, &REG_START + i + 1));
    }
}

void convert_to_degrees_per_second(uint16_t *raw_data, float *degrees_per_second) {
    for (int i = 0; i < NUM_REGISTERS; i++) {
        degrees_per_second[i] = SCALE_FACTOR * ((float)raw_data[i] / (pow(2, 15) - 1)) * 180 / M_PI;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec timestamp;
    char timestamp_str[32];

    spi_fd = spi_open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (spidev_configure(spi_fd, 1000000) < 0) {
        perror("Failed to configure SPI");
        goto spi_close_error;
    }

    gpio_chip_handle = gpiod_chip_open(GPIO_CHIP);
    if (!gpio_chip_handle) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    chip = gpiod_chip_get(gpio_chip_handle, CHIP_SELECT);
    if (!chip) {
        fprintf(stderr, "Chip not found\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        fprintf(stderr, "Line not found\n");
        return 1;
    }

    chip_line = gpiod_line_get_id(line);
    if (gpiod_line_set_direction(line, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO direction");
        return 1;
    }

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", &timestamp);
    fprintf(log_file, "%s.%09ld", timestamp_str, (unsigned long)timestamp.tv_sec * 1000000000 + timestamp.tv_nsec);
    fputc('\n', log_file);

    while (1) {
        uint16_t raw_data[BUFFER_SIZE];
        float degrees_per_second[BUFFER_SIZE];

        read_gyro_data(raw_data);
        convert_to_degrees_per_second(raw_data, degrees_per_second);

        fprintf(log_file, ",%.6f", degrees_per_second[0]);
        for (int i = 1; i < BUFFER_SIZE - 1; i++) {
            fprintf(log_file, ",%.6f", degrees_per_second[i]);
        }
        fprintf(log_file, "\n");

        gpiod_line_set_value(line, 0); // Assert chip select LOW
        clock_gettime(CLOCK_MONOTONIC, &timestamp);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", &timestamp);
        fprintf(log_file, "%s.%09ld", timestamp_str, (unsigned long)timestamp.tv_sec * 1000000000 + timestamp.tv_nsec);
        fputc('\n', log_file);

        gpiod_line_set_value(line, 1); // Deassert chip select HIGH
        sleep(0); // Busy wait for 10 ms
    }

spi_close_error:
    spi_close(spi_fd);
    return 0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);
    return main();
}

