#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <spidev.h>

#define BUFFER_SIZE 64
#define SPI_MODE 0
#define SPI_SPEED (3900000)
#define LED_GPIO 17
#define CE0_GPIO 8
#define SENSITIVITY_FACTOR 131.0

typedef struct {
    double timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

void blink_led(int sec) {
    gpio_putv(LED_GPIO, 1);
    sleep(sec);
    gpio_putv(LED_GPIO, 0);
    sleep(sec);
}

void sigint_handler(int signum) {
    printf("SIGINT received, printing buffer and releasing resources.\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%llu,%d,%d,%d\n", buffer[i].timestamp, buffer[i].x, buffer[i].y, buffer[i].z);
    }
    gpiod_release_on_exit(gpio_handle);
    spidev_release(spi_handle);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    gpio_handle = gpiod_in(CE0_GPIO);
    if (!gpio_handle) {
        fprintf(stderr, "Failed to initialize CE0 GPIO\n");
        return 1;
    }

    spi_handle = spidev_open("/dev/spidev0.0", SPI_MODE);
    if (!spi_handle) {
        fprintf(stderr, "Failed to initialize SPI\n");
        gpiod_release_on_exit(gpio_handle);
        return 1;
    }

    if (spidev_msr(spi_handle, 0x43, NULL) || spidev_msr(spi_handle, 0x45, NULL) || spidev_msr(spi_handle, 0x47, NULL)) {
        fprintf(stderr, "Failed to read gyroscope data\n");
        gpiod_release_on_exit(gpio_handle);
        spidev_close(spi_handle);
        return 1;
    }

    int16_t x = (int16_t)((spidev_ldr(spi_handle) & 0xFF) << 8) | (int16_t)spidev_ldr(spi_handle);
    int16_t y = (int16_t)((spidev_ldr(spi_handle) & 0xFF) << 8) | (int16_t)spidev_ldr(spi_handle);
    int16_t z = (int16_t)((spidev_ldr(spi_handle) & 0xFF) << 8) | (int16_t)spidev_ldr(spi_handle);

    while (1) {
        buffer[buffer_index].timestamp = time(NULL);
        buffer[buffer_index].x = x;
        buffer[buffer_index].y = y;
        buffer[buffer_index].z = z;

        if (abs(x) > 200 || abs(y) > 200 || abs(z) > 200) {
            printf("Axis exceeded limit, blinking LED\n");
            blink_led(0.5);
        }

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Sleep for a short duration to avoid high CPU usage
        usleep(100000);
    }

    gpiod_release_on_exit(gpio_handle);
    spidev_release(spi_handle);
    return 0;
}

