#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define LED_GPIO 21
#define I2C_ADDR 0x68
#define ACCEL_CONFIG 0x1C
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

float atan2f(float y, float x) {
    return atan2(y, x);
}

float pi = 3.14159265358979323846;

void log_reading(float roll, float pitch) {
    char timestamp[20];
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *log_file = fopen("tilt_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s, %f, %f\n", timestamp, roll, pitch);
        fclose(log_file);
    }
}

int main() {
    gpioInitialise();
    if (!wiringPiI2CInit()) {
        fprintf(stderr, "Failed to initialize I2C\n");
        goto exit_cleanup;
    }

    if (pigpioRequest(100, 1000) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        goto exit_cleanup;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    if (wiringPiI2CWriteReg8(I2C_ADDR, PWR_MGMT_1, 0x00) != 1) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        goto exit_cleanup;
    }

    if (wiringPiI2CWriteReg8(I2C_ADDR, ACCEL_CONFIG, 0x00) != 1) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        goto exit_cleanup;
    }

    int16_t ax, ay, az;
    while (1) {
        int res = wiringPiI2CReadReg16(I2C_ADDR, ACCEL_XOUT_H);
        if (res < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }
        res = wiringPiI2CReadReg16(I2C_ADDR, ACCEL_XOUT_L);
        if (res < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }
        res = wiringPiI2CReadReg16(I2C_ADDR, ACCEL_YOUT_H);
        if (res < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }
        res = wiringPiI2CReadReg16(I2C_ADDR, ACCEL_YOUT_L);
        if (res < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }
        res = wiringPiI2CReadReg16(I2C_ADDR, ACCEL_ZOUT_H);
        if (res < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }
        res = wiringPiI2CReadReg16(I2C_ADDR, ACCEL_ZOUT_L);
        if (res < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        ax = (int16_t)((res >> 8) & 0xFF);
        ay = (int16_t)(res & 0xFF);
        az = (int16_t)((res >> 16) & 0xFF);

        float roll = atan2f(ay, az) * 180 / pi;
        float pitch = atan2f(-ax, sqrt(ay * ay + az * az)) * 180 / pi;

        log_reading(roll, pitch);
        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        if (fabs(roll) > 45 || fabs(pitch) > 45) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        sleep(1);
    }

exit_cleanup:
    gpioTerminate();
    pigpioTerminate(0);
    return 0;
}

