#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SI1145_ADDR 0x5A
#define REG_AMBIENT_LIGHT 0x20
#define REG_PROXIMITY 0x22
#define LED_GPIO 17
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define DELAY_MS 10

int i2c_fd = -1;
int gpio_chip = -1;
int gpio_led = -1;
FILE *log_file = NULL;

void signal_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpio_chip != -1) {
        gpiod_chip_unprepare(gpio_chip);
