#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_A_GPIO 23
#define SENSOR_B_GPIO 24
#define ALERT_GPIO 17
#define MIN_DURATION_MS 500

static volatile int sensor_a_state = 0;
static volatile int sensor_b_state = 0;
static FILE *log_file = NULL;

static void seismic_event_callback(int pin, pig_edge edge, uint tick) {
    static uint last_event_tick = 0;
    uint current_tick = tick;

    if (edge == PI_RISING) {
        sensor_a_state = 1;
        sensor_b_state = 1;
    } else if (edge == PI_FALLING) {
        sensor_a_state = 0;
        sensor_b_state = 0;
    }

    if (sensor_a_state && sensor_b_state) {
        if (current_tick - last_event_tick >= MIN_DURATION_MS) {
            trigger_alert();
            log_seismic_event();
            last_event_tick = current_tick;
        }
    }
}

static void trigger_alert() {
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 1);
    sleep_ms(2000);
    gpioWrite(ALERT_GPIO, 0);
}

static void log_seismic_event() {
    if (log_file == NULL) {
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fflush(log_file);
}

int main() {
    int io_err;

    if ((io_err = pigpio_initialise()) != 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_errorMsg(io_err));
        return 1;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_terminate();
        return 1;
    }

    if ((io_err = gpioSetMode(SENSOR_A_GPIO, PI_INPUT)) != 0) {
        fprintf(stderr, "Failed to set sensor A GPIO mode: %s\n", pigpio_errorMsg(io_err));
        fclose(log_file);
        pigpio_terminate();
        return 1;
    }

    if ((io_err = gpioSetMode(SENSOR_B_GPIO, PI_INPUT)) != 0) {
        fprintf(stderr, "Failed to set sensor B GPIO mode: %s\n", pigpio_errorMsg(io_err));
        fclose(log_file);
        pigpio_terminate();
        return 1;
    }

    if ((io_err = gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_OFF)) != 0) {
        fprintf(stderr, "Failed to set pull-up/down for sensor A: %s\n", pigpio_errorMsg(io_err));
        fclose(log_file);
        pigpio_terminate();
        return 1;
    }

    if ((io_err = gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_OFF)) != 0) {
        fprintf(stderr, "Failed to set pull-up/down for sensor B: %s\n", pigpio_errorMsg(io_err));
        fclose(log_file);
        pigpio_terminate();
        return 1;
    }

    if ((io_err = gpioSetAlertMode(ALERT_GPIO, PI_ALERT_NONE)) != 0) {
        fprintf(stderr, "Failed to set alert mode for alert GPIO: %s\n", pigpio_errorMsg(io_err));
        fclose(log_file);
        pigpio_terminate();
        return 1;
    }

    if ((io_err = gpioSetAlertPullUpDown(ALERT_GPIO, PI_PUD_OFF)) != 0) {
        fprintf(stderr, "Failed to set pull-up/down for alert GPIO: %s\n", pigpio_errorMsg(io_err));
        fclose(log_file);
        pigpio_terminate();
        return 1;
    }

    if ((io_err = pigpio_register_edge_callback(SENSOR_A_GPIO, PI_RISING | PI_FALLING, &seismic_event_callback)) != 0) {
        fprintf(stderr, "Failed to register edge callback for sensor A: %s\n", pigpio_errorMsg(io_err));
        fclose(log_file);
        pigpio_terminate();
        return 1;
    }

    if ((io_err = pigpio_register_edge_callback(SENSOR_B_GPIO, PI_RISING | PI_FALLING, &seismic_event_callback)) != 0) {
        fprintf(stderr, "Failed to register edge callback for sensor B: %s\n", pigpio_errorMsg(io_err));
        fclose(log_file);
        pigpio_terminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = (void (*)(int))pigpio_stop;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handlers\n");
        pigpio_terminate();
        return 1;
    }

    while (1) {
        sleep_ms(100);
    }

    pigpio_stop();
    fclose(log_file);
    pigpio_terminate();

    return 0;
}

