    if ((io_err = pigpio_register_edge_callback(SENSOR_A_GPIO, PI_RISING | PI_FALLING, &seismic_event_callback)) != 0) {
        fprintf(stderr, "Failed to register edge callback for sensor A: %s\n", pigpio_errorMsg(io_err));
        fclose(log_file);
        pigpio_terminate();
        return 1;
    }

    if ((io_err = pigpio_register_edge_callback(SENSOR_B_GPIO, PI_RISING | PI_FALLING, &seismic_event_callback)) != 0) {
        fprintf(stderr, "Failed to register edge callback for sensor B: %s\n", pigpio_errorMsg(io_err));
        fclose(log_file);
        pigpio_terminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = (void (*)(int))pigpio_stop;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handlers\n");
        pigpio_terminate();
        return 1;
    }

    while (1) {
        sleep_ms(100);
    }

    pigpio_stop();
    fclose(log_file);
    pigpio_terminate();

    return 0;
}
