#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigio.h>

#define LED_GPIO 17
#define SPI_CS_GPIO 8
#define SPI_CLK_GPIO 11
#define SPI_MOSI_GPIO 10
#define SPI_MISO_GPIO 9
#define REG_ADDR_XL 0x02
#define REG_ADDR_XH 0x03
#define SENSITIVITY 200.0
#define THRESHOLD 20.0
#define BUFFER_SIZE 100

typedef struct {
    struct timespec timestamps[BUFFER_SIZE];
    int16_t rates[BUFFER_SIZE];
    int head;
    int tail;
} CircularBuffer;

CircularBuffer cb;

void init_buffer(CircularBuffer *buf) {
    buf->head = buf->tail = 0;
}

int is_full(CircularBuffer *buf) {
    return ((buf->head + 1) % BUFFER_SIZE) == buf->tail;
}

int is_empty(CircularBuffer *buf) {
    return buf->head == buf->tail;
}

void add_to_buffer(CircularBuffer *buf, struct timespec ts, int16_t rate) {
    buf->rates[buf->head] = rate;
    buf->timestamps[buf->head] = ts;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
}

struct timespec get_oldest_timestamp(CircularBuffer *buf) {
    return buf->timestamps[buf->tail];
}

int16_t get_oldest_rate(CircularBuffer *buf) {
    return buf->rates[buf->tail];
}

void cleanup_buffer(CircularBuffer *buf) {
    init_buffer(buf);
}

void spi_transfer(uint8_t reg_addr_msb) {
    uint8_t tx_buf[2] = {reg_addr_msb | 0x80, 0};
    uint8_t rx_buf[2];

    if (pigpio_spi_transfer(GPIOPIN_SPI0_MOSI, GPIOPIN_SPI0_MISO, GPIOPIN_SPI0_CLK, GPIOPIN_SPI0_CE0, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        exit(EXIT_FAILURE);
    }

    cb.rates[cb.tail] = (rx_buf[1] << 8) | rx_buf[0];
    cb.tail = (cb.tail + 1) % BUFFER_SIZE;
}

void sigint_handler(int signum) {
    pigpio_stop();
    gpio_set_function(LED_GPIO, GPIO_OUTPUT);
    gpio_write(LED_GPIO, 0);
    cleanup_buffer(&cb);
    exit(0);
}

int main(int argc, char *argv[]) {
    int spi_fd;
    int ret;
    struct sigaction sa;

    cb.head = cb.tail = 0;
    init_buffer(&cb);

    gpio_init();
    gpio_set_function(LED_GPIO, GPIO_OUTPUT);
    gpio_write(LED_GPIO, 0);

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = pigpio_spi_open(0, 1000000);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }

    if (pigpio_spi_enable(spi_fd, GPIOPIN_SPI0_CE0, 0) < 0) {
        fprintf(stderr, "Failed to enable SPI chip select\n");
        pigpio_spi_close(spi_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        spi_transfer(REG_ADDR_XL);
        int16_t rate_xl = cb.rates[cb.tail - 1] * SENSITIVITY;

        spi_transfer(REG_ADDR_XH);
        int16_t rate_xh = cb.rates[cb.tail - 1] >> 8;

        int16_t rate = (rate_xl + (rate_xh << 8)) >> 4;

        if (abs(rate) > THRESHOLD) {
            gpio_write(LED_GPIO, 1);
        } else {
            gpio_write(LED_GPIO, 0);
        }

        add_to_buffer(&cb, ts, rate);

        if (is_full(&cb)) {
            cleanup_buffer(&cb);
        }

        usleep(100000);
    }

    pigpio_stop();
    gpio_set_function(LED_GPIO, GPIO_OUTPUT);
    gpio_write(LED_GPIO, 0);
    pigpio_spi_close(spi_fd);
    cleanup_buffer(&cb);

    return 0;
}

