#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_FREQ  100
#define PWM_RES  255

gpio pin_map[] = {
    {17, 0},
    {18, 1},
    {27, 2}
};

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int duration, i, status;
    float duty_cycle, fade_step;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    duration = atoi(argv[1]);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration. Please provide an integer between 1 and 3600.\n");
        return 1;
    }

    status = pigpio_initialise();
    if (status < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    for (i = 0; i < 3; i++) {
        gpioSetMode(pin_map[i].pin, PI_OUTPUT);
        gpioSetPWMfrequency(pin_map[i].pin, PWM_FREQ);
        gpioSetPWMrange(pin_map[i].pin, PWM_RES);

        duty_cycle = 1.0;
        fade_step = 1.0 / PWM_RES;

        while (duty_cycle > 0) {
            gpioWrite(pin_map[i].pin, duty_cycle * PWM_RES);
            usleep(1000000 / PWM_FREQ);
            duty_cycle -= fade_step;
        }

        printf("Lamp %d faded out.\n", i + 1);
    }

    gpioTerminate();
    return 0;
}

