#define NUM_RELAYS 4
#define RED_GPIO  {17, 22}
#define YELLOW_GPIO {23, 24}
#define GREEN_GPIO {17, 22}

struct timespec state_durations[] = {
    {0, 10 * 1000 * 1000}, // Red (10 seconds)
    {2, 0}, // Yellow (2 seconds)
    {0, 10 * 1000 * 1000}, // Green (10 seconds)
    {3, 0} // Yellow (3 seconds)
};

enum state { RED, YELLOW, GREEN, YELLOW2 };
enum state current_state = RED;

static int line_states[NUM_RELAYS][2] = {
    {RED_GPIO[0], RED_GPIO[1]},
    {YELLOW_GPIO[0], YELLOW_GPIO[1]},
    {GREEN_GPIO[0], GREEN_GPIO[1]},
    {YELLOW_GPIO[0], YELLOW_GPIO[1]}
};

static int current_line[NUM_RELAYS] = {0};
static int line_count = 0;

static void state_handler(int signum) {
    printf("Interrupted by signal %d\n", signum);
    gpiod_unrequest_all();
    exit(0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = state_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip;
    int ret;

    ret = gpiod_chip_open(&chip, "GPIO17-GPIO24");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return ret;
    }

    struct gpiod_line *lines[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        ret = gpiod_chip_line_request_each(chip, line_states[i], &lines[i], NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to request lines\n");
            gpiod_chip_close(chip);
            return ret;
        }
    }

    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], 0); // Set relay LOW
        }

        printf("Transitioning to %s state\n", (current_state == RED ? "Red" : (current_state == YELLOW ? "Yellow" : "Green")));
        switch (current_state) {
            case RED:
                current_state = YELLOW;
                break;
            case YELLOW:
                current_state = YELLOW2;
                break;
            case YELLOW2:
                current_state = GREEN;
                break;
            case GREEN:
                current_state = YELLOW;
                break;
        }

        for (int i = 0; i < line_states[line_count][0]; i++) {
            gpiod_line_set_value(lines[line_count], 0); // Set relay LOW
        }

        for (int i = 0; i < line_states[line_count][1]; i++) {
            gpiod_line_set_value(lines[line_count], 1); // Set relay HIGH
        }

        line_count = (line_count + 1) % NUM_RELAYS;
        usleep(state_durations[(int)current_state].tv_sec * 1000000);
    }

    gpiod_unrequest_all();
    gpiod_chip_close(chip);

    return 0;
}

