#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define TOUCH_ELECTRODE 0
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_TIME 100000 // 100 ms in µs
#define I2C_DELAY 1000000 // 10 ms in µs

static volatile int relay_state = 0;
static int i2c_fd = -1;
static int gpio_initialized = 0;

void sigint_handler(int signum) {
    cleanup();
    exit(signum == SIGINT ? 0 : 1);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

void cleanup() {
    if (gpio_initialized) {
        gpioTerminate();
        gpio_initialized = 0;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initialising GPIO\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Default to LOW
    gpio_initialized = 1;
    return 0;
}

int init_i2c() {
    i2c_fd = ioctl_i2c_open(I2C_BUS_1, MPR121_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        return -1;
    }

    if (ioctl_i2c_write_byte(i2c_fd, 0x80) < 0) {
        fprintf(stderr, "Error writing to MPR121 register 0x80\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (ioctl_i2c_write_byte(i2c_fd, 0x63) < 0) {
        fprintf(stderr, "Error writing reset value 0x63 to MPR121\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (ioctl_i2c_write_byte(i2c_fd, 0x5E) < 0) {
        fprintf(stderr, "Error writing stop mode 0x00 to MPR121\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (ioctl_i2c_write_byte(i2c_fd, 0x5D) < 0) {
        fprintf(stderr, "Error enabling electrode 0 on MPR121\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (ioctl_i2c_write_byte(i2c_fd, TOUCH_THRESHOLD) < 0) {
        fprintf(stderr, "Error writing touch threshold 0x%X to MPR121\n", TOUCH_THRESHOLD);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (ioctl_i2c_write_byte(i2c_fd, RELEASE_THRESHOLD) < 0) {
        fprintf(stderr, "Error writing release threshold 0x%X to MPR121\n", RELEASE_THRESHOLD);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (ioctl_i2c_write_byte(i2c_fd, 0x5B) < 0) {
        fprintf(stderr, "Error writing debounce value 0x21 to MPR121\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (ioctl_i2c_write_byte(i2c_fd, 0x5C) < 0) {
        fprintf(stderr, "Error writing charge time 0x%X to MPR121\n", 0x0D);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (ioctl_i2c_write_byte(i2c_fd, 0x5E) < 0) {
        fprintf(stderr, "Error writing run mode 0x%X to MPR121\n", 0x0D);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sa.sa.handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    while (1) {
        uint8_t lsb, msb;
        if (ioctl_i2c_read_bytes(i2c_fd, 0x00, &lsb, 1) < 0) {
            fprintf(stderr, "Error reading from MPR121 register 0x00\n");
            break;
        }
        if (ioctl_i2c_read_bytes(i2c_fd, 0x01, &msb, 1) < 0) {
            fprintf(stderr, "Error reading from MPR121 register 0x01\n");
            break;
        }
        uint16_t touch_status = (msb << 8) | lsb;

        if (touch_status & (1 << TOUCH_ELECTRODE)) {
            relay_state = !relay_state;
            gpioWrite(RELAY_GPIO, relay_state);
            usleep(DEBOUNCE_TIME);
        }

        usleep(I2C_DELAY);
    }

    cleanup();
    return 0;
}
