#define FLAME_SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define LED_GPIO 23
#define DEBOUNCE_INTERVAL_MS 50

static gpiod_chip *chip;
static gpiod_line *flame_sensor_line;
static gpiod_line *buzzer_line;
static gpiod_line *led_line;
FILE *log_file = NULL;

void cleanup(int signum) {
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

void sigint_handler(int signum) {
    cleanup(signum);
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        exit(EXIT_FAILURE);
    }

    flame_sensor_line = gpiod_chip_get_line(chip, "GPIO17");
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line\n");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, "GPIO18");
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, "GPIO23");
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(flame_sensor_line, "Flame Sensor");
    gpiod_line_export(buzzer_line, "Buzzer");
    gpiod_line_export(led_line, "LED");

    gpiod_line_set_direction(flame_sensor_line, GPIO_DIR_IN);
    gpiod_line_set_direction(buzzer_line, GPIO_DIR_OUT);
    gpiod_line_set_direction(led_line, GPIO_DIR_OUT);

    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_set_value(led_line, 0);

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }
}

bool is_flame_detected() {
    int flame_state = gpiod_line_get_value(flame_sensor_line);
    static int last_state = 0;
    static int debounce_count = 0;
    static time_t last_check = 0;

    if (debounce_count == 0) {
        last_state = flame_state;
    }

    if (flame_state == last_state) {
        debounce_count++;
    } else {
        debounce_count = 0;
        last_state = flame_state;
    }

    if (debounce_count >= 3) {
        return flame_state == 0; // Active-low
    }

    return false;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_gpio();

    while (true) {
        if (is_flame_detected()) {
            fprintf(log_file, "%s\n", "Flame Detected");
            fflush(log_file);

            gpiod_line_set_value(buzzer_line, 1);
            gpiod_line_set_value(led_line, 1);

            sleep(DEBOUNCE_INTERVAL_MS / 1000);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
            gpiod_line_set_value(led_line, 0);
        }
    }

    gpiod_chip_put(chip);
    fclose(log_file);
    return 0;
}

