#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define DISPENSE_DURATION 1000
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27
#define LOG_FILE "dispense_log.txt"

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }
    return 0;
}

int set_gpio_output(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", pin);
        return 1;
    }
    return 0;
}

void dispense_cycle(int solenoid_pin1, int solenoid_pin2) {
    gpioWrite(solenoid_pin1, 1);
    gpioDelay(500000); // 0.5 seconds
    gpioWrite(solenoid_pin1, 0);

    gpioWrite(solenoid_pin2, 1);
    gpioDelay(500000); // 0.5 seconds
    gpioWrite(solenoid_pin2, 0);
}

void log_dispense(const char *timestamp, int solenoid_pin1, int solenoid_pin2, int duration) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s for writing.\n", LOG_FILE);
        return;
    }
    fprintf(log_file, "[%s] Dispensed with solenoids %d and %d for %d ms.\n", timestamp, solenoid_pin1, solenoid_pin2, duration);
    fclose(log_file);
}

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (init_pigpio() || set_gpio_output(SOLENOID_1_GPIO) || set_gpio_output(SOLENOID_2_GPIO)) {
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        dispense_cycle(SOLENOID_1_GPIO, SOLENOID_2_GPIO);
        log_dispense(timestamp, SOLENOID_1_GPIO, SOLENOID_2_GPIO, DISPENSE_DURATION);

        usleep(5000000); // 5 seconds delay
    }

    gpioTerminate();
    return 0;
}

