#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_FWD 17
#define MOTOR_A_BWD 18
#define MOTOR_B_FWD 22
#define MOTOR_B_BWD 23
#define ENA_PIN 24
#define ENB_PIN 25

#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

float tilt_error = 0.0;
float distance = 0.0;
float motor_a_speed = 0;
float motor_b_speed = 0;
float prev_error = 0;
float integral = 0;
float derivative = 0;

void pid_controller(float setpoint, float pv) {
    float error = setpoint - pv;
    integral += error;
    derivative = error - prev_error;
    motor_a_speed = Kp * error + Ki * integral + Kd * derivative;
    motor_b_speed = -motor_a_speed;
}

void motor_control(float motor_a, float motor_b) {
    gpioWrite(MOTOR_A_FWD, motor_a > 0);
    gpioWrite(MOTOR_A_BWD, motor_a < 0);
    gpioWrite(MOTOR_B_FWD, motor_b > 0);
    gpioWrite(MOTOR_B_BWD, motor_b < 0);
    gpioWrite(ENA_PIN, 1);
    gpioWrite(ENB_PIN, 1);
    gpioPWM(MOTOR_A_FWD, abs(motor_a));
    gpioPWM(MOTOR_A_BWD, abs(motor_a));
    gpioPWM(MOTOR_B_FWD, abs(motor_b));
    gpioPWM(MOTOR_B_BWD, abs(motor_b));
}

void log_control_cycle(const char *format, ...) {
    static FILE *log_file = NULL;
    static struct timespec last_log_time;
    struct timespec current_time;
    if (!log_file) {
        log_file = fopen("balance_log.txt", "a");
        if (!log_file) {
            pigpio_terminate();
            return;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &current_time);
    if (last_log_time.tv_sec != current_time.tv_sec) {
        fprintf(log_file, "\n");
        last_log_time = current_time;
    }

    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
}

void sigint_handler(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FWD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BWD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FWD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BWD, PI_OUTPUT);
    gpioSetMode(ENA_PIN, PI_OUTPUT);
    gpioSetMode(ENB_PIN, PI_OUTPUT);

    gpioPWM(MOTOR_A_FWD, 255);
    gpioPWM(MOTOR_A_BWD, 255);
    gpioPWM(MOTOR_B_FWD, 255);
    gpioPWM(MOTOR_B_BWD, 255);
    gpioWrite(ENA_PIN, 1);
    gpioWrite(ENB_PIN, 1);

    log_file = fopen("balance_log.txt", "w");
    if (!log_file) {
        pigpio_terminate();
        return 1;
    }

    while (1) {
        tilt_error = (float)(rand() / (RAND_MAX / 10.0)) * 10.0 - 5.0;
        distance = (float)(rand() / (RAND_MAX / 200.0)) * 380.0 + 2.0;

        if (distance < 20.0) {
            motor_a_speed = -127.0;
            motor_b_speed = -127.0;
        } else {
            pid_controller(0.0, tilt_error);
            motor_a_speed = clamp(motor_a_speed, -255.0, 255.0);
            motor_b_speed = clamp(motor_b_speed, -255.0, 255.0);
        }

        log_control_cycle("%s %f %f %f %f\n",
            ctime(&last_log_time), tilt_error, distance, motor_a_speed, motor_b_speed);

        motor_control(motor_a_speed, motor_b_speed);
        gpioDelay(50000);
    }

    pigpio_terminate();
    return 0;
}

