                gpioWrite(RELAY_PIN, 0);
                relay_state = 0;
            } else {
                gpioWrite(RELAY_PIN, 1);
                relay_state = 1;
            }
        }
    }

    // Clean up resources
    gpioTerminate();
    return 0;
