#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define RED_GPIO 17
#define GREEN_GPIO 18
#define BLUE_GPIO 27
#define SAMPLING_RATE 8000
#define BIT_DEPTH 16
#define CHANNELS 1
#define PERIOD_SIZE 1024
#define UPDATE_DELAY_MS 10

#ifdef ALSA_AVAILABLE
#define ALSA_DEVICE "default"
#endif

float sensitivity = 1.0;

void rms_to_rgb(float rms, unsigned char *r, unsigned char *g, unsigned char *b) {
    // Non-linear transition from cool to warm colors
    float t = rms / 32768.0;
    if (t < 0.25) {
        *r = (unsigned char)(255 * (t * 4));
        *g = (unsigned char)(255 * (1 - t * 4));
        *b = (unsigned char)(255 * (1 - t * 4));
    } else if (t < 0.5) {
        *r = (unsigned char)(255 * ((t - 0.25) * 2));
        *g = (unsigned char)(255 * (1 - (t - 0.25) * 2));
        *b = (unsigned char)(255 * (1 - (t - 0.25) * 2));
    } else {
        *r = (unsigned char)(255 * (1 - (1 - t) * 2));
        *g = (unsigned char)(255 * (1 - (1 - t) * 2));
        *b = (unsigned char)(255 * (1 - (1 - t) * 2));
    }
}

int main(int argc, char *argv[]) {
    int ret;
    int pi_init = 0;
    int alsa_init = 0;
    int gpio_red = 0, gpio_green = 0, gpio_blue = 0;
    struct snd_pcm_substream *ss = NULL;
    float rms;
    unsigned char r, g, b;

    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Error: Sensitivity must be positive. Exiting.\n");
            return 1;
        }
    }

    pi_init = pigpio_initialise();
    if (pi_init < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    gpio_red = pigpio_alloc_output(RED_GPIO);
    gpio_green = pigpio_alloc_output(GREEN_GPIO);
    gpio_blue = pigpio_alloc_output(BLUE_GPIO);
    if (!gpio_red || !gpio_green || !gpio_blue) {
        fprintf(stderr, "Error: Failed to allocate GPIO pins. Exiting.\n");
        pigpio_terminate(0);
        return 1;
    }

    if (#ifdef ALSA_AVAILABLE
            ALSA_DEVICE != NULL) {
        alsa_init = snd_pcm_open(&ss, "default", SND_PCM_STREAM_CAPTURE, 0);
        if (alsa_init < 0) {
            fprintf(stderr, "Error: Failed to open ALSA device. Exiting.\n");
            pigpio_terminate(0);
            return 1;
        }

        if (ss->substream) {
            ss->substream->runtime->delay = 10000; // 10 ms period
            if (snd_pcm_prepare(ss->substream) < 0) {
                fprintf(stderr, "Error: Failed to prepare ALSA device. Exiting.\n");
                snd_pcm_close(ss->substream);
                pigpio_terminate(0);
                return 1;
            }
        }
    }

    while (1) {
        if (#ifdef ALSA_AVAILABLE
                ALSA_DEVICE != NULL &&
                ss->substream) {
            ret = snd_pcm_readi(ss->substream, &rms, PERIOD_SIZE / 2);
            if (ret < 0) {
                if (ret == -EPIPE) {
                    fprintf(stderr, "Warning: ALSA buffer overrun. Preparing device...\n");
                    snd_pcm_prepare(ss->substream);
                } else {
                    fprintf(stderr, "Error: Failed to read from ALSA device. Exiting.\n");
                    break;
                }
            } else {
                rms_to_rgb(rms, &r, &g, &b);
                pigpio_set_PWM_duty_cycle(gpio_red, r * sensitivity);
                pigpio_set_PWM_duty_cycle(gpio_green, g * sensitivity);
                pigpio_set_PWM_duty_cycle(gpio_blue, b * sensitivity);
            }
        } else {
            // Simulate sine wave for color cycling
            float amplitude = 1.0;
            float time = (float)rand() / RAND_MAX * 2 * M_PI;
            r = (unsigned char)(amplitude * sin(time));
            g = (unsigned char)(amplitude * sin(time + M_PI / 2));
            b = (unsigned char)(amplitude * sin(time + M_PI));
            pigpio_set_PWM_duty_cycle(gpio_red, r * sensitivity);
            pigpio_set_PWM_duty_cycle(gpio_green, g * sensitivity);
            pigpio_set_PWM_duty_cycle(gpio_blue, b * sensitivity);
        }

        usleep(UPDATE_DELAY_MS * 1000);
    }

    pigpio_terminate(0);
    if (#ifdef ALSA_AVAILABLE
            ALSA_DEVICE != NULL) {
        snd_pcm_close(ss->substream);
    }

    return 0;
}

