#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define TCS34725_ADDR 0x29
#define INTEGRATION_TIME_MS 154
#define DELAY_MS 500

static pig_client *i2c;
static FILE *fp;

void sigint_handler(int signum) {
    pig_terminate(0);
    exit(signum);
}

void sigterm_handler(int signum) {
    pig_terminate(0);
    exit(signum);
}

void init_i2c() {
    i2c = pig_open(0, 1);
    if (!i2c) {
        fprintf(stderr, "Error: Failed to open I2C bus 1\n");
        exit(EXIT_FAILURE);
    }
}

void init_sensor(pig_client *i2c) {
    uint8_t reg_value = 0x03;
    if (pig_i2c_write_register(i2c, TCS34725_ADDR, 0x80, &reg_value, 1) != 1) {
        fprintf(stderr, "Error: Failed to write to sensor register 0x80\n");
        exit(EXIT_FAILURE);
    }

    uint16_t int_time = INTEGRATION_TIME_MS;
    reg_value = (uint8_t)(int_time >> 8);
    if (pig_i2c_write_register(i2c, TCS34725_ADDR, 0x81, &reg_value, 1) != 1) {
        fprintf(stderr, "Error: Failed to write to sensor register 0x81\n");
        exit(EXIT_FAILURE);
    }
    reg_value = (uint8_t)int_time;
    if (pig_i2c_write_register(i2c, TCS34725_ADDR, 0x81, &reg_value, 1) != 1) {
        fprintf(stderr, "Error: Failed to write to sensor register 0x81\n");
        exit(EXIT_FAILURE);
    }
}

void read_sensor_values(pig_client *i2c, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (pig_i2c_read_word_data(i2c, TCS34725_ADDR, 0x14, clear) != 2) {
        fprintf(stderr, "Error: Failed to read clear channel value\n");
        *clear = 0;
    }

    if (pig_i2c_read_word_data(i2c, TCS34725_ADDR, 0x15, red) != 2) {
        fprintf(stderr, "Error: Failed to read red channel value\n");
        *red = 0;
    }

    if (pig_i2c_read_word_data(i2c, TCS34725_ADDR, 0x16, green) != 2) {
        fprintf(stderr, "Error: Failed to read green channel value\n");
        *green = 0;
    }

    if (pig_i2c_read_word_data(i2c, TCS34725_ADDR, 0x17, blue) != 2) {
        fprintf(stderr, "Error: Failed to read blue channel value\n");
        *blue = 0;
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_i2c();
    init_sensor(i2c);

    fp = fopen("color_data.csv", "w");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open color_data.csv for writing\n");
        pig_close(i2c);
        return EXIT_FAILURE;
    }

    fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");

    while (1) {
        time_t now = time(NULL);
        fprintf(fp, "%ld,", now);

        uint16_t clear, red, green, blue;
        read_sensor_values(i2c, &clear, &red, &green, &blue);
        fprintf(fp, "%u,%u,%u,%u\n", clear, red, green, blue);

        gpioDelay(DELAY_MS * 1000);
    }

    fclose(fp);
    pig_close(i2c);
    pig_terminate(0);

    return EXIT_SUCCESS;
}

