#define GPIO_PIN 17
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define DEBOUNCE_INTERVAL 200000 // 200 ms

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

int main() {
    struct timespec ts;
    int fd;
    char filename[20];
    gpioInit();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    fd = open(LOG_FILE, "a");
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    while (!sigint_received) {
        gpioSetMode(GPIO_PIN, PI_OUTPUT);
        gpioWrite(GPIO_PIN, 1); // Pull high

        gpioSetMode(GPIO_PIN, PI_INPUT);
        const int state = gpioRead(GPIO_PIN);

        if (state == 0) { // Motion detected
            clock_gettime(CLOCK_MONOTONIC, &ts);
            strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S", localtime(&ts.tv_sec));
            filename[19] = '.';
            strcat(filename, "h264");

            if (fork() == 0) {
                // Child process: execute raspivid
                execlp("raspivid", "raspivid", "-t", "5000", "-o", VIDEO_DIR + filename, NULL);
                fprintf(stderr, "Failed to execute raspivid.\n");
                exit(1);
            }

            // Parent process: log the event
            if (write(fd, timestamp, strlen(timestamp)) < 0) {
                fprintf(stderr, "Failed to write to log file.\n");
                break;
            }

            // Debounce
            gpioSetMode(GPIO_PIN, PI_INPUT);
            gpioTrigger(GPIO_PIN, 1, DEBOUNCE_INTERVAL);
        }

        usleep(100000); // 100 ms delay
    }

    close(fd);
    gpioTerminate();
    return 0;
}

