#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigio.h>

#define MPU_ADDR 0x68
#define SENSITIVITY 131.0
#define SAMPLE_RATE_DIVIDER 125
#define SAMPLE_INTERVAL_MS 10
#define MAX_REINIT_ATTEMPTS 3

int i2c_fd = -1;
gpio_init();

void log_reading(double x, double y, double z, time_t timestamp) {
    FILE *log_file = fopen("gyro_log.csv", "a");
    if (log_file) {
        fprintf(log_file, "%ld,%.2f,%.2f,%.2f\n", (long)timestamp, x, y, z);
        fclose(log_file);
    }
}

void reinitialize_sensor() {
    int attempts = 0;
    while (attempts < MAX_REINIT_ATTEMPTS) {
        if (i2cOpen(MPU_ADDR, &i2c_fd) < 0) {
            fprintf(stderr, "Failed to open I2C bus\n");
            return;
        }

        if (gpioI2CWriteByteData(i2c_fd, 0x6B, 0x00) < 0) {
            fprintf(stderr, "Failed to wake MPU-6050\n");
            i2cClose(i2c_fd);
            i2c_fd = -1;
            continue;
        }

        if (gpioI2CWriteByteData(i2c_fd, 0x19, 0x07) < 0) {
            fprintf(stderr, "Failed to set sample rate divider\n");
            i2cClose(i2c_fd);
            i2c_fd = -1;
            continue;
        }

        if (gpioI2CWriteByteData(i2c_fd, 0x1B, 0x00) < 0) {
            fprintf(stderr, "Failed to set gyro FSR\n");
            i2cClose(i2c_fd);
            i2c_fd = -1;
            continue;
        }

        break;
    }

    if (i2c_fd == -1) {
        fprintf(stderr, "Exhausted reinitialization attempts\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioInitialise();
    if (i2cOpen(MPU_ADDR, &i2c_fd) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    reinitialize_sensor();

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        time_t timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        int16_t x_raw, y_raw, z_raw;
        if (gpioI2CReadI2CBlockData(i2c_fd, 0x43, 2, (uint8_t *)&x_raw, 2) < 0) {
            fprintf(stderr, "Failed to read X gyro data\n");
            reinitialize_sensor();
            continue;
        }
        if (gpioI2CReadI2CBlockData(i2c_fd, 0x45, 2, (uint8_t *)&y_raw, 2) < 0) {
            fprintf(stderr, "Failed to read Y gyro data\n");
            reinitialize_sensor();
            continue;
        }
        if (gpioI2CReadI2CBlockData(i2c_fd, 0x47, 2, (uint8_t *)&z_raw, 2) < 0) {
            fprintf(stderr, "Failed to read Z gyro data\n");
            reinitialize_sensor();
            continue;
        }

        double x_degps = x_raw * SENSITIVITY / 32768.0;
        double y_degps = y_raw * SENSITIVITY / 32768.0;
        double z_degps = z_raw * SENSITIVITY / 32768.0;

        log_reading(x_degps, y_degps, z_degps, timestamp);

