            reinitialize_sensor();
            continue;
        }
        if (gpioI2CReadI2CBlockData(i2c_fd, 0x47, 2, (uint8_t *)&z_raw, 2) < 0) {
            fprintf(stderr, "Failed to read Z gyro data\n");
            reinitialize_sensor();
            continue;
        }

        double x_degps = x_raw * SENSITIVITY / 32768.0;
        double y_degps = y_raw * SENSITIVITY / 32768.0;
        double z_degps = z_raw * SENSITIVITY / 32768.0;

        log_reading(x_degps, y_degps, z_degps, timestamp);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    i2cClose(i2c_fd);

    return EXIT_SUCCESS;
}

