#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <i2c/i2c.h>

#define ADXL_ADDR 0x53
#define DATA_FORMAT 0x31
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define SAMPLE_INTERVAL 0.1
#define FREEFALL_GPIO 27

static i2c_dev dev;
static gpio_init gpio;
static pigpio_context pi;

void sigint_handler(int signum) {
    i2c_close(&dev);
    gpio_deinit(&gpio);
    pigpio_stop(&pi);
    exit(0);
}

void freefall_event(int x, int y, int z) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%F %T", localtime(&now));

    FILE *fp = fopen("freefall.log", "a");
    if (fp) {
        fprintf(fp, "%s, %d.%03d, %d.%03d, %d.%03d\n", timestamp, x, y, z);
        fclose(fp);
    }
    pigpio_set_mode(pi, FREEFALL_GPIO, PI_OUTPUT);
    pigpio_write(pi, FREEFALL_GPIO, 1);
    delay(5000000); // 5 seconds
    pigpio_write(pi, FREEFALL_GPIO, 0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    gpio_init(&gpio);
    if (i2c_open(&dev, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (pigpio_initialise(&pi) < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (i2c_write_reg8(dev.handle, ADXL_ADDR, DATA_FORMAT, 0x0B) != 6) {
        fprintf(stderr, "Failed to configure ADXL345\n");
    }

    if (i2c_write_reg8(dev.handle, ADXL_ADDR, POWER_CTL, 0x08) != 1) {
        fprintf(stderr, "Failed to enable measurement mode\n");
    }

    while (1) {
        int16_t x_raw, y_raw, z_raw;
        if (i2c_read_words_reg16(dev.handle, ADXL_ADDR, DATAX0, &x_raw, &y_raw, &z_raw) != 3) {
            fprintf(stderr, "Failed to read ADXL345 data\n");
            continue;
        }

        float x_g = x_raw * 0.00390625;
        float y_g = y_raw * 0.00390625;
        float z_g = z_raw * 0.00390625;

        if (abs(x_g) < FREEFALL_THRESHOLD && abs(y_g) < FREEFALL_THRESHOLD && abs(z_g) < FREEFALL_THRESHOLD) {
            static float freefall_start_time = 0;
            static int freefall_confirmed = 0;

            if (!freefall_confirmed) {
                freefall_start_time = get_time_ms();
            }

            if (get_time_ms() - freefall_start_time > FREEFALL_DURATION * 1000) {
                freefall_confirmed = 1;
                freefall_event(x_g, y_g, z_g);
            }
        } else {
            freefall_confirmed = 0;
        }

        delay(SAMPLE_INTERVAL * 1000000);
    }

    i2c_close(&dev);
    gpio_deinit(&gpio);
    pigpio_stop(&pi);

    return 0;
}

