#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_RANGE_US 115200000 // 4 meters
#define MAX_TIMEOUT_US 1000000
#define TRIG_PULSE_US 10
#define LOG_FILE "distance_log.txt"

typedef struct {
    gpio pulse_gpio;
    gpio_callback_data_t callback_data;
    uint32_t ticks;
    uint32_t last_tick;
    uint32_t timeout_count;
    uint8_t running;
    pthread_mutex_t mutex;
} sensor_data;

static sensor_data sensor;
static FILE *log_file;
static struct timespec last_time;
static int signal_flag = 0;

static void trigger_callback(gpio pin, uint level, uint tick, void *data) {
    sensor_data *sd = (sensor_data *)data;
    sd->last_tick = sd->ticks;
    gpio_set_function(TRIG_PIN, PI_OUTPUT);
    gpio_write(TRIG_PIN, 1);
    delayMicroseconds(TRIG_PULSE_US);
    gpio_write(TRIG_PIN, 0);
}

static void echo_callback(gpio pin, uint level, uint tick, void *data) {
    sensor_data *sd = (sensor_data *)data;
    if (level) {
        sd->ticks++;
        if (sd->ticks >= sd->last_tick + 23200000) { // 4 meters
            sd->running = 0;
            return;
        }
    } else {
        sd->timeout_count++;
    }

    if (sd->timeout_count > MAX_TIMEOUT_US) {
        sd->running = 0;
        return;
    }
}

static void *measurement_loop(void *arg) {
    sensor.running = 1;
    gpioInitialise();
    if (gpio_initialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return NULL;
    }

    if (!(log_file = fopen(LOG_FILE, "a"))) {
        fprintf(stderr, "Failed to open log file\n");
        return NULL;
    }

    pthread_mutex_init(&sensor.mutex, NULL);

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PULLUP);

    gpioSetCallback(ECHO_PIN, echo_callback, &sensor);
    gpioSetInterruptEdge(ECHO_PIN, PI_RISING_EDGE);

    gpioSetCallback(TRIG_PIN, trigger_callback, &sensor);
    gpioSetInterruptEdge(TRIG_PIN, PI_FALLING_EDGE);

    while (sensor.running) {
        clock_gettime(CLOCK_MONOTONIC, &last_time);
        delayMicroseconds(200000);

        if (!sensor.running)
            break;

        sensor.ticks = 0;
        sensor.last_tick = 0;
        sensor.timeout_count = 0;

        pthread_mutex_lock(&sensor.mutex);
        uint32_t pulse_width = sensor.ticks - sensor.last_tick;
        pthread_mutex_unlock(&sensor.mutex);

        if (pulse_width > 23200000 || sensor.timeout_count > MAX_TIMEOUT_US)
            continue;

        double distance_m = pulse_width / 29.3;
        double distance_cm = distance_m * 100;

        char timestamp_str[50];
        struct tm *now_tm = localtime(&last_time.tv_sec);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_file, "%llu,%.3f\n", (unsigned long long)last_time.tv_sec * 1000000000 + last_time.tv_nsec, distance_cm);
        fflush(log_file);
    }

    gpioTerminate();
    fclose(log_file);
    return NULL;
}

static void sigint_handler(int signum) {
    signal_flag = 1;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    pthread_t thread;
    pthread_create(&thread, NULL, measurement_loop, NULL);

    while (!signal_flag) {
        sleep(1);
    }

    sensor.running = 0;
    pthread_join(thread, NULL);

    pthread_mutex_destroy(&sensor.mutex);

    return 0;
}

