#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_ADDR_DEFAULT 0x18
#define THRESHOLD_DEFAULT 2.0
#define SAMPLE_INTERVAL 100  // ms
#define READ_RATE 100       // Hz

static int i2c_fd;
static uint8_t addr = I2C_ADDR_DEFAULT;
static float threshold = THRESHOLD_DEFAULT;

void sigint_handler(int signum) {
    gpioTerminate();
    i2cClose(i2c_fd);
    exit(0);
}

void configure_sensor(uint8_t addr) {
    if (i2cOpen(addr, &i2c_fd) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        exit(1);
    }

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        i2cClose(i2c_fd);
        exit(1);
    }

    if (gpioSetMode(0, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        pigpio_terminate();
        exit(1);
    }

    if (i2cWriteByteData(i2c_fd, addr + 0x18, 0x57) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        gpioTerminate();
        pigpio_terminate();
        exit(1);
    }

    if (i2cWriteByteData(i2c_fd, addr + 0x1A, 0x88) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        gpioTerminate();
        pigpio_terminate();
        exit(1);
    }
}

void read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_fd, addr + 0x28, data, 6) < 0) {
        *x = *y = *z = 0;
        return;
    }

    *x = (data[0] << 4) | (data[1] >> 4);
    *y = (data[1] << 4) | (data[2] >> 4);
    *z = (data[2] << 4) | (data[3] >> 4);
}

void log_event(int16_t x, int16_t y, int16_t z) {
    char timestamp[32];
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    FILE *log_file = fopen("/var/log/high_acceleration.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s: X=%d, Y=%d, Z=%d g\n", timestamp, x, y, z);
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);

    if (argc < 2) {
        fprintf(stderr, "Usage: %s [-a <addr>] [-t <threshold>]\n", argv[0]);
        return 1;
    }

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-a") == 0) {
            if (i + 1 < argc && sscanf(argv[i + 1], "%x", &addr) == 1) {
                if (addr < 0x08 || addr > 0x77) {
                    fprintf(stderr, "Invalid I2C address: %x\n", addr);
                    return 1;
                }
            } else {
                fprintf(stderr, "Invalid I2C address format\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 < argc && sscanf(argv[i + 1], "%f", &threshold) == 1 && threshold > 0) {
            } else {
                fprintf(stderr, "Invalid threshold format or value\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Unknown argument: %s\n", argv[i]);
            return 1;
        }
        i++;
    }

    configure_sensor(addr);

    int16_t x, y, z;
    while (1) {
        read_acceleration(&x, &y, &z);

        float gx = (float)x / 100.0f;
        float gy = (float)y / 100.0f;
        float gz = (float)z / 100.0f;

        if (gx * gx + gy * gy + gz * gz > threshold * threshold) {
            log_event(x, y, z);
            system("sudo shutdown -h now");
            return 0;
        }

        gpioSetMode(0, PI_INPUT);
        sleep(SAMPLE_INTERVAL / 1000);
    }

    gpioTerminate();
    pigpio_terminate();
    return 0;
}

