#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define THRESHOLD 5.0
#define REG_START 0xC1
#define REG_READ 0xC0
#define I2C_ADDR 0x30
#define GPIO_RELAY 17
#define SAMPLE_INTERVAL 100000 // 100 ms in µs
#define POLL_ATTEMPTS 50
#define TIMEOUT_ERROR "Timeout error while polling register 0xC1"

typedef struct {
    char timestamp[20];
    int field_raw;
    float field_mT_x100;
    int relay_state;
    char error_message[50];
} MagneticEvent;

void sigint_handler(int signum) {
    gpioTerminate();
    pigpio_stop();
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (fp) {
        time_t t;
        struct tm tm;
        char buffer[80];

        time(&t);
        localtime_r(&t, &tm);
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Relay State: %d, Error: Shutdown\n", buffer, gpioGetMode(GPIO_RELAY) == PI_OUTPUT ? 1 : 0);
        fclose(fp);
    }
}

int main() {
    struct MagneticEvent event;
    gpioInitialise();
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO\n");
        return 1;
    }

    int i2c_fd = i2cOpen(I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        i2cWriteByte(i2c_fd, REG_START);
        int poll_attempts = 0;
        int reg_value = 0;
        while (poll_attempts < POLL_ATTEMPTS) {
            reg_value = i2cReadByte(i2c_fd);
            if (reg_value == 0x00) {
                break;
            }
            poll_attempts++;
            if (reg_value != 0x01) {
                sprintf(event.error_message, "%s", TIMEOUT_ERROR);
                break;
            }
            delay(1);
        }

        if (poll_attempts == POLL_ATTEMPTS) {
            sprintf(event.error_message, "%s", TIMEOUT_ERROR);
            continue;
        }

        uint8_t lsb = i2cReadByteData(i2c_fd, REG_READ + 1);
        uint8_t msb = i2cReadByteData(i2c_fd, REG_READ);
        int16_t field_raw = (msb << 8) | lsb;
        float field_mT_x100 = field_raw * 25 / 1000;

        gettimeofday(event.timestamp, NULL);
        strftime(event.timestamp, sizeof(event.timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&event.timestamp));

        if (field_mT_x100 > THRESHOLD * 100) {
            gpioSetMode(GPIO_RELAY, PI_OUTPUT);
            gpioWrite(GPIO_RELAY, 1);
            event.relay_state = 1;
        } else {
            gpioSetMode(GPIO_RELAY, PI_OUTPUT);
            gpioWrite(GPIO_RELAY, 0);
            event.relay_state = 0;
        }

        event.field_raw = field_raw;
        event.field_mT_x100 = field_mT_x100;

        FILE *fp = fopen("magnetic_events.txt", "a");
        if (fp) {
            fprintf(fp, "%s, Field mT: %.2f, Relay State: %d, Error: %s\n",
                    event.timestamp, field_mT_x100, event.relay_state, event.error_message);
            fclose(fp);
        }

        delay(SAMPLE_INTERVAL);
    }

    gpioTerminate();
    pigpio_stop();
    return 0;
}

