#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <pigpio.h>
#include <time.h>

#define PORT 5000
#define RELAY_PIN 18

static int socket_fd = -1;
static int relay_state = 0;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *ltm = localtime(&now);
    fprintf(stderr, "%02d:%02d:%02d - %s\n", ltm->tm_hour, ltm->tm_min, ltm->tm_sec, event);
}

void handle_client(int client_fd) {
    char buffer[256];
    int valread;

    while ((valread = read(client_fd, buffer, sizeof(buffer))) > 0) {
        buffer[valread] = '\0';
        char *cmd = strtok(buffer, "\n");
        if (cmd != NULL) {
            if (strcasecmp(cmd, "ON") == 0 || strcasecmp(cmd, "off") == 0) {
                if (relay_state == 0) {
                    log_event("Relay turned ON");
                    if (gpioInitialise() == -1) {
                        fprintf(stderr, "Failed to initialize pigpio\n");
                        return;
                    }
                    gpioSetMode(RELAY_PIN, PI_OUTPUT);
                    gpioWrite(RELAY_PIN, 1);
                    relay_state = 1;
                } else {
                    log_event("Relay is already ON");
                }
            } else {
                log_event("Invalid command");
            }
        }
    }

    close(client_fd);
}

int main(int argc, char *argv[]) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return 1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        return 1;
    }

    log_event("Server started");

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            return 1;
        }

        handle_client(new_socket);
    }

    return 0;
}

void cleanup(int signum) {
    close(socket_fd);
    if (socket_fd >= 0) {
        close(socket_fd);
        socket_fd = -1;
    }
    gpioTerminate();
    exit(signum);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((socket_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket");
        return 1;
    }

    // ... (rest of the main function remains the same)
}

