#include <unistd.h>
#include <gpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>

#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENA_GPIO 22
#define MOTOR_IN1_GPIO 23
#define MOTOR_IN2_GPIO 24
#define DRY_CONSECUTIVE_POLLS 3
#define MOTOR_RUN_TIME_S 5
#define POLL_INTERVAL_MS 200

int rain_sensor_state = 0;
int motor_running = 0;
int dry_consecutive_polls = 0;
time_t last_dry_state_change = 0;

void sigint_handler(int signum) {
    syslog(LOG_INFO, "SIGINT received, initiating shutdown...");
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

void sigterm_handler(int signum) {
    syslog(LOG_INFO, "SIGTERM received, initiating shutdown...");
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

void start_motor() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO, exiting...");
        exit(1);
    }

    gpioSetMode(MOTOR_ENA_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_GPIO, PI_OUTPUT);

    gpioWrite(MOTOR_ENA_GPIO, 1);
    gpioWrite(MOTOR_IN1_GPIO, 1);
    gpioWrite(MOTOR_IN2_GPIO, 0);
    motor_running = 1;
}

void stop_motor() {
    gpioWrite(MOTOR_ENA_GPIO, 0);
    gpioWrite(MOTOR_IN1_GPIO, 0);
    gpioWrite(MOTOR_IN2_GPIO, 0);
    motor_running = 0;
}

void check_rain_sensor() {
    int sensor_state;
    if (gpioRead(RAIN_SENSOR_GPIO) == 0) {
        sensor_state = 1; // Rain detected
    } else {
        sensor_state = 0; // Dry
    }

    if (sensor_state != rain_sensor_state) {
        rain_sensor_state = sensor_state;

        if (sensor_state == 0 && dry_consecutive_polls >= DRY_CONSECUTIVE_POLLS) {
            last_dry_state_change = time(NULL);
        }

        if (rain_sensor_state == 0 && motor_running == 0) {
            start_motor();
        }
    }
}

void run_motor_sequence() {
    struct timespec motor_run_time;
    motor_run_time.tv_sec = MOTOR_RUN_TIME_S;
    motor_run_time.tv_nsec = 0;

    clock_gettime(CLOCK_REALTIME, &motor_run_time);
    while (motor_running && (motor_run_time.tv_sec > 0 || motor_run_time.tv_nsec >= 100000000)) {
        gpioWrite(MOTOR_ENA_GPIO, 1);
        gpioWrite(MOTOR_IN1_GPIO, 1);
        gpioWrite(MOTOR_IN2_GPIO, 0);

        if (gpioWrite(MOTOR_ENA_GPIO, 1) < 0 || gpioWrite(MOTOR_IN1_GPIO, 1) < 0 || gpioWrite(MOTOR_IN2_GPIO, 0) < 0) {
            syslog(LOG_WARNING, "Error setting motor GPIOs, continuing...");
        }

        usleep(POLL_INTERVAL_MS * 1000);
        motor_run_time.tv_sec--;

        if (motor_run_time.tv_sec <= 0) {
            motor_running = 0;
        }
    }
}

int main(int argc, char *argv[]) {
    openlog("rain_window", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Rain-actuated window controller initialized");

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);

    while (1) {
        check_rain_sensor();

        if (motor_running) {
            run_motor_sequence();
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

