    gpioSetMode(BUTTON1_PIN, PI_INPUT, PI_PULLUP);
    gpioSetMode(BUTTON2_PIN, PI_INPUT, PI_PULLUP);

    if (gpioSetServoPulseWidth(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set servo pulse width.\n");
        gpioTerminate();
        return 1;
