    if (log_event("Deactivation due to signal %d\n", signum)) {
        gpioWrite(FLOODLIGHT_GPIO, 0);
    }
    exit(0);
}

int main() {
    struct timespec ts;
    gpioInitialise();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) < 0 || gpioSetMode(FLOODLIGHT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    GPIO_TRIGGER_SETUP *trig = malloc(sizeof(GPIO_TRIGGER_SETUP));
    if (!trig) {
        fprintf(stderr, "Failed to allocate memory for trigger setup.\n");
        gpioTerminate();
        return 1;
    }

    trig->gpio = PIR_GPIO;
    trig->pullupout = 1;
    trig->edge = PI_RISING_EDGE;
    trig->bounce = 0;
    trig->jitter = 0;

    if (gpioSetTrigger(trig) < 0) {
        free(trig);
        fprintf(stderr, "Failed to set up GPIO trigger.\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s.\n", LOG_FILE);
        free(trig);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        ts.tv_sec = 0;
        ts.tv_nsec = 100 * 1000 * 1000; // 100 ms

        int motion_detected = gpioRead(PIR_GPIO) == 1;
        if (motion_detected) {
            log_event("Motion detected, activating floodlight.\n");
            gpioWrite(FLOODLIGHT_GPIO, 1);
            if (log_event("Floodlight activated.\n")) {
                gpioWrite(FLOODLIGHT_GPIO, 0);
            }
        }

        if (gpioRead(PIR_GPIO) == 0) {
            log_event("Motion stopped, deactivating floodlight.\n");
            gpioWrite(FLOODLIGHT_GPIO, 0);
            if (log_event("Floodlight deactivated.\n")) {
                free(trig);
                fclose(log_file);
                gpioTerminate();
                return 0;
            }
        }

        nanosleep(&ts, NULL);
    }

    free(trig);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

int log_event(const char *format, ...) {
    va_list args;
    va_start(args, format);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&time(NULL)));

    vfprintf(stderr, format, args);
    fprintf(stderr, "\n");

    if (vfprintf(stderr, format, args) < 0) {
        return 0;
    }

    char *event = malloc(strlen(timestamp) + strlen(format) + 1);
    if (!event) {
        return 0;
    }

    vsprintf(event, format, args);
    fprintf(log_file, "%s %s", timestamp, event);
    free(event);

    return 1;
}
