        fprintf(stderr, "Failed to perform soft reset on MPR121\n");
        mprisClose(fd);
        return 1;
    }

    if (mprisConfigBaseline(fd, MHD_1, NHD_1, NCL_1, FDL_1) < 0) {
        fprintf(stderr, "Failed to configure baseline filtering\n");
        mprisClose(fd);
        return 1;
    }

    if (mprisSetDebounce(fd, 0x5B, DEBOUNCE_MS) < 0) {
        fprintf(stderr, "Failed to set debounce\n");
        mprisClose(fd);
        return 1;
    }

    if (mprisSetFFI(fd, 0x2C, FFI_RISE) &&
        mprisSetSFI(fd, 0x2C, SFI_RISE) &&
        mprisSetCDT(fd, 0x2C, CDT_RISE)) {
        fprintf(stderr, "Failed to set FFI/SFI/CDT\n");
        mprisClose(fd);
        return 1;
    }

