#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <time.h>
#include <stdarg.h>
#include <libgpiod.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define SERVO_PWM_FREQ 50
#define SERVO_PULSE_WIDTH_MIN 1000
#define SERVO_PULSE_WIDTH_MAX 2000
#define BUFFER_SIZE 1024

static int socket_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *servo_line;
static struct gpiod_line *pir_line;
static char buffer[BUFFER_SIZE];
static FILE *log_file = NULL;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_USER | LOG_INFO, format, args);
    if (log_file != NULL) {
        struct tm tm;
        time_t now = time(NULL);
        localtime_r(&now, &tm);
        fprintf(log_file, "[%04ld-%02d-%02dT%02d:%02d:%02d.%03ld] ",
                1900 + tm.tm_year, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                (int)(time(NULL) - now) * 1000);
        vfprintf(log_file, format, args);
        fputc('\n', log_file);
    }
    va_end(args);
}

void init_logging() {
    log_file = fopen("security.log", "a");
    if (!log_file) {
        log_message("Failed to open security.log: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_logging() {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void init_gpio() {
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        log_message("Failed to open gpiochip0: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_get_line(chip, "GPIO%d", SERVO_PIN, &servo_line);
    if (ret < 0) {
        log_message("Failed to get servo line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_get_line(chip, "GPIO%d", PIR_PIN, &pir_line);
    if (ret < 0) {
        log_message("Failed to get PIR line: %s\n", strerror(errno));
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(servo_line, NULL);
    gpiod_line_export(pir_line, NULL);

    gpiod_line_set_direction(servo_line, GPIO_OUT);
    gpiod_line_set_direction(pir_line, GPIO_IN);
}

void cleanup_gpio() {
    gpiod_line_release(servo_line);
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
}

void setup_servo_pwm(int angle) {
    int pulse_width = (angle / 180.0) * (SERVO_PULSE_WIDTH_MAX - SERVO_PULSE_WIDTH_MIN) + SERVO_PULSE_WIDTH_MIN;
    gpiod_line_set_value(servo_line, 0);
    usleep(pulse_width);
    gpiod_line_set_value(servo_line, 1);
    usleep(1000 - pulse_width);
}

int main() {
    int ret;
    struct sockaddr_in addr;
    socklen_t len = sizeof(addr);

    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        log_message("Failed to create socket: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(5000);

    ret = bind(socket_fd, (struct sockaddr *)&addr, sizeof(addr));
    if (ret < 0) {
        log_message("Failed to bind socket: %s\n", strerror(errno));
        close(socket_fd);
        return EXIT_FAILURE;
    }

    ret = listen(socket_fd, 1);
    if (ret < 0) {
        log_message("Failed to listen on socket: %s\n", strerror(errno));
        close(socket_fd);
        return EXIT_FAILURE;
    }

    init_logging();
    init_gpio();

    while (1) {
        ret = accept(socket_fd, (struct sockaddr *)NULL, NULL);
        if (ret < 0) {
            log_message("Failed to accept connection: %s\n", strerror(errno));
            continue;
        }

        char command[BUFFER_SIZE];
        int bytes_read = read(ret, command, BUFFER_SIZE);
        if (bytes_read < 0) {
            log_message("Failed to read from socket: %s\n", strerror(errno));
            close(ret);
            continue;
        }

        if (bytes_read == 0) {
            log_message("Client disconnected\n");
            close(ret);
            continue;
        }

        if (strncmp(command, "SERVO", 5) == 0) {
            int angle;
            if (sscanf(command + 5, " %d", &angle) != 1 || angle < 0 || angle > 180) {
                log_message("Invalid angle value\n");
                send(ret, "Invalid angle value\n", strlen("Invalid angle value\n"), 0);
                continue;
            }
            setup_servo_pwm(angle);
            send(ret, "SERVO_ANGLE_SET\n", 15, 0);
        } else if (strncmp(command, "PIR", 3) == 0) {
            send(ret, (pir_line->value ? "PIR:1" : "PIR:0") "\n", 11, 0);
        } else {
            send(ret, "Invalid command\n", 13, 0);
        }
    }

    cleanup_gpio();
    cleanup_logging();
    close(socket_fd);
    return 0;
}

