#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>

#define BH1750_ADDR 0x23
#define RELAY_PIN 23
#define LOG_FILE "grow_log.txt"
#define SAMPLING_INTERVAL 2000
#define MIN_LUX 150
#define ONE_TIME_HIGH_RES 0x20
#define CONVERSION_DELAY 120

int i2c_fd;
pigpio *gpio;
FILE *log_file;

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void init_i2c() {
    if (i2cOpen(0, &i2c_fd) < 0) {
        log_error("Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    if (gpioInitialize() < 0) {
        log_error("Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetPullUpDown(RELAY_PIN, 1);
}

void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
}

void close_log_file() {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void read_bh1750_lux(uint8_t *raw_data) {
    if (i2cWriteByte(i2c_fd, BH1750_ADDR, ONE_TIME_HIGH_RES) < 0) {
        log_error("Failed to write to BH1750\n");
        return;
    }
    usleep(CONVERSION_DELAY * 1000);
    if (i2cReadDevice(i2c_fd, BH1750_ADDR, 2, raw_data, 2) < 0) {
        log_error("Failed to read from BH1750\n");
        return;
    }
}

double convert_to_lux(uint8_t *raw_data) {
    return (double)(raw_data[0] << 8 | raw_data[1]) / 1.2;
}

void sample_and_control_light() {
    uint8_t raw_data[2];
    double lux = 0;

    read_bh1750_lux(raw_data);
    lux = convert_to_lux(raw_data);

    if (lux < MIN_LUX) {
        gpioSetOutputLevel(RELAY_PIN, 1); // Activate relay
    } else {
        gpioSetOutputLevel(RELAY_PIN, 0); // Deactivate relay
    }

    time_t now = time(NULL);
    fprintf(log_file, "%ld %lf\n", now, lux);
}

void cleanup() {
    gpioTerminate();
    i2cClose(i2c_fd);
    close_log_file();
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    init_i2c();
    init_gpio();
    init_log_file();

    while (1) {
        sample_and_control_light();
        sleep(SAMPLING_INTERVAL / 1000);
    }

    return 0;
}

