#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define BROKER_ADDRESS "localhost"
#define BROKER_PORT 1883
#define CLIENT_ID "relay_controller_1"
#define GPIO_PIN 17
#define RETRY_DELAY 5

mosquitto_connection *mc = NULL;
pigio_context gpio;

void mqtt_callback(mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    const char *topic = (const char *)msg->topic;
    const char *payload = (const char *)msg->payload;

    if (strcmp(topic, "home/lights/control") != 0)
        return;

    if (payload[0] == 'O' && payload[1] == 'N')
        gpioSetMode(gpio, GPIO_PIN, PI_OUTPUT);
    else if (payload[0] == 'F' && payload[1] == 'O')
        gpioSetMode(gpio, GPIO_PIN, PI_INPUT);
    else {
        syslog(LOG_ERR, "Invalid payload: %s", payload);
        return;
    }

    gpioWrite(gpio, GPIO_PIN, 0); // LOW (relay OFF)
}

void sigint_handler(int signum) {
    mosquitto_disconnect(mc);
    gpioTerminate(gpio);
    mosquitto_lib_cleanup();
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    openlog("relay_controller", LOG_PID, LOG_USER);

    gpioInit();
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }
    gpioSetMode(gpio, GPIO_PIN, PI_OUTPUT);
    gpioWrite(gpio, GPIO_PIN, 0); // LOW (relay OFF)

    mc = mosquitto_new(NULL, true);
    if (!mc) {
        syslog(LOG_ERR, "Failed to create mosquitto client");
        gpioTerminate(gpio);
        return 1;
    }

    mosquitto_connect_callback(mc, mqtt_callback);
    mosquitto_connect_options_t co;
    mosquitto_options_init(&co);
    co.cleansession = 1;
    co.keepalive = 60;
    co.username = NULL;
    co.password = NULL;
    co.will_flag = 0;
    co.will_topic = NULL;
    co.will_payload = NULL;
    co.will_qos = 0;
    co.will_retain = 0;
    co.properties = NULL;

    if (mosquitto_connect(mc, BROKER_ADDRESS, BROKER_PORT, 600, &co) < 0) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_connack_string(mosquitto_connack_resp_code(mc->last_will_code)));
        mosquitto_lib_cleanup();
        gpioTerminate(gpio);
        return 1;
    }

    if (mosquitto_subscribe(mc, "home/lights/control", 0) < 0) {
        syslog(LOG_ERR, "Failed to subscribe to topic");
        mosquitto_disconnect(mc);
        mosquitto_lib_cleanup();
        gpioTerminate(gpio);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    mosquitto_loop_forever(mc, -1, 1);

    mosquitto_disconnect(mc);
    mosquitto_lib_cleanup();
    gpioTerminate(gpio);
    closelog();

    return 0;
}

