    int servo_pins[NUM_SERVOS] = {7, 8, 9, 10, 11};
    int pulse_widths[NUM_SERVOS] = {1000, 1500, 2000, 500, 2500};
    int i;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    // Set PWM frequency and range
    for (i = 0; i < NUM_SERVOS; i++) {
        if (gpioSetMode(servo_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for servo pin %d\n", servo_pins[i]);
            goto cleanup;
        }
        if (gpioSetPWMfrequency(servo_pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for servo pin %d\n", servo_pins[i]);
            goto cleanup;
        }
        if (gpioSetPWMrange(servo_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set PWM range for servo pin %d\n", servo_pins[i]);
            goto cleanup;
        }
    }

    // Apply pulse widths and hold for 3 seconds
    for (i = 0; i < NUM_SERVOS; i++) {
        if (gpioPWM(servo_pins[i], pulse_widths[i]) < 0) {
            fprintf(stderr, "Failed to set PWM for servo pin %d\n", servo_pins[i]);
            goto cleanup;
        }
    }

    sleep(HOLD_TIME);

    // Stop PWM and release resources
    for (i = 0; i < NUM_SERVOS; i++) {
        gpioTerminate();
    }

cleanup:
    gpioTerminate();
    return (EXIT_SUCCESS);
}

