#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdatomic.h>
#include <time.h>

#define TARGET_SPEED 50.0
#define Kp 0.5
#define Ki 0.05
#define PWM_FREQ 10000
#define ENCODER_STALL_TIMEOUT 2000000000LL // 2 seconds in nanoseconds
#define CONTROL_PERIOD 100000 // 100 ms in microseconds

// Motor and encoder GPIO definitions
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23
#define ENCODER_A_PHA 4
#define ENCODER_A_PHB 5
#define ENCODER_B_PHA 6
#define ENCODER_B_PHB 12

// Shared encoder counters
_Atomic uint64_t encoder_a_count = 0;
_Atomic uint64_t encoder_b_count = 0;

// PI controller state
float integral_a = 0.0;
float integral_b = 0.0;
float previous_error_a = 0.0;
float previous_error_b = 0.0;

// Motor speeds
float motor_a_speed = 0.0;
float motor_b_speed = 0.0;

// PWM duty cycles
uint8_t pwm_a_duty = 128;
uint8_t pwm_b_duty = 128;

// Signal handler function
void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

// Encoder ISR
void encoder_isr(uint encoder, uint mode, void *data) {
    static struct timespec last_stall_check;
    struct timespec now;

    if (atomic_load(&encoder_a_count) == 0 && timespec_diff(&now, last_stall_check) > ENCODER_STALL_TIMEOUT) {
        printf("Warning: Encoder A stalled\n");
    }

    if (atomic_load(&encoder_b_count) == 0 && timespec_diff(&now, last_stall_check) > ENCODER_STALL_TIMEOUT) {
        printf("Warning: Encoder B stalled\n");
    }

    last_stall_check = now;
}

// Control loop
void control_loop() {
    static uint64_t last_time = 0;
    uint64_t current_time;
    float error_a, error_b;
    uint16_t pwm_a, pwm_b;

    while (1) {
        current_time = gpioGetTime();
        if (current_time - last_time >= CONTROL_PERIOD) {
            last_time = current_time;

            // Read encoder counts
            encoder_a_count = gpioRead(ENCODER_A_PHA);
            encoder_b_count = gpioRead(ENCODER_B_PHA);

            // Calculate motor speeds
            motor_a_speed = (float)(encoder_a_count - atomic_load(&encoder_a_count_last)) / (gpioGetBootTime() - last_time_last) * 64 * 1000; // RPM
            motor_b_speed = (float)(encoder_b_count - atomic_load(&encoder_b_count_last)) / (gpioGetBootTime() - last_time_last) * 64 * 1000; // RPM

            // PI controller
            error_a = TARGET_SPEED - motor_a_speed;
            integral_a += error_a;
            if (integral_a > 2.0) integral_a = 2.0; // Anti-windup
            pwm_a = pwm_a_duty + Kp * error_a + Ki * integral_a;
            pwm_a = constrain(pwm_a, 0, 255);

            error_b = TARGET_SPEED - motor_b_speed;
            integral_b += error_b;
            if (integral_b > 2.0) integral_b = 2.0; // Anti-windup
            pwm_b = pwm_b_duty + Kp * error_b + Ki * integral_b;
            pwm_b = constrain(pwm_b, 0, 255);

            // Update encoder counters
            atomic_store(&encoder_a_count_last, encoder_a_count);
            atomic_store(&encoder_b_count_last, encoder_b_count);

            // Set PWM duty cycles
            gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
            gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQ);
            gpioSetPWMdolayer(MOTOR_A_PWM, 0);
            gpioSetPWMrange(MOTOR_A_PWM, 0);
            gpioPWMwrite(MOTOR_A_PWM, pwm_a);

            gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
            gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQ);
            gpioSetPWMdolayer(MOTOR_B_PWM, 0);
            gpioSetPWMrange(MOTOR_B_PWM, 0);
