#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigio.h>
#include <wiringPiI2C.h>

#define RELAY_GPIO 17
#define BH1750_ADDR 0x23
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_HIGH 200
#define HISTERESIS 10
#define POLL_INTERVAL_MS 5000
#define I2C_CMD_HIGH_RES_MODE 0x21
#define RAW_TO_LUX_FACTOR 1.2

FILE *log_file = NULL;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
    fflush(log_file);
}

uint16_t read_lux_from_sensor(int fd) {
    uint8_t cmd[2] = {I2C_CMD_HIGH_RES_MODE, 0};
    write(fd, cmd, 2);

    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 180 * 1000 * 1000;
    nanosleep(&ts, NULL);

    uint16_t raw_lux;
    read(fd, &raw_lux, 2);
    return raw_lux / RAW_TO_LUX_FACTOR;
}

int main(int argc, char *argv[]) {
    pigpio *gpio;
    int fd;

    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    gpio = pigpio_initialise(NULL);
    if (!gpio) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        pigpio_terminate(NULL);
        return 1;
    }

    fd = wiringPiI2C_initialise(BH1750_ADDR);
    if (!fd) {
        fprintf(stderr, "Failed to initialize I2C bus.\n");
        pigpio_terminate(gpio);
        return 1;
    }

    log_file = fopen("chicken_coop_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        pigpio_terminate(gpio);
        wiringPiI2C_close(fd);
        return 1;
    }

    int relay_state = 0;
    uint16_t lux;

    while (1) {
        lux = read_lux_from_sensor(fd);
        log_message("%04d-%02d-%02d %02d:%02d:%02d: Lux = %d, Relay = %s\n",
                    __DATE__, __TIME__,
                    time(NULL),
                    (int)lux,
                    relay_state ? "ON" : "OFF");

        if (lux < LUX_THRESHOLD_LOW && !relay_state) {
            relay_state = 1;
            pigpio_set_mode(gpio, RELAY_GPIO, PI_OUTPUT);
            pigpio_write(gpio, RELAY_GPIO, 1);
        } else if (lux > LUX_THRESHOLD_HIGH && relay_state) {
            relay_state = 0;
            pigpio_write(gpio, RELAY_GPIO, 0);
        }

        sleep(POLL_INTERVAL_MS / 1000);
    }

    pigpio_terminate(gpio);
    fclose(log_file);
    wiringPiI2C_close(fd);

    return 0;
}

