#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_DELAY 50000 // 50 ms

static int relay_state = 0;
static int last_touch_state = 0;
static unsigned long last_touch_timestamp = 0;

void toggle_relay() {
    if (relay_state) {
        gpioWrite(RELAY_GPIO, 0);
        relay_state = 0;
        printf("Relay turned OFF at %s\n", time_iso8601());
    } else {
        gpioWrite(RELAY_GPIO, 1);
        relay_state = 1;
        printf("Relay turned ON at %s\n", time_iso8601());
    }
}

int main() {
    int ret;

    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_errorString(ret));
        return 1;
    }

    if ((ret = gpioSetMode(TOUCH_GPIO, PI_INPUT)) < 0) {
        fprintf(stderr, "TOUCH_GPIO set to input failed: %s\n", pigpio_errorString(ret));
        goto release;
    }

    if ((ret = gpioSetMode(RELAY_GPIO, PI_OUTPUT)) < 0) {
        fprintf(stderr, "RELAY_GPIO set to output failed: %s\n", pigpio_errorString(ret));
        goto release_input;
    }

    gpioSetAlert(TOUCH_GPIO, PI_FALLING, 0);

    while (1) {
        if (gpioRead(TOUCH_GPIO) != last_touch_state) {
            last_touch_state = gpioRead(TOUCH_GPIO);
            last_touch_timestamp = time(NULL);

            if (last_touch_state == 1) {
                if (time(NULL) - last_touch_timestamp > DEBOUNCE_DELAY) {
                    toggle_relay();
                }
            }
        }

        gpioWait();

        if (gpioRead(TOUCH_GPIO) == 0) {
            last_touch_state = 0;
        }

        usleep(10000); // 10 ms sleep
    }

release:
    gpioTerminate();
release_input:
    gpioSetAlert(TOUCH_GPIO, 0, 0);

    return 0;
}

