#include <string.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define HISTERESIS 0.5
#define THRESHOLD 5.0
#define DEBOUNCE_TIMEOUT 1000000

int pulse_counter = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void flow_callback(int pin, uint pulse_time_us, void *user_data) {
    int ret;
    if ((ret = pthread_mutex_lock(&mutex)) != 0) {
        fprintf(stderr, "Error locking mutex: %s\n", strerror(ret));
        return;
    }
    pulse_counter++;
    if ((pthread_mutex_unlock(&mutex)) != 0) {
        fprintf(stderr, "Error unlocking mutex: %s\n", strerror(ret));
    }
}

void log_lpm_reading(double lpm) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld: LPM = %.2f\n", now, lpm);
        fflush(log_file);
    }
}

void log_solenoid_state(int state) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld: Solenoid state = %d\n", now, state);
        fflush(log_file);
    }
}

void toggle_solenoid(double lpm) {
    int ret;
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Error initialising pigpio: %s\n", pigpio_errorString(ret));
        exit(EXIT_FAILURE);
    }

    if ((ret = gpioSetMode(FLOW_SENSOR_GPIO, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting flow sensor GPIO mode: %s\n", pigpio_errorString(ret));
        goto cleanup;
    }

    if ((ret = gpioSetMode(SOLENOID_GPIO, PI_INPUT)) < 0) {
        fprintf(stderr, "Error setting solenoid GPIO mode: %s\n", pigpio_errorString(ret));
        goto cleanup;
    }

    if ((ret = gpioSetISRFuncEx(FLOW_SENSOR_GPIO, PI_RISING_FALLING, flow_callback, &pulse_counter)) < 0) {
        fprintf(stderr, "Error setting ISR function for flow sensor: %s\n", pigpio_errorString(ret));
        goto cleanup;
    }

    if ((ret = gpioSetAlertFunc(SOLENOID_GPIO, PI_ALERT_RISING_FALLING, NULL)) < 0) {
        fprintf(stderr, "Error setting alert function for solenoid: %s\n", pigpio_errorString(ret));
        goto cleanup;
    }

    if ((log_file = fopen("water_flow.log", "a")) == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        goto cleanup;
    }

    if ((ret = pthread_create(&thread, NULL, &sample_lpm, NULL)) != 0) {
        fprintf(stderr, "Error creating thread: %s\n", strerror(ret));
        goto cleanup;
    }

cleanup:
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    return;
}

void *sample_lpm(void *arg) {
    double prev_lpm = 0.0;
    double lpm;
    int solenoid_state = 1;

    while (1) {
        if ((pthread_mutex_lock(&mutex)) != 0) {
            fprintf(stderr, "Error locking mutex: %s\n", strerror(errno));
            break;
        }

        lpm = (pulse_counter / 450.0) * 60.0;
        log_lpm_reading(lpm);

        if (lpm > THRESHOLD + HISTERESIS && solenoid_state) {
            gpioWrite(SOLENOID_GPIO, 0);
            solenoid_state = 0;
            log_solenoid_state(0);
        } else if (lpm < THRESHOLD - HISTERESIS && solenoid_state == 0) {
            gpioWrite(SOLENOID_GPIO, 1);
            solenoid_state = 1;
            log_solenoid_state(1);
        }

        pulse_counter = 0;
        pthread_mutex_unlock(&mutex);

        sleep(1);
    }

    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    int ret;
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    toggle_solenoid(0.0);

    while (1) {
        sleep(1);
    }

    return 0;
}

void sigint_handler(int signo) {
    log_solenoid_state(1);
    gpioWrite(SOLENOID_GPIO, 1);
    fclose(log_file);
    pthread_destroy(thread, NULL);
    pthread_mutex_destroy(&mutex);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int signo) {
    sigint_handler(signo);
}

pthread_t thread;
```

This code initializes the pigpio library, sets up the flow sensor and solenoid GPIO pins, and configures interrupt-driven pulse counting with a debounce timeout. It uses a mutex to protect the shared pulse counter and samples the LPM every second. The solenoid state changes are logged along with LPM readings. The program handles SIGINT and SIGTERM signals by logging the event, reopening the solenoid to its safe state, closing the log file, destroying the mutex, and calling `gpioTerminate()`.

