#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE 50

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);
}

int main(int argc, char *argv[]) {
    setup_signal_handlers();

    int debounce_delay = DEFAULT_DEBOUNCE;
    if (argc > 1 && strcmp(argv[1], "-d") == 0) {
        if (argc < 3) {
            fprintf(stderr, "Usage: %s <debounce_ms>\n", argv[0]);
            exit(1);
        }
        debounce_delay = atoi(argv[2]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(1);
    }

    if (gpioSetMode(TOUCH_PIN, PI_OUTPUT) < 0 || gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        exit(1);
    }

    gpioSetWarningHandler(NULL);

    const int touch_state = 0; // Idle (LOW)
    int last_touch_state = touch_state;
    unsigned long last_change = 0;
    unsigned long debounce_timeout = 0;

    while (1) {
        gpioRead(TOUCH_PIN, &touch_state);

        if (touch_state != last_touch_state) {
            last_change = millis();
        }

        if ((millis() - last_change) > debounce_delay) {
            if (touch_state != last_touch_state) {
                if (touch_state == 1) { // HIGH (touched)
                    gpioWrite(RELAY_PIN, 1);
                    printf("Relay: ON\n");
                } else { // LOW (not touched)
                    gpioWrite(RELAY_PIN, 0);
                    printf("Relay: OFF\n");
                }
                last_touch_state = touch_state;
            }
        }

        if (gpioPending(TOUCH_PIN)) {
            unsigned int edge = gpioRead(TOUCH_PIN);
            if (edge == 1 && last_touch_state == 0) {
                gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
                printf("Relay: %s\n", gpioRead(RELAY_PIN) ? "ON" : "OFF");
            }
            gpioClearPending(TOUCH_PIN);
        }

        if (gpioPending(RELAY_PIN)) {
            gpioClearPending(RELAY_PIN);
        }

        if (millis() - last_change > debounce_delay) {
            last_change = millis();
        }

        usleep(100000); // 50 ms polling interval
    }

    gpioTerminate();
    return 0;
}

