#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQ 50
#define PWM_PERIOD (1000000 / PWM_FREQ)
#define ANGLE_STEP 10
#define MIN_PULSE 500
#define MAX_PULSE 2500

int servo_angle = 90;
int termios_flags;

void save_termios() {
    termios_flags = termios.c_flags;
}

void restore_termios() {
    if (tcsetattr(STDIN_FILENO, TCSANOW, &termios_flags) == -1) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

void handle_sigint(int signum) {
    gpioStopServo(SERVO_PIN);
    gpioTerminate();
    restore_termios();
    exit(0);
}

void set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        angle = (angle < 0) ? 0 : 180;
    }

    int pulse_width = (angle * (MAX_PULSE - MIN_PULSE)) / 180 + MIN_PULSE;
    if (pulse_width < MIN_PULSE || pulse_width > MAX_PULSE) {
        pulse_width = (angle < 0) ? MIN_PULSE : MAX_PULSE;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, PWM_PERIOD);
    gpioSetPWMrange(SERVO_PIN, PI_PWM_MODE_MS);
    gpioSetServoPulsewidth(SERVO_PIN, pulse_width);
    servo_angle = angle;
    printf("Servo angle: %d\n", angle);
}

int main() {
    save_termios();
    const struct sigaction sa = { .sa_handler = handle_sigint };
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise() failed with error code %d\n", errno);
        return EXIT_FAILURE;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, PWM_PERIOD);
    gpioSetPWMrange(SERVO_PIN, PI_PWM_MODE_MS);
    gpioSetServoPulsewidth(SERVO_PIN, (MIN_PULSE + MAX_PULSE) / 2);

    while (1) {
        struct termios termios;
        tcgetattr(STDIN_FILENO, &termios);
        termios.c_lflag &= ~ICANON;
        tcsetattr(STDIN_FILENO, TCSANOW, &termios);

        int c = getchar();
        switch (c) {
            case '+':
                set_servo_angle(servo_angle + ANGLE_STEP);
                break;
            case '-':
                set_servo_angle(servo_angle - ANGLE_STEP);
                break;
            case 'q':
                gpioStopServo(SERVO_PIN);
                gpioTerminate();
                restore_termios();
                exit(0);
            default:
                continue;
        }
    }

    gpioStopServo(SERVO_PIN);
    gpioTerminate();
    restore_termios();
    return 0;
}

