#include <stdbool.h>
#include <signal.h>
#include <errno.h>

#define DEBOUNCE_WINDOW_NS (2 * 1000 * 1000)
#define SAMPLE_INTERVAL_S (5)
#define PULSES_PER_REVOLUTION (1)

static volatile unsigned long pulseCount = 0;
static FILE *logFile = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void sigint_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        if (logFile != NULL) {
            fclose(logFile);
        }
        exit(0);
    }
}

static void count_pulse_event(struct gpiod_line *line_, struct gpiod_event event, void *user_data) {
    if (event.type == GPIOD_EVENT_TYPE_ACTIVE_HIGH || event.type == GPIOD_EVENT_TYPE_ACTIVE_LOW) {
        if (event.timestamp - user_data >= DEBOUNCE_WINDOW_NS) {
            pulseCount++;
        }
    }
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR | O_CLOEXEC);
    if (chip == NULL) {
        fprintf(stderr, "Error: gpiod_chip_open() failed: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, "GPIO17");
    if (line == NULL) {
        fprintf(stderr, "Error: gpiod_chip_get_line() failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input_flags(line, &gpiod_line_event_wait, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Error: gpiod_line_request_input_flags() failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    logFile = fopen("motor_rpm.log", "w");
    if (!logFile) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpiod_chip_close(chip);
        return 1;
    }

    while (true) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double rpm = (double)pulseCount / SAMPLE_INTERVAL_S * 60.0;
        pulseCount = 0;

        char timestamp[33];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));

        fprintf(logFile, "%s,%.2f\n", timestamp, rpm);
        fflush(logFile);
        printf("Current RPM: %.2f\n", rpm);

        sleep(SAMPLE_INTERVAL_S);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(logFile);
    return 0;
}

