#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

volatile sig_atomic_t cleanup_flag = 0;

static void signal_handler(int signum) {
    cleanup_flag = 1;
}

int main() {
    struct timespec touch_timeout = {0, 300000000000L}; // 10 seconds
    gpioInitialise();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    if (gpioSetMode(4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO4 mode.\n");
        goto terminate;
    }

    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 mode.\n");
        goto terminate;
    }

    gpioWrite(17, 0); // Ensure relay is OFF initially

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!cleanup_flag) {
        int touch_state = gpioRead(4);
        if (touch_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading touch sensor.\n");
            goto terminate;
        }

        if (touch_state) {
            static int last_state = 0;
            static struct timespec last_touch_time;

            if (touch_state != last_state) {
                last_state = touch_state;
                if (timespecDiff(&touch_timeout, &last_touch_time) > 0) {
                    gpioWrite(17, !gpioRead(17));
                    last_touch_time = touch_timeout;
                }
            } else {
                if (timespecDiff(&touch_timeout, &last_touch_time) > 10000000000L) { // 10 seconds
                    gpioWrite(17, 0); // Force relay OFF
                    touch_state = 0; // Ignore further toggles
                }
            }
        }

        usleep(50000); // Poll every 50 ms
    }

terminate:
    gpioWrite(17, 0); // Ensure relay is OFF before cleanup
    gpioTerminate();

    return 0;
}

