#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define PWM_PIN 18
#define ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24
#define SAMPLE_INTERVAL_MS 100
#define PULSES_PER_LITER 450.0
#define Kp 1.0

float target_flow_rate;
float error;
float output;
int last_pulse_count = 0;
unsigned long last_sample_time_ms = 0;
FILE *log_file = NULL;

void sigint_handler(int signum) {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(1);
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    if (gpioSetPWMfrequency(PWM_PIN, 1000) < 0) {
        fprintf(stderr, "PWM frequency setup failed\n");
        gpioTerminate();
        exit(1);
    }

    gpioSetOutputLevel(ENABLE_PIN, 1);
    gpioSetPWMset(PWM_PIN, 0);
}

void setup_isr() {
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_NO_PULL);
    gpioSetRisingPulseSetup(FLOW_SENSOR_PIN, 100000);
    gpioSetRisingPulseTrigger(FLOW_SENSOR_PIN, 0);

    if (gpioSetIRQHandler(FLOW_SENSOR_PIN, true, &count_pulse) < 0) {
        fprintf(stderr, "ISR registration failed\n");
        gpioTerminate();
        exit(1);
    }

    gpioSetIRQEnabled(FLOW_SENSOR_PIN, true);
}

void count_pulse(int pin, uint pulse_time_us, uint edge, void *ctx) {
    static unsigned long last_time = 0;
    unsigned long current_time = millis();

    if (current_time - last_time >= 100) {
        last_time = current_time;
        float pulse_count = (float)(gpioGetLevel(FLOW_SENSOR_PIN) ? 1 : 0);
        float flow_rate = (pulse_count - last_pulse_count) * PULSES_PER_LITER;
        last_pulse_count = pulse_count;

        error = target_flow_rate - flow_rate;
        output = Kp * error;
        output = clamp(output, 0, 255);

        gpioSetPWMduty(PWM_PIN, (int)output);

        log_data(current_time, flow_rate, output);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <target_flow_rate_L/min>\n", argv[0]);
        return 1;
    }

    target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate\n");
        return 1;
    }

    log_file = fopen("flow_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");

    setup_gpio();
    setup_isr();

    while (1) {
        gpioWaitEvent(FLOW_SENSOR_PIN, HIGH, true);
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

int clamp(int val, int min, int max) {
    if (val < min)
        return min;
    else if (val > max)
        return max;
    return val;
}

void log_data(unsigned long timestamp_ms, float flow_rate, int valve_position) {
    fprintf(log_file, "%lu,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
}

