#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigio.h>

#define RFID_SPI_CHANNEL 0
#define RFID_SPI_SPEED 100000
#define RFID_TAG {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}
#define RFID_TAG_LEN 10
#define BUTTON_GPIO 22
#define LOCK_GPIO_1 17
#define LOCK_GPIO_2 27
#define DEBOUNCE_TIME_MS 50
#define AUTH_TIMEOUT_MS 5000

FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    spiClose(RFID_SPI_CHANNEL);
    gpioTerminate();
    exit(0);
}

void init_logging() {
    log_file = fopen("/var/log/door_access.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    struct tm tm;
    time_t now = time(NULL);
    localtime_r(&now, &tm);
    fprintf(log_file, "[%04d-%02d-%02dT%02d:%02d:%02d.000Z] - System started\n",
            1900 + tm.tm_year, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
}

void log_access_attempt(const char *message) {
    struct tm tm;
    time_t now = time(NULL);
    localtime_r(&now, &tm);
    fprintf(log_file, "[%04d-%02d-%02dT%02d:%02d:%02d.000Z] - %s\n",
            1900 + tm.tm_year, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return EXIT_FAILURE;
    }

    if (spiOpen(RFID_SPI_CHANNEL, RFID_SPI_SPEED) < 0) {
        perror("spiOpen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        spiClose(RFID_SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetMode(LOCK_GPIO_1, PI_OUTPUT);
    gpioSetMode(LOCK_GPIO_2, PI_OUTPUT);

    init_logging();

    while (1) {
        int button_state = gpioRead(BUTTON_GPIO);
        if (button_state == 0) {
            if (gpioRead(LOCK_GPIO_1) == 1 && gpioRead(LOCK_GPIO_2) == 1) {
                char tag_buffer[RFID_TAG_LEN + 1];
                int bytes_read = spiXfer(RFID_SPI_CHANNEL, tag_buffer, RFID_TAG_LEN);
                if (bytes_read != RFID_TAG_LEN || memmem(tag_buffer, bytes_read, RFID_TAG, sizeof(RFID_TAG))) {
                    log_access_attempt("Invalid RFID tag or read failure");
                    gpioWrite(LOCK_GPIO_1, 1);
                    gpioWrite(LOCK_GPIO_2, 1);
                    continue;
                }

                if (bytes_read == 0) {
                    log_access_attempt("No RFID tag present");
                    gpioWrite(LOCK_GPIO_1, 1);
                    gpioWrite(LOCK_GPIO_2, 1);
                    continue;
                }

                gpioWrite(LOCK_GPIO_1, 0);
                gpioWrite(LOCK_GPIO_2, 0);
                gpioDelay(AUTH_TIMEOUT_MS * 1000);
                gpioWrite(LOCK_GPIO_1, 1);
                gpioWrite(LOCK_GPIO_2, 1);
                log_access_attempt("Successful authentication");
            } else {
                log_access_attempt("Button pressed without valid RFID tag");
            }
        }
        gpioDelay(DEBOUNCE_TIME_MS);
    }

    spiClose(RFID_SPI_CHANNEL);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

