#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define GPIO_PIN 17
#define POLL_INTERVAL_MS 50

static int i2c_handle;
static int gpio_init = 0;

void sigint_handler(int signum) {
    gpioInterruptCancel(GPIO_PIN);
    pigpio_stop();
    printf("Exiting...\n");
    exit(0);
}

void setup_mpr121() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetOutputLevel(GPIO_PIN, 0);

    if (i2c_handle = i2cOpen(I2C_BUS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(1);
    }

    if (i2cWrite(i2c_handle, I2C_ADDR, (void *)"\x06\x00\x00\x00\x00\x00\x00\x00", 8) < 0) {
        fprintf(stderr, "Failed to perform soft reset on MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(1);
    }

    if (i2cWrite(i2c_handle, I2C_ADDR, (void *)"\x01\x00\x00\x00", 4) < 0) {
        fprintf(stderr, "Failed to set touch threshold\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(1);
    }

    if (i2cWrite(i2c_handle, I2C_ADDR, (void *)"\x02\x00\x00\x00", 4) < 0) {
        fprintf(stderr, "Failed to set release threshold\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(1);
    }

    if (i2cWrite(i2c_handle, I2C_ADDR, (void *)"\x03\x00\x00\x00", 4) < 0) {
        fprintf(stderr, "Failed to set filter\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(1);
    }

    if (i2cWrite(i2c_handle, I2C_ADDR, (void *)"\x04\x80\x00\x00", 4) < 0) {
        fprintf(stderr, "Failed to enable run mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(1);
    }
}

void log_relay_state(int state) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen("relay_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s: Relay state changed to %s\n", timestamp, state ? "ON" : "OFF");
        fclose(log_file);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    setup_mpr121();

    while (1) {
        uint8_t status_reg_0 = i2cRead(i2c_handle, I2C_ADDR, 1, 0x00);
        uint8_t status_reg_1 = i2cRead(i2c_handle, I2C_ADDR, 1, 0x01);

        int touched = (status_reg_0 & 0xF0) || (status_reg_1 & 0xF0);
