#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define I2C_BUS 1
#define MPR_ADDR 0x5A
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_CHARGE_TIME 0x20
#define ELE_CURRENT 0x01
#define STABILIZATION_DELAY 100000 // 100 ms

int main() {
    int fd;
    gpioInit();

    if ((fd = gpioOpen(0, 0)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioClose(fd, 0);
        return 1;
    }

    gpioSetOutput(RELAY_PIN, 0); // Initially off

    if (i2cOpen(I2C_BUS, &fd) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioClose(fd, 0);
        return 1;
    }

    if (i2cWriteReg8(fd, MPR_ADDR, 0x06, 0x00) < 0) {
        fprintf(stderr, "Failed to write to MPR121 register 0x06\n");
        i2cClose(fd);
        gpioClose(fd, 0);
        return 1;
    }

    if (i2cWriteReg8(fd, MPR_ADDR, 0x12, TOUCH_THRESHOLD) < 0) {
        fprintf(stderr, "Failed to write touch threshold to MPR121\n");
        i2cClose(fd);
        gpioClose(fd, 0);
        return 1;
    }

    if (i2cWriteReg8(fd, MPR_ADDR, 0x13, RELEASE_THRESHOLD) < 0) {
        fprintf(stderr, "Failed to write release threshold to MPR121\n");
        i2cClose(fd);
        gpioClose(fd, 0);
        return 1;
    }

    if (i2cWriteReg8(fd, MPR_ADDR, 0x1A, FILTER_CHARGE_TIME) < 0) {
        fprintf(stderr, "Failed to write filter/charge time to MPR121\n");
        i2cClose(fd);
        gpioClose(fd, 0);
        return 1;
    }

    if (i2cWriteReg8(fd, MPR_ADDR, 0x1B, ELE_CURRENT) < 0) {
        fprintf(stderr, "Failed to write electrode current to MPR121\n");
        i2cClose(fd);
        gpioClose(fd, 0);
        return 1;
    }

    if (i2cWriteReg8(fd, MPR_ADDR, 0x2C, 0x20) < 0) {
        fprintf(stderr, "Failed to enable electrodes on MPR121\n");
        i2cClose(fd);
        gpioClose(fd, 0);
        return 1;
    }

    usleep(STABILIZATION_DELAY);

    uint8_t touch_status;
    while (1) {
        if (i2cReadReg8(fd, MPR_ADDR, 0x00) | i2cReadReg8(fd, MPR_ADDR, 0x01)) {
            gpioOutput(RELAY_PIN, !gpioGetOutput(RELAY_PIN));
            printf("Relay toggled due to touch event\n");
        }
        sleep(0.1);
    }

    i2cClose(fd);
    gpioClose(fd, 0);
    return 0;
}

