#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIR 17
#define GPIO_RELAY 18
#define RATE_LIMIT_DURATION 2000 // 2 seconds
#define UNLOCK_DURATION 500 // 500 ms

FILE *log_file = NULL;

void log_event(const char *event) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file);
    }
}

void rate_limit_handler(int signal) {
    if (signal == SIGINT) {
        gpioTerminate();
        if (log_file != NULL) {
            fclose(log_file);
            log_file = NULL;
        }
        exit(0);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = rate_limit_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library. Exiting.\n");
        return 1;
    }

    log_file = fopen("door_events.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIR, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIR, PI_PUD_DOWN);
    gpioSetAlertMode(GPIO_PIR, PI_RISING_EDGE);
    gpioSetOutputLevel(GPIO_RELAY, 0); // Relay off

    int last_event_time = 0;
    while (1) {
        if (gpioRead(GPIO_PIR) == 1) {
            time_t current_time = time(NULL);
            if (current_time - last_event_time > RATE_LIMIT_DURATION) {
                log_event("Motion detected");
                gpioWrite(GPIO_RELAY, 1); // Relay on
                sleep(UNLOCK_DURATION / 1000);
                gpioWrite(GPIO_RELAY, 0); // Relay off
                last_event_time = time(NULL);
                log_event("Door unlocked");
            } else {
                log_event("Rate-limited: Motion detected (ignored)");
            }
        }
        gpioPoll(50); // Non-blocking polling at 50 ms interval
    }

    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    return 0;
}

