#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t shutdown_flag = 0;

struct motor_pattern {
    int steps;
    int duty_cycles[2][256];
    int durations[256];
};

void sigint_handler(int signum) {
    shutdown_flag = 1;
}

int main() {
    const int gpio_motor1 = 17;
    const int gpio_motor2 = 27;
    struct motor_pattern pattern;
    int i, j;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    // Set GPIO pins as PWM output
    if (gpioSetMode(gpio_motor1, PI_OUTPUT) < 0 || gpioSetMode(gpio_motor2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, sigint_handler);

    // Seed the random number generator
    srand(time(NULL));

    gpioPWM(gpio_motor1, 0);
    gpioPWM(gpio_motor2, 0);

    while (!shutdown_flag) {
        pattern.steps = rand() % 11 + 5; // 5 to 15 steps

        for (i = 0; i < pattern.steps; ++i) {
            pattern.durations[i] = rand() % 151 + 50; // 50 to 200 ms

            for (j = 0; j < 2; ++j) {
                pattern.duty_cycles[j][i] = rand() % 256; // PWM duty cycle 0-255
            }
        }

        // Play the pattern
        for (i = 0; i < pattern.steps; ++i) {
            gpioSetPWMfrequency(gpio_motor1, 1500);
            gpioSetPWMfrequency(gpio_motor2, 1500);

            gpioPWM(gpio_motor1, pattern.duty_cycles[0][i]);
            gpioPWM(gpio_motor2, pattern.duty_cycles[1][i]);

            gpioDelay(pattern.durations[i]);
        }
    }

    // Graceful shutdown
    gpioTerminate();

    return 0;
}

