    gpioPWM(gpio_motor2, 0);

    while (!shutdown_flag) {
        pattern.steps = rand() % 11 + 5; // 5 to 15 steps

        for (i = 0; i < pattern.steps; ++i) {
            pattern.durations[i] = rand() % 151 + 50; // 50 to 200 ms

            for (j = 0; j < 2; ++j) {
                pattern.duty_cycles[j][i] = rand() % 256; // PWM duty cycle 0-255
            }
        }

        // Play the pattern
        for (i = 0; i < pattern.steps; ++i) {
            gpioSetPWMfrequency(gpio_motor1, 1500);
            gpioSetPWMfrequency(gpio_motor2, 1500);

            gpioPWM(gpio_motor1, pattern.duty_cycles[0][i]);
            gpioPWM(gpio_motor2, pattern.duty_cycles[1][i]);

            gpioDelay(pattern.durations[i]);
        }
    }

    // Graceful shutdown
    gpioTerminate();

    return 0;
}
