        gpioWrite(CLK_PIN, 0);
        read_result = gpioRead(DATA_PIN, timeout);
        gpioWrite(CLK_PIN, 1);

        if (read_result < 0) {
            printf("Timeout reading from HX711\n");
            continue;
        }

        total += read_result;
        count++;

        if (count >= AVERAGE_COUNT) {
            float avg_value = total / count;
            offset = (avg_value - (scale_factor * 32768)) / scale_factor;
            save_calibration_data(CALIBRATION_FILE, offset);
            total = 0;
            count = 0;
        }

        float weight = avg_value * scale_factor + offset;

        if (weight > CALIBRATION_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }

        fprintf(stderr, "%f kg\n", weight);

        usleep(READ_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return 0;
