#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigio.h>

#define RAIN_SENSOR_GPIO 4
#define IN1_GPIO 17
#define IN2_GPIO 18
#define PWM_ENABLE_GPIO 27
#define DEBOUNCE_COUNT 3
#define DEBOUNCE_INTERVAL_MS 50
#define MOTOR_RUN_TIME_S 5
#define LOG_INTERVAL_S 60
#define PWM_FREQ 1000
#define PWM_DC 150

int gpio_initialized = 0;
int rain_detected = 0;
int debounce_count = 0;
unsigned long last_log_time = 0;

void log_message(const char *format, ...) {
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time.tv_sec));

    syslog(LOG_INFO, "%s: ", timestamp);
    va_list args;
    va_start(args, format);
    vsyslog(LOG_INFO, format, args);
    va_end(args);
}

void init_gpio() {
    if (pigpio_initialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    gpio_initialized = 1;
    pigpio_set_mode(RAIN_SENSOR_GPIO, PI_OUTPUT);
    pigpio_set_mode(IN1_GPIO, PI_OUTPUT);
    pigpio_set_mode(IN2_GPIO, PI_OUTPUT);
    pigpio_set_mode(PWM_ENABLE_GPIO, PI_OUTPUT);
}

void cleanup_gpio() {
    if (gpio_initialized) {
        pigpio_terminate();
        gpio_initialized = 0;
    }
}

void close_window() {
    if (pigpio_write(IN1_GPIO, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high");
    }
    if (pigpio_write(IN2_GPIO, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
    }
    if (pigpio_set_PWM_frequency(PWM_ENABLE_GPIO, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
    }
    if (pigpio_set_PWM_range(PWM_ENABLE_GPIO, 255) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
    }
    if (pigpio_set_PWM_duty(PWM_ENABLE_GPIO, PWM_DC) < 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle");
    }

    struct timespec run_time;
    clock_gettime(CLOCK_REALTIME, &run_time);
    run_time.tv_sec += MOTOR_RUN_TIME_S;

    while (debounce_count >= DEBOUNCE_COUNT && clock_should_yield() == 0) {
        pigpio_delay(DEBOUNCE_INTERVAL_MS);
    }

    if (clock_should_yield()) {
        syslog(LOG_WARNING, "Yielding to avoid busy loop");
        clock_gettime(CLOCK_REALTIME, &run_time);
        run_time.tv_sec = MOTOR_RUN_TIME_S;
    }

    pigpio_wait_for_edge(PWM_ENABLE_GPIO, PI_RISING, 0);
    pigpio_stop_pwm(PWM_ENABLE_GPIO);
    pigpio_write(IN1_GPIO, 0);
    pigpio_write(IN2_GPIO, 0);
}

void check_rain_and_log() {
    if (pigpio_read(RAIN_SENSOR_GPIO) == 0) {
        rain_detected = 1;
        debounce_count = 0;
    } else {
        rain_detected = 0;
    }

    if (rain_detected) {
        debounce_count++;
    } else {
        debounce_count = 0;
    }

    if (debounce_count >= DEBOUNCE_COUNT) {
        log_message("Rain detected, closing window\n");
        close_window();
        debounce_count = 0;

        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);

        if (current_time.tv_sec - last_log_time >= LOG_INTERVAL_S) {
            last_log_time = current_time.tv_sec;
            log_message("Window control log:\n");
            // Add code here to read and log the window control events from /var/log/window_control.log
        }
    }
}

void sigint_handler(int signum) {
    cleanup_gpio();
    log_message("Exiting on signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_gpio();
    syslog_open("/var/log/window_control.log");

    while (1) {
        check_rain_and_log();
        clock_should_yield();
    }

    cleanup_gpio();
    syslog_close();
    return 0;
}

