#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigio.h>

#define DT_PIN 23
#define SCK_PIN 24
#define GPIO17 17
#define WEIGHT_THRESHOLD 100
#define LOG_FILE "stock_events.txt"

static volatile sig_atomic_t sigint_received = 0;

void signal_handler(int signum) {
    sigint_received = signum;
}

int main() {
    pigpio *gpio;
    int fd;
    char timestamp[20];
    int weight;
    int timeout_count = 0;
    int data_stuck_high = 0;

    gpio = pigpio(0, 0);
    if (gpio == (pigpio*)PIGIO_ERROR) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(DT_PIN, PIGPIO_INPUT) < 0 || gpioSetMode(SCK_PIN, PIGIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        goto pigpio_cleanup;
    }

    if (gpioSetMode(GPIO17, PIGIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        goto pigpio_cleanup;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = fopen(LOG_FILE, "a");
    if (!fd) {
        fprintf(stderr, "Failed to open log file\n");
        goto pigpio_cleanup;
    }

    while (1) {
        time(&time_t);
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&time_t));

        if (gpioRead(DT_PIN) == 0) {
            if (gpioHX711Read(SCK_PIN, DT_PIN, &weight, 10000) < 0) {
                fprintf(stderr, "HX711 read failed\n");
                timeout_count++;
                if (timeout_count > 5) {
                    fprintf(stderr, "HX711 timeout, resetting...\n");
                    gpioSetWarningOnTimeout(false);
                    timeout_count = 0;
                }
                    continue;
            }

            if (data_stuck_high) {
                fprintf(stderr, "Data stuck high, resetting...\n");
                gpioSetWarningOnDataStuckHigh(false);
                data_stuck_high = 0;
            }

            if (weight < WEIGHT_THRESHOLD) {
                gpioWrite(GPIO17, 1);
                fprintf(fd, "%s - Solenoid lock activated\n", timestamp);
                gpioDelay(5000000); // 5 seconds
                gpioWrite(GPIO17, 0);
                fprintf(fd, "%s - Solenoid lock deactivated\n", timestamp);
            } else {
                gpioWrite(GPIO17, 0);
            }
        } else {
            data_stuck_high = 1;
        }

        gpioDelay(1000000); // 1 second delay
    }

pigpio_cleanup:
    if (gpioStop()) {
        fprintf(stderr, "pigpio cleanup failed\n");
    }

    fclose(fd);

    if (sigint_received) {
        printf("Exiting on SIGINT or SIGTERM\n");
    }

    return 0;
}

