#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG "security.log"
#define KNOWN_WEIGHT 5.0
#define TIMEOUT_MS 100

float calibration_factor;
FILE *calibration_file = NULL;
FILE *security_log = NULL;

void sigint_handler(int signum) {
    gpioTerminate();
    if (calibration_file) fclose(calibration_file);
    if (security_log) fclose(security_log);
    exit(0);
}

void calibrate() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(1);
    }

    gpioSetMode(HX711_DATA_PIN, PI_OUTPUT);
    gpioSetMode(HX711_CLK_PIN, PI_OUTPUT);

    if (fopen(CALIBRATION_FILE, "r") != NULL) {
        fclose(calibration_file);
        fprintf(stderr, "Calibration file already exists. Please remove it and try again.\n");
        exit(1);
    }

    if (fopen(CALIBRATION_FILE, "w") == NULL) {
        fprintf(stderr, "Failed to open calibration file for writing.\n");
        gpioTerminate();
        exit(1);
    }

    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (!calibration_file) {
        fprintf(stderr, "Failed to open calibration file for writing.\n");
        gpioTerminate();
        exit(1);
    }

    int raw_value;
    printf("Place a %g kg weight on the load cell and press Enter...\n", KNOWN_WEIGHT);
    fflush(stdout);
    getchar();

    if (read_hx711(&raw_value) < 0) {
        fprintf(stderr, "Failed to read raw value from HX711.\n");
        fclose(calibration_file);
        gpioTerminate();
        exit(1);
    }

    calibration_factor = (float)raw_value / KNOWN_WEIGHT;
    fprintf(calibration_file, "%g\n", calibration_factor);
    fclose(calibration_file);

    gpioTerminate();
