#include <signal.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO 20
#define LOG_FILE "relay_events.log"

static int relay_state = 0;
static GPIO *chip;
static GpioLine *sensor_line;
static GpioLine *relay_line;

void toggle_relay() {
    relay_state = !relay_state;
    gpiod_line_set_value(relay_line, relay_state);
    printf("Relay state toggled to %d\n", relay_state);
}

void log_event(const char *format, ...) {
    va_list args;
    va_start(args, format);
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    char log_msg[256];
    vsnprintf(log_msg, sizeof(log_msg), format, args);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", timestamp, log_msg);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
    va_end(args);
}

void sigint_handler(int signum) {
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("GPIO", "export");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, "GPIO16");
    if (sensor_line == NULL) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_inputs(sensor_line, 1) < 0) {
        perror("Failed to request sensor line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, "GPIO20");
    if (relay_line == NULL) {
        perror("Failed to get relay line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_outputs(relay_line, 1) < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_set_value(relay_line, 0); // Relay OFF initially

    while (1) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value == 0) { // Obstacle detected
            toggle_relay();
            log_event("Obstacle detected, relay state: %d", relay_state);
        }

        sleep(1);
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

