#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpio.h>
#include <gpio_chip.h>

#define GPIO_NUMBER 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600

volatile sig_atomic_t sig_flag = 0;

void sigint_handler(int signum) {
    sig_flag = 1;
}

void sigterm_handler(int signum) {
    sig_flag = 1;
}

int main() {
    struct gpio_chip *chip;
    struct gpio_line *line;
    int duration;
    char line_buffer[256];

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize libgpiod
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Find the chip and line
    chip = gpio_chip_open(0, "GPIO");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpio_exit();
        return 1;
    }

    line = gpio_chip_get_line(chip, GPIO_NUMBER);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_NUMBER);
        gpio_close(chip);
        gpio_exit();
        return 1;
    }

    // Configure the line as output with active-low set to 0
    if (gpio_line_set_direction(line, GPIO_LINE_OUTPUT) < 0 ||
        gpio_line_set_active_low(line, 0) < 0) {
        fprintf(stderr, "Failed to configure GPIO line %d\n", GPIO_NUMBER);
        gpio_close(chip);
        gpio_exit();
        return 1;
    }

    // Read duration from configuration file
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open configuration file %s\n", CONFIG_FILE);
        gpio_close(chip);
        gpio_exit();
        return 1;
    }

    if (fgets(line_buffer, sizeof(line_buffer), fp) &&
        strstr(line_buffer, "duration=") &&
        sscanf(line_buffer, "duration=%d", &duration) == 1 &&
        duration > 0 && duration <= MAX_DURATION) {

        printf("Watering duration: %d seconds\n", duration);

        // Activate the valve
        gpio_line_set_value(line, 1);
        printf("Valve ON\n");

        // Wait for the configured duration
        for (int i = 0; i < duration; i++) {
            if (sig_flag) {
                printf("Early exit requested, turning valve OFF\n");
                gpio_line_set_value(line, 0);
                break;
            }
            sleep(1);
        }

        // Turn the valve OFF
        gpio_line_set_value(line, 0);
        printf("Valve OFF\n");

    } else {
        fprintf(stderr, "Invalid or missing duration in configuration file\n");
        fclose(fp);
        gpio_close(chip);
        gpio_exit();
        return 1;
    }

    fclose(fp);

    // Release resources and close chip
    gpio_close(chip);
    gpio_exit();

    return sig_flag ? 0 : 1;
}

