        set_motor_speed(left_speed, right_speed);
        log_control_cycle(sensor_states[0], sensor_states[2], sensor_states[0], sensor_states[1], sensor_states[2]);

        gpioPulsePair(MOTOR_GPIO[0], 1500, 1500);
        gpioPulsePair(MOTOR_GPIO[1], 1500, 1500);
