#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define RELAY_PIN 23
#define I2C_ADDR 0x23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180

static const char *log_file = "grow_log.txt";
static int i2c_fd = -1;
static int relay_state = 0;

void log_message(const char *message) {
    char timestamp[32];
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    FILE *log_fp = fopen(log_file, "a");
    if (log_fp) {
        fprintf(log_fp, "%s: %s\n", timestamp, message);
        fclose(log_fp);
    }
}

int main() {
    pigpio *gpio;
    int ret;

    gpio = pigpio_init();
    if (!gpio) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_fd = i2c_open(1, 0x23);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x23\n");
        pigpio_terminate(gpio, 0);
        return 1;
    }

    if (i2c_write_then_read(i2c_fd, 0x10, NULL, 0, (uint8_t *) &ret, 1) < 1) {
        fprintf(stderr, "Failed to configure BH1750 for high-resolution mode\n");
        i2c_close(i2c_fd);
        pigpio_terminate(gpio, 0);
        return 1;
    }

    while (1) {
        uint16_t lux_value = 0;
        if (i2c_read(i2c_fd, 0x00, (uint8_t *) &lux_value, 2) != 2) {
            fprintf(stderr, "Failed to read lux value from BH1750\n");
            log_message("I2C read error");
            continue;
        }

        if (lux_value < LUX_THRESHOLD) {
            if (!relay_state) {
                gpio_write(RELAY_PIN, 1);
                relay_state = 1;
                log_message("Relay activated");
            }
        } else {
            if (relay_state) {
                gpio_write(RELAY_PIN, 0);
                relay_state = 0;
                log_message("Relay deactivated");
            }
        }

        log_message(sprintf(
            "Lux: %d, Relay: %s",
            lux_value,
            relay_state ? "ON" : "OFF"
        ));

        usleep(MEASUREMENT_DELAY_MS * 1000);
    }

    gpio_terminate(gpio, 0);
    i2c_close(i2c_fd);
    fclose(log_fp);

    return 0;
}

