#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define LOCK_BUTTON_GPIO 21
#define UNLOCK_BUTTON_GPIO 22
#define SERVO_GPIO 18

static volatile sig_atomic_t ctrlc_caught = 0;

static void sigint_handler(int signum)
{
    ctrlc_caught = 1;
}

static int init_pigpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }
    return 0;
}

static void cleanup_pigpio(void)
{
    gpioTerminate();
}

static void servo_control(int locked)
{
    static int pulse_width = 1000;

    if (locked) {
        pulse_width = 1000; // Locked position (0 degrees)
    } else {
        pulse_width = 2000; // Unlocked position (180 degrees)
    }

    pulse_width = constrain(pulse_width, 500, 2500);
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetServoPulseWidth(SERVO_GPIO, pulse_width);
}

static void button_callback(int button_gpio, int level, void (*edge_callback)(int))
{
    static unsigned long last_press_time = 0;
    unsigned long current_time = gpioGetTimestamp();

    if (level == 0 && (current_time - last_press_time) > 100000000L) { // 100 ms delay
        edge_callback(button_gpio);
        last_press_time = current_time;
    }
}

static void lock_button_pressed(int button_gpio)
{
    servo_control(1); // Lock the servo
}

static void unlock_button_pressed(int button_gpio)
{
    servo_control(0); // Unlock the servo
}

int main(void)
{
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (init_pigpio()) {
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    gpioSetMode(LOCK_BUTTON_GPIO, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_GPIO, 1);
    gpioSetPullUpDown(UNLOCK_BUTTON_GPIO, 1);

    gpioCallback(LOCK_BUTTON_GPIO, PI_FALLING_EDGE, button_callback);
    gpioCallback(UNLOCK_BUTTON_GPIO, PI_FALLING_EDGE, button_callback);

    servo_control(0); // Initially unlock the servo

    while (!ctrlc_caught) {
        // Main loop can be expanded with other tasks
    }

    cleanup_pigpio();
    return EXIT_SUCCESS;
}

