#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <gpiod.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define PULSE_DURATION_MS_1 200
#define PULSE_DURATION_MS_2 300

struct motor_data {
    int gpio;
    int duration_ms;
};

void stop_motors(struct motor_data *motors, int num_motors) {
    for (int i = 0; i < num_motors; i++) {
        gpiod_line_set_value(motors[i].gpio, 0);
    }
}

int main() {
    struct gpiod_chipchip *chip;
    struct gpiod_line *lines[2];
    struct motor_data motors[] = {
        {MOTOR1_GPIO, PULSE_DURATION_MS_1},
        {MOTOR2_GPIO, PULSE_DURATION_MS_2}
    };
    int num_motors = sizeof(motors) / sizeof(motors[0]);

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        return 1;
    }

    for (int i = 0; i < num_motors; i++) {
        lines[i] = gpiod_chip_get_line(chip, motors[i].gpio);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for motor %d\n", i + 1);
            return 1;
        }

        if (gpiod_line_request_output(lines[i], "motor") < 0) {
            fprintf(stderr, "Failed to request output for motor %d\n", i + 1);
            return 1;
        }
    }

    struct sigaction sa;
    sa.sa_handler = stop_motors;
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handlers\n");
        return 1;
    }

    while (1) {
        for (int i = 0; i < num_motors; i++) {
            gpiod_line_set_value(lines[i], 1);
            sleep_ms(motors[i].duration_ms);
            gpiod_line_set_value(lines[i], 0);
            sleep_ms(motors[i].duration_ms);
        }
    }

    for (int i = 0; i < num_motors; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

