            zmq_msg_init(&msg);
            zmq_msg_copy(&msg, "SOUND_ALERT", 13);
            zmq_send(socket, &msg, ZMQ_SNDMORE);
            zmq_msg_close(&msg);
        }

        usleep(10 * 1000);
    }
