void alarm_node_mode() {
    while (1) {
        zmq_msg_t msg;
        zmq_msg_init(&msg);
        zmq_recv(socket, &msg, ZMQ_SNDMORE);

        if (zmq_msg_more_parts(msg)) {
            zmq_msg_more_parts(&msg, 0);
            const char *topic = (const char *)zmq_msg_data(&msg);
            if (strcmp(topic, "SOUND_ALERTS") == 0) {
                gpiod_trigger(led_line, GPIO_HIGH);
                usleep(1 * 1000000);
                gpiod_trigger(led_line, GPIO_LOW);
            }
        }

        zmq_msg_close(&msg);
    }
}

int main(int argc, char *argv[]) {
    int mode;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        return EXIT_FAILURE;
    }

    mode = atoi(argv[1]);

    setup_gpio(mode);

    if (mode == 1) {
        sound_sensor_mode();
    } else {
        alarm_node_mode();
    }

    cleanup_gpio();

    return 0;
