#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <pigio.h>
#include <mqtt.h>

#define NEC_MARK 560
#define NEC_SPACE 1690
#define NEC_INVERTED_MARK 560
#define NEC_INVERTED_SPACE 1690
#define NEC_MARK_PULSE_WIDTH 9000
#define NEC_SPACE_PULSE_WIDTH 4500

static const int IR_PIN = 17;
static const int MQTT_PORT = 1883;

static pigio *pi;
static mqtt *mqtt_client;

static int nec_decode(uint32_t *address, uint32_t *command) {
    uint32_t pulse_width_sum = 0;
    int pulse_count = 0;
    uint32_t pulse_width = 0;

    while (gpioPulseLength(pi, IR_PIN) > 0) {
        pulse_width = gpioPulseLength(pi, IR_PIN);
        if (pulse_width >= NEC_MARK_PULSE_WIDTH) {
            pulse_width_sum += pulse_width - NEC_MARK_PULSE_WIDTH;
            pulse_count++;
        }
        if (pulse_count > 16)
            break;
    }

    *address = 0;
    *command = 0;

    if (pulse_count < 11 || pulse_count > 20)
        return -1;

    for (int i = 0; i < pulse_count; i++) {
        if (i < 6) {
            if (pulse_width < NEC_MARK)
                *address |= (1 << (5 - i));
            else
                *command |= (1 << (5 - i));
        } else if (i < 11) {
            if (pulse_width < NEC_SPACE)
                *command |= (1 << (i - 6));
            else
                *address |= (1 << (i - 6));
        }
    }

    if (pulse_count != 20 || (gpioRead(pi, IR_PIN) != 0 && gpioRead(pi, IR_PIN) != 1))
        return -1;

    return 0;
}

static int nec_validate(uint32_t address, uint32_t command) {
    return ((address ^ command) == 0);
}

static void nec_log(uint32_t address, uint32_t command) {
    syslog(LOG_INFO, "NEC: Address 0x%08x, Command 0x%08x", address, command);
}

static void nec_mqtt_publish(const char *topic, const char *payload) {
    mqtt_message_t msg;
    mqtt_zero(&msg);
    msg.payload = (uint8_t *)payload;
    msg.payloadlen = strlen(payload);
    mqtt_publish(mqtt_client, topic, &msg);
}

static void nec_callback(int fd, int events, void *user) {
    gpioAlertInit(pi, IR_PIN, GPIO_FALLING_EDGE, user);
}

int main(int argc, char **argv) {
    int ret;

    pi = pigio_init();
    if (!pi) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(pi, IR_PIN, GPIO_INPUT);

    mqtt_client = mqtt_client_init("ir_decoder");
    if (!mqtt_client) {
        syslog(LOG_ERR, "Failed to initialize MQTT client");
        pigio_terminate(pi);
        return 1;
    }

    mqtt_client_set_callback(mqtt_client, nec_mqtt_publish);

    ret = gpioSetAlert(pi, IR_PIN, nec_callback, NULL);
    if (ret) {
        syslog(LOG_ERR, "Failed to set GPIO alert");
        pigio_terminate(pi);
        return 1;
    }

    while (1) {
        uint32_t address, command;
        ret = nec_decode(&address, &command);
        if (ret == 0 && nec_validate(address, command)) {
            nec_log(address, command);
            nec_mqtt_publish("ir/decoded", sprintf(
                "%02x%02x", (unsigned char)address, (unsigned char)command));
        } else {
            syslog(LOG_WARNING, "Invalid NEC frame");
        }
    }

    pigio_terminate(pi);
    mqtt_client_destroy(mqtt_client);
    return 0;
}

