#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <string.h>
#include <signal.h>
#include <math.h>

#define BH1750_ADDR_HIGH 0x23
#define BH1750_ADDR_LOW  0x24
#define BH1750_ADDR_MID  0x25
#define BH1750_ADDR_LOW2 0x26
#define ONE_TIME_HIGH_RES 0x20
#define CONVERSION_TIME_MS 180

int i2c_fd;
int udp_sock;
volatile sig_atomic_t exit_flag = 0;

float read_lux(int fd, int addr) {
    int r;
    unsigned char data[2];

    if (addr == BH1750_ADDR_HIGH || addr == BH1750_ADDR_LOW ||
        addr == BH1750_ADDR_MID || addr == BH1750_ADDR_LOW2) {
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            fprintf(stderr, "Error setting I2C address\n");
            return NAN;
        }

        if (write(fd, &ONE_TIME_HIGH_RES, 1) != 1) {
            fprintf(stderr, "Error writing to sensor\n");
            return NAN;
        }

        usleep(CONVERSION_TIME_MS * 1000);

        if (ioctl(fd, I2C_RDWR, data) != 2) {
            fprintf(stderr, "Error reading from sensor\n");
            return NAN;
        }

        return ((data[0] << 8) | data[1]) / 1.2;
    }

    return NAN;
}

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_sock < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(5005);

    if (bind(udp_sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to bind UDP socket");
        close(i2c_fd);
        return 1;
    }

    while (!exit_flag) {
        float lux_values[4];
        for (int i = 0; i < 4; i++) {
            int addr = i == 0 ? BH1750_ADDR_HIGH :
                       i == 1 ? BH1750_ADDR_LOW  :
                       i == 2 ? BH1750_ADDR_MID : BH1750_ADDR_LOW2;
            lux_values[i] = read_lux(i2c_fd, addr);
        }

        char msg[256];
        snprintf(msg, sizeof(msg), "%d,%f;%d,%f;%d,%f;%d,%f",
                 BH1750_ADDR_HIGH >> 3, lux_values[0],
                 BH1750_ADDR_LOW  >> 3, lux_values[1],
                 BH1750_ADDR_MID >> 3, lux_values[2],
                 BH1750_ADDR_LOW2 >> 3, lux_values[3]);

        if (sendto(udp_sock, msg, strlen(msg), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            perror("Failed to send UDP packet");
        }

        usleep(1000000);
    }

    close(i2c_fd);
    close(udp_sock);
    return 0;
}

