#define SAMPLING_INTERVAL 1
#define MAX_RETRIES 3

int i2c_fd = -1;

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
        fflush(stdout);
        fflush(stderr);
        fflush(stdout);
        fprintf(stderr, "Clean shutdown.\n");
    }
}

int read_airflow_data(uint8_t *data, int retries) {
    if (i2c_fd == -1) {
        return -1;
    }

    if (retries > 0) {
        if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
            perror("Failed to acquire bus\n");
            return -1;
        }

        if (retries == 1 && read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from sensor\n");
            return -1;
        } else if (read(i2c_fd, data, 2) != 2) {
            if (retries < MAX_RETRIES) {
                usleep(100 * 1000);
                return read_airflow_data(data, retries + 1);
            } else {
                perror("Max retries reached\n");
                return -1;
            }
        }
    } else {
        perror("Failed to read from sensor\n");
        return -1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    float flow = (raw_value - 3277) * 0.1;

    return write(STDOUT_FILENO, &flow, sizeof(float));
}

int main() {
    struct termios term;
    signal(SIGINT, sigint_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus\n");
        return -1;
    }

    if (tcgetattr(STDIN_FILENO, &term) != 0) {
        perror("Failed to get termios attributes\n");
        return -1;
    }
    term.c_lflag &= ~ICANON;
    term.c_lflag &= ~ECHO;
    tcsetattr(STDIN_FILENO, TCSANOW, &term);

    FILE *log_file = fopen("airflow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file\n");
        return -1;
    }

    while (1) {
        uint8_t data[2];
        if (read_airflow_data(data, 0) < 0) {
            break;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld: %f SLPM\n", now, (float)data[0]);
        fflush(log_file);

        sleep(SAMPLING_INTERVAL);
    }

    fclose(log_file);
    close(i2c_fd);
    tcsetattr(STDIN_FILENO, TCSANOW, &term);

    return 0;
}

