    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%d,%d,%d,%d,%d,%d,%d,%d,%d\n", now, spectral_data[0], spectral_data[1], spectral_data[2], spectral_data[3], spectral_data[4], spectral_data[5], spectral_data[6], spectral_data[7], spectral_data[8]);
