    if (tx_len > 0) {
        if (write(i2c_fd, tx_buf, tx_len) != tx_len) {
            return -1;
        }
    }

    if (rx_len > 0) {
        if (read(i2c_fd, rx_buf, rx_len) != rx_len) {
            return -1;
        }
    }

