        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    unsigned char tx_buf[2] = {WHO_AM_I, 0x00};
    unsigned char rx_buf;

    if (i2c_transfer(tx_buf, 1, &rx_buf, 1) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (rx_buf != 0x19) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    unsigned char enable_tx_buf[1] = {ENABLE};

