    while (1) {
        if (i2c_transfer(NULL, 0, spectral_data, SPECTRAL_DATA_LEN) < 0) {
            break;
        }

        int lux_approx = spectral_data[F1] + spectral_data[F2] + spectral_data[F3] + spectral_data[F4] + spectral_data[F5] + spectral_data[F6] + spectral_data[F7] + spectral_data[F8];
        lux_approx /= 8;

        log_spectral_data(spectral_data);
        printf("F1:%d F2:%d F3:%d F4:%d F5:%d F6:%d F7:%d F8:%d Clear:%d NIR:%d Lux_approx:%d\n", spectral_data[F1], spectral_data[F2], spectral_data[F3], spectral_data[F4], spectral_data[F5], spectral_data[F6], spectral_data[F7], spectral_data[F8], spectral_data[CLEAR], spectral_data[NIR], lux_approx);

        sleep(5);
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

