#define SENSOR_REG_ACCEL_X_H 0x29
#define SENSOR_REG_ACCEL_Y_L 0x2A
#define SENSOR_REG_ACCEL_Y_H 0x2B
#define SENSOR_REG_ACCEL_Z_L 0x2C
#define SENSOR_REG_ACCEL_Z_H 0x2D

#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10000

int i2c_fd = -1;
char *i2c_addr_str = "0x37";
int interval = 1;
char *output_filename = "seismic_data.csv";

void log_error(const char *message) {
    fprintf(stderr, "%s: %s\n", time_str(), message);
    fflush(stderr);
}

int i2c_read(int fd, uint8_t reg, int16_t *value) {
    struct i2c_rdwr_ioctl_data rdwr;
    rdwr.u8 = reg;
    rdwr.u8len = 1;
    rdwr.u8buf = NULL;
    rdwr.u8buf_len = 0;
    rdwr.u8buf_offset = 0;

    if (ioctl(fd, I2C_RDWR, &rdwr) < 0) {
        log_error("I2C read failed");
        return -1;
    }

    if (lseek(fd, 0, SEEK_SET) < 0) {
        log_error("I2C seek failed");
        return -1;
    }

    if (read(fd, value, 2) != 2) {
        log_error("I2C read failed");
        return -1;
    }

    *value = (*value << 8) | *(value + 1);
    return 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    struct i2c_rdwr_ioctl_data rdwr;
    rdwr.u8 = reg;
    rdwr.u8len = 1;
    rdwr.u8buf = &value;
    rdwr.u8buf_len = 1;
    rdwr.u8buf_offset = 0;

    if (ioctl(fd, I2C_RDWR, &rdwr) < 0) {
        log_error("I2C write failed");
        return -1;
    }

    return 0;
}

int open_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open /dev/i2c-1");
        return -1;
    }

    if (ioperm(i2c_fd, 1, true) < 0) {
        log_error("Failed to acquire i2c-dev permissions");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

void close_i2c() {
    ioperm(i2c_fd, 1, false);
    close(i2c_fd);
    i2c_fd = -1;
}

int main(int argc, char *argv[]) {
    int ret;
    int retries = 0;
    int value1, value2;
    time_t now;

    // Parse command-line arguments
    // ...

    // Open I2C bus
    if ((ret = open_i2c()) < 0) {
        return ret;
    }

