    // ...

    while (1) {
        now = time(NULL);
        fprintf(fp, "%ld,%d,%d,%d\n", now, 0, 0, 0);
        fflush(fp);

        for (int i = 0; i < 6; i++) {
            int16_t raw_value;
            if ((ret = i2c_read(i2c_fd, SENSOR_REG_ACCEL_X_L + (i / 2) * 2, &raw_value)) < 0) {
                if (retries < MAX_RETRIES) {
                    retries++;
                    log_error("I2C read failed, retrying in %d ms", RETRY_DELAY_MS);
                    sleep(RETRY_DELAY_MS / 1000);
                    continue;
                } else {
                    log_error("I2C read failed after %d retries", MAX_RETRIES);
                    break;
                }
            }

            int16_t g_value = raw_value * 0.000244;
            fprintf(fp, "%ld,%d\n", now, g_value);
            fflush(fp);
        }

        sleep(interval);
    }

    // Close I2C bus and CSV file
    close_i2c();
    fclose(fp);

    return 0;
}

