#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEV "/dev/serial0"
#define BAUD 115200
#define INTER_BYTE_TIMEOUT 0.5
#define SELECT_TIMEOUT 2

struct termios term;
int uart_fd;
char line_buffer[256];
size_t buffer_index = 0;

void handle_sigint(int sig) {
    printf("\nReceived SIGINT, closing UART and exiting...\n");
    close(uart_fd);
    exit(0);
}

void handle_sigterm(int sig) {
    printf("\nReceived SIGTERM, closing UART and exiting...\n");
    close(uart_fd);
    exit(0);
}

void configure_uart(int fd) {
    if (tcgetattr(fd, &term) != 0) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    term.c_cflag = CLOCAL | CREAD | (CS8 << 3) | CBAUD(BAUD);
    term.c_iflag = IGNPAR;
    term.c_oflag = 0;
    term.c_lflag = 0;
    term.c_cc[VMIN] = 1;
    term.c_cc[VTIME] = INTER_BYTE_TIMEOUT * 1000; // Convert seconds to milliseconds

    if (tcsetattr(fd, TCSANOW, &term) != 0) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    uart_fd = open(UART_DEV, O_RDONLY | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    configure_uart(uart_fd);

    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(uart_fd, &readfds);

    while (1) {
        int maxfd = uart_fd;
        struct timeval tv;
        tv.tv_sec = SELECT_TIMEOUT;
        tv.tv_usec = 0;

        int ret = select(maxfd + 1, &readfds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("select");
            exit(EXIT_FAILURE);
        } else if (ret == 0) {
            printf("No data available, retrying...\n");
            continue;
        }

        if (FD_ISSET(uart_fd, &readfds)) {
            int bytes_read = read(uart_fd, &line_buffer[buffer_index], sizeof(line_buffer) - buffer_index);
            if (bytes_read == -1) {
                perror("read");
                exit(EXIT_FAILURE);
            } else if (bytes_read == 0) {
                printf("Connection closed by peer, exiting...\n");
                break;
            } else {
                buffer_index += bytes_read;

                if (line_buffer[buffer_index - 1] == '\n') {
                    char *timestamp_str = strtok(line_buffer, ",");
                    char *range_str = strtok(NULL, ",");

                    if (timestamp_str && range_str) {
                        time_t timestamp = strtol(timestamp_str, NULL, 10);
                        double range = strtod(range_str, NULL);

                        printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d, Range: %.2f meters\n",
                               1900 + (timestamp / (24 * 60 * 60)),
                               (timestamp / (60 * 60)) % 100,
                               (timestamp / 60) % 60,
                               timestamp % 60,
                               (timestamp / 1000) % 60,
                               (timestamp % 1000),
                               range);
                    } else {
                        printf("Invalid line format, retrying...\n");
                    }

                    buffer_index = 0; // Reset buffer for next line
                }
            }
        }
    }

    close(uart_fd);
    return 0;
}

