#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_LEFT 4
#define GPIO_MIDDLE 11
#define GPIO_RIGHT 13

static volatile sig_atomic_t sigint_received = 0;
static volatile sig_atomic_t sigterm_received = 0;

void sigint_handler(int signum) {
    sigint_received = 1;
}

void sigterm_handler(int signum) {
    sigterm_received = 1;
}

int main() {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10000000; // 100 ms

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LEFT, PI_INPUT) < 0 ||
        gpioSetMode(GPIO_MIDDLE, PI_INPUT) < 0 ||
        gpioSetMode(GPIO_RIGHT, PI_INPUT) < 0 ||
        gpioSetPullUpDown(GPIO_LEFT, 1) < 0 ||
        gpioSetPullUpDown(GPIO_MIDDLE, 1) < 0 ||
        gpioSetPullUpDown(GPIO_RIGHT, 1) < 0) {
        fprintf(stderr, "Error: Failed to configure GPIO pins.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (!sigint_received && !sigterm_received) {
        gpioReadFast(GPIO_LEFT);
        gpioReadFast(GPIO_MIDDLE);
        gpioReadFast(GPIO_RIGHT);

        char timestamp[20];
        time_t t = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(t));

        int left = gpioRead(GPIO_LEFT);
        int middle = gpioRead(GPIO_MIDDLE);
        int right = gpioRead(GPIO_RIGHT);

        if (left == 0 && middle == 0 && right == 0) {
            fprintf(stdout, "EMERGENCY STOP!\n");
        } else {
            fprintf(stdout, "%s Left: %d, Middle: %d, Right: %d\n",
                    timestamp, left, middle, right);
        }

        nanosleep(&ts, NULL);
    }

    gpioTerminate();

    // Close the serial port here if needed

    return 0;
}
